    [3494] = "Saqueador",
    [3495] = "Infurnus",
    [3496] = "Durgen Martillo de Endecha",
    [3498] = "Titanosaurio",
    [3499] = "Cazadores ravasaurios",
    [3500] = "Pezuña Trueno",
    [3501] = "Cimaveneno",
    [3502] = "Nanaya",
    [3503] = "Ceniza",
    [3504] = "Rey Op",
    [3505] = "Rayo",
    [3507] = "Matriarca cuernoatroz",
    [3511] = "Elemental primitivo",
    [3582] = "Atal'alarion",
    [3583] = "Avatar de Hakkar",
    [3584] = "Sombra de Eranikus",
    [3585] = "Hazzas",
    [3586] = "Morphaz",
    [3587] = "Sastrón",
    [3588] = "Segasueños",
    [3589] = "Jammal'an el Profeta",
    [3597] = "Garranieve",
    [3600] = "Vitrix",
    [3644] = "Horror de las Tierras Altas",
    [3676] = "Minero Johnson",
  },
  quests = {
    [2] = {ot = "Llévale la garfa de Garfafilada a Senani Corazón Atronador en el Puesto del Hachazo, Vallefresno.", st = "El poderoso hipogrifo Garfafilada ha sido asesinado, y la garra de la bestia difunta es la prueba de tu victoria. Sin duda, Senani Corazón Atronador, en Puesto del Hachazo, estará interesada en ver este trofeo de tu hazaña.", t = "La garfa de Garrafilada"},
    [5] = {ot = "Habla con el Chef Grual.", st = "¡Llevo semanas escondiéndome en esta ciudad fantasma y no he comido más que larvas y hierbajos! Necesito algo de comida decente. Estoy en disposición de pagar bien.$B$BSi me traes un festín, te pagaré generosamente.$B$BHe oído que el chef Grual del Mesón del Cuervo Escarlata de Villa Oscura hace unos estupendos pasteles de cangrejo oscuro...", t = "La hambruna de Alterio"},
    [6] = {ot = "Mata a Garrick Piesuaves y lleva su cabeza al ayudante de alguacil Willem a la Abadía de Villanorte.", st = "Garrick Piesuaves es un maleante que lleva semanas acosando a granjeros y mercaderes. Ha sido visto en una choza cerca de los viñedos, cruzando el puente al este de la abadía. Tráeme la cabeza de ese villano y podrás quedarte con su botín.$B$BPero ve con cuidado, $n. Garrick anda con una pandilla de matones. Puede que no te sea fácil llegar hasta él.", t = "La recompensa por Garrick Piesuaves"},
    [7] = {ot = "Mata 10 alimañas kóbold y regresa con el alguacil McBride.", st = "$n, lo primero que tienes que hacer es limpiar; un clan de kóbolds ha invadido los bosques del norte. Ve y liquida a todos los kóbolds que encuentres; si reducimos sus filas podremos echarlos de Villanorte.", t = "La limpieza del campamento kóbold"},
    [8] = {ot = "Lleva la carta anodina a Claros de Tirisfal y entrégasela a la tabernera Renee.", st = "¡Eh, colega! ¿Le harías un favor a un joven hombre que ha combatido contra más zombis y arañas de los que puede contar?$B$BTengo una carta que tiene que llegar a Rémol... Es para una tabernera llamada Renee no sé qué. No creo que importe cómo se apellida, la verdad.$B$BPero el sitio es muy acogedor y está lleno de víctimas de la Plaga que intentan abrirse paso en el mundo. Es el sitio ideal para descansar... si es que necesitas hacerlo. Anímate... si vas, te pagaré bien.", t = "Un trato de pícaro"},
    [9] = {ot = "El granjero Saldean quiere que mates a 20 vigías de la cosecha.", st = "¡Mira lo que le ha ocurrido a este lugar! Estas tierras estaban antes en manos de buenos granjeros. Pero los condenados ladrones los han ahuyentado a todos. ¡Pero no a mí! Eso sí, parece que algunos vigías de la cosecha han invadido los campos.$B$BSi estás $gpreparado:preparada; me gustaría que fueras y mataras a 20 de ellos. Vuelve cuando hayas terminado y te pagaré. Si terminas con los de mi campo, puedes limpiar también los campos vecinos.", t = "Campos de la muerte"},
    [11] = {ot = "Lleva 8 bandas gnoll pintadas al ayudante de alguacil Rainer al Cuartel.", st = "En las fronteras del Bosque de Elwynn se han avistado gnolls, unas criaturas salvajes que seguramente no están allí por trabajo. Un grupo enorme de ellos, uno más numeroso del que podemos contener solos, ha infestado los bosques que hay al sur de la torre de vigilancia. Otro grupo ha infestado las áreas cercanas al Lago del Hito, al este.$B$BEl ejército de Ventormenta elogiará a quienquiera que le ayude a matarlos. Tráeme sus bandas gnoll pintadas como prueba de tu hazaña.", t = "Recompensas por los gnolls Zarparrío"},
    [12] = {ot = "Gryan Mantorrecio quiere que mates a 15 tramperos Defias y a 15 contrabandistas Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela.", st = "La Milicia Popular solo tiene un objetivo: defender las tierras de los Páramos de Poniente y traer la paz a nuestro entorno. Por desgracia, el precio de la paz suele pagarse en sangre.$B$BSegún el informe de uno de mis exploradores, una banda de tramperos Defias ha sido vista cerca de la Mina de Jango al noroeste de aquí, en La Granja de Molsen y en la Plantación de Calabazas de Cejade. Si quieres unirte a nuestras filas, acaba con 15 tramperos Defias y con 15 contrabandistas Defias y vuelve a verme.", t = "La Milicia Popular"},
    [13] = {ot = "Gryan Mantorrecio quiere que mates a 15 saqueadores Defias y a 15 despojadores Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela.", st = "Una banda de despiadados saqueadores Defias ha sido vista saqueando la Mina de la Costa del Oro, el Arroyo de la Luna y la Hacienda de Alexston. La Milicia Popular no tolerarán ese comportamiento. Avisa inmediatamente, $n, y haz conocer la presencia de la Luz en los Páramos de Poniente.$b$bLa Mina de la Costa del Oro está cerca de la costa, al oeste de la torre. El siguiente paso de tu instrucción consistirá en acabar con 15 de esos saqueadores Defias y con 15 despojadores Defias.", t = "La Milicia Popular"},
    [14] = {ot = "Gryan Mantorrecio quiere que mates a 15 bandoleros Defias, a 5 acechacaminos Defias y a 5 nudillos Defias. Cuando lo hayas hecho vuelve a verle en la Colina del Centinela.", st = "Algunos Defias nos han esquivado. Según informa mi mejor explorador, los Defias han estado saqueando y expoliando el campo, hasta la parte sureste de los Páramos de Poniente. Creemos que se están ocultando en Las Colinas Afiladas, planeando sus siguientes pasos. Acaba con esos miserables en nombre de La Milicia Popular", t = "La Milicia Popular"},
    [15] = {ot = "Mata a 10 trabajadores kóbold y preséntate ante el alguacil McBride.", st = "$n, mis exploradores me dicen que la infestación kobold es peor de lo que habíamos pensado. Un grupo de trabajadores kóbold ha acampado cerca de la Mina del Eco, al norte.$B$BVe a la mina y expúlsalos. Sabemos que hay al menos 10 de ellos. Mátalos, comprueba si quedan más y ven a verme.", t = "Investiga la Mina del Eco"},
    [18] = {ot = "Lleva 12 pañuelos de arpillera roja al ayudante de alguacil Willem en las afueras de la Abadía de Villanorte.", st = "Hace poco llegó una banda de maleantes a Villanorte. Se hacen llamar la Hermandad Defias; se les ha visto cruzando el río hacia el este.$B$BNo sé qué están haciendo, ¡pero seguro que no es nada bueno! Tráeme sus pañuelos y te daré un arma como recompensa.", t = "Hermandad de ladrones"},
    [19] = {ot = "Lleva la cabeza de Tharil'zun al alguacil Marris a Crestagrana.", st = "Hay avanzados y renegados Roca Negra tendiendo emboscadas entre aquí y el Fuerte de Petravista. El jefe de los avanzados se llama Tharil'zun y lo queremos muerto. ¡Tráeme su cabeza!", t = "Tharil'zun"},
    [20] = {ot = "Lleva 10 hachas desgastadas por la batalla al alguacil Marris a Villa del Lago.", st = "Los orcos Roca Negra llegaron desde Las Estepas Ardientes y han invadido el Fuerte de Petravista, al norte de aquí. Andan merodeando por el norte de Villa del Lago y tienen a los ciudadanos encerrados como a ganado.$B$BLibra a Villa del Lago de esta amenaza. Mata a los orcos y tráeme 10 hachas desgastadas por la batalla como prueba.$B$BAunque nos amenazan desde el norte, sabemos que hay más al sureste de Crestagrana. Si los encuentras, mátalos también.", t = "La amenaza de los Roca Negra"},
    [21] = {ot = "Mata 12 obreros kóbolds y luego regresa con el alguacil McBride en la Abadía de Villanorte.", st = "Ha quedado demostrado que tenemos que purgar la Mina del Eco. Vuelve allí y ayuda a eliminar a los kóbolds.$B$BDate prisa, $n. Cuanto más tiempo dejemos a los kóbolds en la mina, más nos costará expulsarlos de Villanorte.", t = "Refriega en el Eco"},
    [22] = {ot = "Salma Saldean necesita 8 hígados de dentosangre para hacer un pastel de hígado de dentosangre.", st = "Las cebollas están peladas. El ajo machacado. La corteza está tostada. Las hierbas de eneldo picadas. ¡Lo único que me falta para mi famosa empanada de carne son 8 hígados de dentosangre!", t = "Pastel de hígado de dentosangre"},
    [23] = {ot = "Llévale la pata de Ursangous a Senani Corazón Atronador en el Puesto del Hachazo, Vallefresno.", st = "<La garra del gran oso Ursangous es tu trofeo en esta parte de la Caza de Vallefresno. En ella se distingue un pequeño emblema en forma de cuarto creciente, cuyo significado todavía no ha sido revelado.$B$BDebes llevar la garra a Senani Corazón Atronador en el Puesto del Hachazo para demostrar que has vencido a la bestia y completado esta etapa de la caza.>", t = "La pata de Ursangous"},
    [24] = {ot = "Lleva la cabeza de Shadumbra a Senani Corazón Atronador en el Puesto del Hachazo, Vallefresno.", st = "El otrora ágil Shadumbra ahora yace inmóvil mientras proclamas tu victoria. La cabeza del sable de la noche muerto es un trofeo adecuado para esta batalla de la Caza de Vallefresno. Senani Corazón Atronador en el Puesto del Hachazo seguramente deseará ver este trofeo para otorgarte el crédito correspondiente a esta etapa de la Caza de Vallefresno.", t = "La cabeza de Shadumbra"},
    [25] = {ot = "Elimina a 12 elementales de agua podrida en el Lago Mystral, hacia el este del Paso del Espolón y al sudoeste de Puesto del Hachazo.$B$BExplora la glorieta del Lago Mystral por encima de la avanzada de la Alianza cercana.$B$BVuelve con Mastok Bufido en Puesto Hachazo, Vallefresno.", st = "Si quieres ser de utilidad, ¿por qué no haces algo para solucionar la situación cerca de Paso del Espolón?$B$BLos transportes entre Vallefresno y Espolón no están en funcionamiento porque el lago cobra vida y ataca a todo lo que se acerca... personas incluidas. Lo que sería más práctico que simplemente aporrear a esos elementales de agua sería que alguien explore la glorieta del Lago Mystral, la que tiene una buena vista de la avanzada de la Alianza allí.$B$B¿Quieres hacer algo útil?", t = "Paralización en Espolón"},
    [26] = {ot = "Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.", st = "$n, he seguido tus progresos con gran gozo. Sin duda te estás convirtiendo en $gun valioso protector:una valiosa protectora; de la naturaleza.$B$BHa llegado el momento de que aprendas más sobre una de las formas animales con las que Cenarius nos ha bendecido. Una forma que podemos adoptar y que nos permite controlar el agua. Tendrás que viajar al poblado Amparo de la Noche, que está en Claro de la Luna, y hablar con Dendrita Rafagaestelar del Círculo Cenarion. Él será tu guía.", t = "Una lección que aprender"},
    [27] = {ot = "Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.", st = "$n, he seguido tus progresos con gran gozo. Sin duda te estás convirtiendo en $gun valioso protector:una valiosa protectora; de la naturaleza.$B$BHa llegado el momento de que aprendas más sobre una de las formas animales con las que Cenarius nos ha bendecido. Una forma que podemos adoptar y que nos permite controlar el agua. Tendrás que viajar al poblado Amparo de la Noche, que está en Claro de la Luna, y hablar con Dendrita Rafagaestelar del Círculo Cenarion. Él será tu guía.", t = "Una lección que aprender"},
    [28] = {ot = "Lleva un adorno de altar del Lago Elune'ara al Santuario de Remulos, al noroeste de Claro de la Luna. Usa el adorno en el santuario. $b$bDespués, habla con Tajarri en el santuario para completar la prueba.", st = "En tu primera prueba, debes ir a las profundidades del Lago Elune'ara y encontrar un adorno de altar. Se descompone rápidamente, por lo que deberás ir inmediatamente al Santuario de Remulos. Coloca el adorno en el altar y habla con Tajarri; es una de las celadoras más apreciadas de Claro de la Luna.$B$BTienes un tiempo limitado para completar la tarea y es probable que tengas que competir con otros druidas en busca de adornos. Necesitarás toda tu destreza mental y física.$B$BSuerte, $n.", t = "La prueba del lago"},
    [29] = {ot = "Lleva un adorno de altar del Lago Elune'ara al Santuario de Remulos, al noroeste de Claro de la Luna. Usa el adorno en el santuario. $b$bDespués, habla con Tajarri en el santuario para completar la prueba.", st = "En tu primera prueba, debes ir a las profundidades del Lago Elune'ara y encontrar un adorno de altar. Se descompone rápidamente, por lo que deberás ir inmediatamente al Santuario de Remulos. Coloca el adorno en el altar y habla con Tajarri; es una de las celadoras más apreciadas de Claro de la Luna.$B$BTienes un tiempo limitado para completar la tarea y es probable que tengas que competir con otros druidas en busca de adornos. Necesitarás toda tu destreza mental y física.$B$BSuerte, $n.", t = "La prueba del lago"},
    [30] = {ot = "Busca el colgante de Agilidad acuática y el colgante de Resistencia acuática. Habla con la gente de Claro de la Luna para conseguir pistas sobre la ubicación de los colgantes. $b$bForma el colgante del león marino con los otros dos cuando estés cerca del Santuario de Remulos. $b$bLleva el colgante completo a Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.", st = "En tu segunda prueba debes encontrar las dos mitades del colgante del león marino. Una obtiene su poder de la agilidad del león marino cuando se desliza en el agua, la otra lo obtiene de su increíble capacidad de resistencia. Los druidas se alimentan de ambos rasgos para asumir su forma acuática.$B$BHabla con la gente de Claro de la Luna para averiguar dónde están las mitades y tráemelas para que las unamos. Luego llevarás el colgante a Dendrita Rafagaestelar.", t = "La prueba del león marino"},
    [31] = {ot = "Vuelve a Cima del Trueno y enséñale el colgante del león marino a Turak Tótem de Runa.", st = "Has completado tu formación para la adopción de una forma acuática. Ve a ver a tu instructor, Turak Tótem de Runa, a Cima del Trueno. Enséñale el colgante y demuéstrale que puedes aprender lo que tenga que enseñarte. Él completará tu formación para que puedas fundirte con el agua.$B$BBuena suerte, joven druida. Volveremos a vernos.", t = "Forma acuática"},
    [33] = {ot = "Tráele 8 piezas de carne de lobo dura a Eagan Desollapelambres fuera de la Abadía de Villanorte.", st = "¡Detesto a esos asquerosos lobos grises! Pero los filetes de lobo son tan deliciosos...  Tráeme carne de lobo dura y te la cambiaré por algo que te será útil.$B$BPuedes cazar a los lobos grises y los lobos jóvenes que merodean por la región de Villanorte.", t = "Lobos en la frontera"},
    [34] = {ot = "Martie Jainrose de Villa del Lago quiere que mates a Panzallena. Llévale un colmillo como prueba.", st = "Han vuelto a arrasar mi jardín, y sé quién es el responsable. Es ese maldito jabalí, ese al que el alguacil Marris llama Panzallena.$B$BYa es demasiado tarde para replantar narcisos. Ese puerco ha devastado mis flores. ¡Acaba con ese bicharraco! Si me traes un colmillo suyo, te recompensaré. Dicen que anda husmeando por los campos que hay al suroeste de Villa del Lago, pero de vez en cuando viene a mi jardín.", t = "Una visita poco grata"},
    [35] = {ot = "El alguacil Dughan quiere que hables con el guardia Thomas.", st = "Si te preocupa que los rumores sobre los múrlocs sean ciertos, hay algo que puedes hacer: viaja al puente oriental de Elwynn y habla con el guardia Thomas. Ha estado emplazado en el puente durante la última semana, así que debe saber cuál es el estado de la situación.$B$BTráeme su informe.", t = "Más preocupaciones"},
    [36] = {ot = "Verna Cejade quiere que le entregues su receta del estofado de los Páramos de Poniente a Salma Saldean.", st = "Nunca pensé que llegaría el día en el que tuviera que dejar la granja. Pero los campos están llenos de ladrones y es demasiado peligroso que sigamos aquí. En cuanto el granjero Cejade consiga arreglar el carro nos pondremos en marcha.$B$B¿Podrías hacerme un favor? Deja que te escriba mi receta del estofado de los Páramos de Poniente. Por favor, llévasela a Salma Saldean, estará en la Finca de Saldean, nada más pasar la bifurcación del camino.", t = "Estofado de los Páramos de Poniente"},
    [37] = {ot = "El guardia Thomas quiere que viajes al norte, río arriba, y busques a sus dos guardias, Rolf y Malakai.", st = "Hace unos días mandé a dos guardias, Rolf y Malakai, a investigar el río. Aún no han regresado. Para completar mi informe necesito saber qué les ocurrió a esos hombres.$B$BViaja al norte a lo largo del río y encuentra a mis guardias... o lo que quede de ellos.", t = "Encuentra a los guardias perdidos"},
    [38] = {ot = "Salma Saldean quiere 3 carnes fibrosas de buitre, 3 morros de dentosangre, 3 ojos de múrloc y 3 okras.", st = "¡Ayúdame a preparar el estofado de los Páramos de Poniente! Vuelve con estos ingredientes: $B $B 3 piezas de carne fibrosa de buitre $b 3 morros de dentosangre $b 3 ojos de múrloc $b 3 okras", t = "Estofado de los Páramos de Poniente"},
    [39] = {ot = "Preséntate ante el alguacil Dughan en Villadorada.", st = "Habla al alguacil Dughan de la muerte de Malakai y Rolf, y después infórmale de que no podrá contener a los múrlocs del este de Elwynn con sus tropas.$B$BSé que no tenemos bastantes soldados, quizás Dughan pueda encontrar alguno más.", t = "Entrega el informe de Thomas"},
    [40] = {ot = "Remy \"Dos Veces\" quiere que hables con el alguacil Dughan de Villadorada.", st = "¡$n, hay una nueva amenaza en el Bosque de Elwynn! ¡Los múrlocs están subiendo por los ríos al este de Elwynn, ahuyentando a los peces y atacando a las buenas gentes de allí!$B$BAvisé al alguacil Dughan, pero le preocupan más los gnolls y los bandidos. No cree que los múrlocs sean una amenaza.$B$B¡Por favor, $n! ¡Habla con Dughan y convéncelo de que envíe más tropas al este!", t = "Un peligro con olor a pescado"},
    [45] = {ot = "Busca a Rolf o alguna prueba de su muerte en el poblado múrloc.", st = "En tu exploración del área encuentras huellas palmeadas que llevan al este por la costa del Lago del Hito. Hacia el este, en la distancia, adivinas la silueta de una aldea múrloc.$B$BQuizás Rolf encontró allí su destino...", t = "Descubre el destino de Rolf"},
    [46] = {ot = "Lleva 8 aletas de múrloc rotas al guardia Thomas al puente oriental de Elwynn.", st = "El ejército de Ventormenta ha puesto precio a la cabeza de los rondadores y batidores múrloc de Elwynn. Mátalos y tráeme sus aletas. El ejército de Ventormenta te recompensará bien.$B$BLos múrlocs han construido una aldea en el Lago del Hito, al norte de aquí, y otra en el sur, donde se bifurca el río.", t = "Recompensas por los múrlocs"},
    [47] = {ot = "Lleva 10 unidades de polvo de oro a Remy \"Dos Veces\" a Villadorada. Puedes obtener polvo de oro de los kóbolds del Bosque de Elwynn.", st = "Los kóbolds de esa zona a veces llevan polvo de oro. Me vendría muy bien. Consígueme un montón de polvo de oro y te pagaré el mejor precio de la ciudad, ¡el mejor!$B$BPuedes encontrar kóbolds en la Mina Abisal, al sur, y también alrededor de la Cantera de Jaspe, al noreste.", t = "Intercambio de polvo de oro"},
    [52] = {ot = "Mata a 8 merodeadores y 5 osos del bosque jóvenes y vuelve a ver al guardia Thomas al puente oriental de Elwynn.", st = "Saludos, $n. Los animales salvajes son más agresivos cuanto más nos alejamos de Villadorada. El Aserradero de la Vega del Este sufre constantes ataques de lobos y osos.$B$BNos vendría bien tu ayuda ahí fuera.", t = "Proteger la frontera"},
    [54] = {ot = "Llévale los documentos del alguacil McBride al alguacil Dughan en Villadorada.", st = "$n, eres $gun:una:c; $c que ciertamente ha demostrado que le preocupa la seguridad de Villanorte. Tu siguiente misión será proteger el Bosque de Elwynn.$B$BSi aceptas, te daré unos papeles para el alguacil Dughan, que está en Villadorada. Para ir a Villadorada, sigue el camino hacia el sur, pasada la frontera.", t = "Informa en Villadorada"},
    [56] = {ot = "La comandante Althea Cerranegro de Villa Oscura quiere que mates a 8 guerreros esqueléticos y a 6 magos esqueléticos.", st = "Como Comandante de La Guardia Nocturna, es mi deber proteger a los ciudadanos de Villa Oscura. Ventormenta ha retirado a los guardias que estaban aquí destacados. Ahora tenemos que arreglárnoslas solos.$B$BSi crees estar a la altura de la tarea, nos vendría bien tu ayuda. Ayuda a La Guardia Nocturna aventurándote en el Jardín Sereno, al sur de Villa Oscura y matando a 8 guerreros esqueléticos y a 6 magos esqueléticos. ¡Hemos de acabar con la amenaza de los no-muertos!", t = "La Guardia Nocturna"},
    [57] = {ot = "La comandante Althea Cerranegro de Villa Oscura quiere que mates a 15 malignos esqueléticos y a 15 horrores esqueléticos.", st = "$n, me están llegando informes de una infestación de no-muertos en el bosque. Si estás a la altura, viaja al Cementerio del Cerro del Cuervo y mata a 15 de esos malignos esqueléticos y a 15 horrores esqueléticos. También me han llegado noticias de la presencia de esqueletos al sur de Villa Oscura, en el Cementerio del Jardín Sereno y en sus alrededores. ¡Hemos de expulsar a los no-muertos del Bosque del Ocaso!", t = "La Guardia Nocturna"},
    [59] = {ot = "Entrega a Sara Timberlain el marcador de armaduras de Ventormenta.", st = "Por tu astucia y valor, te entrego un marcador que vale por una pieza de armadura. Quiero que se lo lleves a Sara Timberlain en el Aserradero de la Vega del Este. Dale el marcador y ella te forjará una armadura. Y cuando la recibas, úsala en defensa de Elwynn, $n.$B$BEl Aserradero de la Vega del Este está pasando el puesto del guardia Thomas en el este.", t = "Armadura de paño y cuero"},
    [60] = {ot = "Lleva 8 velas grandes a William Mortero a Villadorada.", st = "Hola, $gmuchacho:muchacha;. ¿Tienes un momento?$B$BMi hermano y yo somos boticarios en Ventormenta. Yo estoy aquí para conseguir velas grandes, por la cera. ¿Puedes ayudarme?$B$BPuedes conseguir velas grandes de los kóbolds. He oído rumores de que están infestando las minas de Elwynn... La Mina Abisal que está hacia el sur y la Cantera de Jaspe, al este. Te sugiero que empieces a buscar velas en uno de esos lugares.", t = "Las velas de los kóbolds"},
    [61] = {ot = "Lleva el envío de William a Morgan Mortero al Distrito de Mercaderes de Ventormenta.", st = "Mi hermano Morgan espera mi envío de velas en Ventormenta. No tengo tiempo para hacer el viaje en persona, pero si quisieras llevarle el envío, te pagaría bien.$B$BHe empaquetado las velas. Encontrarás a Morgan en nuestra tienda, Herbolario Mortero, en el Distrito de Mercaderes de Ventormenta.", t = "Un envío para Ventormenta"},
    [62] = {ot = "Explora la Mina Abisal y vuelve junto al alguacil Dughan a Villadorada.", st = "¡La mina de Villanorte no es la única que tiene problemas! Según mis informes, la Mina Abisal de Elwynn también ha sido ocupada por los kóbolds.$B$BExplora la mina y comprueba la veracidad de mis informes. Luego vuelve aquí. La mina está hacia el sur de Villadorada, entre La Granja Pedregosa y la granja Maclure.", t = "La Mina Abisal"},
    [63] = {ot = "Derrota a la manifestación de agua corrupta y coloca los brazales de manifestación corrupta con las gotas restantes del agua más pura en el blandón de Siemprefuente en el Bosque de Argénteos.", st = "Por la costa del Bosque de Argénteos, al oeste de El Sepulcro, verás un altar infestado por la peste. Los espíritus de ese lugar ya no se comunican con nuestro pueblo y de ti depende acabar con esa manifestación de la Plaga y limpiar el estanque.$B$BLlévate los brazales de elemental y las gotas restantes de la poción de Salmuera y colócalos en el blandón. El ritual debería bastar para invocar a un espíritu puro con el que comunicarte.$B$BTráeme una prueba de haber completado la tarea y te recompensaré con un tótem.", t = "La llamada del agua"},
    [64] = {ot = "El granjero Cejade quiere que recuperes el reloj de bolsillo que dejó olvidado en el guardarropa de su granja en la plantación de calabazas del Oeste.", st = "¡Fue horrible! Verna me despertó cuando oyó jaleo en los campos. Estaban llenos de gamberros. Nos fuimos corriendo y olvidé recoger mi reloj de bolsillo. Me lo dio el padre de Verna el día de nuestra boda y es horrible saber que está en manos de esos ladrones. Dejé el reloj de bolsillo en el guardarropa de la granja. Busca el campo de calabazas que está al Oeste... no tiene pérdida. ¡Si me lo devuelves te estaré muy agradecido!", t = "La reliquia olvidada"},
    [65] = {ot = "Gryan Mantorrecio quiere que hables con Wiley en Villa del Lago.", st = "La banda de desgraciados responsable de que las gentes de los Páramos de Poniente abandonaran sus tierras se llama a sí misma la Hermandad Defias. Necesito que te infiltres en este clan de matones. Debemos averiguar quién lidera el grupo y dónde se esconden. En Villa del Lago, en la posada, encontrarás a un pícaro que responde al nombre de Wiley; me debe un favor.$B$BViaja a Villa del Lago, en las Montañas Crestagrana, al este de Elwynn, y averigua todo lo que puedas.", t = "La hermandad de los Defias"},
    [66] = {ot = "Busca al secretario Daltry en el Concejo de Villa Oscura.", st = "La otra noche, un terrible tumulto me recorrió las venas. Sentí que mi nieta Alyssa estaba en grave peligro. Consulté las cartas y vi a la Muerte contemplándome desde la mesa.$B$BBusqué la luz en un largo y oscuro trance... intentaba encontrar algo concreto que me ayudara a calmar el espíritu. Y un nombre vino a mí. Stalvan.$B$BAcude al secretario del Concejo e intenta averiguar algo más sobre ese nombre. Temo por todos nosotros.", t = "La leyenda de Stalvan"},
    [67] = {ot = "Viaja a la Escuela de Arroyo de la Luna y lleva cualquier información que descubras sobre Stalvan al secretario Daltry.", st = "Stalvan, ¿eh? Deja que consulte el registro.$B$BStalvan... Stalvan... Veamos... ¡Ah! ¡Aquí está! Tengo un señor Stalvan Mantoniebla. Según consta aquí, su última dirección es la Escuela de Arroyo de la Luna. ¡Pero este dato es de hace mucho tiempo!$B$BHazme un favor, ¿quieres? Si pasas por Arroyo de la Luna, hazme saber si consigues información más reciente sobre este tipo. Me gusta llevar los registros al día.", t = "La leyenda de Stalvan"},
    [68] = {ot = "Lleva la carta polvorienta sin enviar al secretario Daltry.", st = "En el viejo arcón encuentras una carta polvorienta sin enviar.", t = "La leyenda de Stalvan"},
    [69] = {ot = "Ve a la Posada Orgullo de León a ver si alguien ha oído el nombre de Stalvan.", st = "¡Ay, ay! Esto se me debió de pasar la primera vez. En el registro, justo debajo de la primera dirección de Stalvan, hay otra dirección. Está tachada... Parece que se dirigía a la Posada Orgullo de León, en Villadorada. Quizás quieras comprobarlo, $n.", t = "La leyenda de Stalvan"},
    [70] = {ot = "Recupera la carta sin enviar de Stalvan del cofre y entrégala en el distrito de Los Canales de Ventormenta.", st = "Stalvan... ese nombre me suena de algo. ¡Ya sé de qué!$B$BUna noche de tormenta de hace muchos años, llegó aquí un mensajero que buscaba refugio para la noche. Casi a medianoche, el hombre se precipitó escaleras abajo gritando, pálido de terror. Desapareció en la tormenta aún en pijama.$B$BCon las prisas, se olvidó sus cartas en el cofre de arriba. Y nunca volvió a buscarlas. Una de ellas es de ese tal Stalvan. Iba dirigida al distrito de Los Canales de Ventormenta. Puedes quedártela.", t = "La leyenda de Stalvan"},
    [71] = {ot = "Entrega los medallones de Rolf y Malakai al guardia Thomas. Lo encontrarás en el puente oriental de Elwynn.", st = "Ahora que tienes los dos medallones, llévaselos al guardia Thomas al puente. Así sabrá que sus guardias murieron asesinados.", t = "Informa a Thomas"},
    [72] = {ot = "Busca una pista entre los objetos empaquetados.", st = "Mi padre era el custodio de la propiedad mucho antes que yo. Tuvo que limpiar la sangre después de la masacre. Pero eso ahora no viene al caso.$B$BEl fondo de Cresta Sílex se ha agotado. Ahora, las últimas pertenencias de la familia serán subastadas. Es culpa de esos buitres de los recaudadores de impuestos. Como veo que te mueres por saber más, creo que puedes mirar entre toda esta basura. Quién sabe lo que puedes encontrar.", t = "La leyenda de Stalvan"},
    [76] = {ot = "Explora la Cantera de Jaspe y vuelve a informar al alguacil Dughan a Villadorada.", st = "Gracias a ti, ahora sabemos que la Mina Abisal está infestada de kóbolds. Ahora necesitamos un explorador que investigue la Cantera de Jaspe, que está más lejos.$B$BExplora la Cantera de Jaspe e infórmame si ves algún kóbold. Para llegar a la mina, viaja hacia el este por el camino hasta que llegues a la Torre de Azora. Cuando llegues allí, dirígete hacia el norte. Encontrarás la mina al pie de las colinas.", t = "La Cantera de Jaspe"},
    [83] = {ot = "Llévale 6 pañuelos de lino rojo a Sara Timberlain en el Aserradero de la Vega del Este.", st = "Los Defias de Villanorte usan máscaras de arpillera, pero los Defias de Elwynn usan máscaras de lino, que puedo usar para crear artículos de lino muy delicados.$B$BTráeme pañuelos de lino rojos y los usaré para crear algo para ti.$B$BLos miembros de la pandilla Defias están asentados en campamentos por todo Elwynn.", t = "Artículos rojos de lino"},
    [84] = {ot = "Lleva el pastel de tripa de cerdo a Billy Maclure a Los Viñedos de Maclure.", st = "Aquí tienes. Y cuando le des el pastel a Billy, ¡dile que espero que se atragante con él!", t = "Vuelve con Billy"},
    [85] = {ot = "Habla con Billy Maclure.", st = "He perdido mi collar... creo que me lo robó ese granuja de Billy Maclure. Normalmente pasa el día escondido como una rata en Los Viñedos de Maclure, al este de aquí.$B$BRecupera mi collar y le darás una alegría al corazón de una anciana viuda.", t = "El collar perdido"},
    [86] = {ot = "Lleva 4 trozos de carne de jabalí a la tía Bernice Pedregosa en la Granja Pedregosa.", st = "Si me das un pastel, puede que te diga quién tiene el collar. Bernice, esa anciana de la otra granja, hace unos pasteles de tripa de cerdo increíbles...$B$BQuizás te cocine un pastel si le llevas algunos trozos de carne de los jabalíes que rondan por nuestras granjas y le dices para qué son.", t = "Un pastel para Billy"},
    [87] = {ot = "Lleva el collar de Bernice a tía Bernice Pedregosa a La Granja Pedregosa.", st = "Estaba jugando cerca de la Mina Abisal y creo que se me cayó... quiero decir, creo que vi el collar de la señora. No me preguntes cómo llegó allí... ¡Yo no fui!$B$BDe todas formas, vi a un enorme kóbold con dientes de oro que lo recogía y se lo llevaba a la mina. Si encuentras a ese kóbold, encontrarás el collar, ¡lo juro!", t = "Dientes de Oro"},
    [88] = {t = "¡Princesa debe morir!"},
    [89] = {ot = "Lleva 5 picas y 5 remaches de hierro al supervisor Olento a Villa del Lago.", st = "Durante la última invasión orca tuvimos que usar todo el hierro para fabricar balas, espadas y armaduras. Hicimos un pedido de materia prima a Ventormenta, pero unos gnolls Crestagrana secuestraron la caravana y se ocultaron en las colinas de detrás de Villa del Lago.$B$BY ahora estamos sin material para reconstruir el puente. Te recompensaré, $n, si me traes 5 picas y 5 remaches de hierro.$B$BVenga, ¡a trabajar!", t = "El puente sempiterno"},
    [90] = {ot = "Reúne 10 costillares de lobo magros y vuelve con el chef Grual en Villa Oscura.", st = "¡El kebab de lobo sazonado es el especial de la casa! ¡Claro que te puedo preparar un poco! Pero necesitaré algunos productos. Tráeme 10 costillares de lobo magros. Con tantos lobos en el bosque, encontrar costillares no será un problema. Por suerte para ti, acabo de recibir mi último cargamento de hierbas aromáticas de Ventormenta, así que solo me faltan los costillares para ponerme manos a la obra.", t = "Kebab de lobo sazonado"},
    [91] = {ot = "Lleva 10 colgantes Pielsombra a Bailiff Conacher al Concejo de Villa del Lago.", st = "Se ha instalado un enemigo de Ventormenta en las laderas orientales de Crestagrana. Ese bellaco usa lo arcano para extender el terror entre nuestra gente. Se oculta bajo el nombre de Morganth.$B$BHa esclavizado al clan gnoll Pielsombra. De acuerdo con las leyes de Villa del Lago, asistir a un enemigo del Reino está penado con la muerte.$B$B¡Esos miserables gnolls deben morir!$B$BTráeme diez colgantes Pielsombra y te recompensaré.", t = "Ley de Solomon"},
    [92] = {ot = "El chef Breanna de Villa del Lago quiere 5 piezas de carne de cóndor dura, 5 morros de dentosangre grandes y 5 raciones de carne de araña crujiente.", st = "Me encantaría prepararte un estofado Crestagrana. Pero tengo un problemita; durante los disturbios con los orcos alimenté a toda la guarnición de Ventormenta. No me queda nada en la despensa, pero si tú me traes los ingredientes, cocinaré para ti.$B$BTráeme cinco filetes de carne de cóndor dura, cinco morros de dentosangre grandes y cinco raciones de carne de araña crujiente.", t = "Estofado Crestagrana"},
    [93] = {ot = "Reúne 6 patas pegajosas de araña y llévaselas al Chef Grual a Villa Oscura.", st = "Te voy a contar un secreto: ¡los pasteles de \"cangrejo\" oscuro, en realidad se hacen con patas de araña! Sé que es un poco asqueroso, pero las patas de araña son muy sabrosas y los pasteles quedan estupendos. Tráeme patas pegajosas de araña y yo te preparo algunos pasteles.$B$BHe oído que las arañas de hilo venenoso son las mejores para cocinar. Están al norte, entre las laderas de las colinas y el río.", t = "Los pasteles de cangrejo oscuro"},
    [94] = {ot = "Lleva el Glifo de Azora a la Estatua Leonida, cerca de la Torre de Ilgalar, en Crestagrana.", st = "Mi rival, Morganth, es un malvado mago de gran poder que vive en la Torre de Ilgalar, en Crestagrana. He creado un dispositivo que me permitirá espiar sus movimientos: el Ojo de Azora. Ahora puedo verlo desde lejos.$B$BPero no puedo saber lo que piensa... Necesito más ayuda.$B$BSi quieres ayudarme tú, lleva mi Glifo de Azora a la Torre de Ilgalar. Colócalo sobre la Estatua Leonida, cerca de la Torre.$B$BCuando lo hayas hecho, el poder de Azora me permitirá ver los planes de Morganth para el futuro.", t = "Un ojo vigilante"},
    [95] = {ot = "Ve a la granja de Sven y averigua qué había enterrado detrás del viejo tocón.", st = "Yo antes trabajaba en una granja al sureste... hasta que un día que tuve que ausentarme, los Jinetes Oscuros del Paso de la Muerte arrasaron mi granja y asesinaron a mi familia.$B$BCuando regresé vi una figura misteriosa cerca de mi granero... enterrando algo. Huyó antes de que pudiera llegar a él y tampoco quería entretenerme: quería ir tras los Jinetes Oscuros. Así que nunca descubrí qué se escondía allí.$B$BTe agradecería que encontraras lo que enterró aquella figura misteriosa. El lugar en el que debes buscar está detrás del tocón que hay cerca de mi granero.", t = "La venganza de Sven"},
    [99] = {ot = "Lleva 6 grilletes de Piroleña a Dalar Tejealba en El Sepulcro.", st = "Según aumenta mi conocimiento sobre la magia de Arugal, aumenta también mi desdén por el desafortunado necio. Estoy a punto de completar la investigación de su Remedio... Bonito nombre...$B$BMi conocimiento será completo cuando descubra qué encantamiento está causando el extraño comportamiento en la Aldea Piroleña. Por el día, los aldeanos parecen ser humanos. Pero, cuando el sol desaparece, se convierten en huargen Furia Lunar.$B$BNecesito extraer energía de los grilletes encantados que Arugal utilizó con ellos. Tráeme seis grilletes de Piroleña encantados, $n.", t = "La locura de Arugal"},
    [101] = {ot = "Consigue 10 colmillos de necrófago, 10 dedos de esqueleto y 5 viales de veneno arácnido para Lady Eva en Villa Oscura.", st = "A medida que la corrupción mística invade el bosque, la necesidad de autoprotección se hace innegable, $n. El viento me susurra y me cuenta de grandes peligros que el futuro te depara.$B$BSi deseas protegerte, noble $c, tráeme 10 colmillos de necrófago, 10 dedos de esqueleto y 5 viales de veneno arácnido. Te encantaré un tótem de castigo que dañará a aquellos que intenten causarte daño a ti.", t = "El Tótem de castigo"},
    [102] = {ot = "Lleva 8 garras de gnoll al capitán Danuvin en la Colina del Centinela.", st = "Ventormenta nos ha abandonado. Nauseabundos aires de depravación soplan por las llanuras de los Páramos de Poniente. Este era mi hogar y no daré la espalda a los ciudadanos que decidieron permanecer aquí. Nosotros, los antiguos granjeros, ofreceremos resistencia.$B$BTu tarea, si decidieras aceptar, consistirá en patrullar las praderas de los Páramos de Poniente. Localiza y aniquila a los infames gnolls que parecen colaborar con los ladrones de Las Minas de la Muerte. Tráeme 8 garras de gnoll y sabré recompensar tu valentía.", t = "En patrulla por los Páramos de Poniente"},
    [103] = {ot = "Lleva 5 botellas de aceite al capitán Grisillo en el Faro de Poniente.", st = "La noche en que murió la familia del guardián del Faro fue horrible. Contemplé, impotente, cómo el Viejo Ojosombrío lideraba el ataque. Pero lo pasado pasado está y lo que ahora me preocupa son las vidas de los que navegan por el Mare Magnum y se acercan demasiado a las peligrosas rocas de la costa. Como no hay nadie que vigile la llama, la responsabilidad es ahora mía.$B$BAyúdame a mantener la antorcha iluminada trayéndome 5 botellas de aceite de los monstruos de la cosecha.", t = "Guardián de la Llama"},
    [104] = {ot = "Lleva una escama del Viejo Ojosombrío al capitán Grisillo en el Faro de Poniente.", st = "Cuando acabó mi vida contra las rocas, no tenía ni idea de lo que me esperaba en el más allá. El Faro estaba sumido en la oscuridad aquella noche, ya que el Viejo Ojosombrío había asustado a la familia del guarda. Lograron regresar y volver a encender la llama, pero el Viejo Ojosombrío coaccionó a los múrlocs de mente más débil para que asaltaran el Faro con él de nuevo. La segunda vez, la familia no corrió la misma suerte y pereció inútilmente ante mis ojos.$b$bMata al Viejo Ojosombrío si lo ves por la costa y tráeme una de sus escamas, te recompensaré.", t = "La amenaza costera"},
    [106] = {ot = "Entrega a Tommy Joe Pedregosa la carta de amor de Maybell.", st = "¡Oh, estoy maldita! He entregado mi corazón a Tommy Joe Pedregosa, pero nuestras familias se odian a muerte. Así que no puedo verlo, ¡aunque me duelan los ojos por no poder mirar su hermoso rostro!$B$BTe lo ruego, lleva esta carta a Tommy Joe. Suele estar en el río que está al oeste de La Granja Pedregosa, al oeste de aquí.", t = "Jóvenes enamorados"},
    [107] = {ot = "Lleva la nota de la Abuela Pedregosa a William Mortero.", st = "¡Seguro que William Mortero tiene una poción que reúna a los dos jóvenes amantes!$B$BTen, llévale esta nota a William. Está en la Posada Orgullo de León, en Villadorada.", t = "Una nota para William"},
    [109] = {ot = "Habla con Gryan Mantorrecio. Puedes encontrarlo en la torre de piedra de la Colina del Centinela, saliendo de la carretera que cruza los Páramos de Poniente.", st = "Parece que has visto bastantes combates en tu vida, $c. Si no has tenido suficiente, busca a Gryan Mantorrecio. Comanda la Milicia Popular que protege las granjas de los Páramos de Poniente. Seguro que le vendrá bien tu ayuda. Puedes encontrarlo en la torre de piedra de la Colina del Centinela, saliendo de la carretera que cruza los Páramos de Poniente.", t = "Habla con Gryan Mantorrecio"},
    [111] = {ot = "Habla con la Abuela Pedregosa.", st = "Por favor, $n, habla con mi abuelita. Si alguien puede encontrar la forma de reunirme con Maybell, esa es ella.$B$BEstá en nuestra casa, al este de aquí.", t = "Habla con la abuelita"},
    [112] = {ot = "Lleva 4 hojas de alga de cristal a William Mortero a Villadorada.", st = "Puedo hacer un licor de invisibilidad para Maybell, para que salga de Los Viñedos de Maclure y se reúna con Tommy Joe. Pero para hacer el licor necesito alga de cristal.$B$BAunque el alga normalmente crece en el océano, también se puede conseguir de los múrlocs. Ve a ver si los múrlocs que hay cerca del Lago de Cristal tienen algo. El Lago de Cristal está al este de Villadorada.", t = "La recolección de algas"},
    [114] = {ot = "Lleva el licor de invisibilidad a Maybell Maclure.", st = "Lleva este licor de invisibilidad a la joven Maybell. Debería durar lo suficiente para que haga una visita a Tommy Joe.", t = "La fuga"},
    [115] = {ot = "Lleva 3 orbes de medianoche al alguacil Marris a Villa del Lago.", st = "Los Roca Negra han traído taumaturgos oscuros a los ataques en Crestagrana. Tienen unos objetos de poder oscuro, los orbes de medianoche. Estos orbes han malherido a muchos de los que luchan en Crestagrana; tenemos que hacernos con esos objetos demoníacos.$B$BTráeme los orbes de medianoche de los cadáveres de taumaturgos umbríos Roca Negra. Me encargaré de destruirlos; el mundo estará mejor sin ellos.", t = "Magia de las Sombras"},
    [118] = {ot = "Llévale la nota de Verner al herrero Argus en Villadorada.", st = "¡He necesitado tanto hierro para abastecer a la guardia de Ventormenta que no tengo bastante para hacer herraduras!$B$BVe a Villadorada y dale esta nota al herrero Argus; le cuento mi problema y le hago un pedido de herraduras.", t = "El precio de unas herraduras"},
    [119] = {ot = "Regresa con Verner Osbien en Crestagrana y entrégale el cajón de herraduras.", st = "Muy bien, 50 herraduras...$B$B¡Aquí las tienes, listas para llevar! Dile a Verner que ha sido un placer y que lea la nota que he pegado a la caja.", t = "Regresa junto a Verner"},
    [120] = {ot = "El magistrado Solomon te ha dado un informe para el general Marcus Jonathan de Ventormenta. Quiere que vuelvas en cuanto lo hayas entregado.", st = "Estamos en tiempos difíciles, $c. Vivimos bajo un asedio constante. Si no llegan refuerzos, solo nos queda la derrota. El mensaje que te confío es de la mayor importancia. Llévaselo al general Marcus Jonathan de Ventormenta inmediatamente. Después vuelve, ya sean tus noticias buenas o malas.$B$B¡Apresúrate!", t = "Mensajero a Ventormenta"},
    [121] = {ot = "Lleva la respuesta del general Marcus Jonathan al magistrado Solomon a Villa del Lago.", st = "Mientras espero la respuesta del Rey, llévale esta carta al magistrado Solomon.$B$BPuedes retirarte, $c.", t = "Mensajero a Ventormenta"},
    [122] = {ot = "Lleva 6 escamas de barriga de cachorro de dragón Negro a Verner Osbien a Crestagrana.", st = "Necesito escamas de barriga de cachorro de dragón Negro para pagarle las herraduras que Argus me envió desde Villadorada. Si me traes 6 escamas, tendré para pagarle y también para hacerte un regalo.$B$BEsos bichos vuelan al sur de Villa del Lago, pero a menudo se alejan. Tendrás que estar ojo avizor para cazarlos en cuanto los veas.", t = "Escamas de barriga"},
    [123] = {ot = "Ve a ver al alguacil Dughan en Villadorada y entrégale la lista del coleccionista", st = "Esta nota muestra un cronograma de días y horarios en los que una persona —descrita como \"el Coleccionista\"— recibirá cargamentos de oro provenientes de las minas del Bosque de Elwynn.$B$BSegún la nota, parece que el Coleccionista vive cerca de la Plantación de Calabazas de Brackwell, al este de Elwynn.$B$BParece importante. Deberías informar al alguacil Dughan en Villadorada.", t = "El Coleccionista"},
    [124] = {ot = "Mata a 10 toscos y 8 místicos Crestagrana y ve a ver a Verner Osbien.", st = "¡Como si no tuviera bastante con los orcos! Ahora tengo toscos y místicos gnolls en la cresta que hay al norte de mi establo y se llevan mis caballos cuando se pierden.$B$BSi nos libras de los gnolls, mis caballos y yo te lo agradeceremos eternamente.", t = "El aullido de los gnolls"},
    [125] = {ot = "El supervisor Olento de Villa del Lago quiere que recojas su caja de herramientas del fondo del Lago Sempiterno.", st = "Échame una mano, $n. Con todo esto del asedio, es difícil conseguir suministros. Mis herramientas venían de camino de Villadorada, pero hicieron explotar el puente. Pusimos las herramientas en una barca, pero los orcos atacaron con una catapulta y todo acabó en el fondo del lago.$B$BRecupera mi caja de herramientas, $n, y te ganarás una buena recompensa.", t = "Las herramientas perdidas"},
    [126] = {ot = "Lleva la zarpa de Ululante a Verner Osbien a Villa del Lago.", st = "$n, los gnolls siguen ahí. Los oigo aullar mientras cazan en las colinas de Villa del Lago. El que más fuerte aúlla es Ululante, el jefe.$B$B¡Mátalo! ¡Su manada se asustará y huirá! Tráeme su garra como prueba.$B$BY ten cuidado; si es el jefe, será por algo. Ya sabes lo que dicen de los perros viejos.", t = "El aullido de las colinas"},
    [127] = {ot = "Lleva 10 peces luna moteados al maestro de embarcadero Baren a Villa del Lago.", st = "El Lago Sempiterno es famoso por su pez luna moteado. Tiene mucha demanda, ¡pero me estoy quedando sin existencias!$B$BTráeme 10 peces luna moteados; te pagaré bien. Y si no sabes pescar, intenta robárselo a los múrlocs.", t = "Pescado a la venta"},
    [128] = {ot = "Mata a 15 campeones Roca Negra y el guardia Howe te recompensará en Villa del Lago.", st = "Tenemos que acabar con esos Roca Negra. El enemigo ha invadido nuestra tierra. Estas montañas pertenecen al rey de Ventormenta. Nuestras fuentes nos dicen que el jefe de cada unidad del clan se llama Campeón. Encontrarás su campamento hacia el norte, justo al oeste del camino a Las Estepas Ardientes.$B$BEl magistrado Solomon quiere que mueran. Acaba con 15 Campeones Roca Negra y vuelve a verme.", t = "La recompensa de Roca Negra"},
    [129] = {ot = "Llévale su comida al guardia Parker. Está de patrulla en el camino a Villa Oscura.", st = "¿Puedes hacerme un favor? Le he preparado la comida al guardia Parker, pero ha salido de patrulla. Es un guardia de Ventormenta grande y fuerte que puede defenderse, pero para mí es demasiado peligroso.$B$B¡Si le llevas la comida, cuando vuelvas te invitaré a comer! ¿Qué me dices? Está de patrulla en el camino a Bosque del Ocaso.", t = "Una comida gratis"},
    [130] = {ot = "Habla con Martie Jainrose, la herborista de Crestagrana.", st = "¿Te importa entregarle unas flores a Darcy de mi parte? Cómpralas en el herbolario de Villa del Lago, en el extremo oeste de la ciudad.$B$BPero no vayas a decir en la tienda para quién son o quién las envía...", t = "Una visita al herborista"},
    [131] = {ot = "Dale el ramo de narcisos a Darcy.", st = "Aquí tienes el ramo. Lo he hecho de narcisos, mis flores favoritas.", t = "Un ramo de narcisos"},
    [132] = {ot = "Lleva la Nota de Wiley a Gryan Mantorrecio en los Páramos de Poniente.", st = "Lo que voy a contarte puede costarme la vida. La banda Defias está preparando algo grande. Lo último que oí fue que estaban colaborando con varios gnolls, kóbolds e incluso goblins.$B$BLlévale esta nota a Mantorrecio. Explica todo lo que sé sobre este asunto.", t = "La hermandad de los Defias"},
    [135] = {ot = "Lleva la Nota de Wiley a Mathias Shaw de Ventormenta.", st = "Me pregunto qué querría decir Wiley cuando habló de los Albañiles. Quizás fue un lapsus. ¿Podría estar relacionada la banda Defias con los Albañiles? El único que podría saberlo es Mathias Shaw, líder del IV:7. Enséñale la nota de Wiley, tal vez tenga algo que añadir a este misterio. Si tienes problemas para encontrarlo, busca en el Cuartel, en el Casco Antiguo.", t = "La hermandad de los Defias"},
    [136] = {ot = "Encuentra el baúl del capitán Sanders y busca la siguiente pista.", st = "Si estás leyendo esto, el capitán Sanders estará sepultado bajo el agua. Así que mi tesoro es tuyo, solo tienes que seguir las pistas.$B$BPrimero tienes que encontrar mi baúl. Seguramente estará enterrado en la arena, en la costa Oeste de los Páramos de Poniente, cerca de los restos de naufragios. Habrá muchos restos, pero solo un ancla oxidada en la costa. ¡Encuentra el ancla y encontrarás mi baúl! Allí encontrarás también la siguiente pista.", t = "El tesoro escondido del capitán Sanders"},
    [138] = {ot = "Busca el viejo barril junto a la chimenea en ruinas y busca la siguiente pista.", st = "Esto es lo que dice la siguiente pista: ¡Buen trabajo, compañero! Ahora tienes que ir al Este. Al Este hacia los riscos, al Este hacia el camino. Busca las ruinas de chimeneas a orillas del camino. Allí encontrarás un viejo barril con la siguiente pista.", t = "El tesoro escondido del capitán Sanders"},
    [139] = {ot = "Busca la jarra vacía junto al molino de viento para encontrar la siguiente pista.", st = "Buscando en el barril descubres otro fragmento de papiro. En este se puede leer: Desde este barril, ve hacia el Norte. Tan recto como vuela el cuervo, anda hasta que veas una jarra vacía junto al solitario molino de viento sobre los riscos del mar. Si buscas alrededor de la jarra encontrarás lo que estás buscando.", t = "El tesoro escondido del capitán Sanders"},
    [140] = {ot = "Localiza la arqueta del capitán Sanders y ábrela para obtener tu recompensa.", st = "Ciertamente, dentro de la vieja jarra hay otra pista sobre el tesoro de Sanders. La tinta se ha corrido en algunas partes y el papel huele a whisky, pero aún logras comprender algunas partes del texto: Ahora que has encontrado mi vieja jarra de whisky ¡casi has llegado al tesoro! Dirígete hacia el Oeste desde la botella y baja hasta la costa. Cuando llegues al agua, ¡sigue adelante! ¡Nada directo hacia el oeste hasta encontrar la isla con el cofre del tesoro!", t = "El tesoro escondido del capitán Sanders"},
    [141] = {ot = "Lleva el informe de Shaw a Gryan Mantorrecio de los Páramos de Poniente.", st = "La Hermandad de los Albañiles estaba dirigida por un tal Edwin VanCleef. VanCleef fue responsable de la reconstrucción de Ventormenta cuando la ciudad fue arrasada por los orcos en la Primera Guerra. Al parecer, VanCleef y sus hombres no estaban satisfechos con el tratamiento que les brindó el rey cuando terminó la reconstrucción. Pero eso solo explicaría algunas cosas.$B$BHe redactado un informe más detallado para tu maestro en los Páramos de Poniente. ¡Llévaselo de una vez!", t = "La hermandad de los Defias"},
    [142] = {ot = "Localiza al mensajero Defias de los Páramos de Poniente y lleva su mensaje a Mantorrecio.", st = "Tenemos que descubrir la localización de la Ladronera Defias. $n, según los informes de mi explorador se ha visto a un mensajero Defias en los caminos entre el Arroyo de la Luna, la Mina de la Costa del Oro y la Mina de Jango. Quiero que le captures. Si ofrece resistencia, mátalo y tráeme lo que esté llevando.", t = "La hermandad de los Defias"},
    [143] = {ot = "El magistrado Solomon quiere que lleves su petición a Gryan Mantorrecio a los Páramos de Poniente.", st = "En el ejército de Ventormenta pasa algo raro; ya deberían haber llegado. No tenemos tiempo que perder. No voy a quedarme a mirar cómo se sacrifica la gente de Villa del Lago sin intentar conseguir ayuda. He oído que en los Páramos de Poniente se ha formado una Milicia Popular.$B$BLleva nuestra súplica a su jefe, Gryan Mantorrecio; puede que sus hombres nos ayuden hasta que llegue la Reserva.", t = "Mensajero a los Páramos de Poniente"},
    [144] = {ot = "Lleva la respuesta de Gryan Mantorrecio al magistrado Solomon.", st = "Me duele leer la nota del magistrado Solomon. Evidentemente, no sabe que hay guerra en los Páramos de Poniente, si no, no pediría ayuda a la Milicia. Si Ventormenta no nos hubiera abandonado también a nosotros, no necesitaríamos una milicia.$B$BLlévale la respuesta a tu señor en Crestagrana, $c. Dile que lamento la pérdida de tantos hombres buenos.", t = "Mensajero a los Páramos de Poniente"},
    [145] = {ot = "El magistrado Solomon quiere que lleves una carta a Lord Cerranegro a Villa Oscura.", st = "Necesito tu ayuda una vez más. He escrito a Lord Cerranegro para pedir que mande a su Guardia Nocturna como refuerzo de la defensa de Villa del Lago. Es imprescindible que reciba este mensaje cuanto antes, pero debes ser extremadamente prudente. Cerranegro es el alcalde de Villa Oscura, en pleno corazón del Bosque del Ocaso. No te salgas de los caminos.", t = "Mensajero a Villa Oscura"},
    [146] = {ot = "Lleva la respuesta de Lord Cerranegro al magistrado Solomon.", st = "Si no conociera a Solomon, diría que se ha vuelto loco. ¿Que envíe a La Guardia Nocturna a Villa del Lago porque Ventormenta no envía ayuda? La Guardia Nocturna se creó porque Ventormenta nos abandonó cuando nos infestó esta magia inmunda. Si envío a la Guardia, esta ciudad sería invadida antes de que mis guardias lleguen al Linde del Bosque.$B$BLlévale la respuesta a tu señor en Villa del Lago.", t = "Mensajero a Villa Oscura"},
    [147] = {ot = "Encuentra y mata al Coleccionista y vuelve junto al alguacil Dughan con el anillo del coleccionista.", st = "Si el Coleccionista se está llevando oro de nuestras minas, ¡está robando al Rey! Lleva al Coleccionista ante la justicia. Y tráeme a mí el anillo que se mencionaba en la nota. Podría indicarnos para quién trabaja el Coleccionista...$B$BLa nota dice que el Coleccionista se esconde en la Plantación de Calabazas de Brackwell. Deberías buscarlo allí.\"", t = "La persecución"},
    [148] = {ot = "Habla con Lady Eva.", st = "Ay, ¿qué puede hacer un anciano como yo? Necesito suministros de Villa Oscura, pero está tan lejos y yo soy tan viejo y tan débil... No sobreviviría al viaje.$B$B¿Podrías ir a Villa Oscura y traerme un poco de hilo de cabello de fantasma? Puedes conseguirlo de Lady Eva. Ve a su casa en la plaza de Villa Oscura.", t = "Suministros de Villa Oscura"},
    [149] = {ot = "Lleva el peine espectral a Mary la Ciega.", st = "Mary la Ciega es un desgraciado y triste espíritu que mora en una vieja granja en las colinas del sur de Villa Oscura.$B$BTen, coge este peine espectral y pide a Mary la Ciega que se peine el cabello. Luego tráeme el peine y yo extraeré de él el cabello de fantasma que necesito para crear el hilo.$B$BY ten cuidado... cerca de la casa acechan seres oscuros...", t = "Hilo de cabello de fantasma"},
    [150] = {ot = "Lleva 8 aletas múrloc al maestro de embarcadero Baren a Villa del Lago.", st = "Los múrlocs nos están complicando la vida. Se están instalando en las orillas del Lago Sempiterno y pescan en cantidades increíbles. ¡Tenemos que echarlos o acabarán con todos los peces del lago!$B$B¿Te apetece cazar múrlocs? Tráeme 8 aletas y te llevarás algo a cambio...", t = "Cazadores furtivos"},
    [151] = {ot = "Verna Cejade de los Páramos de Poniente quiere que le lleves 8 puñados de avena.", st = "¡Pobre vieja Blanchy! La bestia está agotada después de todo el trabajo que le dimos. Le di de comer antes de dejar la granja, pero no esperábamos que se rompiera el carro. Si pudieras traerle algunos puñados de avena te estaría muy agradecida.$B$BSeguro que podrás encontrar algunos por las granjas de los Páramos de Poniente, si puedes librarte de esas horribles máquinas que los han invadido. Hay varias granjas al suroeste de aquí.", t = "La pobre y vieja Blanchy"},
    [152] = {ot = "Mata 7 cazamareas, 7 guerreros, 7 oráculos y 7 correcostas y vuelve con el capitán Grisillo en el Faro de Poniente.", st = "Seguramente habrás visto todos los restos de naufragios a lo largo de la costa. El Mare Magnum es traicionero. La costa de los Páramos de Poniente tiene que estar limpia, de ese modo si algún marinero llega hasta nuestras costas, no correrá ningún peligro. Pero los múrlocs son un gran problema.$B$BMata 7 cazamareas, 7 guerreros, 7 oráculos y 7 correcostas y procuraré que seas $grecompensado:recompensada;.", t = "Hay moros en la costa"},
    [153] = {ot = "Lleva 15 pañuelos de cuero rojo al explorador Galiaan en la Colina del Centinela.", st = "La tapadera de los Defias cambia constantemente. He estado siguiendo sus movimientos desde hace algún tiempo. Aunque, recuerda, he averiguado que muchos miembros de la banda se identifican por sus pañuelos de cuero rojo.$B$BTráeme 15 de esos pañuelos y procuraré que seas $grecompensado:recompensada;.", t = "Pañuelos rojos de cuero"},
    [154] = {ot = "Lleva el peine de fantasma a Lady Eva a Villa Oscura.", st = "¡¡NO!!$B$B¡Aleja ese peine de mí!$B$B¡Soy un monstruo! ¡Nadie volverá a pensar que soy guapa!", t = "Devuelve el peine"},
    [155] = {ot = "Escolta al Traidor de los Defias a la ladronera secreta de la Hermandad Defias. Cuando el Traidor de los Defias te enseñe dónde se esconden VanCleef y sus hombres, regresa con Gryan Mantorrecio con toda la información.", st = "¿Así que Mantorrecio envía a $gun:una; $r enclenque para protegerme? Supongo que tendrás que hacerlo. Pero será mejor que traigas algunos amigos.$B$B¿Ya conoces el trato, verdad? Tú me guardas las espaldas y yo te llevo hasta la Ladronera Defias. La banda Defias busca mi cabeza, así que si me ven contigo, intentarán matarme.$B$BAvísame cuando tú y los amigos que puedas reunir estén listos para emprender la marcha.", t = "La hermandad de los Defias"},
    [156] = {ot = "Recoge 8 flores podridas y llévaselas al tabernero Smitts a Villa Oscura.", st = "Si me traes algunas flores podridas puedo prepararte un poco de zumo de zombi.$B$BLas flores podridas crecen en lugares extraños. En particular, tengo entendido que puedes encontrarlas en las calaveras de horrores esqueléticos y malignos esqueléticos... ¡Claro que nunca lo he comprobado en persona!$B$BEl Cementerio de Cerro del Cuervo y del Jardín Sereno están repletos de esqueletos. Podrías deshacerte de ellos mientras buscas las flores podridas. El pueblo de Villa Oscura estará agradecido.", t = "Busca flores podridas"},
    [157] = {ot = "Lleva el hilo de cabello de fantasma a Abercrombie, a su choza al norte del Cementerio del Cerro del Cuervo.", st = "Aquí tienes tu hilo, $n. Entre muchas otras cosas, sirve para atar espíritus malvados o para coser la vida en objetos inanimados.", t = "Devolver el pelo"},
    [158] = {ot = "Habla con el tabernero Smitts.", st = "Necesito una botella de licor. De zumo de zombi. El tabernero Smitts, del Mesón del Cuervo Escarlata de Villa Oscura, debería tener alguna botella.$B$BPor favor, date prisa, $n. ¡Las noches empiezan a ser frías y necesito ese fuego en mis venas!", t = "Zumo de zombi"},
    [159] = {ot = "Lleva el zumo de zombi a Abercrombie a su choza.", st = "Aquí tienes tu zumo de zombi...$B$BY... ten cuidado con él. ¡Es tan fuerte que resucitaría a un muerto!", t = "Entrega de zumo"},
    [161] = {ot = "El ingeniero jefe Hinderweir quiere que lleves las partículas con olor extraño a Ashlan Risapétrea, el experto en explosivos en Dun Modr.", st = "Si lo que sospecho es cierto, se trata de una especie de pólvora explosiva. Un experto en explosivos debe analizarla para que sepamos con qué estamos tratando. Ashlan Risapétrea fue asignado al regimiento que protege Dun Modr y el Puente Thandol. Necesito que realices un viaje peligroso y severo, $n.$b$bAtraviesa la Puerta de Algaz, sigue el camino a través de Los Humedales y busca a Risapétrea en Dun Modr. Escucha mi consejo: ¡no te salgas del camino y no te detengas por nada!", t = "Se aproxima una oscura amenaza"},
    [163] = {ot = "Averigua qué está acechando Cerro del Cuervo.", st = "Algo ocurre en Cerro del Cuervo, $n. Calor jura que alguien –o algo– está rondando los edificios de la zona. Ha visto sombras moviéndose dos noches seguidas y dice que hace tres noches vio luz en una de las ventanas.$B$BSi, como dices, te preocupa la seguridad del Bosque del Ocaso, averigua qué monstruo acecha el Cerro del Cuervo.", t = "Cerro del Cuervo"},
    [164] = {ot = "Entrega los suministros a Sven.", st = "¿Conoces a Sven? ¡Pues él sí que trabaja para la Luz! Él y sus seguidores están acampados en la linde noroccidental del Bosque del Ocaso.$B$BPor desgracia, son muy pocos, y no pueden permitirse enviar a nadie a buscar suministros a la ciudad. ¿No podrías llevarles tú estos suministros?", t = "Entrega a Sven"},
    [165] = {ot = "Ve a ver cómo está el anciano de la choza que hay cerca del Cementerio del Cerro del Cuervo.", st = "Antes venía por aquí un anciano... venía a comprar suministros con bastante frecuencia, pero hace un tiempo que no lo veo. Vive en una choza cerca del Cementerio del Cerro del Cuervo, si no recuerdo mal. ¿Podrías ir a ver si le ha ocurrido algo?", t = "El ermitaño"},
    [166] = {ot = "Mata a Edwin VanCleef y lleva su cabeza a Gryan Mantorrecio.", st = "Todavía hay una tarea que debes cumplir. Edwin VanCleef debe ser asesinado. Aunque me entristece condenar a alguien a la pena de muerte, el bien común de las gentes de los Páramos de Poniente exige que VanCleef descanse de una vez por todas. Tráeme la cabeza de ese villano cuando hayas terminado tu hazaña.", t = "La hermandad de los Defias"},
    [167] = {ot = "Lleva la insignia de la Liga de Expedicionarios del supervisor Cardortiga a Wilder Cardortiga, en Ventormenta.", st = "Estábamos en las profundidades de una gran mina en los Páramos de Poniente, oculta tras un granero en el Arroyo de la Luna. No tenemos ni idea de dónde salieron esos ladrones. En fin, el túnel se derrumbó sobre nosotros. Conseguí salir, pero los otros... bueno... de los otros no sé nada.$B$BCreo que tú podrías tener más suerte ahí abajo. Si pudieras buscar a mi hermano, te lo agradecería mucho. Siempre llevaba su insignia de la Liga de Expedicionarios. Si no puedes encontrarle, al menos la insignia me daría algo de paz mental.", t = "Oh, hermano..."},
    [168] = {ot = "Recupera 4 Tarjetas del Sindicato Minero y llévaselas a Wilder Cardortiga, en Ventormenta.", st = "Muchos de mis amigos murieron ese horrible día cuando se derrumbó el túnel de la mina. Si tus aventuras te llevan de casualidad a esa parte de la mina en el Arroyo de la Luna, por favor, busca alguna señal que pueda identificarles. Si te encuentras con alguna de sus Tarjetas del Sindicato Minero, tráemelas y me aseguraré de que sus familias reciban la resolución de este horrible accidente.", t = "Recolección de recuerdos"},
    [169] = {ot = "Mata a Gath'Ilzogg y lleva su cabeza al magistrado Solomon a Villa del Lago para recibir tu recompensa.", st = "Se busca a Gath'Ilzogg por dirigir los ataques Roca Negra al Fuerte de Petravista y las incursiones en Villa del Lago.$B$BGath'Ilzogg es extremadamente peligroso. Se encuentra en el Fuerte maquinando nuevos crímenes del clan contra la humanidad. Debemos sofocar la infestación de orcos cueste lo que cueste. Se ofrece recompensa a quien presente la cabeza de Gath'Ilzogg al magistrado Solomon.", t = "SE BUSCA: Gath'Ilzogg"},
    [170] = {ot = "Balir Martilloescarcha quiere que mates a 6 troggs Comepiedras y a 6 troggs Comepiedras fornidos.", st = "Espero que estés aquí para echar una mano, $c. Después del último ataque de los troggs, nos vendría bien cualquier ayuda.$B$BHe oído que esos malnacidos han estado apareciendo por todas partes y parece que el Valle de Crestanevada no es una excepción. Han sido vistos en los montes del sureste y cerca del lago helado.$B$BY eso no es todo. Hace unas noches atacaron e invadieron nuestro campamento del oeste.$B$BNecesitamos ayuda, $gmuchacho:muchacha;. Necesitamos brazos fuertes para hacer retroceder a los troggs.", t = "Una nueva amenaza"},
    [174] = {ot = "Viktori Prism'Antras de Villa Oscura quiere que le lleves un tubo de bronce.", st = "Cog, mi amigo gnomo, me ha prometido ayuda para crear un instrumento que me servirá para ver las estrellas. Más allá de la magia hay una verdad que puede explicar las extrañas transformaciones del bosque.$B$BTráeme un tubo de bronce creado por un ingeniero cualificado. Ese es el primer paso según el manual de Cog.", t = "Mira las estrellas"},
    [175] = {ot = "Localiza a Mary y convéncela de que te dé una superficie reflectora para el proyecto de Viktori.", st = "Según el manual de Cog, ahora necesito encontrar algo para reflejar la luz. Me acuerdo de una mujer llamada Mary que se hizo muy famosa por aquí porque siempre llevaba un espejo consigo. Quizás puedas encontrar a Mary y pedirle que nos preste una superficie reflectante para este proyecto... Vive al sur del Bosque del Ocaso. Al menos, es donde vivía antes...", t = "Mira las estrellas"},
    [176] = {ot = "Mata al gnoll Hogger y llévale su garra de gnoll enorme al alguacil Dughan.", st = "Se busca: Hogger.$B$BUn gnoll enorme, Hogger, está al acecho en el bosque al suroeste de Elwynn. Ha sofocado todos los intentos de capturarlo.$B$BEl ejército de Ventormenta ofrece una generosa recompensa por el gnoll. Para cobrarla, los cazarrecompensas tendrán que llevar una prueba de la muerte de Hogger al alguacil Dughan en Villadorada.", t = "SE BUSCA: \"Hogger\""},
    [177] = {ot = "Quita el espejo de Mary la Ciega al necrófago demente y llévaselo a Viktori a Villa Oscura.", st = "El espejo era uno de mis tesoros más preciados hasta... el incidente. Después de lo que ocurrió, lo escondí detrás del granero. Antes venía por aquí un necrófago demente... Quizás lo cogió él. Se dice que esa bestia inmunda vive en el Cementerio del Jardín Sereno.", t = "Mira las estrellas"},
    [179] = {ot = "Sten Brazorrecio quiere 8 piezas de carne de lobo dura.", st = "¿Qué tenemos aquí? Tienes pinta de necesitar algo para mantener las manos calientes, ¿mm?$B$BYo te diré lo que necesitas: un par de estupendos guantes bien calentitos. Y, como soy un alma generosa, me encantaría proporcionarte ese par de guantes. Pero con una condición.$B$BNecesito que me consigas carne de lobo. Es un buen trato, ¿mm? Tú me traes un poco de carne de lobo y yo evito que pierdas los dedos por congelación. ¿Y bien? ¿Qué dices?", t = "Los enanos modistos"},
    [180] = {ot = "Mata al teniente Fangore y lleva su zarpa al magistrado Solomon a Villa del Lago.", st = "Se busca al teniente Fangore$B$BSe acusa al jefe del clan gnoll Pielsombra de colaborar con el enemigo del Reino Morganth. El magistrado Solomon ha decretado la pena de muerte para este traidor a Ventormenta. Su zarpa se considerará prueba de su muerte.", t = "Se busca: Teniente Fangore"},
    [182] = {ot = "Grelin Barbablanca quiere que mates 14 crías de trol Peloescarcha.", st = "A mi hermano Senir y a mí nos enviaron a distintas partes de Dun Morogh a investigar la amenaza que representan los trols. El Senado ya tiene bastante con los troggs y no tiene tiempo para más inconvenientes.$b$bPor lo que he visto, los trols no están bien ubicados aquí en Valle de Crestanevada, principalmente se encuentran en la cueva al sur. Diría que el ejército no será necesario. Un par de brazos fuertes deberían bastar.$b$b¿Te interesaría colaborar en esta tarea? Tengo autoridad como para ofrecerte una compensación por tu ayuda.", t = "La cueva de los trols"},
    [183] = {ot = "Talin Ojo Ávido quiere que mates a 12 jabalíes del risco pequeños.", st = "No hay nada como pasar un día cazando jabalíes, ¿eh?$B$BAunque con la de jabalíes que tenemos en el Valle de Crestanevada, la cosa pierde un poco de gracia. Ni siquiera hay que provocarlos. Ya están todos enfadados e inquietos, no necesitan ayuda para eso. De hecho, últimamente hay tantos jabalíes en la zona que mi caza diaria se está convirtiendo en una actividad peligrosa.$B$BPara abreviar, si pudieras ayudarme a matar algunos jabalíes, te lo agradecería mucho.", t = "Cazador de jabalíes"},
    [184] = {ot = "Lleva las escrituras de Cedaje al granjero Cedaje.", st = "Estas son las escrituras de una extensión de tierras de labranza de los Páramos de Poniente. Están firmadas por un tal Theodore Cejade y por su mujer, Verna. En el reverso de las escrituras hay unas palabras garabateadas con gran prisa:$B$B\"Presionamos a Cejade y conseguimos sus escrituras. Pensé que te vendría bien si querías falsificar una para ti.$B$BLos Cejade no nos darán problemas. La última vez que los vi estaban saliendo de los Páramos de Poniente con un carro roto.\"$B$BCrees que probablemente los Cejade querrán recuperar sus escrituras...", t = "Las escrituras de Cejade"},
    [199] = {ot = "Enséñale la pista al ingeniero jefe Hinderweir.", st = "Coges una muestra de esas partículas con olor extraño.", t = "Se aproxima una oscura amenaza"},
    [214] = {ot = "La exploradora Riell de la Colina del Centinela quiere que le lleves 10 pañuelos de seda roja.", st = "No es ningún secreto que la marca distintiva de la banda Defias son los pañuelos rojos. Pero hemos averiguado que el material del que están hechos los pañuelos sirve para identificar el rango del miembro.$B$BDicho esto, quiero que elimines tantos miembros Defias de alto rango como puedas. Podrás encontrarlos en la ladronera secreta de VanCleef. Cuando hayas terminado tráeme 10 pañuelos de seda roja y sabré recompensarte. Buena suerte, $n.", t = "Pañuelos rojos de seda"},
    [216] = {ot = "Elimina 12 vengadores Piel de Cardo y 12 chamanes Piel de Cardo; la mayoría están ubicados al este de Ensenada de Zoram en Poblado Piel de Cardo. Una vez que hayas terminado, regresa con Karang Amakkar en Avanzada de Zoram'gar, Vallefresno.", st = "¡Los fúrbolgs Piel de Cardo son una amenaza para nuestra expansión! El Poblado Piel de Cardo, al este, obstruye el paso entre este lugar y el Puesto del Hachazo. Es un camino que rodearía el pueblo de Astranaar; sin él, ofrecemos a la Alianza una vía más para la expansión.$B$B$n, no podemos permitir... ¡un hueco en el camino de la expansión!$B$BVe al Poblado Piel de Cardo y acaba con los fúrbolgs. Recibirás una compensación por esta tarea y, lo que es más importante, ¡estarás cumpliendo con tu deber para la Horda!", t = "Entre una roca y un Piel de Cardo"},
    [217] = {ot = "Mata al líder trogg, Gromug, y a sus dos guardias, Rechín y Camorrista y preséntate ante el capitán Rugelfuss en la torre de vigilancia del sur.", st = "$n, nuestros exploradores han identificado al líder de esta incursión reciente de troggs. Parece que estas bestias en Loch Modan siguen las órdenes de un jefe llamado Gromug. Sin embargo, Gromug tiene mucha custodia. Dos de sus guardias más importantes, Rechín y Camorrista, jamás se alejan de su lado.$b$bSi te sientes $gpreparado:preparada;, $n, quiero que dirijas la misión de asesinato de Gromug y de sus dos matones. Una vez que el líder trogg esté muerto, quizás tengamos una oportunidad para expulsar a estas bestias de regreso a la tierra.", t = "En defensa de las tierras del rey"},
    [218] = {ot = "Grelin Barbablanca quiere que mates a Grik'nir el Frío y recuperes su diario.", st = "¡Mi diario! Se lo llevaron a la cueva. El que lo tenía... era un bruto enorme con marcas extrañas en el rostro y el cuerpo. No pude ver mucho más que eso.$b$bHas tenido suerte con los trols... ¿Podrías recuperarlo por mí?", t = "El diario robado"},
    [219] = {ot = "Protege al cabo Keeshan en el camino a Crestagrana.", st = "¡Al fin, ayuda para la Alianza!$B$BAyúdame...$B$BLo último que recuerdo es que esos malditos orcos nos tenían rodeados. Los mataron a casi todos. A mí me dieron un golpe en la cabeza y perdí el conocimiento, y ahora me encuentro cautivo. Ayúdame, estoy malherido.$B$BTienes que ayudarme a volver... Por favor, eres mi única esperanza.", t = "Desaparecido en combate"},
    [220] = {ot = "Llévale el vial de agua pura a Islen Vident'aqua en Los Baldíos.", st = "Islen tendrá una tarea más para ti antes de recompensarte con tu siguiente tótem. Sea cual sea esa tarea, te hará falta el vial de agua que te he dado.$B$BAhora vete y encuéntrala. Volveremos a encontrarnos algún día.", t = "La llamada del agua"},
    [224] = {ot = "El montaraz Pedernal en la torre de vigilancia sur quiere que mates a 10 troggs Rompecantos y 10 exploradores Rompecantos.", st = "¡Tenemos que proteger Loch Modan, $n! Con todos los soldados del rey que tenemos luchando valientemente en campañas remotas, estamos superados en el frente local. ¡Los troggs emergen de todas las grietas posibles! La infestación trogg es la principal amenaza para Forjaz. Tenemos que destruir a estos mutantes asquerosos.$b$bTe necesitamos, valiente $gaventurero:aventurera;, para que avances y acabes con la amenaza trogg. Mata 10 troggs Rompecantos y 10 exploradores Rompecantos y vuelve a verme.", t = "En defensa de las tierras del rey"},
    [226] = {ot = "Mata a 12 lobos feroces hambrientos y a 8 lobos feroces rabiosos y vuelve al campamento de Sven en la frontera oeste de Bosque del Ocaso a buscar a Lars.", st = "A Sven y a mí nos esperan días peligrosos, con el nigromántico al este... y aquí solos... tenemos que cazar nuestra propia comida. Y cada vez que vuelvo al campamento con algo de carne, aparecen lobos hambrientos o rabiosos buscando un bocado. ¡Vivir aquí es peligroso, no hace falta que lo jure!$B$BPero si consiguieras librarnos de algunos de esos lobos, nos facilitarías mucho la cosa. Se concentran sobre todo al norte y al este de aquí, cerca del río.", t = "Con los lobos en los talones"},
    [230] = {ot = "Lleva el libro de la granja de Sven a Sven.", st = "Cavando en el montículo encuentras un pequeño libro manchado de tierra.$B$BNo tiene título pero... contiene información que a Sven le gustaría tener.", t = "El campamento de Sven"},
    [233] = {ot = "Entrégale el fajo de cartas a Talin Ojo Ávido.", st = "Mm, oye, tú no querrás hacerme un favor... ¿o sí? Hoy ha llegado un fajo de cartas a través del paso, pero no tengo tiempo para entregarlas.$B$BEstán todas dirigidas a Talin Ojo Ávido. Lo encontrarás al oeste. Solo tienes que seguir el camino. Ha establecido su campamento en la orilla del lago helado.$B$B¿Qué respondes?", t = "Entrega de correo en el Valle de Crestanevada"},
    [234] = {ot = "Entrégale la carta a Grelin Barbablanca.", st = "Si no recuerdo mal, el campamento de Grelin está al sureste, por el camino. Estará ansioso por recibir su correo.", t = "Entrega de correo en el Valle de Crestanevada"},
    [237] = {ot = "El montaraz Gravagau, de la torre de vigilancia sur, quiere que mates a 10 aplastacráneos y 10 videntes Rompecantos. Luego ve a informarle.", st = "El montaraz Pedernal habla muy bien de ti, $r. Por eso he decidido confiarte una misión de extrema importancia. Tenemos que mantener a raya a los troggs invasores hasta que nuestros hermanos regresen de luchar por la Alianza.$B$BDirígete a las colinas del sur y mata a diez aplastacráneos y diez videntes Rompecantos. Eso nos hará ganar tiempo. Regresa cuando termines la misión.", t = "En defensa de las tierras del rey"},
    [239] = {ot = "Ve al Cuartel de Arroyoeste y habla con el ayudante de alguacil Rainer.", st = "La plaza fuerte de la frontera occidental informa de un aumento de actividad de gnolls y ladrones. Solicitan que enviemos más soldados de Ventormenta, ¡pero no podemos prescindir de ninguno!$B$BTu ayuda nos vendría bien. Habla con el ayudante de alguacil Rainer en el Cuartel de Arroyoeste y que te diga qué necesita.$B$BLa plaza fuerte está al oeste, bajando por el camino. Encontrarás un puente sobre un arroyo. Crúzalo. La plaza fuerte estará a la derecha.", t = "El Cuartel de Arroyoeste necesita ayuda"},
    [240] = {ot = "Vuelve a donde Alterio con los pasteles de cangrejo oscuro.", st = "¡¡Y voilà!! ¡Croquetas de \"cangrejo\" à la Grual!", t = "Regresa junto a Alterio"},
    [244] = {ot = "Preséntate ante el ayudante de alguacil Feldon.", st = "Saludos, $c. Estoy patrullando esta parte del camino. De momento todo está en calma, pero he visto campamentos gnoll al norte y al este de aquí.$B$B¡Debes informar de esto en Villa del Lago! Preséntate ante el ayudante de alguacil Feldon en Villa del Lago y dile lo de los gnolls. Seguro que te paga sueldo de explorador.$B$BLo encontrarás al sur del puente a Villa del Lago.", t = "Gnolls invasores"},
    [245] = {ot = "Mata a 15 telarácnidas pigmeovenenosas y vuelve al Bosque del Ocaso a informar al vigía Dodds.", st = "Salve, $c. ¿Has visto esas arañas que han invadido la frontera occidental? Esas amenazas de ocho patas son demasiado para nosotros pero el Comandante no tiene suficientes hombres. No puede enviar a nadie tan lejos de Villa Oscura.$B$BOdio tener que pedirte esto pero, parece que tú podrías manejar a esos bichos. No puedo prometerte una gran recompensa, pero si nos ayudas a erradicar a esos arácnidos, encontraré la forma de compensarte.$B$BAh, y deja que te dé un consejo: evita su veneno a toda costa.", t = "Amenazas de ocho patas"},
    [246] = {ot = "Mata a 10 bastardos y 6 furtivos Crestagrana e informa al ayudante de alguacil Feldon en Villa del Lago.", st = "Andamos escasos de tropas, pero hay que hacer algo con esos gnolls.$B$BRastrea el sur de Crestagrana en busca de gnolls. Espíalos, mata a tantos como puedas y vuelve para informarme de cuántos son y si suponen una amenaza. Sus campamentos están por todo el camino meridional de Crestagrana.$B$BEl ejército de Ventormenta te recompensará, $n.", t = "Evaluar la amenaza"},
    [247] = {t = "El fin de la Caza"},
    [248] = {ot = "Trepa la torre de vigilancia intacta junto a Fuerte de Petravista.$B$BEncuentra un contenedor apropiado para colocar el Glifo de Azora.", st = "He estado observando la Torre de Ilgalar; Morganth está en conflicto con los orcos en el Fuerte de Petravista. Desconozco los motivos, pero tú me ayudarás a descubrirlos.$B$BCoge otro Glifo de Azora y sube a la atalaya intacta que hay junto al Fuerte de Petravista.$B$BEncuentra un objeto en el que depositar el glifo. Un cofre o un tarro iría bien, un lugar en el que nadie se fije en él.", t = "Ver más allá"},
    [250] = {ot = "Investiga los alrededores de la rampa este de la Presa y lleva al ingeniero jefe Hinderweir alguna pista sobre lo que traman los Hierro Negro.", st = "Menos mal que alguien se interesa por el bienestar de la Presa. ¡Primero la destrucción del Puente Thandol y después el saqueo de Dun Modr! No dudo que el objetivo del siguiente ataque de los Hierro Negro será la Presa. Casi todos los agentes de seguridad se han destinado a luchar con la Alianza, incluido mi mejor inspector.$B$BPor eso te necesito, $n. He visto algunos zapadores Hierro Negro en la rampa oriental de la Presa. Investiga la zona y trae una pista.", t = "Se aproxima una oscura amenaza"},
    [255] = {ot = "El magistrado Narizroma de Thelsamar te ha contratado para matar 4 ogros Mo'grosh, 4 brutos Mo'grosh y 4 déspotas Mo'grosh.", st = "Dos meses esperando para que de Forjaz nos digan que nos darán un puñado de soldados para defendernos, ¡y tenemos que esperar otros dos meses hasta que lleguen! Ya es bastante malo que nuestro pueblo esté desprotegido, y además la excavación y la represa —¡la represa!— son blancos fáciles.$b$bParece que no tengo elección. Necesitaré contratar soldados a sueldo.$b$b¿Qué hay de ti? Pareces $Gun:una; $c bastante capaz. Un grupo de ogros se ha establecido al noreste del lago. Quizás puedas reclutar algunos guerreros más y eliminar esta amenaza.", t = "Mercenarios"},
    [257] = {ot = "Mata 6 águilas ratoneras montesas y regresa a la Cabaña del Errante con Daryl el Jovenzuelo en menos de 15 minutos.", st = "¿Crees que tu astucia se compara con la de Daryl el Audaz? ¡Claro que no! Por supuesto, eres más que $Gbienvenido:bienvenida; a intentar superarlo. Aquí tienes un desafío que debería estar por encima de tus habilidades, así que no te sientas mal si no estás a la altura.$b$bUna bandada de cuervos ha anidado aquí en Loch Modan. ¿Por qué no intentas acabar con algunas de esas bestias? Te diré algo más, si logras superar mi desafío en quince minutos, te daré mi arco o mi arma.$b$b<Te observa con desdén.>$b$bDe cualquier forma, no pareces tener mucho que perder.", t = "La fanfarronada de un cazador"},
    [258] = {ot = "Mata 5 jabalíes monteses mayores y regresa a la Cabaña del Errante con Daryl el Jovenzuelo en menos de 12 minutos.", st = "$n, ¿verdad? Veo que estás muy $Gorgulloso:orgullosa; por haber completado la primera prueba. Como dije antes, no es una gran hazaña.$b$bDeberías probar tus habilidades cazando jabalíes. Créeme, esta no es una cacería de jabalíes como la de Valle de Crestanevada, así que será mejor que tengas cuidado con ellos. Te daré solo doce minutos esta vez.$b$bNo te sientas mal si fracasas. ¡Te daría hasta mi último centavo si lo lograras!$b$b¿Alguna vez te conté la historia de cómo conseguí mi famosa cicatriz? ¿No? Fue hace unos dos años...", t = "El reto de un cazador"},
    [262] = {ot = "Llévate el libro que encontraste en la granja de Sven a Villa Oscura y enséñaselo a sus habitantes.", st = "¡Debí adivinar quién era esa figura que vi en las sombras la noche en que mi familia fue asesinada!$B$BPor favor, $n, has demostrado ser $gun hombre:una mujer; de recursos. Te lo ruego, encuentra a ese ser misterioso. ¡He de saber qué secretos guarda!$B$BNo sé nada que tú no sepas ya pero, ten, coge el libro que encontraste en mi granja. Quizás alguien del pueblo pueda decirte a quién pertenece el libro.", t = "La figura en las sombras"},
    [263] = {ot = "Montaraz Muroplof en la torre de vigilancia sur quiere que mates 10 chamanes Rompecantos y 10 cascahuesos Rompecantos.", st = "Los montaraces me han dicho que eres muy valiente y capaz, $n. Necesitamos a $gun:una; $r como tú por aquí. El problema con los troggs no mejora en absoluto. Hemos mandado las reservas al frente y nos hemos quedado solos aquí. Pero ahora que tenemos $Gun:una; $c $Gexperimentado:experimentada;, veamos qué puedes hacer.$b$bSal y mata a 10 chamanes Rompecantos y a 10 cascahuesos Rompecantos. Espero que seas capaz de hacerle honor a tu reputación, $gasesino:asesina; de troggs.", t = "En defensa de las tierras del rey"},
    [264] = {ot = "Coloca el colgante de Clarice sobre la tumba de Yuriv en Argénteos.", st = "¡Sucia escoria! Me abandona por su maldita cruzada porque \"la Luz es lo más importante que tenemos contra la amenaza que representan los no-muertos.\"$B$B¡¿Y sus hijos?! ¡¿Y YO?! Noche tras noche me quedaba esperando por él... ¡siempre en segundo lugar después de sus condenadas obligaciones!$B$BBueno, ¡mira lo que te depara la \"justicia\", $n! ¡Él está muerto y yo tengo precisamente lo que estaba intentando detener!$B$BCoge esto y ponlo encima de su tumba en El Sepulcro. ¡No quiero tener nunca más nada que ver con eso... ni con él!", t = "Hasta que la muerte nos separe"},
    [265] = {ot = "Averigua si otros habitantes tienen pistas sobre la figura misteriosa.", st = "Te devuelvo tu libro, $n. Y te deseo mucha suerte. Si preguntas a la gente del pueblo, quizás puedas conseguir más pistas.$B$BEmpezaré por darte yo una: aunque el autor de este libro no es de Villa Oscura, el libro fue comprado aquí.", t = "La búsqueda de la figura continúa"},
    [266] = {ot = "Busca pistas sobre la figura misteriosa en la posada.", st = "Ten tu libro. Y buena suerte con tus pesquisas.$B$BQuizás quieras continuar la búsqueda en la posada. Si la persona a la que buscas pasó algo de tiempo en el pueblo, es probable que alguien le viera allí.", t = "Preguntas en la posada"},
    [267] = {ot = "Lleva 8 dientes de trogg de piedra al capitán Rugelfuss a la torre de vigilancia sur.", st = "$C, es posible que no estés al corriente de la amenaza trogg que se cierne sobre tierras enanas. Con las fuerzas de reserva de Forjaz en el frente de la Alianza, solo nos queda una fracción de las fuerzas de defensa necesarias para proteger estas tierras. Mi regimiento debe quedarse aquí protegiendo la puerta, por lo que no podemos abandonar nuestros puestos, nos arriesgaríamos a una invasión.$b$bPero tenemos que presionar un poco a esos malditos troggs que merodean por las colinas. Si te crees capaz, lanza un ataque contra los troggs. Tráeme 8 dientes de trogg de piedra como prueba de tu acción.", t = "La amenaza trogg"},
    [268] = {ot = "Lleva a Sven el diario completo de Alterio.", st = "El libro que encontraste no estaba acabado. Tuve que dejarlo en la granja de Sven cuando huí...$B$BTen. Lleva mi diario completo a Sven. Describe con más detalle lo que ocurrió en su granja.$B$BAunque este diario ha sido mi única compañía todas estas semanas, si renunciando a él me evito tener que afrontar la ira de Sven... ¡te lo doy encantado!", t = "Entrega para Sven"},
    [269] = {ot = "Entrega el diario completo de Alterio al obispo Lontananza de Ventormenta.", st = "Ve a la ciudad de Ventormenta y habla con el obispo Lontananza. Búscalo en la Catedral de la Luz. Dale el diario de Alterio y dile que deseas enfrentarte a Morbent Vil.$B$BAunque Ventormenta ha abandonado a Villa Oscura, Lontananza es un alma buena y sabia. Puede que te ayude a salvarnos.$B$BTu misión es peligrosa, pero date prisa, $n. Las sombras del Bosque del Ocaso son más cada vez más oscuras.", t = "En busca de sabiduría"},
    [271] = {ot = "Mata al viejo Tiznado y llévale una prueba a Daryl el Jovenzuelo en la Cabaña del Errante.", st = "Supongo que no te interesa vengarte de Lord Arrogancia, ¿verdad? Daryl tiene cierta habilidad, aunque me duela reconocerlo.$b$bHace un año el objetivo de la Cabaña del Errante era un gran oso, pero ni uno solo de los cazadores logró derribarlo. Así que Daryl decidió probar suerte con él. Lo único que consiguió fue la terrible cicatriz que tiene en el ojo.$b$bMata al oso, y eso sin duda le cerrará el pico a Daryl aunque solo sea por una vez.$b$bPuedes encontrar al oso, el viejo Tiznado, en su guarida, que está en las colinas de Thelsamar.", t = "La venganza de Vyrin"},
    [272] = {ot = "Busca el colgante de Agilidad acuática y el colgante de Resistencia acuática. Habla con la gente de Claro de la Luna para conseguir pistas sobre la ubicación de los colgantes. $b$bForma el colgante del león marino con los otros dos cuando estés cerca del Santuario de Remulos. $b$bLleva el colgante completo a Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.", st = "En tu segunda prueba debes encontrar las dos mitades del colgante del león marino. Una obtiene su poder de la agilidad del león marino cuando se desliza en el agua, la otra lo obtiene de su increíble capacidad de resistencia. Los druidas se alimentan de ambos rasgos para asumir su forma acuática.$B$BHabla con la gente de Claro de la Luna para averiguar dónde están las mitades y tráemelas para que las unamos. Luego llevarás el colgante a Dendrita Rafagaestelar.", t = "La prueba del león marino"},
    [273] = {ot = "Habla con Huldar.", st = "Pero aún hay tiempo, ayúdanos a buscar a Huldar. No puede estar muy lejos; aunque son fuertes, no creo que Miran y Saean puedan ir muy rápido cargando con esos barriles.$B$BEstán siguiendo la ruta normal, hacia el sur y siguiendo la curva de Loch Modan.$B$BSi todavía no han llegado, los encontrarás.", t = "Aprovisionar la excavación"},
    [275] = {ot = "Mata a 12 trepadores del pantano y regresa con Rethiel el Guardaverde en Los Humedales.", st = "No sé la causa, pero una auténtica podredumbre está creciendo en Los Humedales. Han aparecido trepadores del pantano. Son burbujas enfermas y febriles en el país, y para detener la fiebre deben ser abatidos y devueltos al pantano.$B$BLos trepadores del pantano se arrastran por los canales de Los Humedales.", t = "Ampollas en la tierra"},
    [276] = {ot = "Mata 15 gnolls Pellejomusgo y 10 bastardos Pellejomusgo y regresa con Rethiel el Guardaverde en Los Humedales.", st = "Los gnolls Pellejomusgo han vivido en paz en Los Humedales durante mucho tiempo, pero ahora se están multiplicando. Sus pies pisotean las flores y arbustos del pantano y sus hachas no dejan de talar árboles para alimentar sus fuegos.$B$BHan dejado de estar en equilibrio con la tierra. Para que sobrevivan Los Humedales, debemos reducir a los gnolls.$B$BMata a 15 gnolls Pellejomusgo y a 10 bastardos Pellejomusgo en el Sur, junto a la puerta enana de Algaz. Cuando lo hayas hecho, vuelve aquí.", t = "Patas sucias"},
    [277] = {ot = "Lleva 9 sílex rudimentarios a Rethiel el Guardaverde.", st = "Los Pellejomusgo están talando los árboles de Los Humedales, y utilizan su carne para darse calor. ¡No seguiré sufriendo este dolor!$B$BArrebata a los Pellejomusgo los sílex rudimentarios que utilizan para hacer fuego. Todos los Pellejomusgo llevan esos sílex rudimentarios, excepto los pequeños gnolls y bastardos Pellejomusgo.", t = "No al fuego"},
    [279] = {ot = "Mata a 12 múrlocs Branquiazul.$B$BMata a Engullidor y coge su cabeza.$B$BLleva la cabeza de Engullidor a Karl Boran en Puerto de Menethil.", st = "Los múrlocs están emergiendo de las profundidades y construyen sus aldeas en la costa. Están acosando a nuestros pescadores y mercaderes, y es necesario detenerlos.$B$BUno de estos múrlocs, Engullidor, anda con otros múrlocs branquiazul y asalta a los mercaderes que pasan por el camino, para después regresar a la seguridad de sus chozas múrloc. Nuestros mercaderes están en peligro y pagaremos para ponerlos a salvo.$B$BEngullidor acecha el río hacia el norte de aquí. Encuéntralo, acaba con los de su especie y tráeme su cabeza.", t = "Zarpas de las profundidades"},
    [281] = {ot = "Busca los cajones y barriles en los campamentos múrloc de la costa.", st = "No hace mucho los múrlocs atacaron una nave de mercaderes, La princesa ciega. Aunque el barco escapó intacto, esas inmundas criaturas sacaron gran parte de su cargamento por la borda, incluida una valiosa estatuilla de Terenas Menethil. Queremos recuperar la estatuilla.$B$BRegistra las casuchas múrloc de la costa en busca de cajones, barriles o cualquier otra evidencia del cargamento perdido. Encuentra la estatuilla y vuelve a verme.", t = "Recuperación de bienes"},
    [282] = {ot = "Habla con el montaraz Thalos.", st = "Tenía intención de enviar a mi aprendiz a que entregara a mi hermano Senir mi informe, pero por mi tranquilidad de espíritu... preferiría confiarlo a manos más seguras. Si es que no te importa, claro.$B$BMmm... tendrás que atravesar el túnel para llegar a Kharanos.$B$BHabla con el montaraz Thalos antes de adentrarte en el túnel. Ahora está infestado de troggs.$B$BSigue la carretera para regresar a Yunquemar y luego ve hacia el este hasta llegar al túnel. Thalos no andará lejos.", t = "Las observaciones de Senir"},
    [284] = {ot = "Busca la Estatuilla de Menethil.", st = "Registras a fondo el grupo de casuchas múrloc y no encuentras ni un rastro de la Estatuilla de Menethil.$B$BTal vez encuentres más pistas en las casuchas del Norte y del Noreste.", t = "La búsqueda continúa"},
    [285] = {ot = "Sigue buscando la Estatuilla de Menethil en las casuchas de los múrlocs.", st = "Este grupo de casuchas de múrloc, tras inspeccionarlo a fondo, no revela nada.$B$BPe... pero estás $gseguro:segura; de que la próxima pista que encuentres será muy fructífera.$B$B¡La Estatuilla de Menethil debe estar en alguna de las casuchas del Norte!", t = "Inspecciona más casuchas"},
    [286] = {ot = "Llévale la estatuilla de Menethil a Karl Boran.", st = "Después de sacar el barril de toda la mugre y abrirlo, descubres una figurilla plateada empaquetada entre paja. Representa a un joven paladín de pelo largo, con un martillo alzado.$B$B¡Tiene que ser la Estatuilla de Menethil! Debes regresar con Karl Boran en el Puerto de Menethil.", t = "Devuelve la Estatuilla"},
    [287] = {ot = "Explora el Poblado Peloescarcha y mata a 5 rebanacabezas Peloescarcha para Senir Barbablanca de Kharanos.", st = "Llevo mucho retraso con mi informe y me vendría bien tu ayuda, $n. Conseguí averiguar dónde se esconden los trols, pero vi tantos de ellos que me dio miedo entrar.$B$BPor eso... necesito que entres en la cueva, eches un vistazo y mates a algunos de los trols. Luego vuelves aquí.$B$BSigue la carretera norte que sale de Kharanos, cuando llegues al puente, sigue el río helado hacia el oeste hasta que llegues al Lago Glacial. En la orilla oeste encontrarás Las Birras. La cueva está al suroeste del poblado.", t = "Poblado Peloescarcha"},
    [288] = {ot = "Compra un cántaro de hidromiel para el contramaestre Fistimos.", st = "En su día fui contramaestre del Dueña de las olas, una nave de alto bordo de la Tercera Flota de Kul Tiras. La flota maldita. Maldita, porque en su último viaje fue atacada por dragones rojos. ¡Dragones controlados por orcos!$B$BNo teníamos ninguna oportunidad contra el fuego de los dragones... y nuestra flota ardió y se hundió en esta costa. Soy el único superviviente de todas esas desgraciadas naves...$B$B... ¡Oh, me va a estallar la cabeza! Tengo que beber algo fresco si quiero acabar con esta resaca y seguir con mi historia.", t = "La Tercera Flota"},
    [291] = {ot = "Entrega el informe de Senir al senador Barin Rocarroja de Forjaz.", st = "¡Fantástico! Lleva mi informe al senador Barin Rocarroja. Es un tipo muy agrio; procura que no te contagie su desbordante alegría. Está en Forjaz, en la cámara en la que el rey Magni celebra sus audiencias.$B$B¿Que no sabes llegar a Forjaz? Sigue la carretera norte que sale de Kharanos, cruza el puente, sigue el camino del este que verás bordeado de estandartes, y que sube por la ladera de la montaña.$B$BPor cierto... ¿podrías no mencionar eso de que me has ayudado? No me gustaría que pensaran que no trabajo duro, ya me entiendes.", t = "Los informes"},
    [294] = {ot = "Ormer Trenzaferro de la Excavación de Whelgar quiere que mates 10 estridadores jaspeados y 10 raptores jaspeados.", st = "La situación es grave, ciertamente. Cuando descubrimos estos huesos acudieron los raptores, atraídos por ellos. Esas bestias inmundas mataron a mis hermanos y nos atraparon a mí, a Merrin y al pobre prospector.$b$bLimpia Los Humedales de esos raptores, $n. Encontrarás raptores jaspeados y estridadores jaspeados al oeste de este risco. Mata 10 ejemplares de cada uno, si puedes.$b$bSerá un buen comienzo para la venganza que he planeado.", t = "La venganza de Ormer"},
    [297] = {ot = "Llévale 8 ídolos de piedra grabados a Magmar Ceñimal.", st = "Hace poco, justo antes de que los troggs emergieran en esta excavación, descubrimos una gran cantidad de extraños ídolos grabados. Pero no tuvimos oportunidad de estudiarlos, ya que poco después del descubrimiento ¡los troggs nos echaron de las ruinas! Y esos ídolos tienen un efecto extraño en ellos. ¡Los vuelven locos!$b$bTráeme 8 ídolos: quiero estudiarlos, ¡y quiero quitárselos a los troggs! Encontrarás los ídolos si buscas a troggs que infestan la zona.", t = "Recoger ídolos"},
    [298] = {ot = "Lleva el informe de Vetaferro a Jern Cornamenta a Thelsamar.", st = "Tengo que enviar un informe a Thelsamar. ¡Eso, e insistir en mi pedido de pólvora! Este es el informe. Llévaselo a Jern Cornamenta, es nuestro contacto en Thelsamar.$B$BNo es un encargo difícil, pero no tengo a nadie más para hacerlo.", t = "Un informe sobre el avance de la excavación"},
    [301] = {ot = "Lleva el informe de Vetaferro al prospector Pico Tormenta.", st = "Necesitamos autorización para llevar más pólvora a Vetaferro. Lleva este informe a la oficina central de la Liga de Expedicionarios, en Forjaz.$B$BAquí tienes el informe. Dáselo al prospector Pico Tormenta y no olvides agacharte en cuanto lo hagas. Pico Tormenta tiene muy mal genio y no le va a gustar lo lento que va Vetaferro.$B$BLo encontrarás en la Asamblea de Expedicionarios.", t = "Informe a Forjaz"},
    [302] = {ot = "Habla con Jern Cornamenta en Thelsamar.", st = "¡Si Vetaferro necesita más pólvora, por Magni que la va a tener! Ya le he enviado la autorización a Jern Cornamenta a Thelsamar. Él preparará el envío para Vetaferro.$B$BY otra cosa: quiero que te ocupes personalmente de que la pólvora llega a su destino. El último envío no llegó, así que mantén los ojos abiertos.", t = "Pólvora para Vetaferro"},
    [303] = {ot = "Motley Garmason en Dun Modr quiere que mates 15 enanos Hierro Negro, 5 tuneladores Hierro Negro, 5 saboteadores Hierro Negro y 5 demoledores Hierro Negro.", st = "La guerra se desata aquí y en el exterior. Mientras los poderosos soldados enanos dan sus vidas en territorios lejanos en nombre de la Alianza, nuestra propia tierra es víctima de los actos malignos de los enanos Hierro Negro. Arrasaron con el Puente Thandol. Dun Modr cayó poco después.$b$bNecesitamos que reúnas fuerzas y muevas el frente de batalla. Si puedes matar 15 enanos Hierro Negro, 5 tuneladores, 5 saboteadores y 5 demoledores, puede que la reserva llegue a tiempo para terminar la campaña.$b$bAhora, ¡date prisa!", t = "La guerra contra los Hierro Negro"},
    [305] = {ot = "Tarrel Tejepiedra quiere que viajes a la Excavación y que contactes con Merrin Tejepiedra.", st = "No puedes imaginar lo preocupado que he estado.$b$bDurante un mes, mi mujer, Merrin, me ha estado enviando cartas cada semana. Forma parte del equipo de la Excavación de Whelgar, pero hace casi dos semanas que he dejado de recibir sus cartas. ¡Seguro que algo va mal!$b$bLargatrenza dijo que si no recibíamos noticias del equipo enviaría a un explorador para comprobar cómo va todo. Supongo que tú eres $gese explorador:esa exploradora;, $n. ¡Busca a Merrin en la excavación, al este!", t = "La búsqueda del equipo de excavación"},
    [306] = {ot = "Regresa con Tarrel Tejepiedra y entrégale la nota de Merrin.", st = "¡Fue horrible! Estábamos desenterrando unos extraños artefactos cuando dimos con estos grandes huesos.$b$bAntes de poder saber qué sucedía, los raptores jaspeados inundaron la excavación. Se perdieron muchas vidas.$b$bOrmer... tan valiente... nos salvó al prospector y a mí. Nos defendió mientras corríamos a buscar refugio. Ahora estamos atrapados y todo nuestro trabajo está perdido.$b$bToma, lleva esta nota a mi querido Tarrel. En ella le explico cuál es nuestra situación.", t = "La búsqueda del equipo de excavación"},
    [307] = {ot = "Dirígete a la Mina de Fuenteplata y recoge 4 cargas de equipamiento de minero.$B$BRegresa con el montaraz Pico Tormenta.", st = "La Mina de Fuenteplata, al este de aquí, se secó hace mucho tiempo. La Liga de Mineros la convirtió en un depósito, pero los kóbolds se han instalado allí y están poniendo sus sucias patas encima de las confiables herramientas de los enanos.$b$bPronto expulsaremos a esas ratas, pero la Liga quiere que alguien saque el equipamiento de la mina antes de que los guerreros lo pisoteen y lo destruyan. Será una expedición difícil, tal vez quieras llevar compañía.$b$bEl equipamiento está almacenado en cajones de la Liga de Mineros por toda la mina. Buena suerte.", t = "Zarpas asquerosas"},
    [308] = {t = "Distraer a Jarven"},
    [309] = {ot = "Asegúrate de que Miran y el cargamento lleguen al sitio de excavación; luego infórmale al Prospector Vetaferro.", st = "¿Todo listo para partir, $n?$b$bPrimero, necesitamos llevar esta pólvora a Vetaferro. Será mucho para que cargue yo solo, y estas partes pueden ser peligrosas... Además, quién sabe qué clase de sorpresas puedan tener los Hierro Negro para mí.$b$bMe sentiré mucho mejor si me acompañas.", t = "Proteger el envío"},
    [310] = {ot = "Ve al sótano de la Destilería Cebatruenos de Kharanos y sustituye un barril de cerveza del Trueno con uno de brebaje de Cebadiz.", st = "Tengo que reconocer que esos Cebatruenos preparan unas bebidas estupendas. ¡Pero hay que bajarles los humos! ¡La suya no es la única bebida decente del mundo! Quizás tú puedas ayudarme a darles una lección...$B$BTen, coge este barril de brebaje de Cebadiz. Cuélate en el sótano de la Destilería Cebatruenos de Kharanos y cámbialo por uno de sus barriles de Cerveza del Trueno. ¡Y ya veremos qué brebaje les gusta más a los clientes!$B$BY si encuentras guardias vigilando los barriles, intenta distraerlos...", t = "Rivales acérrimos"},
    [311] = {ot = "Lleva el barril de cerveza del Trueno a Marleth Cebadiz a Las Birras.", st = "Ya has dejado el barril del brebaje de Marleth en el almacén de la destilería de Kharanos y recoges un barril de Cerveza del Trueno como prueba de que has cumplido...", t = "Regresa junto a Marleth"},
    [312] = {ot = "Ve a la cueva del Viejo Barbahielo y recupera la carne seca de Tundra MacGrann de la caja fuerte robada.", st = "Tenía carne seca para un mes, salada y bien guardada para la estación fría. ¡Estaba bajo llave para que los osos no se la comieran! Pero cuando salí a cazar ciervos, esa bestia, el Viejo Barbahielo, se las arregló para romper la cerradura. Eso sí, no podrá con el torio, seguro. Claro que yo me moriré de hambre si no recupero mi carne.$B$BSeguro que tú te mueves con más sigilo que yo. ¿No podrías ir a recuperar mi alijo? Con esta pierna coja no conseguiré entrar y salir de esa cueva con suficiente rapidez.", t = "La reserva robada de Tundra MacGrann"},
    [313] = {ot = "Recoge 8 crines de wendigo y llévaselas al piloto Roscapiedra.", st = "Conducir una máquina de asedio no es para cualquiera. Necesitas brazos de hierro y nervios de acero... ¡por suerte, yo tengo todo eso! ¿Y tú? ¿Crees estar a la altura? ¿Quieres demostrármelo?$B$BBien... Quiero hacer mi máquina, Potenciatrol, un poco más cómoda. ¿Me traerías unas cuantas crines de wendigo del Cubil Pardo, al oeste de Kharanos? ¡Esas crines serían fantásticas como alfombra para la cubierta interna de mi máquina!", t = "El Cubil Pardo"},
    [314] = {ot = "Rudra Semperámbar quiere que mates a Vagash y le lleves su colmillo a la granja de carneros.", st = "Oímos los gritos en medio de la noche. Y esta mañana faltaban dos cabezas de ganado. Esa ruin bestia conocida como Vagash ha estado alimentándose de nuestro sustento. Como la mayor parte del ejército del rey Magni está luchando con la Alianza en tierras distantes, no queda nadie para mantener a raya a Vagash.$B$BQuizás tú tengas el valor necesario para buscar a esa bestia y matarla. Tráeme uno de sus colmillos y te daré una recompensa. Vagash acecha desde encima de este rancho. Ten cuidado, es muy peligroso.", t = "La protección del rebaño"},
    [315] = {ot = "Llévale 6 cardaluz a Rejold Cebadiz en Las Birras.", st = "Tengo una misión. Mi misión consiste en conseguir la cerveza perfecta. Sé que puedo hacerlo, llevo la cebada en la sangre. Solo tengo que encontrar la receta adecuada...$B$BLos trols Peloescarcha cultivan una planta llamada cardaluz en lo alto de las colinas al este. La utilizan para rituales extraños y tribales. Nosotros los enanos casi no la usamos, pero tiene un sabor único... ¡y quisiera experimentar con ella en mis cervezas!$B$BTráeme algunas muestras de cardaluz de los videntes Peloescarcha, o quítaselas a los trols de sus cestas de cardaluz.", t = "La cerveza perfecta"},
    [317] = {ot = "Reúne 4 trozos de carne de jabalí y 2 pelajes de oso grueso y llévaselas al piloto Bramiz al Almacén de Brasacerada.", st = "Me estoy preparando para empezar una misión para la Brigada de Asedio. Es una misión larga y tengo que cargar un mes de suministros en mi reactor a vapor. Así que, mientras Brasacerada trabaja en mi tanque, quizás podrías ir de caza por mí...$B$BNecesito pieles para hacerme una cama y carne para comer. Puedes cazar jabalíes para la carne y osos para las pieles... ve a los campos nevados que hay al sur de El Cubil Pardo.", t = "Los suministros del reactor a vapor"},
    [318] = {ot = "Consigue un tonel de tajada de Rejold Cebadiz de Las Birras.", st = "Rejold Cebadiz experimenta con sus brebajes. Algunos saben bien, otros mal y otros... bueno, esos tumbarían al enano más fuerte.$B$BVive en Las Birras, al oeste de Kharanos. Y lo que quiero es una de sus bebidas: tajada. Me mantendrá caliente en los caminos más fríos.$B$BY... ¡ese bendito líquido quema tanto que también puedo usarlo para aumentar la potencia de mi reactor a vapor! Me ha sacado de un apuro más de una vez.", t = "La tajada"},
    [319] = {ot = "Mata a 6 osos zarpahelada, 8 jabalíes del risco mayores y 8 leopardos de la nieve y luego vuelve a Las Birras con Rejold Cebadiz.", st = "Tengo un tonel de tajada, pero... ¿podrías hacerme un favor? En Las Birras vendría bien un poco de ayuda con los animales salvajes que deambulan por las nieves de los alrededores. A veces se acercan demasiado.$B$BNo es que tengamos miedo de los osos, los gatos ni los jabalíes... ningún enano que se precie lo tiene. Pero si tú pudieras ocuparte de esos animales, tendríamos más tiempo para trabajar y hacer cerveza.", t = "Un favor a cambio de un barril de tajada"},
    [320] = {ot = "Entrega el tonel de tajada al piloto Bramiz en el Almacén de Brasacerada.", st = "Aquí tienes tu tonel de tajada, $n. Y, una vez más, gracias por la caza.", t = "Regresa junto a Bramiz"},
    [323] = {ot = "Mata a 15 asaltantes esqueléticos, 3 sanadores esqueléticos y 3 depositarios esqueléticos y vuelve a donde Sven.", st = "Morbent Vil es un nigromántico y un aliado de los Jinetes Oscuros. Te enfrentaría al poder de Morbent Vil, pero no te enviaré a luchar contra ese demonio sin conocer tu fuerza.$B$BYa me has probado tu valentía pero, si de verdad quieres enfrentarte al nigromántico, tendrás que probar primero que puedes derrotar a sus esbirros.", t = "Pon a prueba tu valor"},
    [337] = {ot = "Devuelve el libro: La Historia de Ventormenta a La Biblioteca de Ventormenta.", st = "Aunque la cubierta de este libro está llena de arañazos y de barro, aún se pueden leer las palabras del lomo: La Historia de Ventormenta. Al abrir el libro se ve claramente el sello de la biblioteca de Ventormenta en la primera página.$B$BParece que alguien sacó este libro y no lo llegó a devolver...", t = "Un libro viejo de Historia"},
    [343] = {ot = "Ve al Archivo Real en el Castillo de Ventormenta y habla con Milton Gavilla. Podrá encontrar el libro sobre metalurgia que el hermano Kristoff necesita para su charla.", st = "Voy a dar un discurso sobre la fortaleza de espíritu y me gustaría recitar unos pasajes de un libro sobre metalurgia, \"La tensión del hierro\". En el Archivo Real, en el Castillo de Ventormenta debería haber una copia del libro. ¿Podrías ir a buscarlo para mí? Si lo haces, ¡que las bendiciones de la Luz te acompañen!$B$BEl Archivo Real es enorme, pero el bibliotecario jefe, Milton Gavilla, conoce todas las estanterías como la palma de su mano. Habla con él, te dará el libro.", t = "Hablando de entereza"},
    [344] = {ot = "Habla con el hermano Paxton en la Abadía de Villanorte.", st = "¿La tensión del hierro? Sí, conozco el libro. Es bastante bueno, lo escribió el minero enano Margulf Blaggon hace unas décadas. Pasó la mayor parte de su vida en las profundidades de Khaz Modan, extrayendo minerales. ¡Un tipo listo!$B$B¿Por dónde iba? ¡Oh, sí, La tensión del hierro! Me temo que el libro se llevó a la Abadía de Villanorte. El custodio de la biblioteca de la Abadía, el hermano Paxton, quería hacer una copia del libro para su biblioteca.$B$BPero eso fue hace meses. Me pregunto por qué estará tardando tanto...", t = "Hermano Paxton"},
    [345] = {ot = "Habla con el supervisor Olento en Villa del Lago y pregúntale sobre el mineral de hierro de Rethban.", st = "He intentado terminar mi ejemplar de Tensiones del hierro, pero...$B$BBueno, verás, hago mi propia tinta para los libros que copio. Es mi fórmula personal: no se corre ni mancha, y se seca muy rápido. Lamentablemente, ¡se seca demasiado rápido! Mi último lote se secó antes de que pudiera terminar la copia, y no he tenido tiempo para preparar más tinta.$B$BPara eso necesito menas de hierro de Rethban de las Montañas Crestagrana. El supervisor Olento de Villa del Lago es mi proveedor habitual.", t = "Suministros de tinta"},
    [346] = {ot = "Vuelve a hablar con el hermano Kristoff en la Plaza de la Catedral. Entrégale el libro La tensión del hierro.", st = "Ahora que he terminado de copiar el libro, aquí tienes el original de La tensión del hierro. Gracias por tu paciencia y, si ves a Milton, por favor, dile que siento haberme retrasado tanto.", t = "Regresa junto a Kristoff"},
    [347] = {ot = "Reúne 5 montones de mineral de hierro de Rethban y llévaselos al hermano Paxton en la biblioteca de Villanorte.", st = "La mena de Rethban tiene ese nombre por el hombre que lo descubrió, Bart Rethban. Cuando se funde, no es tan fuerte como el hierro, pero tiene un color oscuro que algunos escribas utilizan en sus tintes. Se puede encontrar en las Cavernas de Rethban, al norte de aquí.$B$BGeneralmente lo tenemos almacenado, pero estamos demasiado ocupados preparándonos para los atacantes orcos que no hemos tenido tiempo de recogerlo. Y, además, los gnolls de Crestagrana viven ahora en las Cavernas de Rethban y sus esclavos se encargan de recoger el mineral.$B$BAsí que si necesitas recogerlo, tendrás que ir a por él.", t = "La mena de Rethban"},
    [350] = {ot = "Habla con Elling Trias en Ventormenta.", st = "Ese Marzon tenía que contactar con un miembro de los Defias y llegar a un acuerdo con Lescovar...$B$BCon VanCleef y Thredd muertos, no sería fácil llevar a Lescovar ante la justicia, ya que las pruebas no sirven de nada sin sus testimonios. Y eso, sin considerar que Lescovar es un noble, y está muy bien conectado. Efectivamente, eso hace que esté por encima de la ley.$B$BVas a necesitar más ayuda. Odio hacer esto, pero conozco a alguien que nos ayudará. Busca a Trias en el Distrito de Mercaderes de la ciudad.", t = "Mira por un viejo amigo"},
    [353] = {ot = "Entrega el paquete Pico Tormenta al montaraz Pico Tormenta en Loch Modan.", st = "Los Pico Tormenta son unos enanos muy respetados y famosos por su exigente gusto. Así que no es sorprendente que Gringer Pico Tormenta, un montaraz de Forjaz, me encargara que forjara un arma para él.$B$BHe terminado el arma, pero... el montaraz Pico Tormenta está muy lejos, en Loch Modan. Si tienes planeado viajar al norte, ¿podrías entregarle este paquete?$B$BEl último mensaje que recibí del montaraz Pico Tormenta, decía que estaba estacionado en la torre de vigilancia del norte, en Loch Modan.", t = "Una entrega a Pico Tormenta"},
    [354] = {ot = "Llévale los restos de Gregor, los restos de Nissa y los restos de Thurman a Coleman Farthing, que está en Rémol.", st = "Los Agamand eran una de las familias más prósperas de los Claros de Tirisfal. Yo solía trabajar en sus molinos... antes de la Peste.$B$BCuando la Plaga apareció por primera vez, los Agamand fortificaron su casa y convencieron a todos sus empleados para que se quedaran y les ayudaran a defenderse. Fuimos unos insensatos pero, al menos, fuimos unos insensatos leales.$B$BLos Agamand, a causa de su orgullo, nos abocaron a todos a la desgracia. ¡Y ahora son esbirros de la Plaga!$B$BSirve a los Renegados y derrota a los Agamand, que sucumbieron a la peste. Sírveme a mí y tráeme sus restos.", t = "Muertes en la familia"},
    [355] = {ot = "Habla con el magistrado Sevren de Rémol.", st = "Me has entregado los restos de los Agamand y con ello, has satisfecho mis deseos de venganza. Pero los Molinos de Agamand encierran una amenaza para todos los Renegados, no solo para mí.$B$BHe informado al magistrado Sevren acerca de tus hazañas contra los Agamand y desea hablar contigo.", t = "Habla con Sevren"},
    [356] = {ot = "Mata 8 horrores sangrantes y 8 espíritus deambulantes, y preséntate ante Linnea en su campamento.", st = "Los defensores que están en el Baluarte y protegen Tirisfal de las Tierras de la Peste están en alerta constante. Pero en ocasiones, algunos integrantes de la Plaga logran infiltrarse.$B$BEl éxito en El Baluarte depende de una batalla de un solo frente. No podemos permitir que nos ataquen por la retaguardia ni que interrumpan la línea de suministros de nuestros defensores.$B$BAyuda al Baluarte. Patrulla hacia el este y mata a todos los monstruos de la Plaga que encuentres. Préstale especial atención a la Hacienda Balnir que está al este. Se ha convertido en un refugio para los intrusos de la Plaga.", t = "Patrulla de la retaguardia"},
    [357] = {ot = "Llévale el libro de hechizos del exánime a Bethor Duroyelo en Entrañas.", st = "Hay un exánime que mora en la isla Lago Aguasclaras, en el norte. Aunque es un Renegado independiente, cree que los otros no-muertos son esclavos de la Plaga por lo que sus esbirros atacan a todo aquel que se acerca a él.$B$BPero, dado que es un Renegado, la Reina lo reclama. Y si tiene conocimientos de nigromancia, estos serán... muy útiles para nosotros.$B$BPara descubrir su identidad y talentos, debo ver su libro de hechizos. Irrumpe en su campamento, róbalo y tráemelo aquí.", t = "La identidad del exánime"},
    [358] = {ot = "Mata a los asaltatumbas Putrepellejo y a los bastardos Putrepellejo. $B$BLlévale 8 icores embalsamantes al magistrado Sevren de Rémol.", st = "Las fosas comunes, al suroeste de la Granja de Garren situada hacia el norte de aquí, se hicieron para albergar la impresionante cantidad de cadáveres de aquellos que perecieron en Tirisfal cuando la Peste golpeó por primera vez.$B$BDe estas tumbas no había salido ni un solo no-muerto hasta el momento, pero ahora la Plaga envía a gnolls Putrepellejo a recoger cadáveres para que engrosen las filas de sus ejércitos. ¡Esto es inaceptable!$B$BTienes una doble tarea que cumplir: mata a los Putrepellejo de las fosas comunes y la Granja de Garren, y quítales el icor embalsamante que les da vida.", t = "Profanadores"},
    [359] = {ot = "Habla con la guardia de la muerte Linnea.", st = "Necesito conocer las últimas noticias de nuestro puesto del Guardia de la Muerte situado al este de aquí.$B$BTengo que saber si las fuerzas de la Plaga han pasado por El Baluarte y han entrado en Tirisfal. Debemos mantener la vigilancia en la frontera con las Tierras de la Peste pues no podemos permitir que la Plaga afiance su presencia aquí.$B$BViaja hacia el sur siguiendo el camino y cuando este se bifurque, continúa en dirección este hasta el puesto. Habla con la Guardia de la Muerte Linnea. Ella tiene la información que necesito.", t = "Las obligaciones de los Renegados"},
    [360] = {ot = "Ve a ver de nuevo al magistrado Sevren de Rémol.", st = "Ahora llévale la información que te he dado al magistrado Sevren. Le gustará recibirla lo antes posible así que date prisa.$B$BY si ves a algún miembro de la Plaga por el camino, acaba con él. No podemos permitir que vaguen por nuestras tierras a su antojo.", t = "Regresa junto al magistrado"},
    [361] = {ot = "Encuentra a Yvette Farthing y entrégale la carta de Thurman Agamand.", st = "Esta carta la escribió Thurman, el hijo mayor de Gregor Agamand. Está dirigida a una tal Yvette Farthing, aunque parece que nunca llegó a recibirla...", t = "Una carta sin entregar"},
    [362] = {ot = "Acaba con Devlin Agamand y llévale los restos de Devlin a Coleman Farthing en Rémol.", st = "Devlin Agamand era el más joven de los dos hijos de la familia Agamand y en vida ambos no podían ser más diferentes. Thurman era alto y amable mientras que su hermano pequeño era débil y tenía la lengua muy afilada.$B$BCuando la Peste llegó a los Molinos de Agamand, no me sorprendió de que Devlin sucumbiera casi de inmediato. Sus desbarres todavía pueden oírse cerca del camino que conduce a los Molinos de Agamand.$B$BEstoy recogiendo lo que queda de los Agamand y quiero al pobre Devlin. Encuéntralo, acaba con él y tráeme sus huesos.", t = "Los molinos fantasma"},
    [363] = {ot = "Habla con el sacerdote de las Sombras Sarvis.", st = "Era hora de que despertaras. Ya estábamos listos para arrojarte al fuego con los demás, pero parece que lo lograste.$b$bSoy Mordo, el cuidador de la cripta de Camposanto. Y tú ya no eres $Gesclavo:esclava; del Rey Exánime.$b$bHabla con el sacerdote de las sombras Sarvis en la capilla que está en la base de la colina, él te contará más sobre lo que debes saber.", t = "Desvelo brutal"},
    [364] = {ot = "El sacerdote de las sombras Sarvis quiere que mates 8 zombis descerebrados y 8 zombis espantosos.", st = "Los Renegados estamos en guerra con el ejército de la Plaga del Rey Exánime: ejércitos de no-muertos, bestias asquerosas del norte y espectros atormentados, todos resucitados con nigromancia.$b$bLa parte norte del pueblo ha sido arrasada por autómatas y debemos destruirlos. Acaba con ellos, no les tengas piedad, aunque hayan sido nuestros hermanos y hermanas. Los caídos no son más que esclavos del Rey Exánime.", t = "Los autómatas"},
    [365] = {ot = "Roba 10 calabazas de la plantación que encontrarás en dirección oeste, justo al norte de Camposanto, y llévaselas al boticario Johaan a Rémol.", st = "¿Qué tenemos aquí? Pareces un poco $gnovato:novata;, $c. Si quieres demostrar tu valía a la Dama Oscura, tendrás que aprender los caminos de los Renegados.$B$BEncontrarás una plantación en dirección oeste. Los humanos infestan la tierra al igual que el moho un cuerpo en descomposición. Y lo que es peor, la Cruzada Escarlata vigila la zona desde su torre. Dales una lección a esos canallas y roba 10 de sus preciadas calabazas.$B$BCuando tengas 10, llévaselas al boticario Johaan a Rémol.", t = "Campos de pena"},
    [366] = {ot = "Devuélvele el libro de hechizos de Gunther a su dueño, que se encuentra en la isla del Refugio de Gunther.", st = "Hace tiempo, Gunther y yo, junto con el ahora nigromántico de la Plaga Thule Corvozarpa, fuimos amigos y estudiamos juntos en el Kirin Tor (una sociedad de magos de Dalaran).$B$BTanto Gunther como yo sucumbimos a la Peste pero creí que él estaría muerto o sirviendo al Rey Exánime. ¡Es estupendo saber que está libre!$B$BTenemos que conseguir que se una a nosotros. He lanzado un hechizo sobre su libro de forma que, cuando lo vea, sepa que yo también estoy libre del Rey Exánime. Cuando se entere de esto, espero que se una a nosotros.", t = "Devuelve el libro"},
    [367] = {ot = "El boticario Johaan de Rémol quiere que recojas 5 viales de sangre de can oscuro.", st = "Lady Sylvanas ha recurrido a la Sociedad Real de Boticarios. La Dama Oscura cree que nuestro conocimiento, sumado a la magia recién descubierta, será la clave para derrotar a Arthas. Nos ha instado a idear una nueva peste, una peste mucho más mortífera que cualquier otra dolencia conocida en Azeroth. Esta nueva enfermedad llevará a la ruina al ejército de la Plaga de Arthas.$b$bMis estudios revelan que la clave podría estar en la sangre de las bestias. Tráeme 5 viales de sangre de can oscuro para que pueda comprobar mi teoría.", t = "Una nueva Peste"},
    [368] = {ot = "El boticario Johaan de Rémol necesita 5 escamas de Anca Vil de los múrlocs de los Claros de Tirisfal.", st = "Mientras recogías las muestras, me he dado cuenta gracias a mis experimentos de que serán necesarios más componentes para que esta nueva enfermedad se propague como es debido. Envenenar a unas cuantas víctimas es un juego de niños pero extender una plaga por todo un mundo es algo más complicado.$B$BNecesitaré 5 escamas de Anca Vil de los múrlocs de la zona. Encontrarás a estas criaturas en la costa hacia el norte o el oeste.", t = "Una nueva Peste"},
    [369] = {ot = "El boticario Johaan de Rémol quiere que le lleves 4 muestras de veneno de nocturácnida sañosa.", st = "Mientras recogías lo que te pedí, descubrí un viejo texto en uno de mis tomos que explica cómo una antigua peste arrasó con miles de víctimas inocentes. Más tarde se descubrió que el agente mortal de dicha peste estaba presente en el veneno de las nocturácnidas.$B$BTráeme un poco de veneno de una nocturácnida sañosa para completar este experimento. Quiero comprobar si el elemento contagioso presente en el veneno servirá para mi nuevo brebaje. Se dice que hay muchas arañas en los Claros de Tirisfal del Este.", t = "Una nueva Peste"},
    [370] = {ot = "El ejecutor Zygand de Rémol quiere que mates al capitán Perrine, a 3 zelotes Escarlata y a 3 misioneros Escarlata.", st = "Los documentos del ejecutor Arren contienen exactamente todos los detalles que necesitamos para erradicar la infestación humana de nuestras tierras. De acuerdo con esta información, la Cruzada Escarlata ha enviado al capitán Perrine y a una brigada a las ruinas de la torre situada al suroeste de Rémol.$B$BMata a Perrine, a 3 zelotes y a 3 misioneros y regresa aquí.", t = "En guerra con la Cruzada Escarlata"},
    [371] = {ot = "El ejecutor Zygand de Rémol te ha encargado que mates al capitán Vachon y a 5 frailes Escarlata.", st = "Seguimos en guerra y la Cruzada Escarlata se hace cada vez más fuerte. El informe que el ejecutor Arren me ha enviado indica que la Cruzada Escarlata ha estado atacando desde las ruinas de la torre situada al sudeste de Tirisfal, cerca de la Hacienda Balnir, bajo las órdenes del capitán Vachon.$B$BMata a Vachon y a 5 frailes Escarlata. ¡Será un duro golpe para la Cruzada!", t = "En guerra con la Cruzada Escarlata"},
    [372] = {ot = "El ejecutor Zygand de Rémol quiere que asesines al capitán Melrache y a sus dos guardaespaldas.", st = "La Cruzada Escarlata ha estado atacando desde las ruinas de la torre situada al norte de Tirisfal, más allá de la Tumba de Faol. De acuerdo con los datos que tenemos, están bajo las órdenes del implacable capitán Melrache.$B$BTe voy a confiar una misión tan poco habitual como peligrosa. Mata a Melrache y a sus dos guardaespaldas en nombre de la Dama Oscura.", t = "En guerra con la Cruzada Escarlata"},
    [373] = {ot = "Entrega la carta destinada al arquitecto jefe a Baros Alexston en Ventormenta.", st = "Registrando a Edwin VanCleef descubres, entre otras cosas, una carta sin enviar. Va dirigida a Baros Alexston, el arquitecto jefe de Ventormenta, Ayuntamiento, Plaza de la Catedral.$B$BParece ser que ha sido escrita y sellada recientemente.", t = "La carta sin enviar"},
    [374] = {ot = "Llévale 10 anillos con la insignia escarlata al Guardia de la Muerte Burgess de Rémol.", st = "El ejecutor Zygand me dice que has estado matando a miembros de la Cruzada Escarlata. Los Claros de Tirisfal están plagados de ellos.$B$BVarimathras, teniente de la Dama Oscura, se está encargando personalmente de exterminar a la escoria de Azeroth: la raza de los humanos. Aquí en los Claros de Tirisfal nos enfrentamos a un nuevo género de humanos: la Cruzada Escarlata.$B$BCorre el riesgo y lanza una ofensiva contra la Cruzada Escarlata, $c. Tráeme 10 anillos con la insignia Escarlata como muestra de tu lealtad a Varimathras y a la Dama Oscura.", t = "Prueba de defunción"},
    [375] = {ot = "Llévale 5 pelambres de Murciumbrío y un hilo burdo a Gretchen Dedmar, que está en Rémol.", st = "Tengo tanto frío... La Peste de los no-muertos corre por mis venas como una serpiente de hielo. Pronto me embargará el estado de automatismo pero nada me impedirá que sirva a nuestra Dama Oscura. En su momento yo misma cosí bolsas de cadáveres para los soldados caídos del poderoso ejército de Sylvanas.$B$BPero ahora mis manos tiemblan de frío. Si me trajeras 5 pelambres de Murciumbrío y un hilo burdo, podría coser yo mismo una manta. Ayúdame, $n, para que así pueda seguir sirviendo a la causa.", t = "El frío de la muerte"},
    [376] = {ot = "La novicia Elreth requiere 6 garras de carroñero y 6 alas de murciumbrío.", st = "Mis deberes son atender a nuestros guerreros heridos, suministrar ropa y armaduras y asistir al sacerdote de las Sombras Sarvis en lo que necesite.$B$BParece que tú también vas a acabar a su servicio... dando caza a los autómatas. Seguro, sé cómo piensa. Si quieres seguir de una pieza, que seguro que sí, quizás pueda ayudarte. Me estoy quedando sin patas y alas. Si me traes algunas, te buscaré una armadura. Encontrarás muchos lobos y murciélagos hacia el sur.", t = "Los Malditos"},
    [377] = {ot = "El consejero Tallolino de Villa Oscura quiere que le lleves la mano de Dextren Ward.", st = "Como si no tuviéramos suficiente con la negligencia de los residentes del Bosque del Ocaso, ahora la Casa de Nobles escupe en el ojo al Consejo de Villa Oscura con su decisión de encarcelar a Dextren Ward en Ventormenta en lugar de decapitarlo como establecía la sentencia de Lord Cerranegro.$B$BTutor fue descubierto vendiendo cadáveres del cementerio a Morbent Vil, y ese es un delito que se castiga con la muerte. Y sin embargo, Ventormenta lo reclama como prisionero.$B$BAsesina a Ward en las Mazmorras de Ventormenta. Tráeme su mano y yo te recompensaré.", t = "Crimen y castigo"},
    [378] = {ot = "Motley Garmason quiere que le lleves la cabeza de Kam Furiahonda a Dun Modr.", st = "Has demostrado tu lealtad al rey Magni, $c. Y tu odio por la escoria Hierro Negro es tan grande como el mío.$B$BHay una tarea que me gustaría hacer por mí mismo, pero el honor me obliga a permanecer junto a Largatrenza. Roggo ha conseguido reunir datos que demuestran que Kam Furiahonda fue miembro de la conspiración para el ataque del Puente Thandol. Fueron los planes de Furiahonda los que hicieron perder a Largatrenza a toda su familia.$B$BFuriahonda está retenido, por razones políticas, en las Mazmorras de Ventormenta. Le quiero muerto, $n. ¡Por Largatrenza! ¡Tráeme su cabeza!", t = "La furia mora en las profundidades"},
    [380] = {ot = "El ejecutor Arren quiere que mates 10 nocturánidas jóvenes y 8 arañas nocturánidas.", st = "Obtener los recursos naturales que necesitamos para sobrevivir es una de nuestras luchas más arduas. El oro escaseaba incluso en los tiempos en los que el poder de la Alianza estaba en su cumbre.$B$BHay una mina de oro al noroeste que ha sido invadida por arañas. Necesitamos el oro de esa mina, pero no podemos extraerlo mientras las arañas estén por ahí. No tengo mucho personal para la tarea, así que tendremos que encargarnos de ellas poco a poco.$B$BSube allí y a ver si puedes hacer algo por nosotros, $n.", t = "Hoya Nocturácnidas"},
    [381] = {ot = "Lleva al ejecutor Arren 12 bandas Escarlata de conversos Escarlata y de iniciados Escarlata.", st = "Te alegrará saber que estamos haciendo algunos progresos en la mina, gracias, en gran parte, a tus esfuerzos. Ahora podemos centrarnos en otros problemas.$B$BMis exploradores me han comunicado que un destacamento de la Cruzada Escarlata está estableciendo un campamento al sureste de aquí. La Cruzada Escarlata es una despreciable organización que nos da caza. No descansarán hasta que hayan acabado con todos los no-muertos, sean de la Plaga del Rey Exánime o no. ¡Debemos atacar primero!$B$BTen cuidado, su impuro celo los convierte en adversarios muy peligrosos.", t = "La Cruzada Escarlata"},
    [382] = {ot = "Mata a Meven Korgal, el mensajero, en el campamento de los Cruzados y vuelve a comunicar al ejecutor Arren cualquier información que encuentres.", st = "Los informes que me envían mis superiores desde Rémol indican que un agente de la Cruzada Escarlata fue enviado desde el Monasterio Escarlata hasta el Camposanto. Sabemos que ese mensajero transporta una información muy importante. No tengo más detalles pero, lleve lo que lleve, ¡debemos conseguirlo!$B$BEres la persona más cualificada a la que puedo enviar, $n. Encuentra a ese mensajero y tráeme cualquier información que encuentres.", t = "El mensajero rojo"},
    [383] = {ot = "Ve a Rémol y entrega los documentos de la Cruzada Escarlata al ejecutor Zygand.", st = "Hay que hacer llegar esto a mi superior, el ejecutor Zygand, en Rémol. Con esta información podremos asestar un golpe definitivo a la Cruzada Escarlata. Has sido muy útil en Camposanto, pero necesito que alguien lleve esto a Zygand y además, creo que él podrá asignarte tareas más adecuadas.$B$BCuando salgas de Camposanto, sigue la carretera del norte. Poco después de entrar en Tirisfal, encontrarás un cruce. Toma el sendero del este y sigue en esa dirección. En tu camino pasarás por la Mansión Fríogar.", t = "Información decisiva"},
    [384] = {ot = "Ragnar Cebatruenos de Kharanos quiere 6 costillas de jabalí del risco y una jarra de malta rapsódica.", st = "¡Nada les gusta más a mis clientes que unas ricas costillas de jabalí a la cerveza! El problema es que el trampero local que solía traerme los suministros se ha alistado en el ejército del rey para ayudar en el frente de la Alianza.$B$BQuizás tú puedas ayudarme... Si me traes seis costillas de jabalí montés y una malta rapsódica de la taberna, compartiré contigo la receta familiar de mis famosas costillas de jabalí a la cerveza. ¡Y te daré una muestra gratis! ¡El secreto está en la malta!", t = "Costillas de jabalí a la cerveza"},
    [385] = {ot = "Lleva 5 piezas de carne de crocolisco y 6 pieles de crocolisco a Marek Coracero, en la Cabaña del Errante.", st = "Vienen muchos cazadores a Loch Modan por los crocoliscos. Los mercaderes compran pieles de crocolisco para hacer ropa y armaduras, e incluso hay a quien le gusta su carne.$B$BHacemos negocio, pero no mucho, porque esos bichos son muy feroces y se esconden en las islas del lago. Pero tú no te prives, enfrentarse a esos dientes es toda una experiencia.$B$BMe acuerdo de una vez que...", t = "La caza de crocoliscos"},
    [386] = {ot = "Lleva la cabeza de Targorr el Pavoroso al guardia Berton a Villa del Lago.", st = "Targorr el Pavoroso sirvió bajo las órdenes de Gath'llzogg como Verdugo supremo. Sus métodos eran los más despiadados, incluso para los orcos. No dudó en torturar a hombres que habían servido lealmente en la defensa del Reino. Ahora se encuentra recluso en las Mazmorras de Ventormenta, a la espera de que se cumpla su sentencia de muerte. Aun así, hay algo que no encaja. Uno de los nobles burócratas ha detenido su ejecución. Seguro que se trata de una maniobra oscura.$B$BTienes que acabar con Targorr el Pavoroso, $n. Viaja a Las Mazmorras y decapítalo antes de que logre escapar a su destino.", t = "Lo que sucede alrededor..."},
    [387] = {ot = "El celador Thelagua de Ventormenta quiere que mates 10 prisioneros Defias, 8 presidiarios Defias y 8 insurgentes Defias en Las Mazmorras.", st = "¡Hay que detener el motín! Necesito tu ayuda. ¡Si alguien se entera de que la prisión es un caos perderé mi trabajo! Esto es juego sucio. Pero lo importante es obligar a los prisioneros a rendirse, por la seguridad de Ventormenta.$B$BEl castigo por sublevación es la muerte. Mata a alguno de esos desviados. Y verás cómo vuelven al buen camino...", t = "Detener el motín"},
    [388] = {ot = "Nikova Raskol, de Ventormenta, quiere que consigas 10 pañuelos de lana roja.", st = "El resentimiento corre por mis venas como una corriente fría. Mi nieto, Mac, era un chico muy bueno. 14 años recién cumplidos. Cuando el ejército fue mandado al frente, Mac cogió las armas para defender la ciudad. Fue un guardia de Las Mazmorras, donde está encerrada la banda Defias. Mac reprendió a algunos de los prisioneros por romper sus mantas de lana para hacer bufandas, un símbolo de la banda. Por hacerlo, recibió una puñalada en la espalda.$B$BQuiero venganza. Tráeme 10 de sus valiosos pañuelos de lana. Son del color de la sangre.", t = "El color de la sangre"},
    [389] = {ot = "Habla con el celador Thelagua en las Mazmorras.", st = "VanCleef y yo fuimos miembros de la Hermandad de los Albañiles. Nuestro primer proyecto después de la Guerra era reconstruir Ventormenta.$B$BCuando terminamos, nos estafaron. Los nobles se negaron a pagarnos. A algunos de los Albañiles mayores les ofrecieron trabajos gubernamentales, pero VanCleef y yo los rechazamos debido a nuestra lealtad con los Albañiles. Él lideró un motín y abandonó la ciudad, jurando venganza.$B$BEs posible que su teniente, Bazil Thredd, sepa más sobre los planes de VanCleef. Está prisionero en las Mazmorras.", t = "Bazil Thredd"},
    [391] = {ot = "Mata a Bazil Thredd y lleva su cabeza al celador Thelagua en las Mazmorras.", st = "Dejemos esto claro, $n. No confío en ti. Pero en estas circunstancias, tendré que pasarlo por alto.$B$BEsto es lo que vamos a hacer: baja ahí y habla con Thredd. Si realmente estás de nuestra parte, mátale y tráeme su cabeza como prueba. Si descubrimos que estás de su parte, cuando te encontremos... morirás junto con el resto de esos gusanos.", t = "El motín de Las Mazmorras"},
    [392] = {ot = "Lleva la descripción del visitante de Thredd lacrada a Baros Alexston en Ventormenta.", st = "Durante los primeros años del encarcelamiento de Thredd, nunca recibió visitas. Supuse que ya no resultaba útil para la Hermandad y que le habían abandonado.$B$BEn fin, hace unos meses, todo cambió. Comenzó a recibir visitas regularmente... una, o quizás dos veces por semana. Era un hombre extraño... un tipo tranquilo. Tenía sospechas, pero sus papeles estaban en regla.$B$BEn los documentos venía que su nombre era Maelik; esta es su descripción. No creo que venga a visitar más a Thredd.", t = "Extraño visitante"},
    [393] = {ot = "Lleva la descripción del visitante de Thredd lacrada al maestro Mathias Shaw en Ventormenta.", st = "No tengo ni idea, $n. Hay alguien más que quizás pueda ayudarte y resulta que me debe un favor por... bueno, no hace falta entrar en detalles. En los cuarteles del Casco Antiguo, puedes encontrar al maestro Mathias Shaw del IV:7. Shaw está metido en la mayor parte de los negocios sucios o turbios de la ciudad.$B$BSi alguien puede saberlo, es él.", t = "Sombras del pasado"},
    [394] = {ot = "Habla con Mathias Shaw en Ventormenta.", st = "Encuentra a Shaw en el Casco Antiguo. Dile que nos hemos encargado de la amenaza de Lescovar y cuéntale lo de tu participación en los planes del señor contra la ciudad. Seguro que se sentirá orgulloso de tener a otro héroe entre los ciudadanos de Ventormenta.$B$BLo más probable es que te envíe a ver al príncipe o a otro noble. Pero que no se te suba a la cabeza, $n. Los nobles pueden creer que gobiernan la ciudad, pero hay algunas cosas que se les escapan de las manos.", t = "La cabeza de la bestia"},
    [395] = {ot = "Habla con Baros Alexston en Ventormenta.", st = "¡Ah, casi lo olvidaba! Alexston vino cuando no estabas, quería hablar contigo. Sin duda quiere informar a los nobles de los tejemanejes de la Hermandad Defias.$B$BUn pequeño consejo, $n: si alguien te pregunta, da todos los detalles, menos que fue tu mano la que mató a Lescovar. Confía en mí. Sé cómo van esas cosas...$B$BY, con respecto a Trias, bueno, si puedes evitarlo, nunca jamás hables de él con nadie.", t = "El fin de la Hermandad"},
    [396] = {ot = "Lleva el informe de Baros Alexston sobre la Hermandad Defias al rey Varian Wrynn en el Castillo de Ventormenta.", st = "He preparado un informe para el rey. Creo que tú deberías entregárselo, junto con un resumen de tus descubrimientos. No te preocupes, sin duda te elogiará por hacer tu deber con el pueblo de Ventormenta.$B$BTu audiencia comenzará pronto, así que será mejor que te des prisa, todavía te queda un buen tramo hasta el Castillo de Ventormenta.", t = "Una audiencia con el Rey"},
    [398] = {ot = "Mata a Ojo de cresa y llévale su garra al ejecutor Zygand de Rémol para obtener una recompensa.", st = "Se busca: ¡Ojo de cresa!$B$BConsiderado una bestia incluso entre los propios gnolls, Ojo de cresa ha sido sentenciado a muerte por sus crímenes en contra de los Renegados. Este infame villano ha estado robando cuerpos y poniéndolos a disposición del ejército del Rey Exánime. Ojo de cresa fue visto por última vez saqueando las tierras situadas en las proximidades de la Granja de Garren, al norte de Rémol.$B$BA partir de este momento, la ciudad de Rémol ofrece una recompensa al que sea capaz de llevar a cabo su ejecución. Muéstrale al ejecutor Zygand la garra del villano una vez ejecutada la sentencia.$B$BLa clemencia queda relegada a los débiles.", t = "SE BUSCA: Ojo de cresa"},
    [399] = {ot = "Ve a la casa de Baros Alexston en los Páramos de Poniente y busca su brújula. A continuación, llévasela al Distrito de la Catedral, en Ventormenta.", st = "Parece que han pasado siglos desde que era pequeño y trabajaba en la granja de Páramos de Poniente. Dicen que no se puede volver al pasado, y es verdad. En especial para mí, pues unos ladrones quemaron y tomaron el hogar de mi familia.$b$bHablé con mi padre sobre el paradero de mis posesiones, entre ellas mi primera brújula. No pudo recuperarlas. Pero también me ha dicho que deberían estar escondidas en la granja.$b$bEncontrarás la Hacienda de Alexston al oeste de Colina del Centinela. ¿Podrías recuperar mis cosas?", t = "Principios humildes"},
    [400] = {ot = "Entrega las herramientas de Brasacerada a Beldin Brasacerada.", st = "Beldin Brasacerada es el dueño de la tienda de mecánica local y además es el mejor técnico de máquinas de asedio. Pero es implacable con sus herramientas. ¡Te aseguro que rompe más llaves de tuerca arcoluz de las que le podemos suministrar!$B$BAcabamos de completar su último pedido. Si se lo llevas, seguro que te compensa el esfuerzo.$B$BSu tienda, el Almacén de Brasacerada, está al noreste de Kharanos. Y es un lugar en el que se reúnen los pilotos veteranos de máquinas de asedio, así que estate $gatento:atenta; por si oyes algo interesante.", t = "Herramientas para Brasacerada"},
    [404] = {ot = "Llévale 7 garras podridas al Guardia de la Muerte Dillinger de Rémol.", st = "La Plaga ha alcanzado los Claros de Tirisfal y ha infestado el área al oeste de Rémol, cerca del puente viejo.$B$BDirígete allí y enfréntate a los muertos podridos. Trae sus garras podridas y los Guardias de la Muerte te recompensarán.", t = "Una tarea pútrida"},
    [405] = {ot = "Comunícale las órdenes de Sevren a Bethor Duroyelo en Entrañas.", st = "Bethor Duroyelo, un poderoso mago de alto rango de Entrañas, que cae al sur, me ha pedido que le envíe a alguien capaz de hacer frente a la Plaga. Tú, $n, eres $gel elegido:la elegida;.$B$BHázselo saber a Bethor y él te explicará cuál es tu misión. Yo desconozco los detalles pero sé que tiene algo que ver con reclutar a un exánime, y parece peligroso.$B$BPrepárate, $c, pues no debes fallar.$B$BBusca a Bethor en el Barrio de la Magia de Entrañas.", t = "El exánime pródigo"},
    [407] = {ot = "Llévale la calabaza envenenada al zelote Escarlata capturado que está encerrado en el sótano del Mesón La Horca.", st = "¿Simples e inofensivas calabazas, verdad? Eso es lo que deben parecer... Si queremos detener el avance de Arthas por el norte y la infestación humana por el sur, tenemos que comenzar a valorar nuestro propio potencial.$B$BCon un poco de ingenio, una simple calabaza se convierte en un arma de nuestra Dama Oscura. Solo hay que echarle un poco de mi última fórmula.$B$BHan capturado a otro zelote Escarlata y está encerrado en el sótano del Mesón La Horca. Llévale a ese desgraciado esta calabaza.", t = "Campos de pena"},
    [408] = {ot = "Mata a 8 ancestros gemebundos y a 8 ancestros en podredumbre.$B$BMata al capitán Dargol y llévale su calavera al magistrado Sevren de Rémol.", st = "Los miembros de la Plaga han encontrado cobijo en los Molinos de Agamand. El punto más sólido es la Cripta de la Familia Agamand, lugar en el que su líder militar, un esqueleto llamado capitán Dargol, ha establecido su puesto de mando. Por medio de la nigromancia, ha revivido a los ancestros de los Agamand y planea utilizarlos contra nosotros.$B$BEsto no puede ocurrir y tú has de evitarlo. Viaja a la Cripta de la Familia Agamand y derrota a los ancestros de los Agamand.$B$B¡Ah! Y tráeme la calavera del capitán Dargol.", t = "La Cripta de la Familia"},
    [409] = {ot = "Coge una vela de señalización.$B$BDespierta a Lillith Nefala y mátala.$B$BVuelve a ver a Gunther a su isla.", st = "Afirmas que no estás $gsometido:sometida; a la voluntad del Rey Exánime y el encantamiento que Bethor lanzó sobre mi libro lo corrobora. Sin embargo, para que pueda confiar en ti debes darme una prueba de que estás en contra de la Plaga.$B$BHay un viejo altar, a poca distancia de la costa sur de esta isla, que utiliza un poderoso agente de la Plaga llamado Lillith Nefara.$B$BCoge una vela de señalización de este cajón. Enciéndela en el altar y Lillith se despertará. Acaba con Lillith y creeré que en verdad eres $gun enemigo:una enemiga; del Rey Exánime.", t = "Prueba de lealtad"},
    [411] = {ot = "Llévale la gema abisal a Bethor Duroyelo en Entrañas.", st = "Dale esta gema abisal a mi viejo camarada Bethor. A través de ella podremos comunicarnos... y en verdad tengo mucho que contarle.", t = "El regreso del exánime pródigo"},
    [412] = {ot = "Llévale 8 piñones de estabilización y 8 engranajes giromecánicos a Razzle Engranágil en Kharanos.", st = "Luego de un análisis más detallado de la situación en Gnomeregan, parece que no solo fallamos en eliminar a los troggs sino que también terminamos por convertir a la mayor parte de la raza gnómica en horribles, descerebrados y malignos gnomos parias.$b$bOzzie y yo planeamos revertir este efecto paria asqueroso con nuestro último invento: el recombobulador. La máquina está casi completa pero necesitamos urgentemente algunos piñones de estabilización y engranajes giromecánicos. Quítales algunos a los gnomos parias que están frente a Gnomeregan para nosotros.", t = "Operación Recombobulación"},
    [413] = {ot = "Lleva el tonel de cerveza negra Brillante al montaraz Cebadiz.", st = "Me gustaría que mi hermano Wellart probara mi nueva cerveza negra Brillante. Es un montaraz. Está destacado en la torre de vigilancia del sur, en la frontera del Loch Modan.$B$BNo se dedica a hacer cerveza, como los demás Cebadiz, pero le encanta beberla y sé que esta le gustará.$B$B¿Podrías llevarle este tonel de cerveza negra Brillante de mi parte?", t = "Cerveza negra Brillante"},
    [414] = {ot = "Lleva el tonel de cerveza negra Brillante al montaraz Kadrell.", st = "He estado bebiendo la cerveza negra Brillante esa que hizo mi hermano. ¡Está buenísima! Quiero que la pruebe un compañero mío. Se llama Kadrell y normalmente patrulla por el camino de Thelsamar en Loch Modan.$B$BPara llegar a Thelsamar, ve al sureste a través del túnel y gira al noreste cuando el camino se divida. Sigue en esa dirección y llegarás $gderecho:derecha; a Thelsamar.$B$BDale este tonel de cerveza negra Brillante al montaraz Kadrell. ¡A ver qué le parece!", t = "Cerveza negra para Kadrell"},
    [416] = {ot = "Llévale 12 orejas de ratas de túneles al montaraz Kadrell en Thelsamar.", st = "Tenemos una infestación muy importante al oeste. Los kóbolds ratatúneles se han establecido en las laderas, han montado guaridas y apestan nuestra tierra con su suciedad.$B$BQueremos eliminarlos. Cázalos, tráeme sus orejas y llévate la recompensa.$B$BPuedes encontrar a los kóbolds ratatúneles en sus guaridas al oeste de Thelsamar, por todas las laderas.", t = "Mata ratas"},
    [417] = {ot = "Mata a Sarnagarra.$B$BLleva su garra sarnosa y el diario de Hildelve al piloto Podomartillo.", st = "Hildelve escribió en su diario que fue atacado por Sarnagarra, un gran oso zarpahelada. Ahuyentó a la bestia, pero no antes de que esta lo atacara salvajemente.$B$BA juzgar por el estado del cuerpo de Hildelve, Sarnagarra debió de regresar para matarlo.$B$BPero Hildelve tuvo tiempo de escribir un último deseo en su diario:$B$BSarnagarra debe pagar por esto.", t = "Vengar al piloto"},
    [418] = {ot = "Llévale 3 piezas de carne de oso, 3 intestinos de jabalí y 3 icores de araña a Vidra Hogartufa en Thelsamar.", st = "Entre los chicos que entran y salen, y los trabajadores de la excavación que vienen después de un día duro de trabajo, nunca nos faltan estómagos vacíos en Thelsamar. Somos famosos por nuestras morcillas, supongo que no las habrás probado.$b$b¿No? Bueno, por aquí hay que trabajar para ganarse el pan, no creas que por ser $gun:una; $c muy elegante vas a ser la excepción.$b$bNecesitaré carne de oso, intestinos de jabalí para poner el relleno y también icor de araña para un toque picante. ¡Tráeme todo eso y deja que Vidra te cocine!", t = "Morcillas de Thelsamar"},
    [419] = {ot = "Encuentra al piloto Hildelve.", st = "Mi amigo y colega piloto de máquinas de asedio, Mori Hildelve, está perdido en las colinas. Estábamos buscando una mena rara que necesitamos para fabricar pólvora de calidad superior y, durante la búsqueda, ¡condujo su máquina por una colina muy empinada y la averió!$B$BAún convencido de que el mineral estaba en estas montañas, Hildelve me encargó proteger nuestras máquinas mientras seguía la búsqueda a pie.$B$BHan pasado varios días y he oído algunos rugidos bestiales en las colinas por la noche. Mori es muy rudo, pero estoy un poco preocupado.$B$BPor favor, $n. Encuéntralo.", t = "El piloto perdido"},
    [420] = {ot = "Lleva el informe de Grelin a Senir Barbablanca a Kharanos.", st = "Los troggs del túnel son extremadamente hostiles y no dudan en atacar a los viajeros que lo cruzan. Pero tú pareces fuerte. No deberías tener problemas para pasar.$B$BMmm... indicaciones... Pues para hablar con Senir tienes que ir a Kharanos.$B$BÁbrete paso a través del túnel y cuando lo hayas cruzado, sigue el camino. Te llevará directamente a Kharanos.", t = "Las observaciones de Senir"},
    [421] = {ot = "Dalar Tejealba en El Sepulcro quiere que mates a 5 canosos Furia Lunar.", st = "Lady Sylvanas ha encomendado a Varimathras la conquista de las tierras humanas y enanas del sur.$B$BPero ese necio, Arugal, charlatán de Dalaran y ahora bestia maldita del Castillo de Colmillo Oscuro, dejó que su imprudente magia causara estragos en el bastión estratégico del Bosque de Argénteos.$B$BNecesito a alguien muy diestro en combate para ayudar a arreglar el desastre de Arugal. Demuéstrame tu valía matando a 5 canosos Furia Lunar. Es fácil encontrar a esas bestias salvajes al final del camino, hacia la colina de abajo.", t = "Demuestra tu valía"},
    [422] = {ot = "Recupera el Remedio de Arugal para Dalar Tejealba, en El Sepulcro.", st = "No me puedo imaginar cómo Arugal consiguió que el Kirin Tor le aceptase.$B$BLo que importa ahora es descubrir exactamente, qué magia utilizó Arugal. Así podré volverla contra él y asegurar el Bosque de Argénteos para la Dama Oscura.$B$BAl principio, Arugal se estableció en la granja de trigo que está justo al norte del puente. Uno de los mortacechadores, informó sobre algunos libros de hechizos que había visto, pero no pudo hacerse con ellos. Consigue el hechizo llamado Remedio de Arugal que está en esos libros.", t = "La locura de Arugal"},
    [423] = {ot = "Lleva 6 grilletes de glotón y 3 grilletes de almanegra a Dalar Tejealba en El Sepulcro.", st = "Tras examinar el trabajo de Arugal, se han confirmado mis peores sospechas. Ese viejo chiflado no estaba cualificado ni para limpiar orinales en Dalaran, y mucho menos para representar al Kirin Tor en su momento más desesperado. ¡Imbéciles!$B$BArugal utilizó objetos encantados para reforzar su débil magia. Necesito examinar esos objetos. Continúa tu viaje y mata glotones Furia Lunar y almanegras Furia Lunar hasta que hayas reunido suficientes grilletes encantados para mi investigación. Puedes encontrar a estas repugnantes criaturas hacia el norte y el este.", t = "La locura de Arugal"},
    [424] = {ot = "Mata a Grimson el Pálido y lleva su cabeza a Dalar Tejealba en El Sepulcro.", st = "Voy a tardar mucho más de lo que había pensado en descubrir los oscuros secretos que yacen tras los encantamientos que Arugal estaba usando.$B$BPero, mientras tanto, necesito que te encargues de un pequeño problema que nuestros acechadores negros han descubierto. Parece ser que Arugal permitió que su magia se extendiera hasta la Mina de Elem, en las colinas del sureste.$B$BLa mina resultó ser un lugar estratégico para el avance de Varimathras.$B$BQuiero que decapites al supervisor contaminado de la mina, Grimson el Pálido. Tras su muerte, la mina será nuestra.", t = "La locura de Arugal"},
    [425] = {ot = "Mata a Ivar el Hediondo y lleva la cabeza de Ivar a Rane Yorick en Los Dominios de Ivar.", st = "Mi hermano Quinn y yo teníamos que explorar el Bosque de Argénteos e informar al sumo ejecutor Hadrec. Pero no llegamos muy lejos... Cuando atravesábamos una granja, fuimos atacados por el necrófago Ivar el Hediondo.$B$BConseguimos escapar de Ivar, pero hirió gravemente a Quinn. Ahora se está recuperando gracias a la poción que le diste, pero Ivar podría volver antes de que Quinn esté totalmente bien.$B$BMata a Ivar para que Quinn tenga tiempo para curarse. Generalmente, Ivar está en el establo de allí, esperando a que baje la guardia.", t = "Ivar el Hediondo"},
    [426] = {ot = "Recoge 5 costillas con cortes y 3 calaveras ennegrecidas, y después regresa ente el Guardia de la Muerte Dillinger de Rémol.", st = "Los miembros de la Plaga están intentando establecer una base en los Molinos de Agamand. Si lo consiguen, podrán lanzar más ataques sobre Tirisfal.$B$BLas órdenes son claras: hay que detener a la Plaga en los Molinos.$B$BVe a los Molinos. Recoge costillas con cortes de los soldados armadóseos y los soldados testapartida, y calaveras ennegrecidas de los tirahuesos Ojosombra.$B$BPara llegar hasta los Molinos, sigue el camino en dirección oeste. Tras cruzar el puente, toma el siguiente desvío hacia el norte y continúa en esa dirección. Cuando veas los molinos de viento, dará comienzo la batalla.", t = "La invasión de los molinos"},
    [427] = {ot = "El ejecutor Zygand de Rémol quiere que mates a 10 guerreros Escarlata.", st = "Los documentos que el ejecutor Arren nos ha proporcionado son exactamente lo que necesitábamos para dar un giro a nuestra batalla contra la desdichada Cruzada Escarlata. Ahora sabemos sus ubicaciones exactas en Claros de Tirisfal.$B$BPero la Guardia de la Muerte tiene otras preocupaciones mayores. El ejército del Rey Exánime es más numeroso cada día que pasa. Necesitamos a alguien con un poco de \"iniciativa\" como tú para que envíe a la Cruzada Escarlata a la tumba.$B$BDemuéstrame que eres capaz de servir a la Dama Oscura; para ello, viaja al oeste hasta la torre que encontrarás pasada la Hacienda Solliden y mata a 10 guerreros Escarlata.", t = "En guerra con la Cruzada Escarlata"},
    [429] = {ot = "Consigue 3 corazones de huargo descoloridos y llévaselos al boticario Renferrel en El Sepulcro.", st = "El necrófago, Ivar el Hediondo, hirió de gravedad a mi hermano Quinn y no sé si podrá curarse sin ayuda de la alquimia. Si bien yo no soy un boticario, sé que nuestros boticarios pueden preparar pociones curativas a partir de corazones de huargos descoloridos.$B$BConsigue esos corazones y llévaselos al boticario Renferrel en El Sepulcro, al sur. Después, vuelve aquí con la poción.$B$BEncontrarás muchos huargos entre aquí y la Huerta de Malden, al este.", t = "Corazones salvajes"},
    [430] = {ot = "Lleva la poción de Quinn a Quinn Yorick en Los Dominios de Ivar, al norte de El Sepulcro.", st = "Aquí está la poción para curar a Quinn Yorick.$B$BAhora, si me perdonas, tengo algo muy importante que hacer...", t = "Regresa junto a Quinn"},
    [432] = {t = "¡Malditos troggs!"},
    [433] = {ot = "Mata a 10 cascahuesos comepiedras para el senador Mehr Piedrasanta en la Cantera de Gol'Bolar.", st = "Como miembro del senado y la Liga de Expedicionarios, he decidido encargarme de esta parte de la infestación de troggs que asola nuestras tierras.$b$bHan hecho un verdadero desastre en la Cantera de Gol'Bolar, y sin motivo aparente. Mientras excavábamos, comenzaron a salir, destruyeron nuestro equipamiento y expulsaron a nuestros mineros. No tenemos muchas más opciones que exterminarlos, reagruparnos y volver al trabajo.$b$bSi me ayudas con los troggs, con gusto te recompensaré por tu tiempo.", t = "El servidor público"},
    [434] = {ot = "Quédate en el jardín hasta que Lord Gregor Lescovar y Marzon el Filo Silencioso hayan terminado de hablar. A continuación, mátalos antes de volver a reunirte con Elling Trias en Ventormenta.", st = "Cuando le ponga el disfraz al robot espía, irá a hablar con Lescovar. Los guardias le dejarán pasar sin problemas.$B$BMientras estabas reuniendo los materiales, me encargué de informar a Marzon de que tenía que reunirse de nuevo con Lescovar. Incluso le di información falsa.$B$BLescovar dirá a sus guardias que se retiren y esperará a Marzon aquí fuera, en el jardín. En cuanto empiecen a hablar de los Defias, te toca mover ficha. Tienes que matarlos antes de que vuelvan los guardias. Cuando hayas terminado, habla con Trias.", t = "El ataque"},
    [435] = {ot = "Escolta a Erland a través de los lobos, hasta llegar a Rane Yorick.", st = "Los lobos que están fuera no se mueven y me miran de forma malvada cada vez que salgo por esa puerta. Deben de estar increíblemente hambrientos si piensan que puede merecer la pena comerme.$B$BTengo que informar a mi compañero de equipo, el Mortacechador Rane Yorick. Y, para conseguir llegar donde está Rane, necesitaré ayuda con esos lobos.$B$B¡Por favor, escóltame! Hay un montón de lobos ahí fuera, así que tendríamos más oportunidades si tienes algún amigo que pueda ayudarnos...", t = "Escolta a Erland"},
    [436] = {ot = "Habla con el explorador Ceñimal.", st = "El prospector Vetaferro dirige la excavación de unas antiguas ruinas al este del lago. Últimamente está haciendo pocos progresos, a pesar de todos los suministros que le hemos enviado.$B$BVetaferro es un enano honrado y tenaz que valora los resultados. Por eso sospecho que hay otros factores en su contra.$B$BVe a la Excavación de Vetaferro y habla con Magmar Ceñimal. Él se encarga de los detalles de la excavación y sabrá a qué se debe el retraso en los trabajos.$B$BPara llegar a la excavación, rodea el extremo sur del lago y luego dirígete al este.", t = "La excavación de Vetaferro"},
    [437] = {ot = "Mata gnolls Putrepellejo en El Campo Muerto.$B$BCuando aparezca Latipesadilla, mátala.$B$BLleva la esencia de Latipesadilla al sumo ejecutor Hadrec en El Sepulcro.", st = "Los informes iniciales de nuestros exploradores en Argénteos, muestran que los Putrepellejo tienen una base en una vieja granja del norte, El Campo Muerto. Hemos lanzado pequeños asaltos contra ellos, pero cada vez que lo intentamos, el alma en pena Latipesadilla les ayuda, utilizando su magia para diezmar nuestras tropas.$B$BQueremos acabar con Latipesadilla.$B$BVete a El Campo Muerto y ataca a los Putrepellejo. Si no ves a Latipesadilla, mata a los Putrepellejo hasta que aparezca y, después, mátala a ella.$B$BSu esencia se convertirá en polvo. Tráeme ese polvo como prueba.", t = "El Campo Muerto"},
    [438] = {ot = "Ve a El Viejo Embarcadero.$B$BEncuentra la razón por la que la Plaga está ahí.", st = "$n, hemos descubierto una nueva infestación de la Plaga: El Viejo Embarcadero. El embarcadero está al este de El Sepulcro y está muy protegido por los Putrepellejo y otros no-muertos.$B$BDebe de haber una razón para la ocupación de la Plaga de esa zona. Vete a El Viejo Embarcadero y descubre por qué está allí la Plaga.", t = "El Viejo Embarcadero"},
    [439] = {ot = "Lleva el anillo de Deliah al sumo ejecutor Hadrec en El Sepulcro.", st = "Entre los cadáveres sobresale una mano, abierta. Es la mano de una mujer, con marcas de la peste, pero relativamente fresca.$B$BEn la mano hay un anillo. Al sacar el anillo e inspeccionarlo revela una inscripción:$B$B\"Para Deliah\"", t = "Pistas de Putrepellejos"},
    [440] = {ot = "Lleva el anillo de Deliah al magistrado Sevren en Rémol.", st = "Si quieres encontrar al marido o bienamado de Deliah, quien le dio el anillo... habla con el magistrado Sevren en Rémol. Debería tener registros de los fallecimientos recientes y, con suerte, podrás descubrir quién es Deliah.$B$BPero yo no contendría el aliento. Quienquiera que le dio el anillo, está probablemente muerto. Y, si no está muerto, probablemente ya no le importa Deliah.", t = "El anillo grabado"},
    [441] = {ot = "Lleva el anillo de Deliah a Raleigh.", st = "Deliah tenía un marido, Raleigh, que ahora vive en Entrañas. Si la Deliah que vivía en Rémol es la dueña de este anillo, Raleigh lo sabrá.$B$BRaleigh está en el Barrio del Comercio, en Entrañas.", t = "Raleigh y Entrañas"},
    [442] = {ot = "Lleva la cabeza de Thule al sumo ejecutor Hadrec en El Sepulcro.", st = "Ha llegado el momento de asaltar el punto fuerte de la Plaga en Argénteos: la Isla de Fenris.$B$BDebes volver a la isla y acabar con a Thule Corvozarpa. ¡Quiero su cabeza!$B$BEsta misión es tan peligrosa como vital, $n. No puedes fallar.", t = "Asalto a la Isla de Fenris"},
    [443] = {ot = "Lleva 8 botellas de icor de Putrepellejo al boticario Renferrel en El Sepulcro.", st = "Antes de lanzar un asalto en la Isla de Fenris, debemos determinar quién está detrás de los gnolls Putrepellejo. Nuestros boticarios creen que su origen yace en el extraño líquido que fluye por sus cuerpos.$B$BVete a la Isla de Fenris, al este de El Viejo Embarcadero y recoge icor de los gnolls que encuentres allí. Llévaselo al boticario Renferrel, está fuera de El Sepulcro.", t = "Icor de Putrepellejo"},
    [444] = {ot = "Lleva la muestra de icor a Bethor Duroyelo en Entrañas.", st = "He reducido el icor que me has traído y he separado sus componentes básicos. Mis descubrimientos no son concluyentes, pero he determinado que en la creación del icor se utilizó brujería y nigromancia.$B$BMientras sigo estudiando el icor, quiero que le lleves una muestra a Bethor Duroyelo en Entrañas. Bethor no es un boticario, pero su conocimiento de la magia, puede ayudarnos a descubrir el misterio de los Putrepellejo.$B$BVete. Encontrarás a Bethor en el Barrio de la Magia de Entrañas.", t = "El origen de los Putrepellejos"},
    [445] = {ot = "Llévale los hallazgos del boticario Johaan al boticario Renferrel en Bosque de Argénteos.", st = "El tiempo es un lujo que no nos podemos permitir quienes trabajamos para Lady Sylvanas. Pero seguro que ya te habías dado cuenta.$B$BComo miembro de la Sociedad Real de Boticarios es mi deber compartir mis conocimientos con mis colegas para que con nuestro esfuerzo colectivo logremos algún día proporcionarle a la Dama Oscura su tan ansiada Nueva Peste.$B$BLlévale estas conclusiones al boticario Renferrel que está en El Sepulcro en el Bosque de Argénteos. Sigue los caminos que parten en dirección sur desde Rémol. Desde Entrañas, dirígete hacia el suroeste.", t = "Entrega a Bosque de Argénteos"},
    [446] = {ot = "Lleva el pergamino de Bethor al boticario Renferrel en El Sepulcro de Argénteos.", st = "Este icor fue creado por un viejo amigo mío: Thule Corvozarpa. Antes de la Gran Guerra, era un joven mago muy prometedor, pero cuando el Rey Exánime ocupó el trono, traicionó a sus hermanos y aliados con la Plaga.$B$BNo me había dado cuenta de que todavía sigue con vida, ni de que él es quien lidera a los Putrepellejo contra nosotros.$B$BConozco muchos de sus hechizos y puedo ayudar a preparar una poción para contrarrestarlos. Lleva este pergamino al boticario Renferrel. Tiene los conjuros necesarios para la poción.", t = "Thule Corvozarpa"},
    [447] = {ot = "Consigue 6 corazones de oso grisáceo y 6 muestras de sangre de celerácnida y llévaselas al maestro boticario Faranell en Entrañas.", st = "Arthas cuenta con innumerables tropas. Pero, con una Nueva Plaga podríamos erradicar tanto al ejército de la Plaga como a la infestación humana.$B$BMis estudios han demostrado que la sangre de araña combinada con una toxina derivada del corazón de un oso grisáceo resulta en un elixir letal. Reúne muestras de las arañas en Penumbra de las Celerácnidas, al noroeste, y de los osos que vagan por el Bosque de Argénteos. Lleva los componentes al maestro boticario Faranell de la Sociedad Real de Boticarios, en Entrañas.", t = "Una fórmula mortal"},
    [448] = {ot = "Preséntate ante el sumo ejecutor Hadrec en El Sepulcro.", st = "Antes de iniciar un asalto a la Isla de Fenris, ve a ver al sumo ejecutor Hadrec. Es posible que tenga equipamiento o información adicional que pueda serte útil.", t = "Preséntate ante Hadrec"},
    [449] = {ot = "Lleva el informe de los Mortacechadores al sumo ejecutor Hadrec en El Sepulcro.", st = "Si bien las heridas de Quinn se están curando, quiero entregar nuestro informe al sumo ejecutor Hadrec lo antes posible. Contiene información vital para la ocupación de los Renegados de Argénteos.", t = "El informe de los Mortacechadores"},
    [450] = {ot = "Recupera el Diario del boticario Berard de la Aldea Piroleña y llévaselo al boticario Renferrel en El Sepulcro.", st = "Puedes seguir ayudando a la Sociedad Real de Boticarios, $n.$B$BCuando Arugal utilizó su magia maligna en el bosque, maldijo a uno de nuestros miembros más prometedores, el boticario Berard. Ahora es un sirviente de Arugal, sin dominio de sí mismo. En estas condiciones, Berard no nos sirve de nada. Pero sus descubrimientos podrían servirnos. Estaba estudiando una antigua plaga que acabó con la vida acuática del Lago Lordamere años atrás.$B$BVe a buscar el Diario de Berard. Está en su estudio, el la Posada de la Aldea Piroleña, y llévaselo al boticario Renferrel.", t = "Una fórmula mortal"},
    [451] = {ot = "Lleva 6 muestras de moho de trepador del Lago, 6 muestras de moho de vagador del Lago y un tumor endurecido al maestro boticario Faranell en Entrañas.", st = "Según el Diario de Berard, el musgo de los vagadores del Lago y los trepadores podría ser útil para nuestro objetivo de crear una Nueva Plaga. Esas bestias viven en las islas del Lago Lordamere, al este.$B$BTambién menciona un tumor endurecido muy extraño que descubrió en un múrloc Anca Vil. Por lo visto, el tumor es tan poco común, que Berard solo pudo obtener uno.$B$BReúne muestras del musgo y del tumor endurecido y llévaselas al maestro boticario Faranell en Entrañas.", t = "Una fórmula mortal"},
    [452] = {ot = "Ayuda a la mortacechadora Faerleia a destruir al Consejo Piroleña.", st = "¡Has llegado justo a tiempo, $n!$B$BEl Consejo Piroleña está a punto de regresar. Arugal tiene que encargarse de otras cosas en el bastión. Utiliza el Consejo como si fueran marionetas, para mantener a los ineptos esbirros de la Aldea Piroleña bajo su control. Pero creo que sin la ayuda del Consejo Piroleña, los hijos de Arugal se volverían contra su maestro.$B$BNo puedo encargarme de todo sin ayuda. Te necesito. Juntos podemos acabar con el Consejo para Lady Sylvanas.", t = "La emboscada de Aldea Piroleña"},
    [453] = {ot = "Encuentra a la figura misteriosa. Las pistas que tienes: $B$BNo es oriundo de Villa Oscura. $B$BEs una persona nerviosa, que se altera fácilmente. $B$BDejó Villa Oscura y se dirigió al oeste.", st = "Buena suerte, $n. Espero que encuentres al tipo este... y que lo encuentres vivo.$B$BSi dejó la seguridad de Villa Oscura, podría haber sido víctima de las bestias salvajes.", t = "Encuentra la figura misteriosa"},
    [454] = {ot = "Habla con Miran.", st = "Antes llevábamos juntos los barriles de pólvora. Pero ahora que ha pasado esto... Ahora tenemos que dividir el trabajo, Miran lleva los barriles y yo vigilo los otros.$B$BNo me gusta que Miran vaya por ahí solo con los barriles. ¿Te importa acompañarlo?", t = "Tras la emboscada"},
    [456] = {ot = "Mata 7 sables de la noche jóvenes y 4 jabalíes cardo jóvenes y regresa con el conservador Ilthalaine.", st = "Saludos, $n. Soy el conservador Ilthalaine. He venido a Cañada Umbría para asegurarme de que se mantiene el equilibrio de la naturaleza.$B$BEsta primavera ha llovido más de lo normal, lo que ha beneficiado mucho a algunas criaturas del bosque, pero ha perjudicado a otras.$B$BAhora hay demasiados sables de la noche y jabalíes Cardo; Cañada Umbría no puede alimentar a tantas bestias. Joven $c, reduce las poblaciones de jabalí Cardo y sable de la noche para mantener la armonía de la naturaleza.", t = "El equilibrio de la naturaleza"},
    [457] = {ot = "El Conservador Ilthalaine necesita que mates a 7 sables de la noche sarnosos y 7 jabalíes cardo.", st = "Diezmar a la población joven de estas criaturas en Cañada Umbría ha sido un buen comienzo, $n, pero aún queda trabajo por hacer.$b$bLos recursos del bosque se agotarán pronto si no resolvemos este problema. Matar a las bestias de la naturaleza es un mal necesario para el bien de todos los que compartimos esta tierra. Adéntrate en el bosque y mata sables de la noche sarnosos y jabalíes cardo en nombre del equilibrio.", t = "El equilibrio de la naturaleza"},
    [458] = {ot = "Busca a la dríade Tarindrella.", st = "Qué bueno que has llegado, $c. Los espíritus del bosque me han susurrado unas noticias un tanto extrañas.$b$bLa misteriosa protectora de los bosques, Tarindrella, ha regresado a Cañada Umbría. La presencia de la dríade no se había sentido en los bosques de Kalimdor en muchos años. Algo sin duda anda mal si ha viajado de regreso a esta tierra.$b$bBusca a Tarindrella para ver a qué ha venido a nuestra arboleda. Una de las centinelas nos informó que la ha visto al sudeste de Aldrassil.", t = "La protectora de los bosques"},
    [459] = {ot = "Recoge 8 musgoviles y llévaselos a Tarindrella.", st = "Algo terrible sucede en los bosques de Teldrassil. Observa las colinas donde solían vivir los pacíficos fúrbolgs. Han abandonado sus hogares y adoptado el nombre \"tribu Tuercepinos\".$b$bSolo la corrupción del musgovil maldito podría ocasionar una transformación semejante. Los grells y grellines han infestado el área y amenazan a los residentes de Cañada Umbría. $b$bEnfréntate a los grells y grellines, $n, y comprueba si realmente están bajo los efectos del encantamiento del musgovil maldito.", t = "La protectora de los bosques"},
    [460] = {ot = "Lleva la cabeza de Alaric a su tumba.", st = "\"No pareces un Putrepellejo. Bien. Ya había perdido la esperanza...$B$BMe llamo Alaric, y fui el jefe de los sirvientes y guardaespaldas de Thule. Utilizó su magia para \"protegerme\" de la peste de no-muertos, pero su hechizo me dio una no-vida de la que no puedo escapar. Después de crear a los malvados gnolls Putrepellejo, Thule me decapitó... y dio mi cabeza a los gnolls como juguete.$B$BPor favor, llévame con mi cuerpo. Creo que los gnolls lo enterraron aquí, en el Castillo de Fenris cerca del establo, en una tumba sin nombre.\"", t = "Descansar en piezas"},
    [461] = {ot = "Lleva a Alaric al nicho oculto.", st = "Conozco un nicho oculto en el castillo que contiene un objeto muy valioso para Thule y sus viejos colegas. También contiene algo que podrías encontrar útil. ¡Llévame allí!$B$BEl nicho está en la torre suroeste del castillo, detrás de una estantería polvorienta.$B$BCoge mi cuerpo, pero deja mis botas. De todas formas... nunca me quedaron bien...", t = "El nicho oculto"},
    [463] = {ot = "Encuentra al Guardaverde.", st = "¿Has oído hablar del Guardaverde? No lo estarás buscando, ¿verdad? Si lo buscas es que estás $gloco:loca;, pero, ¿quién soy yo para apartar a un idiota de su muerte?$B$BSi estás buscando a esa bestia, he oído decir que está en los pantanos, al este del camino cuando se divide hacia Dun Modr. Está escondido entre los crocoliscos... ¡y cosas aún peores!$B$BDeja aquí tu dinero. No lo necesitarás allí a dónde vas... no querrás que Verdín se rompa un diente con tus monedas cuando te parta en dos de un bocado, ¿verdad?", t = "El Guardaverde"},
    [470] = {ot = "Uno de los mocos de la Tumba de Barbaférrea tiene la Bolsa de Shida, recupérala y devuélvesela en Puerto de Menethil.", st = "¡Durante mi visita semanal a la Tumba de Barbaférrea fui atacada por espantosos y pringosos mocos! Por supuesto, me entró pánico.$B$BLe lancé mi bolsa a uno de ellos, ¡pero no le hizo nada! El moco la absorbió... Por fortuna eso me dio algo de tiempo para escapar.$B$B¡La mala noticia es que necesito recuperar el contenido de mi bolsa!$B$BNo sé a qué moco le lancé la bolsa, ¡todos parecían iguales! La Tumba de Barbaférrea está al noreste de aquí, cerca de Dun Modr. ¡Muchísimas gracias!", t = "Abriéndose paso entre los mocos"},
    [471] = {ot = "Reúne 6 pieles de crocolisco gigante y llévaselas a James Halloran en Puerto de Menethil.", st = "Envié a mi aprendiz a los pantanos para desollar algunos de nuestros famosos crocoliscos gigantes de Los Humedales. Cuando no regresó salí a buscarlo... Basta decir que no fue una visión muy agradable.$B$BLa matrona dice que el chico podría recuperarse, ¡pero hasta entonces sigo necesitando pieles!$B$B... Si quisieras matar unas cuantas de esas bestias no estaría en contra, después de todo lo que hicieron. Encontrarás a los crocoliscos al Norte, siguiendo la costa y pasadas las casuchas de los múrlocs.", t = "Deberes de aprendiz"},
    [475] = {ot = "Busca a Gaerolas Talvethren en la Aldea Brisa Estelar.\n", st = "Se avecinan problemas en el bosque.$B$BGaerolas Talvethren es el Gran celador de los druidas hibernantes de la Garra en Túmulo de Ban'ethil. Su función como protector de los Adormecidos es preservar su seguridad de modo que no se rompa el pacto que tienen con Ysera. $b$bPero hace tiempo que no sé nada de él y me inquieta. Viaja al este hasta la Aldea Brisa Estelar para hablar con Gaerolas y regresa para informarme de todo. Cuando sepa que mis hermanos duermen apaciblemente, me quedaré más tranquilo.", t = "Una brisa problemática"},
    [476] = {ot = "Ve a ver a Athridas Manto de Oso a Dolanaar.", st = "¡La tribu de los Tuercepinos ha sido corrompida!$B$BLos fúrbolgs que anteriormente eran pacíficos se han rebelado contra los protectores del bosque. Me tendieron una emboscada cuando me marchaba al Túmulo de Ban'ethil y saquearon la Aldea Brisa Estelar. Ursal el Violento, su jefe, está empleando los maléficos poderes del musgovil para volverlos locos.$B$BYo estoy malherido y no puedo llevarle estas trágicas noticias a Athridas. Tendrás que hacerlo tú, joven $c. ¡Esperemos que los trastornados Tuercepinos aún no hayan llegado a Ban'ethil!", t = "Corrupción en Tuercepinos"},
    [477] = {ot = "Recupera el contenido de una de las cajas de zahoríes de Dalaran. Encontrarás la Aldea Piroleña hacia el sur.", st = "Como sabrás, la ciudad de Molino Ámbar sigue siendo una fuente de oposición humana, principalmente gracias al apoyo que reciben de los magos de Dalaran.$B$BNo sé cuál es su plan, pero que se hayan interesado por un lugar tan remoto como Molino Ámbar, indica que tiene que ser más importante de lo que pensamos.$B$BHan estado enviando cajas por carro desde Trabalomas. Muchos de esos suministros acaban en un pequeño campamento al norte de la Aldea Piroleña. Consigue los contenidos de una caja y tráemelos.", t = "Pasa la frontera"},
    [478] = {ot = "Lleva el extraño colgante al sacerdote de las Sombras Allister en El Sepulcro.", st = "<Rápidamente coges el colgante de la caja y vuelves a colocar la tapa.>", t = "Mapas y runas"},
    [479] = {ot = "Consigue 8 colgantes de Dalaran al sacerdote de las Sombras Allister en El Sepulcro.", st = "Dalar está intentando localizar la fuente de los hechizos de los magos. Por ahora, tendremos que ralentizar su avance como podamos...$B$BLos conjuradores, magos y protectores tienen, sin lugar a dudas, los colgantes. Quítaselos.$B$BSigue hacia el sur por el camino principal y después, dirígete al este, a Molino Ámbar.", t = "Las investigaciones de Molino Ámbar"},
    [480] = {ot = "Mata al archimago Dalaran, recupera su bastón y llévaselo al sacerdote de las Sombras Allister en El Sepulcro.", st = "Un archimago de gran poder está supervisando la reactivación del nodo de energía Ley. Con el progreso que han conseguido, nuestra única esperanza de detenerles es matándole. Será difícil, estará protegido por muchos magos y depositarios.$B$BDebes ir y acabar con él rápidamente. Cuando esté muerto, tráeme su bastón. Ahora, vete.", t = "El Tejedor"},
    [481] = {ot = "Lleva el colgante con runas grabadas a Dalar Tejealba en El Sepulcro.", st = "Lleva el colgante a Dalar Tejealba, quizás pueda ayudarnos a entender los planes de los magos.", t = "El análisis de Dalar"},
    [482] = {ot = "Habla con el sacerdote de las Sombras Allister en El Sepulcro.", st = "¡Por supuesto! ¿Cómo se me ha podido olvidar?$B$BMolino Ámbar fue uno de los lugares marcados por el Kirin Tor, debido a que tiene un nodo de energía Ley inactivo. Los magos deben de estar planeando reactivar el nodo y usar sus energías para algo.$B$BNo podemos permitir que esto ocurra...$B$BPara activar las energías Ley de la zona, necesitarán una gran cantidad de poder. Podemos paralizarlo todo si conseguimos los colgantes de los magos.$B$BCuéntale esto a Allister, él decidirá lo que tenemos que hacer.", t = "Las intenciones de los Dalaran"},
    [483] = {ot = "Recupera las Reliquias del Despertar y llévaselas a Athridas Manto de Oso en Dolanaar.", st = "Han visto a los invasores Tuercepinos saqueando Túmulo de Ban'ethil hacia el oeste.$B$BLos druidas durmientes quedarán atrapados en el Sueño Esmeralda por toda la eternidad, ajenos a sus destinos, a menos que los ayudemos. El delicado ritual de hibernación no puede detenerse sin las Reliquias del Despertar.$B$BViaja al Túmulo y consigue el talismán de la garra del cuervo, el cañón de pluma negra, el zafiro de cielo y la runa de nidal que los druidas guardan en cofres sagrados. Tráemelos y podré preparar el ritual del despertar.", t = "Las Reliquias del Despertar"},
    [484] = {ot = "Consigue $1oa pieles de crocoliscos jóvenes para James Halloran de Puerto de Menethil.", st = "Soy James Halloran, el curtidor. Mis pieles curtidas de crocolisco son las más apreciadas de todas y llegan cargamentos a todos los puertos del mundo.$b$b¿Viste a Einar? Es uno de los cazadores encargados de proporcionarme pieles de crocolisco.$b$bMe estoy quedando sin las suaves pieles de crías de crocolisco.$b$bPor eso te pagaré generosamente por una pila de esas pieles. Podrás encontrar crías de crocolisco en los pantanos que están a las mismas puertas de la ciudad.", t = "Piel de crocolisco joven"},
    [486] = {ot = "Mata a Ursal el Violento y regresa con Athridas Manto de Oso en Dolanaar.", st = "Ha llegado el momento de salvar a los druidas de la Garfa. Si fallamos ahora, $n, nunca podrán despertar de su sueño.$b$bPrepararé las Reliquias del Despertar para llevar a cabo el ritual. Para que mi trabajo surta efecto, debemos eliminar a la bestia maldita responsable de esta horrible situación. Solo entonces podrá completarse el ritual.$b$bUrsal el Violento fue quien se metió con nuestros hermanos y él es quien debe pagar para que puedan ser liberados. Viaja hasta las Tierras de los Tuercepinos al sudoeste y mátalo.", t = "Ursal el Violento"},
    [487] = {ot = "Mata 6 emboscadores Tuercepinos y regresa con la centinela Amara Noctámbula en las afueras de Dolanaar.", st = "El camino a Darnassus debe permanecer seguro. Los viajeros que se dirigen de Dolanaar a Darnassus han estado denunciando ataques brutales de fúrbolgs corruptos de la tribu Tuercepinos.$b$bEste camino se utiliza a diario para el transporte de mercancías y es la vía de comunicación más importante de Darnassus. No podemos permitir que esa pandilla de bárbaros paganos aterrorice a la gente.$b$bDefiende el bosque sagrado, $c. Su guarida está en algún lugar debajo de este punto de observación. Mata a 6 de estos emboscadores Tuercepinos y vuelve a verme.", t = "El camino a Darnassus"},
    [488] = {ot = "Llévale a Zenn Nauseapezuña afuera de Dolanaar 3 colmillos de sable de la noche, 3 plumas de lechuza estrígida y 3 muestras de seda de araña Tejemadera.", st = "Veo que tienes ganas de trabajar. Por suerte para ti, no hay día que pase que no desee tener cerca a $gun:una; $c que haga mi voluntad.$B$B¿Sabes, $n? Puedo hacerte muy feliz y ofrecerte cosas que jamás hubieras soñado tener, pero para eso deberás traerme una serie de objetos.$B$BPara desempeñar mi trabajo en el bosque a veces necesito ciertos... componentes. Tráeme 3 colmillos de sable de la noche, 3 plumas de lechuza estrígida y 3 muestras de seda de araña Tejemadera.$B$BY que esto quede entre nosotros, $r.", t = "Las apuestas de Zenn"},
    [489] = {t = "¡Búsqueda de redención!"},
    [490] = {ot = "Shayla Brisa Nocturna, en el camino afuera de Darnassus, desea que le traigas $1oa colmillos Tuercepinos.", st = "Por órdenes estrictas de los Centinelas, estoy ofreciendo una recompensa por los Tuercepinos. Ya no son aliados del bosque. La corrupción los ha convertido en una amenaza sin conciencia para nuestra gente y las criaturas del claro.\n\nSegún la orden dada, recibirás una recompensa por eliminar a la amenaza fúrbolg de Teldrassil. Tráeme sus colmillos como prueba de tus hazañas.\n\nEncontrarás a los fúrbolgs concentrados en Hondonada Ban'ethil, al oeste de Dolanaar y al sur del camino, así como en la aldea Brisa Estelar, al este.", t = "Recompensa por: fúrbolgs Tuercepinos"},
    [492] = {ot = "Llévale la bebida especial de Johaan al montaraz capturado.", st = "De acuerdo con la Guardia de la Muerte, acaban de capturar a otro de esos insensatos enanos montaraces. La Guardia de la Muerte suele encerrar a los prisioneros en el sótano del Mesón La Horca hasta que pueda encargarse \"debidamente\" de ellos.$B$B¿Por qué no vas a comprobar si al montaraz capturado le gusta la bebida especial que he preparado para él? Contiene una pequeña muestra de lo que la Dama Oscura tiene reservado para todo Azeroth.", t = "Una nueva Peste"},
    [493] = {ot = "Lleva el descubrimiento del boticario Renferrel al boticario Lydon en la ciudad de Molino Tarren, en las Laderas de Trabalomas.", st = "La Dama Oscura está presionando mucho a la Sociedad Real de Boticarios para que creen una Nueva Plaga. Estamos trabajando diligentemente y hemos avanzado mucho. Creemos que lo conseguiríamos antes si compartiésemos información entre la Sociedad.$B$BPor esa razón, quiero que entregues mis últimos descubrimientos al boticario Lydon en el Molino Tarren, una pequeña ciudad en las Laderas de Trabalomas. El viaje será largo.$B$BDirígete al sur y no te alejes de los caminos. ¡Sigue las señales de cerca!", t = "Viaja a Laderas de Trabalomas"},
    [494] = {ot = "Ve a Molino Tarren para llevar el mensaje de la mortacechadora Lesh a la suma ejecutora Darthalia.", st = "Cállate y presta atención, $c.$B$BMe han enviado aquí para vigilar Trabalomas. La mía es una misión de reconocimiento. Debes enviar un mensaje a la suma ejecutora Darthalia, a Molino Tarren, de inmediato. Dile que la mortacechadora Lesh le envía este mensaje:$B$B\"Desde el oeste nos llega el llanto del cuervo.\"$B$BSigue el camino que va al este y fíjate bien en las indicaciones. ¡Apresúrate! ¡Ve a Molino Tarren a toda prisa!", t = "El momento de atacar"},
    [496] = {ot = "El boticario Lydon de Molino Tarren quiere 10 lenguas de oso gris y un poco de icor de trepador.", st = "Otro maldito día en el Molino Tarren. Todo este aire puro me pone enfermo, $n.$B$BTenemos que infestar a los humanos cuanto antes. He estado estudiando potenciales agentes letales para utilizar en mis brebajes pero no he tenido tiempo de recogerlos todos.$B$BSi quieres hacer algo útil, podrías procurarme los siguientes objetos: diez lenguas de oso gris e icor de trepador, que es muy raro y difícil de encontrar. Nada más salir del Molino Tarren encontrarás osos y trepadores.", t = "Elixir de sufrimiento"},
    [498] = {ot = "Krusk de Molino Tarren quiere que liberes a Drull y a Tog'thar en el Castillo de Durnholde.", st = "El Jefe de Guerra me envió con algunos compañeros a Durnholde para recoger un objeto e investigar a esa tal Hermandad.$B$BFuimos a echar un vistazo, pero un numeroso grupo de humanos nos atacó por sorpresa. Luchamos como fieras, pero estábamos en franca minoría. Nos tomaron cautivos a algunos, pero conseguí escapar.$B$BDurnholde está al otro lado del río, hacia el sureste. Drull y Tog'thar están retenidos allí; debes ir a rescatarlos.", t = "El rescate"},
    [499] = {ot = "Dale el elixir de sufrimiento a Umpi.", st = "Tardaré un momento en mezclar estos ingredientes para crear lo que yo llamo mi elixir de sufrimiento.$B$B¡Allá vamos! Ah, nada me alegra tanto la vida en este lugar miserable como traer padecimientos al mundo.$B$BVeamos si la poción tiene el efecto deseado.$B$BDale a probar a mi asistente Umpi lo que la Dama Oscura ha planeado tanto para los humanos como para la Plaga.", t = "Elixir de sufrimiento"},
    [501] = {ot = "Lleva 10 viales de sangre de león de montaña al boticario Lydon de Molino Tarren.", st = "Oh, $n. En Trabalomas todo está florecido y el aire es puro y fresco. No puedo soportarlo. Miro por mi mugrienta ventana y espero el día en que nuestra Nueva Plaga traiga a este mundo la muerte que merece.$B$BAunque me gustaría perderme en mis negras reflexiones, el deber hacia la Dama Oscura me llama. ¿Quieres ayudarme? Según mis estudios, puedo obtener una estupenda poción letal con sangre de león de montaña. Tráeme un poco, verás qué bien lo pasaremos.", t = "Elixir de dolor"},
    [502] = {ot = "Dale el elixir de dolor a Stanley.", st = "¡No hay nada como el olor a sangre fresca!$B$BAhora añadimos un poquito de esto y una pizca de esto otro ¡y ya está! Esta poción se llama elixir de dolor. Si mis cálculos son correctos, este brebaje complacerá enormemente a Lady Sylvanas. Pero antes hay que probarlo.$B$BLlévalo a la granja norteña de Campos de Trabalomas, que está al suroeste. A ver qué le parece esta golosina a Stanley, el perrito del granjero Ray.", t = "Elixir de dolor"},
    [516] = {ot = "Encuentra El Desafío de Beren y, a continuación, mata 6 esclavos Corvozarpa y 6 guardianes Corvozarpa. Por último, vuelve a ver al sacerdote de las Sombras Allister en El Sepulcro.", st = "Me han informado sobre un grupo de no-muertos que están reagrupándose para preparar un ataque contra nosotros. Con esta información, podemos hacer algo y atacar primero, poniendo fin de un manotazo a su pequeño plan.$B$BPor desgracia, la información de la que dispongo es bastante incompleta. Se supone que están escondidos en El Desafío de Beren. Se desconoce la ubicación exacta, pero parece ser una cueva en las colinas, cerca de unos magos de Dalaran.$B$BConfío en tus recursos. Encuéntrales y acaba con ellos.", t = "El Desafío de Beren"},
    [527] = {ot = "Mata a 6 mozos de labranza de Trabalomas y 6 granjeros de Trabalomas, al granjero Ray y al granjero Getz e informa a Darthalia en Molino Tarren.", st = "Mantente en posición de atención cuando te dirijas a mí, $c.$b$bEstoy bajo las órdenes directas de Varimathras. Debemos aplacar la infestación humana hasta que nuestros boticarios desarrollen una plaga nueva.$b$bSegún nuestros informes, el poblado de Trabalomas se encuentra vulnerable. Tu primer deber es desbaratar su línea de suministros y su infraestructura.$b$bVe hacia el oeste. Asalta las granjas en el norte de los Campos de Trabalomas. Encárgate de que los terratenientes, los granjeros Ray y Getz, también sean ejecutados.", t = "La batalla de Trabalomas"},
    [528] = {ot = "Mata a 15 campesinos de Trabalomas e informa a Darthalia en Molino Tarren.", st = "El ataque a las granjas del norte tiene aterrados a los lugareños. Excelente.$B$BNuestros mortacechadores informan que los campesinos huyen a los campos del sur de Trabalomas. Esos necios creen que pueden escapar a su destino escondiéndose en el huerto.$B$BPero se equivocan, $n. Vuelve a Campos de Trabalomas y busca a los campesinos ocultos. Aniquílalos en el nombre de nuestra Dama Oscura.$B$BPuedes retirarte.", t = "La batalla de Trabalomas"},
    [530] = {ot = "Mata a Valdred Moray.$B$BLlévale sus manos a Raleigh Andrean, que está en Entrañas.", st = "Valdred, el que una vez fue mi mejor amigo, es el asesino de mi esposa. Aunque soy incapaz de llorar su muerte, sí que anhelo venganza. Si matas a Valdred y me traes sus manos malditas, te recompensaré.$B$BLa última información de que dispongo es que se encuentra en La Muralla de Cringris, al sur del Bosque de Argénteos, con intención de escapar al reino de Gilneas.", t = "La venganza de un esposo"},
    [531] = {ot = "Lleva la cabeza del viejo Tiznado a Vyrin Vientoveloz a la Cabaña del Errante.", st = "¡Por la Luz! No puedes meter eso aquí, es antihigiénico, antiestético y... ¡y huele mal!$B$BLlévatelo, ¿quieres? ¡Ese trofeo sangriento no le interesa a nadie!", t = "La venganza de Vyrin"},
    [544] = {ot = "Localiza a los traidores y recupera los artefactos. Luego vuelve a verme, $n.", st = "Había venido a Molino Tarren para estudiar, pero ahora debo solucionar una crisis. Verás, hace unos meses, cuatro Renegados huyeron de Entrañas. Dieron la espalda a su gente, pero lo peor es que robaron a la Dama Oscura.\n\nEntraron en una cámara de seguridad y robaron cuatro objetos que usaron nuestros boticarios en algunos proyectos. Sylvanas quiere recuperar esos objetos.\n\nLos ladrones huyeron de Entrañas a Dalaran y esos magos los pusieron en cuarentena en el Campo de Reclusión de Lordamere.", t = "Colarse en la cárcel"},
    [545] = {ot = "Mata a 6 invocadores de Dalaran y 12 esclavos elementales. Luego vuelve a hablar con el magus Vacuamirada en Molino Tarren.", st = "Antes de que desapareciera como por arte de magia, solía haber una barrera mágica enorme alrededor de la ciudad de Dalaran, que fue reconstruida hace poco. No me importa qué fue lo que ocasionó que una maravilla mágica semejante fallase. Lo que sí me importa es que en los alrededores de su ciudad, que ahora están expuestos, puede haber muchos tesoros mágicos. Vestigios de las ruinas sobre las que se construyó la nueva ciudad.$B$BPero los magos patrullan la zona con sus esclavos elementales.$B$BTienes que eliminarlos. Vuelve cuando hayas reducido sus filas.", t = "Las patrullas de Dalaran"},
    [546] = {ot = "El Guardia de la Muerte Samsa de Molino Tarren quiere 30 calaveras humanas de Trabalomas.", st = "Oí que has sido reclutado por Darthalia para luchar contra los humanos de Trabalomas. Estoy celoso.$B$BMientras tú te diviertes matando humanos, saqueando el pueblo y aterrorizando a gente inocente... yo estoy aquí clavado haciendo guardia en el Molino Tarren.$B$B¿No podrías apiadarte de un viejo Guardia de la Muerte como yo? Verás, colecciono calaveras humanas. Y tú pasarás algún tiempo combatiendo contra humanos. Reúne 30 calaveras mientras combates tu larga batalla y tráemelas. Haré que te merezca la pena.", t = "Recuerdos de muerte"},
    [549] = {ot = "Mata a 10 pícaros y 10 veladores de la Hermandad. La suma ejecutora Darthalia te dará tu recompensa en Molino Tarren.", st = "Por orden de la Lady Sylvanas, se decreta la pena de muerte para todos los miembros de la organización conocida como la Hermandad. Aquellos que sean tomados como prisioneros serán ejecutados. Se sabe que se están reuniendo en las ruinas del Castillo de Durnholde, al sureste de Molino Tarren.$B$BSe ofrece una generosa recompensa a quien pueda dar cuenta de sus actividades a la suma ejecutora Darthalia.", t = "SE BUSCA: Personal de la Hermandad"},
    [556] = {ot = "Lleva 10 muestras de piedra desgastada al vigilante Bel’varil de Molino Tarren.", st = "Los magos de Dalaran tienen una notable facilidad para relacionarse con elementales, que son poderosas criaturas de otras dimensiones. Los magos controlan a los elementales con talismanes mágicos. El mago Vacuamirada quiere analizar estos talismanes.$B$BVe a buscarlos al territorio de los magos de Dalaran, al oeste de Trabalomas.$B$BCualquier ciudadano de Dalaran puede llevar uno, pero te sugiero que busques en el campo de reclusión. Es más seguro que ir a Dalaran.", t = "Muestras de piedra"},
    [557] = {ot = "Lleva 4 brazales de vínculo de Tierra al vigilante Bel’varil de Molino Tarren.", st = "El mago está ocupado estudiando las muestras de piedra que has traído, pero pronto querrá ver sus opuestos: los brazales de vínculo. Cuando un elemental los lleva, queda ligado al servicio del mago.$B$BCaza elementales en las ruinas de Dalaran y recoge sus brazales de vínculo de Tierra para ganarte el favor del mago.", t = "Brazales de vínculo"},
    [590] = {ot = "Derrota a Calvin Montesco en Camposanto.", st = "¿Qué?$B$B¡¿Qué?!$B$B¿Quieres dinero? Yo no te debo dinero.$B$B¿Una carta? ¿Qué carta? Ah, estás buscando pelea. Muy bien, colega. ¡Vamos allá! Que te debo dinero...", t = "Un trato de pícaro"},
    [729] = {ot = "Viaja al sur y asegúrate de que el prospector Tripirrem está bien.", st = "Fue todo un honor que el maestro Mostachogris me asignara trabajar bajo la guía del gran prospector Tripirrem. En la academia de Forjaz todos conocían los grandes descubrimientos de Tripirrem.$b$bPero el prospector es un poco... um... ajeno... con su entorno.$b$bHabíamos descubierto evidencia de una gran sociedad. Gólems horribles brotaron de la tierra y arrasaron con el sitio. Tripirrem nunca pareció notarlo. Huí de regreso a Auberdine para buscar ayuda.$b$b¡Viaja al sur y verifica que el prospector se encuentre bien!", t = "El prospector despistado"},
    [730] = {t = "¿Problemas en Costa Oscura?"},
    [731] = {ot = "Protege al prospector Tripirrem mientras busca el fósil misterioso. Luego vuelve a Auberdine y busca a la arqueóloga Hollee.", st = "Dime, Hollee... ah, no, que no eres Hollee. ¿Dónde está Hollee?$B$BDeja, total, no es importante. Tenemos que encontrar ese cepillo de piedra... Quiero decir, el fósil misterioso. Tenemos que encontrar ese fósil. La Liga de Expedicionarios de Darnassus querrá algún informe de lo que he estado haciendo.$B$BAvísame cuando estés $glisto:lista;. Iremos a la caza de ese cepillo. Quiero decir, ¡del fósil! Así encontraremos algo palpable para satisfacer a la Liga.$B$B¿Estás $glisto:lista;?", t = "El prospector despistado"},
    [741] = {ot = "Ve a Darnassus y entrega el fósil misterioso al arqueólogo jefe Mostachogris.", st = "¿Así que el prospector quiere mandar el misterioso fósil a la Liga de Expedicionarios de Darnassus? No me gusta la idea de irme de Costa Oscura sin él.$B$BTen, $n, ve a Darnassus y entrega el misterioso fósil al arqueólogo jefe Mostachogris.", t = "El prospector despistado"},
    [743] = {ot = "Lleva 8 garfas de Viento Furioso a Ruul Garra de Águila al Poblado Pezuña de Sangre.", st = "Te agradezco que te pares a hablar conmigo, $n. Me llamo Ruul y soy guerrero y maestro.$B$BHas alcanzado la edad en la que debes prepararte para las pruebas que te esperan si quieres ir más allá de Mulgore.$B$BPara poner a prueba tu fuerza, ve al sureste a enfrentarte a las arpías Viento Furioso. Sus nidos están en los bordes de la montaña, alejados del camino.$B$BSon enemigas naturales de Mulgore y serán un buen indicativo de tu habilidad.", t = "Las Viento Furioso son un peligro"},
    [744] = {ot = "Consigue 6 plumas azur y 6 plumas de bronce, y llévaselas a Eyahn Garra de Águila en Cima del Trueno.", st = "$n, mi hermano pronto se personará ante el jefe Pezuña de Sangre y será un honor para mí prepararle su penacho.$B$BMe gustaría pedirte un favor mientras acabo de curtir estas cintas de piel. No he podido reunir todas las plumas que necesito y me preguntaba si tú podrías ayudarme a conseguir más.$B$BPuedes obtener las plumas del tamaño adecuado de las arpías que habitan al norte y noroeste de Cima del Trueno. Solo necesito 6 plumas azur y 6 de bronce para completar mi diseño.", t = "Preparación para la ceremonia"},
    [745] = {ot = "Mata a 10 curtidores, 8 desolladores y 5 furtivos Crines Pálidas y vuelve al Poblado Pezuña de Sangre para hablar con Baine Pezuña de Sangre.", st = "$n, esta tierra está herida por muchos conflictos. Espero que no tengas que presenciar tantos como yo en mi vida. Sin embargo, te pido que vayas a uno. Verás lo peligrosa que puede ser cualquier amenaza, por pequeña que sea, si no se ataja de inmediato.$B$BUnos gnolls Crines Pálidas se han instalado al sur de Pezuña de Sangre y en una cueva del oeste. No respetan nuestros intentos de establecer comunicación y matan a placer por todo Mulgore.$B$BLas palabras ya no sirven de nada.", t = "Compartir la tierra"},
    [746] = {ot = "Recoge 5 picos de prospector. $b$bBusca una forja para destrozar los picos. $b$bLleva 5 trozos de herramienta rota a Baine Pezuña de Sangre al Poblado Pezuña de Sangre.", st = "Al noroeste hay enanos preparando una excavación. Creen que la tierra está llena de secretos y eso es cierto, pero perforarla no es la mejor manera de descubrirlos.$B$BEncuentra las herramientas de los enanos, rómpelas y tráeme los pedazos.$B$BNecesitarás una forja para romperlas. Hay una en Cima del Trueno, pero te servirá cualquiera, incluso la del campamento enano.", t = "Una excavación de los enanos"},
    [747] = {ot = "Grull Viento de Halcón quiere que le lleves 7 plumas y 7 piezas de carne de zancudo de llanura al Campamento Narache.", st = "Tienes un aire prometedor, demostrarás tu valía ante la tribu. Puede que pronto te acojan en la gran ciudad de Cima del Trueno. Pero antes de eso, tendrás que mostrar tu valía ante mi padre, el Jefe Viento de Halcón.$B$BAquí en Mesa de la Nube Roja estamos orgullosos de nuestra habilidad para la caza. Los tauren cazamos por necesidad y por deporte. Nos estamos quedando sin carne y necesitamos plumas para la ropa. Caza zancudos de llanura y demuestra tu valor mientras reabasteces al poblado.", t = "Empieza la caza"},
    [748] = {ot = "Lleva 6 zarpas de lobo de pradera y 4 garfas de zancudo de llanura a Mull Tronacuerno al Poblado Pezuña de Sangre.", st = "¡Los goblins han mancillado nuestros pozos de agua sagrada! No podemos permitirlo.$B$BPara limpiarlos necesito un tótem de limpieza; tú lo llevarás al pozo y realizarás el ritual de limpieza.$B$BEl primer tótem es para el Pozo Pezuña Invernal. Necesitamos la ayuda de la tierra. Tráeme zarpas de lobo de pradera y espolones de zancudo de llanura adulto. Los encontrarás al suroeste.$B$BVuelve a mí con las zarpas y los espolones, $n.", t = "Pozos envenenados"},
    [749] = {ot = "Morin Acechanubes quiere que registres las cajas de la Caravana Devastada.", st = "Hace unos días nos encontramos una caravana escoltada de Ventura y Cía. en la costa norte del Lago Toro de Piedra. En un combate anterior habíamos perdido a dos de los nuestros, así que atacamos la caravana.$B$BDejamos las cajas porque lo incendiamos todo, pero hemos visto a rescatadores de Ventura y Cía. cerca de las carretas quemadas; quizás quedó algo de valor.$B$BPodrías acercarte a ver qué hay en las cajas.", t = "La Caravana Devastada"},
    [750] = {ot = "Grull Viento de Halcón quiere que le lleves 10 pelambres de puma montés al Campamento Narache.", st = "Un buen cazador tauren sabe que la presa no es un mero trofeo. Los animales de la llanura son nuestro medio de subsistencia. Si quieres impresionar a los ancestros, trae algunas pelambres de puma montés; son muy valiosas. Los pumas viven en esas colinas hacia el sur.$B$BLos niños necesitan ropa y tenemos que reparar las carpas.", t = "La caza sigue"},
    [751] = {ot = "Lleva los documentos de Ventura y Cía. a Morin Acechanubes cerca del Poblado Pezuña de Sangre.", st = "Al abrir la caja ves que está llena de mineral, otra prueba de las operaciones mineras de Ventura y Cía. en Mulgore. Coges el paquete de documentos que hay encima del mineral.$B$BEn las laderas del este se oyen ruidos de actividad industrial y se ve una columna de humo.", t = "La Caravana Devastada"},
    [752] = {ot = "El Jefe Viento de Halcón quiere que vayas a buscar a su madre cerca del pozo que hay al sureste del Campamento Narache.", st = "Todos los miembros de la tribu contribuyen a la armonía de la vida. Vivimos juntos y trabajamos juntos.$B$BCada uno de nosotros es responsable del bienestar de los demás. Quisiera pedirte un pequeño favor.$b$bMi madre se fue esta mañana a recoger agua del pozo que hay al sureste de Narache. Ya ha pasado un buen rato. ¿Podrías ir a buscarla mientras yo atiendo los asuntos de la tribu?", t = "Una humilde contribución"},
    [753] = {ot = "Llena un cántaro de agua en el pozo. $b$bLlévaselo al Jefe Viento de Halcón al Campamento Narache, que está al noroeste del pozo.", st = "He recorrido muchos caminos en la vida, mis piernas ya no son fuertes. Todavía puedo ser útil para la tribu, es solo que tardo un poco más en hacer las cosas.$B$BPero tú rebosas vitalidad, $c. Vamos a ponerla a prueba; llena un cántaro en el pozo y llévaselo a mi hijo, el jefe del Campamento Narache.$B$BRecuerda que incluso el más insignificante servicio puede valerte el respeto de los ancestros.", t = "Una humilde contribución"},
    [754] = {ot = "Usa el tótem de limpieza en el Pozo Pezuña Invernal y ve a ver a Mull Tronacuerno.", st = "Este es el tótem para el Pozo Pezuña Invernal. Llévalo al pozo y lleva a cabo el ritual de limpieza. El pozo está hacia el sureste y en poder de los repugnantes goblins.$B$BEs una misión difícil, pero no podemos perder el acceso a los pozos.$B$BSuerte, $n.", t = "La purificación de Pezuña Invernal"},
    [755] = {ot = "Ve a ver al vidente Lenguagris, que vive en las colinas al sur del Campamento Narache.", st = "Tu buena disposición y entusiasmo por ayudar a los tauren de Narache te ennoblecen, $n. Creo que un día se te aclamará en Cima del Trueno con grandes honores como $c.$B$BPero antes de eso, debes cumplir con los tres Ritos de la Madre Tierra.$B$BLa primera prueba es el Rito de la Fuerza. Ve a ver al vidente Lenguagris y dile que vas de parte del Jefe Viento de Halcón.$B$BSu morada está al sur del Campamento Narache, escondida entre las colinas.", t = "Los ritos de la Madre Tierra"},
    [756] = {ot = "Lleva 6 garras de acechador y 6 garras de puma a Mull Tronacuerno.", st = "Para crear el tótem de limpieza Tronacuerno necesitamos las garras de los depredadores de las llanuras Mulgore. Caza a los acechadores de praderas y a los pumas de las estepas, y tráeme las garras de ambos.$B$BLos encontrarás tanto hacia el este como hacia el oeste.", t = "El tótem de Tronacuerno"},
    [757] = {ot = "Mata a varios Erizapúas en el Barranco Cortazarza y lleva 12 cinturones Erizapúas al Jefe Viento de Halcón al Campamento Narache.", st = "Los Ritos de la Madre Tierra son los pasos con los que un joven tauren se gana el respeto de Cima del Trueno.$B$BEl primero que debes superar es el Rito de la Fuerza, con el que pruebas tu valor al matar enemigos de la tribu.$B$BLos Erizapúas del Barranco Cortazarza se están instalando en nuestro terreno de caza tribal. Atacan por emboscada a nuestros cazadores y roban en el poblado durante la noche.$B$BPara demostrar tu valor, acaba con esos villanos y entrega sus cinturones al jefe del Campamento Narache como prueba.", t = "Rito de la fuerza"},
    [758] = {ot = "Usa el tótem de limpieza en el Pozo Tronacuerno y ve a ver a Mull Tronacuerno.", st = "$n, el tótem ya está listo. Una vez más, te corresponde realizar el ritual de purificación.$B$BVe al Pozo Tronacuerno, que está al norte, y usa el tótem de purificación Tronacuerno en el ritual. Vuelve aquí cuando termines.$B$BQue los espíritus te acompañen.", t = "La purificación de Tronacuerno"},
    [759] = {ot = "Lleva 8 dientes de alfa de pradera a Mull Tronacuerno al Poblado Pezuña de Sangre.", st = "Ya solo queda por limpiar un pozo, que lleva el nombre del clan Crinferal. Para ello, la tierra debe ofrecernos los dientes de un depredador feroz, el lobo alfa de pradera. Los encontrarás al norte. Vuelve cuando hayas conseguido los dientes.$B$BLos alfa suelen deambular alrededor de nuestra ciudad, Cima del Trueno.", t = "El tótem Ferocrín"},
    [760] = {ot = "Usa el tótem de limpieza Ferocrín en el Pozo Ferocrín y ve a ver a Mull Tronacuerno.", st = "Los espíritus están complacidos contigo por la limpieza del Pozo Tronacuerno y el Pozo Pezuña Invernal, joven $n. El tótem Ferocrín ya está listo y tu última tarea te espera.$B$BEl Pozo Ferocrín está al norte de Cima del Trueno. ¡Lleva a cabo el ritual! ¡Limpia la tierra del veneno de los goblins! Que las aguas vuelvan a fluir puras y claras.", t = "La purificación de Ferocrín"},
    [761] = {ot = "Lleva 8 péñolas trofeo de aguilón a Harken Tótem de Viento al Poblado Pezuña de Sangre.", st = "El aguilón es un ave muy astuta, difícil de encontrar y de cazar. Un trofeo de plumas de aguilón sería una prueba de tu talento cazador.$B$BVe a las llanuras y caza uno.$B$BTráeme las plumas y gana honor para tu clan.$B$BEstán por todo Mulgore, pero tendrás que estar ojo avizor para verlos y muy veloz para cazarlos.", t = "La caza de los aguilones"},
    [763] = {ot = "Lleva el tótem de Alalcón a Baine Pezuña de Sangre al Poblado Pezuña de Sangre. Sigue el camino que sale del Campamento Narache.", st = "Si quieres seguir con los Ritos de la Madre Tierra tendrás que pasar otras dos pruebas. Debes ampliar tu experiencia, $n.$B$BVe al Poblado Pezuña de Sangre y habla con el Jefe Baine Pezuña de Sangre, hijo de Cairne Pezuña de Sangre. Allí podrás seguir tu viaje y ganarte la aceptación de los ancestros de Cima del Trueno.$B$BDale a Baine Pezuña de Sangre este tótem. Reconocerá mis grabados y te ayudará.$B$BSigue el camino que sale del Campamento Narache. Viaja deprisa y no te desvíes o te perderás.", t = "Los ritos de la Madre Tierra"},
    [764] = {ot = "Mata a 14 trabajadores de Ventura y Cía. y a 6 supervisores de Ventura y Cía. para Morin Acechanubes en Poblado Pezuña de Sangre.", st = "Esto explica el aumento de personal y equipamiento de Ventura y Cía. que hemos visto en Mulgore. Esos goblins... su empresa se expande demasiado rápido y contra su conveniencia. Ya conoces el dicho, enséñale algo a un goblin, y escucharás el sonido de fondo de la balanza.$b$bSon unos bichejos de lo más codiciosos. Por desgracia para sus negocios, los tauren no permitiremos que lleven a cabo sus operaciones en nuestras tierras. Dirígete a su mina, al noreste de la caravana saqueada y envíales un mensaje.", t = "Los Ventura y Cía."},
    [765] = {ot = "Mata al supervisor Saltatuercas y lleva su sujetapapeles a Morin Acechanubes al Poblado Pezuña de Sangre.", st = "Según los documentos que recuperaste de la caravana, Ventura y Cía. ideó varios planes para tratar de echarnos de nuestras tierras, y así tener libertad total para saquearlas.$b$bLos límites a los que estaban dispuestos a llegar para conseguir sus objetivos me asquean. Quiero ver muerto al cerebro que ideó estos planes. Se llama supervisor Saltatuercas y lo encontrarás en la Mina Ventura y Cía., al este de la caravana saqueada. Tráeme su sujetapapeles y veremos si encontramos algo útil.", t = "Supervisor Saltatuercas"},
    [766] = {ot = "Lleva un corazón de lobo de pradera, un fémur de puma de las estepas, una escama de zancudo de llanura y una molleja de aguilón a Maur Clamalluvias en el Poblado Pezuña de Sangre.", st = "Mi abuelo solía contarme historias sobre sus batallas con un zancudo llamado Mazzranache. Me hablaba de sus demoníacos ojos rojos, de sus afiladas garras y de su mordedura venenosa.$b$bLa casualidad quiso que, mientras viajaba por las llanuras, me lo encontrase; y me diese un terrible mordisco en el hombro. Era tan espantoso como mi abuelo solía describirlo. Para desinfectar la herida necesito unas cuantas cosas: un corazón de lobo, un fémur de puma, escamas de zancudo de llanura y una molleja.$B$BApresúrate, el tiempo corre.", t = "Mazzranache"},
    [767] = {ot = "Habla con Zarlman Dos Lunas en el Poblado Pezuña de Sangre.", st = "El Rito de la Visión, uno de los Ritos de la Madre Tierra, te enseñará cómo ganar el respeto de los ancestros de Cima del Trueno.$B$BNuestra gente ha aprendido que la tierra es la sagrada proveedora. Para tomar parte en la visión ritual, debes hablar con el guía espiritual de la aldea, Zarlman Dos Lunas.", t = "Rito de la Visión"},
    [768] = {ot = "Llévale 12 pieles de cuero ligero a Veren Zancaalta a Cima del Trueno.", st = "Saludos, joven. El brillo en tus ojos me indica que estás impaciente por continuar la caza. ¡Ojalá traigas honor a tu clan!$B$BYo trabajo con pieles y con ellas confecciono ropajes y armaduras para las gentes de Cima del Trueno.$B$BSi cazas bestias y me traes sus pieles, confeccionaré algo especialmente para ti.", t = "Recolecta cuero"},
    [769] = {ot = "Llévale 4 pellejos de cuero ligero y 4 hilos gruesos a Veren Zancaalta a Cima del Trueno.", st = "Los kodos de Mulgore son fuertes y robustos, unas cualidades que apreciamos mucho. Si tienes conocimientos de peletería y deseas aprender a fabricar una bolsa de piel de kodo, tráeme suministros para mi oficio.$B$BHazlo y compartiré mis conocimientos contigo.", t = "Bolsa de pellejo de kodo"},
    [770] = {ot = "Busca a alguien que conozca a Aullido Fantasma.", st = "La piel destrozada de Aullido Fantasma aún muestra la terrible herida que recibió en el combate contra la Legión Ardiente.$B$BHabría que avisar de su muerte en Poblado Pezuña de Sangre…", t = "La capa del demonio marcado"},
    [771] = {ot = "Lleva 2 piedras de pozo y 2 bellotas ámbar a Zarlman Dos Lunas al Poblado Pezuña de Sangre.", st = "Para superar el Rito de la Visión debes conseguir los componentes necesarios para crear el Agua de los Videntes.$B$BNecesito piedras de pozo, que encontrarás cerca de los pozos de Mulgore. Las mezclaré con bellota ámbar, que cae de los orgullosos árboles de nuestra tierra.$B$BEstos ingredientes son mágicos; tómate el elixir resultante junto a la hoguera tribal para tener una visión. Síguela y te llevará al siguiente paso de esta misión sagrada.", t = "Rito de la Visión"},
    [772] = {ot = "Bebe el Agua de los Videntes frente a la hoguera tribal del Poblado Pezuña de Sangre y sigue a la visión cuando aparezca.", st = "Aquí tienes el Agua de los Videntes.$B$BTómatela cerca de la hoguera tribal. Al cabo de un momento la visión se materializará junto a la hoguera.$B$BA partir de ahí, de ti depende el seguirla...", t = "Rito de la Visión"},
    [773] = {ot = "Ve a Roca Roja, al este de Cima del Trueno, y busca al espíritu ancestral.", st = "Para que los ancestros de Cima del Trueno te acepten, tienes que superar el Rito de la Sabiduría.$B$BAhora que has superado el Rito de la Visión, los espíritus ancestrales de Roca Roja te darán las bendiciones de los ancestros. Solo quien ha bebido el Agua de los Videntes merece recibir la bendición.$B$BVe a Roca Roja, al este de Cima del Trueno, y busca al espíritu ancestral, $n.", t = "Rito de la Sabiduría"},
    [775] = {ot = "Habla con Cairne Pezuña de Sangre en Cima del Trueno.", st = "Se te venerará en nuestra gran ciudad. Te mereces tal honor, $r, pues has completado los Ritos de la Madre Tierra.$B$BTu última misión consiste en buscar a nuestro noble jefe, Cairne Pezuña de Sangre, que vive en la cima de la mesa más alta de Cima del Trueno.", t = "Viaje a Cima del Trueno"},
    [776] = {ot = "Cairne Pezuña de Sangre de Cima del Trueno quiere que le lleves el cuerno de Arra'chea.", st = "Has superado los Ritos de la Madre Tierra y te has ganado un lugar en Cima del Trueno.$B$BPero no puedes dormirte en los laureles; debes probar tu valor constantemente.$B$BSomos cazadores, $n. En Mulgore vive un hermoso kodo que se llama Arra'chea. Tráeme el cuerno de Arra’chea para demostrarme tu habilidad para rastrear y cazar.", t = "Los ritos de la Madre Tierra"},
    [780] = {ot = "Grull Viento de Halcón quiere que le lleves 8 hocicos y 8 costillares de jabaguerrero al Campamento Narache.", st = "Los jabaguerreros del Barranco Cortazarza se están instalando en nuestro terreno de caza tribal. Los jabaespines Erizapúas, con quienes estamos en guerra, los amaestran para aumentar su ferocidad.$B$BAcaba con esas bestias y trae algunos hocicos y costillares para hacer caldo.", t = "Los jabaguerreros"},
    [781] = {ot = "Lleva los planes de ataque Erizapúas al jefe Viento de Halcón al Campamento Narache.", st = "Tras estudiar cuidadosamente el mapa, te das cuenta de que lo que has descubierto son los planes del jefe Erizapúas para un asedio prolongado sobre el Campamento Narache.$b$b¡Seguro que al jefe Viento de Halcón le hace falta esta información!", t = "Ataque al Campamento Narache"},
    [783] = {ot = "Habla con el alguacil McBride.", st = "Espero que te hayas preparado, joven $c, porque hay trabajo por hacer aquí en Villanorte.$B$BY no me refiero a cultivar los campos.$B$BLos guardias de Ventormenta están esforzándose para mantener la paz aquí, con tantos de los nuestros en tierras distantes y tantas amenazas que se acercan. Por eso estamos buscando la ayuda de todos los que quieran defender su hogar. Y su lealtad.$B$BSi viniste por ese motivo, habla con mi superior, el alguacil McBride. Está dentro de la abadía a mis espaldas.", t = "Una amenaza interna"},
    [784] = {ot = "Mata a 10 navegantes Kul Tiras, 8 marineros Kul Tiras y al teniente Benedict. Luego vuelve a buscar a Gar'Thok a Cerrotajo.", st = "Bajo el mando del almirante Valiente, los humanos de Kul Tiras invadieron Durotar, violando el pacto que el Jefe de Guerra selló con Jaina Valiente años atrás para derrotar a Archimonde.$B$BEl ataque humano fue rechazado y el Fuerte de Tiragarde cayó. Pero las reservas del Almirante, comandadas por el teniente Benedict, han retomado el fuerte y vuelven a amenazar nuestro territorio. Los humanos no tienen respeto alguno por la diplomacia.$B$BPor tu honor, viaja al sur hasta el Fuerte de Tiragarde y acaba con los invasores humanos.", t = "Vencer a los traidores"},
    [786] = {ot = "Lar Colmillo Acechador, de las afueras del Poblado Sen'jin, quiere que destruyas los 3 planes de ataque de Risco Kolkar.", st = "Baja la voz, $c. Los centauros Kolkar están justo al otro lado de este promontorio, al oeste, en el Risco Kolkar.$B$BLa otra noche, cuando estaban fuera, en una de sus batidas, me colé en su poblado y descubrí que esas bestias inmundas tienen planeado un ataque en tres oleadas contra los trols y orcos de Durotar.$B$BDebemos frustrar sus planes de invasión. Quizás tú puedas reunir la fuerza necesaria para infiltrarte en el Risco Kolkar y destruir sus planes.$B$BLo último que vi es que los habían repartido entre tres de sus líderes.", t = "Frustrar los planes kolkar"},
    [788] = {ot = "Mata a 10 jabalíes jaspeados y vuelve con Gornek en El Cubil.", st = "El primer punto del día será fortalecer un poco tu espalda. Te podría enviar a Los Baldíos, a cazar kodos, pero, sinceramente, nos eres más útil $gvivo:viva; que $gmuerto:muerta;.$B$BCreo que lo mejor será que empieces por los jabalíes jaspeados que encontrarás al norte de aquí.", t = "Dientes afilados"},
    [789] = {ot = "Consigue 10 colas de escórpido obrero para Gornek en el Cubil.", st = "Guerreros poderosos y novatos torpes han sido víctimas por igual de la picadura venenosa del escórpido. Encontrarás grandes cantidades de escórpidos al noroeste de aquí. Tráeme diez de sus colas como prueba de tu habilidad en batalla.$b$bEl antídoto para su picadura se crea a partir del veneno que se extrae de sus aguijones. Tenemos grandes cantidades de antídoto para el veneno de escórpido para curar a jóvenes como tú...$b$bPero sin duda no lo necesitarás, ¿verdad?", t = "Aguijón de escórpido"},
    [790] = {ot = "Mata a Sarkoth y llévale su zarpa a Hana'zua.", st = "¡$C! Creía que iba morir ahí fuera sin que nadie se enterara. Cuando estaba cazando los escórpidos del valle me crucé con uno que tenía un aspecto especialmente atroz. Me lancé contra él y conseguí asestarle un enorme golpe antes de que se enrollara en mi pierna.$B$BPero no estaba listo para su aguijón, y consiguió deslizarse en mi peto, desgarrando y penetrando en mi piel y derramando mi sangre. Por favor, ¡debes matar a ese escórpido! ¡Hay que defender mi honor! Combatí con él en la meseta que está al Sur.", t = "Sarkoth"},
    [791] = {ot = "Furl Ceñosprecio de la Atalaya de Cerrotajo quiere 8 retales.", st = "El tiempo me ha inutilizado para el combate. A mi edad, busco otras formas de ser útil.$B$BDesde este punto estratégico puedo vigilar la llegada de invasores. A medida que nuestra fuerza aquí se consolida, me encuentro dando la alarma cada vez menos.$B$BPara pasar el tiempo, creo objetos para ayudar a guerreros jóvenes y capacitados para defender nuestro hogar.$B$BA ti podría hacerte una bolsa para que lleves tus pertenencias. Si crees que te vendría bien, tráeme un retal. Sabrás lo que es... es un artículo muy normal tanto para centauros como para humanos.", t = "Asume tu responsabilidad"},
    [792] = {ot = "Mata a 12 familiares viles.$B$BRegresa con Zureetha Vistalonga fuera de El Cubil.", st = "Estoy segura de que aprenderás mucho en el Valle de los Retos, joven $c.$B$BFui enviada al Valle para guiarte, pero aquí he descubierto una creciente corrupción...$B$BUn grupo que se llama a sí mismo el Filo Ardiente tiene un aquelarre aquí mismo, en el Valle de los Retos. Se esconden en una cueva al Noreste, y sus familiares viles se han esparcido desde la boca de la cueva sembrando el caos y la confusión.$B$BTe ofrezco tu primera tarea contra el Filo Ardiente: derrotar a esos familiares. Aniquila a tantos como puedas y, si sobrevives, vuelve a verme.", t = "Familiares viles"},
    [794] = {ot = "Lleva el medallón del Filo Ardiente a Zureetha Vistalonga, a las puertas de El Cubil.", st = "Mis adivinaciones me traen visiones de un objeto lleno de poder, oculto en las profundidades del Aquelarre del Filo Ardiente y custodiado por bestias y magia negra.$B$BEs el llamado medallón del Filo Ardiente y tu siguiente tarea es sacarlo del Aquelarre.$B$BPero ten mucha cautela, el medallón puede estar en posesión de un agente del Filo Ardiente y su poder podría ser mayor que el del resto de los familiares con los que te hayas encontrado.$B$BVete, $n. Encontrarás el Aquelarre en una cueva, al Norte y al Oeste.", t = "El medallón del Filo Ardiente"},
    [804] = {ot = "Informa de la situación de Hana'zua a Gornek en El Cubil.", st = "La hazaña que has hecho por mí llena de valor mi corazón. ¡No puedo caer tan fácilmente! ¡Debo resistir!$B$BPero lo cierto es que no puedo hacer el camino de vuelta a El Cubil sin ayuda. Por favor, $n, vuelve a El Cubil e informa a Gornek de mi situación. Quizás él pueda ayudarme.", t = "Sarkoth"},
    [805] = {ot = "Habla con el maestro Gadrin en el Poblado Sen'jin.", st = "Tus retos contra el Filo Ardiente han terminado... aquí, en el Valle. Pero quiero que informes sobre todo lo que has descubierto.$B$BVe al Poblado trol Sen'jin y busca al maestro Gadrin. Poblado Sen'jin está al este del valle, y a la derecha cuando llegues al cruce.$B$BInforma a Gadrin sobre el Filo Ardiente y dile que han alcanzado el Valle de los Retos. Con él, averigua si también han llegado a Sen'jin.$B$BEn marcha, $n, y sé $grápido:rápida;. Temo que el mal del Aquelarre del Filo Ardiente solo sea el heraldo de una mayor amenaza...", t = "Preséntate en el Poblado Sen'jin"},
    [806] = {ot = "Lleva la zarpa de Fizzle a Orgnil Escaralma a Cerrotajo.", st = "¡No podemos permitir que el Filo Ardiente se establezca en Durotar! ¡Debemos acabar con él antes de que extienda su maldad!$B$BYo conduje mi propia investigación y averigüé que un brujo del Filo Ardiente, un goblin llamado Fizzle Tormenta Oscura, ha acampado en el Monte del Trueno, al noroeste. Ahí es donde están propagando el caos él y sus esbirros.$B$BEncuentra a Fizzle y acaba con él. ¡Y tráeme una zarpa suya!", t = "Oscuras tormentas"},
    [808] = {ot = "Recupera la calavera de Minshina del círculo de poder de las Islas del Eco.$B$BLlévasela al maestro Gadrin al Poblado Sen'jin.", st = "En mis sueños oigo la voz de mi hermano Minshina llamándome.$B$BSe lo llevó Zalazane, el brujo de las Islas del Eco que hay al este. Y ahora está muerto.$B$BPero la muerte no lo ha liberado. Zalazane utilizó su magia para atrapar el espíritu de Minshina en su propia calavera. En mi sueño, lo veo con otras calaveras, en un círculo de poder que está en la más grande de las Islas del Eco. Mientras siga allí, el alma de mi hermano estará maldita.$B$BTe lo ruego, $n. Encuentra el círculo y recupera la calavera de Minshina. Luego tráemela.$B$B¡Libera a mi hermano!", t = "La calavera de Minshina"},
    [809] = {ot = "Habla con Ak'Zeloth en Los Baldíos.", st = "Desde la última Gran Guerra, aquella en la que la Legión Ardiente fue derrotada, he buscado fuentes de corrupción demoníaca entre los orcos. El collar que me has traído confirma mis temores.$B$BPertenece al Filo Ardiente, un culto que adora un objeto de gran poder demoníaco. Se llama Semilla del Demonio y se encuentra en Los Baldíos, en la Cima Calígine. ¡Debe aniquilarla!$B$BVe a la Avanzada del Puente, hacia el oeste en la frontera de Los Baldíos y habla con mi ayudante, Ak'Zeloth. Él te guiará.", t = "Ak'Zeloth"},
    [812] = {ot = "Encuentra a Kor'ghan en Orgrimmar y consigue el antídoto para venocola. Luego lleva el antídoto a Rhinag. Está cerca del límite noroeste de Durotar.", st = "$n... llegas en el momento perfecto. Solo espero poder alabar tu velocidad también.$B$BTuve un descuido combatiendo con unos venocolas aquí cerca y uno de ellos me picó. Siento que su veneno me debilita por momentos. A este paso, calculo que me queda una hora de vida. Voy a necesitar tu ayuda...$B$BKor'ghan, de Orgrimmar, sabe cómo preparar el antídoto. Encuéntralo... y deprisa, $n. No viviré mucho. Debería estar en el Circo de las Sombras.", t = "Se necesita un remedio"},
    [813] = {ot = "Lleva 4 glándulas de veneno de venocola a Kor'ghan a Orgrimmar.", st = "Los venocolas son los escórpidos más mortíferos de Durotar. Rhinag no debería haber intentado cazar uno sin llevar el antídoto... pero ahora, lo último que necesita son mis reproches.$B$BTráeme unas cuantas glándulas de veneno de cualquiera de los ejemplares de venocola que encontrarás en la entrada de Orgrimmar y yo prepararé el antídoto.$B$BY date prisa, $n. Uno de los nuestros necesita nuestra ayuda.", t = "En busca del antídoto"},
    [815] = {ot = "Lleva 3 huevos de colazote al cocinero Torka de Cerrotajo.", st = "¡Ay! Casi me olvido de que tengo que preparar el desayuno.$B$B$n, muévete y tráeme unos huevos de colazote. Necesitaré por lo menos tres si quiero tener suficientes para la comida de mañana.$B$BLos colazotes Garrasangre son animales fieros y protegen sus huevos con la vida. A veces los entierran a gran profundidad y es difícil sacarlos sin correr peligro. Si te diriges a las Islas del Eco, al sureste del Poblado Sen'jin, encontrarás muchos.", t = "Romper huevos"},
    [816] = {ot = "Lleva un indicio del destino de Kron a Misha Tor'kren, a la granja que hay al noroeste de Cerrotajo.", st = "$n, por favor, ¿podrías ayudarme? Mi hijo Kron fue a cazar hace días y aún no ha regresado. Fue hacia el oeste, hacia Los Baldíos, a cazar crocoliscos en el Río Furia del Sur. Temo lo peor.$B$BEs muy fuerte pero su orgullo le mete siempre en líos. Yo le advertí de que los crocoliscos son fuertes y aviesos. Pero solo conseguí que se fuera enfadado.$B$BSi no puedes encontrarlo, al menos tráeme algún indicio de su suerte... aunque tengas que abrir el estómago de todos los crocoliscos de las orillas del Furia del Sur.", t = "Perdido, pero no olvidado"},
    [817] = {ot = "Lleva 4 pelajes de tigres de Durotar a Vel'rin Colmillo al Poblado Sen'jin.", st = "Muchos de los pelajes que usamos provienen de tigres de Durotar, $n. Mantas, armaduras, tiendas... tenemos muchos motivos para cazar a esas bestias y muchos también para dejar que proliferen.$B$BPero ha llegado el momento de hacer una selección en la manada, por decirlo de algún modo. Nuestros números crecen y nuestras necesidades empiezan a superar nuestras reservas. Necesito más pelajes para preparar los bienes que nuestra gente necesita.$B$BTráeme 4 pelajes de tigres de Durotar. Te recompensaré. Puedes encontrarlos en las islas que hay al sur de aquí.", t = "Presa práctica"},
    [818] = {ot = "Lleva 4 ojos de makrura intactos y 8 viales de moco de reptador al maestro Vornal al Poblado Sen'jin.", st = "Mis ojos empiezan a fallarme, pero aún veo con claridad. Y a menudo tengo que utilizar mis habilidades alquímicas para ayudarme en hechizos que antes me salían con facilidad. Pero me niego a adoptar un aprendiz. No he encontrado ningún trol ni orco merecedor de serlo.$B$B¿Tú crees valer lo suficiente? Sí, claro... Es evidente que lo crees.$B$BNecesito unas cosillas. ¿Crees que podrás conseguírmelas?$B$BNecesito ojos de makrura intactos y frascos de moco de reptador. Puedes conseguirlos de cualquier makrura o reptador de Durotar. Volveremos a hablar pronto.", t = "Un espíritu responsable"},
    [819] = {ot = "Encuentra a alguien que sepa algo sobre el barril vacío de Chen.", st = "Un cartelito en uno de los extremos del barril reza,$B$B\"Chen Cerveza de Trueno-$B$BQue tu ánimo se levante y con tu copa siempre brindes.\"", t = "El barril vacío de Chen"},
    [821] = {ot = "Llévale 5 colmillos de león de la sabana, 5 riñones de zancudo de llanura y 1 cuerno de truenagarto al maestro cervecero Drohn en Trinquete.", st = "¿Te gustaría probar la cerveza a la que le dio nombre Chen? Ah, la Cerveza de Trueno es un poderoso brebaje. Chen le enseñó la receta a mi mentor y mi mentor, a su vez, me la transmitió. Necesitaré que me consigas unas cosas pero te lo aseguro: el subidón lo merece.$B$BTráeme 5 colmillos de leones de la sabana de cualquier león de la sabana, 5 riñones de zancudo de llanura de cualquier zancudo de llanura y un asta de truenagarto de cualquier especie de truenagarto. Eso debería irnos perfectamente.$B$BPuedes encontrar estos ingredientes por Los Baldíos.", t = "El barril vacío de Chen"},
    [822] = {ot = "Llévale 5 glándulas relampagueantes, 1 glándula salivaria de halcón trueno y 1 hígado de kodo al maestro cervecero Drohn en Trinquete.", st = "Esa cerveza de trueno sí que es buena, ¿eh?$B$BTengo otra receta que me enseñó Chen. ¿Te interesa? No te quitará mucho tiempo, y puede serte útil si planeas continuar con tus aventuras.$B$BTráeme 5 glándulas relampagueantes de cualquier tormentero, 1 glándula salivaria de halcón trueno de los halcones trueno superiores y un hígado de kodo de cualquiera de los kodos de Los Baldíos.$B$BComo dije, es una bebida muy potente; es la cerveza trogg que te había mencionado.", t = "El barril vacío de Chen"},
    [823] = {ot = "Habla con Orgnil Escaralma de Cerrotajo.", st = "En el Poblado Sen'jin no nos faltan problemas, pero te agradecemos tu ayuda. Claro que las noticias que traes del Filo Ardiente podrían significar más problemas para todo el mundo.$B$BEn Cerrotajo hay un orco llamado Orgnil Escaralma que se encarga de librar Durotar de males como el que representa el Filo Ardiente. Busca a Orgnil y háblale de nuestra situación. Cuéntale también las noticias que traes del Valle de los Retos. Querrá saber esas cosas.$B$BCerrotajo se encuentra al norte.", t = "Informa a Orgnil"},
    [824] = {ot = "Llévale el globo de agua contaminada a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.", st = "El Anillo de la Tierra es un grupo de chamanes dedicados al estudio y la conservación de los elementos. Les sobra conocimiento sobre lunáticos dioses antiguos, ancestrales leyendas y tradiciones como nunca alcanzará la mayoría de los eruditos.$B$BEstás de suerte, conozco a alguien del Anillo de la Tierra aquí en Vallefresno. Dirígete a la Avanzada de Zoram'gar, en la costa de La Ensenada de Zoram, y enséñale a Je'neu Sancrea lo que has encontrado. Si alguien es capaz de interpretar el significado del globo, es él.", t = "Je'neu del Anillo de la Tierra"},
    [825] = {ot = "Gar'Thok de Cerrotajo quiere que recuperes 3 herramientas gnómicas de los restos de naufragio de la costa.", st = "Uno de mis mejores exploradores me ha informado de que los restos de la flota naufragada de Valiente aún están en la costa de Durotar, al este del Fuerte de Tiragarde.$B$BNo es un secreto que los humanos, aliados con esas mínimas criaturas llamadas gnomos, han desarrollado sus conocimientos de mecánica. Debemos estudiar a fondo a todos nuestros enemigos potenciales. Y nosotros también nos beneficiaremos de sus conocimientos.$B$BNada entre los restos del naufragio, $n y recupera las herramientas de la Alianza.", t = "Los restos del naufragio..."},
    [826] = {ot = "Derrota a Zalazane.$B$BMata a 8 trols vudú y 8 trols maléficos.$B$BLleva la cabeza de Zalazane a Gadrin.", st = "Zalazane, el curandero brujo, vive en las Islas del Eco, hacia el este. En otro tiempo, esas islas eran nuestro hogar.$B$BDesde ellas, Zalazane envía a sus trols a la península, a maldecir a nuestra gente y a esclavizarnos bajo su dominio.$B$BHay que detenerle.$B$BDerrota a Zalazane y a sus esbirros, antiguos trols Lanza Negra que hemos dado por perdidos. Tráeme su cabeza. Así sabré que su demoníaco reinado ha llegado a su fin.", t = "Zalazane"},
    [827] = {ot = "Recoge los collares abrasadores de los cultores de Roca del Cráneo. $B$BLlévaselos a Margoz a su campamento.", st = "$n, el Filo Ardiente ha infestado la cueva que hay al este de Orgrimmar, Roca del Cráneo. En esa cueva celebran sus inmundos rituales y queman su propia carne con collares abrasadores.$B$BCreo que usando esos collares, los cultores entran en sintonía con los poderes demoníacos. Pero para confirmarlo, necesito estudiar esos collares.$B$BVe a Roca del Cráneo y recoge los collares abrasadores que lleven los cultores. Tráemelos y yo descubriré su secreto.", t = "Roca del Cráneo"},
    [828] = {ot = "Habla con Margoz.", st = "Uno de nuestros chamanes, Margoz, sabe más sobre la corrupción del Filo Ardiente. Habla de una cueva de las montañas llamada Roca del Cráneo... ¡justo a las afueras de Orgrimmar! Esa cueva proporciona refugio a una banda de adeptos del Filo Ardiente.$B$BAntes de ir a Roca del Cráneo, habla con Margoz. Es sabio y su consejo es valioso.$B$BEstá acampado hacia el noreste, entre la costa y el Barranco Árido.$B$BSigue su consejo pero, diga lo que diga Margoz, $n, ¡aún quiero que aplastes a esos adeptos!", t = "Margoz"},
    [829] = {ot = "Lleva un collar de muestra a Neeru Hojafuego a Orgrimmar.", st = "Los collares abrasadores que me trajiste son potentes instrumentos demoníacos. Pero me temo que discernir su origen está más allá de mis habilidades chamánicas. Necesitamos que los estudie un brujo.$B$BLleva un collar abrasador a Neeru Hojafuego. Es un brujo muy capacitado que dice que utiliza sus poderes contra los demonios. Asegura que sus investigaciones de lo oculto son beneficiosas. Sea esto cierto o no, creo que necesitaremos su ayuda para luchar contra el culto demoníaco de Durotar.$B$BEncontrarás a Neeru en Orgrimmar, en el Circo de las Sombras.", t = "Neeru Hojafuego"},
    [830] = {ot = "Lleva las órdenes del almirante Valiente a Gar'Thok a Cerrotajo.", st = "Abres el viejo y desgastado sobre y descubres un documento que parece oficial. Reconoces el sello del almirante Valiente.$B$BParece importante. Gar'Thok, el Comandante de Cerrotajo, podría estar interesado en esta información.", t = "Las órdenes del almirante"},
    [831] = {ot = "Entrégale las órdenes del almirante Valeinte a Nazgrel en la Cámara de Thrall en Orgrimmar.", st = "No se puede confiar en los humanos. Luchamos a su lado con el corazón apesadumbrado porque sabíamos que nos traicionarían algún día.$b$bLa muerte del almirante Valiente no bastó para detener el legado de su traición. Esa escoria humana tenía un plan bien organizado antes de morir.$b$bParece que su reino no desaparecerá ni siquiera con la muerte de Benedict. Quién sabe cuánto pasará hasta que la próxima oleada de soldados Valiente llegue a nuestras costas.$b$b¡Tenemos que llevarle estas órdenes a Nazgrel en Orgrimmar de inmediato! Puedes encontrarlo en la Cámara de Thrall.", t = "Las órdenes del almirante"},
    [832] = {ot = "Lleva este ojo a Neeru Hojafuego.", st = "<Del colgante emanan unas palabras que se introducen en tu mente.>$B$B¿Gazz'uz?$B$BGazz'uz... ¡informa!$B$BHay noticias sobre tu descubrimiento en la Roca del Cráneo. ¡Debes prepararte para un ataque!$B$B¡Gazz'uz! ¡Te ordeno que hables! Habla. O me aseguraré de que llegue a Neeru Hojafuego la noticia de tu presencia y dejaré que descargue sobre ti su brutalidad.$B$BY no creo que quieras medirte con Neeru...$B$B¿Gazz'uz? ¿Estás ahí...?", t = "Sombras Ardientes"},
    [833] = {ot = "El tradicionalista Tótem de Lluvia quiere que mates 8 intrusos erizapúas en Roca Roja.", st = "Solo los tauren más valientes reposan en Roca Roja, nuestro cementerio sagrado. Es un honor que concedemos a los valientes guerreros que fundaron y defendieron Cima del Trueno y a aquellos que han entregado la vida por el bien de sus tribus y sus jefes.$B$BPero una vil amenaza se cierne sobre nuestra tierra sagrada. Una banda de Erizapúas está arrasando el cementerio; yo ya estoy mayor para enfrentarme a ellos.$B$BHay que emplear la fuerza, $n.", t = "Cementerio sagrado"},
    [834] = {ot = "Consigue 5 sacos de suministros y regresa con Rezlak cerca de Orgrimmar.", st = "Soy Rezlak, uno de los chicos de Gazlowe. El jefe me manda a ayudar a los orcos de Durotar. Las cosas han ido bien... excepto para las caravanas. ¡No consigo mantenerlas a salvo! Eso hace mi trabajo un poco más difícil, ¿sabes?$B$BEl último envío —que, dicho sea de paso, prometieron que llegaría— fue robado por arpías Viento Seco de... ¿de dónde era que eran? ¿El Cañón del Ventajo?$B$B¡Necesito conseguir esos suministros o nunca lograré nada! Sigue el cañón hacia el sur. Encontrarás una brecha en las paredes este y oeste.", t = "Las arpías Viento Seco"},
    [835] = {ot = "Mata a 12 Salvajes Viento Seco y 8 Brujas de la Tormenta Viento Seco para Rezlak, cerca de Barranco Árido.", st = "Gazlowe me dijo una vez: \"Rezlak. En la vida hay que saber una cosa: que si quieres algo bien hecho, tienes que hacerlo tú mismo.\"$b$bPues bien, como no me puedo permitir perder todas las caravanas, voy a tomar las riendas del asunto. Barranco Árido se encuentra en la parte del este de Cañón del Ventajo. Si matamos a todas las arpías allí, las rutas estarán a salvo.$b$bY claro, Gazlowe me enseñó algo más: \"Todo tiene un precio\". Así que, ¿cuento con tu ayuda, $n?", t = "Asegurar las rutas"},
    [837] = {ot = "Mata a 4 jabaespines Crines de Acero, 4 exploradores Crines de Acero, 4 polvorosos Crines de Acero y 4 guardias de batalla Crines de Acero para Gar'Thok, de Cerrotajo.", st = "Cuando llegamos, los jabaespines Crines de Acero poseían gran parte de la tierra... era una espinita que teníamos clavada. Con mucho esfuerzo hemos expulsado a la mayoría, pero aún quedan algunos bien fortificados en algunas zonas.$B$BPero esto ha durado ya demasiado. Por nuestro propio bien, no podemos permitir que haya Crines de Acero en nuestras tierras. Sus campamentos están al oeste de aquí. Busca las zarzas y los encontrarás. Hoy los echaremos de Durotar y mañana... puede que hasta de Kalimdor.", t = "Invasión"},
    [840] = {ot = "Sigue el camino occidental desde Cerrotajo hasta los Baldíos, después del puente.$B$BVe a la avanzada orca que se encuentra cruzando el puente.$B$BEntrega tu carta de reclutamiento a Kargal Marca de Guerra, en la Avanzada de Los Baldíos.", st = "Mmm, pareces fuerte.$B$BEscucha, mi buen amigo Kargal necesita nuevos reclutas para una misión en Los Baldíos. Sé que quieres servir bien a la Horda. Pues esta es tu oportunidad.$B$BLleva esta carta de reclutamiento a Kargal, a ver si la firma.", t = "Nuevo recluta de la Horda"},
    [842] = {ot = "Sigue el camino al oeste de la Avanzada del Puente de Kargal.$B$BEn la bifurcación, gira a la izquierda y sigue el camino al sur. $B$BBusca a Sergra Espinoscura en la intersección de El Cruce.", st = "Lleva esta carta de reclutamiento firmada a El Cruce.$B$BSergra Espinoscura, esa maldita, está a cargo. Es una chamán despreciable que te hablará sin sentido durante horas antes de asignarte una tarea útil. Thrall está convencido de que es especial, pero yo tengo mis dudas.$B$BTendrás que decidirlo por tu cuenta, $gcachorro:cachorra;...", t = "Servicio militar en El Cruce"},
    [843] = {ot = "Gann Picopiedra quiere que mates a 15 excavadores de Bael'dun y a 5 supervisores de Bael'dun.$B$BLlévale el diario de Khazgorm a Gann Picopiedra.", st = "Solitario, errante voy por estas carreteras.$B$BLos enanos de Bael Modan no muestran el menor respeto por mi tierra. Unas tremendas explosiones provocan enormes socavones en el suelo mientras sus máquinas destrozan las colinas. Esos destructivos enanos han cribado las tierras que otrora fueron nuestro hogar y de las que se alimentaba mi tribu.$B$BTodo intento de solución diplomática ha fracasado. Ha llegado la hora de una acción decisiva.$B$BExpulsa a la fuerza a los enanos de la excavación de Bael Modan y tráeme el diario de su jefe, el prospector Khazgorm.", t = "La reclamación de Gann"},
    [844] = {ot = "Reúne 7 picos de zancudos de llanura y llévaselos a Sergra Espinoscura en El Cruce.", st = "Tu primera presa será fácil.$B$BLos zancudos de llanura en el este han estado entrometiéndose con nuestros suministros de comida y se han convertido en una molestia.$B$BElimina a los zancudos de llanura y tráeme sus picos.", t = "La amenaza de los zancudos de llanura"},
    [845] = {ot = "Mata galopadores zhebras y recoge 4 pezuñas de zhebra para Sergra Espinoscura en El Cruce.", st = "Las zhebras, aunque no son las bestias más feroces de los Baldíos, son un poco más peligrosas que los zancudos de llanuras. No te preocupes, te enviaremos contra una presa más grande a su debido tiempo, pero por ahora necesitas afilar un poco más los dientes.$B$BCaza zhebras en el norte y el sur y recoge sus pezuñas. Tráemelas y quizás la próxima vez te enviemos contra una bestia un poco más desafiante.", t = "La zhebra"},
    [846] = {ot = "Gann Picopiedra quiere que le traigas 6 viales de nitroglicerina, 6 fajos de pulpa de madera y 6 muestras de nitrato sódico.", st = "Es evidente que el prospector dependía de los explosivos y de esos ruidosos vehículos para destrozar el suelo. Cabe esperar que pronto llegará otro Capataz para sustituirlo.$B$BQuiero darles a los enanos un poco de su propia medicina. Según estos planos, si combinamos nitroglicerina con pasta de madera y nitrato sódico, podemos crear una carga explosiva. Es bien sabido que el fusilero, los soldados y los oficiales tienen los suministros.$B$BReúne estos objetos y tráemelos. ¡Voy a preparar una carga que los enanos no olvidarán!", t = "La venganza de Gann"},
    [848] = {ot = "Llévale 4 esporas de hongos al boticario Helbrim en El Cruce.", st = "Los oasis de Los Baldíos ocultan un misterio. La energía de la vida fluye por sus aguas, revitalizando a las plantas y los animales que las beben.$B$BRevitalizando… y alterando.$B$BCerca de estos oasis, crece un tipo de champiñón. Sus esporas tienen unas propiedades que nosotros, los boticarios de Lordaeron, encontramos útiles.$B$BTráeme esas esporas y te ganarás nuestra gratitud.", t = "Esporas de hongos"},
    [849] = {ot = "Destruye la máquina voladora de Bael Modan y regresa junto a Gann Picopiedra.", st = "Según los planos de Khazgorm, no debería ser un problema preparar una carga explosiva.$B$BAh, eso es.$B$BBien, $n, voy a confiarte una tarea especial. Lleva este palo explosivo y úsalo para hacer saltar la máquina voladora de Bael Modan.$B$BLa máquina voladora no es solo una parte clave de la infraestructura del sitio sino que se usa además como máquina de guerra. Es más, constituye un icono de poder y un insulto a la memoria de mi tribu.$B$BDame un motivo de orgullo completando esta tarea heroica y recibirás justa recompensa.", t = "La venganza de Gann"},
    [850] = {ot = "Lleva la cabeza de Barak a Regthar Portamorta, al oeste de El Cruce.", st = "Los centauros han acosado a los tauren durante años. Y recientemente, los centauros kolkar de Los Baldíos se han convertido en una auténtica amenaza. No solían estar organizados pero han surgido nuevos jefes entre ellos. Y se han unido.$B$BPara mantener nuestras propiedades, hay que acabar con los jefes de los centauros.$B$BTráeme la cabeza de Barak Aterrakodos. Su campamento está cerca de las Charcas del Olvido al norte.$B$BDerrótalo y vuelve aquí.", t = "Los jefes Kolkar"},
    [851] = {ot = "Lleva la cabeza de Verog a Regthar Portamorta, al oeste de El Cruce.", st = "El centauro Verog el Derviche deambula por Los Baldíos, no será fácil encontrarlo. Pero tiene una tienda de mando en el Oasis Estancado al sudeste. Tal vez puedas llamar su atención.$B$BViaja al Oasis Estancado al sudeste y ataca a los centauros cerca de la tienda de mando. Será peligroso, pero si matas suficientes centauros debería sonar una alarma. Y así Verog saldrá.$B$BTráeme su cabeza y yo la colocaré junto a la de Barak Aterrakodos.", t = "Verog el Derviche"},
    [852] = {ot = "Lleva la cabeza de Hezrul a Regthar Portamorta, al oeste de El Cruce.", st = "Hezrul Marcasangre es el jefe de los centauros Kolkar en Los Baldíos. Es feroz, brutal y astuto. Su derrota sería un golpe contundente para los Kolkar. La amenaza que suponen se vería reducida en gran medida.$B$BMátalo. Como con Barak y Verog, tráeme la cabeza de Hezrul.$B$BEstá llevando a los suyos desde el Oasis Aguaverde hacia el sur.", t = "Hezrul Marcasangre"},
    [853] = {ot = "Llévale las esporas devueltas a la boticaria Zamah en Cima del Trueno antes de que se agote el límite de tiempo.", st = "He convertido las esporas que me diste en una emulsión. Debo enviársela a mi socia, la boticaria Zamah. Si se la llevas, seguro que tendrá algo para ti de nuestro fondo de productos alquímicos.$B$BSe encuentra en las Pozas de las Visiones, una caverna en el subsuelo de los chamanes de Cima del Trueno. El camino hacia esta caverna está muy bien escondido pero la encontrarás en el risco del Alto de los Espíritus.$B$BApúrate. Esta emulsión solo conservará su efectividad por poco tiempo y se debe procesar y volver a sellar antes de que eso ocurra.", t = "Boticaria Zamah"},
    [854] = {ot = "Habla con Thork en El Cruce, en Los Baldíos.", st = "Había vaticinado tu llegada, joven $c. Aunque quizás ya no seas tan joven.$B$BHa llegado el momento de que te internes más en estas tierras. Tu destino es conseguir grandes cosas.$B$BTienes que ir a El Cruce; nuestra vida está ligada a la de los orcos y necesitan ayuda. Sigue este camino hacia el este y después hacia el norte hasta El Cruce. Habla con Thork, que tiene la bendición de la Madre Tierra.", t = "Viaja a El Cruce"},
    [855] = {ot = "Lleva 15 brazales centauro a Regthar Portamorta, al oeste de El Cruce.", st = "Los kolkar son una amenaza para las ambiciones de la Horda en Los Baldíos; debemos reducir sus números. Y por eso tengo un trabajo para ti.$B$BCuando estés en sus territorios, mata a sus guerreros y recoge brazales centauro. Vuelve cuando tengas unos cuantos y la Horda te recompensará bien.", t = "Los brazales centauro"},
    [857] = {ot = "Feegly el Exiliado quiere que le consigas la Lágrima de las Lunas.", st = "¡El poder era mío! ¡Lo tenía en mis manos! ¡Y lo quiero recuperar! ¡Lo voy a recuperar!$b$bEsos excavadores asquerosos lo descubrieron... era tan hermoso. El primer gran descubrimiento que hicimos, considerado la Lágrima de las Lunas, lo hicimos en Bael Modan.$b$b¡Tendría que haber sido mío! ¡Mío!$b$bEl general Trenzado se puso celoso del poder que me otorgaba y lo guardó en el castillo. ¡Dijo que estaba maldito! ¡Ese necio!$b$b¡Los demás lo querían y había que detenerlos! Ese bastardo de Trenzado me hizo a un lado.$b$bAhora quiero recuperarlo. ¡Voy a recuperarlo!", t = "La Lágrima de las Lunas"},
    [858] = {ot = "Consigue la llave de ignición y llévasela a Rabiaire.", st = "¿No te mandará Petardol? Estoy en un apuro. Me metí sin darme cuenta de que necesitaba una llave para desbloquear la columna que mueve la trituradora. Un operario de otra trituradora me preguntó si todo iba bien ¡y me entró el pánico! En lugar de decirle que me faltaba la llave, le dije que había algún tipo de problema mecánico.$b$b¡Tenemos que salir de aquí cuanto antes! Sube a la sala de control en la cima de la grúa, el supervisor debe tener la llave de esta trituradora.$b$b¡Sácame de aquí!", t = "La llave de contacto"},
    [862] = {ot = "Llévale 8 ratas de madriguera a Larva al este de El Cruce.", st = "$gUn:Una; $c debe de pasar hambre por Los Baldíos. Al menos yo, me muero de hambre.$B$B¿Sabes qué? Voy a preparar un rico estofado. Solo necesito unas ratas de madriguera.$B$BAl parecer, a esos condenados enanos de Bael Modan les sobra lo mejor de lo mejor. Dirígete hacia el sur a Bael Modan y tráeme unas ratas de excavación.$B$BNo eres digno de llamarte aventurero curtido ¡hasta que has pasado un tiempo matando ratas! ¡Andando!", t = "Estofado de ratas de madriguera"},
    [863] = {ot = "Protege a Rabiaire y a la trituradora goblin robada de camino a Petardol en Trinquete.", st = "Supongo que aprenderé sobre la marcha... No puede ser muy difícil. Unos botones por aquí, una palanca o dos... Bueno, ¿$glisto:lista;?", t = "La fuga"},
    [865] = {ot = "Recoge 5 cuernos de raptor intactos de segadores Solescama y llévaselos a Mebok Mizzyrix en Trinquete.", st = "Los raptores de Los Baldíos son más inteligentes que los de cualquier otro sitio, y creo que se debe precisamente a sus cuernos. Si es así, quizás podría moler algunos para fabricar \"bebidas de inteligencia\". ¡Podría amasar fortunas!!$B$BY tú puedes ayudarme. Tráeme cuernos de raptor intactos de segadores Solescama. Puedes encontrarlos en los Baldíos del Sur y en los Baldíos del Norte cerca de la frontera de Bosque de Vallefresno.", t = "Cuernos de raptor"},
    [866] = {ot = "Llévale 8 muestras de raíces a Mebok Mizzyrix en Trinquete.", st = "Las hierbas de Los Baldíos no son como las de otras regiones. Sus propiedades son casi idénticas pero el agua de oasis las altera por lo que hay diferencias apenas perceptibles.$B$BDeseo estudiar esas diferencias... ¡para ver si se les puede sacar partido!$B$BSi eres un entendido en herboristería, recolecta muestras de raíces de las hierbas que encuentres en Los Baldíos. Tráeme esas muestras para que las pueda comparar con las de otras regiones.", t = "Recoge muestras de raíces"},
    [867] = {ot = "Recoge 8 garras de alabruja.$B$BLlévaselas a Darsok Movedaga en El Cruce.", st = "Estas malditas arpías han arrasado con los suministros de nuestras caravanas por mucho tiempo. Es hora de cortar algunas gargantas y reducir sus números.$B$BEché un vistazo a sus nidos y descubrí quiénes están a cargo. El ataque más devastador destruirá una buena sección de su cadena de mando más baja y luego nos encargaremos de los rangos más altos.$B$BEmpecemos de a poco: elimina arpías alabruja y malaplumas alabruja en el noroeste, y tráeme 8 garras de alabruja. Con eso podremos comenzar bien...", t = "Arpías saqueadoras"},
    [868] = {t = "¡A cazar huevos!"},
    [869] = {ot = "Lleva 12 cabezas de raptor a Gazrog en El Cruce.", st = "No hace mucho tiempo, robaron un cargamento de plata de nuestra torre de vigilancia. Era la paga de los guardias de El Cruce, y queremos recuperar esa plata.$B$BLo raro es que... atrapamos a uno de los ladrones la noche del robo. ¡Y... era un raptor! ¡Increíble!$B$BNo sé para qué quieren la plata los raptores. Pero no me importa... Quiero a los raptores muertos para que no vuelvan a robarnos.$B$BCaza a los raptores de los Baldíos. ¡Tráeme sus cabezas!", t = "Raptores ladrones"},
    [870] = {ot = "Informa sobre tus descubrimientos a Tonga Tótem de Runa.", st = "Hace mucho tiempo, Los Baldíos eran un lugar frondoso, rebosante de vida. Pero la guerra y el cataclismo arrasaron con la tierra, la abrasaron y dejaron un páramo yermo. Así son las cosas, y eso atribula mi corazón.$B$BPero en los últimos años, se han formado nuevos oasis en Los Baldíos, y la vida se abre camino. Y entre las profundidades, los druidas sentimos un poder que busca brotar a la superficie.$B$BDebemos encontrar la fuente. Viaja a las Charcas del Olvido, al noroeste de El Cruce. Busca una fuente de poder entre sus aguas y vuelve a verme.", t = "Las Charcas del Olvido"},
    [871] = {ot = "Mata a 8 buscaquas, 8 tejespinas y 3 cazadores de la tribu Crines de Acero, y regresa con Thork en El Cruce.", st = "Todos los jabaespines son nuestros enemigos, $n. Algunos son más problemáticos que otros.$B$BLa tribu Crines de Acero ha estado atacando nuestras rutas de suministros desde Durotar, lo que resulta cada vez más molesto. Envié exploradores para que busquen al líder de estos ataques, pero hasta entonces, todas las pérdidas que puedas causarles a esos sucios hombres cerdo nos vendrá bien.$B$BDeberías comenzar al noreste de camino a Durotar. Sus guaridas son fáciles de identificar por las enormes zarzas espinosas que brotan de la tierra. Búscalos y ejecútalos.", t = "Interrupción de los ataques"},
    [872] = {ot = "Mata a 8 geománticos Crines de Acero, 8 defensores Crines de Acero y a Kreenig Gruñucico.$B$BLuego llévale el colmillo de Kreenig Gruñucico a Thork en El Cruce.", st = "Uno de mis exploradores presenció un ataque contra una caravana de Durotar, $n. No hay duda de que los culpables son los jabaespines de la tribu Crines de Acero. Uno de ellos es el líder de estos asaltos: Kreenig Gruñucico. Lo vieron al noreste de aquí, justo al sur del camino de Durotar. Si queremos poner fin a la amenaza, Kreenig debe morir.$B$BPero para asegurarnos de que estos ataques terminen, debemos herir su orgullo además de sus cuerpos. Mata a Kreenig y a otros miembros de su tribu, y vuelve a verme cuando tengas su colmillo.", t = "La perturbación termina"},
    [873] = {ot = "Llévale el corazón de Isha Awak a Mahren Vidente del Cielo.", st = "El gran Isha Awak es dueño y señor de estas aguas. Grande es su fuerza y solemne su orgullo. Los humanos de la costa lo temen, porque les ha infligido muchas bajas.$B$BPero no lo temo. Incluso doy las gracias por su presencia. Es un desafío digno y una presa honorable.$B$BSi estás $glisto:lista;, nada mar adentro en busca de Isha Awak, la Condena Abisal.$B$BSu ánimo mora en su corazón y oírlo latir es conocer tu sino.", t = "Isha Awak"},
    [874] = {ot = "Habla con Mahren Vidente del Cielo.", st = "Has cazado las fieras de Los Baldíos. Eso demuestra fortaleza de espíritu. Pero $gun cazador:una cazadora; siempre debe estar $gpreparado:preparada;. En cualquier terreno, $gun auténtico cazador:una auténtica cazadora;, puede seguirle la pista a una presa. No se detendrá ante montañas ni ciénagas.$B$BNi siquiera ante el mar.$B$BEncuentra a mi hermana, Mahren. Se dedica a cazar a los grandes monstruos marinos de la costa. Te enseñará todo lo que hay que saber sobre ellos.$B$BPero ándate con cuidado cuando la busques, ya que la costa de Los Baldíos está en manos de los humanos.", t = "Mahren Vidente del Cielo"},
    [875] = {ot = "Recoge 6 anillos de tenientes arpías de destripadoras alabruja y regresa con Darsok Movedaga en El Cruce.", st = "Jajaja, $n. ¿Volviste por más? Bien, me gusta oír eso.$B$BEsta vez necesito que mates a algunas tenientes arpías de las Colinas Áridas. Solo las destripadoras alabruja pueden ser tenientes; puedes distinguirlas por los anillos que llevan. Son de lo más despreciables, pero tienen algunas subalternas a su cargo. Si eliminas a 6 de ellas, será un golpe decisivo contra su matriarcado.$B$BEncárgate de que sufran antes de morir, $n. Queremos que esas sucias arpías sepan lo estúpido que es pelear contra la Horda.", t = "Las tenientes arpías"},
    [876] = {ot = "Mata a Serena Sangrepluma y lleva su cabeza a Darsok Movedaga en El Cruce.", st = "Hiciste un trabajo tan bueno con las tenientes y subordinadas que me gustaría que hicieras una última cosa por mí.$B$BSerena Sangrepluma es la hermana de una arpía llamada Sangrepluma, que murió a manos de Rexxar hace tiempo. Al parecer, estos ataques contra las caravanas de la Horda son una venganza por su muerte.$B$BNecesito que la degüelles y me traigas su cabeza. Quiero colocarla en la próxima caravana que enviemos... Dales a esas arpías un motivo de preocupación.", t = "Serena Sangrepluma"},
    [877] = {ot = "Investiga el Oasis Estancado y regresa con Tonga en El Cruce.", st = "Puede que haya más grietas en los demás oasis de Los Baldíos, como la que encontraste en las Charcas del Olvido. En ese caso, tal vez las grietas sean la fuente de vida de los oasis.$B$BDebemos comprobarlo.$B$BToma, lleva estas semillas. Están muertas y estériles, pero llévalas al Oasis Estancado en el sudeste. Si encuentras una grieta, coloca las semillas en su interior... y observa.", t = "El Oasis Estancado"},
    [878] = {ot = "Mata a 6 buscaquas Erizapúas, 12 tejespinas Erizapúas y 12 geománticas Erizapúas y vuelve junto a Quebrantadientes en el Campamento Taurajo en Los Baldíos.", st = "Debes acabar con mis enemigos. <Gruñe.> Debes ayudar a Quebrantadientes y a los Crines de Acero a debilitar a los Erizapúas. Ambas tribus son muy espirituales, vinculadas a la tierra y a su poder. <Gruñe.> Nos da fuerza en todo... especialmente en la guerra.$B$BSi quieres saber quién le causa realmente este suplicio a Thork <gruñe> y a la Horda, entonces ¡ayuda a Quebrantadientes! Ataca a los líderes espirituales de los Erizapúas hacia el norte; debilítalos lo suficiente para que los Crines de Acero puedan vencerlos y dominar Los Baldíos.", t = "Tribus en guerra"},
    [879] = {ot = "Mata a Nak, Kuz y Lok Aterraorcos y lleva sus calaveras a Quebrantadientes en el Campamento Taurajo en Los Baldíos.", st = "Tres miembros de mi tribu salieron del Horado para encabezar unas incursiones contra la Horda, $r. <Gruñe.> Son crueles y taimados, y si los derrotas, entonces El Cruce y la mayor parte de Los Baldíos conocerán la paz... <gruñe> al menos por lo que respecta a la tribu Crines de Acero <gruñe.>$B$BNak, Kuz y Lok Aterraorcos son a los que tienes que buscar. Se encuentran en un lugar remoto del sur de Los Baldíos. Uno lanza hechizos, otro es un rastreador y su líder, llamado Aterraorcos <gruñe> es un guerrero. Mátalos, $r, como ellos me han matado a mí.", t = "Traidores"},
    [880] = {ot = "Lleva 8 caparazones de quijaforte alterado a Tonga Runatótem en El Cruce.", st = "Tus hallazgos son increíbles, $n. Estos oasis contienen propiedades provenientes de una fuente externa. O tal vez una interna.$B$BQuiero saber cómo afectan estas grietas a las bestias que beben las aguas de los oasis.$B$BCaza quijafortes del oasis en los Oasis Aguaverde y Estancado. Tráeme sus caparazones para examinarlos.", t = "Seres alterados"},
    [881] = {ot = "Lleva el pellejo de Echeyakee a Sergra Espinoscura en El Cruce.", st = "Albineblina, Echeyakee en la lengua de los tauren, es el rey de los felinos de la sabana. Es tan sigiloso al cazar que dicen que es como una neblina blanca y etérea sobre la tierra. Y tan raudo mata a sus presas que no tienen tiempo de sentir miedo ni dolor.$B$BBLos tauren dicen que es muerte y misericordia a la vez.$B$BTú descubrirás si es verdad, porque ahora te encomiendo cazar a Echeyakee. Su guarida está al noreste de El Cruce, entre los huesos de kodos gigantes$B$BVe. Haz sonar este cuerno cuando llegues a su guarida. Cuando lo hagas, aparecerá.", t = "Echeyakee"},
    [882] = {ot = "Llévale el colmillo de Ishamuhale a Jorn en el Campamento Taurajo.", st = "Ishamuhale, Dientarpón, es el más feroz de los raptores Solescama de Los Baldíos. No caza por deporte, ni por comida. Caza porque le apasiona la caza. Mata porque está en su naturaleza.$B$BY tendrás la oportunidad de conocer su naturaleza, $n, porque tu camino sigue ahora las huellas de las garras de Ishamuhale.$B$BEmpieza la caza. Mata a su presa favorita, una zhebra, y trae entonces sus despojos al árbol muerto al noroeste de Trinquete. Ishamuhale olerá los despojos y esto lo atraerá.$B$BPrepárate para cuando llegue.", t = "Ishamuhale"},
    [883] = {ot = "Llévale la pezuña de Lakota'mani a Jorn en el Campamento Taurajo.", st = "La pezuña de Lakota'mani es un símbolo de la fuerza del gran kodo.", t = "Lakota'mani"},
    [884] = {ot = "Llévale la espina caudal de Owatanka a Jorn en el Campamento Taurajo.", st = "Al tocarla, saltan chispas de la espina caudal de Owatanka.", t = "Owatanka"},
    [885] = {ot = "Llévale la pluma de Washte Pawne a Jorn Vidente del Cielo en el Campamento Taurajo.", st = "La pluma de Washte Pawne hace daño al tocarla.", t = "Washte Pawne"},
    [886] = {ot = "Habla con Tonga Tótem de Runa en El Cruce.", st = "Los druidas de Cima del Trueno sentimos la presencia de un extraño poder en Los Baldíos, al este de Mulgore.$B$BEnviamos a Tonga Tótem de Runa para que descubra la fuente de dicho poder pero tememos que necesite ayuda.$B$BVe a Los Baldíos y habla con Tonga. Lo encontrarás en El Cruce. Para llegar hasta allí, sigue el camino que sale del Poblado Pezuña de Sangre en dirección este. Una vez en Los Baldíos, coge hacia el norte cuando el camino se bifurque. Continúa en dirección norte y encontrarás El Cruce.$B$BTen cuidado de no abandonar el camino, $n, pues Los Baldíos es un terreno muy abrupto.", t = "El oasis de Los Baldíos"},
    [887] = {t = "Los filibusteros de los Mares del Sur"},
    [888] = {ot = "Recupera el envío de botas y las lentes telescópicas a Gazlowe en Trinquete.", st = "Aunque me gustaría recuperar toda mi mercancía, seguro que no es posible. Sin embargo, ¡es imprescindible que recupere unas cuantas cosas!$B$BComo puedes ver, mi observatorio está listo pero necesita la más pequeña de las dos lentes. La primera llegó de Durotar por caravana pero la segunda se envió por barco... y nunca llegó a puerto. ¡Y tampoco me ha llegado el envío por mar de Drizzlik desde Bahía del Botín!$B$BDirígete al campamento pirata y a ver si los puedes encontrar.", t = "Botín robado"},
    [890] = {ot = "Llévale el libro de contabilidad de Gazlowe al maestro de muelles Vertipeluca.", st = "¡Llevo siglos esperando mi último cargamento de mercancías de Bahía del Botín! Pondría la mano en el fuego a que lo robaron los filibusteros pero para asegurarnos, podrías acercarte hasta el muelle y preguntarle a Vertipeluca si ya han guardado mi mercancía en el almacén sin notificármelo.$B$BToma mi libro de contabilidad y dile a Vertipeluca que coteje mis datos de inventario con sus registros.", t = "El envío perdido"},
    [891] = {ot = "El capitán Thalo'thas Solbrillante de Trinquete quiere que recojas 10 medallas de Theramore y mates a la capitana Justamonta, el cañonero Whessan y el cañonero Smythe.", st = "¡He perdido otro barco de mi flota por culpa de esos humanos exaltados del Fuerte del Norte!$b$bDebemos encargarnos de esos malditos. Esos patanes incautos están tan alterados y paranoicos que le disparan a todo lo que ven sin pensarlo.$b$bViaja al sur por la Costa Mercante hasta el Fuerte y ataca sus fuerzas. Tráeme las medallas de sus soldados como prueba. Y por el bien de mi flota, mata a la capitana Justamonta y sus cañoneros fanáticos!", t = "Las armas del Fuerte del Norte"},
    [892] = {ot = "Llévale el libro de contabilidad de Gazlowe a Gazlowe en Trinquete.", st = "Todo parece cuadrar según mis registros, $n. Vuelve y dile a Gazlowe que no ha habido suerte. No me sorprendería nada que los piratas le hubiesen birlado ese material.$B$BNo puedo hacer nada más por él. Bueno, sí, podrías decirle que tengo unas cosas de Minahonda para él y que pase a recogerlas cuando tenga un rato.", t = "El envío perdido"},
    [893] = {ot = "Llévale 1 puñal Crines de Acero, 1 varita Crines de Acero carbonizada y 1 escudo de guerra Crines de Acero a Jironack Forjacero en Campamento Taurajo en Los Baldíos.", st = "Por lo que me han contado, los jabaespines Crines de Acero hacia el sur, más allá de la Tierra de Gigantes, no cuentan con herreros cualificados pero, al parecer, han empezado a desarrollar armas resistentes. Me gustaría ponerles la mano encima a varios tipos diferentes para aprender su técnica si fuera posible.$B$BSi deseas contribuir con honor a la Horda, tráeme algunas muestras de sus armas. Encuentra una daga de sus acechadores, una varita de sus videntes y un escudo de sus frenéticos bélicos. ¡Con eso debería bastar!", t = "Una selección de armas"},
    [894] = {ot = "Accede a la consola de control del laboratorio de investigación de Ventura y Cía.", st = "Ventura y Cía. ha montado un pequeño centro de investigación al norte de aquí, al sudoeste de El Fangal. No tengo muy claro qué hacen allí pero logré descubrir que están haciendo pruebas con algo llamado \"churumbele\".$B$BY digo yo, ¿qué leches es un churumbele? Bueno, sea lo que sea, quiero examinarlo, así que necesito que alguien me lo consiga.$B$BConseguí una copia de su manual de instrucciones del sistema de control, gracias al cual deberías poder encontrar la forma de desconectar el churumbele.", t = "El churumbele"},
    [895] = {ot = "Llévale la cabeza del barón Longavera a Gazlowe en Trinquete.", st = "¡SE BUSCA!$b$bBarón Longavera, capitán de El Temerario$b$bEl capitán Longavera de Gilneas lidera navíos de los Filibusteros de los Mares del Sur y se lo busca por piratería. ¡Los restos deben poder identificarse!$b$b-- Gazlowe", t = "SE BUSCA: Barón Longavera"},
    [896] = {ot = "Recupera la esmeralda ojo de gato de un sobrestante o un agente de Ventura y Cía para el maestro de muelles Vertipeluca en Trinquete.", st = "Como maestro de muelles de un puerto tan importante como Trinquete, siempre estoy al tanto de toda la información. Conozco absolutamente todo lo relacionado con el intercambio de mercancías y dinero entre este lugar y Bahía del Botín.$b$bLas últimas noticias que oí se relacionan con la Mina Pedrusco de Ventura y Cía., al noreste de El Fangal. Uno de los mineros descubrió una esmeralda del tamaño de un puño. Conozco a un par de compradores que estarían interesados en algo así, y estoy dispuesto a compartir las ganancias de la venta.", t = "La fortuna de un minero"},
    [897] = {ot = "Llévale la cabeza del Cosechador a Jorn Vidente del Cielo.", st = "Esta extraña criatura insectoide parece de un orden natural por fuera, como si no perteneciera a Los Baldíos.", t = "El Cosechador"},
    [898] = {ot = "Escolta a Gilthares Ramafuego de vuelta hasta Trinquete con el Capitán Solbrillante.", st = "¡Por fin! ¡Alguien que viene a rescatarme!$B$BNo puedo creer que hayas logrado superar a los guardias. Estos zelotes de Theramore están completamente desquiciados. Hundieron nuestro barco y a mí, el único superviviente, me encarcelaron. Me calificaron de enemigo y de amenaza para la Alianza.$B$B¡Yo! ¿Una amenaza para su gran farsa de Alianza? Solo era un marinero de un envío de licor de luna entre Trinquete y Bahía del Botín.$B$BPero basta de charla. Me ayudarás a volver a Trinquete, ¿verdad? Dime cuando estés $glisto:lista; y saldremos para allá.", t = "Escapar del fuerte"},
    [899] = {ot = "Lleva 60 colmillos de jabaespines erizapúas a Mankrik en El Cruce.", st = "Tal vez conozcas el dolor de la incertidumbre, tal vez no, $c. Pero recuerda esto: vengo aquí todos los días, desde el alba hasta el ocaso, oteando el horizonte en busca de más de esos monstruos. He matado a todos los hombres cerdo que encontré desde entonces, pero mi sed de sangre no está satisfecha. Quizás, en lugar de dirigirme al norte de El Cruce debí dirigirme a Taurajo.$B$BTú, $c... tú podrías ayudarme .$B$BMátalos. Mata a cuantos puedas. Tráeme sus colmillos y celebraremos sus muertes juntos.", t = "Consumido por el odio"},
    [900] = {ot = "Cierra la válvula de control de combustible, la válvula reguladora y la válvula de control principal y usa entonces de nuevo la consola de control.", st = "Ahora las tres válvulas de control están abiertas. Por los indicadores del panel de control cabe suponer que se deberían apagar antes de que se pueda apagar el dispositivo.", t = "El churumbele"},
    [901] = {ot = "Consigue la llave de la consola del manitas el Risitas para usarla en la consola de control.", st = "Una vez apagado el aparato, se puede abrir el panel de control y extraer el churumbele de la consola. Con todo lo demás listo, solo queda conseguir la llave que desbloquea la consola.", t = "El churumbele"},
    [902] = {ot = "Devuélvele el churumbele a Petardol en Trinquete.", st = "Al abrir el panel frontal de la consola de control se accede al denso cableado, conducciones y otros extraños mecanismos, la mayoría de los cuales no parece tener ninguna función práctica. Si se apartan y se mira hacia el interior de la consola, se verá el churumbele. Basta con tirar de él para sacarlo de su compartimento.", t = "El churumbele"},
    [903] = {ot = "Recoge 7 garras de merodeadores de la sabana para Sergra Espinoscura en El Cruce.", st = "Ahora es momento de buscar una presa que muerda fuerte. Los merodeadores de Los Baldíos son una raza resistente. Fuertes, ingeniosos, astutos... y mortales. Puedes encontrarlos en pastizales altos. Hay muchos al sudoeste de El Cruce.$B$BTen cuidado durante la cacería, $n. No querrás que el depredador se convierta en la presa.", t = "Merodeadores en Los Baldíos"},
    [905] = {ot = "Mata raptores solescama y recoge sus plumas. Usa las plumas en los 3 nidos de segadores. Vuelve con Sergra Espinoscura en El Cruce.", st = "Ahora la cacería se intensifica, $n. Es hora de derrotar a tu presa y encontrar su guarida.$B$BCaza a los raptores solescama en el sur. Mátalos y quítales sus plumas. Coloca las plumas en los nidos de los segadores al sudoeste del Oasis Estancado. ¡Muéstrales a sus hermanos que no les tienes miedo!", t = "Los segadores furiosos"},
    [906] = {ot = "Llévale la calavera de Lok a Thork en El Cruce, en Los Baldíos.", st = "Llévale la cabeza de Lok a Thork en El Cruce, $r. <Gruñe.> Debería saber lo que le ha ocurrido a mi tribu sin más explicaciones, ¡vaya!, y no es que él se creyera que Quebrantadientes tuviera nada que ver con <gruñe> tales cosas. Pero seguro que te recompensará por llevarle tan gran trofeo <gruñe.>$B$BSeguiré bendiciéndote con el poder de Agamaggan por todo el tiempo que permanezca en esta jaula, $r. Hasta entonces, adiós.", t = "Traidores"},
    [907] = {ot = "Llévale 3 unidades de sangre de truenagarto a Jorn Vidente del Cielo en el Campamento Taurajo.", st = "Bien, $n, ahora debes enfrentarte a los colosales truenagartos. Son fieras tan monumentales que el suelo de las llanuras tiembla bajo sus pisadas. Ten cuidado cuando luches contra ellos, un paso en falso y te aplastarían como a una hormiga.$B$BEncontrarás a los truenagartos en Los Baldíos del Sur. Se llaman morrotormenta, Tormentero y Tronatesta. Vuelve cuando los hayas vencido.", t = "Los truenagartos iracundos"},
    [913] = {ot = "Encuentra 1 halcón trueno, mátalo y llévale sus alas a Jorn Vidente del Cielo en el Campamento Taurajo.", st = "$n, el halcón trueno es un animal de lo más feroz. Ha llegado la hora de que te enfrentes a uno de ellos. Debes averiguar por donde andan y traerme sus alas como prueba de haber cazado a uno.$B$BHazlo y ya casi habrás acabado tus tareas conmigo.", t = "El chillido del halcón trueno"},
    [914] = {ot = "Lleva las gemas de Cobrahn, Anacondra, Pythas y Serpentis a Nara Ferocrín en Cima del Trueno.", st = "Los druidas de las Cuevas de los Lamentos, los Druidas del colmillo, son una aberración. Fueron parte de una orden de nobles druidas que pretendían sanar Los Baldíos, pero ahora tan solo pretender cambiar esta tierra para amoldarla a sus propios y retorcidos sueños.$B$BLos Druidas del colmillo tienen cuatro líderes, y cada uno de ellos posee una gema de sueño. ¡Sus rostros aún me siguen atormentando! Derrota a los líderes y tráeme sus gemas. Así Los Baldíos recuperarán la paz.$B$BVete, $n. Los encontrarás escondidos en las profundidades de las Cuevas de los Lamentos.", t = "Líderes del Colmillo"},
    [916] = {ot = "Lleva 10 glándulas de veneno de tejemadera a Gilshalan Caminaviento en Aldrassil.", st = "Vine a Cañada Umbría para observar a las arañas tejemadera que habitan en la Gruta Narácnida. Son primas de una variedad de arañas mucho más pequeñas; creo que el Árbol del Mundo las ha afectado profundamente, y me gustaría conseguir algunos especímenes para confirmar mi teoría.$B$BPrimero, necesito un poco de su veneno. Recoge glándulas venenosas de tejemadera de las arañas de la Gruta Narácnida en el norte. Así podré examinarlas y compararlas con el veneno de sus primas más pequeñas.", t = "Veneno de tejemadera"},
    [917] = {ot = "Llévale un huevo de tejemadera a Gilshalan en Aldrassil.", st = "Ahora que tengo el veneno de las arañas, me gustaría tener algunos especímenes para estudiar. Lamentablemente, capturar a una araña gigante viva es más de lo que puedo pedirte, joven $c. ¡Y una araña gigante es más de lo que puedo enfrentar sin ayuda!$B$BPero si encuentras un huevo en su etapa de gestación, será mucho más fácil obtener especímenes. Y luego podré idear algo para contener a las arañas que salgan de los huevos.$B$BDebe haber un nido en lo profundo de la Gruta Narácnida. Por favor, busca un huevo en el nido y tráemelo.", t = "Huevo de Tejemadera"},
    [918] = {ot = "Lleva 8 semillas de brezomadera a Denalan en el Lago Al'Ameth.", st = "Los brezomadera de Teldrassil son elementales de la naturaleza. En cierto modo, representan el orden natural de las plantas y los animales de nuestro gran árbol.$B$BPor eso es desagradable ver lo malhumorados que están últimamente.$B$BCreo que tiene que ver con la tierra. He estado trabajando en diferentes métodos de nutrición de plantas y me gustaría probarlos con semillas de brezomadera. ¿Podrías recoger semillas de brezomadera alrededor del Lago Al'Ameth y traérmelas?", t = "Semillas de Brezomadera"},
    [919] = {ot = "Lleva 12 brotes de brezomadera a Denalan en el Lago Al'Ameth.", st = "Están brotando pequeños Brezomadera alrededor de las aguas del Lago Al'Ameth. Me temo que ya no es posible ayudarlos por lo que deberíamos eliminarlos antes de que crezcan más y empiecen a causar problemas.$B$BCuando pases por el lago, si ves algún brote de Brezomadera, arráncalo. ¡Ayúdanos a mantener la tierra limpia!", t = "Brotes de Brezomadera"},
    [920] = {ot = "Habla con Tenaron Tormentagarre en Aldrassil, en Cañada Umbría.", st = "¿Eres $n? He oído que Tenaron te estaba buscando. Está en la sala más alta de Aldrassil.$B$BAunque es mejor tomarse la vida con calma, no lo hagas esperar demasiado.", t = "Las invocaciones de Tenaron"},
    [921] = {ot = "Llena la ampolla de cristal y devuélvesela a Tenaron Tormentagarre en la cima de Aldrassil.", st = "Es hora de que salgas a buscar tu destino, $n. Pero antes de que te aventures al mundo que se extiende más allá de nuestros bosques encantados, hay mucho que debes aprender sobre nuestra historia reciente.$b$bNuestro pueblo ha cambiado mucho desde la Batalla del Monte Hyjal. Nordrassil es una tenue sombra de lo que supo ser, su poder se consumió por completo para derrotar a Archimonde y expulsar a la Legión Ardiente...$b$bHay algo que debes hacer. Ve a la poza de la luna al norte de Aldrassil y vuelve aquí con una ampolla llena con sus aguas.", t = "La corona de la Tierra"},
    [922] = {ot = "Llévale una semilla de Brezomadera a Rellian Verdeguja en Darnassus.", st = "$n, ¿podrías llevarle una de las semillas que me trajiste a mi amigo Rellian Verdeguja? Es un druida de Darnassus, y la última vez que hablamos expresó su interés en mi trabajo con los brezomadera. Él había desarrollado algunas ideas propias, y estará agradecido si tiene una semilla de muestra para trabajar.$B$BGracias, $n. Has sido de gran ayuda. Espero que algún día veas el fruto de mi labor.$B$BLo más probable es que Rellian esté caminando por el Enclave Cenarion de Darnassus.", t = "Rellian Verdeguja"},
    [923] = {ot = "Lleva 5 tumores musgosos a Rellian Verdeguja en Darnassus.", st = "Hay algo malvado creciendo entre los brezomadera. Estamos intentando encontrar la fuente de ese mal, pero hasta que lo hagamos, debemos talar todos los brezomadera que ya no tengan remedio. Por el bien de Teldrassil. Los que vagan por el Lago Primigenio, al norte de Teldrassil, son los más afectados. ¡Hay que eliminarlos!$B$BDestruye todos los brezomadera que encuentres ahí y recoge los tumores musgosos que crecen en ellos. Tráelos para que podamos quemarlos.", t = "Tumores"},
    [924] = {ot = "Coge 1 piedra de energía imperfecta. Llévala al Altar de Fuego antes de que su energía desaparezca y vuelve junto a Ak'Zeloth.", st = "La Semilla del Demonio es una poderosa herramienta para la Legión Ardiente. Se encuentra en una caverna en la Cima Calígine, sobre un altar de fuego demoníaco.$B$BHe preparado piedras de energía que cuando se colocan cerca de la semilla interfieren en su conexión con la Legión.$B$BCoge una piedra de la mesa y llévala al altar de fuego en lo más alto de la Cima Calígine. Dirígete hacia el oeste, luego hacia el norte en el cruce de caminos. Verás la montaña a tu izquierda. La cara norte es la más segura de escalar.$B$BY date prisa, la energía de la piedra se agota con el tiempo.", t = "La Semilla del Demonio"},
    [926] = {t = "La piedra de energía con imperfecciones"},
    [927] = {ot = "Llévale el corazón musgoso a Denalan, que está en el Lago Al'Ameth.", st = "El corazón de Negromusgo el Fétido está recubierto de un musgo oscuro y grasiento. De hecho, se sabe que es un corazón porque late lenta y rítmicamente... Incluso ahora se sigue oyendo su latido.$B$BPuede que Denalan quiera verlo.", t = "El corazón musgoso"},
    [928] = {ot = "Lleva la vasija casi llena a Corithras Furia Lunar a Dolanaar.", st = "Aunque podría contarte mucho más de las Pozas de la Luna y de Teldrassil, debo dejarte ir; Corithras Furia Lunar te está esperando. He puesto el agua que has traído en esta vasija; llévasela.$B$BEstará en la Poza de la Luna de Dolanaar. Coge el camino del sur de Aldrassil al salir de Cañada Umbría y sigue los adoquines cuando el camino gira al oeste.$B$BTen cuidado, $n. Últimamente hay criaturas muy peligrosas en el bosque.", t = "La corona de la Tierra"},
    [929] = {ot = "Llena la ampolla de jade y devuélvesela a Corithras Furia Lunar en Dolanaar.", st = "Primero, deja que te cuente más sobre la tarea que debes completar. Los druidas de Darnassus usan el agua de las pozas de la luna de Teldrassil, que deben rellenarse de vez en cuando. Usando estas ampollas especiales puedes recoger agua de las pozas de la luna.$B$BToma esta vasija y ve hasta la poza de la luna que está a las afueras de la Aldea Brisa Estelar, al este. Llénala de agua y tráemela de vuelta. Cuando hayas terminado tu tarea, continuaré la historia desde donde Tenaron la dejó…", t = "La corona de la Tierra"},
    [930] = {ot = "Llévale el fruto resplandeciente a Denalan, que está en el Lago Al'Ameth.", st = "Un gran fruto redondo pende entre las hojas de esta resplandeciente planta.$B$BTienes la certeza de que a Denalan le gustaría analizarlo.", t = "El fruto resplandeciente"},
    [931] = {ot = "Lleva una fronda fulgurante a Denalan en el Lago Al'Ameth", st = "Las hojas de esta planta fulguran con la luz del bosque, creando un aura intermitente.$B$BCrees que a Denalan le gustaría tener una muestra.", t = "Fronda fulgurante"},
    [932] = {ot = "Mata a Lord Melenas y llévale su cabeza a Tallonkai Cruzarraíz en Dolanaar.", st = "Debo advertirte, $n, que este asunto debe quedar entre nosotros. Los sátiros ya son toda una vergüenza para nosotros, y este en concreto está demasiado cerca.$B$BSe llama Lord Melenas y habita en la cercana cueva de Roca Mácula, donde ha reunido a un numeroso grupo de guerreros grells. Su corazón es negro como la noche, pero lo que trama es incluso más repugnante.$B$BDebes encontrarlo en su cueva cercana, al norte de aquí, y traerme su cabeza.", t = "Odio enraizado"},
    [933] = {ot = "Llena la ampolla de turmalina y devuélvesela a Corithras Furia Lunar en Dolanaar.", st = "Hay otra poza de la luna al sudeste de la entrada a Darnassus, en las costas de los Estanques de Arlithrien. A los Centinelas se les está dificultando patrullar el área debido a los ataques y el malhumor de los fúrbolgs Tuercepinos que crece día a día.$b$bBusca la poza con cuidado, y ten tus armas bien a mano.", t = "La corona de la Tierra"},
    [935] = {ot = "Llévale la vasija llena al archidruida Fandral Corzocelada de Darnassus.", st = "Sin las bendiciones de Alexstrasza la Protectora y Nozdormu el Atemporal, el crecimiento de Teldrassil ha sido dificultoso. Se han visto bestias extrañas saliendo del suelo del árbol, y fúrbolgs enloquecidos que atacan a los viajeros.$b$bSolo espero que encuentren pronto la solución que busca el archidruida. Verteré todas las ampollas que trajiste en este contenedor y lo llevarás a Darnassus.$b$bEntrégaselo a Fandral Corzocelada, lo encontrarás en la arboleda de los druidas.", t = "La corona de la Tierra"},
    [937] = {ot = "Consigue 6 cinturones Sangrepluma y llévaselos a la centinela Arynia Quiebranubes de El Claro del Oráculo.", st = "Me enviaron aquí con un pequeño grupo de centinelas para proteger el Árbol del Oráculo de las arpías que han anidado en el claro. Poco a poco estamos intentando expulsarlas.$B$BCuando el Árbol del Oráculo envió a un mensajero a Darnassus con un informe, este fue atacado y asesinado por un grupo de arpías.$B$BSi te sientes $gcapacitado:capacitada; para esta tarea, ve a sus nidos y acaba con ellas, y después tráeme sus cinturones como prueba de ello.", t = "El claro encantado"},
    [938] = {ot = "Lleva a Niebla ante la centinela Arynia Quiebranubes que se encuentra en la Poza de la Luna situada cerca del Árbol del Oráculo.", st = "La piel de la dientes de sable es de un color gris característico que armoniza con el del bosque en el que se encuentra. Mientras permanece allí tendida, observas que está malherida, con profundas laceraciones en la espalda y el estómago.$B$BLevanta la cabeza y te observa fijamente, dejando ver a través de sus azules ojos la gran inteligencia que posee. Parece que desea seguirte.", t = "Niebla"},
    [940] = {ot = "Llévale la Corteza con inscripciones al archidruida Fandral Corzocelada de Darnassus.", st = "El bosque susurra tus osadas proezas, $n. Una vez expulsadas las arpías de sus nidos, el bosque vuelve a estar en calma y las criaturas que en él habitan se sienten de nuevo seguras. Temía enviar a otro mensajero al archidruida pero ahora sé que tú le harás llegar mi mensaje sin problema.$B$BEntrégaselo y el bosque te ofrecerá su protección en los caminos que conducen hasta el Bosque de Piedra.", t = "Teldrassil"},
    [941] = {ot = "Coloca el corazón máculo en la maceta de Denalan.", st = "He quitado el musgo que recubría el corazón pero aun así sigue estando sucio...$B$BPonlo en mi maceta y veamos qué pasa. Contiene tierra nutritiva que podría limpiar y purificar el corazón.", t = "Plantar el corazón"},
    [942] = {ot = "Lleva el fósil misterioso al arqueólogo Gargavino al Puerto de Menethil.", st = "Este fósil tiene un parecido notable con el que vi en Forjaz. Un arqueólogo llamado Gargavino lo trajo para nuestra conferencia anual de la Liga de Expedicionarios. Él creía que el fósil guardaba un poder que podía revelarse de alguna forma.$b$bLo último que supe fue que Gargavino se había refugiado en el Mesón Aguahonda del Puerto de Menethil, esperando por la escolta que lo llevaría a la Excavación de Whelgar. Búscalo y muéstrale el fósil de Tipirrem. Quizás pueda descifrar los secretos del pasado.$b$bEl barco hacia Menethil zarpa de Auberdine.", t = "El prospector despistado"},
    [943] = {ot = "El arqueólogo Gargavino, del Puerto de Menethil, quiere que le lleves la Piedra de Relu y el fósil de Gargavino.", st = "El fósil original lo tiene ahora el prospector Whelgar, en su excavación de Los Humedales. Cuando descubrí la Piedra de Relu, creía que era la clave para desvelar el misterio del fósil.$B$BCuando me dirigía a reunirme con Whelgar, fui atacado por raptores y perdí la reliquia. No sé cuál de esas bestias se tragó la reliquia pero, si la recuperas, podré liberar el poder de esos artefactos.$B$BTráeme la Piedra de Relu y el fósil original.", t = "El prospector despistado"},
    [944] = {ot = "Reúne información y luego utiliza una ampolla de adivinación para crear un cuenco de visión. Utiliza el cuenco para hablar con Onus.", st = "Es extraño que haya nagas aquí, en Costa Oscura. Pero aún más extraño es... lo del Martillo Crepuscular. Ese culto adora a los antiguos Señores de la Tierra, que fueron derrotados hace mucho tiempo.$B$BUno de ellos cayó en La Espada del Maestro, al sur de aquí.$B$BVe allí y busca a más adeptos del Martillo Crepuscular.$B$BLlévate esta ampolla de adivinación. Utilízala para crear un cuenco de visión cuando encuentres La Espada del Maestro. Y luego utilízalo para hablar conmigo.", t = "La Espada del Maestro"},
    [945] = {ot = "Ayuda a escapar a Therylune y luego dile a Therysil, en el Santuario de Aessina, que su hermana está a salvo.", st = "¡Socorro!$B$BEstaba paseando por La Espada del Maestro cuando esos asquerosos del Culto me rodearon. ¡Menos mal que se me da bien esconderme!$B$B¿Puedes ayudarme a salir de aquí? También necesito avisar a mi hermana Therysil de que estoy bien. Está al sur, en Vallefresno, en el Santuario de Aessina.", t = "La fuga de Therylune"},
    [947] = {ot = "Lleva 5 boletos rudos y 1 oronja verde a Barithras Sombra Lunar a Auberdine.", st = "Estoy ideando una poción para la que necesito unas setas muy raras, unas que solo crecen en una cueva determinada. Esa cueva se encuentra más allá del Salto de Fonroca, al este y un poco al norte por las montañas.$B$BIría hasta allí en persona, pero en el Páramo de los Ancianos me aconsejaron que me mantuviera lejos de ese lugar. Nuestros venerables aliados creen que la cueva es el refugio de un nuevo mal de Costa Oscura.$B$BTe lo ruego, $n, tráeme algunas de esas setas. Y aprovecha para explorar la cueva y confirmar los temores de los ancianos.", t = "La cueva de las setas"},
    [948] = {ot = "Ve al Páramo de los Ancianos y habla con Onus.", st = "Onus, un anciano del Conocimiento del Páramo de los Ancianos, ha sabido de tu viaje a Salto de Fonroca y desea hablar contigo. El Páramo se encuentra hacia el sur, cerca de las montañas.$B$BLos ancianos son pacientes y sabios, $n. Si Onus busca tu consejo sobre lo que viste en el Salto, temo que la cosa es urgente.", t = "Onus"},
    [949] = {ot = "Encuentra una pista en el campamento del Martillo Crepuscular en La Espada del Maestro.", st = "No se sabe qué motivos han llevado al Martillo Crepuscular a La Espada del Maestro. Pero sus motivos son, sin duda, oscuros.$B$BDebes ir a su campamento de La Espada. Busca algo que pueda arrojar un poco de luz sobre sus intenciones.$B$BPorque debemos saber cuáles son antes de preparar un plan.", t = "El campamento del Martillo Crepuscular"},
    [950] = {ot = "Lleva a Onus los garabatos incomprensibles que has encontrado.", st = "Mirar el Escrito Crepuscular es una locura. El texto empieza a bailar tras un momento, y la belleza se torna en formas grotescas.$B$BSolo te da tiempo a arrancar una hoja de garabatos incomprensibles antes de que te desvanezcas.", t = "Regresa junto a Onus"},
    [951] = {ot = "Lleva 6 reliquias de Mathystra a Onus al Páramo de los Ancianos.", st = "El papiro que encontraste en La Espada del Maestro es una página de un antiguo texto escrito por los elfos. Está terriblemente mancillado por la corrupción del Martillo Crepuscular, pero parece que el Culto está sirviéndose de una antigua magia élfica para devolver a sus maestros a nuestro mundo$B$BViaja hacia el noreste, hasta las Ruinas de Mathystra y busca antiguas reliquias entre los hierbajos y las piedras. Estudiándolas, podríamos averiguar cómo pretende explotar el Martillo Crepuscular la magia de los elfos.", t = "Las reliquias de Mathystra"},
    [952] = {ot = "Entrégale el mensaje de Fandral a Onus en el Páramo de los Ancianos en Costa Oscura, al sur de Auberdine.", st = "Si tuviste tiempo para hacer de $gmensajero:mensajera; para el Árbol del Oráculo, seguro que puedo persuadirte para que lleves un mensaje al Páramo de los Ancianos, en Costa Oscura, al sur de Auberdine.$B$BProbablemente, por motivos de seguridad, tengas que utilizar un hipogrifo como medio de transporte, pero confío plenamente en ti. Llévale esto a Onus, el anciano del Conocimiento. Ha estado a la espera de noticias mías, igual que yo he aguardado noticias de El Claro del Oráculo.", t = "El Páramo de los Ancianos"},
    [953] = {ot = "Estudia las tablillas que hablan de Ameth'Aran y de su caída y reúnete con la centinela Tysha Filoluna en Costa Oscura.", st = "Encontrarás las ruinas de Ameth'Aran hacia el este. Ahora las habitan los inquietos espíritus de los Altonato que en vida moraban entre sus muros, unos muros entre los que los siervos de Azshara practicaban libremente su poderosa magia.$B$BCuando me enviaron a explorar las ruinas encontré dos grandes tablillas con grabados que relataban la historia de Ameth'Aran y de su caída. Mientras leía las runas me abordaron los espíritus y tuve que huir.$B$BPor favor, si puedes, aventúrate entre las ruinas e intenta descifrar las tablillas en mi lugar.", t = "La caída de Ameth'Aran"},
    [954] = {ot = "Encuentra la fuente de la extraña aura azul en las Ruinas de Bashal'Aran.", st = "Las ruinas de Bashal'Aran, al este, están invadidas por esbirros demoníacos. Los espíritus y los sátiros que han establecido su morada en la zona se alimentan de la energía mágica del lugar. Sus poderes crecen continuamente.$B$BAun así, he notado que hay un santuario al que no se acercan jamás. En la parte occidental de las ruinas, sobre un pequeño acantilado, se ve una extraña aura azul... Debe haber una explicación a la reluctancia de los demonios.$B$BQuisiera que lo investigaras.", t = "Bashal'Aran"},
    [955] = {ot = "Consigue 8 pendientes de grell y llévaselos a Asterion a Bashal'Aran.", st = "Si tuviera que contar la historia de mi vida, sobrepasaría sin duda los límites de tu paciencia. Digamos que la mía ha sido una vida larga y atormentada y que esta forma espectral es el peor de los tormentos que he sufrido.$B$BLa magia me ata a este lugar. Mis palabras pueden sonar falsas, porque no habría palabras que expresaran mi agradecimiento si me ayudaras a averiguar cómo me retiene mi prisión. Me ata un sello y, examinando los pendientes de duendecillos y grells, quizás encuentre alguna pista que me lleve a él.", t = "Bashal'Aran"},
    [956] = {ot = "Consigue el sello de piedra lunar antiguo y llévaselo a Asterion a Bashal'Aran.", st = "Si los grells han entrado en contacto directo con el sello que me ata a mi prisión eterna, sospecho cuál podría ser la causa. Sin duda el sello está en poder del sátiro que los comanda.$B$BTengo el presentimiento de que es así, $n. Debe tenerlo uno de los sátiros. Si logras hacerte con él, me acercarías tanto al otro lado de los barrotes de mi prisión que me harías llorar.", t = "Bashal'Aran"},
    [957] = {ot = "Destruye el sello de piedra lunar antiguo en la antigua llama de Ameth'Aran y vuelve a reunirte con Asterion en Bashal'Aran.", st = "El sello que conforma mi prisión fue obra de uno de los Altonato más poderosos. En Ameth'Aran, al sur, hay unas ruinas idénticas a estas. En ellas persiste, incluso hoy, una antigua llama, una llama azul. Esa llama podría destruir el sello.$B$BPero no bajes la guardia en las ruinas, $n...", t = "Bashal'Aran"},
    [958] = {ot = "Reúne 7 reliquias de los Altonato y llévaselas a Thundris Tejevientos a Auberdine.", st = "$C. Tengo que pedirte un favor.$B$B¿Has visto las ruinas de Ameth'Aran? Si no las has visto, las puedes encontrar en el lado este del camino principal, viajando hacia el sur. En otro tiempo fueron el hogar de los poderosos Altonato. Hoy son testimonios de la destrucción que sus errores produjeron.$B$BLos centinelas me han dicho que los espíritus de los Altonato persisten y que aún poseen sus antiguos instrumentos mágicos. Hemos de hacernos con esas reliquias para poder destruirlas.", t = "Las herramientas de los Altonato"},
    [959] = {t = "¡A por la botella!"},
    [962] = {ot = "La boticaria Zamah de Cima del Trueno quiere que recojas 10 reptilias.", st = "La Sociedad Real de Boticarios, establecida en la gran Entrañas de Lordaeron, me ha enviado aquí con un propósito muy concreto, $n. Quizás quieras ayudarme a mí y, de paso, también a la Dama Oscura en nuestro intento de mejorar la forma física de los Renegados.$B$BÚltimamente he estado estudiando una extraña planta llamada reptilia y creo que en grandes cantidades tiene un gran potencial.$B$BLamentablemente, la reptilia solo se encuentra en los recesos más oscuros de las Cuevas de los Lamentos, un sistema de cuevas muy peligroso situado en Los Baldíos.", t = "Reptilia"},
    [963] = {ot = "Libera el espíritu de Anaia Correalba y lleva su colgante a Cerellean Zarpablanca a Auberdine.", st = "En el período que siguió a las batallas en el Pozo de la Eternidad, oí que Ameth'Aran había sido destruido y que su gente había muerto... y entre ellos, Anaia, mi amada.$B$BJamás habría pensado que, miles de años después, el recuerdo de Anaia seguiría atormentando mis sueños. Un día, deambulando por los bosques de Costa Oscura como en un letargo, me encontré en las ruinas de Ameth'Aran... y allí vi el espíritu atormentado de mi amada.$B$BDebo liberarla, pero me faltan las fuerzas. Sin embargo, su espíritu debe ser destruido.", t = "Un amor eterno"},
    [965] = {ot = "Encuentra a Balthule Tenebroso cerca de La Torre de Althalaxx en Costa Oscura.", st = "Saludos, joven $r. Soy Elissa Brisa Estelar y soy la encargada de proteger Auberdine de todo mal.$B$BCon tal propósito envié a Balthule Tenebroso a observar los extraños sucesos de la Torre de Althalaxx, al noreste.$B$BY ya debería haber regresado. Me preocupa que haya encontrado algún peligro imprevisto en el bosque. Apreciaría sobremanera que fueras en su busca y te aseguraras de que se encuentra bien.", t = "La Torre de Althalaxx"},
    [966] = {ot = "Reúne 4 papiros desgastados para Balthule Golpesombra acerca de La Torre de Althalaxx.", st = "Un grupo de brujos se ha instalado alrededor y dentro de la torre. Habría regresado a Auberdine a informar a Elissa, pero tenía miedo de perderme algo.$B$BDelgren sospechaba que una compañía como esta estaba reuniéndose en la torre, pero no sabía por qué.$B$BA mis manos han llegado algunos fragmentos de los papiros que llevan los brujos, pero necesito reunir más para resolver el enigma. Deja que te dé un consejo: no entres en la torre, los brujos que hay en ella son los más poderosos.", t = "La Torre de Althalaxx"},
    [967] = {ot = "Entrega la carta de Balthule a Delgren el Purificador que está en el Bosque de Vallefresno.", st = "Mi maestro, Delgren el Purificador es un paladín que ha ofrecido gentilmente su ayuda en la defensa de nuestros bosques de los demonios y los no-muertos. Me ha enseñado mucho sobre la Luz Sagrada y el arte de la guerra.$B$BDelgren debe saber de las operaciones del culto cuanto antes.$B$BLo encontrarás al sur de aquí, en la Atalaya de Maestra del Bosque de Vallefresno. Debes apresurarte: la amenaza de la Facción Oscura crece cada hora.", t = "La Torre de Althalaxx"},
    [968] = {ot = "Lleva el libro Los Poderes Subyacentes a Gerrig Agarrahueso a La Caverna Abandonada, en Forjaz.", st = "Aunque la cubierta de este libro está gastada y arañada, aún se puede leer el título:$B$BLos Poderes Subyacentes$B$BEn el interior del libro hay una lista de nombres impronunciables con títulos terribles, rituales de adoración y sacrificios preferidos... muchos de los cuales incluyen criaturas vivas, humanoides.$B$BEn la cubierta interior del libro hay unas palabras escritas: \"Runas y Maldiciones de Agarrahueso, La Caverna Abandonada, Forjaz. Propiedad de: Gerrig Agarrahueso.\"$B$BSi Agarrahueso vende libros de este tipo, quizás me vuelva a comprar este.", t = "Los Poderes Subyacentes"},
    [970] = {ot = "Reúne una gema de alma resplandeciente y vuelve junto a Delgren el Purificador en la Atalaya de Maestra.", st = "La carta de Balthule es espantosa. Este culto de la Facción Oscura es una espina clavada que debo eliminar. Me las he visto con algunos de los miembros de la Facción Oscura al noreste de este lugar, en Ordil'Aran. Uno de ellos posee una gema de almas que, creo, guarda el secreto del poder del culto.$B$BTráemela y podré descifrar el secreto de su interior.", t = "La Torre de Althalaxx"},
    [971] = {ot = "Lleva el manuscrito de Lorgalis a Gerrig Agarrahueso en la Caverna Abandonada de Forjaz.", st = "Como sabes, recopilo conocimiento. Conocimiento antiguo. Conocimiento poderoso. Conocimiento que abre puertas, y conocimiento que puede despertar a los Durmientes.$B$BHay rumores de un viejo conocimiento, el manuscrito de Lorgalis, que se encuentra en el fondo de las Cavernas de Brazanegra en Vallefresno. Es la vieja morada de elfos que murieron hace tiempo. Elfos que guardaban grandes saberes antes de que su ciudad cayera en la ruina.$B$BBusca el manuscrito en las Cavernas de Brazanegra. Si lo haces, no lo olvidaré. Ni siquiera después de... el fin de los tiempos.", t = "Conocimiento en las Cavernas"},
    [973] = {ot = "Llévale el Libro de Ilkrud Magthrull a Delgren el Purificador en la Atalaya de Maestra.", st = "Ilkrud Magthrull. Sí, sé algo acerca de él. Es un poderoso orco brujo que mora en el Santuario de la Escara, un lugar de extrema maldad al suroeste de Vallefresno.$B$BHasta ahora no había pasado de ser una molestia menor y no he tenido que tratarlo pero, por lo visto, ha llegado su hora.", t = "La Torre de Althalaxx"},
    [982] = {ot = "Recupera el arcón del Amanecer de Plata y el arcón del Halo de Bruma para Gorbold Mano de Acero de Auberdine. Ambos objetos deberían estar en los cascos de los navíos naufragados al norte de la aldea.", st = "En Costa Oscura, al norte de aquí, naufragaron dos barcos, el Amanecer de Plata y el Halo de Bruma. Hace un tiempo, los dos barcos fueron abordados por unos múrlocs cuando navegaban hacia Auberdine. Ahora yacen en el fondo del océano como trofeos de esos demonios.$B$BLos capitanes no sobrevivieron y sus cuadernos de bitácora y otros efectos aún siguen en sus cajas fuertes. Me gustaría que los recuperaras para nosotros. Es importante para los miembros de la tripulación que aún están por aquí.", t = "Profundo océano, mar inmenso"},
    [983] = {ot = "Reúne 6 patas de reptador y colócalas en la caja mecánica 827.", st = "¡Eh! Necesito ayuda con mi último invento, la caja mecánica. ¡Sirve para hablar con gente que está lejos!$B$BPuede que hayas visto alguna ya. Son unas cajas con muchas palancas. El problema que tienen es que necesitan un mantenimiento constante.$B$BCada una tiene un problema diferente, pero yo he hecho una cosa muy inteligente. He colocado cada caja cerca de las criaturas que tienen las piezas adecuadas para repararlas. Y ahora, hay que reparar la caja mecánica 827. Está al sur de Auberdine, muy cerca. Hacen falta 6 patas de reptador para arreglarla. Te pagaré...", t = "La caja mecánica 827"},
    [984] = {ot = "Encuentra el campamento de fúrbolgs corruptos en Costa Oscura, vuelve a Auberdine y busca a Terenthis.", st = "Algunos de mis hermanos fueron salvados de un fúrbolg corrupto en Teldrassil y yo he jurado impedir otras atrocidades. No permitiré que los nuestros resulten heridos... o algo peor.$B$BYa he detectado un par de indicios de corrupción en Costa Oscura, pero aún he de encontrar signos de que se haya extendido. Creo que lo lógico sería continuar la investigación con los fúrbolgs. ¿Podrías buscar alguno de sus campamentos y decirme si has visto algún signo de corrupción?", t = "La extensión de la amenaza"},
    [985] = {ot = "Mata a 5 soplavientos y a 8 abrecaminos Bosque Negro y vuelve a Auberdine a buscar a Terenthis.", st = "Ya has demostrado que sabes rastrear a nuestros enemigos, $n. ¿Crees que también podrás enfrentarte a ellos?$B$BLo pregunto porque algunos aventureros prefieren eludir el combate directo...$B$BSi crees que estás a la altura de la tarea, puedo decirte que la mayor amenaza para nuestra gente proviene del campamento que hay al sur de Auberdine. Allí encontrarás una parte de la tribu Bosque Negro. Mata a 8 abrecaminos y a 5 soplavientos y vuelve aquí.", t = "La extensión de la amenaza"},
    [986] = {ot = "Encuentra 5 pelambres de Acechalunas refinadas y llévaselas a Terenthis a Auberdine.", st = "$n, con tus habilidades me has ayudado mucho en mi empresa. ¿Podría abusar una vez más de tu buena disposición y pedirte que ayudes a Zarpadura y a su maestro Volcor? Puedo crear para ti una capa mágica que te permitirá caminar entre las criaturas de Costa Oscura sin ser $gdetectado:detectada;.$B$BPero para tener suficiente material para crear la capa necesitaré 5 buenas pelambres de algún patriarca acechalunas o de una matriarca acechalunas. Puedes encontrar felinos de esos al sur, cerca del Río Culebra o cerca de Vallefresno, más al sur todavía.", t = "El maestro perdido"},
    [990] = {ot = "Encuentra a Raene Correlobo en Vallefresno.", st = "$n, mi señora, Raene Correlobo, te espera en la ciudad de Astranaar en Vallefresno. Con tu ayuda, quizás podamos reducir algo la corrupción que allí se ha extendido.$B$BDirígete al sur desde aquí y mantente cerca de la carretera, llegarás allí sin problemas si sigues estas instrucciones.", t = "El camino de Vallefresno"},
    [991] = {ot = "Busca a Teronis en Vallefresno.", st = "$n, un viejo amigo mío está ayudando a las centinelas aquí en Vallefresno, pero aún no ha regresado.$B$BTiene pistas sobre el paradero de un objeto que podría frenar los ataques de los fúrbolg a nuestra gente: una vara creada por un hechicero ya fallecido.$B$BAntes de partir, mencionó que buscaba una gema para la vara.$B$BTambién dijo que la gema podría estar oculta en un santuario de Lago Falathim, al pie de la montaña al oeste. La gema estaba protegida ahí antes de que invadieran el lugar.$B$BEncuentra a mi amigo, $n, por favor.", t = "La limpieza de Raene"},
    [993] = {ot = "Encuentra a Volcor en Costa Oscura y dale la capa de Acechalunas encantada.", st = "La capa está acabada, $n. Ha llegado el momento de ir a buscar a Volcor. Solo espero que aún estemos a tiempo.$B$BLa magia de la capa, una vez convocada, no durará mucho... solo unos cinco minutos. Tú decides cuándo es la ocasión de utilizarla: pero yo sugeriría que esperaras hasta que encuentres a Zarpadura.$B$BSi lo que me ha dicho es verdad, encontrarás a su maestro en una cueva al sur de aquí. Zarpadura te estará esperando al lado del camino. Cuando lo veas, saluda con un ademán y él te señalará el camino hacia su maestro.", t = "El maestro perdido"},
    [995] = {ot = "Escapa de la cueva fúrbolg y reúnete con Terenthis en Auberdine.", st = "Muy bien... si no tienes dudas, salgamos de aquí. Partiremos cuando tú digas.$B$BY recuerda, cuando hayas escapado, busca a Terenthis en Auberdine. Yo iré hacia allí por mi cuenta. Probablemente me muevo más rápido que tú.", t = "Escaparse furtivamente"},
    [997] = {ot = "Llévale el paquete con tierras raras a Denalan, que está en el Lago Al'Ameth.", st = "¿Te diriges hacia el sur? ¿Al Lago Al'Ameth? De ser así hay algo que quiero pedirte...$B$BMi compañero Denalan tiene un campamento en el extremo oriental del lago, donde está estudiando y haciendo experimentos con la flora de Teldrassil. Encargó un paquete con tierras raras de Darnassus que llegó con retraso pues no hace mucho que lo recibimos aquí en Dolanaar.$B$B¿Podrías llevarle tú el paquete?", t = "Las tierras de Denalan"},
    [1001] = {ot = "Consigue 3 ojos de trillador de los trilladores de Costa Oscura en las profundidades del mar, cerca de la caja mecánica 411.", st = "Del interior de la máquina sale una vocecita.$B$B\"¡Soy Zumbang! La siguiente caja mecánica está al norte de Auberdine, en la playa.$B$BEs la número 411 y requiere 3 ojos de trillador para ser reparada. ¡Están cerca de la costa! Los trilladores de Costa Oscura... *Hip*... Uy, perdón...$B$BComo la vez anterior, cuando le das los artículos a la caja mecánica, te escupe tu recompensa. *Hip*... ¿Qué? No, ¡estoy bien!\"", t = "La caja mecánica 411"},
    [1002] = {ot = "Reúne 6 colmillos de Acechalunas y colócalos en la caja mecánica 323.", st = "La caja mecánica sufre un ataque estático y Zumbang empieza a hablar.$B$B\"La siguiente caja mecánica es la 323. Está al norte de Auberdine pero..., ¿dónde está la cerveza? ¿Qué? Ah, está por el camino, cerca del puente. No deberías tener problemas.\"$B$BZumbang murmura algo incoherente y luego le oyes tragar escandalosamente.$B$B\"Esta necesita colmillos de Acechalunas... 6 en total.\"", t = "La caja mecánica 323"},
    [1003] = {ot = "Consigue 4 cueros cabelludos grisáceos de los osos cardo grisáceos del sur de Auberdine y colócalos en la caja mecánica 525.", st = "Por encima de los ruidos que provienen de la máquina, oyes la voz de Zumbang que te llama.$B$B\"La shiguiente eshtá al shur, por el camino. No deberías tener problemas para encontrarla... jushto al lado d'un eshcondite... cerca de un pantano. Creo que la eshcondí en unosh robushtosh... Digo, arburshtosh. Je, je, je... Shí, la caja mecánica 525 neceshita cuerosh cabelludosh grisháceohs de los Oshos Cardosh esos. ¡Tuercash! ¡Qué bocado! Grisháceosh... Je, je, je...\"$B$BLa máquina traga y traga y se desconecta. Y, de repente, vuelve a la vida.$B$B\"¡4!\"", t = "La caja mecánica 525"},
    [1007] = {ot = "Lleva la estatuilla antigua a Talen en su campamento cerca de la Ensenada de Zoram.", st = "Debo pedirte algo, $n.$B$BEstaba en mi pequeña embarcación, explorando las ruinas sumergidas de Zoram, cuando los nagas me atacaron. ¡Salieron del agua y se lanzaron sobre mí con sus garras! Hui con los suministros que pude salvar hasta este miserable campamento.$B$BPero cuando llegué a la costa y hui... perdí mi posesión más preciada.$B$BPor favor, $n, encuentra el sitio de mi emboscada, en la costa del norte, y busca una estatuilla antigua. Es la única razón por la que enfrenté los peligros de la Ensenada de Zoram.", t = "La estatuilla antigua"},
    [1008] = {ot = "Llévale 20 cabezas de Colafuria a Shindrell Fuegoveloz en Astranaar.", st = "El mal nos acecha desde la costa noroeste conocida como La Ensenada de Zoram.$B$BEs el lugar de descanso de la ciudad maldita de Zoram, destruida en el Diluvio y desde entonces sumergida bajo los mares. Se perdió para los elfos de la noche durante siglos. Perdida y casi olvidada.$B$BAhora, los nagas han regresado y en cuanto a sus motivos... los ignoramos. Pero el porqué importa poco; debemos ejecutar a estos desalmados ¡y devolverlos a los abismos!$B$BVuelve a mí cuando hayas completado tu misión.", t = "La Ensenada de Zoram"},
    [1009] = {ot = "Lleva el anillo de Zoram a Talen cerca de la Ensenada de Zoram.", st = "Temo que los secretos de las estatuillas antiguas permanecerán ocultos para siempre a menos que encuentres las llaves de su cerradura antigua.$B$BELa llave es un anillo, el anillo de Zoram. Les perteneció a los gobernadores de la ciudad antes de que las olas del Cataclismo la hundieran.$B$BDurante años, la ubicación del anillo fue un misterio, pero los naga lo encontraron hace poco.$B$BSu líder, Ruuzel, habita en una isla en la frontera norte de Zoram. Por favor, $n, ¡recupera el anillo por mi!", t = "Ruuzel"},
    [1010] = {ot = "Lleva 5 cabellos de Bathran a Orendil Hojagrande en Vallefresno.", st = "Hay una planta que solía crecer en las viejas Ruinas de Bathran al norte. La planta se llamaba cabello de Bathran, y era conocida por curar los males del espíritu.$B$BHay una niña enferma en la aldea, y creo que no se trata de una simple afección física. ¿Podrías ir a las Ruinas de Bathran y buscar cabello de Bathran? Puede que lo necesite para el tratamiento.$B$BLas Ruinas de Bathran están al norte de la Atalaya de Maestra y al sur de la frontera con Costa Oscura.", t = "Cabello de Bathran"},
    [1011] = {ot = "Llévale una botella de enfermedad a Kayneth Ventoleve en Canción del Bosque.", st = "Los Renegados, el brazo de no-muertos de la Horda, se han infiltrado en Vallefresno y merodean entre nuestras ruinas y túmulos. Creemos que su objetivo es propagar enfermedades por la tierra de los elfos de la noche. ¡Tenemos que saberlo con seguridad!$B$BLos Renegados tienen un campamento al sur de este lugar, cerca de El Túmulo de Dor'danil, donde crean venenos y enfermedades y los embotellan. Infíltrate en su campamento y roba una botella de enfermedades. Vuelve con esa botella. La probaré y averiguaré para qué sirve.", t = "Los males de los Renegados"},
    [1013] = {ot = "Lleva el Libro de Ur al vigilante Bel'dugur al Apothecarium de Entrañas.", st = "$n, en el Castillo de Colmillo Oscuro hay un libro que deseo para mi colección: el Libro de Ur. Ur era un gran mago de Dalaran antes de que llegara la Plaga; sus estudios sobre otros mundos son muy valiosos para... ciertas facciones entre los Renegados.$B$BVe al Castillo de Colmillo Oscuro y tráeme el libro. Informaré a la Dama Oscura de tus servicios...", t = "El Libro de Ur"},
    [1014] = {ot = "Mata a Arugal y lleva su cabeza a Dalar Tejealba en El Sepulcro.", st = "Arugal sigue viviendo en el Castillo de Colmillo Oscuro. No podemos reclamar Argénteos como bastión estratégico para la Dama Oscura hasta que no hayamos matado a Arugal.$B$BMe encargaré de erradicar su magia, $n. Pero dejo en tus manos que Arugal se encuentre con la muerte que tanto merece.$B$BVe al Castillo de Colmillo Oscuro y pon fin de una vez por todas a los terribles hechizos de Arugal. ¡Tráeme la cabeza del malvado mago!", t = "Arugal debe morir"},
    [1016] = {ot = "Recoge 5 brazales elementales intactos y usa el pergamino de adivinación sobre ellos. Después, llévaselo a la centinela Velene Golpe Estelar en el Refugio Brisa de Plata.", st = "Lleva este pergamino de adivinación, tal vez revele al creador de los elementales. Pero necesitarás algo de ellos para usar como componente y concentrar la magia del pergamino. Sus brazales deberían servir.$B$BCon unos brazales intactos de las criaturas debería bastar. Los demás brazales no servirán a nuestros propósitos, pero tal vez puedas vendérselos a un mercader. Cuando tengas los brazales intactos, usa el pergamino. Vuelve a verme con los resultados y luego continuaremos.", t = "Brazales elementales"},
    [1017] = {ot = "Mata a Sarilus Fuenteviciosa y lleva su cabeza a la centinela Velene Golpe Estelar en el Refugio Brisa de Plata.", st = "Solo hay un mago no-muerto en Los Baldíos capaz de envilecer a tantos elementales de agua. También es el único lo suficientemente inconsciente para intentarlo. Sarilus Fuenteviciosa probablemente se encuentre en la cumbre de Cima Calígine, riéndose de mí.$B$B$N, debes aventurarte en territorio enemigo y acabar con ese bellaco. Ya estoy cansada de su insensatez y tenemos que demostrarle lo que les ocurre a quienes irritan a las centinelas.$B$B¡Destrúyelo y tráeme su cabeza! Ve con cuidado, la Horda podría estar vigilándote.", t = "Mago invocador"},
    [1020] = {ot = "Llévale la cura de Orendil a Pelturas Lunablanca en Astranaar.", st = "$n, he desarrollado una cura que tal vez ayude a la niña enferma. Lleva la cura a Astranaar y dásela al padre, Pelturas Lunablanca.$B$BPara llegar a Astranaar, sigue el camino sur y luego gira al este.", t = "Cura de Orendil"},
    [1021] = {t = "¡Vil sátiro! ¡Dríades en peligro!"},
    [1022] = {ot = "Ve a la Vega del Aullido y estudia el libro de Mel'Thandris. Luego, regresa con la centinela Melyria Sombrigélida en el Santuario de Aessina.", st = "Aunque hemos puesto muchos recursos y esfuerzo en expulsar hacia el norte a los demonios restantes en Frondavil, no hemos tenido mucho éxito. Hemos logrado mantener apartados de Vallefresno a casi todos los demonios.$B$BHacia el norte, cerca de los límites de Frondavil, el altar en ruinas de Mel'Thandris ha sido tomado por unos misteriosos hombres lobo. Sus llamadas te hielan la sangre y han hecho que se conozca esa zona como la Vega del Aullido. Es posible que el Libro de Mel'Thandris que se conserva en el altar arroje algo de luz sobre el motivo que ha traído a estos hombres lobo.", t = "La Vega del Aullido"},
    [1023] = {ot = "Busca la gema resplandeciente y regresa a ver a Raene Correlobo en Astranaar con el diario de Teronis.", st = "Mientras investigas las pertenencias de Teronis, encuentras un diario que aún está en buenas condiciones.$B$BTomas el diario y dejas el cuerpo de Teronis en su lugar.$B$BSolo falta encontrar la gema que buscaba Teronis. Raene dijo que estaba en el área. Quizá los múrlocs la tengan...", t = "La limpieza de Raene"},
    [1024] = {ot = "Busca a Shael'dryn en la poza de la luna al noreste.", st = "Tendrás que encargarte de la investigación tú $gmismo:misma;, pero según las notas de Teronis, parece que tu próxima tarea es buscar las demás piezas de la vara creada por Dartol. Te sugiero que comiences en la poza de la luna al este del Lago Iris. Cuando estés $glisto:lista;, sigue el camino y gira al norte al llegar a una área de descanso a tu izquierda.$B$BAllí hay una dríade llamada Shael'dryn que podrá ayudarte. Búscala.$B$BLleva la gema contigo: Shael'dryn la necesitará para ayudarte a reforjar la vara.", t = "La limpieza de Raene"},
    [1025] = {ot = "Mata a 1 vigía del cubil, 2 ursas, 10 totémicos y 12 guerreros de la tribu de los Maderiza y vuelve junto a Raene Correlobo en Astranaar.", st = "Antes de que vayas a la Poza de la Luna, tengo otra tarea que ayudará al pueblo de Vallefresno si te apetece poner a prueba tus habilidades.$B$BPor la carretera que va hacia el este antes de llegar al Río Falfarren, los fúrbolgs han estado asaltando a los viajeros. Sus torturadas mentes alimentándose del miedo y su apetito saciándose con sangre inocente.$B$BAyuda a las centinelas a proteger las tierras mostrando hacia esos monstruos la misma misericordia que ellos para con los de nuestra clase.$B$BMe parece que sus campamentos están al sur de la carretera... ve con cuidado.", t = "Una defensa agresiva"},
    [1026] = {ot = "Encuentra la llave de madera y una pieza de la vara de Dartol antes de regresar con Shael'dryn en la poza de la luna.", st = "Ojalá tus nuevas fueran mejores.$B$BRaene tiene razón, he oído hablar de la creación de Dartol y de los antárboles de la región, al menos una vez. Ahora se han corrompido, su naturaleza se ha pervertido.$B$BSi quieres encontrar la próxima parte de la vara, tendrás que encontrar la llave que abre el cofre en el que se encuentra.$B$BLa llave de madera está en uno de los antárboles al noreste desde aquí, cerca de Frondavil. Cuando la tengas, busca un pequeño claro al oeste del camino cerca de la frontera de Frondavil... El cofre debería estar escondido por ahí.", t = "La limpieza de Raene"},
    [1027] = {ot = "Encuentra la última pieza de la vara de Dartol y regresa con Shael'dryn en la poza de la luna.", st = "La última pieza de la vara fue entregada a los druidas de Dor'danil para que la protejan. No sé dónde la escondieron. Lamento no poder ayudarte más.$B$BSolo puedo decirte que sigas el camino que lleva a Los Baldíos. Los druidas se refugiaron al este de ese camino, pero no podrán ayudarte: los mataron hace poco... No me gusta hablar de eso.$B$BCuando encuentres la última pieza, tráemela y te ayudaré a reconstruir la vara.", t = "La limpieza de Raene"},
    [1028] = {ot = "Encuentra el Santuario Oculto y encanta de nuevo la vara de Dartol.", st = "Aquí tienes la vara completada, $n. Volver a construirla ha sido sencillo... encontrar el santuario que tiene el poder para cargarla de nuevo será la parte complicada.$B$BCentrándote y con un poco de empeño, no debería ser demasiado difícil para alguien como tú, con tantos logros en tu haber.$B$BDirígete al sureste desde aquí, hay muy pocos caminos, así que ten cuidado, y mantén la vista hacia el norte. El santuario se encuentra oculto en las montañas que rodean este claro.$B$BUna vez allí, coloca la vara en el interior del santuario... el resto es magia. Je, je.", t = "La limpieza de Raene"},
    [1029] = {ot = "Vuelve junto a Raene Correlobo en Astranaar.", st = "Te sugiero que encuentres a Raene y le digas que la vara está terminada. Ella sabrá por dónde debes continuar.$B$BBuena suerte, $n.", t = "La limpieza de Raene"},
    [1030] = {ot = "Busca un fúrbolg sin corromper y usa el poder de la vara de transformación de Dartol para hablarle.", st = "Me temo que no estoy completamente seguro de lo que planeaba hacer a continuación.$B$BSi lo que dijo sobre el poder de la vara era cierto, significa que te permite asumir una forma completamente nueva. Aunque no sé cuál.$B$BTal vez quería usar los poderes para acercarse a los fúrbolgs corrompidos, pero hasta las criaturas no corrompidas pueden masacrarlo en un descuido. Transformado por la vara, Dartol tendría que hablar con un fúrbolg que esté a salvo de los efectos del musgovil.$B$BDeberías comenzar tu búsqueda al sudeste del Lago Mystral.", t = "La limpieza de Raene"},
    [1031] = {ot = "Mata a Geltharis y vuelve a ver a Illiyana con la rama de Cenarius en el Santuario de Aessina.", st = "Anilia te pone las manos en los hombros y te acerca. Entre jadeos, señala el arco al norte, antes de que sus ojos se cierren y el último soplo de vida salga de su boca. \"Se la ha llevado... Geltharis...\" En tu corazón sabes que el deseo póstumo de Anilia es que la Rama de Cenarius vuelva a las manos de la dríade.", t = "La Rama de Cenarius"},
    [1032] = {t = "¡Muerte a los sátiros!"},
    [1033] = {ot = "Lleva la lágrima de Elune a Pelturas en Astranaar.", st = "Esperaba que la cura de Orendil salvara a Relara, pero me temo que solo ha frenado su enfermedad. ¡Tenemos que encontrar una medicina más eficaz! Por suerte, Orendil me habló de otros remedios para probar en caso de que el suyo no funcionara.$B$BLa lágrima de Elune es un tipo de piedra que solo se encuentra en un lugar: la isla del Lago Iris, al este de Astranaar. Orendil dijo que la piedra se llevaría la corrupción... Por favor, $n, ¡tráeme la lágrima de Elune y reza para que acabe con la enfermedad de mi niña!", t = "Lágrima de Elune"},
    [1034] = {ot = "Llévale 5 puñados de polvo estelar a Pelturas en Astranaar.", st = "La lágrima de Elune logró curar en parte la enfermedad de mi hija. Tiene menos pesadillas y le estoy agradecido a la diosa por su bendición. Pero... sigue teniendo la fiebre muy alta.$B$BOrendil me habló de un polvo de escarcha que se encuentra en Las Ruinas del Polvo Estelar. Quizás mitigue la fiebre de Relara. Te ruego que consigas un poco de ese polvo y me lo traigas.$B$BLas Ruinas del Polvo Estelar se encuentran en el sur, $n. Que Elune haga breve tu viaje.", t = "Las Ruinas del Polvo Estelar"},
    [1035] = {ot = "Recupera una piedra lunar caída del Oráculo Sombramatorral y llévasela a Pelturas en Astranaar.", st = "La fiebre de Relara ya queda atrás, pero todavía sigue débil. No creo que con el tiempo solamente logre recuperar la energía perdida. Creo que va a necesitar la energía de una piedra lunar.$B$BLas solíamos recoger en el Lago Cielo Estrellado, al sureste... hasta que los Sombramatorral llegaron.$B$BSu líder, un oráculo Sombramatorral, recogió todas las que había y las esconde como su tesoro. Tu misión consiste en recuperar una.$B$BY para hacerlo, creo que deberás matar al líder.", t = "Lago Cielo Estrellado"},
    [1037] = {ot = "Habla con Thyn'tel Tejespada en el Bancal del Guerrero en Darnassus.", st = "Velinde Cantoestelar era mi predecesora aquí en el Bosque de Vallefresno. Al principio parecía que tenía la situación en Frondavil bajo control pero poco a poco sus esfuerzos flaquearon. Un buen día desapareció sin más.$B$BMe enviaron aquí para continuar su trabajo. Aunque me temo que no sé nada de la sacerdotisa. Quizás Thyn'tel Tejespada, una Comandante de las centinelas, sepa algo sobre su desaparición que no me haya comentado.$B$BSeguro que entenderá la trascendencia de tal información.", t = "Velinde Cantoestelar"},
    [1038] = {ot = "Busca el diario de Velinde en su cofre y llévaselo, junto con la llave, a Thyn'tel Tejespada a Darnassus.", st = "¿El Libro de Mel'Thandris te enseñó esto? Supongo que no hacemos daño a nadie si te permito examinar sus pertenencias. Esta llave abre el cofre en el que ella guardaba sus cosas en el barracón de centinelas. Llevaba un diario de servicio. Si hay algo que aprender por aquí, estará en su diario.$B$BDebería decirte que los centinelas creen que tenía sus propias razones para irse y esperan que vuelva en cualquier momento. La sacerdotisa ha demostrado en el pasado que merece toda nuestra confianza.", t = "Las pertenencias de Velinde"},
    [1039] = {ot = "Ve a Trinquete y habla con el maestro de muelles Vertipeluca.", st = "Trinquete es el único puerto de Los Baldíos. Seguramente Velinde encontró un navío mercante en Trinquete que la llevó a la Cala Aguasnegras, en Azeroth. Hemos tratado poco con los goblins que llevan el puerto, pero el capataz del puerto debería tener información sobre los barcos de pasajeros.$B$BSigue el camino del sureste que atraviesa Vallefresno y te encontrarás en Los Baldíos. Pero ve con cuidado, $n. Hay guerreros de la Horda patrullando esa tierra. En el puerto estarás a salvo.", t = "El puerto de Los Baldíos"},
    [1045] = {ot = "Mata a 4 guardias Sangradientes y llévale la calavera de Ran Sangradientes a Krolg, cerca del Lago Mystral.", st = "Los elfos de la noche existen desde tiempos remotos, pero su arrogancia está destruyendo su propio mundo. Y ahora también amenaza nuestras vidas. Pero eso no es posible controlarlo...$B$BCulpo a los elfos por eso, pero aún somos responsables de nuestras acciones. Incluso más allá de la corrupción, somos capaces de provocar un mal terrible.$B$BRan Sangradientes es un claro ejemplo de ese mal. Sediento de poder, lleno de avaricia... La corrupción solo lo ha fortalecido. Detesto a los elfos con todo mi ser, pero no le deseo el mal a sus niños, por lo que debemos controlar a los nuestros.", t = "La limpieza de Raene"},
    [1046] = {ot = "Lleva calavera de Ran Sangradientes y la vara de transformación de Dartol a Raene Correlobo en Astranaar.", st = "Vuelve con tu propia tribu y cuéntales de tu victoria aquí.$B$BMuéstrales tu trofeo y báñate con la gloria...", t = "La limpieza de Raene"},
    [1054] = {ot = "Llévale la calavera de Dal Zarpasangrante a Raene Correlobo en Astranaar.", st = "Directamente al norte de Astranaar están los fúrbolgs Piel de Cardo. Mis exploradores me informan de que en los últimos meses han aumentado mucho sus efectivos. Si acaban siendo demasiados, podrían envalentonarse y atacar directamente Astranaar.$B$BMata a tantos de su clase como puedas pero tráeme la calavera de su jefe como prueba de que hemos reprimido el movimiento... por ahora.$B$BSeguiré aquí en Astranaar y esperaré tus noticias. Que Elune esté contigo.", t = "Matanza selectiva"},
    [1055] = {ot = "Vuelve junto a Shael'dryn en la Poza de la Luna.", st = "La vara, ahora completa, está en tus manos. Shael'dryn se alegrará al enterarse de tu éxito.", t = "La limpieza de Raene"},
    [1056] = {ot = "Ve junto al vigilante Albagorm en la Cima del Espolón.", st = "Según los espíritus del bosque, eres valiente y no te importa viajar.$B$BHacia el sur, cerca del Lago Mystral, se encuentra un túnel conocido como El Paso del Espolón. Este túnel lleva a una zona llamada Risco Cortaviento en Sierra Espolón. Cuando llegues allí, prosigue tu camino hacia el suroeste hasta pasar el Lago del Peñasco, dirígete entonces hacia el norte por una cuesta empinada hasta alcanzar la Cima del Espolón.$B$BAllí aguarda el vigilante Albagorm. Presta atención a su encargo, $r.$B$BEl viaje será peligroso.", t = "Viaje a Cima del Espolón"},
    [1057] = {ot = "El vigilante Albagorm en la Cima del Espolón quiere que mates a 6 arpías Furia Sangrienta, a 6 emboscadoras Furia Sangrienta, a 6 destripadoras Furia Sangrienta y a 6 malaplumas Furia Sangrienta.", st = "Como $gprotector:protectora; de los espíritus, sin duda sabrás por qué siento tanta inquietud.$B$BHas viajado a través de estas montañas para llegar a la cumbre. Seguro que has visto la parodia en la que se ha convertido esta tierra. La codicia ha llevado a la destrucción de estas colinas sagradas.$B$BEl ambicioso ejército de industriales mecanizados, incendió La Vega Carbonizada, al sur. Peor aún, los Furia Sangrienta que han invadido la tierra, nos niegan el paso para comenzar a reconstruir.$B$B¡Expulsa a las malvadas arpías, $n!", t = "La reconquista de La Vega Carbonizada"},
    [1058] = {ot = "El médico brujo Jin'Zil en Malaka'jin quiere 5 porciones de savia del Espolón, 5 mostachos Crepusculares, 30 ojos de trotadores y una escama de dragón hada.", st = "¡Qué bien, qué bien!$B$B¡Tres cajitas para tres elfitos! ¿Pero qué haremos con nuestros simpáticos amiguitos \"abraza-árboles\"? Mmm... Démosles un poco de... ¿Cómo la llaman...? ¡Magia del bosque!$B$B¡Necesitaré un buen montón de savia del Espolón! Tráeme algunos mostachos Crepusculares de esos horribles felinos. Y muchos ojos de trotadores... Nunca se puede tener suficientes ojos de trotadores. Oh, y que no nos olvidemos, una preciosa escama de dragón hada.$B$B¡Vete rápidamente a la Cima del Espolón, $n! Así podré crear algo de magia del bosque.", t = "Magia del bosque de Jin'Zil"},
    [1060] = {ot = "Entrégale la carta de Darsok a Jin'Zil en su cueva de Malaka'jin, en Espolón.", st = "Has hecho un gran trabajo para mí, $n. Eres como una pata de conejo de la suerte y eso es algo que siempre me alegro de ver.$B$BLas arpías no son de los alrededores de Los Baldíos. Proceden de un lugar llamado Espolón, muy lejos al noroeste desde aquí. Aunque es probablemente un lugar peligroso para ti, necesito que le entregues esta misiva a un viejo amigo que vive allí, un médico brujo que responde al nombre de Jin'Zil.$B$BSe alegrará de saber que Serena Sangrepluma ha muerto y creo que Espolón te parecerá un lugar interesante.", t = "Carta para Jin'Zil"},
    [1061] = {ot = "Habla con Seereth Petrajada en Sierra Espolón.", st = "Los espíritus de Sierra Espolón están enojados por la intrusión de los goblins y sus siervos. Por eso la tierra se ha lamentado y aquellos que aún escuchan han oído su súplica.$B$BSe envió a Seereth Petrajada, una prometedora chamán de la Horda. Nos dijo que los goblins están deforestando la tierra a gran velocidad y pidió ayuda.$B$BVe a Sierra Espolón a hablar con ella; su campamento está cerca de la Vega del Gran Bosque. Lo mejor será que sigas el camino hacia el oeste desde El Cruce, en Los Baldíos.", t = "Los espíritus del Espolón"},
    [1062] = {ot = "Mata a 15 leñadores de Ventura y Cía. y vuelve a ver a Seereth Petrajada, en la frontera entre Espolón y Los Baldíos.", st = "Ventura y Cía, la empresa dirigida por goblins, se ha establecido en Sierra Espolón y ha estado talando árboles y quemando enormes franjas de bosque. Los espíritus de este lugar están obnubilados de dolor y furia. ¡Debemos detener a Ventura y Cía!$B$BDirígete al noroeste, más allá de Vega del Gran Bosque y hacia Risco Cortaviento. Encontrarás a los goblins y a sus sirvientes trabajando. Muéstrales que la Horda no permitirá la explotación de Espolón. Asegúrate de hacerlo en el idioma que ellos comprenden mejor...$B$BLa violencia.", t = "Los invasores goblin"},
    [1063] = {ot = "Habla con Magatha en Cima del Trueno.", st = "Para conectar realmente con los espíritus de Espolón, debemos consultar con los ancestros tauren.$B$BNo sé el nombre de muchos de los líderes, pero sí conozco uno: Magatha. He oído que es muy vieja y muy sabia. Si hay alguien que pueda conseguir ayuda espiritual de los tauren, es ella.$B$BMagatha vive en la capital tauren de Cima del Trueno, en el Alto de los Ancestros. En el risco que queda al noreste de la ciudad. Habla con Magatha y cuéntale el peligro que corre Sierra Espolón.", t = "La bruja anciana"},
    [1064] = {ot = "Habla con la boticaria Zamah en las Pozas de las Visiones de Cima del Trueno.", st = "Los tauren tienen un vínculo con la tierra y me apena conocer la difícil situación de Espolón pero me temo que para salvar a la tierra primero debemos eliminar el mal que la puebla.$B$B¿No es una suerte, pues, que los Renegados sean nuestros aliados? Ellos saben mucho del mal y creo que podrán ayudarnos. De ese modo, reforzarán la confianza entre nuestros pueblos.$B$BHabla con la boticaria Zamah, una erudita y emisaria de los Renegados. La podrás encontrar en las Pozas de las Visiones, al pie del Alto de los Espíritus.", t = "Ayuda de los Renegados"},
    [1065] = {ot = "Entrégale la nota de Zamah al boticario Lydon, que está en Molino Tarren.", st = "Para liberar a Espolón de Ventura y Cía., debemos tomar medidas extremas pero evitar el derramamiento de sangre.$B$BPuede que un colega mío tenga lo que necesitamos. Su nombre es Lydon y se encuentra en la ciudad de Molino Tarren en las Laderas de Trabalomas, en la lejana tierra de Lordaeron.$B$BPara llegar a Trabalomas viaja en zepelín hasta nuestra capital, Entrañas. Después ve en dirección norte a los Claros de Tirisfal, al sudeste hasta Argénteos y en dirección sur para llegar a Trabalomas.$B$BBusca a Lydon y entrégale esta nota en la que se detalla todo lo que necesitamos.", t = "Viaje a Molino Tarren"},
    [1066] = {ot = "Lleva 5 viales de sangre inocente al boticario Lydon de Molino Tarren.", st = "Voy a crear una toxina que drene la violencia de Ventura y Cía.; así se volverán débiles y dóciles. Eso solucionará el problema de la Horda en Sierra Espolón.$B$BPero necesito sangre inocente, que es difícil de conseguir.$B$BPor suerte, la Hermandad, que es un grupo de maleantes humanos de esta zona, emplea a magos de la sombra, que recolectan sangre inocente para sus turbios propósitos.$B$BLos encontrarás en el Castillo de Durnholde, al sureste de aquí.", t = "Sangre inocente"},
    [1067] = {ot = "Lleva la toxina de Lydon a la boticaria Zamah de Cima del Trueno.", st = "Aquí está la toxina. Tendrá un efecto favorable, quizás incluso contagioso, en Ventura y Cía. ¡Me emociona ver una demostración práctica de mi trabajo!$B$BPero antes de usarla, llévasela a la boticaria Zamah. Tiene que diseñar un proceso que intensifique el efecto de la toxina.", t = "Regreso a Cima del Trueno"},
    [1068] = {ot = "Destruye las sierras XT:4 y XT:9, a continuación vuelve a ver a Seereth Petrajada, en la frontera entre Sierra Espolón y Los Baldíos.", st = "Existe una relación entre la magia espiritual de los chamanes y la magia natural de los druidas. Este es el motivo por el que los chamanes podemos oír los pedidos de Espolón. Muchos de sus susurros ya no puedo oírlos, pero hay un mensaje, una visión, que es muy clara...$B$BVi dos máquinas con forma de hombre en Risco Cortaviento, al noroeste de Vega del Gran Bosque, talando árboles a una velocidad imposible. ¡Debemos detener a estas bestias metálicas!$B$BEn mi visión, las máquinas estaban marcadas con unos símbolos extraños:$B$BXT:4 y XT:9.", t = "Las sierras XT:4 y XT:9"},
    [1069] = {ot = "Llévale 15 huevos de Musgondo a Mebok Mizzyrix en Trinquete.", st = "¡Las tortillas de huevos de araña están causando furor en Bahía del Botín! Solo hay un problema... no hay huevos en Bahía del Botín.$B$B¡Puedo oler la oportunidad!$B$BLa araña Musgondo vive en el Risco Cortaviento y en el Cañón Sishir, en Sierra Espolón hacia el noroeste. Tráeme sus huevos ¡y te pagaré un dineral!$B$BEn el Risco Cortaviento, los huevos estarán cerca de lo que quede de arboleda.$B$BEn el Cañón Sishir... bueno, si no tienes un estómago a prueba de bomba, quizás debas limitarte a recolectar los huevos en el Risco Cortaviento...", t = "Huevos de araña musgondo"},
    [1070] = {ot = "Encuentra a Kaela Lanzasombra contemplando la vista del valle a la entrada del Risco Cortaviento, en Sierra Espolón.", st = "Hola, $n.$B$BPareces tener ansias de conocer mundo. ¿Has estado en Sierra Espolón? Es una tierra apestada por Ventura y Cía. y otros enemigos de los elfos nocturnos.$B$BRecientemente, la centinela Correlobo envió a mi amiga Kaela Lanzasombra allí para investigar lo que está pasando en la tierra, pero todavía no sé nada de ella. Y me preocupa mucho, porque la Alianza envió a un mago gnomo con ella... y eso es sin duda una señal de problemas.$B$B¿Podrías encontrarla y venir a informarme?", t = "Estar de guardia en Espolón"},
    [1071] = {ot = "Mata a 10 leñadores de Ventura y Cía. y a 10 deforestadores de Ventura y Cía. A continuación, vuelve a ver a Gaxim Silvóxido en Espolón.", st = "Verás, $n, soy miembro de la Asamblea Iluminada de Arcanología, Alquimia e Ingeniería, y mi objetivo... no, ¡mi DEBER!... es demostrar a esos elfos de la noche, que la unión de magia, combinaciones y mecanismos puede ayudarles a salvar sus bosques.$B$BPero se trata de una guerra dura, ¡y, por lo visto, esos goblins se reproducen como conejos! Ni siquiera he tenido tiempo de construir mis últimos inventos.$B$BNecesito algo de tiempo para planear y organizarme. Pero, para ello, necesito que me ayudes a mantener a raya a los goblins en el Risco Cortaviento, al este...", t = "Una tregua para el gnomo"},
    [1072] = {ot = "Habla con Lomac Destrabaengranajes en Forjaz.", st = "El dispositivo en el que estoy pensando, es la versión más avanzada hasta la fecha. Pero necesitaremos una poción especial para que funcione. Y creo que también podríamos intentar ir a lo grande, porque esta podría ser tu última misión.$B$BY, para eso, vamos a necesitar explosivos potentes: nitromirgliceronio.$B$BEl único que puede hacer NG-5 es un viejo amigo mío: Lomac Destrabaengranajes. Búscalo en Ciudad Manitas.$B$BConvéncelo para que nos haga NG-5. Me pondré a trabajar en mis dispositivos.", t = "Un viejo colega"},
    [1073] = {ot = "Lleva 4 pociones de maná menores y 2 elixires de entereza menor a Lomac Destrabaengranajes en Forjaz.", st = "¡Ja, ja, ja! ¿Necesitas nitromirgliceronio para evitar que los goblins destruyan un bosque?$B$BNo me importa si conoces a Gaxim o no... Te lo daré solo para verte a ti, o a los otros, explotar en un millón de trocitos.$B$BPero hay un problema: me he quedado sin NG-5.$B$BPero mira, si me traes las pociones correctas, te prepararé lo que necesitas ahora mismo.$B$BLo mínimo que podías hacer es demostrar tu habilidad como $gboticario:boticaria; antes de que te dé una muestra de mi mejor creación.", t = "Ineptitud + Productos químicos = Diversión"},
    [1075] = {ot = "Encuentra a Collin Mauren en Ventormenta.", st = "Muy bien y, ahora, la parte de detonación remota de mi plan... Oh, eso no te lo he explicado todavía, ¿no?$B$BPues en resumen se trata de esto: con un poco de magia, puedo conseguir que los explosivos exploten cuando tú no estés cerca. Estoy creando un dispositivo que te permitirá, tan solo con pulsar un botón, hacer que el NG-5 explote.$B$BPero necesito un hechizo de un amigo de Ventormenta... Collin Mauren. Le encontrarás en el Barrio de los Magos. Es un humano, así que no deberías tener problemas para encontrarle.", t = "Un pergamino de Mauren"},
    [1076] = {ot = "Lleva restos de demonio de polvo a Collin Mauren en Ventormenta.", st = "Ah, creo que ya lo tengo. Un hechizo mensajero... Creo que ese es el efecto que está buscando.$B$BTendré que hacer un pergamino donde grabar el hechizo. Para ello, necesitaré restos de un demonio de polvo.$B$BMientras reúno el resto de los componentes, ¿qué te parece si vas a los Páramos de Poniente a buscar a una de esas malvadas criaturas? Los demonios de polvo son peligrosos, pero seguro que puedes encargarte de algo así si estás $gdispuesto:dispuesta; a someterte a uno de los experimentos de Gaxim.$B$BEstaré aquí cuando vuelvas.", t = "Demonios en los Páramos de Poniente"},
    [1078] = {ot = "Lleva 8 escamas cristalizadas a Collin Mauren en Ventormenta.", st = "Todos los viajeros siguen preguntándome por Sierra Espolón. Parece ser un lugar muy popular para aventureros... No importa si buscas dracoleones, elementales, o tienes algo que hacer con Ventura y Cía.$B$BEn La Vega Carbonizada, en Espolón, solía haber una especie de basiliscos cuyas escamas, al molerlas, producían un increíble componente para alguno de los hechizos que he creado.$B$BSi esos basiliscos siguen con vida, me encantaría conseguir algunas escamas.$B$BTómate tu tiempo, no corre prisa, pero puedo pagarte generosamente.", t = "Escamas cristalizadas para Mauren"},
    [1085] = {ot = "Habla con Gaxim.", st = "La situación aquí, en Espolón, es obviamente grave para que una elfa de la noche y un gnomo estén trabajando juntos.$B$BVentura y Cía. ha devastado estas tierras y yo he pasado la mayor parte de mi tiempo intentando poner fin a la destrucción.$B$BNo juzgues a Gaxim prematuramente. Comprende la necesidad que tenemos de trabajar juntos.$B$BSi quieres ayudarnos, empieza por hablar con Gaxim.$B$BSiento no poder enviarte de vuelta a ver a Tara con buenas noticias todavía. Quizás pronto...", t = "Estar de guardia en Espolón"},
    [1086] = {ot = "Lleva el nublador tóxico al aeropuerto de Ventura y Cía. e informa a la boticaria Zamah.", st = "La toxina ya está lista. Solo queda entregarla. Y eso te toca a ti, $n.$B$BVentura y Cía. tiene que disponer de un sistema para enviar mensajes y paquetes ligeros entre su administración central y las operaciones de Sierra Espolón. Probablemente sea un aeropuerto, no lo bastante grande para un zepelín, pero sí para un transportador aéreo. Recorre las zonas de influencia de Ventura y Cía. en Sierra Espolón y encuentra el aeropuerto. Si lo localizas, planta la toxina.$B$BY sal de ahí inmediatamente.", t = "El aeropuerto de máquinas voladoras"},
    [1087] = {ot = "Mata a 4 Hijos de Cenarius, 4 Hijas de Cenarius y 4 botánicas Cenarion para Braelyn Manofuego, cerca del Refugio Roca del Sol.", st = "No puedes ni imaginarte el odio que siento por esta tierra maldita. Los de Cenarius y los druidas kaldorei de la cima, utilizan sus patéticos poderes para reprimir el flujo de la magia, incluso muy lejos, al sur de sus patéticas posesiones... sus amados bosques.$B$BYo podría regresar a Jaedenar y regocijarme con el flujo de la magia, pero mi maestro no me permite volver hasta que no haya finalizado mi trabajo.$B$BNo me cabe la menor duda de que sientes tanto aprecio por los elfos de la noche y sus pequeños aliados como yo. Ayúdame y ambos quedaremos satisfechos.", t = "El legado de Cenarius"},
    [1088] = {ot = "Lleva la cabeza de Ordanus a Braelyn Manofuego cerca del Refugio Roca del Sol.", st = "Creyeron poder detener el flujo de la magia. Se equivocaron. Creyeron que podían ocultar a Ordanus, ¡pero conseguiré su cabeza!$B$BLa magia me otorga la visión verdadera. Sí... ahí está. Una encrucijada... En la copa de un gran árbol en el Bosque de Vallefresno. Un nombre... Algaba. Uno de los hijos mayores del dios del bosque. Le hicieron desaparecer de la cima antes de que pudiera encontrarle, pero se está quedando sin tiempo.$B$BTráemelo y compartiré contigo un poderoso regalo.", t = "Ordanus"},
    [1090] = {ot = "Consigue el misterioso mineral de Piznik cuando termine de extraerlo.", st = "¿Sabes? Una vez fui la segunda persona más importante de este lugar. Pero todo cambió con la llegada de Gerenzo. Despidió a mi jefe, Ziz Fizziks, y me envió a trabajar a las minas. Sin embargo, Ziz me dijo que permaneciese aquí y reuniese algo de información. Su nuevo jefe nos pagará bien si podemos descubrir los planes de Gerenzo.$B$BDe todas formas, lo que sí sé es que Gerenzo ha ordenado excavar grandes cantidades de su mineral dorado verdoso. Puedo conseguirte una muestra para que se la lleves a Ziz, pero tendrás que vigilar por si aparecen patrullas mientras lo hago.", t = "Órdenes de Gerenzo"},
    [1092] = {ot = "Lleva la mena sin identificar a Ziz Fizziks, en Sierra Espolón.", st = "Supongo que también debería pensar en cómo salir de aquí. Las noticias de lo ocurrido aquí no tardarán en llegar a los de arriba y seguro que no van a estar muy contentos al verme de nuevo.$B$BSaldré a hurtadillas para encontrarme con Ziz. Con suerte, ¡podrá encontrarme otro trabajo!$B$BVoy a intentar arreglar un poco este desastre, pero deberías llevar la muestra del mineral a Ziz ahora mismo. Me dijo que iba a establecer su campamento en alguna parte del lado oeste del Risco Cortaviento. Buena suerte.", t = "Órdenes de Gerenzo"},
    [1093] = {ot = "Consigue los planos de la Súper Segadora 6000 para Ziz Fizziks en Sierra Espolón.", st = "Es terrible lo que Ventura y Cía. ha hecho aquí, ¿verdad? ¿En qué estaban pensando? ¡Una compañía goblin contratando a un gnomo!$B$BPor suerte para mí, Petardol puede distinguir a un genio en cuanto lo ve. ¡Me contrató justo después de que me despidieran!$B$BMe dice que han construido una enorme máquina cortaleña y Petardol quiere que robe los planos para él. El problema es que Gerenzo, maldito gnomo, me quiere muerto... Quizás tú podrías robar los planos por mí... Seguro que los lleva encima alguno de sus operadores.", t = "Súper Segadora 6000"},
    [1094] = {ot = "Entrega el sobre lacrado a Petardol en Los Baldíos.", st = "Este sobre contiene toda la información que conseguí conseguir antes de que me echaran a patadas... Documentos internos de Ventura y Cía., algunos manuales, cosas técnicas... Oh y, por supuesto, los planos de la Súper Segadora 6000.$B$BPetardol vive en Trinquete, en Los Baldíos. No creo que tengas problemas para encontrarle, es pequeñito y verde.", t = "Más instrucciones"},
    [1095] = {ot = "Lleva las nuevas órdenes a Ziz Fizziks en Sierra Espolón.", st = "El asunto de este gnomo contratado por Ventura y Cía. ha provocado algo de revuelo en Minahonda. Los grandes comerciantes no aprueban la asociación de Razdunk con el tal Gerenzo.$B$BRiddlevox me ha pedido que me ocupe del problema y seguro que la orden viene de los grandes comerciantes. Por supuesto, el Director no me lo ha dicho. Digamos que... tengo un presentimiento.$B$BSea como fuere, hay que apartar a Gerenzo y eso parece una prueba a la medida de Fizziks.", t = "Nuevas instrucciones"},
    [1096] = {ot = "Lleva el brazo mecánico de Gerenzo Silbillave a Ziz Fizziks, en Sierra Espolón.", st = "Una vez vi a Gerenzo, pero te diré algo, es difícil de mirar... Su carne parece podrida y tiene injertos de metal y engranajes por todo su cuerpo. Ha reemplazado algunos de sus miembros por otros mecánicos.$B$BGerenzo vigila toda la zona, desde el noreste de aquí, más arriba del Lago del Peñasco, cerca de la noria. Yo no podría llegar hasta ahí arriba, por no mencionar enfrentarme a Gerenzo... Pero tú pareces muy capaz de hacerlo.$B$BSi le matas por mí, ¡te recompensaré!", t = "Gerenzo Silbillave"},
    [1097] = {ot = "Habla con Grimand Elmore.", st = "Hay un enano forjador de armas en Ventormenta, Grimand Elmore, que ha enviado un mensaje diciendo que necesita ayuda con una entrega. Creo que quiere enviar un paquete a su hogar, en el norte.$B$B¡Tienes unas piernas muy fuertes! Si te interesa ponerlas en marcha, vete a hablar con Grimand. Podrías sernos muy útil aquí, pero también debemos mantener nuestros tratos con los enanos.$B$BPuedes encontrar a Grimand Elmore en la tienda de armas del Distrito de los Enanos de Ventormenta, en la sección noreste de la ciudad.", t = "La tarea de Elmore"},
    [1098] = {ot = "Encuentra a los mortacechadores Adamant y Vincent.", st = "Estamos preparando un ataque a Colmillo Oscuro y enviamos a dos mortacechadores a investigar. De eso hace ya muchos días ¡y necesitamos su informe para preparar el ataque!$B$B$n, tienes que ir al Castillo de Colmillo Oscuro, hacia el sur, y localizar a los mortacechadores Adamant y Vincent. Ayúdalos si lo necesitan.$B$BEsta misión es tan peligrosa como crítica, $n. No falles.", t = "Mortacechadores en Colmillo Oscuro"},
    [1100] = {ot = "Lee el diario de Henrig Soliceja.", st = "Abres lentamente el desgastado diario de Henrig Soliceja...", t = "El diario de Soliceja"},
    [1101] = {ot = "Llévale el medallón de Filonavaja a Díscolo Falfindel de Thalanaar.", st = "¡Pobre Heralath! Y el enano Soliceja, ¡qué valiente era!$B$BNo debemos permitir que su valentía caiga en el olvido. Hay que detener a esa malvada... Charlga Filonavaja.$B$BSin duda, infiltrarse en el Horado es arriesgado pero no hay tiempo para enviar noticias a Darnassus. $n, reúne un equipo para matar a Charlga.$B$BTráeme el medallón de Filonavaja como prueba de su defunción.", t = "La bruja del Horado"},
    [1102] = {ot = "Llévale el corazón de Filonavaja a Auld Picopiedra, que está en Cima del Trueno.", st = "Cairne es un líder noble que ha unido a nuestro pueblo aquí en Cima del Trueno.$B$BPero no puedo perdonar a aquellos que nos han echado de nuestras tierras ancestrales. Mi pueblo habitó en Los Baldíos del Sur durante décadas, una tierra que era sagrada para nosotros, hasta que numerosos enemigos nos expulsaron de ellas.$B$BEl destino le depara venganza a Charlga Filonavaja, que tiene a un ejército congregado en Horado Rajacieno.$B$BTráeme el corazón de Filonavaja y podré morir en paz, $n.", t = "Un destino vengador"},
    [1109] = {ot = "Llévale una pila de guano del Horado al maestro boticario Faranell en Entrañas.", st = "Como puedes comprobar, $n, tenemos unos interesantes experimentos entre manos aquí en la Sociedad Real de Boticarios.$B$BDado que yo soy el maestro aquí, mi trabajo consiste en supervisar nuestros proyectos de alquimia más ambiciosos. ¡Hay tanto trabajo y tan poco tiempo!$B$BParece que tienes muchos kilómetros a tus espaldas, $c, así que quizás puedas ayudarnos.$B$BNecesito una sustancia no muy común y un tanto nauseabunda que proviene de una extraña especie de murciélagos que solo se encuentran en ese agujero apestoso conocido como Horado Rajacieno. Tráeme el guano de los murciélagos del Horado para que podamos ponernos manos a la obra.", t = "Guano del Horado"},
    [1111] = {ot = "Lleva el pedido de piezas de Kravel al Maestro de muelles Vertipeluca en Trinquete.", st = "Mi trabajo consiste en proporcionar a los demás lo que necesitan, y en este caso los gnomos me han hecho un pedido de piezas. Las piezas llegaron a Trinquete hace una semana pero yo no he podido ir a recogerlas.$B$BAsí pues, ¿te apetece ir a dar un paseo? Ve a Trinquete y entrégale este pedido de piezas al maestro de muelles Vertipeluca, que seguramente esté en el puerto.$B$BHaz esto por mí y te encargaré más trabajos.$B$BTrabajos, $gamigo mío:amiga mía;, que te reportarán grandes beneficios...", t = "Maestro de muelles Vertipeluca"},
    [1112] = {ot = "Lleva las piezas de Kravel a Kravel Karbarbán en el Desierto de Sal.", st = "Aquí está el paquete para Kravel, $n. Cuando se lo entregues, dile que si quiere más pedidos especiales ¡tendrá que correr con los gastos!", t = "Las piezas de Kravel"},
    [1131] = {ot = "Llévale la costilla de Metaleador a Melor Pezuña Pétrea, que está en Cima del Trueno.", st = "A veces se caza para conseguir alimento, otras por honor e incluso se puede cazar para aprender las lecciones que enseña la Madre Tierra.$B$BPero la caza que yo te encargo no pertenece a ninguno de estos tipos. Se trata de matar a una criatura que no cuenta con la bendición de la Madre Tierra.$B$BLa hiena Metaleador vaga por Las Mil Agujas, al sur de Los Baldíos. Es un tirano que intenta atraer a otras hienas y que infunde miedo a otras criaturas más pacíficas, provocando un derramamiento de sangre.$B$BEncuentra a Metaleador, $n. Encuéntralo y derrótalo.", t = "Metaleador"},
    [1134] = {ot = "Lleva 12 sacos de veneno de alaorgullo a Shindrell Fuegoveloz en Astranaar.", st = "No tenemos la guerra declarada a la Horda, pero nuestra paz es frágil. A menudo encontramos a sus agentes actuando en nuestra contra, pero lo hacen encubiertamente.$B$BNos enteramos de uno de esos avances mediante unas fuentes ocultas en Theramore, decían que los orcos recogen veneno de las alaorgullo, cerca del Lago Mirkfallon en Sierra Espolón, hacia el sur. Los asesinos orcos utilizan el veneno en sus asaltos secretos contra la Alianza.$B$BSi esto es cierto, debemos detenerlos, $n. Tenemos que impedir que accedan a su fuente de veneno.", t = "Alaorgullo del Espolón"},
    [1138] = {ot = "Reúne 6 trozos de cangrejo de gran calidad para Gubber Blump de Auberdine.", st = "Adoro los cangrejos. ¡Los cangrejos son el fruto del mar! Puedes asarlos, hervirlos, guisarlos, hacerlos a la plancha... Se hacen en sartén, en olla, en hogueras... Y también hay ensalada de cangrejo, sopa de cangrejo, guiso de cangrejo, cangrejo a la pimienta, cangrejo al limón y cangrejo-sorpresa de Forjaz. Creo que no me dejo nada.$B$BPero ahora estoy pescando. No voy a conseguir ningún cangrejo. Se pueden conseguir de reptadores de arrecife y de reptadores de marea escamados. Y se pueden hacer mil cosas con ellos. Puedes asarlos, hervirlos, guisarlos, hacerlos a la plancha...", t = "Rico marisco"},
    [1140] = {ot = "Libera las almas de los Altonato atrapadas en la Senda de la Noche y en Satyrnaar y vuelve junto a Delgren el Purificador en la Atalaya de Maestra.", st = "La letra de los orcos es un poco mejor que los garabatos de un niño. Muchos de los de mi orden se burlaron cuando decidí aprender su lengua pero me ha resultado de provecho tener un conocimiento más profundo de mis enemigos.$B$BPor los garabatos de Ilkrud, parece que Athrikus aún posee dos gemas de almas que se guardan en la Senda de la Noche y en Satyrnaar, áreas bajo el dominio de los sátiros al noreste de Vallefresno.$B$BVe con cuidado, $n, los templos de los sátiros bañados en sangre pueden ser perturbadores hasta para $gun:una; $c $gcurtido:curtida; como tú.", t = "La Torre de Althalaxx"},
    [1141] = {ot = "Pesca 6 meros de Costa Oscura para Gubber Blump de Auberdine.", st = "Me encanta pescar. Los Blump somos una famosa familia de pescadores. Yo soy Gubber Blump. Yo también pesco.$B$BEn esta zona hay un pez que me gusta pescar: el mero de Costa Oscura. Yo solía salir en un barco a pescar meros, pero desde que aparecieron los múrlocs, ya no sale ningún barco. Además, seguro que los múrlocs se han comido todos los meros.$B$BOye, ¿quieres ayudarme a pescar un mero de Costa Oscura? Si lo haces, ¡te daré una auténtica caña de pescar de la familia Blump! Es una caña estupenda para pescar.", t = "La familia y la caña de pescar"},
    [1142] = {ot = "Encuentra el colgante de Treshala Arroyobarbecho y llévaselo a Darnassus.", st = "No voy a durar mucho... Estoy débil.$B$BEl valiente enano Cimahuraña ha ido a advertir a Falfindel...$B$BAntes de morir, quisiera...$B$BSe han llevado el colgante de vínculo de mi esposa, Treshala...$B$BEncuéntralo, por favor... Llévaselo a Treshala a Darnassus...$B$BY dile que he... muerto.", t = "Decaída mortal"},
    [1144] = {ot = "Escolta a Willix el Importador hasta que salga del Horado Rajacieno.", st = "¡Al fin llegó la ayuda!$b$bNo sabes cuánto tiempo he estado aquí. No recuerdo la última vez que vi el exterior.$b$bVerás, soy un emprendedor. Siempre busco cómo ganarme una moneda. Supe que Mebok Mizzyrix pagaba bien por los tubérculos de hierba roja de este chiquero. Creí que podría entrar y marcharme de inmediato. Como verás, ¡estaba un poquito equivocado!$b$bPero bueno, si fueras tan amable como para sacarme de aquí, te aseguró que valdrá la pena.", t = "Willix el Importador"},
    [1145] = {ot = "Entrégale la nota lacrada de Korran a Belgrom Destrozarroca en Orgrimmar.", st = "Muchos viajeros que han pasado por El Cruce me han ayudado a recoger huevos de la Tierra de Gigantes y muchos de ellos podrán contarte historias de lo peligrosas que son esas bestias. Yo ya he oído las suficientes como para poder afirmar que esos insectos representan una amenaza mayor de lo que mis maestros pensaban.$B$BNecesito enviar a un mensajero a Orgrimmar, a ver a Belgrom Destrozarroca. No se trata de un asunto cualquiera por eso necesito que vaya alguien que se tome esta tarea en serio.$B$BBelgrom suele andar por las inmediaciones de la Casa de la Hermandad de Guerreros.", t = "El enjambre crece"},
    [1146] = {ot = "Entrégale la nota lacrada de Belgrom a Moktar Krin en Las Mil Agujas.", st = "Por lo que veo, Korran ha llegado a la misma conclusión que yo acerca de esos insectos... parece que representan una amenaza mayor de lo que yo pensaba.$B$BHace unos días, un cazador regresó agonizante de Las Mil Agujas. Formaba parte de un destacamento de asalto enviado a El Desierto de Sal para expulsar de allí a un equipo de excavación formado por enanos. Durante el ataque, empezaron a salir insectos de una cueva que formaba parte de la excavación y casi acaban con todo el destacamento.$B$BEstaban liderados por Moktar Krin y se han refugiado en la frontera de El Desierto de Sal. Llévale esta nota.", t = "El enjambre crece"},
    [1149] = {ot = "Si tienes fe, salta desde las tablas que dominan Las Mil Agujas.", st = "¿Me has estado buscando o quizás ha sido el destino el que te ha traído a mí? No tiene importancia... Ahora estás aquí y tu viaje encontrará un nuevo punto de partida.$B$BSon muchas las facetas que conforman un ser, tanto su espíritu como su cuerpo y su mente. Algunas de ellas son mensurables por las tradiciones de una cultura. Otras, sin embargo, solo podemos esperar que encuentren un lugar dentro de nosotros. Si no te opones, pondré a prueba algunas de tus facetas.$B$BSi superas las pruebas, te harás más fuerte. De lo contrario, descubrirás la inmensidad de El Vacío Abisal.$B$BLa primera es una prueba de fe.", t = "Prueba de fe"},
    [1150] = {ot = "Llévale la garra de Grenka a Dorn Acechallanos, que está en Las Mil Agujas.", st = "Me alegra ver que tu valentía permanece imperturbable ante lo que ya has hecho. Ya que tu fe está intacta, ha llegado el momento de poner a prueba tu cuerpo.$B$BLa primera prueba es de resistencia. Ve con algunos amigos a Guarida Malapluma al oeste de Poblado Viento Libre. Intérnate en las profundidades de su guarida y destruye sus provisiones. De esa forma, habrás provocado su furia, y si logras sobrevivir lo suficiente, la mismísima Grenka Aullasangre vendrá a buscarte. Mátala y tráeme su garfa para completar la prueba.", t = "Prueba de resistencia"},
    [1151] = {ot = "Llévale fragmentos de Rok'Alim a Dorn Acechallanos, que está en Las Mil Agujas.", st = "En los tiempos de los dioses antiguos, los elementales ocupaban la mayor parte de este mundo. Ellos veneraban a los dioses antiguos y estos, haciendo uso de su poder, relegaron a los elementales a este mundo. Cuando los dioses antiguos desaparecieron, los elementales se desvanecieron de nuestro mundo y ahora solamente regresan cuando los poderosos magos requieren su presencia.$B$BAun así, hay algunas excepciones. Algunos elementales eran más poderosos y consiguieron permanecer aquí por su cuenta. Uno de ellos es Rok'Alim.$B$BPara poner a prueba tu fuerza, encuentra a Rok'Alim en Las Mil Agujas y acaba con él.", t = "Prueba de fuerza"},
    [1153] = {ot = "Arrebátale una muestra bruta de mena a un cavador o a un perito Gravamorro y llévasela a Jironack Forjacero al Campamento Taurajo de Los Baldíos.", st = "$C, me has ayudado con eficacia en el pasado. El Jefe de Guerra está satisfecho con mis logros y quiere que continúe con renovada determinación. Según me dicta mi honor, informaré al Jefe de Guerra de tu valía para que te otorgue el reconocimiento que te mereces. Pero antes he de pedirte que me ayudes otra vez.$B$BRecientemente han llegado unos viajeros del sur, de un lugar llamado Las Mil Agujas. Estos afirman que allí mataron a un kóbold que tenía una muestra de un extraño mineral, pero no están dispuestos a vendérmelo. Quiero una muestra de ese mineral para analizarlo.", t = "Una nueva muestra de mineral"},
    [1167] = {ot = "Habla con Balthule Golpesombra cerca de La Torre de Althalaxx.", st = "Antes de enfrentarte a Athrikus, probablemente sería prudente que consultaras a Balthule. No me cabe la menor duda de que habrá estado muy atento en su observatorio de la torre y podría tener información sobre los últimos movimientos.", t = "La Torre de Althalaxx"},
    [1195] = {ot = "Llévale una ampolla con grabados llena a Zangen Pezuña Pétrea, que está en Cima del Trueno.", st = "Los centauros Galak de Las Mil Agujas custodian un artefacto desde el comienzo de sus tiempos.$B$BNos gustaría arrebatárselo pero para ello necesitamos una ampolla de agua de una de las Pozas de la Luna de los elfos de la noche.$B$BPara conseguir el agua, primero tendrás que hacerte con una de las ampollas que portan los dríades cerca del Refugio de la Algaba en el corazón del Bosque de Vallefresno. Hay una Poza de la Luna cerca de la orilla occidental del Río Falfarren, al sur de la carretera principal, donde podrás llenar la ampolla de agua.", t = "La llama sacra"},
    [1196] = {ot = "Entrégale la ampolla con grabados llena a Rau Abiscorredor del Poblado Viento Libre.", st = "Llévale la ampolla con agua a Rau Abiscorredor en el Poblado Viento Libre en la zona sudeste de Las Mil Agujas. Podrás llegar a Las Mil Agujas cogiendo El Gran Elevador que encontrarás en el extremo sur de Los Baldíos.$B$BNo me sorprendería que pudieras seguir ayudándonos.", t = "La llama sacra"},
    [1197] = {ot = "Consigue la pezuña hendida para Rau Abiscorredor del Poblado Viento Libre.", st = "Con el agua que has traído podrás apagar temporalmente la llama que protege la reliquia de los centauros. Sin embargo, su efecto no es permanente por lo que tendrás que darte prisa.$B$BEncontrarás el Risco Pezuña Quebrada, el fuerte de los centauros, en dirección norte. La llama se encuentra en el Campamento Pezuña Quebrada, un lugar fuertemente custodiado del risco.$B$BTen cuidado pues los centauros Galak tienen a muchos hombres allí y no dejarán que les arrebates algo tan preciado para ellos con facilidad.", t = "La llama sacra"},
    [1198] = {ot = "Busca al guardia argenta Thaelrid en las Cavernas de Brazanegra.", st = "Corren muchos rumores estos días sobre la unión del Martillo Crepuscular y los nagas de las Cavernas de Brazanegra en la costa de Vallefresno.$b$bMi función aquí con el Alba Argenta es recopilar la mayor cantidad de información posible, para saber dónde y cuándo se necesita ayuda.$b$bHan pasado semanas desde que envié a un explorador para que revisara la actividad de la Cavernas de Brazanegra. El guardia argenta Thaelrid aún no se ha reportado.$b$bMis demás exploradores están ocupados con asuntos más urgentes.$b$bBusca y ayuda a Thaelrid por mí, $n.", t = "Buscando a Thaelrid"},
    [1199] = {ot = "Lleva 10 colgantes crepusculares al guardia argenta Manados en Darnassus.", st = "Fortalecidos por los ritos antiguos de los caóticos dioses antiguos, los miembros del Martillo Crepuscular buscan el regreso de sus amos oscuros y propagan la muerte y el terror por todo el mundo.$b$bCreemos que el Martillo Crepuscular se ha aliado con los nagas y están reuniendo sus fuerzas en las Cavernas de Brazanegra en la costa de Vallefresno.$b$bNo sé qué plan malvado están ideando en las profundidades del viejo templo, pero debemos detenerlos.$b$bDeclárale la guerra al Martillo y tráeme prueba de tus hazañas. Recibirás una gran recompensa por tus esfuerzos.", t = "Cascada Crepuscular"},
    [1200] = {ot = "Lleva la cabeza del señor crepuscular Kelris al vigía del alba Selgorm en Darnassus.", st = "La fuerza me ha abandonado. ¡Necesito tu ayuda!$b$bHace mucho tiempo este sitio fue un gran templo de Elune. Pero la desgracia conllevó la ruina cuando la corrupción de un dios antiguo brotó de la tierra y contaminó la poza de la luna.$b$bAku'Mai, sirviente del dios antiguo, se alzó de las aguas.$b$bLos cultistas del Martillo Crepuscular se han aliado con los nagas para establecerse en el lugar. Los cultistas, liderados por Kelris, sacrifican inocentes para Aku'Mai a cambio de poder.$b$bPor favor, mata a Kelris y lleva su cabeza a Selgorm en Darnassus, $n.", t = "La vileza de Brazanegra"},
    [1221] = {ot = "Coge un cajón con agujeros.$BCoge una vara de mando de husmeador.$BLee el manual de propietario de husmeador. $b$bCuando llegues a Horado Rajacieno, usa el cajón con agujeros para invocar un husmeador taltuza; usa la vara para que busque tubérculos. $b$bLleva 6 tubérculos hojazul, la vara de mando de husmeador y el cajón con agujeros a Mebok Mizzyrix a Trinquete.", st = "Los tubérculos hojazul son muy apreciados en todo el mundo. Pero son muy raros. Solo se encuentran aquí, en Los Baldíos, enterrados profundamente en Horado Rajacieno.$B$B¡Y es imposible encontrarlos a no ser que sepas dónde mirar! Por eso he amaestrado husmeadores taltuza para que los busquen. Tienen un olfato extraordinario, huelen los tubérculos a una distancia de 50 pasos.$B$BNo será fácil, pero si me traes tubérculos te pagaré muy bien.", t = "Los tubérculos hojazul"},
    [1275] = {ot = "Gershala Susurro Nocturno en Auberdine quiere 8 bulbos raquídeos corruptos.", st = "Los tontos elfos de sangre intentan dominar la magia demoníaca. ¿Acaso no fueron testigos de lo que les sucedió a los nagas y a los sátiros de Kalimdor?$b$bTemo que los elfos de sangre sufran una deformación similar. Azeroth no está lista para soportar el nacimiento de otra raza de monstruos malignos.$b$bQuiero estudiar los bulbos raquídeos de los sátiros y los nagas para intentar deducir qué destino les espera a los elfos. En las Cavernas de Brazanegra, en la costa de Vallefresno, encontrarás tanto sátiros como nagas.$b$bEs un largo viaje, $n.", t = "Investigaciones acerca de la corrupción"},
    [1338] = {ot = "Lleva el pedido de Pico Tormenta a Furen Barbalarga a Ventormenta.", st = "Hay un forjador de armaduras enano cuyo trabajo me gusta mucho. Se llama Furen Barbalarga y es el mejor de su gremio. Necesito un escudo nuevo, y quiero que me lo haga él.$B$BSolo hay un problema... Furen vive muy al sur, en el Distrito de los Enanos de Ventormenta. ¡En tierra humana! No entiendo por qué vive ahí, tan lejos de Forjaz. ¡Será que los humanos le pagan una fortuna!$B$BSi te apetece viajar y ganar algo de dinero, ve a ver a Furen para hacer mi pedido de un escudo.", t = "Un pedido de Pico Tormenta"},
    [1339] = {ot = "Habla con el montaraz Pico Tormenta.", st = "Dicen que el montaraz Pico Tormenta busca alguien que le haga de mensajero. Alguien con ganas de viajar un poco. ¿Qué te parece? ¿Te ves capaz, $r?$B$BEntonces, ve a hablar con Pico Tormenta en la cima de la torre norte.", t = "La tarea del montaraz Pico Tormenta"},
    [1358] = {ot = "Lleva la muestra de corazón de lobo al boticario Helbrim en Los Baldíos.", st = "Un colega de Kalimdor, el boticario Helbrim, está investigando los efectos de las toxinas de Lordaeron en las bestias de Kalimdor. Estaría muy interesado en una muestra de los corazones de lobo que Renferrel me envió.$B$BHelbrim está en Los Baldíos, en una aldea conocida como El Cruce. Para llegar a él, deberás viajar en zepelín hasta la capital orca de Orgrimmar y, a continuación, dirigirte a pie hacia Durotar. Sigue en dirección oeste por Los Baldíos y pronto llegarás a la aldea El Cruce.", t = "Muestra para Helbrim"},
    [1359] = {ot = "Lleva las muestras de corazón de lobo a la boticaria Zinge en Entrañas.", st = "Los corazones de lobo que conseguiste, poseen una calidad nunca vista antes en especímenes similares. Tienen tal grado de toxicidad que deberían ser mortales incluso para los lobos en los que laten esos corazones.$B$BEs bastante impresionante, y debemos estudiarlo en profundidad. He guardado algunas muestras de los corazones. Llévaselas a mi colega, la boticaria Zinge. La encontrarás en nuestro puesto de mando, en Entrañas.", t = "Una entrega de Zinge"},
    [1431] = {ot = "Habla con Keldran en Orgrimmar.", st = "Guarda silencio, $c, y deja que te hable de algo que tiene mucha importancia para mi gente.$B$BSomos orgullosos y la guerra con los humanos ha impacientado incluso a Thrall. Verás, nuestro Jefe de Guerra es sabio y prudente y siempre piensa primero en su pueblo. También es diplomático y aprendió mucho de los humanos cuando estuvo con ellos.$B$BSi la historia te interesa, ve a ver a Keldran, que está cerca de la salida oeste de la ciudad.", t = "Las relaciones de la Alianza"},
    [1442] = {ot = "Lleva una gema Kor a Thundris Tejevientos a Costa Oscura.", st = "Saludos, $n. ¿Cómo puedo ayudar a quien sigue una senda sagrada?$B$BAh, sí, Fontana, el herrero... Cuánto tiempo. Lo recuerdo bien, aunque hacía tiempo que no oía hablar de él.$B$BNo lo tengo por avaricioso, luego su deseo de tener una gema Kor solo puede tener un motivo noble.$B$BPara encontrar una de esas gemas tendrás que ir hacia el noroeste de Vallefresno. Allí encontrarás unas ruinas antiguas y las Cavernas de Brazanegra. Allí viven los nagas que siguen usando esas gemas. No vayas por tu cuenta, $c.", t = "La búsqueda de la gema Kor"},
    [1470] = {ot = "Lleva 3 calaveras de armadóseos a Venya Marthand.", st = "Buenas, criatura. Veo que aún no has desarrollado del todo los poderes de los brujos. Pero siento que tienes un gran deseo de aprender.$B$BY aprenderás.$B$BNo hay fuerza en la ignorancia. El conocimiento es nuestro mayor poder. Aplicando el conocimiento podemos controlar las magias y los seres del vacío y atarlos a nuestra voluntad.$B$BTe enseñaré a atar a un siervo a tu voluntad. Pero primero tienes que traerme 3 calaveras de los esqueletos armadóseos que hay cerca de la herrería abandonada.", t = "Descubrir el misterio"},
    [1471] = {ot = "Utilizando las Runas de invocación, invoca y domina a un abisario, y después devuélvele las Runas de invocación a Carendin Halgar, que está en el Barrio de la Magia de Entrañas.", st = "¿Ves el Círculo de Invocación? Ahí es donde debes invocar a un abisario.$B$BCon la ayuda de estas runas, podrás liberarlo y luego tendrás que dominarlo por medio de la fuerza de las armas y la magia.$B$BCuando hayas conseguido subyugarlo será completamente tuyo. Vuelve entonces a verme y te explicaré el hechizo de invocación para que te ayude en el fin que persigas.", t = "El vínculo"},
    [1473] = {ot = "Recupera el grimorio de Egalin y dáselo a Carendin Halgar, que está en el Templo de los Condenados.", st = "Parece que todo apunta a que estás $gpreparado:preparada; para aprender a invocar a un abisario.$B$BSe trata de un ser creado a partir del caos y, si lo invocas pero eres incapaz de dominarlo, será tu fin.$B$BEgalin fue el primero en invocar a un abisario, y explica el proceso en su grimorio.$B$BDesgraciadamente, nos lo robó un agente de la Cruzada Escarlata y ahora está escondido en la base que tienen en una torre hacia el oeste. Tráemelo y compartiré ese conocimiento contigo.", t = "Criatura Abisal"},
    [1478] = {ot = "Habla con Carendin Halgar en Entrañas.", st = "¡Ah, $n! Parece que Carendin Halgar desea verte para continuar con tu instrucción.$B$BDeberías sentirte muy $gorgulloso:orgullosa;, $n. No todos los días el maestro Halgar se digna a instruir a $gun joven brujo:una joven bruja;.$B$BLo encontrarás en el Barrio de la Magia de Entrañas, cerca del Templo de los Condenados.", t = "Las invocaciones de Halgar"},
    [1483] = {ot = "Habla con Ziz Fizziks en Risco Cortaviento.", st = "Ventura y Cía. se quedó con muchos de los cerebros goblins más brillantes pero de vez en cuando, conseguimos robarle alguno.$B$BHace algún tiempo, la delegación de Ventura y Cía. en Sierra Espolón contrató a Gerenzo Silbillave, ¡un gnomo! Esto afectó tanto a su otro ingeniero, Ziz Fizziks, que me rogó que le encontrara un nuevo empleo con el sindicato de manitas. Le asigné unas tareas pero puede que necesite ayuda.$B$B¿Podrías ir a ver cómo le va por mí? Se encuentra en el extremo occidental del Risco Cortaviento.", t = "Ziz Fizziks"},
    [1485] = {ot = "Lleva 6 cabezas de familiar vil a Ruzan.", st = "Los brujos que llegaron antes que nosotros se ganaron la desconfianza de la Horda, y aunque se nos tolera, no somos realmente queridos.$B$BPero esto no ha servido para unir a los brujos, muchos de ellos viven recluidos, trabajando a solas en su magia. No pretendo conducirte a uno u otro camino, sino ayudarte a madurar.$B$BAntes de enseñarte las artes de la invocación, tráeme seis cabezas de los familiares viles que encontrarás en la cueva del Noreste.", t = "Familiares viles"},
    [1486] = {ot = "Nalpak de las Cuevas de los Lamentos quiere 20 pellejos descarriados.", st = "Cuando Naralex se hundió en su pesadilla, una extraña raza de bestias salió de debajo de Los Baldíos y se adentró en las Cuevas de los Lamentos.$B$BEstas criaturas descarriadas tienen propiedades extrañas y como de otro mundo. Aunque su naturaleza es malvada, creo que puede venir algo bueno de su presencia aquí en Kalimdor. Creo que sus pellejos serán especialmente útiles para la peletería.$B$BSi crees que estás $gpreparado:preparada; para emprender esta tarea, aventúrate en las cuevas y hazte con algunos pellejos descarriados.", t = "Pellejos descarriados"},
    [1487] = {ot = "Ebru de las Cuevas de los Lamentos quiere que mates 7 devastadores descarriados, 7 víboras descarriadas, 7 arrastrapiés descarriados y 7 colminfernos descarriados.", st = "Naralex tiene un fin muy noble.$B$BNuestro gran líder aspiraba a entrar en el Sueño Esmeralda y a ayudar a que estas duras tierras volvieran a convertirse en el exuberante bosque que fueron un día. Pero algo fue terriblemente mal.$B$BEl sueño de Naralex se convirtió en pesadilla y criaturas corruptas comenzaron a habitar las cavernas.$B$BMientras algunos discípulos de Naralex se esfuerzan por despertar a nuestro maestro, yo me ocupo de librar a las cuevas de esas malvadas bestias.$B$BAventúrate a las cavernas, $n, y erradica esos engendros descarriados.", t = "Erradicación de descarriados"},
    [1489] = {ot = "Habla con Hamuul Tótem de Runa", st = "Los caparazones que me has traído están contaminados, nunca había visto algo así. Seguro que el agua de los oasis es la causa, y puedo sentir la confusión que causan en esta tierra. Es como si la tierra soñara y no pudiera despertar.$B$BLas Cuevas de los Lamentos deben de ser la fuente de la contaminación. Pero antes de ir allí habla con Hamuul Tótem de Runa, el druida anciano. Ya le hice saber lo que está ocurriendo en Los Baldíos. Es sabio y podrá ofrecerte consejo.$B$BLo encontrarás en Cima del Trueno, en el Alto de los Ancestros.", t = "Hamuul Tótem de Runa"},
    [1490] = {ot = "Habla con Nara Ferocrín.", st = "Entré en el país de los sueños, y soñé con un culto de druidas que habitaba en las Cuevas de los Lamentos. Vi que sus fines fueron nobles, pero se echaron a perder. Ahora sirven a la corrupción que se está filtrando por Los Baldíos.$B$BSoy viejo y mi fuerza se desvanece. No puedo morar mucho tiempo en el país de los sueños y sé muy poco sobre los druidas corruptos. Pero Nara es joven y su espíritu implacable. Ella permaneció sumergida en la ensoñación cuando yo tuve que huir.$B$BHabla con Nara. La encontrarás en la tienda, ahí mismo.", t = "Nara Ferocrín"},
    [1491] = {ot = "Llévale 6 porciones de esencia de lamentos a Mebok Mizzyrix en Trinquete.", st = "Bueno, los cuernos de raptor no funcionaron como esperaba. Pero no hay problema, ¡nadie se volvió rico en su primer intento! Además, ¡creo que encontré algo que funcionará todavía mejor en mis bebidas de inteligencia!$B$BHay una sustancia llamada esencia de lamentos que creo que es el motivo del origen de las plantas y animales extraños en los Baldíos. ¡Tráeme algunas y probaré agregarlas a mis bebidas!$B$BOí que la esencia se acumula en criaturas ectoplásmicas en las Cuevas de los Lamentos, al oeste. Caza a esas criaturas y consigue la esencia.", t = "Bebidas de inteligencia"},
    [1492] = {ot = "Llévale el cajón seguro al maestro de muelles Vertipeluca, en Trinquete.", st = "Necesito enviar una caja de pociones, componentes y otras cosas a mis socios del Viejo Mundo. Apenas tengo tiempo de llevarlos al embarcadero de Trinquete y la última caravana ya ha salido.$B$BSi puedes, lleva esto al maestro de muelles Vertipeluca. Se asegurará de que sale en el primer barco hacia Cala Aguasnegras.", t = "Maestro de muelles Vertipeluca"},
    [1499] = {ot = "Habla con Zureetha Vistalonga.", st = "Zureetha ha estado enviando novicios como tú para ayudar a acabar con las criaturas que habitan la cueva cercana al lugar en el que combatiste a los familiares viles.$B$BCreo que te convendría ayudarle y ganar experiencia. No olvides decirle que me ayudaste con el problema de los diablillos, seguro que te dará alguna recompensa.", t = "Familiares viles"},
    [1501] = {ot = "Lleva la tablilla de Vergua a Gan'rul Ojosangre a Orgrimmar.", st = "Quedan tan pocos brujos... Tienes que perfeccionar tus habilidades rápidamente si quieres ser útil a la Horda y al Jefe de Guerra.$B$BTe voy a enseñar otro hechizo de invocación.$B$BPero antes tienes que recuperar la tablilla de Vergua; la robaron unos brujos de Filo Ardiente y ahora está en su guarida de Roca del Cráneo, al este de la ciudad. La tablilla tiene las runas necesarias para invocar a un abisario.", t = "Criatura Abisal"},
    [1504] = {ot = "Usa los glifos de invocación para invocar y dominar a un abisario y lleva los glifos a Gan'rul Ojosangre a Orgrimmar.", st = "Verás que la tablilla contiene los glifos de invocación. Llévatela al círculo de la carpa de Neeru Hojafuego, que está al otro lado de la caverna; allí podrás invocar al abisario.$B$BDerrótalo con cualquier medio físico o mágico de que dispongas. Luego devuélveme los glifos de invocación y te enseñaré cómo ligar a la criatura a tu voluntad.", t = "El vínculo"},
    [1506] = {ot = "Habla con Gan'rul Ojosangre en Orgrimmar.", st = "¡Eh, tú! $n, ¿verdad?$B$BEspero que no tengas la agenda muy llena porque Gan'rul quiere verte ahora mismo. Lo encontrarás con los brujos mayores en el Circo de las Sombras.$B$BSegún mi experiencia con Gan'rul, esto de que te convoque solo puede ser muy bueno o muy malo.", t = "Las invocaciones de Gan'rul"},
    [1507] = {ot = "Habla con Cazul en el Circo de las Sombras.", st = "Llegó la hora de que aprendas más sobre la magia de las invocaciones. Te voy a enseñar a invocar a un sayaad, una criatura con unos poderes mentales increíbles. Puede esclavizar a los débiles, pero tú no tienes de qué preocuparte; seguro que resistirás.$B$BPara invocarlo, tienes que atraerlo con un objeto que simbolice amor y devoción. Queda en ti encontrar el objeto adecuado.$B$BSi me permites un consejo, habla con Cazul... Parece que no hay nada que ese viejo brujo no sepa.", t = "Devoradora de almas"},
    [1508] = {ot = "Habla con Zankaja en Orgrimmar.", st = "Si vienes de parte de Gan'rul, quiere decir que vas a invocar una súcubo, una hembra de la raza sayaad, y necesitas un objeto que la atraiga.\n\nMmm... Si confías en que un hombre ciego te guíe, $n, escucha. En los riscos de Orgrimmar, al oeste de la torre del jinete del viento, vive Zankaja, que espera el regreso de su compañero.\n\nVe a hablar con ella.", t = "Cazul, el ciego"},
    [1509] = {ot = "Habla con Gazrog en El Cruce.", st = "A Dogran lo ascendieron y lo destinaron a El Cruce. Estaba muy contento.$B$BMe daba pena que se fuera, pero no se lo dije. Y también estaba preocupada. Los Baldíos son más peligrosos que Orgrimmar y me temía lo peor.$B$BYa hace una semana que tendría que haber vuelto y no sé nada de él...$B$B¿Puedes ir a El Cruce a preguntar? Habla con Gazrog, estaban destinados juntos.", t = "Noticias de Dogran"},
    [1510] = {ot = "Habla con Ken'zigla en Malaka'jin.", st = "Estaba destinado al Campamento Taurajo, intentando erradicar a los jabaespines. Un día los siguió hasta el campamento, donde fue atacado por esas bestias. Sus compañeros lo rescataron, pero estaba muy grave. Sus heridas tenían muy mala pinta y no se atrevían a moverlo.$B$BNos pidieron un jarabe curativo de los trols de Malaka'jin, al pie de Sierra Espolón. Enviamos a un mensajero, pero todavía no ha vuelto.", t = "Noticias de Dogran"},
    [1511] = {ot = "Lleva el jarabe de Ken'zigla al bruto Logmar al Campamento Taurajo.", st = "Imaginaba que vendría alguien más a por el jarabe, así que lo tengo preparado.$B$BAquí tienes, $n. Recuerda, ¡dale solo la mitad! Con eso podrán desplazarlo sin que se desangre. Al día siguiente, dale la otra mitad.$B$BLlévaselo a Logmar, que está en el Campamento Taurajo. Por lo que me dijo el primer mensajero, él sabe dónde está el tal Dogran.", t = "Jarabe de Ken'zigla"},
    [1512] = {ot = "Lleva el colgante cubierto de tierra a Gan'rul Ojosangre a Orgrimmar.", st = "Zankaja es joven y guapa, no puede encadenarse a un lisiado; no permitiré que malgaste su vida.$B$BDéjame solo, $n. Y gracias. Así puedo caer honrosamente en combate, en lugar de extinguirme como un vegetal.$B$BY por favor, no le digas nada a ella, no quiero que se sienta culpable.", t = "Un regalo de amor"},
    [1513] = {ot = "Usa el colgante de Dogran para invocar y dominar a un súcubo y lleva el colgante a Gan'rul Ojosangre a Orgrimmar.", st = "$N, lleva eso al círculo de invocación de la carpa de Neeru. Invoca a un súcubo y demuéstrale lo que puedes hacer. Eres lo suficientemente fuerte. Pero sé prudente; la arrogancia y el exceso de confianza han sido la perdición de más de un buen brujo.$B$BCuando lo hayas derrotado, devuélveme el colgante para que pueda decirle a Zankaja lo que ha pasado.", t = "El vínculo"},
    [1515] = {ot = "Lleva el jarabe de Ken'zigla a Dogran a Los Baldíos.", st = "Ya que has llegado hasta aquí, no seré yo quien te detenga. Pero no tengo personal que te acompañe, tendrás que ir por tu cuenta.$B$BLo tienen retenido en un campamento de jabaespines al norte de aquí; busca dos chozas juntas. Estará muy vigilado, si es que no lo han matado ya sus heridas o esos animales.$B$BSuerte.", t = "El cautiverio de Dogran"},
    [1516] = {ot = "Lleva 2 pezuñas de acechador vil a Canaga Clamatierras en el Valle de los Retos.", st = "Ha llegado el momento, joven $c. Te estás haciendo fuerte y tu espíritu aguanta firme como la tierra. Al seguir la ruta del chamán has demostrado sabiduría antes incluso de haberte puesto a prueba.$B$BEl elemento tierra guiará tu destino, y pasará a formar parte de ti si estás $gpreparado:preparada;. Pero siempre debes mostrarle tu reconocimiento. Si estás $glisto:lista; verás cosas que solo conoce un chamán.$B$BVe a buscar a los acechadores viles, al Norte, y coge dos de sus pezuñas. Cuando las tengas vuelve aquí y seguiremos hablando de tu futuro.|n", t = "La llamada de la tierra"},
    [1517] = {ot = "Encuentra la Roca de los Espíritus y bebe la Sapta de tierra.", st = "Una sapta es una bebida creada para unir nuestros espíritus con los elementos. Cargada de magia, la poción permite a quien tiene fuerza de voluntad ver los elementos que nadie más puede ver. Tu espíritu se conectará con los elementos para los que fue creada la sapta, y son pocos los chamanes que conocen la receta.$B$BLa sapta siempre se bebe en un lugar sagrado, y en ningún otro sitio... recuérdalo.$B$BBusca la Roca de los Espíritus al suroeste de aquí, la encontrarás al final del Sendero Oculto. Cuando llegues, bebe la sapta, y... deberías poder ver.", t = "La llamada de la tierra"},
    [1518] = {ot = "Lleva el cuarzo en bruto a Canaga Clamatierras en el Valle de los Retos.", st = "Coge este cuarzo en bruto y llévaselo a Canaga Clamatierras como prueba de nuestro encuentro. Te hará un tótem y este guijarro será su corazón. Puede parecer muy pequeño, pero descubrirás que el tamaño no importa, y que incluso las cosas más pequeñas pueden superar a otras.$B$BTen paciencia, $n. Sigue siendo fuerte. Y busca la sabiduría. Es todo lo que te pide la tierra. Al final te harás $guno:una; con ella... Respétala del mismo modo que ella te respeta a ti.", t = "La llamada de la tierra"},
    [1519] = {ot = "Lleva 2 dosis de bálsamo ritual a la vidente Pluma de Cuervo al Campamento Narache.", st = "$C, ha llegado el momento; tu cuerpo crece en edad y en fuerza y tu espíritu gana profundidad, como la tierra. Veo en tus ojos la sabiduría de tu alma.$B$BLa tierra guía a mi gente y nos habla, como te hablará a ti en el futuro. Pero debes ponerte a prueba. Si tu momento ha llegado, verás cosas que solo los nuestros pueden ver.$B$BBusca a los chamanes Erizapúas en el barranco que hay al este y coge un bálsamo que usan en sus rituales. Regresa cuando hayas conseguido el suficiente para crear tu propia poción.", t = "La llamada de la tierra"},
    [1520] = {ot = "Encuentra la Roca de los Kodos y bebe la sapta de tierra.", st = "La sapta es una bebida que nos ayuda a vincular el espíritu a los elementos. Con la magia adecuada, la poción ayuda a ver los elementos como nadie los ha visto antes. Tu espíritu quedará ligado para siempre al elemento para el que se creó la sapta. Solo unos pocos elegidos conocen la receta.$B$BSiempre debes beberte la sapta en un lugar sagrado; nunca jamás en otro sitio.$B$BVe al lugar santo de los chamanes, hacia el este, y bebe allí la sapta.", t = "La llamada de la tierra"},
    [1521] = {ot = "Lleva el cuarzo en bruto a la vidente Pluma de Cuervo al Campamento Narache.", st = "Toma este cuarzo en bruto y llévaselo a la vidente Pluma de Cuervo como prueba de nuestro encuentro. Te hará un tótem y este guijarro será su corazón. Puede parecer muy pequeño, pero descubrirás que el tamaño no importa, y que incluso las cosas más pequeñas pueden superar montañas.$B$BTen paciencia, $n. Sigue siendo fuerte. Y busca la sabiduría. Es todo lo que te pide la tierra. Al final te harás $guno:una; con ella... Respétala del mismo modo que ella te respeta a ti.", t = "La llamada de la tierra"},
    [1524] = {ot = "Lleva la antorcha de la Llama Latente a Telf Joolam a Durotar.", st = "Ya tienes poder suficiente para llevar el Tótem del Fuego, pero eso no quiere decir que estés $glisto:lista;.$B$BA lo largo del Río Furia del Sur de Durotar, antes del Mare Magnum, hay una senda oculta que lleva a uno de los picos más altos de la tierra. Ábrete camino hasta la cima. Allí, custodiado por Telf Joolam, encontrarás uno de nuestros santuarios: el Santuario de la Llama Latente.$B$BLleva esta antorcha a Joolam. Así sabrá que intentas domar el fuego. Enciéndela en el blandón del santuario y tráemela. Yo me encargaré de que te sea concedido el Tótem de Fuego.", t = "La llamada del fuego"},
    [1525] = {ot = "Lleva 1 alquitrán y 1 faltriquera de componentes a Telf Joolam a Durotar.", st = "Pero tú no has venido aquí a recibir lecciones de historia, ¿verdad? Has venido aquí por la Llama Eterna y el Tótem de Fuego.$B$BEl primer paso es crear una sapta y unirte a la llama.$B$BPuedo crearte la sapta de fuego si me traes dos objetos. Primero necesito alquitrán. Un objeto sencillo que suelen llevar los taumaturgos de los Crines de Acero de la región este de Los Baldíos.$B$BEl segundo objeto será más difícil: una faltriquera de componentes de uno de los cultores del Filo Ardiente. Los encontrarás en una cueva que está sobre los barrancos del noreste de Cerrotajo.", t = "La llamada del fuego"},
    [1526] = {ot = "Derrota a la Manifestación de fuego menor y coloca las ascuas ardientes sobre el altar de la llama eterna.", st = "La sapta de fuego está acabada. Ha llegado el momento de que afrontes la llama. Utiliza la sapta del santuario y sube a la cima de la montaña para enfrentarte a la aparición que encontrarás allí. Él no te atacará hasta que no estés $glisto:lista;, pero se dará cuenta de que puedes verlo.$B$BAtaca con rapidez, $n, pues cuanto más tardes en matarlo, más crecerá su poder. Una vez le hayas derrotado, coloca sus ascuas ardientes en el blandón y enciende la antorcha.", t = "La llamada del fuego"},
    [1527] = {ot = "Lleva la antorcha de la llama eterna a Kranal Fiss a Los Baldíos.", st = "Con la antorcha firmemente sujeta, te alejas del blandón y diriges la vista sobre Durotar. Sientes una excitación creciente que tira de tu espíritu a la vez que el viento agita la llama y la hace bailar con violencia.$B$BEmprendes el camino de regreso a Los Baldíos en busca de Kranal Fiss.", t = "La llamada del fuego"},
    [1530] = {ot = "Encuentra a Salmuera en los Baldíos del Sur.", st = "Si hay una lección que has de aprender acerca del agua, es esta: el agua significa renacimiento.$B$BSu energía fluye, erosiona y limpia todo tipo de cosas. Su capacidad de curación y de reconstitución te parecerá sin parangón pero solo se da cuando es pura.$B$BCuando entiendas que si el agua está contaminada, puede causar estragos en todo aquello que toca, te darás cuenta de cuán vital es este recurso.$B$BSi deseas la sapta del agua, encuentra a Salmuera en lo más recóndito de Los Baldíos del Sur. Los jabaespines la importunan constantemente en su hogar.", t = "La llamada del agua"},
    [1531] = {ot = "Encuentra a Prate Vidente de las Nubes en Las Mil Agujas.", st = "Tú estar haciendo progresos, colega. Estar $gpreparado:preparada; para demostrar si merecer recibir Tótem de aire, pero antes encontrar a Prate Vidente de las Nubes en Las Mil Agujas debes. Si tratas a ella con respeto, ella dirá lo que tener que hacer para conseguir tu Tótem de aire.$B$BVe al sur por Los Baldíos y al llegar a Las Mil Agujas, hacia el este. Encontrarás a ella por allí escondida con su novio... ¡Ja, ja, ja! No digas que yo dije... ¡a ella no gustar!", t = "La llamada del aire"},
    [1534] = {ot = "Llena el odre de agua azul vacío en Las Ruinas del Polvo Estelar en Vallefresno y llévasela a Salmuera en Los Baldíos.", st = "Toma este odre de agua y adéntrate en el frondoso bosque que los elfos de la noche llaman Vallefresno. Está en un lugar remoto del norte de Los Baldíos.$B$BCuando hayas penetrado en el bosque, dirígete hacia el oeste. Por las montañas que separan Espolón y Vallefresno, y más allá del Lago Mystral, encontrarás un lugar sagrado: Las Ruinas del Polvo Estelar. En el centro del lago encontrarás una fuentecilla.$B$BTráeme una muestra del agua de esa fuente. Será el último componente que necesitarás antes de que te mande de nuevo con Islen.", t = "La llamada del agua"},
    [1535] = {ot = "Llena el odre de agua marrón vacío en el abrevadero que está debajo de la cabaña de Salmuera y llévaselo a Los Baldíos.", st = "Para adquirir el conocimiento y ganarte la sapta, debes buscar solo las formas más puras de agua. Conforme recoges muestras para mí, observa a tu alrededor. Ten cuidado con las criaturas que dependen del agua, que la protegen. Fíjate en cómo afecta a los bosques y a los desiertos. Presencia cómo la mismísima sustancia en la que se sustenta la vida, obliga a las criaturas a arrebatar vidas.$B$BEmpezaremos con una tarea simple: debajo de mi cabaña hay un abrevadero con el preciado líquido. Llena este odre y vuelve aquí.", t = "La llamada del agua"},
    [1536] = {ot = "Llena el odre de agua rojo vacío en el pozo de Molino Tarren y llévasela a Salmuera en Los Baldíos.", st = "Hace mucho tiempo seguí a unos compañeros hasta las Laderas de Trabalomas. Nos defendimos de tenaces humanos que allí moran y acabamos en un pueblecito que los Renegados habían tomado: Molino Tarren.$B$BAllí fue donde encontré algo muy especial: en el centro del pueblo había un pequeño pozo con agua dulce de manantial. No sé muy bien si los lugareños apestados se daban cuenta de su valor, es un pequeño vestigio sagrado en un mar sin consagrar.$B$BTráeme una muestra de esa agua en este odre.", t = "La llamada del agua"},
    [1578] = {ot = "Llévale 6 hachas de cobre y 6 cinturones de anillas de cobre a Thorvald a la torre de vigilancia sur de Loch Modan.", st = "Los montaraces de Loch Modan están luchando denodadamente contra los troggs. Necesitan un suministro constante de armaduras y armas.$B$BPor eso está allí mi colega Thorvald, encargándose del equipamiento de los montaraces. Seguro que te agradecerá que le fabriques unas hachas y unos cinturones de anillas de cobre. Puede incluso que comparta su sabiduría contigo.$B$BThorvald está en la torre sur de Loch Modan.", t = "Abastecer al frente"},
    [1579] = {ot = "Lleva 8 mecanismos eléctricos a Maniveo Zumbang a Auberdine.", st = "Vine a Auberdine por su tranquilidad. Quería inventar mis inventos en un sitio tranquilo. El ajetreo de Forjaz era demasiado para mí cuando había pasado la noche bebiendo.$B$BAsí que me embarqué hacia Auberdine. Pero bebí demasiado durante la travesía. ¡Y se me cayó la caja de mecanismos eléctricos por la borda! ¡Necesito mis mecanismos!$B$BNo sé exactamente dónde se me cayeron, pero si puedes ir de pesca al océano, quizás tengas suerte...", t = "Mecanismos eléctricos"},
    [1580] = {ot = "Lleva 12 electromuelles a Maniveo Zumbang a Auberdine.", st = "Sabemos que tienes mucha suerte, pero... ¿hasta dónde llega, $n?$B$BUna noche, estaba yo deambulando por los caminos de Costa Oscura... Iba buscando un buen río o lago para probar mi nuevo señuelo-pato autopropulsado explosivo y... creo que estaba un poco alegre porque perdí el conocimiento y me levanté horas después en Auberdine. ¡Tenía el pelo quemado y había perdido mi bolsa de electromuelles! ¡Seguro que se me cayeron al agua!$B$B¡Necesito mis electromuelles! Quizás puedas pescarlos de algún lago o río de Costa Oscura...", t = "Los electromuelles"},
    [1581] = {ot = "Llévale 6 elixires de fuerza de león y 2 elixires de defensa menor a Syral Filohoja, que está en Dolanaar.", st = "Nuestra tienda de alquimia y hierbas marcha bien, pero mi marido pasa tanto tiempo preparando pociones que casi nunca tenemos tiempo para nosotros.$B$B¿Podrías ayudarnos?$B$BSi me pudieras traer un pedido de elixires prefabricados, estaría encantada de hacer negocios contigo. Tengo algunas hierbas raras que puede que encuentres útiles.", t = "Elixires para Filohoja"},
    [1598] = {ot = "Lleva los Poderes del Vacío a Drusilla La Salle.", st = "¡Eh, tú! Eres $n, ¿verdad?$B$BEspero que estés muy seguro de que quieres convertirte en brujo, porque es bien difícil.$B$BYo te instruiré, pero antes debo asegurarme de que tienes lo que hay que tener.$B$BTeníamos un novicio en la abadía que huyó para unirse a la Hermandad Defias. ¿Que qué más da? Pues da que robó unos libros importantes.$B$BYo quería estudiar uno de ellos, Poderes del Vacío. Tráemelo; lo tienen escondido en su carpa de los Viñedos.", t = "El libro robado"},
    [1599] = {ot = "Lleva 3 talismanes de plumas a Alamar Grimm a Yunquemar.", st = "Debes de ser $gel nuevo brujo del:la nueva bruja de la; que habla todo el mundo. Has debido de impresionar a alguien, si no, no me pedirían que robara tiempo a mis investigaciones para instruirte.$B$BNo te preocupes, no te lo echaré en cara.$B$BEl Diablillo es el hechizo de invocación más sencillo que aprenderás. Pero antes de que te imparta tal conocimiento, debes probarme que tienes las habilidades mágicas y físicas necesarias.$B$BTráeme tres talismanes de plumas de los novicios de Peloescarcha. Los encontrarás en una cueva que hay al suroeste.", t = "Novato"},
    [1618] = {ot = "Tormus Forjahonda quiere que le lleves 4 cinturones rúnicos de cobre y 4 grandes mazas de cobre pesadas a Verner Osbien, en Crestagrana.", st = "Los enanos no somos los únicos que luchamos. ¡Nuestros aliados humanos también están muy ocupados!$B$BCrestagrana sufre ataques constantes de los orcos Roca Negra y siempre anda mal de equipamiento. Si decides ayudarles, seguro que su herrero, Verner Osbien, te enseñará lo que sepa.", t = "Equipar Crestagrana"},
    [1638] = {ot = "Habla con Harry Burlguard.", st = "Has demostrado ser $gun guerrero:una guerrera; excelente, $n, pero todavía eres joven y tienes mucho que aprender.$B$BVe a hablar con Harry Burlguard, suele estar en la taberna El Cerdo Borracho, en el Casco Antiguo de Ventormenta. Harry es un viejo veterano y un buen instructor. Puede enseñarte algunos movimientos que te ayudarán a seguir con vida algo más tiempo.", t = "Instrucción de guerrero"},
    [1639] = {ot = "Habla con Bartleby.", st = "Sí, puedo enseñarte. Pero primero quiero ver tus movimientos.$B$B¿Ves a aquel borracho al fondo del bar? ¿Bartleby? Quiero que cojas su jarra.$B$BJe, y si conoces a Bartleby sabrás que no va a dártela sin más.", t = "Bartleby, el borracho"},
    [1640] = {ot = "Golpea a Bartleby y habla con él.", st = "¿¿Que quieres qué?? ¡Estás $gloco:loca;!$B$BSolo me quitarás la jarra de mis manos frías y muertas...", t = "Vence a Bartleby"},
    [1641] = {t = "Escrito sobre divinidad"},
    [1642] = {ot = "Habla con Duthorian Rall en Ventormenta.", st = "Un paladín debe reflejar en todas las cosas la Luz que complementa su fuerza. El esfuerzo por alcanzar la divinidad, para uno de nosotros, no significa aspirar al bien, pues aspiramos al bien en todas nuestras acciones.$B$BAunque en estos duros tiempos somos convocados para atacar al mal, debes recordar que será la ayuda que prestes a los demás lo que te distinguirá de los ciudadanos de Azeroth. La compasión, la paciencia y el valor tienen tanta importancia en un paladín como su fuerza en la batalla.$B$BAprende esto ahora y nunca lo olvides.", t = "Escrito sobre divinidad"},
    [1643] = {ot = "Busca a Stephanie Turner en el Distrito de Mercaderes de Ventormenta.", st = "Ahora, tu tarea, $n, es encontrar en Ventormenta a alguien que necesite ayuda. Alguien de intenciones y corazón puros. Quizás alguien que ayude a los demás. Alguien que necesite ser guiado. En cualquier caso, esa persona debe tener intenciones nobles y depender de tu bondad.$B$BVuelve a mí cuando hayas acabado. Entonces seguiremos hablando de tu camino y de lo que significa ser un paladín de la Luz.", t = "Escrito sobre divinidad"},
    [1644] = {ot = "Lleva 10 retales de paño de lino a Stephanie Turner a Ventormenta.", st = "Benditos sean, la mayoría de ellos han perdido a su familia en la última década... a manos de la Plaga.$B$BMi marido John recoge material para que yo haga camisas y pantalones para los niños, pero no he tenido tiempo de hacerlo. Mi primera preocupación ha sido ponerles comida que en el plato y procurarles un techo.$B$B¿Cómo dices? ¿Que quieres ayudar? ¡Oh, gracias a la Luz! ¡Y gracias a ti, $n!$B$BSi pudieras traerme paño de lino para que cosa ropa para los niños, me ayudarías mucho.", t = "Escrito sobre divinidad"},
    [1645] = {t = "Escrito sobre divinidad"},
    [1646] = {ot = "Ve a Forjaz y habla con Tiza Forjabatalla.", st = "Un paladín debe reflejar en todas las cosas la Luz que complementa su fuerza. El esfuerzo por alcanzar la divinidad, para uno de nosotros, no significa aspirar al bien, pues aspiramos al bien en todas nuestras acciones.$B$BAunque en estos duros tiempos somos convocados para atacar al mal, debes recordar que será la ayuda que prestes a los demás lo que te distinguirá de los ciudadanos de Azeroth. La compasión, la paciencia y el valor tienen tanta importancia en un paladín como su fuerza en la batalla.$B$BAprende esto ahora y nunca lo olvides.", t = "Escrito sobre divinidad"},
    [1647] = {ot = "Busca a John Turner en el anillo exterior de Forjaz.", st = "Ahora, tu tarea, $n, es encontrar en Forjaz a alguien que necesite ayuda. Alguien de intenciones y corazón puros. Quizás alguien que ayude a los demás. Quizás alguien que necesite ser guiado. En cualquier caso, esa persona debe tener intenciones nobles y depender de tu bondad.$B$BVuelve a mí cuando hayas acabado. Entonces seguiremos hablando de tu camino y de lo que significa ser un paladín de la Luz. Esperaré tu regreso en el templo. Habrá otros paladines que necesiten mi guía.", t = "Escrito sobre divinidad"},
    [1648] = {ot = "Lleva 10 retales de paño de lino a John Turner a Forjaz.", st = "Mi esposa y yo llevamos un orfanato en Ventormenta. En los últimos diez años hemos acogido a muchos niños que han perdido a sus padres en ataques del Azote. Yo vengo a Forjaz más o menos cada mes. Recojo suministros que me dan los habitantes y hablo con todos los grupos para ver si pueden ayudar en algo.$B$BEste viaje ha sido de una lentitud agonizante y no muy productivo.$B$BSi pudieras conseguirme más tela para que mi mujer haga algo de ropa, podría por fin hacer un envío a casa.", t = "Escrito sobre divinidad"},
    [1649] = {ot = "Habla con Duthorian Rall en Ventormenta.", st = "El valor y todas las virtudes que lo acompañan, son como minerales preciosos y poco comunes: debes apreciarlos cuando los encuentras porque son valiosos, pero también debes invertir tiempo en cuidarlos... refinarlos. Cuando se mezclan correctamente, se forma una fuerte aleación que, algunas veces, resulta imposible de romper, incluso con los golpes más poderosos.$B$BTodo esto debe ser puesto a prueba: la fuerza, tu fe, tu valentía. Debes aprender a no perder la fe y darte cuenta de que con el poder de la Luz, puedes conseguir cosas que otros no pueden.", t = "Escrito sobre valor"},
    [1650] = {ot = "Encuentra a Daphne Fontana en los Páramos de Poniente.", st = "¡Bien! Que no vaciles es una señal inequívoca de que estás $gpreparado:preparada; y $gdispuesto:dispuesta; a ponerte a prueba. Que así sea.$B$BJusto al final de Playa Larga, en los Páramos de Poniente, hay una pequeña casa con vistas al océano. Allí vive una pareja, los Fontana. Jordan es un herrero fabuloso y ha ido a Forjaz a pasar una temporada con los enanos. Pero esto ha dejado a Daphne, su mujer, sola y desprotegida.$B$BLos informes sugieren que los Defias han tomado casi toda la zona, es posible que Daphne necesite protección. Ve allí.", t = "Escrito sobre valor"},
    [1651] = {ot = "Defiende a Daphne Fontana del ataque de los Defias.$B$BSi quieres tener éxito, sus espíritus no pueden salir de sus espirales mortales.$B$BCuando lo hayas conseguido, vuelve a hablar con Daphne Fontana.", st = "Apuesto a que volverán pronto, así que debes prepararte.$B$BTengo una pistola en la casa. La tomaré y me prepararé para ayudarte pero, en general, estarás $gsolo:sola;.$B$BNo tengo ni idea de cuántos mandarán, pero seguro que serán más de los que mandaron antes.$B$BRuega a la Luz que nos bendiga porque... ¿Has oído eso? Creo que vienen ya.$B$B¡Nos colocaremos cerca de la casa!", t = "Escrito sobre valor"},
    [1652] = {ot = "Habla con Duthorian Rall en Ventormenta.", st = "Por favor, vuelve a ver a Duthorian y dile que, por ahora, estoy a salvo. Y todo gracias a ti y a la iglesia.$B$BÉl enviará el mensaje a Forjaz para que mi querido Jordan sepa que no tiene nada que temer.$B$B¡Oh, cómo echo de menos a mi marido! Qué ganas tengo de que vuelva.", t = "Escrito sobre valor"},
    [1653] = {ot = "Habla con Jordan Fontana en Forjaz.", st = "No dudo que Jordan desea darte las gracias personalmente, y puesto que debo enviarle mensaje de que su esposa está bien, creo que eres la mejor elección.$B$BJordan iba a ser paladín de la Luz hasta que su dedicación al arte de su padre lo llevó por otros derroteros; conoce bien nuestro modo de vida y lo consideramos uno de nuestros más devotos.$B$BEstará en Forjaz; le gusta trabajar en el exterior por algo relacionado con el aire fresco.", t = "La prueba de rectitud"},
    [1654] = {ot = "Consulta la lista y llévale a Jordan Fontana de Forjaz lo siguiente: madera de roble de Piedrablanca, envío de oro refinado de Bailor, el martillo de herrero de Jordan y una gema Kor.", st = "Si aceptas, te recompensaré. Entiéndeme bien, mi generosidad depende de hasta qué punto me ayudes, pero creo que una alianza nos sería beneficiosa.$B$BTe haré un arma digna de tus logros, un símbolo de los paladines y de la Luz, pero tienes que traerme los objetos que necesito para crearla. Tengo aquí la lista; solo necesito a alguien valiente que vaya a buscar los objetos. ¿Qué me dices, $c?", t = "La prueba de rectitud"},
    [1656] = {ot = "Lleva el fardo de pelajes al tabernero Kauth al Poblado Pezuña de Sangre.", st = "Por favor, $n, ¿puedes ayudarme? Estoy cumpliendo la prueba del Rito de la Fuerza; mi padre me pidió que entregara estas pieles en la posada de Pezuña de Sangre.$B$BNo puedo completar el rito y el recado de mi padre; no tengo fuerzas. ¿Puedes hacer la entrega por mí?$B$BLa posada es un sitio muy agradable para descansar de tanto viaje; seguro que me lo agradecerás.", t = "Una tarea por terminar"},
    [1665] = {ot = "Lleva la jarra de Bartleby a Burlguard.", st = "Vale, vale, toma mi jarra. Pero deja que me la acabe... Aquí tienes.", t = "La jarra de Bartleby"},
    [1680] = {ot = "Habla con Tormus Forjahonda.", st = "Ahora que ya has aprendido nuevos movimientos, es el momento de darte un arma decente. Ve a hablar con Tormus Forjahonda. Te hará un arma que seguro que te gustará.$B$BLo encontrarás aquí, en Forjaz, en La Gran Fundición.", t = "Tormus Forjahonda"},
    [1683] = {ot = "Lleva el cuerno de Vorlus a Elanaria en Darnassus.", st = "Antes de poder instruirte, debes mostrarme tu determinación.$B$BEl sátiro Vorlus Pezuñavil ha encontrado una de nuestras pozas de la Luna más remotas, al sureste del Túmulo de Ban'ethil. Ahora se pasa el día chapoteando en sus aguas y corrompiéndolas con su mugre.$B$BEncuentra a Vorlus en la Poza de la Luna y termina con él. Tráeme su cuerno como prueba y comenzaré tu instrucción avanzada como $gguerrero:guerrera;.$B$BEl camino a la Poza de la Luna está bien escondido, $n, pero mantente $gconcentrado:concentrada; y alerta y lo encontrarás.", t = "Vorlus Pezuñavil"},
    [1684] = {ot = "Habla con Elanaria.", st = "Saludos, $gguerrero:guerrera;. Tus habilidades siguen creciendo, pero hay mucho más de lo que crees en tu profesión. Para seguir progresando debes encontrar a un instructor.$B$BLa guerrera Elanaria vive en Darnassus, en el Bancal del Guerrero. Ella podrá instruirte.", t = "Elanaria"},
    [1685] = {ot = "Preséntate ante Gakin el Presotenebra en el Barrio de los Magos de Ventormenta.", st = "Si es que... siempre igual. Me he pasado el día buscándote sin encontrarte y ahora, cuando ya ni te esperaba, te plantas aquí, sin más.$B$BYa he perdido demasiado tiempo buscándote. No perdamos más. El maestro Gakin te ha convocado para instruirte. Creo que deberías ir en su busca lo antes posible.$B$BLo encontrarás en el sótano de la posada El Cordero Degollado. Por cierto, será mejor que no comentes por ahí ese detalle de la posada... No queremos que se corra la voz de dónde se encuentra...", t = "La invocación de Gakin"},
    [1688] = {ot = "Consigue la gargantilla de Surena para Gakin el Presotenebra de Ventormenta.", st = "Tenía una estudiante llamada Surena Caledon. Estuvo donde tú estás ahora, ansiosa por aprender la magia de los brujos y sin tener siquiera una pizca de talento. Además, era joven y muy atractiva. Si lo hubiera sabido, ¡maldita traidora!$b$bLa arpía ladrona huyó con uno de los Defias, Erlan Yermestia. Si bien su pérdida no tiene importancia, le obsequié una gargantilla de sangrita que debo recuperar.$b$bSu vida ya no significa nada para mí. Puedes encontrarla en la Plantación de Calabazas de Brackwell. Tráeme lo que me pertenece.", t = "Surena Caledon"},
    [1689] = {ot = "Con la gargantilla de sangrita, invoca y somete a un abisario. Después devuelve la gargantilla de sangrita a Gakin el Presotenebra, en Ventormenta.", st = "Al recuperar mi gargantilla y vencer a Surena has demostrado ser, al menos, tan capaz como ella.$B$BCon eso dicho, también debo decirte que necesitas instrucción desesperadamente. Puedes controlar los flujos de la magia, sí, pero ser un brujo es mucho más que eso.$B$BTe demostraré como controlar a un abisario, pero antes de poder hacerlo, debes invocar a uno en un Círculo de Invocación y dominarlo con todas las armas, tanto físicas como mágicas, que tienes a tu disposición. Utiliza la magia de esta gargantilla en el Círculo de Invocación que está ahí abajo.", t = "El vínculo"},
    [1699] = {ot = "Entra en las Cavernas de Rethban, llega hasta la primera bifurcación y regresa junto a Yorus Cebadiz en el tiempo estipulado.$B$BNo debes morir y liberar tu espíritu.", st = "He llamado a mi desafío El guantelete de Rethban. Para superar la prueba, todo lo que tienes que hacer es entrar en las Cavernas de Rethban, hasta el primer cruce, y volver aquí. ¡Es fácil! Aunque hay algunos peros...$B$BTienes que volver en una hora.$B$BEncontrarás montones de gnolls de Crestagrana en el camino$B$BAntes de empezar tienes que tomar un trago de la bebida de mi familia: ¡brebaje de Cebadiz!$B$BBueno, ¿qué dices? Las Cavernas de Rethban están en las laderas al norte de Villa del Lago. ¿Estás $glisto:lista; para afrontar El guantelete de Rethban?", t = "El guantelete de Rethban"},
    [1701] = {ot = "Reúne los materiales que necesita Furen Barbalarga y llévaselos a Ventormenta.", st = "Te he dado un buen escudo, pero la cosa no termina aquí. Conozco los secretos para hacer una armadura de malla extremadamente dura. No es fácil y se necesitan algunos materiales bastante extraños, pero si quieres hacer tú los preparativos te haré una pieza.$B$B¿Qué me dices, $n? Si estás $glisto:lista; para el desafío, te daré una lista de lo que necesitas y dónde conseguirlo.", t = "Armadura de malla endurecida con fuego"},
    [1702] = {ot = "Lleva el barril de brebaje a Furen Barbalarga.", st = "Superando El guantelete de Rethban has demostrado de qué estás $ghecho:hecha;, $n. Y yo soy fiel a mi palabra. Te daré la recompensa prometida...$B$BEl único problema es que está en Ventormenta.$B$BVe a hablar con mi amigo, Furen Barbalarga, en el Distrito de los Enanos de Ventormenta. Es el mejor forjador de escudos que podrás encontrar, y me debe un gran favor.$B$BToma, llévale este barril de brebaje de Cebadiz a Furen y pídele un escudo. Seguro que te dará uno estupendo.", t = "El forjador de escudos"},
    [1716] = {ot = "Habla con Takar el Vidente en Los Baldíos.", st = "Un sayaad es un devorador de almas, un dominador de voluntades con la capacidad de tentar corazones. Lo único que sabe hacer es el mal.\n\nLos relatos más lujuriosos se refieren al demonio por su nombre común: “súcubo” para las hembras, “íncubo” para los machos.\n\nSe requiere de un estímulo para invocar a la criatura. Con un símbolo de amor como carnada, seguramente atenderá tu llamado. Si la derrotas, se convertirá en tu instrumento.\n\nPero no será fácil encontrar algo así. Deberías hablar con Takar el Vidente. Puedes encontrarlo en Los Baldíos de Kalimdor, cerca del Campamento Taurajo.", t = "Devoradora de almas"},
    [1718] = {ot = "Habla con Klannoc Macleod.", st = "Tu fama como $gguerrero:guerrera; no deja de crecer, $n. Ha llegado el momento de enfrentarte a tus pares y ver cuál es tu posición entre ellos.$B$BHay una isla en la costa de Los Baldíos, al sur de Trinquete. Es conocida como Isla de Batalla y en ella se encuentran los guerreros.$B$BSe encuentran y combaten.$B$BHabla con el jefe guerrero de Isla de Batalla, Klannoc Macleod. Si te juzga $gdigno:digna; te guiará por la senda del guerrero.$B$BPara llegar a Isla de Batalla, busca el banco de arena que cubre La Costa Mercante.", t = "El isleño"},
    [1719] = {ot = "Mata a Will el Grande y habla con Klannoc Macleod en Isla de Batalla.", st = "Si quieres instruirte conmigo tendrás que superar La Reyerta. Es un desafío que ofrecemos aquí, en Isla de Batalla, a los guerreros que se creen fuertes, si superas la prueba sabremos que lo eres.$B$BPara empezar dirígete al centro de esa multitud y ponte en la rejilla. Así indicarás a Twiggy Cabezaplana que estás $gpreparado:preparada; y enviará a tus contrincantes.$B$BDerrótalos y llamará a Will el Grande. Mata a Will el Grande y vuelve a verme dentro del tiempo permitido.", t = "La Reyerta"},
    [1738] = {ot = "Recupera el duramen de Vallefresno y llévaselo a Gakin el Presotenebra en el Barrio de los Magos de Ventormenta.", st = "Para preparar tu llegada, utilicé mi visión para ver por encima del mundo y a través de la niebla del tiempo. He encontrado lo que buscas.$B$BEn la Guerra de los Ancestros, dos amantes cayeron juntos en combate. En el lugar donde exhalaron su último aliento, nació un árbol conocido como el duramen, un símbolo de su amor imperecedero.$B$BEso debería ser suficiente para tentar a un súcubo. Lo encontrarás en las Ruinas de Ordil'Aran, en la parte noroeste del Bosque de Vallefresno.", t = "Duramen"},
    [1739] = {ot = "Utilizando el corazón del duramen, invoca y somete a un súcubo. Después devuelve el corazón del duramen a Gakin el Presotenebra en El Cordero Degollado.", st = "Utilizando el corazón del duramen, podrás lanzar un hechizo en el Círculo de Invocación de la cripta subterránea para abrir un portal y que pueda pasar el súcubo.$B$BTen cuidado, $n, algunos súcubos han dominado incluso a las mentes más fuertes.$B$BCuando hayas vencido y lo devuelvas al vacío, vuelve a verme y te enseñaré a invocarlo y controlarlo.", t = "El vínculo"},
    [1740] = {ot = "Encuentra 3 fragmentos de Soran'ruk y 1 fragmento grande de Soran'ruk y llévaselos a Doan Karhan en Los Baldíos.", st = "Cuando los demonios de la Legión caen en desgracia, sus espíritus se encarcelan en unos orbes que se distribuyen entre sus magos y brujos.$B$BMuchos fueron llevados por sus sirvientes en Azeroth. Incluso rotos en trozos, poseen los poderes de los demonios atrapados en ellos.$B$BEl orbe de Soran'ruk se partió en dos piezas, una de las cuales se rompió en pedazos aún más pequeños para los acólitos del Martillo Crepuscular de las Cavernas de Brazanegra. La otra, la de mayor tamaño, acabó en manos de un mago del Castillo de Colmillo Oscuro. Encuéntralas y podré reconstituirlo.", t = "El orbe de Soran'ruk"},
    [1778] = {ot = "Ve a Forjaz y habla con Tiza Forjabatalla.", st = "Voy a empezar a hacer planes para volver pronto a casa. Espero que a Stephanie le vaya bien en Ventormenta. Estoy deseando volver a verla. Hasta la próxima, $c.", t = "Escrito sobre divinidad"},
    [1779] = {ot = "Coge el Símbolo de la Vida y habla con Muiredon Forjabatalla. Está en Forjaz.", st = "Quiero que cojas esto, $n. Se llama Símbolo de la Vida.$B$BHas demostrado tener paciencia y caridad y ahora quiero que pruebes tus aptitudes y tu poder en combate.$B$BMi marido Muiredon tuvo hace poco un encuentro con unos enanos Hierro Negro en el que casi pierde la vida. Y ahí está... Uno de nuestros sacerdotes está curando sus heridas.$B$BCoge el Símbolo y habla con él. Si puedes ayudarle, volveremos a hablar. Pronto. Que la Luz sea contigo.", t = "Escrito sobre divinidad"},
    [1780] = {ot = "Habla con Duthorian Rall en Ventormenta.", st = "Llevaré esto a los niños hoy mismo. Cuídate, por favor, $gbuen:buena; $c. No encuentra una a menudo personas como tú en la ciudad. Has demostrado que los paladines de Ventormenta nunca vuelven la espalda a quienes los necesitan.$B$BAdiós.", t = "Escrito sobre divinidad"},
    [1781] = {ot = "Lleva el Símbolo de la Vida a Gazin Tenorm a Ventormenta.", st = "Coge esto, $n. Se llama Símbolo de la Vida.$B$BHas demostrado ser paciente y $gcaritativo:caritativa; y ahora ha llegado el momento de ver si tienes poder suficiente para centrarte en uno de los mayores dones de la Luz.$B$BMi amigo Gazin tuvo hace poco un encuentro con unos Defias en Elwynn, cerca de la Vigilia de los Héroes... casi le cuesta la vida. Está cerca del altar. Uno de nuestros sacerdotes está curando sus heridas.$B$BLlévale el Símbolo y habla con él. Si puedes ayudarle, volveremos a hablar. Pronto. Que la gloria de la Luz sea contigo.", t = "Escrito sobre divinidad"},
    [1783] = {ot = "Coge el Símbolo de la Vida y resucita a Narm Faulk en Dun Morogh.", st = "Estábamos espiando a unos enanos Hierro Negro que se habían establecido en un búnker al sur del Lago de Helm. Sabíamos que no tramaban nada bueno. Por eso Narm y yo quisimos echar un vistazo de cerca. Vimos a su líder dando órdenes a sus hombres.$B$BNarm y yo aprovechamos la ocasión para matar a algunos de ellos, pero enseguida llegaron más. Y eran más fuertes de lo que creíamos. Narm me dijo que corriera a buscar refuerzos, así que aquí estoy.$B$BNarm necesita ayuda y no descansaré hasta que la consiga.$B$B¿Puedes ayudarnos, $n?", t = "Escrito sobre divinidad"},
    [1784] = {ot = "Consigue una misiva Hierro Negro de los enanos Hierro Negro que están cerca de Helm y luego vuelve a Forjaz y busca a Muiredon Forjabatalla.", st = "Antes de que yo cayera en combate, Muiredon y yo casi habíamos derrotado a uno de los espías Hierro Negro cerca de esa casa pequeña. Vimos cómo su capitán repartía órdenes e intentamos matar a uno de ellos y hacernos con esas órdenes.$B$BEn el Consejo de Forjaz hay quien todavía no cree que en Dun Morogh haya enanos Hierro Negro. Si conseguimos esas órdenes, no solo tendremos una prueba de su presencia, sino que además, podremos hacernos una idea de lo que planean.$B$BConsigue una de esas órdenes y llévasela a Muiredon, $n.", t = "Escrito sobre divinidad"},
    [1785] = {ot = "Ve a Forjaz y habla con Tiza Forjabatalla.", st = "Ya'stoy viendo a mi mujer hinchándose d'orgullo. Más te vale ir yendo p'allá ya mismo. Creo que querrá echarse unas palabras contigo.$B$BQue la Luz t'acompañe, potente $c. Te buscaré en el campo de batalla cuando llegue el momento de luchar contra la Plaga y los Hierro Negro esos.", t = "Escrito sobre divinidad"},
    [1786] = {ot = "Coge el Símbolo de la Vida y resucita a Henze Faulk en Elwynn.", st = "Henze y yo conseguimos llegar a la Vigilia de los Héroes, una isla que hay en el centro del Lago del Hito, al noreste de Elwynn. Habíamos oído que los Defias habían cruzado nuestras fronteras y queríamos conseguir pruebas para los consejeros del Rey.$B$BVimos a un par de esos tipos leyendo unos documentos y atacamos. Por desgracia, llegaron más magos y pronto nos vimos superados.$B$BHenze los contuvo mientras yo escapaba... ese tonto, haciéndose el héroe...$B$BAhora está ahí, solo... ¿Puedes ayudarnos, $n?", t = "Escrito sobre divinidad"},
    [1787] = {ot = "Recupera 1 misiva Defias de los zahoríes bribones Defias de Elwynn y vuelve con Gazin Tenorm a Ventormenta.", st = "Ya tendremos ocasión de hablar sobre el Símbolo más adelante. Lo importante ahora es conseguir esos papeles que tenían los Defias. Si logramos hacernos con ellos, podremos probar que la banda Defias se ha infiltrado en Elwynn y, con suerte, averiguaremos cuáles son sus planes.$B$BYo ahora no estoy en disposición de combatir, $n. ¿Crees que tienes la fuerza necesaria para arrebatar esos papeles a los Defias de la isla?$B$BSi consigues hacerte con ellos, llévaselos a Gazin. Y dile también que estoy bien.", t = "Escrito sobre divinidad"},
    [1788] = {ot = "Habla con Duthorian Rall en Ventormenta.", st = "Cuando Duthorian haya echado un vistazo a este texto, se lo llevaré a los consejeros del Rey. Pero tú deberías ir a hablar con Duthorian ya. ¡Querrá darte una palmadita en la espalda!$B$BGracias otra vez, $n. Espero que volvamos a encontrarnos. Eres $gun aliado al:una aliada a la; que me enorgullece considerar $gun amigo:una amiga; también.", t = "Escrito sobre divinidad"},
    [1791] = {ot = "Habla con Bath'rah el Vigía del viento.", st = "Ahora que has aprendido la actitud rabiosa, querrás tener una buena arma.$B$BVe a hablar con Bath'rah el Vigía del viento, un ermitaño trol que vive entre las Montañas de Alterac y las Tierras de la Peste del Oeste. Es un forjador de armas muy diestro y un poderoso chamán.$B$BPara encontrar a Bath'rah ve hasta el río que fluye en el lado oriental del Molino Tarren. Síguelo hacia el Norte. Bath'rah está acampado junto a las ruinas que encontrarás en la orilla oriental del río.", t = "El Vigía del viento"},
    [1793] = {t = "Escrito sobre valor"},
    [1818] = {ot = "Habla con el Guardia de la Muerte Dillinger en Rémol.", st = "Me han dicho que el Guardia de la Muerte Dillinger tiene un trabajo para alguien como tú. Si quieres probar tu valor para las fuerzas de la Dama Oscura, informa inmediatamente a Dillinger.$B$BEl puesto del Guardia de la Muerte Dillinger está en el extremo occidental de Rémol, junto al cementerio.", t = "Habla con Dillinger"},
    [1819] = {ot = "Mata a Ulag el Cuchilla y ve a hablar con el Guardia de la Muerte Dillinger.", st = "Cuando la Plaga se extendió por los Claros de Tirisfal, capturamos a uno de ellos para someterlo a estudio. Tenía una mente libre, se llamaba a sí mismo Ulag el Cuchilla. Pero, aunque era libre, seguía cautivado por el Rey Exánime.$B$BEsperábamos encontrar un modo de romper el control del rey sobre Ulag, pero fracasamos. Ahora, por fin, ha llegado el momento de liberarle.$B$BLibérale y mátale.$B$BActiva el disparador de piedra calavera junto al mausoleo del Norte. Así levantarás el sello que le mantiene atado.$B$BCuando lo hagas... estate $gpreparado:preparada;, $n.", t = "Ulag el Cuchilla"},
    [1820] = {ot = "Habla con Coleman Farthing.", st = "Has demostrado tu valor a la Dama Oscura, quizás ahora puedas probarte ante uno de sus súbditos.$B$BColeman Farthing aguarda a un guerrero que quiera convertirse en su instrumento de venganza contra los enemigos de los Renegados.$B$BLo encontrarás en el Mesón La Horca, en la parte oriental de Rémol.", t = "Habla con Coleman"},
    [1821] = {ot = "Lleva a Coleman Farthing el hacha de la familia Agamand, la espada de la familia Agamand, la maza de la familia Agamand y la daga de la familia Agamand.", st = "Los Agamand fueron mis empleadores en vida, ¡y fueron el motivo de mi muerte! Los Agamand se merecen ser los esbirros descerebrados del Rey Exánime.$B$BY yo me quedaré con los últimos vestigios de su honor. Ve a la cripta familiar y róbales sus reliquias familiares: una espada, un hacha, una daga y una maza. ¡Tráeme todo a mí!$B$BLa cripta de la familia Agamand está al norte de los Molinos de Agamand, protegida por la Plaga y los Agamand muertos.", t = "Reliquias Agamand"},
    [1822] = {t = "Arma reliquia"},
    [1823] = {ot = "Habla con Ruga Tótem de Ira.", st = "Eres $gun guerrero:una guerrera; de fama y talento. ¿Estás $gpreparado:preparada; para la prueba de Ruga Tótem de Ira? Si lo estás, encontrarás a Ruga en Campamento Taurajo, en Los Baldíos.$B$BEstá esperando a todo guerrero que responda a su llamada.", t = "Habla con Ruga"},
    [1824] = {ot = "Lleva 5 antenas agitadas a Ruga Tótem de Ira de Campamento Taurajo.", st = "Para superar la prueba debes viajar hacia el Sur, hasta Tierra de Gigantes. Allí encontrarás gran cantidad de criaturas reptantes, insectos. Son nuevas en Los Baldíos y no me gusta lo que presagian.$B$BTráeme sus antenas cuando aún sigan agitándose y no pierdas tiempo, $n, o las antenas dejarán de agitarse. Tráeme las antenas en el tiempo previsto y superarás la prueba.", t = "Prueba en Tierra de Gigantes"},
    [1838] = {ot = "Lleva 15 lingotes de hierro humeantes, 10 azuritas en polvo, 10 barras de hierro y un vial de flogisto a Thun'grim Vistafuego.", st = "He oído hablar de tu fuerza y valor y me gustaría hacerte una armadura, una compañera que te ayudará en tus nuevas hazañas.$B$BPero la elaboración de la armadura será una auténtica misión, $n. Necesitaré tu ayuda y la de otros herreros de la Horda.$B$BToma, coge este pergamino. He pasado muchas noches luchando con mis ojos casi ciegos, escribiendo lo que necesito para la armadura. Tráeme los objetos que aparecen en el pergamino y crearé la primera pieza de la armadura.", t = "Armadura brutal"},
    [1858] = {ot = "Roba la llave de Tazan, abre su cartera y llévale el contenido a Therzok al Circo de las Sombras, en Orgrimmar.", st = "Tú te encargas de abrirla, luego tráeme el contenido. La cerradura es complicada, así que lo más fácil será que consigas la llave.$B$BComo Tazan no la llevaba encima, debemos suponer que se la dio a alguien... Ah, claro. Tenía un secretario, un borracho que se llama Gamon. Lo más seguro es que esté en la taberna; intenta quitarle la llave.", t = "Mano Destrozada"},
    [1859] = {ot = "Ve a Orgrimmar, al Circo de las Sombras, y habla con Therzok.", st = "Baja la voz, $n. Sé quién eres. Tenía tu descripción y te esperaba.$B$BPor lo que he oído de ti, te manejas bien en combate y no te opones a alguna incursioncilla que otra de vez en cuando.$B$B¿Me equivoco?$B$BEs lo mismo. Tienes que ir a Orgrimmar a ver a Therzok. Tiene una oferta que hacerte.", t = "Therzok"},
    [1860] = {ot = "Habla con Jennea Cañón en Ventormenta.", st = "Los magos tenemos una tarea por hacer, y es vital para la seguridad de Ventormenta y del Bosque de Elwynn.$B$BJennea Cañón sabe los detalles. Estudia en el Sagrario del Mago, en el Barrio de los Magos de Ventormenta. Deberías ir a verla lo antes posible.", t = "Habla con Jennea"},
    [1879] = {ot = "Habla con Bink en Forjaz.", st = "¡$n! Bink, mi colega gnomo de Forjaz, ha enviado un mensaje. ¡Tiene una tarea que hacer y solo confía en un mago para hacerlo! ¿Serás tú ese mago, $n?$B$BSi es así, ve a hablar con Bink. La encontrarás en la Sala de los Misterios en La Sala Mística de Forjaz.", t = "Habla con Bink"},
    [1881] = {ot = "Habla con Anastasia Hartwell.", st = "$n, Anastasia Hartwell tiene una misión para alguien con tus aptitudes. Habla con ella en el Barrio de la Magia en Entrañas y prepárate para tu primera tarea como mago de los Renegados.", t = "Habla con Anastasia"},
    [1882] = {ot = "Lleva las Bocas de dragón de Balnir a Anastasia Hartwell en el Barrio de los Magos de Entrañas.", st = "Las Tierras de la Peste del Este son una aberración. Ideadas por el Rey Exánime, propagan su magia a la tierra, corrompiendo y matando toda forma de vida. Aunque las fuerzas destructivas de la Peste tienen un cierto encanto, nosotros, los magos de los Renegados, creemos que es indomable y que debe ser reducida.$B$BPero antes de nada, debemos medir hasta qué punto se ha propagado en Tirisfal. Ve a la Hacienda Balnir en la parte oriental de Tirisfal. En el jardín encontrarás flores: Bocas de dragón. Recógelas y vuelve a verme.", t = "La Hacienda Balnir"},
    [1885] = {ot = "Habla con Mennet Carkad en el Barrio de los Pícaros de Entrañas.", st = "¿$n? No eres exactamente como esperaba, teniendo en cuenta que el mismísimo Carkad se ha interesado por ti. Si bien es cierto que la primera impresión no siempre es la que cuenta, ¿no crees?$B$BEn cualquier caso, deberías ir a verlo tan pronto como puedas. No te gustaría saber lo que les ocurrió a los que hicieron caso omiso a su llamada.", t = "Mennet Carkad"},
    [1886] = {ot = "Consigue la carta de presentación de Astor y devuélvesela a Mennet Carkad, en el Barrio de los Pícaros.", st = "Si quieres formar parte de los mortacechadores, la guardia de élite de Lord Varimathras, tendrás que demostrar tu valía.$B$BNo quiero mentirte, $n, esta misión puede suponer tu muerte.$B$BYo tengo otras cosas que requieren de mi atención. Necesito los efectos personales de Astor Hadren, un mensajero que viaja entre el Bosque de Argénteos y Entrañas. Te dejo a tu elección el método que debes utilizar.$B$BCuanto menos sepas sobre la naturaleza de su negocio, mejor para ti. Si realizas con éxito está misión, te contaré más.", t = "Los mortacechadores"},
    [1898] = {ot = "Habla con Andron Gant en Entrañas.", st = "La carta de presentación debería ser suficiente para convencer a Andron de que tú eres $gel mensajero:la mensajera; que estaba esperando. Conozco bien a Andron y sé que no es demasiado desconfiado.$B$BLord Varimathras sospecha que Andron ha estado ayudando a otro grupo. Desea saber de qué organización se trata y quiere pruebas.$B$BQuiero que vayas a hablar con Andron y que obtengas esta información. Lo encontrarás en su tienda, cerca de El Apothecarium.", t = "Los mortacechadores"},
    [1899] = {ot = "Llévale el libro de contabilidad de Astor a Mennet Carkad en el Barrio de los Pícaros, en Entrañas.", st = "Encontrarás el libro de contabilidad con la información que buscan los que te envían en la estantería que está a mis espaldas. Llévaselo y diles que preferiría que te enviaran a ti en caso de que deseen seguir adelante con nuestro plan.", t = "Los mortacechadores"},
    [1918] = {ot = "Llévale el globo de agua contaminada a Mastok Bufido en el Puesto del Hachazo, Vallefresno.", st = "El elemental caído creó un globo de agua de brillo intenso. El contenido del globo es, cuando menos, repulsivo. No es descabellado suponer que lo que contaminó el Lago Mystral también puede estar presente en el agua del globo.$b$bNo es fácil saber quién podría estar interesado en semejante hallazgo. Quizá la persona que te envió a investigar el lago, Mastok Bufido de Puesto del Hachazo, tenga alguna idea.", t = "El elemento contaminado"},
    [1919] = {ot = "Habla con Jennea Cañón en Ventormenta.", st = "Tu conocimiento sobre esta disciplina no deja de crecer, joven $n. ¿Estás $glisto:lista; para comenzar las auténticas lecciones? ¿Estás $glisto:lista; para ocupar tu lugar en la guerra secreta en la que estamos embarcados?$B$BSi es así, ve a hablar con Jennea Cañón, en el Sagrario del Mago, en el Barrio de los Magos de Ventormenta. Tiene una tarea para ti y esa tarea te abrirá la primera ventana al mundo de lo invisible.", t = "Preséntate ante Jennea"},
    [1920] = {ot = "Detrás de Jennea Cañón encontrarás un Canto de manifestación y un cofre de arcas de contención. Cógelos y lleva 3 arcas de contención llenas a Jennea, en el Sagrario del Mago.", st = "Han llegado informes de una alteración en la taberna El Ermitaño Taciturno del Barrio de los Magos. Criaturas invisibles y extrañas vagan por la taberna y temo que se haya formado una falla de maná.$B$BQuiero que investigues la taberna y que captures a esas criaturas. Utiliza el Canto de manifestación en la taberna para hacer visibles a las criaturas, cuando las tengas dominadas utiliza un arca de contención para capturarlas. Cuando tengas bastantes vuelve a verme trayendo contigo las arcas llenas y vacías y el Canto.", t = "Investiga lo que pasa en El Ermitaño Taciturno"},
    [1960] = {ot = "Detrás de Anastasia Hartwell encontrarás un Canto de manifestación y un cofre de arcas de contención. Cógelos y lleva 3 arcas de contención llenas, el cofre de arcas de contención y el canto de manifestación a Anastasia en Entrañas.", st = "La tienda de alquimia de Algernon, en El Apothecarium, es el centro de una extraña alteración. Criaturas invisibles, hechas tan solo de magia, vagan por la tienda... ¡debe haber una razón y debemos descubrirla!$B$BInvestiga la alteración y captura a esas criaturas. Coge el cofre de arcas y el pergamino que hay detrás de mí. Utiliza el pergamino en la tienda para hacer visibles a las criaturas, cuando las hayas dominado con tus hechizos, arroja un arca para capturarlas. Vuelve con las arcas llenas, el cofre y el canto.", t = "Investiga la tienda de alquimia"},
    [1961] = {ot = "Llévale 10 linos y 6 gemas de maná de Dalaran a Josef Gregorian.", st = "Ha llegado la hora de que tengas tus primeras togas mágicas, $n. Son un símbolo de tu condición y un testimonio de tu valor.$B$BPara obtenerlas, deberás recoger gemas de maná de los magos de Dalaran, en los Argénteos. Sus creencias son similares a las nuestras, por lo que matarlos no es nada placentero, pero bueno, si no son capaces de hacernos frente, la verdad que merecen morir.$B$BTrae las gemas y un poco de lino para Josef Gregorian en la tienda de sastrería del Barrio de la Magia.", t = "Recolección de materiales"},
    [1962] = {t = "Toga de fuego de hechizo"},
    [1963] = {ot = "Mata a Tazan y llévale su cartera a Therzok al Circo de las Sombras, en Orgrimmar.", st = "El Jefe de Guerra es demasiado cauteloso a la hora de usar el poder de la Horda. En el pasado fuimos conquistadores y debemos volver a serlo. Mano Destrozada se encargará de eso.$B$BAtacamos al enemigo expuesto desde la sombra, para reducir sus filas en secreto. Hay algo que debes hacer para probar tu valía.$B$BEl trol Tazan, que comercia con los piratas cerca de Trinquete, tiene información que me interesa. Mátalo y tráeme su cartera.", t = "Mano Destrozada"},
    [1978] = {ot = "Entrégale el libro de contabilidad de Andron a Varimathras, que está en la Cámara de la Dama Oscura en Entrañas.", st = "¿La Hermandad? Nunca lo habría sospechado. Parece que la traición de los señores de Alterac comenzó hace años.$B$BLord Varimathras se complacerá de escuchar esto, y como tú has sido una pieza clave en este descubrimiento, sería perfecto si se lo hicieras llegar tú mismo.$B$BY por cierto, no me he olvidado:$B$B$gbienvenido:bienvenida; a los mortacechadores.", t = "Los mortacechadores"},
    [1998] = {ot = "Mata a Fenwick Thatros y llévale su cabeza a Mennet Carkad, que está en el Barrio de los Pícaros de Entrañas.", st = "Lord Varimathras me ha enviado una misiva sobre una amenaza para los no-muertos que debe ser eliminada de inmediato. Su nombre es Fenwick Thatros, el que Lord Varimathras cree que es el líder de los no-muertos que se han asentado en el Bosque de Argénteos.$B$BTu nombre me vino a la mente rápidamente, $n. Confío en tus facultades y sé que podrás realizar esta misión a la perfección.$B$BSegún los mortacechadores del Bosque de Argénteos, puedes encontrar a Thatros cerca del embarcadero destartalado de Lordamere.", t = "Fenwick Thatros"},
    [2038] = {ot = "Localiza las herramientas de Bingles y devuélveselas:$b$bllave inglesa, destornillador, martillo y cartucho de explosivos.", st = "Por si no fuera bastante haberme estrellado en Loch Modan, me atacaron unos troggs de una isla cercana y me robaron las herramientas y mis cartuchos de explosivos Pimpampum. ¡Sin girocóptero y sin explosivos no hay nada que hacer!$B$BTráeme mis herramientas y mis explosivos, $n. ¡Por Gnomeregan!", t = "Suministros de Bingles"},
    [2039] = {ot = "Encuentra a Bingles Pimpampum en Loch Modan.", st = "¡Hemos perdido contacto con Bingles! Fue a una misión de reconocimiento a Gnomeregan hace una semana y no ha vuelto a dar señales de vida. Seguro que ha saltado por los aires.$B$BLa última vez que se le vio, volaba sobre Loch Modan. Quizás tú puedas enterarte de qué ha pasado, $n.", t = "Encuentra a Bingles"},
    [2040] = {ot = "Recupera la Dentrituradora goblin de Las Minas de la Muerte y devuélveselo a Shoni la Shilenshiosha, en Ventormenta.", st = "¡Esos malditos troggs han tomado Gnomeregan! La situación es grave, pero quizás puedas ayudar, $n.$B$BEn las profundidades de Las Minas de la Muerte hay una trituradora goblin operativa. Encuentra la trituradora y trae su batería intacta. Con la batería de la trituradora, podemos dar a nuestras excavadoras gyroagujereamáticas la energía necesaria para atravesar los rocosos límites subterráneos de Gnomeregan, ¡y nos abrirán el camino para el asalto gnomo!", t = "Asalto subterráneo"},
    [2041] = {ot = "Habla con Shoni la Shilenshiosha en Ventormenta.", st = "A lo mejor... A lo mejor puedes ayudarnos en la batalla por Gnomeregan.$B$BVe a Ventormenta a hablar con Shoni la Shilenshiosha, la jefa de trabajos subterráneos. Necesita un cable con las excavadoras gyroagujereamáticas.$B$BLo más seguro es que esté con los enanos en Ventormenta.$B$BSuerte, $n.", t = "Habla con Shoni"},
    [2078] = {ot = "Encuentra el Trillomajareitor 4100, el contramaestre de Gelkak, y condúcelo hasta él.", st = "Tienes que encontrar a mi contramaestre, $gmarinero:marinera; de agua dulce.$B$BCoge esta llave, pónsela en la cabeza y tráelo aquí, con su capitán.$B$BEsos múrlocs no son sus dueños... ¡ya se darán cuenta cuando mi segundo se encargue de ellos!", t = "La venganza de Gyromast"},
    [2098] = {ot = "Encuentra y devuelve los tres fragmentos de la llave de Gelkak Gyromast.", st = "La vida del pirata no es fácil, te lo digo yo. ¡No es todo abordajes y ron! También hay desgracia... Mi barco se hundió cerca de la costa por culpa de esos malditos trillanodontes.$B$B¡Necesito tener conmigo a mi contramaestre! ¡Cuanto antes!$B$BCuando alcancé la costa se me cayó la llave de mi segundo de a bordo en las rocas y me la robaron esas bestias de Costa Oscura. Por el rabillo del ojo pude ver reptadores furiosos, feroces zancudos de bosque y múrlocs rebuscando entre los restos del naufragio.", t = "La búsqueda de Gyromast"},
    [2118] = {ot = "Captura un oso cardo rabioso vivo y llévaselo a Tharnariun. $B$BSi no consigues capturar un oso cardo rabioso y pierdes la trampa, pídele otra a Tharnariun Espinarbolado.", st = "Por Costa Oscura se extiende una enfermedad que se hace con la mente y el cuerpo de todo lo que toca.$B$BLos osos cardo han sido los más afectados por esta plaga. Eran nobles animales que se han convertido en rabiosos objetos de destrucción. Creo que yo podría tener una cura para este mal.$B$BLleva esta trampa al bosque y colócala en el suelo. Cualquier oso cardo rabioso que cruce la luz será manso por un breve período de tiempo. Y cuando esto ocurra, te seguirá. Guía uno hasta aquí, $n.", t = "Tierras apestadas"},
    [2138] = {ot = "Libra al bosque de 20 Osos Cardo rabiosos y ve a buscar a Tharnariun Espinarbolado a Costa Oscura.", st = "Tal y como temía... la cura no funciona.$B$BMe entristece ordenar la muerte de una criatura de la naturaleza, pero estos osos enfermos deben ser sacrificados.$B$BVuelve al bosque y mata a 20 Osos Cardo rabiosos, $n. Eso no detendrá la plaga pero, al menos durante un tiempo, reducirá el daño que esos animales están haciendo al bosque y a sus habitantes.", t = "La limpieza de la infección"},
    [2139] = {ot = "Encuentra a la madre del cubil y mátala.", st = "El precio por la supervivencia de nuestra gente y nuestras tierras es muy alto, $n.\n\nHas derramado la sangre de muchos siervos de la naturaleza. Has derribado a muchos animales enfermos. Los habitantes de Auberdine están en deuda contigo, pues, aunque sea solo por un tiempo, has mitigado el dolor del bosque...\n\nTengo una última tarea para ti. Pero te advierto, tendrás que volver a matar. Tengo la esperanza de que esta sea la última vez que recurro a ti, $n.\n\nAl noreste hay una cueva, cerca de Bashal'Aran. En ella reside la madre del cubil. Mátala.", t = "La esperanza de Tharnariun"},
    [2158] = {ot = "Habla con el tabernero Farley de la Posada Orgullo de León.", st = "Todos los aventureros deben descansar cuando les invade el agotamiento, ¡y no hay mejor lugar para descansar que la Posada Orgullo de León!$B$BMi mejor amigo, el tabernero Farley, lleva la Posada Orgullo de León. Si le dices que te envío yo, puede que te haga un descuento en la comida y la bebida.$B$BPara encontrar la Posada Orgullo de León, viaja al sur por el camino que sale de aquí, ¡no tiene pérdida!", t = "Descanso y relajación"},
    [2159] = {ot = "Llévale el paquete de Dolanaar al tabernero Keldamyr.", st = "Saludos, joven $c. ¿Me podrías prestar tu ayuda? Tengo un paquete de hierbas que debo entregar en la ciudad de Dolanaar pero todavía tengo asuntos pendientes con los druidas de Cañada Umbría y no puedo irme.$B$B¿Puedes entregar este paquete por mí? Su destinatario es el tabernero Keldamyr de la posada de Dolanaar, que se encuentra un poco más adelante en dirección sur.", t = "Paquete de Dolanaar"},
    [2160] = {ot = "Lleva a Kharanos el cajón de suministros del mesón y entrégaselo a Tannok Martilloescarcha.", st = "¡Eh! Tienes pinta de ser de corazón aventurero. Si vas a arriesgarte a atravesar el paso, ¿crees que podrías llevar un paquete a la posada de Kharanos?$B$BPorque pensabas hacer un alto en la posada, ¿no? Sí, seguro, si consigues cruzar el paso, necesitarás descansar un poco.$B$BY como vas a pasar por allí, no te costará nada entregar esto a Tannok Martilloescarcha, el ayudante del tabernero. Yo no puedo cruzar el paso ¡y pasarán días hasta que llegue una escolta de montaraces!", t = "Suministros para Tannok"},
    [2161] = {ot = "Lleva la carga de Ukor al tabernero Grosk a Cerrotajo.", st = "Perdón... ¿Puedes ayudarme?$B$BTengo un montón de comida aquí. ¡Y por el camino he tenido que afrontar escórpidos y arañas y cosas peores! Traje la comida al Valle de los Retos porque pensaba que la necesitarían y quería ayudar. ¡Pero no necesitan comida! Y ahora tengo que llevármela de vuelta a Cerrotajo y tengo miedo de las bestias que pueda encontrarme por el camino...$B$B¿Podrías llevarla tú por mí? Yo soy una criatura insignificante y tú, sin embargo, eres un ser aguerrido. ¡No temes a nada!$B$BLlévaselo al tabernero Grosk de la posada de Cerrotajo. ¡Gracias!", t = "Un cargamento de peón"},
    [2178] = {ot = "Llévale 5 piezas de carne de zancudo a Alanndarian Arrullanoche a Auberdine.", st = "¿Hueles ese delicioso aroma? Es mi receta secreta, $n: guiso de zancudo recién hecho. ¡Es una delicia!$B$BQuizás te interese aprender la receta...$B$BPues para que te la enseñe, tendrás que probarme que eres capaz de dominar a las bestias.$B$BNo espero que salgas, domestiques a un zancudo y vuelvas cabalgando en él, pero si consigues matar a unos pocos y traerme algo de su suculenta carne, me dejaría convencer para compartir mi receta.", t = "Guiso de zancudo"},
    [2205] = {ot = "Entrega el paquete de Keryn Sylvius al maestro Mathias Shaw que está en el Cuartel de Ventormenta.", st = "¿La insignia? Oh, no es nada, pescadito. Al menos nada que tú puedas arreglar. Por la pinta que tienes, diría que Mathias, más que pensar que eres $gun pícaro:una pícara;, te tomaría por $gel chico:la chica; de los recados del quesero. Además, el trabajo me fue asignado a mí y fui yo quien se comprometió a hacerlo.$B$BHablando de lo cual... lleva este paquete a Mathias. Quizás te dé un par de pequeñas tareas.$B$BEn marcha. |n", t = "Busca el IV:7"},
    [2218] = {ot = "Ve a Forjaz y habla con Hulfdan Barbanegra.", st = "Otra alma perdida buscando guía, ¿eh? Supongo que quieres encontrar un propósito en esta vida... tu propósito. Lo he visto mil veces, todos los héroes acaban buscando trabajo.$B$BPues bien, hoy es tu día de suerte. Hogral tiene la cura para tu mal.$B$BTe voy a dar algo que hacer: Sigue este sendero hasta Forjaz y ábrete camino hasta La Caverna Abandonada. Una vez en ella, localiza a la hermandad de ladrones y habla con Hulfdan Barbanegra. Él te indicará el camino hacia la salvación.|n", t = "El camino hacia la salvación"},
    [2241] = {ot = "Llévale la rosa de Jannok a Syurna, que está en Darnassus.", st = "Dicen que soy un \"amante furibundo\", aunque no sé muy bien a qué se refieren.$B$BEs cierto que pienso en todo momento en Syurna, que mi casa está repleta de retratos de ella, y que paso días enteros sin comer, beber o dormir lamentándome por el amor que podríamos haber tenido. ¿Acaso es algo malo?$B$B¡Y ella no quiere verme! ¡A MÍ! He intentado enviarle mensajes pero ya no habla con nadie que no sea un pícaro.$B$B¿Podrías llevarle tú esta flor? No olvides decirle que es de parte de Jannok.", t = "Cuando cae la manzana"},
    [2242] = {ot = "Encuentra a Sethir el Ancestro y ve a contarle todo lo que descubras a Syurna.|n", st = "Creemos que hay un ser que podría ayudarnos a entender qué está ocurriendo en los bosques de Teldrassil. Por desgracia, los intentos de convencer a la criatura para que coopere han fracasado.$B$BSe esconde en una rama a las afueras de El Claro del Oráculo. Todos los que se han acercado al sátiro, ya sea por las buenas o por las malas, han encontrado la muerte. Quizás el sigilo sea la respuesta, $n.$B$BConsigue lo que porta Sethir el Ancestro en sus talegas y vuelve a verme.|n", t = "La llamada del destino"},
    [2281] = {ot = "Ve a Villa del Lago en las Montañas Crestagrana y habla con Lucius.\n", st = "Enviarte ahora a la batalla sería suicida. Renzik no necesita otro pícaro muerto en sus manos. Pero no te apresures, $n, ya te meterá prisa Renzik.$B$BDirígete hacia las Montañas Crestagrana y habla con Lucius, es un miembro del IV:7. Lo encontrarás en el embarcadero de Villa del Lago, con los demás vagos y maleantes.", t = "Cita en Crestagrana"},
    [2282] = {ot = "Abre la caja fuerte de Lucius y llévale la muestra de robo a Villa del Lago.", st = "¡Llevamos años entrenando ladrones aquí! No todos los bribones nacen con los dedos ligeros del amigo Lucius.$B$BSigue el camino y encontrarás el Molino de Alther. Dentro hay un cofre con algo importante. Tráeme lo que contiene y te ganarás tu Certificado de Ratería.", t = "Molino de Alther"},
    [2298] = {ot = "Viaja a Ventormenta y busca a Renzik \"Chafarote\".", st = "Y ahí estábamos, a punto de empezar a planear la fase III, cuando llegaron un par de esos brutos de Magni hablando de un atraco o algo así y arrestaron a gente del círculo oculto.$B$B¡Y al viejo Barbanegra no le arresta nadie! Los ánimos se caldearon y no sé cómo, salió a relucir tu nombre.$B$B¿Mi consejo? Coge el primer grifo que salga de Forjaz y ve a Ventormenta. Ve al Casco Antiguo y habla con un viejo amigo mío que se llama Renzik \"Chafarote\".", t = "Una regia sacudida"},
    [2359] = {ot = "Roba la Llave de la Torre Defias, entra en la Torre Defias y descubre qué contiene el Cofre del Bosque del Ocaso. Lleva toda la información que encuentres a Mathias Shaw de Ventormenta. Lee el diario de Kearnen para saber cómo acceder a la torre.|n", st = "Hace semanas que vigilo esta torre, $n. Hace poco pasó un gran cargamento procedente del Bosque del Ocaso, y con él vinieron esos guardias.$B$B¿Qué son? Tu suposición es tan acertada como la mía: no son humanos.$B$BEn cualquier caso, en el cargamento había un cofre, supongo que es lo que guardaban esas abominaciones. El zombi con los pinchos tiene una llave que necesitaremos.$B$BConsigue esa llave, ve a la torre y averigua qué hay en ese cofre. Lleva a Mathias lo que descubras.", t = "La torre de Klaven"},
    [2360] = {ot = "Ve a los Páramos de Poniente y encuentra a la agente Kearnen para dar parte.", st = "Justo a tiempo, $n. La división de reconocimiento del IV:7 ha informado sobre un aumento de actividad Defias en los Páramos de Poniente.$B$BParece ser que los Defias han tomado una atalaya abandonada de la Alianza al sureste de la Colina del Centinela y la están utilizando como base de operaciones para robar mercancías de la ruta de suministros de Crestagrana.$B$BVe a los Páramos de Poniente y contacta con la agente Kearnen para dar parte. La encontrarás escondida, cerca de la torre.$B$B... Y $n, si te descubrieran, el IV:7 negaría todo conocimiento de tu existencia.", t = "Mathias y los Defias"},
    [2378] = {ot = "Viaja a Orgrimmar y habla con Shenthul, que estará en el Circo de las Sombras.|n", st = "Has servido con diligencia a los mortacechadores, $n, pero quizás sea hora de que vayas más allá. Aunque tengas cualidades para el sigilo y el engaño, debes continuar con tu instrucción.$B$BLos mortacechadores cuentan con aliados entre los Mano Destrozada. Busca a los que nos puedan echar una mano; encuentra a Shenthul en Orgrimmar.|n", t = "Encuentra a los Mano Destrozada"},
    [2379] = {ot = "Habla con Zando'zan en el Circo de las Sombras.", st = "No conseguirás superar los obstáculos que nos esperan solo con fuerza de voluntad.$B$BHabla con Zando'zan para empezar tu formación como miembro de Mano Destrozada.$B$BSolo cuando domines el sigilo y el robo podrás seguir tu camino hacia tu destino.|n", t = "Zando'zan"},
    [2381] = {ot = "Llévale el tesoro de los Mares del Sur a Desdio el Desdichado en Trinquete. No olvides conseguir una G.E.A.Q. y herramientas de ladrones del aparato Gizmotrónico de Wrenix. Necesitarás todo eso para completar tu misión.$B$BSi te atacaran unos loros anormalmente agresivos, ¡usa la G.E.A.Q.!|n|n", st = "No quiero asustarte, $n, pero los cinco últimos ladrones a los que había enviado a robar el tesoro de los Mares del Sur acabaron en pedacitos.$B$BHacia el sur, bordeando la costa, encontrarás el Surcamareas, el barco de los filibusteros de los Mares del Sur. A buen recaudo en la bodega se encuentra el premio: el tesoro de los Mares del Sur. En el segundo nivel de ese barco está la guarida de los piratas, un lugar donde practican todos sus ladrones.$B$BSube a bordo de ese barco, roba el tesoro y tráemelo. Usa la guarida de los piratas si necesitas practicar cómo robar ¡pero ten cuidado!|n", t = "Saquear a los saqueadores"},
    [2382] = {ot = "Viaja a Trinquete y habla con Desdio el Desdichado.", st = "Zando'zan ha visto que se acerca, sí, la muerte se acerca a Thrall. Será un puñal en la espalda, o un veneno que recorra su cuerpo... Zando'zan ha dicho demasiado.$B$B¡$n! Zando'zan tiene una misión para $n. $n tiene que ir a Trinquete, que está al este de El Cruce, y hablar con Desdio el Desdichado. Ve.|n", t = "Desdio de Trinquete"},
    [2383] = {ot = "Lee el Pergamino simple y habla con Frang en el Valle de los Retos.", st = "Ah, mientras estabas fuera llegó un papiro para ti, $n.$B$BLéelo cuando tengas tiempo, si no me equivoco viene de parte del instructor de guerreros, Frang. Querrá tener unas palabras contigo cuando estés $glisto:lista;. Lo encontrarás a las puertas de El Cubil, al abrigo de la sombra.", t = "Papiro simple"},
    [2399] = {t = "Flora en brote"},
    [2438] = {ot = "Llévale el atrapasueños esmeralda a Tallonkai Cruzarraíz en Dolanaar.", st = "Gaerolas Talvethen, el celador de Túmulo de Ban'ethil, me dio una vez un atrapasueños esmeralda. Este poderoso amuleto es capaz de extraer la energía del Sueño Esmeralda y dar buena suerte a quien lo porta.$B$BPor desgracia, me lo he dejado en Aldea Brisa Estelar... A pesar de que en un tiempo Brisa Estelar fue un lugar tranquilo, ahora ha sucumbido a la corrupción de los fúrbolgs que allí habitan.$B$B¿Estás $gdispuesto:dispuesta; a recuperar mi atrapasueños, $c?", t = "El atrapasueños esmeralda"},
    [2458] = {ot = "Ve a la torre de Ventura y Cía., al norte de El Fangal, y localiza al capataz Fizzule, el agente de Mano Destrozada. $b$bCuando veas la torre, usa la pistola de bengalas para avisar de tu llegada al capataz Fizzule. Lanza 2 bengalas y acércate al capataz para darle el /saludo de los Mano Destrozada. $b$bTienes que hacerlo en este orden, porque Fizzule te matará si no te reconoce.", st = "¿Has oído hablar de Ventura y Cía.?$B$BNos ha costado un año de duros esfuerzos, pero hemos conseguido infiltrar un agente.$B$BHemos descubierto que planean algo a gran escala. Ve hacia el norte, a El Fangal; en la torre de Ventura y Cía. Encontrarás a nuestro agente, el capataz Fizzule.$B$BCuando encuentres la torre, dispara la pistola de bengalas, busca a Fizzule y dale el saludo de Mano Destrozada.|n", t = "Agente encubierto"},
    [2459] = {ot = "Tallonkai Cruzarraíz de Dolanaar quiere que mates a 7 místicos Tuercepinos y encuentres la joya perdida.", st = "La esmeralda... ¡ha desaparecido! ¡Mi atrapasueños está estropeado!$B$BHay un grupo de místicos Tuercepinos al norte de Brisa Estelar. He oído que su líder, Ferocitas el Comesueños, tiene un collar que brilla de noche con una luz de color verde. Por el aspecto de mi atrapasueños, estoy seguro de que él me ha robado la esmeralda... No se daría cuenta ni en mil años de que el poder de la esmeralda es inútil en sus manos.$B$BEncuentra la joya perdida, $n. Y aprovecha para matar también a algunos místicos corruptos.", t = "Ferocitas el Comesueños"},
    [2460] = {ot = "Da el saludo de los Mano Destrozada a Shenthul.", st = "Si quieres pertenecer a Mano Destrozada, tendrás que aprender el saludo. Es la única forma de identificar a los miembros.$B$BMírame, apréndelo y repite.", t = "El saludo de los Mano Destrozada"},
    [2478] = {ot = "Roba la llave de la torre del supervisor Silixiz, mata a 2 zánganos mutados de Ventura y Cía., 2 patrullas de Ventura y Cía. y 2 oteadores de Ventura y Cía.$B$BAsesina al gran supervisor Puzik Gallywix y quédate con su cabeza, fuerza la cerradura del arcón de Gallywix y roba la mezcla de Zanzil modificada que allí está oculta. Lleva el alijo y la cabeza de Gallywix a Shenthul en Orgrimmar, él te dará más instrucciones.|n", st = "Tendrás que robarle la llave de la torre al supervisor Silixiz, $n. Cuando la llave esté en tus manos, quédatela, podría necesitarla más tarde.$B$BRecuerda, el veneno lo ha debilitado todo en esta torre. Usa todos tus recursos para sembrar el caos y la destrucción entre sus habitantes. Masácralos a todos ¡sin piedad!$B$BCuando todo esté bañado en sangre, toma la caja fuerte de Gallywix y roba el preparado de Zanzil ahí guardado. Lleva la cabeza de Gallywix y el preparado a Shenthul en Orgrimmar.", t = "Misión: Posible, pero no probable"},
    [2479] = {ot = "Ve a Molino Tarren, en Laderas de Trabalomas, para entregar la muestra de Zanzil a Serge Hinott. $b$bPara llegar a Molino Tarren, coge el zepelín a Entrañas y sigue el camino hacia el sur por el Bosque de Argénteos hacia Trabalomas. ¡Sigue las indicaciones!|n|n", st = "Llévale una muestra de la mixtura a Serge Hinott, que está en Molino Tarren.$B$BSi hay alguien que pueda curarte, ese es él. Si vives lo suficiente, te enseñará a crear y usar venenos.", t = "La ayuda de Hinott"},
    [2480] = {ot = "Espera a que Serge Hinott te cure.", st = "¡Jamás vi un veneno con tan extraordinario efecto! ¿Zanzil, dices? Nunca he oído hablar de él, pero admiro su genio por crear este brebaje.$B$B¿Quieres que te cure y te enseñe a usar el veneno?$B$BDame un momento para examinar la toxina, $n.", t = "La ayuda de Hinott"},
    [2498] = {ot = "Rellian Verdeguja quiere que hables con Denalan, que está en el Lago Al'Ameth.", st = "Me acabo de enterar de que Denalan, que está en el Lago Al'Ameth, ha descubierto la causa de los tumores que les nacen a los Brezomadera. Por favor, habla con él y dile que vas de mi parte.$B$BDate prisa, $n, pues necesita tu ayuda.", t = "Regresa junto a Denalan"},
    [2499] = {ot = "Denalan del Lago Al'Ameth quiere que consigas el tumor gigantesco de Roblegüello.", st = "En una cueva junto al banco del sur del lago, un brezomadera llamado Roblegüello está propagando la corrupción a todas las criaturas que habitan en Lago Al'Ameth.$B$BNo me atreví a acercarme demasiado, pero incluso desde una distancia, es bastante obvio que a Roblegüello lo está envenenando el tumor más grande que jamás he visto...  Me atrevería a decir que es gigantesco.$B$B$n, ya has hecho muchísimo para ayudarnos, pero debo pedirte que realices una tarea más. Caza a Roblegüello y recoge el tumor; extirpa esta fuente de corrupción de mi hogar.", t = "Roblegüello"},
    [2518] = {ot = "La sacerdotisa A'moora del Templo de la Luna en Darnassus quiere que le lleves las hileras de plata de Lady Sathrah.", st = "Lady Sathrah estuvo una vez en la gracia de Elune. Elegante y pura, la araña tejía sus telas de plata a la luz de la luna, y atrapaba la niebla de la noche. El rocío plateado tenía grandes poderes curativos y se guardó aquí, en el templo.$B$BPero en los últimos tiempos, Sathrah fue consumida por la locura y ahora sus crías también están en peligro.$B$B$n, encuentra a Lady Sathrah y ponle fin a su sufrimiento. Suele estar al noreste de Teldrassil, cerca del Lago Primigenio. Recoge sus hileras de plata y tráemelas.", t = "Las lágrimas de la Luna"},
    [2519] = {ot = "La hermana Aquinne quiere que hables con la sacerdotisa A'moora en el Templo de la Luna.", st = "Una criatura del bosque, en su día grandiosa, necesita ayuda, $r.$B$BHay una difícil tarea que cumplir.$B$BPor favor, busca a la sacerdotisa A'moora; ella te lo explicará todo. La encontrarás al sudeste de aquí, dentro del Templo de la Luna.", t = "El templo de la Luna"},
    [2520] = {ot = "La sacerdotisa A'moora quiere que coloques las hileras de plata de Lady Sathrah en la fuente que hay en el interior del templo, y que después vayas a verla de nuevo.", st = "Ahora has de cumplir con el cometido que te ha sido asignado. Coge las hileras y ofrece el sacrificio de Lady Sathrah como ofrenda a Elune.$B$BEn el interior de este templo se encuentra la fuente central, lugar en el que debes colocar la ofrenda. Las aguas sagradas purificarán y eliminarán la corrupción que hizo enloquecer a Sathrah.$B$BCuando hayas cumplido tu cometido, vuelve a verme.", t = "El Sacrificio de Sathrah"},
    [2541] = {ot = "Llévale un talismán de vudú chamán a Oben Garrafuria al Túmulo de Ban'ethil.", st = "Los chamanes Tuercepinos que habitan este lugar han descubierto un modo de separar el espíritu de un druida durmiente de su cuerpo físico. Los fúrbolgs han reanimado mi representación física y la están utilizando para atacar a todo el que intente entrar en Túmulo de Ban'ethil. Yo estoy atrapado en el Sueño Esmeralda y no puedo hacer nada para detenerlos.$B$BTienes que ayudarme. Los chamanes Tuercepinos portan un extraño talismán para llevar a cabo el ritual y me gustaría examinarlo. Por favor $n, tráeme uno.", t = "El druida durmiente"},
    [2561] = {ot = "Oben Garrafuria quiere que mates su cuerpo desalmado y luego uses el talismán vudú.", st = "Tras haber estudiado el talismán, $n, veo con claridad lo que hay que hacer. Tómalo y haz lo que te digo.$B$BDebes explorar las áreas más profundas del Túmulo de Ban'ethil. Allí encontrarás mi cuerpo desalmado... Aunque me cueste aceptar lo que voy a decir, no veo otro modo de liberarme del control de los Tuercepinos.$B$BPara que pueda escapar, debes matar mi forma física. Después, utiliza el talismán vudú sobre mi cuerpo inerte. Vuelve a verme cuando hayas cumplido tu cometido.", t = "El druida de la Zarpa"},
    [2607] = {ot = "Habla con Doc Mixilpixil en el sótano de los Cuarteles.", st = "Parece ser que has obtenido más información de la que me esperaba. Ciertamente, esto es un extraño giro de los acontecimientos, $n.$B$B¿Una cura? Mmm... Vete al sótano y habla con Doc Mixilpixil. Quizás pueda ayudarte.", t = "Toque de Zanzil"},
    [2608] = {ot = "Túmbate para que te examine Doc Mixilpixil. ¿Cómo va a encontrar la cura si no encuentra la causa?|n", st = "¡Oh! Pareces como $gmuerto:muerta;. Corrección, he visto muchos muertos, tú tienes peor aspecto. $gCaballero:Señorita;, tú serías lo que la muerte obtuvo como resultado en su último examen médico.$B$B¡Ja! ¿Has oído eso, Noarm? ¡Escríbelo!$B$B*Tose* Mmm, sí. Para poder ayudarte, necesito sacarte sangre. No te preocupes, solo duele las primeras... cincuenta veces, o así... Túmbate cuando estés $gpreparado:preparada; para el tratamiento, $n.", t = "Toque de Zanzil"},
    [2609] = {ot = "Lleva a Doc Mixilpixil un ramo de flores silvestres simples, un vial emplomado, un tubo de bronce y una bobina de hilo de seda verde pistacho. La 'itis' no se cura sola, $gjovencito:jovencita;.", st = "Es unánime, $n. Tienes la 'itis'.$B$BPor suerte para ti, tengo la cura para la 'itis'.$B$BEsto es lo que necesito: un ramo de flores silvestres simples, un vial emplomado, un tubo de bronce y por último, pero no menos importante, una bobina de hilo de seda verde pistacho. La vieja Emma dejó una bobina para mí en 'El Paño Fino'. Podrás encontrar la tienda en los canales.$B$BY ahora date prisa, $n, e intenta no tocar a nadie hasta que estés $gcurado:curada;. Oh, y el doctor Montgomery dice que necesitas una ducha... Lo dice él, no yo.", t = "Toque de Zanzil"},
    [2745] = {ot = "Habla con Tyrion en el Castillo de Ventormenta.", st = "Mmm, una historia interesante, y bastante grave. Sí, puedo ayudarte, pero si quieres que esto salga bien, lo que necesitas es impartir una forma de justicia que no es... legal.$B$BHay que encargarse de Lescovar y Marzon y lo más rápido posible. ¿Crees que eres capaz de algo así?$B$BTú decides. Si es así, apresúrate al castillo y busca a un viejo amigo mío, un gnomo llamado Tyrion. Lleva un par de semanas vigilando a Lescovar. Debería poder ayudarte con esto.", t = "Infíltrate en el castillo"},
    [2746] = {ot = "Lleva 3 paños de seda y 2 manzanas frescas de Clara a Tyrion en Ventormenta.", st = "Trias quiere que adelantemos el plan, ¿eh? Muy bien, podemos hacerlo, pero todavía tengo que terminar de prepararme. Y, has de saber una cosa, yo me encargo de la parte difícil, pero tú eres quien se va a ensuciar las manos. Bien.$B$BDe acuerdo, necesito que me consigas un par de cosas antes de poder poner mi plan en marcha. Tengo el disfraz perfecto para que el robot espía pase por delante de esos guardias.$B$BTráeme seda y un par de manzanas. La seda la tienes que buscar, pero la pequeña granja de Clara, justo en las afueras de la ciudad, tiene las manzanas del tamaño perfecto.", t = "Objetos importantes"},
    [2841] = {ot = "Consigue la combinación de la caja fuerte de Termochufe en Gnomeregan y lleva los planos de la plataforma a Nogg a Orgrimmar.|n", st = "Hasta hace dos años, la tecnología gnómica solo servía para echarse unas risas. Las cosas han cambiado mucho; han construido una plataforma mejor que todas las nuestras juntas. ¡Quiero los planos, $n!$B$BEstán en una caja fuerte cerca del mekigeniero Termochufe. Para empeorar las cosas, él es el único que sabe la combinación.$B$BHaz lo que sea por conseguirla, $n. ¡Tienes que abrir la caja y traerme los planos!|n", t = "Las guerras de la plataforma"},
    [2842] = {ot = "Habla con Scooty en Bahía del Botín.", st = "En cuanto Kernobee nos avisó de lo de la plataforma gnómica, Scooty y yo empezamos a trabajar en el Transpoliportador 6000. Es el medio más seguro y rápido para ir a Gnomeregan.$B$BYa está a punto para despegar. Si quieres probarlo, $n, ve a Bahía del Botín y habla con Scooty en la alcándara de jinete de Viento. Para ir a Bahía del Botín tienes que coger el barco en Trinquete.$B$BPor supuesto, puedes ir a Gnomeregan cruzando las montañas de Dun Morogh, que están infestadas de enanos.", t = "Scooty, ingeniero jefe"},
    [2843] = {t = "¡Gnomer-yaaaaa!"},
    [2904] = {ot = "Acompaña a Kernobee a La Rampa del Engranaje y luego ve a ver a Scooty a Bahía del Botín.", st = "<Kernobee gruñe.> ¿Qué...? ¿Qué ha pasado?$B$BSolo recuerdo que me capturó un grupo de enanos Hierro Negro, me dieron una paliza de muerte y me echaron aquí, con estos asquerosos troggs.$B$B¡Sácame de aquí, $n!$B$BEste es el plan: llévame a la salida; si sobrevivimos, tú te vas a la Bahía del Botín y le dices a Scooty que he ido a Trinquete para avisar a Manitas de Oro que los Hierro Negro están metidos en lo de la superplataforma.$B$B¡Andando!", t = "Un buen lío"},
    [2922] = {t = "¡Salva el cerebro de Tecnobot!"},
    [2923] = {ot = "Habla con el maestro manitas Sobrechispa en Forjaz.", st = "El maestro manitas Sobrechispa está muy disgustado con lo ocurrido a su obra mecánica, Tecnobot. Por lo que sé, Tecnobot era una herramienta muy útil para los gnomos, pero dice que se ha averiado.$B$BLástima. ¡Aunque con suerte se podrá arreglar!$B$BVe a hablar con Sobrechispa a Ciudad Manitas, en Forjaz. Se alegrará de que vayas a ayudarlo.", t = "Maestro manitas Sobrechispa"},
    [2924] = {ot = "Lleva 12 esencias artificiales a Klockmort Palmalicate a Forjaz.", st = "Los herreros y manitas de Gnomeregan usaban un componente mecánico casi universal, la esencia artificial, en su trabajo. Pero durante la huida de la ciudad, ¡nadie pensó en recoger esencia! Necesitaré mucha para un trabajo que estoy a punto de empezar.$B$BTe ruego que vayas a Gnomeregan a conseguirme esencia artificial. Está en las zonas más profundas de la ciudad, en unos contenedores que se llaman extrapoladores artificiales.$B$B¡Date prisa y muchas gracias, $n!", t = "Esencias artificiales"},
    [2926] = {ot = "Usa la ampolla de plomo vacía con invasores o saqueadores irradiados para recoger restos radiactivos. Cuando esté llena, llévasela a Ozzie Voltiflop a Kharanos.", st = "Desde el accidente, Gnoarn no piensa en otra cosa que en expulsar a los troggs de Gnomeregan y encontrar una cura para la plaga, $n.$B$BPor suerte, Razzle y yo estamos a punto de conseguirlo; o eso, o hemos destilado un ron muy potente. ¡No lo sabremos hasta que lo probemos! Claro que para poner a prueba nuestra teoría, necesitamos algunas cosas, como restos de los troggs radiactivos en Gnomeregan. ¡Llena esta ampolla de material verdoso radiactivo y tráela de regreso!", t = "Gnogaína"},
    [2927] = {ot = "Habla con Ozzie Voltiflop en Kharanos.", st = "¿Crees que siempre he sido calvo? ¡Pues no $gseñor:señorita;! Perdí todo el pelo por culpa de la fuga radiactiva de Gnomeregan. Hasta entonces, tenía una mata de pelognomo única en todo Azeroth.$B$B<Sacude los puños.>$B$B¡Así se pudran esos malditos troggs en las simas del averno!$B$BA lo mejor no es tarde, $n. Aún podemos salvarla. ¡A la ciudad, me refiero! Ve a hablar con Ozzie Voltiflop en Kharanos. Está buscando una solución con su colega Razzle.", t = "Al día siguiente"},
    [2928] = {ot = "Lleva veinticuatro entrañas robomecánicas a Shoni en Ventormenta.", st = "Es terrible, $n. No vamos a tener suficientes repuestos para llevar nuestra flota de excavadoras gyroagujereamáticas a Dun Morogh.$B$BLo que necesitamos son repuestos, $n. ¿Y qué mejor lugar que Gnomeregan para conseguir repuestos para nuestros vehículos? He oído que robots y mecazancudos vagan libremente por ese lugar.$B$BNecesito que vayas a Gnomeregan y destruyas a esos robots. Tráeme sus entrañas robot. Con dos docenas tendré suficiente.|n", t = "Excavadoras gyroagujereamáticas"},
    [2929] = {ot = "Ve a Gnomeregan y mata al mekigeniero Termochufe. Ve a ver al Manitas Mayor Mekkatorque cuando hayas terminado.", st = "Yo confiaba en Termochufe, $r. Nunca pensé que me traicionaría a mí y a todos los gnomos. ¿Y por qué? ¿Por el poder? ¿Por el dinero? Habría conseguido todo eso por sí mismo. Ahora nos han echado de nuestro hogar y ese chiflado es el que manda. Rey de pacotilla...$B$BVamos a recuperar Gnomeregan, $n. No cejaremos hasta que la ciudad vuelva a nuestras manos. Si quieres ayudarnos, tengo un trabajito para ti. Mata al traidor. Acaba con el mekigeniero Termochufe.", t = "La gran traición"},
    [2930] = {ot = "Lleva una tarjeta perforada prismática al maestro mecánico Funditubo a Forjaz.", st = "¡Cuando tuvimos que huir de Gnomeregan, dejamos atrás información muy valiosa! ¡Qué digo, valiosa! ¡Vital!$B$BNecesito los datos de la tarjeta perforada prismática de un Perforágrafo Matriz 3005-D de alta seguridad oculto en Gnomeregan. Tienes que acceder a la terminal, pero para eso necesitas un permiso... Y para eso tienes que acceder a una terminal de baja seguridad de los modelos -A, -B y -C. Y para eso, necesitas tarjetas perforadas de seguridad en blanco... y todas se quedaron en la ciudad.$B$B¡Qué desastre! ¿Puedes ayudarme?", t = "Rescatar los datos"},
    [2945] = {ot = "Encuentra la manera de limpiar el anillo sucio.", st = "Has encontrado algo que parece un anillo en el cadáver de un enano Hierro Negro. Está cubierto de barro y restos secos y endurecidos, por lo que no se puede llevar ni se puede ver qué tipo de anillo es. Entre el barro, te parece entrever el brillo de metal precioso y quizás una gema.$B$BSi quieres ponértelo, tendrás que encontrar la manera de limpiarlo.", t = "Un anillo sucio"},
    [2947] = {ot = "Puedes quedarte el anillo o buscar a quien realizó los grabados de la parte interior.", st = "Al abrir la caja del Destellamatic 5200 verás lo que estabas esperando: ¡un anillo reluciente! Cuando lo lleves sentirás que te recorre una fuerza mágica.$B$BEn la parte inferior está grabado, pequeño pero legible, el sello de Forjaz. Junto a él hay tres iniciales. \"TdK\". Pueden ser las iniciales del dueño del anillo o las del artesano que lo forjó. Quédate el anillo... o devuélveselo a esta persona. Tú verás...", t = "La devolución del anillo"},
    [2948] = {ot = "Lleva tu anillo de oro luminoso, una barra de plata, una ágata musgosa y 30 monedas de plata a Talvash del Kissel a Forjaz.", st = "Oye, $n, ¡puedo hacerte un anillo mejor que el que llevas! Como decía, ese diseño es muy sencillo. Ahora soy mucho mejor, así que por 30 monedas de plata de nada mejoraré tu anillo. Bueno, en realidad, es algo más de 30...$B$BAhora mismo estoy sin material. ¡Si me traes una barra de plata y una ágata musgosa, las usaré para añadir detalle a tu anillo y darle otro aire!$B$BConfía en mí.", t = "Mejora gnómica"},
    [2949] = {ot = "Puedes quedarte el anillo o buscar a quien realizó los grabados de la parte interior.", st = "¡Al abrir la caja del Destellamatic 5200 ves un anillo reluciente! Al ponértelo, sientes que te recorre una fuerza mágica.$B$BEn la parte interior está grabado, pequeño pero legible, el sello de Orgrimmar. Junto al sello hay algo más, pero incluso después de limpiar el anillo, solo se lee: \"NOG...\"$B$BPueden ser las iniciales del dueño o las del artesano que forjó el anillo. Quédate con el anillo o busca a \"NOG\". Tú verás...", t = "La devolución del anillo"},
    [2950] = {ot = "Lleva tu anillo de oro luminoso, una barra de plata, una ágata musgosa y 30 monedas de plata a Nogg a Orgrimmar.", st = "No, no es que de pronto haya decidido que el anillo es mío. Normalmente no hago estas cosas, pero tu información sobre los Hierro Negro me ha sido muy útil. Mejoraré tu anillo de una forma que nunca se le habría ocurrido a su creador. Seguro que era un gnomo...$B$B¡Si me traes una barra de plata y una ágata musgosa, además de 30 monedas de plata, añadiré detalle a tu anillo y reforzaré su magia! ¿Te interesa la cosa?", t = "Nogg mejora el anillo"},
    [2951] = {t = "¡El Destellamatic 5200!"},
    [2952] = {t = "¡El Destellamatic 5200!"},
    [2962] = {ot = "Viaja hasta Gnomeregan y recupera los restos radiactivos de gran potencia. Pero ten cuidado, ya que es inestable y podría explotar en cualquier momento.$B$BOzzie también quiere que traigas la ampolla pesada de plomo una vez que hayas terminado el trabajo.|n", st = "Tu muestra no solo era insuficiente en cuanto a cantidad, además era impura.$B$BNecesitamos más material verdoso radiactivo. Es evidente que los troggs no han sido suficientemente irradiados. Tendrás que ir a Gnomeregan y traer restos radiactivos, directamente de la fuente. Estoy hablando de babosas, rondadores y horrores irradiados. Y ten cuidado: contener este tipo de restos es difícil. Es posible que tengas que hacer varios intentos hasta que hayas reunido una muestra adecuada.", t = "Necesitamos más material verdoso"},
    [2983] = {ot = "Busca a Kranal Fiss en Los Baldíos.", st = "Ha pasado algún tiempo desde tu última prueba, $n. Hasta el momento has sido paciente en tus estudios, pero llegó el momento de que adquieras mayores poderes... es hora de que aprendas el auténtico poder. El elemento del fuego será tuyo si estás $gdispuesto:dispuesta; a pagar el precio.$B$BBusca a Kranal Fiss en Los Baldíos. Vive en una pequeña casa al norte de El Cruce. Pero cuidado: si llegas hasta las devastadas tierras de los elfos de la noche, habrás ido demasiado lejos.", t = "La llamada del fuego"},
    [2984] = {ot = "Busca a Kranal Fiss en Los Baldíos.", st = "Ha pasado tiempo desde tu última prueba, $n. Hasta ahora has demostrado paciencia en tus estudios, pero ha llegado el momento de que aprendas algo más. Debes aprender de la destrucción... y el caos. De un elemento: el fuego. Podrás comprenderlo, si estás $gdispuesto:dispuesta; a pagar el precio.$B$BBusca a Kranal Fiss en Los Baldíos. Vive en una pequeña casa al norte de El Cruce. Pero cuidado: si llegas hasta las tierras de los elfos de la noche, habrás ido demasiado lejos.", t = "La llamada del fuego"},
    [2998] = {ot = "Habla con Duthorian Rall en Ventormenta.", st = "Saludos, $Ghermano:hermana;. Duthorian Rall, uno de nuestros paladines más influyentes, estuvo hablando de ti hace poco. Le oí decir que era hora de ponerte a la prueba... Y bueno, también dijo algo sobre lo bien que estás yendo hasta ahora y eso.$B$BSi yo fuera tú, iría a Ventormenta y hablaría con él. Seguramente estará en la Catedral de la Luz. Ahí es donde pasa la mayor parte de su tiempo.", t = "Escrito sobre divinidad"},
    [2999] = {ot = "Ve a Forjaz y habla con Tiza Forjabatalla.", st = "Hola, $n. Sé que estás $gocupado:ocupada; ayudando a las gentes de Dun Morogh, pero cuando tengas tiempo, deberías subir las escaleras y hablar con una persona que es muy respetada por aquí: Tiza Forjabatalla. Los paladines más jóvenes deben acudir a ella cuando llega el momento de que aprendan más sobre la Luz y sobre lo que se espera de ellos.", t = "Escrito sobre divinidad"},
    [3065] = {ot = "Lee la Tablilla simple y habla con Frang en el Valle de los Retos.", st = "Ah, mientras estabas fuera llegó un papiro para ti, $n.$B$BLéelo cuando tengas tiempo, si no me equivoco viene de parte del instructor de guerreros, Frang. Querrá tener unas palabras contigo cuando estés $glisto:lista;. Lo encontrarás a las puertas de El Cubil, al abrigo de la sombra.", t = "Tablilla simple"},
    [3082] = {ot = "Habla con Jen'shan en el Valle de los Retos.", st = "Ah, mientras estabas fuera llegó una tablilla para ti, $n.$B$BLéela cuando tengas tiempo, si no me equivoco viene de parte de la instructora de cazadores, Jen'shan. Querrá tener unas palabras contigo cuando estés $glisto:lista;.", t = "Tablilla con grabados"},
    [3083] = {ot = "Lee la Tablilla encriptada y habla con Rwag en el Valle de los Retos.", st = "Ah, mientras estaba fuera llegó una tablilla para ti, $n.$B$BLéela cuando tengas tiempo, si no me equivoco viene de parte del instructor de pícaros, Rwag. Querrá tener unas palabras contigo cuando estés $glisto:lista;.", t = "Tablilla encriptada"},
    [3084] = {ot = "Habla con Shikrik en el Valle de los Retos.", st = "Ah, mientras estaba fuera llegó una tablilla para ti, $n.$B$BLéela cuando tengas tiempo, si no me equivoco viene de parte del instructor de chamanes, Shikrik. Querrá tener unas palabras contigo cuando estés $glisto:lista;.", t = "La tablilla con runas grabadas"},
    [3085] = {ot = "Lee la tablilla sacralizada y habla con Ken'jai a las puertas de El Cubil en el Valle de los Retos.", st = "Ah, mientras estabas fuera llegó una tablilla para ti, $n.$B$BLéela cuando tengas tiempo, si no me equivoco viene de parte del instructor de sacerdotes, Ken'jai. Querrá tener unas palabras contigo cuando estés $glisto:lista;.", t = "Tablilla sacralizada"},
    [3086] = {ot = "Lee la tablilla glífica y habla con Mai'ah junto a la entrada a El Cubil, en el Valle de los Retos.", st = "Ah, mientras estabas fuera llegó una tablilla para ti, $n.$B$BLéela cuando tengas tiempo, si no me equivoco viene de parte de la instructora de magos, Mai'ah. Querrá tener unas palabras contigo cuando estés $glisto:lista;.", t = "Tablilla glífica"},
    [3087] = {ot = "Lee el papiro con grabados y habla con Jen'shan en el Valle de los Retos.", st = "Ah, mientras estabas fuera llegó un papiro para ti, $n.$B$BLéelo cuando tengas tiempo. Si no me equivoco, viene de parte de la instructora de cazadores, Jen'shan. Quiere hablar contigo cuando estés $glisto:lista;.", t = "Papiro con grabados"},
    [3088] = {ot = "Lee el papiro encriptado y habla con Rwag en el Valle de los Retos.", st = "Ah, mientras estabas fuera llegó un papiro para ti, $n.$B$BLéelo cuando tengas tiempo, si no me equivoco viene de parte del instructor de pícaros, Rwag. Querrá tener unas palabras contigo cuando estés $glisto:lista;.", t = "Papiro encriptado"},
    [3089] = {ot = "Lee el papiro con runas grabadas y habla con Shikrik en el Valle de los Retos.", st = "Ah, mientras estabas fuera llegó un pergamino para ti, $n.$B$BLéelo cuando tengas tiempo, si no me equivoco viene de parte del instructor de chamanes, Shikrik. Querrá tener unas palabras contigo cuando estés $glisto:lista;.", t = "El papiro con runas grabadas"},
    [3090] = {ot = "Lee el papiro corrupto y habla con Nartok en el Cubil del Valle de los Retos.", st = "Ah, mientras estabas fuera llegó un papiro para ti, $n.$B$BSiempre que puedo procuro evitar el trato con brujos, pero creo que deberías leerlo cuando tengas tiempo. Si no me equivoco viene de parte del instructor que te acaba de ser asignado, Nartok. Querrá tener unas palabras contigo cuando estés $glisto:lista;.", t = "Papiro corrupto"},
    [3091] = {ot = "Lee la nota simple y habla con Harutt Tronacuerno en el Campamento Narache.", st = "$n, hace un momento te vino a buscar una mensajera. Creo que venía de parte del instructor de guerreros Harutt. Si la nota es suya, será mejor que la leas pronto.|n", t = "La nota simple"},
    [3092] = {ot = "Lee la nota con grabados y habla con Lanka Tirolejano en la Mesa de la Nube Roja.", st = "$n, hace un momento te vino a buscar una mensajera. Creo que venía de parte del instructor de cazadores Lanka. Si la nota es suya, será mejor que la leas pronto.\n", t = "La nota con grabados"},
    [3093] = {ot = "Lee la nota con runas y habla con Meela Caminalba en el Campamento Narache.", st = "$n, hace un momento te vino a buscar una mensajera. Creo que venía de parte de la instructora de chamanes Meela. Si la nota es suya, será mejor que la leas pronto.\n", t = "La nota con runas grabadas"},
    [3094] = {ot = "Lee la nota verdeante y habla con Gart Correbruma en el Campamento Narache.", st = "$n, hace un momento te vino a buscar una mensajera. Creo que venía de parte del instructor de druidas Gart. Si la nota es suya, será mejor que la leas pronto.|n", t = "La nota verdeante"},
    [3095] = {ot = "Lee el pergamino simple, luego ve a Camposanto y habla con Dannal Stern.", st = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello del instructor de guerreros Dannal. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.", t = "Un pergamino simple"},
    [3096] = {ot = "Lee el pergamino encriptado, luego ve a Camposanto y habla con David Trias.", st = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello de David Trias, el instructor de pícaros. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.", t = "Un pergamino codificado"},
    [3097] = {ot = "Lee el pergamino sagrado, luego ve a la iglesia de Camposanto y habla con el clérigo oscuro Duesten.", st = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello del instructor de sacerdotes Duesten. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.", t = "Un pergamino sacralizado"},
    [3098] = {ot = "Lee el pergamino glífico, luego ve a la iglesia de Camposanto y habla con Isabella.", st = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello de la instructora de magos Isabella. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.", t = "Un pergamino glífico"},
    [3099] = {ot = "Lee el pergamino corrupto, luego ve a Camposanto y habla con Maximillion.", st = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello de Maximillion, el instructor de brujos. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.", t = "Un pergamino corrupto"},
    [3100] = {ot = "Lee la carta simple y habla con Llane Beshere en la Abadía de Villanorte.", st = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $n. Parece ser una carta sellada con la insignia de Llane, uno de nuestros instructores de guerreros locales. Deberías leerla antes de continuar con tus tareas en la abadía.", t = "Una carta simple"},
    [3101] = {ot = "Lee la carta consagrada y habla con el hermano Sammuel en la Abadía de Villanorte.", st = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $n. Parece ser una carta sellada con la insignia del hermano Sammuel, uno de nuestros instructores de paladines locales. Deberías leerla antes de continuar con tus tareas en la abadía.", t = "Una carta consagrada"},
    [3102] = {ot = "Lee la carta cifrada y habla con Jorik Kerridan en el establo que hay tras la Abadía de Villanorte.", st = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $n. Parece ser una carta sellada con la insignia de Jorik, uno de nuestros instructores locales. Deberías leerla antes de continuar con tus tareas en la abadía.", t = "Una carta cifrada"},
    [3103] = {ot = "Lee la carta sacralizada y habla con la sacerdotisa Anetta en la Abadía de Villanorte.", st = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $n. Parece ser una carta sellada con la insignia de la sacerdotisa Anetta, una de nuestras instructoras de sacerdotes locales. Deberías leerla antes de continuar con tus tareas en la abadía.", t = "Una carta sacralizada"},
    [3104] = {ot = "Lee la carta glífica y habla con Khelden Bremen en la Abadía de Villanorte.", st = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $n. Parece ser una carta sellada con la insignia de Khelden, uno de nuestros instructores de magos locales. Deberías leerla antes de continuar con tus tareas en la abadía.", t = "Una carta glífica"},
    [3105] = {ot = "Lee la carta impía y habla con Drusilla La Salle junto a la Abadía de Villanorte.", st = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $n. Parece ser una carta sellada con la insignia de Drusilla, una de nuestras instructoras locales. Deberías leerla antes de continuar con tus tareas en la abadía.", t = "Una carta manchada"},
    [3106] = {ot = "Lee la runa simple, luego ve al Valle de Crestanevada y habla con Thran Khorman.", st = "Mientras me estabas ayudando, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Thran, el instructor de guerreros. Échale un vistazo y, cuando puedas, ve a buscarlo a Yunquemar.", t = "Runa simple"},
    [3107] = {ot = "Lee la runa consagrada, luego ve al Valle de Crestanevada y habla con Bromos Grummner.", st = "Mientras me estabas ayudando, me confiaron esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Bromos, el instructor de paladines. Échale un vistazo y, cuando puedas, ve a buscarlo a Yunquemar.", t = "Runa consagrada"},
    [3108] = {ot = "Lee la runa con grabados y luego habla con Thorgas Grimson en Valle de Crestanevada.", st = "Mientras me estabas ayudando, me confiaron esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Thorgas, el instructor de cazadores. Échale un vistazo y, cuando puedas, ve a buscarlo a Yunquemar.", t = "Runa con grabados"},
    [3109] = {ot = "Lee la runa codificada, luego ve al Valle de Crestanevada y habla con Solm Hargrin.", st = "Mientras me estabas ayudando, me confiaron esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Solm, el instructor de pícaros. Échale un vistazo y, cuando puedas, ve a buscar a Solm a Yunquemar.", t = "Runa codificada"},
    [3110] = {ot = "Lee la runa sacralizada, luego ve a Yunquemar y habla con Silo Khalder.", st = "Mientras me estabas ayudando, me confiaron esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Branstock, el instructor de sacerdotes. Échale un vistazo y, cuando puedas, ve a buscarlo a Yunquemar.", t = "Runa sacralizada"},
    [3112] = {ot = "Lee el memorándum simple, luego ve al Valle de Crestanevada y habla con Thran Khorman.", st = "Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Thran, el instructor de guerreros. Échale un vistazo y, cuando puedas, ve a buscar a Thran a Yunquemar.", t = "Memorándum simple"},
    [3113] = {ot = "Lee el memorándum encriptado, luego ve al Valle de Crestanevada y habla con Solm Hargrin.", st = "Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Solm, el instructor de pícaros. Échale un vistazo y, cuando puedas, ve a buscar a Solm a Yunquemar.", t = "Memorándum encriptado"},
    [3114] = {ot = "Lee el memorándum glífico, luego ve a hablar con Marryk Nurribit, dentro de Yunquemar, sobre el Valle de Crestanevada.", st = "Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Marryk, el instructor de magos. Échale un vistazo y, cuando puedas, ve a buscar a Marryk a Yunquemar.", t = "Memorándum glífico"},
    [3115] = {ot = "Lee el memorándum corrupto y habla con Alamar Grimm en Yunquemar, sobre el Valle de Crestanevada.", st = "Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Alamar, el instructor de brujos. Échale un vistazo y, cuando puedas, ve a buscarlo a Yunquemar.$B$BY ten cuidado, $n, muchos no confían en los de tu clase por aquí.", t = "Memorándum corrupto"},
    [3116] = {ot = "Lee el sigilo simple y habla con Alyissia en Cañada Umbría.", st = "Un mensajero de nuestra instructora de guerreros, Alyissia, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.", t = "El sigilo simple"},
    [3117] = {ot = "Lee el sigilo con grabados y habla con Ayanna Semprerguida en la cima de Aldrassil en Cañada Umbría.", st = "Este siglo me lo entregó un mensajero de nuestra instructora de cazadores, Ayanna. Parece que quiere hablar contigo. Léelo y luego llévaselo.", t = "El sigilo con grabados"},
    [3118] = {ot = "Lee el sigilo cifrado y habla con Frahun Sombrusurro en Cañada Umbría.", st = "Un mensajero de nuestro instructor de pícaros, Frahun, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.", t = "El sigilo cifrado"},
    [3119] = {ot = "Lee el sigilo sacralizado y habla con Shanda en Aldrassil.", st = "Un mensajero de nuestra instructora de sacerdotes, Shanda, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.", t = "Sigilo sacralizado"},
    [3120] = {ot = "Lee el sigilo verdeante y habla con Mardant Fuerterroble, en el árbol Aldrassil de Cañada Umbría.", st = "Este sigilo me lo entregó un mensajero de nuestro instructor de druidas, Mardant. Parece que quiere hablar contigo. Léelo y luego llévaselo.", t = "El sigilo verdeante"},
    [3221] = {ot = "Habla con el boticario Renferrel en El Sepulcro.", st = "Mientras estabas ahí fuera ayudando a nuestros mortacechadores, el boticario Renferrel te envió un llamamiento. No me dio ningún detalle, pero quería hablar contigo sobre los corazones de lobo que le entregaste.", t = "Habla con Renferrel"},
    [3261] = {ot = "Habla con Jorn Vidente del Cielo en el Campamento Taurajo.", st = "Tu formación conmigo ha llegado a su fin, $n. Para seguir aprendiendo, debes ir al Campamento Taurajo, hacia el sur, y habla con Jorn Vidente del Cielo. Él seguirá con tu aprendizaje.", t = "Jorn Vidente del Cielo"},
    [3281] = {ot = "Llévale la plata robada a Gazrog en El Cruce.", st = "Puede que hayas matado a los raptores ¡pero aún hay que recuperar la plata que robaron! Me han informado que los raptores tienen un gran número de nidos al sur de Trinquete, llaman a ese lugar Tierras de los Raptores. Es probable que llevaran allí nuestra plata robada.$B$BVe a ese refugio de raptores y busca la plata robada. Cuando la encuentres, devuélvemela.", t = "Plata robada"},
    [3301] = {ot = "Habla con Mura Tótem de Runa en el Sepulcro.", st = "Mi compañera de clan, Mura Tótem de Runa, se dirigía al Bosque de Argénteos así que podría ayudar a nuestros aliados no-muertos. Este bosque está enfermo, se está muriendo, y Mura tenía la esperanza de devolverle la vida. Quizás la extraña vida que hemos encontrado aquí en Los Baldíos pueda ayudarla en su trabajo en el Bosque de Argénteos.$B$BToma uno de los caparazones que recolectaste y llévaselo a Mura en el Bosque de Argénteos. La encontrarás en El Sepulcro. Con un poco de suerte, el estudio del caparazón le dará una idea de lo que necesita para curar ese lugar agonizante.", t = "Mura Tótem de Runa"},
    [3361] = {ot = "Llévale la caja de Félix, el cofre de Félix y el cubo de tornillos de Félix a Félix Rayaullido en Yunquemar.", st = "Expulsamos a los troggs de Gnomeregan, ¡pero luego todo salió terriblemente mal! Ahora nuestro hogar está contaminado por la radiación, y los gnomos estamos dispersos por todo Dun Morogh.$B$BEn el apuro por huir de la radiación, perdí todas mis herramientas y pertenencias personales. Los trols se las llevaron. ¡Robaron mi cofre, mi caja y mi cubo de tornillos! Se los llevaron a sus campamentos al sudoeste de Yunquemar.$B$BYo no soy aventurero. ¿Podrías buscar mis cosas y recuperarlas?", t = "Las penurias de un refugiado"},
    [3364] = {ot = "Lleva la infusión de albaza hirviendo a Durnan Cortapieles a Yunquemar antes de que se enfríe, ¡tienes 5 minutos!", st = "¡Ay! Se supone que tenía que llevar esta deliciosa infusión de albaza a Durnan Cortapieles, de Yunquemar, pero antes tengo que entregar una a Grelin. ¡Se enfriará antes de que llegue a Yunquemar!$B$BTú pareces $grápido:rápida;. Seguro que tú lo consigues. Esta taza estará caliente solo unos cinco minutos más y Durnan no pidió infusión fría de albaza, así que, ¡en marcha! Yunquemar está al noreste. Es un emplazamiento excavado en la montaña.$B$BGracias, $n. ¡Y no olvides devolverme la taza!", t = "Entrega una infusión de albaza hirviendo"},
    [3365] = {ot = "Devuélvele la taza de Nori a Nori Rumborgullo.", st = "¡Qué a gusto me he quedado, oye! Nada calienta el alma en un frío día de invierno como una infusión calentita –no, ARDIENTE– de albaza.$B$BTen, $n. Llévale a Nori esta taza vacía de mi parte, ¿quieres?", t = "Devuelve la taza"},
    [3369] = {ot = "Lleva el Fragmento de Pesadilla a Hamuul Tótem de Runa en el Alto de los Ancestros.", st = "Este fragmento alberga grandes secretos, es la esencia pura del Sueño Esmeralda. Sin embargo, lo que veo en él no es un sueño; hay quien llamaría a esta especie de visión una auténtica pesadilla.$B$BNo quiero alarmarte, $n, pero creo que lo mejor será que lleves este fragmento a manos de un sabio druida tan pronto como puedas...$B$BNecesitas encontrar a Hamuul Tótem de Runa del Alto de los Ancestros. Dirígete a Cima del Trueno. No puedo decirte nada más.", t = "En las pesadillas"},
    [3370] = {ot = "Lleva el Fragmento de Pesadilla a Mathrengyl Garroso de Darnassus.", st = "Este fragmento alberga grandes secretos, es la esencia pura del Sueño Esmeralda. Sin embargo, lo que veo en él no es un sueño; hay quien llamaría a esta especie de visión una auténtica pesadilla.$B$BNo quiero alarmarte, $n, pero creo que lo mejor será que lleves este fragmento a manos de un sabio druida tan pronto como puedas...$B$BNecesitas encontrar a Mathrengyl Garroso del Círculo Cenarion. Dirígete a Darnassus. No puedo decirte nada más.", t = "En las pesadillas"},
    [3376] = {ot = "Lleva la cabeza del Jefe Cornapunta Mantospina a la Valiente Pluma de Viento en Mesa de la Nube Roja.", st = "He oído hablar de ti, $n. Quizás tú puedas ayudarnos donde otros han fallado.$B$BLos tauren hemos hecho un hogar de esta tierra, pero a un precio alto. Los jabaespines Erizapúas del Barranco Cortazarza, liderados por el Jefe Cornapunta Mantospina, nos acosan continuamente. ¡Quiero la cabeza del jefe! ¡Tráemela!$B$BEstará en el barranco que hay al este de su aldea.", t = "La cabeza de Cornapunta"},
    [3519] = {ot = "Habla con Dirania Brillargente en Cañada Umbría.", st = "Uy... Me ha picado una araña llamada Gythyiss la Vil mientras exploraba la cueva de las arañas cerca de aquí. Seguro que me ha envenenado así que tienes que ayudarme.$B$BPor favor, habla con Dirania Brillargente. Ella podrá ayudarme.$B$BDate prisa... me estoy mareando...", t = "Un amigo en apuros"},
    [3521] = {ot = "Recoge 7 champiñones jacintos, 4 lirios alunados y 1 icor tejemadera para Dirania Brillargente en Cañada Umbría.", st = "Tal vez podamos ayudar a Iverron; conozco un antídoto contra ese veneno. Pero necesito algunos ingredientes para poder prepararlo.$B$BNecesitaré champiñones jacintos. Crecen bajo los árboles, o también puedes quitárselos a los grell al sur de aquí; parece que les gustan mucho. También necesito lirios alunados, que solo crecen en estanques.$B$BEl último ingrediente es el más peligroso: icor tejemadera de las arañas que envenenaron a Iverron.", t = "El antídoto de Iverron"},
    [3522] = {ot = "Llévale el antídoto de Iverron a Iverron antes de que se acabe el tiempo. Lo encontrarás junto a la cueva situada al norte.", st = "El antídoto está listo, $n. Por favor, encárgate de que Iverron se lo tome.$B$BHay algo más que debes saber; el antídoto solamente será efectivo durante los próximos 5 minutos. Debes llevárselo a tiempo.$B$BEspero que lo logres, $n.", t = "El antídoto de Iverron"},
    [3524] = {ot = "Recoge huesos de la criatura marina varada que está al sur de Auberdine y llévaselos a Gwennyth Bly'Leggonde a Auberdine.", st = "Se dice que hay unas majestuosas criaturas que van a las playas de Costa Oscura a morir encalladas. Últimamente, estas criaturas han empezado a llegar cada vez en mayor número a la costa. Yo he venido aquí a petición del Templo de la Luna para investigar el suceso, pero la gran cantidad de múrlocs que he encontrado en el agua dificulta mucho mis estudios.$B$BUna de esas gigantes criaturas llegó a la costa al sur de Auberdine para acabar rodeada de rabiosos múrlocs Bruma Gris. ¿Podrías ir a traerme algunos huesos de la criatura para que los estudie?", t = "Varado"},
    [3741] = {ot = "Encuentra el collar de Hilary y llévaselo a Villa del Lago.", st = "Mi amiga Hilary ha perdido su collar. Hemos estado pescando todo el día justo aquí, pero ya hemos mirado. Tiene que haberse caído en el lago. Nuestros padres no nos dejan nadar porque dicen que hay cosas malas en el lago. Pero seguro que tú no tienes miedo de las cosas malas.$B$B¿Puedes buscar su collar, por favor?", t = "El collar de Hilary"},
    [3765] = {ot = "Ve a ver a Gershala Susurro Nocturno en Auberdine.", st = "Ventormenta... un centro de mucho movimiento.$B$BVengo desde muy lejos buscando ayuda. A menudo se dice que hay valientes aventureros caminando por las calles de esta ciudad.$B$BMi hermano, Gershala, necesita ayuda en Costa Oscura. Vive en la ciudad costera de Auberdine.$B$BEl viaje es largo y épico. Por esta razón, necesito la ayuda de $gun:una; $c con experiencia como tú.", t = "Lejana corrupción"},
    [3901] = {ot = "Mata a 12 esqueletos armadóseos, y vuelve con el sacerdote de las sombras Sarvis en Camposanto cuando termines.", st = "$n, has demostrado a los Renegados que tienes potencial... en circunstancias normales. Ahora veamos qué tal funcionas bajo presión.$B$BLos esqueletos armadóseo, más de los esbirros descerebrados del Rey Exánime, son enemigos más rudos que los zombis que has enfrentado hasta ahora. Ya sabes qué hacer: reduce sus filas y demuestra tu valía para los Renegados. No te demores. Ven a verme cuando termines.", t = "Sacudir esqueletos"},
    [3902] = {ot = "Busca 6 piezas de mercancías extraviadas por Camposanto y los alrededores y llévaselas al Guardia de la Muerte Saltain.", st = "¡Eh, tú! Si buscas algo útil que hacer, ¡abre las orejas!$B$BNecesitamos reclutas fresquitos que vayan a Camposanto y busquen cualquier tipo de equipo que pueda sernos útil. Probablemente, estará en pilas de cajas. Dentro de poco se alzarán nuevos reclutas y, si no queremos que vayan por ahí desnudos, ¡más nos vale conseguirles algo que ponerse!$B$B¿Y bien? ¡Muévete, miserable saco de huesos! No habrá recompensa para los vagos.", t = "Hurgar en Camposanto"},
    [3903] = {ot = "Habla con Milly Osworth.", st = "$n, has demostrado que eres $Gun:una; $c de confianza y que no temes al trabajo duro.$b$bMi amiga Milly Osworth está en apuros. Tiene la carreta al otro lado de la abadía, cerca del establo. Seguro que le va bien que le eches una mano.", t = "Milly Osworth"},
    [3904] = {ot = "Lleva 8 cajas de cosecha a Milly Osworth a la Abadía de Villanorte.", st = "¡Una pandilla de salteadores, los Defias, se adentraron en los Viñedos de Villanorte mientras yo cosechaba! Informé a los guardias de Villanorte y me aseguraron que se encargarían del asunto, pero... ¡temo por mis cultivos de uvas! Si los Defias no se los roban, puede que los guardias los arrasen cuando persigan a los criminales.$B$B¡Por favor, tienes que ayudarme! Reuní la mayor parte de mis uvas en cubos, pero los dejé en los viñedos del sudeste.$B$B¡Tráeme esos cajones! ¡Salva mi cosecha!", t = "La cosecha de Milly"},
    [3905] = {ot = "Lleva el Informe de la vendimia al hermano Neals a la Abadía de Villanorte.", st = "Ahora que has salvado mis uvas, llévale el Informe de la vendimia al hermano Neals. Se encarga del almacén de abastos de Villanorte; se alegrará de saber que la vendimia ha sido buena.$b$bEstá en el campanario de la abadía; le gusta sentarse allí a probar el vino.", t = "Informe de la vendimia"},
    [3921] = {ot = "Llévale el churumbele roto a Wenikee Tuercasmil.", st = "Puede que haya roto ese churumbele. Eso no es nada bueno, porque ya les dije a unos colegas de Minahonda al respecto y están muy intrigados. ¡Tenemos que encontrar la forma de solucionarlo!$B$BLleva el churumbele roto a Wenikee Tuercasmil, al sur de la Empaladiza de Mor'shan, el puesto de avanzada de la Horda entre Los Baldíos y Vallefresno. Es muy astuta y curiosa. Si le muestra el churumbele seguro querrá arreglarlo de inmediato.", t = "Wenikee Tuercasmil"},
    [3922] = {ot = "Lleva 15 engranajes a Wenikee Tuercasmil en Los Baldíos.", st = "Quiero reparar este churumbele, pero necesitaré suministros para eso. No me quedan más engranajes del calibre diecisiete y medio y necesitaré muchos de esos para este trabajo.$B$BEl lugar más cercano para conseguirlos es el Fangal del este. Ventura y Cía suele tener varios en sus cubos de herramientas. Ve al Fangal, busca en los cubos de herramientas que encuentres, y ven a verme cuando hayas reunido suficientes engranajes.", t = "Engranajes"},
    [3923] = {ot = "Llévale el churumbele roto y maltrecho a Rilli Gapegajoso en Orgrimmar.", st = "Bueno, eso no funcionó. Puse unos calibres adicionales en el churumbele para medir su integridad estructural y las lecturas dan mínimos históricos. Podría añadir algún dial más y quizás una palanca o dos para intentar repararlo pero... creo que solo empeoraría las cosas.$B$BDeberías llevarle el churumbele a Rilli Gapegajoso. Antes trabajaba para Ventura y Cía., si alguien sabe cómo arreglarlo, ese es Rilli.$B$BLo encontrarás en el Rincón de la Maquinaria de Nogg en Orgrimmar, en el Valle del Honor.", t = "Rilli Gapegajoso"},
    [3924] = {ot = "Llévale el manual del churumbele a Rilli Gapegajoso en Orgrimmar.", st = "Creo que puedo arreglar el churumbele, pero primero voy a necesitar leer el manual. Cuando estaba en la Compañía Ventura y Cía. tenía un rival, el jefe Encobre, que atesoraba los secretos del churumbele, y comentaba algunos detalles solo a quienes tenía plena confianza. Yo no era de los de su confianza...$B$BEl jefe Encobre solía andar por la Mina Pedrusco, en la parte noreste de Los Baldíos. Consigue el manual. Si ves que faltan páginas, seguro que se las ha dado a otros, así que deberás conseguirlas como puedas.", t = "Manual del churumbele"},
    [4021] = {t = "¡Contraataca!"},
    [4161] = {ot = "Consigue 7 patas de araña pequeña para Zarrin en Dolanaar.", st = "Hace mucho tiempo, los elfos de la noche se conocían como los kaldorei, un nombre que significa \"hijos de las estrellas\". Aprender del pasado es un paso muy importante en tu camino como $c, $n. Por ello, debes escuchar atentamente lo que tengo que decirte.$B$BLos kaldorei siempre se han sentido muy orgullosos de su armoniosa relación con la naturaleza. Esto significa que solamente cogemos de la naturaleza lo que necesitamos y lo que podemos devolverle. Este equilibrio nos ha beneficiado mucho, $n.$B$BVe y recoge 7 patas de araña pequeña, ni una más ni una menos, y regresa aquí con ellas.", t = "La receta de los kaldorei"},
    [4402] = {ot = "Lleva 10 manzanas de cactus a Galgar. Recuerdas que mencionó que podías encontrarlas cerca de los cactus.", st = "Hace mucho calor en el Valle de los Retos.$B$B<Galgar se seca la frente.>$B$BSi al menos tuviera algunas manzanas de cactus, ¡podría hacer mi famosa sorpresa de manzana de cactus! Nada es tan refrescante como un bocado de ese manjar.$B$BTe diré algo, $n: si me traes 10 manzanas de cactus te prepararé unas porciones de sorpresa de manzana de cactus para que las lleves a tus aventuras. Si te interesa, encontrarás manzanas de cactus junto a las plantas de cactus que crecen en los alrededores.", t = "Sorpresa de manzanas de cactus de Galgar"},
    [4495] = {ot = "Encuentra a Iverron cerca de la cueva que hay al norte.", st = "Tengo un amigo llamado Iverron que suele venir a verme a la misma hora cada día. Pero hoy no ha venido.$B$BReconozco que su ausencia me inquieta, $n. Pasa mucho tiempo en la cueva que hay al norte, y ya sabes lo peligroso que es, con todas esas arañas por allí.$B$BSi vas hacia allí, ¿te importa buscar a mi amigo?", t = "Un buen amigo"},
    [4542] = {ot = "Entrégale el mensaje urgente al vigiarrisco Cuerno Largo en el Poblado Viento Libre.", st = "Valiente $gviajero:viajera;, los centauros atacan cada vez con más frecuencia en la zona. ¡El Poblado Viento Libre tiene que saberlo inmediatamente! Busca al vigiarrisco Cuerno Largo en el Poblado Viento Libre al sudeste y entrégale este mensaje urgente.$b$bTen cuidado de no cruzarte con el Clan Tótem Siniestro... últimamente tienen una actitud muy extraña con nosotros.|n|c|n", t = "Mensaje para el Poblado Viento Libre"},
    [4581] = {ot = "Llévale la nota de Shindrell a Kayneth Ventoleve en Canción del Bosque.", st = "El druida Kayneth Ventoleve me ha enviado un mensaje. Le gustaría obtener un informe de los acontecimientos en nuestras costas y en los bosques que rodean Astranaar. Teme que haya corrupción recorriendo Vallefresno... y puede que tenga razón.$B$BToma, llévale mi informe. Lo encontrarás en el altar de la Canción del Bosque, en el Bosque Arrullanoche hacia el este.", t = "Kayneth Ventoleve"},
    [4641] = {ot = "Habla con Gornek. Recuerda que Kaltunk marcó en tu mapa su ubicación y que te mencionó que Gornek reside en El Cubil, un edificio que está al oeste.|n|n", st = "Por fin ha llegado el momento, $n... el momento de que combatas en nombre de la Horda. Conquistarás por la gloria de nuestro Jefe de Guerra.$B$BSí...$B$B<Kaltunk te examina.>$B$BLo harás bien.$B$BSupongo que estarás deseando encontrar un dragón o un demonio enorme para estrangularlo con las manos, pero quizás sería más inteligente empezar por algo menos... peligroso.$B$B<Kaltunk se ríe.>$B$BBusca a Gornek. Él podrá asignarte una tarea adecuada para ti, joven $c. Lo encontrarás en El Cubil, al oeste.|n", t = "Tu lugar en el mundo"},
    [4681] = {ot = "Recoge restos de la tortuga marina esquelética de las aguas del oeste de Auberdine y vuelve a Auberdine a hablar con Gwennyth Bly'Leggonde.", st = "La encalladura de esa criatura no es un incidente aislado en Costa Oscura. Hay muchas otras a lo largo de la costa, e incluso en el agua. Quisiera que fueras a estudiar otro caso del que hemos sido informados. Lo encontrarás hacia el oeste de Auberdine, cerca de un navío naufragado. Vuelve a mí con cualquier cosa que encuentres que nos ayude en nuestra investigación.$B$BPuede que a lo largo del viaje encuentres otras criaturas. Te lo ruego, ¡tráenos cualquier cosa que descubras!", t = "Varado"},
    [4722] = {ot = "Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine.", st = "Encuentras el cadáver de una tortuga marina que fue a encallarse a Costa Oscura hace algún tiempo. Los múrlocs se han instalado a su alrededor y ya han hurgado entre los restos de la criatura. Aun así, parece que quedan algunas muestras de los restos que podrían resultar útiles a Gwennyth Bly'Leggonde de Auberdine.", t = "Tortuga marina varada"},
    [4723] = {ot = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.", st = "En la costa de Cabo de la Niebla yacen los restos de un trillador gigante... uno mucho mayor de lo que podría esperar encontrar en Costa Oscura... Es un misterio cómo llegó esta criatura hasta aquí. Los múrlocs que ahora se alimentan de su cadáver parecen demasiado débiles para derribar a una criatura semejante, incluso en gran número.$B$BNo queda mucho de la criatura, pero sí lo suficiente para recoger una muestra y llevársela a Gwennyth Bly'Leggonde de Auberdine para que la estudie.", t = "Criatura marina varada"},
    [4725] = {ot = "Lleva la caja con símbolos extraños a Gwennyth Bly'Leggonde a Auberdine.", st = "Hay muchos restos de tortugas marinas a lo largo de la costa. Esta en concreto tiene una especie de carruaje abandonado atado a la concha de la tortuga. Quizás esta criatura no vino a morir a la costa como parece que han hecho las demás, sino que fue traída por algún ser. Los múrlocs Bruma Gris han convertido los restos de esta criatura en su hogar y se alimentan de su cuerpo.$B$BEn el carruaje encuentras una caja con símbolos extraños. Quizás Gwennyth Bly'Leggonde de Auberdine sepa interpretarlos.", t = "Tortuga marina varada"},
    [4727] = {ot = "Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine.", st = "En la arena de las playas norteñas de Costa Oscura yacen los restos de un esqueleto de tortuga marina. Es posible que los múrlocs Bruma Gris no hayan encontrado los restos, o bien, que lo hayan hecho y se mantengan alejados de ellos por algún motivo que desconocemos. En cualquier caso, quedan restos suficientes para llevar una muestra a Gwennyth Bly'Leggonde a Auberdine, para que la estudie el Templo de la Luna.", t = "Tortuga marina varada"},
    [4728] = {ot = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.", st = "El cadáver, que parece ser de una especie de mamífero marino, yace medio destripado en la playa. Alrededor de esta enorme criatura encallada hay una carretilla y algunas herramientas, como si alguien hubiera intentado examinar los restos. Aunque los múrlocs ya han saqueado los restos, queda suficiente para reunir una muestra adecuada para Gwennyth Bly'Leggonde de Auberdine.", t = "Criatura marina varada"},
    [4730] = {ot = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.", st = "El cuerpo medio devorado de lo que podría ser un gigante mamífero marino yace en la playa. Una banda de múrlocs, más fuertes que los que encontraste cerca de Auberdine, se ha instalado alrededor de la criatura. Quedan suficientes restos del esqueleto de la criatura para llevar una muestra de sus huesos a Gwennyth Bly'Leggonde a Auberdine.", t = "Criatura marina varada"},
    [4731] = {ot = "Lleva la caja con símbolos extraños a Gwennyth Bly'Leggonde a Auberdine.", st = "Hay otro grupo de restos de una tortuga marina encallada en la costa. Estos restos tienen una especie de carruaje abandonado atado a la concha de la tortuga. Quizás esta criatura no vino a morir a la costa como parece que han hecho las demás, sino que fue traída por algún ser. Unos poderosos múrlocs Bruma Gris han hecho de los restos de esta criatura su hogar.$B$BEn el carruaje encuentras una caja con símbolos extraños. Quizás Gwennyth Bly'Leggonde de Auberdine sepa interpretarlos.", t = "Tortuga marina varada"},
    [4732] = {ot = "Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine.", st = "Encuentras el cadáver de una tortuga marina que fue a encallarse a la Costa Oscura hace algún tiempo. Los múrlocs Bruma Gris que han acampado alrededor de la criatura han limpiado prácticamente todos los restos. Aun así, parece que quedan algunas muestras que podrían resultar útiles a Gwennyth Bly'Leggonde de Auberdine.", t = "Tortuga marina varada"},
    [4733] = {ot = "Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine.", st = "Los restos de lo que parece ser un trillador gigante han aparecido encallados en una ensenada rocosa de la Orilla Crepuscular. El trillador es varias veces más grande que los trilladores que suelen verse en esta zona. Viniera de donde viniera, esta criatura no parece ser de Costa Oscura. Aunque la criatura ha sido rapiñada, quedan suficientes restos para reunir una muestra adecuada para Gwennyth Bly'Leggonde de Auberdine.", t = "Criatura marina varada"},
    [4740] = {ot = "Encuentra y mata al múrloc conocido como Viscoso. Se cree que la criatura está defendiendo el emplazamiento múrloc al sur de Auberdine, cerca del agua. $B$BInforma de la muerte de Viscoso a la centinela Glynda Nal'Shea, en Auberdine.", st = "¡Atención!$B$BSe ofrece una recompensa por la cabeza del múrloc \"Viscoso\". Esta inmunda bestia es responsable de la muerte de al menos un centinela y sospechosa de haber provocado el hundimiento de al menos dos navíos de carga en las aguas de Costa Oscura.$B$BViscoso fue visto por última vez en un campamento múrloc al sur de Auberdine. Se cree que está protegiendo el emplazamiento. Quien desee reclamar la recompensa, debe acudir a la centinela Glynda Nal'Shea, en Auberdine.$B$BEl Concejo de Auberdine.", t = "SE BUSCA: ¡Viscoso!"},
    [4761] = {ot = "Ve a Auberdine y habla con Thundris Tejevientos.", st = "Thundris Tejevientos debería ser informado de los resultados de tu exploración del campamento fúrbolg. Desempeña humildemente el cargo de anciano de Auberdine, ocupándose de los asuntos del día a día de la aldea con sabiduría y justicia. Por favor, comparte con él tus descubrimientos sobre la situación fúrbolg.$B$BCreo que él tiene sus propias ideas sobre la razón de su corrupción. Quizás puedas colaborar con él para idear un plan que devuelva el equilibrio a la naturaleza.", t = "Thundris Tejevientos"},
    [4762] = {ot = "Viaja al norte de Auberdine hasta la primera cascada del Río Fonroca y recoge una muestra de agua. $B$BVuelve a Auberdine a buscar a Thundris Tejevientos con la muestra del Río Fonroca.", st = "El Río Fonroca empieza a bajar enrarecido y corrupto. Desemboca en Cabo de la Niebla y temo que su influencia no tardará en afectar a Auberdine. Sospecho que los fúrbolgs que hay río arriba son la causa de la corrupción, pero también creo que no son la raíz del problema.$B$BCoge este tubo de muestras y ve hacia el norte, a la desembocadura del río. Luego ve tierra adentro hasta la primera cascada que encuentres y recoge una muestra de agua. Verás un puente sobre tu cabeza. Cuando tengas la muestra, vuelve a Auberdine y ven a verme.", t = "El Río Fonroca"},
    [4763] = {ot = "Llena el cuenco purificador vacío en la Poza de la Luna de Auberdine. $B$BRecoge una muestra de fruta, nueces y grano del campamento del norte de los fúrbolgs Bosque Negro. $B$BMezcla todo en el cuenco, llévalo al campamento norte y colócalo cerca de la hoguera más cercana al Río Fonroca; así convocarás al sátiro corruptor. $B$BCoge el dije de corrupción y llévaselo a Thundris Tejevientos a Auberdine.", st = "Hemos descubierto que la fuente de la corrupción de los fúrbolgs es el sátiro. Los domina por medio de dijes con los que canaliza su magia. Si queremos salvar a los fúrbolgs, debemos atrapar al sátiro corruptor y hacernos con su dije.$B$BLlena este cuenco en la Poza de la Luna y coge muestras de comida del campamento norte de los fúrbolgs. Mezcla ambas cosas y colócalas en la hoguera, cerca del río. Cualquier fúrbolg que coma de esa mezcla quedará purificado durante el tiempo que necesitas para hacer salir al sátiro corruptor... ¡y matarlo!", t = "La corrupción de los Bosque Negro"},
    [4767] = {ot = "Consigue 10 huevos de dracoleón de Nido Alto para Elu en el Poblado Viento Libre.", st = "Me ha sido encomendada la tarea de reclutar más dracoleones para los jinetes del viento. Cada vez son más y yo espero algún día convertirme en un jinete del viento como ellos. Sin embargo, la demanda de dracoleones es tan elevada que no somos capaces de instruir a todos los necesarios. Quizás tú puedas ayudarme, $n.$B$BNecesito que vayas a Nido Alto y que consigas unos cuantos huevos de dracoleón. Desde aquí, dirígete hacia el noroeste siguiendo las paredes del cañón hasta llegar a una rampa que te conducirá a Nido Alto. Ten cuidado pues los dracoleones son muy protectores con sus huevos y no les gustará nada la presencia de $gun intruso:una intrusa;.", t = "Jinete del viento"},
    [4770] = {ot = "Saca a Pao'ka Monte Presto de Nido Alto y después habla con Motega Pirocabello en Campamento del Tramo Blanco.", st = "¡Por favor ayúdame, $c! Llevo tiempo ocultándome en Nido Alto y hace días que no veo una cara amiga. Vine aquí para estudiar a los dracoleones pero creo que me acerqué demasiado. Me echaron de uno de los nidos y entonces me perdí.$B$B¡Necesito volver a Campamento del Tramo Blanco! Motega no sabe que estoy aquí y se pondría furioso si se enterara de que me aventuré en Nido Alto yo solo.$B$BEl Campamento del Tramo Blanco está justo al este de aquí... ¡Por favor, llévame hasta allí!", t = "De vuelta a casa"},
    [4811] = {ot = "Viaja al este de Auberdine y busca un gran cristal rojo en la zona montañosa que hay al este de Costa Oscura. Vuelve a Auberdine e informa de lo que has encontrado a la centinela Glynda Nal'Shea.", st = "Hay lechúcicos lunares hostiles dirigiéndose hacia el este, cada vez en mayor número. Antes se consideraban criaturas amables, casi místicas. Y aunque hay quien sigue sintiendo veneración por ellos, la seguridad de Auberdine me fuerza a tener una visión más realista.$B$BSegún mis informes, los lechúcicos lunares están siendo conducidos hacia un gran cristal rojo que se encuentra en las montañas del sur de Costa Oscura. Nadie sabe qué es ese cristal. Ni siquiera si existe realmente. Quiero que lo busques y vengas a informarme de lo que encuentres.", t = "El cristal rojo"},
    [4812] = {ot = "Llena el tubo de agua vacío en la Poza de la Luna de Auberdine y luego examina el cristal rojo a lo largo de la pared montañosa oriental de Costa Oscura.", st = "Utiliza este vial vacío para recoger algo de agua de la Poza de la Luna de Auberdine. Su potente magia debería ayudarnos a averiguar cuál es la composición del cristal. Para hacerlo, vierte el líquido sobre el cristal. Él debería hacer el resto.$B$BNo espero que encuentres ningún peligro, pero quiero que seas prudente por si acaso. Frondavil está al este de aquí. Si ese cristal está vinculado a ese lugar, como yo sospecho, podría resultar muy peligroso.", t = "Agua en cascada"},
    [4813] = {ot = "Vuelve a Auberdine e informa de lo que has averiguado a la centinela Glynda Nal'Shea.", st = "El agua de la Poza de la Luna ha revelado que en el interior del cristal hay unos pequeños trozos de hueso y media mandíbula. El hueso maxilar parece ser de un humanoide, pero no hay forma de confirmarlo sin romper el cristal, tarea que incluso la magia más potente encontraría virtualmente imposible.$B$BUna vez completada esta tarea, solo queda ir a Auberdine a informar a la centinela Glynda Nal'Shea.", t = "Los trozos del interior"},
    [4821] = {ot = "Devuélvele el huevo extraño a Hagar Pezuña del Rayo, que está en el Poblado Viento Libre.", st = "Ha surgido un rumor acerca de un extraño huevo aquí en Las Mil Agujas. Aquellos que afirman haberlo visto ni siquiera han podido acercarse a él para examinarlo al detalle pues está protegido por serpientes que lo defienden como si fuera uno de sus propios huevos.$B$BQuiero que encuentres ese huevo extraño y me lo traigas para poder examinarlo. Parece ser que el huevo está situado en una guarida de serpientes, pero hay varias en la base de los riscos sur y noreste del Poblado Viento Libre.", t = "Un huevo extraño"},
    [4841] = {ot = "Mata a 12 exploradores Galak, 10 retadores Galak y 6 cazavientos Galak, y después ve a ver de nuevo al vigiarrisco Cuerno Largo al Poblado Viento Libre.", st = "$n, te ruego que mates a estos centauros. ¡Que sientan la cólera de nuestra venganza! Ataca el campamento de los centauros situado al norte del Poblado Viento Libre. ¡Que la cólera guíe tu mano!|n", t = "Apaciguar al centauro"},
    [4865] = {ot = "Infórmale de tus hallazgos a Motega Pirocabello.", st = "Si no lo hubiera visto con mis propios ojos jamás habría creído que fuera cierto. ¡Venganza ha venido a Las Mil Agujas!$B$B<Hagar se seca la frente.>$B$B¡$n, debes actuar con rapidez! Márchate y busca a Motega Pirocabello. Lo encontrarás en el Campamento del Tramo Blanco, al noroeste del Poblado Viento Libre. ¡Él sabrá lo que hay que hacer!", t = "Venganza"},
    [4881] = {ot = "Avisa a Kanati Nube Gris, en el Campamento del Tramo Blanco, acerca de la conspiración para acabar con su vida.", st = "El tauren Kanati Nube Gris ha tenido la osadía de establecer un campamento de caza en Las Mil Agujas. Debemos darle muerte a él y a los que lo apoyan, y acabar así con el campamento de caza. Nos reuniremos en el pequeño campamento situado al suroeste de El Gran Elevador.|n", t = "Complot de asesinato"},
    [4904] = {ot = "Saca a Lakota Son del Viento de Cumbre de la Nube Negra y después habla con Thalia Ocultaámbar, que está en el Poblado Viento Libre.", st = "Arnak cree que me casaré con él... pero después de rechazar su proposición, él volvió aquella noche y me raptó. Mi hermano intentó impedírselo pero Arnak era demasiado fuerte. Él... asesinó a mi hermano y después me trajo hasta aquí. Mi pobre hermano...$B$B$n, ¿podrías sacarme de Cumbre de la Nube Negra? Por favor... ¡Necesito ver a Thalia! Debe de estar muy preocupada por mí.", t = "Al fin libre"},
    [4921] = {ot = "Encuentra a la esposa de Mankrik y llévala a El Cruce.", st = "Luchábamos juntos en un pequeño campamento tauren cuando nos separaron, ella solita le estaba plantando cara a tres Erizapúas. Pero la diferencia de efectivos empezó a desbordarnos. Estaba alejando a unos cuantos cuando la vi superada por los refuerzos. Ciego de ira, volví para enfrentarme a mis enemigos pero no tardaron en dominarme fácilmente con sus ingentes efectivos.$B$BCuando me desperté, un druida tauren estaba curando mis heridas, se había topado conmigo en el Camino del Oro donde caí.$B$BTe lo ruego, $c, encuentra alguna pista sobre mi esposa.", t = "Perdida en la batalla"},
    [4966] = {ot = "Defiende a Kanati Nube Gris contra el ataque de los centauros.", st = "Creo que los centauros son más numerosos de lo que yo pensaba. Te pido que luches conmigo contra estos viles asesinos, $n.", t = "Defensa de Kanati Nube Gris"},
    [5041] = {ot = "Encuentra los cajones de suministros en El Cruce y devuélvelos a Thork en los Baldíos.", st = "La caravana que fue atacada contenía suministros que necesitamos con urgencia.$B$BComo has sido tan valiente en enfrentarte a la tribu Crines de Acero, te pediré que lo hagas de nuevo. Pero esta vez quisiera que prestes atención por si ves algunos de nuestros suministros perdidos. Seguramente los encuentres en sus campamentos. Los jabaespines estarán engordando gracias a sus actos deshonorables.$B$BEl pueblo de El Cruce estará en deuda contigo.", t = "Suministros para El Cruce"},
    [5052] = {ot = "Llévale una esquirla de sangre a Quebrantadientes en el Campamento Taurajo en Los Baldíos.$B$BReúne más esquirlas de sangre si quieres que te bendiga con el poder de Agamaggan.", st = "Además de las espinas, la sangre afectó a <gruñe> otros aspectos de la tierra: piedras teñidas de rojo sangre mezcladas con otros minerales. Los Erizapúas excavan en busca de estas esquirlas y las llevan como tótems <gruñe> para que les den fuerza en la batalla y para su magia <gruñe.>$B$BConozco los secretos de esa magia.$B$BLlévale a Quebrantadientes una de estas esquirlas de sangre para demostrarle que entiendes de qué va el asunto. Llévale a Quebrantadientes muchas esquirlas y te bendecirá con la magia de los jabaespines, es decir, ¡la magia de Agamaggan! <gruñe.>", t = "Esquirlas de sangre de Agamaggan"},
    [5061] = {ot = "Vuelve a Darnassus y enséñale el colgante del león marino a Mathrengyl Garroso.", st = "Has completado tu formación para la adopción de una forma acuática. Ve a ver a tu instructor, Mathrengyl Garroso, a Darnassus. Enséñale el colgante y demuéstrale que puedes aprender lo que tenga que enseñarte. Él completará tu formación para que puedas fundirte con el agua.$B$BBuena suerte, joven druida. Volveremos a vernos.", t = "Forma acuática"},
    [5062] = {ot = "Recoge 10 pitas incendiarias y después pide consejo a Magatha Tótem Siniestro en el Alto de los Ancestros de Cima del Trueno.", st = "Arikara es una criatura mortífera contra la que hay que actuar con rapidez. Para poder atraparla tendrás que encender el fuego sagrado de la vida, que hará que Arikara aparezca.$B$BVe y recoge pitas incendiarias, una planta poco común. Cuando tengas suficientes pitas, pide consejo a Magatha Tótem Siniestro en el Alto de los Ancestros de Cima del Trueno. Ella es una poderosa chamán que puede encantar la planta y obtener así unos polvos con los que encender el fuego.$B$BViaja en dirección noreste hasta Poza Hirviendo y recoge pitas incendiarias.", t = "El fuego Sagrado"},
    [5064] = {ot = "Localiza y reúne las 3 notas secretas que hay en Cumbre de la Nube Negra.", st = "$n, nos has servido con diligencia en el pasado por lo que ahora te confío una importante misión. El clan Tótem Siniestro está tramando algo. Sabemos que tres agentes de origen desconocido se han estado reuniendo con los Tótem Siniestro durante las últimas semanas. Descubrimos que hay varios cofres en Cumbre de la Nube Negra que contienen mensajes reveladores.$b$b$n, si tienes éxito en esta peligrosa misión, te recompensaré debidamente.", t = "Espiando a los Tótem Siniestro"},
    [5088] = {ot = "Mata a Arikara. Lleva sus restos, junto con el polvo de incendiaria, a Motega Pirocabello en el Campamento del Tramo Blanco, como prueba de tu hazaña.", st = "Toma este polvo de incendiaria, refinado y purificado, y llévalo a Las Mil Agujas. Arrójalo sobre el fuego sagrado de vida que arde en la Cumbre de la Nube Negra, en aquella aguja solitaria donde reposan los muertos.$B$BEl encantamiento que he infundido en el polvo de incendiaria invocará a Arikara ante ti, $n.$B$BTemo que aceche a Cairne Pezuña de Sangre. Las tradiciones de los tauren han cambiado demasiado, y sospecho que esto ha despertado la ira de Arikara. Apresúrate, ¡el destino pende de un hilo, $c!", t = "Arikara"},
    [5147] = {ot = "Mata a Arnak Tótem Siniestro y llévale una prueba de tu hazaña al vigiarrisco Cuerno Largo, que está en el Poblado Viento Libre.", st = "Se busca: Arnak Tótem Siniestro$B$BSe busca a Arnak el Paria por los atroces crímenes de asesinato y secuestro. Quienes tengan la valentía de traer a este criminal ante la justicia recibirán una generosa recompensa.$B$BArnak fue visto por última vez en los riscos situados al lado de Cumbre de la Nube Negra. Para reclamar tu recompensa enseña una prueba de tus acciones al vigiarrisco Cuerno Largo en Poblado Viento Libre.", t = "SE BUSCA: Arnak Tótem Siniestro"},
    [5151] = {ot = "Acaba con la bestia y trae de regreso el hipercondensador y la llave de la jaula de pantera a Wizlo Rodabrillante.", st = "Soy el único superviviente del ataque centauro a nuestra caravana. Una extraña aunque poderosa pantera está custodiando mi mejor invención, y la tiene alrededor del cuello. ¡Ja! Hasta los centauros tiemblan al verla.$B$BAquí tienes la llave de la jaula de pantera. Ya no queda nada allí, solo la pantera. Acaba con esa bestia, tráeme el hipercondensador y te recompensaré.$B$BLos restos de la caravana están al norte de aquí.|n", t = "Hipercondensador"},
    [5261] = {ot = "Habla con Eagan Desollapelambres.", st = "Eagan Desollapelambres está buscando a alguien que cace lobos por él. Eso es bueno, porque hemos empezado a ver muchos lobos más en el Valle de Villanorte últimamente.$B$BSi te interesa, habla con Eagan. Está junto a la abadía, a la izquierda.", t = "Eagan Desollapelambres"},
    [5321] = {ot = "Escolta a Kerlonian Semprumbrío hasta Liladris Rioluna, que está al sur del camino, para encontrar su bolsa en Costa Oscura.", st = "Estaba de camino hacia la Atalaya de Maestra para encontrarme con Liladris Rioluna, pero decidí detenerme aquí a echar una siestecita. Desde que me desperté de mi Sueño Esmeralda me invade un gran sopor...\n\n<bostezo>\n\n¡Y no puedo encontrar mis cosas! ¿Te importaría indicarme el camino?\n\nTengo entendido que la Atalaya de Maestra está al sur de aquí, por el camino de Vallefresno. He venido desde esa dirección...\n\nOtra cosa: puede que me duerma, así que, si necesitas despertarme, utiliza mi cuerno. Lo encontrarás en este cofre.", t = "El despertar"},
    [5441] = {ot = "Utiliza la Cachiporra del supervisor con los peones vagos que estén durmiendo. Despierta a 5 peones y devuélvele la cachiporra al supervisor Thazz'ril en el Valle de los Retos.", st = "¡Malditos peones! Trabajan muy duro recogiendo madera de los árboles del valle, ¡pero siempre se están echando siestas! Necesito a alguien que me ayude a mantener firmes a esos peones.$B$BPareces $gel:la:r; $r $gadecuado:adecuada; para esta tarea. Toma, coge esta cachiporra y utilízala con los perezosos peones que encontrarás durmiendo por ahí durante el trabajo. ¡Un buen golpe y volverán al trabajo! Devuélveme la cachiporra cuando hayas terminado.$B$BQué vagos y flojos son estos peones...", t = "Peones vagos"},
    [5481] = {ot = "Recoge 3 hierbas luminiscentes y entrégaselas al boticario auxiliar Holland en el cementerio de Rémol.", st = "Maestro querer hierbas. Nosotros manos grandes y no poder recoger. Si tú ayudas nosotros no hacer daño. Nosotros necesitar hierba luminiscente. Haber muchas por aquí y cerca de camino.$B$BCuando tú tener hierba luminiscente, llevar a maestro Holland a cementerio de Rémol.|n", t = "La tarea de Gordo"},
    [5482] = {ot = "Recoge 10 apocalíseas y entrégaselas al boticario auxiliar Holland.|n", st = "Estoy en un aprieto, $n. ¡Esa cosa está ahí fuera recogiendo las plantas que no son! Te recompensaré si recoges lo que necesito. Tráeme suficientes apocalíseas y te daré una recompensa apropiada.$B$BTengo entendido que abundan en las proximidades de la fosa común, al norte del cementerio de Rémol. Date prisa y ten cuidado con los gnolls que vagan por la zona.", t = "Apocalíseas"},
    [5541] = {ot = "Lleva la munición de Estruendo a Hegnar Estruendo a Dun Morogh.", st = "Hegnar Estruendo vende armas de fuego en la carretera de Yunquemar. Los fusileros y los equipos de mortero pasan mucho tiempo practicando en la parte exterior de su tienda y siempre necesita munición fresca.$B$BPero la última caja de munición que le envié se perdió por el camino. Mi mensajero acampó cerca de El Cubil Pardo. Cuando un wendigo lo expulsó de allí, ¡el muy inútil, se dejó la munición de Estruendo!$B$B$n, ¿podrías recuperar esa munición y llevársela a Estruendo? Lleva mucho tiempo esperándola y se le estarán acabando las reservas.", t = "Municiones para Estruendo"},
    [5545] = {ot = "Lleva 8 fardos de madera a Raelen al Aserradero de la Vega del Este.", st = "Tengo un auténtico problema entre manos. Se acerca peligrosamente la fecha en la que tengo que entregar un pedido de madera... Los lobos y los osos que hay al norte de aquí ahuyentaron a mis trabajadores, que tuvieron que dejar atrás los fajos de madera que tenían talada.$B$BYa he hablado con el ayudante de alguacil Rainer sobre la necesidad de deshacernos de esos animales, pero necesito que alguien vaya a recoger la madera. Si pudieras recoger ocho fajos de madera, conseguiría cumplir el plazo.", t = "El cumplimiento del plazo"},
    [5621] = {ot = "Encuentra a la centinela Shaya y cura sus heridas utilizando un hechizo de Sanación inferior (Rango 2). A continuación, concédele la Palabra de poder: entereza, y después ve a ver de nuevo a Laurna Luzdelalba a Dolanaar.", st = "Necesito tu ayuda, $n. Tengo que quedarme aquí para instruir a los demás alumnos, pero tú, tú podrías ayudar a una de nuestras centinelas heridas que se encuentra al sur de Dolanaar. La hirieron mientras patrullaba la ciudad y necesita nuestra ayuda. Su nombre es Shaya.$B$BCuando la encuentres, cura sus heridas y fortalece su cuerpo por medio de tus hechizos. Esto al menos la protegerá de males mayores en caso de que se meta en líos. Vuelve a mí cuando hayas cumplido con tu cometido para Elune.", t = "Prendas de la luna"},
    [5622] = {ot = "Habla con Laurna Luzdelalba en Teldrassil.", st = "$n, debes viajar a Dolanaar cuando acabes tus negocios aquí en Cañada Umbría. Allí encontrarás a Laurna Luzdelalba. Ella te seguirá instruyendo en los caminos de Elune, y con ella ganarás tus primeras vestimentas que te distinguirán como $gsacerdote:sacerdotisa; de Elune.$B$BCuídate y que tengas suerte en tus viajes.", t = "Los caminos de Elune"},
    [5623] = {ot = "Ve al Bosque de Elwynn y habla con la sacerdotisa Josetta.", st = "Hola nuevamente, joven $gsacerdote:sacerdotisa;. Ha llegado la hora de que aprendas más sobre nuestra religión. Tras completar las tareas que tengas aquí en Villanorte, busca a la sacerdotisa Josetta en Villadorada. Ella podrá enseñarte más. Ya sabe que vas muy rápido y que la Luz ha hecho mella en ti. Te está esperando.", t = "Al servicio de la Luz"},
    [5624] = {ot = "Encuentra al guardia Roberts y cura sus heridas con Sanación inferior (Rango 2). Después, concédele Palabra de Poder: Entereza y vuelve a Villadorada a hablar con la sacerdotisa Josetta.", st = "Me gusta probar las habilidades de los seguidores de la Luz con un pequeño desafío. Para ver si merecen vestir su primera túnica... un símbolo visible de que la iglesia aprueba y apoya $ga un sacerdote:a una sacerdotisa;.$B$BPero esta situación es un poco diferente. Uno de los ciudadanos de Villadorada vio a un guardia herido cerca del lago que hay al este de aquí. Se llama Roberts. Encuéntralo, cura sus heridas, fortalece su cuerpo y vuelve a mí. Si haces eso por mí, consideraré que has superado la prueba.", t = "Las prendas de la Luz"},
    [5625] = {ot = "Encuentra al montaraz Dolf y cura sus heridas usando la Sanación inferior (Rango 2). Después, concédele Palabra de Poder: Entereza y vuelve a Kharanos a hablar con Maxan Anvol.", st = "Por tradición, este es el momento en el que alguien con tu poder debe demostrar si merece el honor de llevar la toga que denota su posición en la iglesia. Pero, si te soy sincero, tengo asuntos más urgentes que atender. Ha estado aquí un ciudadano de Kharanos y me ha hablado de un montaraz herido llamado Dolf que se encuentra en las afueras de la ciudad, hacia el sur.$B$BSi curas a Dolf y le das entereza, yo consideraré que has demostrado tu valía. ¿Qué te parece?", t = "Las prendas de la Luz"},
    [5626] = {ot = "Ve a Dun Morogh y habla con Maxan Anvol.", st = "¡Eh, $n! ¡¿Tienes un minuto?!$B$BYa llevas tiempo suficiente siguiendo la Luz, es hora de que vayas a Kharanos en busca de Maxan Anvol. Él te enseñará más sobre el camino que estás recorriendo y, si pruebas que lo mereces, te dará tu primera toga. La que denotará tu posición de $gsacerdote:sacerdotisa;.$B$B¡Y ahora, en marcha! En cuanto acabes aquí, atraviesa el túnel. Él te estará esperando.", t = "Al servicio de la Luz"},
    [5629] = {ot = "Ve a Darnassus y habla con la sacerdotisa Alathea.", st = "Hola de nuevo, $n. Sé que has dedicado mucho tiempo a ayudar a nuestra gente, pero ahora debes dedicarte un poco de tiempo a ti. La sacerdotisa Alathea envió a alguien a buscarte. Parece que has llamado la atención de nuestros ancianos. Creen que ha llegado el momento de que empieces a hacer cosas más importantes. Ve al Templo de la Luna de Darnassus y busca a Alathea. Ella te estará esperando. Buena suerte y que Elune te acompañe.", t = "La vuelta a casa"},
    [5634] = {ot = "Habla con el sumo sacerdote Rohan en Forjaz.", st = "Hace poco vino un sacerdote por aquí. Te estaba buscando, joven $r. Dijo que tenía el cometido de encontrarte y comunicarte que debías regresar a la Sala de los Misterios en Forjaz cuanto antes. Cuando llegues, busca al sumo sacerdote Rohan. Él te dará más información.$B$BQue la Luz sea contigo, $n.", t = "Oración desesperada"},
    [5641] = {t = "Castigar"},
    [5642] = {ot = "Habla con Ur'kyo en Orgrimmar.", st = "En Orgrimmar está pasando algo, $n.$b$bLos mensajeros que vienen normalmente en busca de sacerdotes trol suelen ser muy tranquilos. Pero esta vez parecía que llevaban mucha prisa. No te entretengas mucho en Cima del Trueno; ve al Valle de los Espíritus lo antes posible.", t = "Guardia de las Sombras"},
    [5644] = {ot = "Habla con Aelthalyste en Entrañas.", st = "Es un día maravilloso para ti, $n. Puedo ver por las lecciones que has aprendido que ha llegado el momento de que te envíe de nuevo ante Aelthalyste. Hay cosas que solo ella puede enseñarte, eso sí, siempre y cuando demuestres que eres $gmerecedor: merecedora; de ello.$B$BNo quiero estropearte la sorpresa pero recuerdo cuando yo era un joven sacerdote aprendiendo el verdadero poder... el poder divino. ¡Qué tiempos aquellos!$B$BVe a ver a Aelthalyste a Entrañas, $n. Ella te estará esperando en el Barrio de la Guerra.", t = "Sacrificio oscuro"},
    [5648] = {ot = "Encuentra a la bruta Kor'ja y cura sus heridas usando la Sanación inferior (Rango 2). Después, concédele Palabra de Poder: Entereza y vuelve a Cerrotajo a hablar con Tai'jin.", st = "Ya estás $gpreparado:preparada; para tu primera prueba, $n. Una de nuestras brutas fue herida en combate por unas tropas de Valiente, al sur de Cerrotajo, nada más salir de la ciudad. No está muy bien y no le vendría mal que uno de nosotros acudiera en su ayuda. Encuéntrala. Se llama Kor'ja. Cura sus heridas y dale la bendición de nuestros antepasados.$B$BSi haces esto, consideraré que has demostrado que estás $glisto:lista; para moverte en nuestra cultura.", t = "Prendas de espiritualidad"},
    [5649] = {ot = "Ve a Durotar y habla con Tai'jin.", st = "Eh, colega. Nuestra gente se ha unido a la Horda porque es bueno para nosotros. Son leales y nos enseñan mucho sobre cosas como el honor. Pero nuestras viejas costumbres no desaparecen así como así. Los orcos no aprueban todas nuestras tradiciones, pero eso no quiere decir que no podamos seguir practicando algunas de ellas en secreto.$B$BTú lo comprendes. Por eso te envío a ti a Tai'jin, que está en Cerrotajo. Ella te enseñará más de nuestra historia. Te enseñará las costumbres de nuestra tribu. Ve a verla cuando estés $glisto:lista;.", t = "Al servicio de la espiritualidad"},
    [5650] = {ot = "Encuentra al Guardia de la Muerte Kel y cura sus heridas utilizando un hechizo de Sanación inferior (Rango 2). A continuación, concédele la Palabra de poder: entereza, y después ve a ver de nuevo al clérigo oscuro Beryl a Rémol.", st = "Nuestro poder proviene de la oscuridad y la sombra, $n, pero eso no es lo único que debes saber. Has reconocido la importancia de dominar las artes de curación, lo cual es muy sensato por tu parte. Pero para conocer la oscuridad, debes conocer también la luz. Con este fin, tengo una prueba preparada para ti.$B$BAl norte del cementerio hay un Guardia de la Muerte herido, el Guardia de la Muerte Kel. Él nos ha protegido de los gnolls durante un tiempo y ahora necesita que lo curen. Es más, también deberás fortalecer su cuerpo para que así pueda desempeñar de nuevo sus funciones. Utiliza tus hechizos para conseguir estos dos objetivos y después regresa aquí.", t = "Las prendas de la Oscuridad"},
    [5651] = {ot = "Habla con el clérigo oscuro Beryl en los Claros de Tirisfal.", st = "Son muchas las lecciones que los Renegados han aprendido a través de la experiencia, cosas que algunas razas no alcanzan a entender. Y aunque nuestro camino transcurre por la oscuridad, descubrirás que muchas cosas dependen tanto de la luz como de la oscuridad. Las lecciones que recibirás te enseñarán a utilizar ambas... y con criterio. Pero presta atención a lo que te digo: nunca olvides que nacimos de la corrupción y fuimos abandonados a nuestra suerte para que nos pudriéramos como vulgar carroña. La oscuridad es nuestro hogar.$B$BBusca al clérigo oscuro Beryl en Rémol cuando estés $gpreparado:preparada; para seguir aprendiendo.", t = "Al servicio de la Oscuridad"},
    [5654] = {ot = "Habla con Ur'kyo en Orgrimmar.", st = "Es hora de que vayas al encuentro de Ur'kyo, $n. Está en el Valle de los Espíritus, en la ciudad orca. Ve allí y habla con él. Es hora de que aprendas algo más de nuestras costumbres. Es hora de introducirte en el círculo y convertirte en $gun auténtico sacerdote:una auténtica sacerdotisa; de nuestra tribu.", t = "Maleficio de Debilidad"},
    [5658] = {t = "Toque de debilidad"},
    [5672] = {t = "La Gracia de Elune"},
    [5676] = {t = "La reacción Arcana"},
    [5713] = {ot = "Protege a la centinela Aynasha y luego ve a Vallefresno, a la Atalaya de Maestra, y habla con Onaeya.", st = "Viajaba a Auberdine con un mensaje importante cuando fui atacada por el fúrbolg Marosh y sus rastreadores. Me envenenaron... y apenas puedo permanecer de pie. Puedo preparar un antídoto, pero necesitará algo de tiempo antes de que esté listo.$B$BTe pido que me defiendas hasta que pueda aplicarme el antídoto. Yo haré lo mejor que pueda para ayudarte con mi arco.$B$BSi sobrevivimos, podré llevar mi mensaje a Auberdine, mientras tú hablas con Onaeya, en la Atalaya de Maestra, para contarle sobre este incidente.", t = "Un tiro. Un muerto."},
    [5722] = {ot = "Inspecciona la Sima Ígnea en busca del cuerpo de Maur Tótem Siniestro y comprueba si porta algún objeto de interés.", st = "Los troggs no eran lo único que le interesaba a Magatha de la Sima Ígnea. Ella ha oído decir que uno de sus sirvientes, Maur Tótem Siniestro, encontró algo muy especial en la Sima pero que nunca consiguió salir con vida para enseñárselo. Le gustaría encontrar el cuerpo de Maur, si es que todavía queda algo de él, y cualquier indicio de lo que él había encontrado en su intento de hablar con los troggs.$B$BLlévale a Magatha cualquier objeto que pueda ser de su interés y seguro que te recompensará con generosidad.$B$BDe nuevo, busca la Sima en la zona más oscura de Orgrimmar.", t = "Buscando la cartera perdida"},
    [5723] = {ot = "Localiza la Sima Ígnea en Orgrimmar y después mata a 8 troggs Furia Ardiente y 8 chamanes Furia Ardiente y después ve a ver de nuevo a Rahauro a Cima del Trueno.", st = "En la ciudad de Orgrimmar, robustas criaturas conocidas como troggs comenzaron a salir a la superficie desde las profundidades de los túneles llenos de lava. En su benevolencia, Magatha trató de negociar con las criaturas pero estas se echaron encima de sus diplomáticos y los mataron. No permitiría un trato semejante al pueblo tauren por lo que estas criaturas ahora son consideradas como una amenaza para todos los de la Horda.$B$BElla te pide que pongas fin a la amenaza de los troggs antes de que acaben con la Horda. Encuentra la Sima Ígnea y acaba con todos ellos.", t = "Midiendo fuerzas con el enemigo"},
    [5724] = {ot = "Lleva la cartera de Tótem Siniestro hasta Rahauro, en Cima del Trueno.", st = "Encuentras una cartera bajo el cuerpo del tauren. Todavía está fuertemente aprisionada entre sus brazos como si la hubiera estado protegiendo mientras fue atacado por los troggs.$B$BCoges la cartera, la guardas con tu equipo y te dispones a salir de los túneles de vuelta a Rahauro en Cima del Trueno.", t = "La vuelta de la cartera perdida"},
    [5725] = {ot = "Llévale los libros Hechizos de las Sombras y Encantamientos desde el infierno a Varimathras, que está en Entrañas.", st = "Muchos integrantes de la Legión ofrecen regalos a sus seguidores, como seguro que ya sabes. La Dama Oscura cree que muchos de estos regalos estarían mejor en su poder que en manos de esos... que no son tan avezados.$B$BUna secta del Consejo de la Sombra, oculta en las cavernas situadas bajo Orgrimmar y conocida como Hoja Abrasadora, es un excelente ejemplo. La Dama sabe que los miembros de la secta Hoja Abrasadora se han hecho con dos poderosos libros de hechizos que le gustaría \"tomar prestados\". Tú serás quien los consiga para ella.", t = "Poder destructivo"},
    [5726] = {ot = "Lleva una insignia de Teniente a Thrall a Orgrimmar.", st = "No tolero a los traidores, $n. Pero sería necio mostrar mis cartas demasiado pronto; no eliminaría la corrupción de nuestras tierras y la infestación sería aún peor.$b$bPero tú, joven errante, podrías ir hasta donde no llegaron mis agentes y averiguar la verdad.$b$bSi eres lo bastante valiente, ve a Roca del Cráneo, al este de Orgrimmar, consigue una insignia de Teniente de Filo Ardiente y tráemela.", t = "Enemigos ocultos"},
    [5727] = {ot = "Lleva la insignia de Teniente a Neeru Hojafuego. Averigua si cree que eres miembro de Filo Ardiente; luego ve a ver a Thrall a Orgrimmar.", st = "Veamos si la insignia vale la pena el esfuerzo.$b$bEn la ciudad hay un brujo que cree que aún confío en él. No sabe que he descubierto su traición: es el jefe de Filo Ardiente. Pero no te enfrentes con él ahora; podemos usarlo contra nuestros enemigos.$b$bLlévale esta insignia; está en el Circo de las Sombras, aquí en Orgrimmar. Vuelve después de hablar con él y dime si ha creído que eras de los suyos.", t = "Enemigos ocultos"},
    [5728] = {ot = "Mata a Bazzalan y a Jergosh el Convocador y ve a ver a Thrall a Orgrimmar.", st = "Así que jefes de Hoja Abrasadora, ¿eh? Interesante... Si son los más cercanos a Neeru, tienen que ser nuestro primer objetivo. El sátiro Bazzalan y el otro que mencionó Neeru, creo que era un brujo, deben ser eliminados.$b$b$n, vuelve al Circo de las Sombras y entra en la Sima Ígnea. Liquida al sátiro y al brujo, pero que Neeru no se entere de que has sido tú. Tiene que seguir creyendo que eres de $glos suyos:las suyas;.", t = "Enemigos ocultos"},
    [5729] = {ot = "Habla con Neeru Hojafuego en Orgrimmar.", st = "Ahora deberíamos situarte cerca de Neeru. Si está tan inquieto como dicen, podemos conseguir dos cosas: que averigües más cosas sobre el Consejo y Filo Ardiente y que empiece a confiar en ti y te pida ayuda. La necesitará ahora que hay agitación en la cúpula dirigente.$b$bVe otra vez a la Grieta a hablar con él, pero sé sutil.", t = "Enemigos ocultos"},
    [5730] = {ot = "Habla con Thrall en Orgrimmar y cuéntale lo que has averiguado.", st = "Eres $guno:una; de mis generales. Prepárate, $c; pronto pasarás a la acción.$b$bAl parecer he perdido el tiempo con Hoja Abrasadora, pero no por eso tienen que alterarse los demás planes del Consejo de la Sombra. Haré lo que pueda para paliar los daños en la Sima Ígnea; mientras tanto, mis agentes se pondrán a trabajar en nuestro nuevo proyecto en Los Baldíos y Vallefresno. Regresa pronto.", t = "Enemigos ocultos"},
    [5761] = {ot = "Ve a la Sima Ígnea, mata a Taragaman el Hambriento y llévale su corazón a Neeru Hojafuego a Orgrimmar.", st = "Mi trabajo principal consiste en erradicar a las criaturas responsables de la infestación demoníaca en nuestra maravillosa ciudad. Filo Ardiente es una amenaza, pero hay otras, como Hoja Abrasadora, que reside en la Sima Ígnea e intenta subvertir a miembros de la Horda en secreto.$b$bPara detenerlos debemos eliminar a su jefe, un guardia vil llamado Taragaman el Hambriento.$b$bMátalo y entrégale su corazón a Thrall; eso lo tranquilizará.", t = "Matar a la bestia"},
    [5881] = {ot = "Maggran quiere que le entregues una carta a Grish Largo Camino en El Gran Elevador, en Los Baldíos.", st = "La Horda hace bien manteniendo a nuestras tropas frescas... Desde la Gran Guerra, hemos disfrutado de una gran prosperidad aquí, en Kalimdor.$B$BNecesito que me hagas un favor. Hay un tipo, Grish Largo Camino, que protege El Gran Elevador, en Los Baldíos del Sur. Entrégale esta carta. La carta le informará de que un guerrero de reserva va de camino para relevarle, así podrá ir a visitar a su familia. Lo solicitó hace bastante tiempo y estará encantado de conocer las buenas noticias.", t = "La sustitución"},
    [5921] = {ot = "Utiliza el hechizo \"Teletransporte: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.", st = "En las sagradas tierras de Claro de la Luna todos los druidas son bienvenidos, a pesar de las tensiones que hay dentro del Círculo Cenarion entre el archidruida Corzocelada y el guardián Remulos, el guardián de Claro de la Luna. Ahora que estás aprendiendo el camino de la zarpa, te enseñaré el hechizo que te permite transportarte allí. Utilízalo cuando busques el conocimiento o el consuelo del Claro de la Luna.$B$BComo primera lección, ve a Claro de la Luna. Busca a Dendrita Rafagaestelar en el Amparo de la Noche y háblale del camino que recorres. Buena suerte, joven druida.", t = "Claro de la Luna"},
    [5922] = {ot = "Utiliza el hechizo \"Teletransporte: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.", st = "En las sagradas tierras de Claro de la Luna todos los druidas son bienvenidos, al igual que los tauren y los elfos de la noche. El guardián Remulos de Claro de la Luna sigue custodiando a los druidas que hibernan allí. Ahora que estás aprendiendo el camino de la zarpa, te enseñaré el hechizo que te permite teletransportarte allí. Utilízalo cuando busques el conocimiento o el consuelo del Claro de la Luna.$B$BComo primera lección, ve a Claro de la Luna. Busca a Dendrita Rafagaestelar en Amparo de la Noche y háblale del camino que recorres. Buena suerte, joven druida.", t = "Claro de la Luna"},
    [5923] = {ot = "Habla con Mathrengyl Garroso en el Enclave Cenarion de Darnassus.", st = "Oye, perdona...$B$BHe sabido que Mathrengyl Garroso quiere hablar contigo. Por lo visto, tu instrucción de druida va a dar un giro, porque te va a instruir él personalmente. Mathrengyl es el ayudante personal del mismísimo archidruida y uno de los druidas más sabios y augustos que encontrarás en Teldrassil.$B$BLo encontrarás en el Enclave Cenarion de Darnassus, en el segundo piso del árbol de Fandral Corzocelada.", t = "Escucha la llamada"},
    [5928] = {ot = "Habla con Turak Tótem de Runa en Alto de los Ancestros, en Cima del Trueno.", st = "Oye, perdona...$b$bHe sabido que Turak Tótem de Runa quiere hablar contigo. Por lo visto, tu instrucción de druida va a dar un giro, porque te va a entrenar él personalmente. Turak es uno de los ayudantes del archidruida; es sabio y paciente, te enseñará bien.$b$bEstá en Cima del Trueno, dentro de la carpa principal del Círculo Cenarion en el Alto de los Ancestros.", t = "Escucha la llamada"},
    [5929] = {ot = "Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.", st = "Al noroeste de Claro de la Luna está el hogar del un ser noble y sabio llamado el espíritu del gran oso. Gracias a él todos los druidas han podido captar la esencia natural del oso. Todo druida debe buscar la sabiduría del espíritu. Tú no vas a ser una excepción.$b$bPreséntate ante el espíritu del gran oso y aprende lo que tenga que enseñarte. Cuando hayas terminado, vuelve a verme aquí, a Amparo de la Noche. Entonces sabremos si realmente has aprendido la lección.", t = "Espíritu del gran oso"},
    [5930] = {ot = "Busca al espíritu del gran oso al noroeste de Claro de la Luna y aprende lo que tenga que enseñarte sobre la naturaleza del oso. Después ve a hablar con Dendrita Rafagaestelar a Amparo de la Noche, en Claro de la Luna.", st = "Al noroeste de Claro de la Luna está el hogar del un ser noble y sabio llamado el espíritu del gran oso. Gracias a él todos los druidas han podido captar la esencia natural del oso. Todo druida debe buscar la sabiduría del espíritu. Tú no vas a ser una excepción.$b$bPreséntate ante el espíritu del gran oso y aprende lo que tenga que enseñarte. Cuando hayas terminado, vuelve a verme aquí, a Amparo de la Noche. Entonces sabremos si realmente has aprendido la lección.", t = "Espíritu del gran oso"},
    [5931] = {ot = "Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion.", st = "Ha llegado el momento de separarnos, puesto que para poner en práctica lo que has aprendido debes volver a quien te envió a mí. Mathrengyl Garroso vive en armonía con la naturaleza, aunque vive peligrosamente cerca de donde el equilibrio natural se ha roto. Escúchalo bien y pronto habrá terminado tu preparación como $gprotector:protectora; del equilibrio.$b$bVete, joven. Volveremos a vernos.", t = "El regreso a Darnassus"},
    [5932] = {ot = "Vuelve a Cima del Trueno para hablar con Turak Tótem de Runa en Alto de los Ancestros.", st = "Ha llegado el momento de separarnos, puesto que para poner en práctica lo que has aprendido debes volver a quien te envió a mí. Aunque se dice que los tauren son inexpertos en la sabiduría de Cenarius, Turak Tótem de Runa vive en armonía con la naturaleza. Escúchalo bien y pronto habrá terminado tu preparación como $gprotector:protectora; del equilibrio.$b$bVete, joven. Volveremos a vernos.", t = "Vuelve a Cima del Trueno"},
    [6001] = {ot = "Utiliza el polvo de luna Cenarion en la piedra de lechúcico lunar de Auberdine para invocar a Garraluna. Luego tendrás que enfrentarte a Garraluna y ganar la fuerza física y de corazón que posee. $B$BCuando hayas acabado, vuelve a Darnassus y habla con Mathrengyl Garroso.", st = "Al este de Auberdine hay muchas cuevas de lechúcicos lunares. La que está más cerca de Auberdine alberga una piedra de lechúcico lunar en su interior. Garraluna, el guardián de la piedra, solo se enfrentará a ti cuando le apliques polvo de luna Cenarion. Garraluna posee una fuerza que debes usar como miembro de la zarpa.$B$BTe has ganado el derecho a usar este polvo de luna Cenarion, $n... ¡Ahora demuéstrame que también te has ganado el derecho a poseer la fuerza física y de corazón que necesitas como druida!", t = "Cuerpo y corazón"},
    [6002] = {ot = "Aplica el polvo de luna Cenarion a la piedra de lechúcico lunar que se encuentra entre Mulgore y Los Baldíos para provocar a Garraluna. Hecho esto, has de enfrentarte a Garraluna para obtener la fuerza física y de corazón que posee.$B$BHabla con Turak Tótem de Runa en Cima del Trueno cuando hayas acabado.", st = "Al oeste de Taurajo en Los Baldíos, justo antes de Mulgore, yace una piedra de lechúcico lunar. Los lechúcicos lunares son criaturas muy especiales no nativas de estas tierras. Garraluna, el guardián de la piedra, se enfrentará a ti cuando le apliques a la piedra polvo de luna Cenarion. Garraluna posee una fuerza que debes usar como miembro de la zarpa.$B$BTe has ganado el derecho a usar este polvo de luna Cenarion, $n... ¡Ahora demuéstrame que también te has ganado el derecho a poseer la fuerza física y de corazón que necesitas como druida!", t = "Cuerpo y corazón"},
    [6061] = {ot = "Usa la fusta de doma para domar un zancudo de llanura adulto. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.", st = "Para los tauren es importante seguir la tradición ancestral de luchar contra criaturas poderosas. Al someterlas absorbemos su espíritu, lo que nos acerca a la Madre Tierra.$b$bDel mismo modo, domar a una bestia para que luche de nuestro lado es una forma de unirse a la naturaleza. Aprenderás a domar criaturas. Pero estas cosas requieren tiempo y práctica. Para empezar, usa esta fusta de doma para domar un zancudo de llanura adulto.", t = "Domesticar la bestia"},
    [6062] = {ot = "Usa la fusta de doma para domar un jabalí jaspeado temible. Practica un poco y devuélvele la fusta a Thotar en Cerrotajo.", st = "Someter a la naturaleza a tu autoridad es una habilidad admirable. Como $gcazador:cazadora;, debes esforzarte en aprender a utilizar la fuerza y el poder inherentes a cualquier criatura.$B$BHacerse con el control de un animal no es una tarea sencilla; debes acometerla con gran determinación.$B$BComo primera tarea, coge esta fusta de doma y utilízala para domar a un jabalí jaspeado temible. Podrás encontrar los que quieras cerca de Cerrotajo. Practica tus habilidades de combate con el jabalí a tu lado y luego vuelve a verme.", t = "Domesticar la bestia"},
    [6063] = {ot = "Utiliza la fusta de doma para domar a un rondador Tejemadera. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.", st = "Al ser $gcazador:cazadora; es muy importante que recuerdes la responsabilidad que tienes en tus manos. La naturaleza no es un poder que puedas modificar a tu antojo. Todo al contrario, es un poder que debe respetarse y entenderse como algo mucho más fuerte que tu propia existencia.$B$B$n, debes demostrar que comprendes lo que acabo de decirte para poder adquirir la habilidad de domar a un animal para convertirlo en tu mascota.$B$BEn primer lugar, coge esta fusta de doma con la que podrás domar a un rondador Tejemadera. Dómalo y practica tus habilidades como $gcazador:cazadora;.", t = "Domesticar la bestia"},
    [6064] = {ot = "Usa la fusta de doma para domar a un jabalí del risco grande. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.", st = "¡Buenas, $Gchaval:chavala;! Supongo que quieres saber cómo conseguir una mascota.$b$bMuy bien, vamos a ello. Para cazar, lo más importante es el equipo, pero ya hablaremos de mi lanzatralla otro día. De momento, hablaremos de lo que te interesa: ¡las mascotas!$b$bLo mejor es que pruebes con varias criaturas, hasta que decidas cuál te gusta más. Busca un jabalí del risco grande y dómalo con la fusta de doma.", t = "Domesticar la bestia"},
    [6081] = {ot = "Habla con Ormak Tirosiniestro en Orgrimmar.", st = "Ahora tienes la capacidad de domar una mascota, pero también debes adquirir las habilidades necesarias para amaestrarla.$B$BDirígete a Orgrimmar y habla con Ormak Tirosiniestro, uno de nuestros cazadores más venerados. Él te proporcionará la habilidad para amaestrar a tu nueva mascota. Lo encontrarás cerca del Bastión de los Valientes.$B$BBuena suerte, $n.", t = "Domesticar la bestia"},
    [6082] = {ot = "Usa la fusta de doma para domar un escórpido acorazado. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo.", st = "La última criatura que debes domar es una a la que deberías intentar emular: el escórpido acorazado. Golpea con rapidez y confianza. Controlar una fuerza como la suya es tu destino como $gcazador:cazadora;.$B$BCuando vuelvas, te otorgaré las habilidades que necesitas para domar a cualquier animal que desees; así tendrás a una criatura a tus órdenes. Bajo tu mando, tu mascota irá ganando experiencia a la vez que lo haces tú. Y también te enseñaré cómo llamarla y despedirla a placer.|n", t = "Domesticar la bestia"},
    [6083] = {ot = "Usa la fusta de doma para domar un reptador de espuma. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo.", st = "La ventaja que te concede una mascota frente a tus rivales es de sobra conocida, $n. Cuando controlas a otra criatura, potencias tu propia fuerza. Tu mascota debe convertirse en una extensión de ti $gmismo:misma;.$B$BTu siguiente cometido requiere que te alejes de la tierra: encontrarás a la siguiente criatura en las aguas de la costa. Cruza el Poblado Sen'jin, cerca de las Islas del Eco. Busca un reptador de espuma, un enérgico cangrejo. Utiliza la fusta para domarlo y luego practica tus habilidades.", t = "Domesticar la bestia"},
    [6084] = {ot = "Usa la fusta de doma para domar un leopardo de las nieves. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.", st = "Son unas bestias bastante aparatosas; quizás prefieras algo más pequeño. Muy bien, tengo lo que necesitas. Al sureste de aquí encontrarás unos gatos blancos grandes, los leopardos de las nieves. Su belleza exterior oculta unos luchadores temibles y muy peligrosos. Verás que son mucho más ágiles que el jabalí que has domado.$b$bCoge esta fusta de doma y a ver qué tal te va con un leopardo de las nieves.", t = "Domesticar la bestia"},
    [6085] = {ot = "Usa la fusta de doma para domar un oso zarpahelada. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos.", st = "A lo mejor prefieres una criatura con más fuerza bruta. Los osos zarpahelada son excelentes mascotas para alguien con poca experiencia como tú. Los encontrarás al este de Kharanos. Aquí tienes la fusta de doma; ¡a ver si este animal te gusta como mascota!$b$bCuando vuelvas, te daré las habilidades que necesitas para domar al animal que quieras; luchará junto a ti en todo y ganará experiencia al mismo tiempo que tú. También te enseñaré a llamarlo y despedirlo.|n", t = "Domesticar la bestia"},
    [6086] = {ot = "Habla con Belia Tronagranito en Forjaz.", st = "$n, tienes la capacidad de domar a un animal, pero también necesitas la habilidad para amaestrarlo.$b$bVe a la Sala de Armas de Forjaz. Habla con Belia Tronagranito, una de las mejores instructoras que tenemos. Te dará el poder de amaestrar a tu mascota, ¡así que andando, $Gchaval:chica;!$b$bBelia es muy agradable, no tendrás problemas con ella. Suerte, $n.|n", t = "Domesticar la bestia"},
    [6087] = {ot = "Usa la fusta de doma para domar un acechador de pradera. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.", st = "Tienes un espíritu indomable, siempre abierto a los desafíos.$B$BAhora debes ganarte la confianza de un tipo de lobo llamado el acechador de pradera. Son criaturas ágiles que no temen a nada; al domar a uno de ellos, adquirirás esas cualidades.$B$BCuando entres en combate aprenderás cómo luchar junto a tu mascota. Se convertirán en una fuerza indivisible.$B$BTen la fusta de doma, $n. Practica amaestrando a un acechador de pradera.", t = "Domesticar la bestia"},
    [6088] = {ot = "Usa la fusta de doma para domar un aguilón. Practica un poco y devuélvele la fusta a Yaw Crinafilada en el Poblado Pezuña de Sangre.", st = "Tu última tarea será amaestrar a una criatura de los cielos. El aguilón es un enemigo peligroso, pero si lo conviertes en tu aliado, ganarás sus ataques repentinos y su presencia amenazante.$b$bCuando vuelvas y por voluntad de la Madre Tierra, te daré las habilidades que necesitas para domar al animal que quieras; luchará junto a ti en todo y ganará experiencia al mismo tiempo que tú. También te enseñaré a llamarlo y a retirarlo.|n", t = "Domesticar la bestia"},
    [6089] = {ot = "Habla con Holt Tronacuerno en el Alto de los Cazadores, en Cima del Trueno.", st = "Ahora tienes la capacidad de domar a un animal, pero también necesitas la habilidad para amaestrarlo.$B$BVe a Cima del Trueno y habla con Holt Tronacuerno. Es uno de nuestros mejores cazadores. Te dará la habilidad de amaestrar a tu mascota si considera que la mereces.$B$BHa dominado a las bestias más feroces de Azeroth y tiene a varias criaturas a su mando. Vive en armonía con la Madre Tierra; aprenderás mucho de él. Suerte, $n.|n", t = "Domesticar la bestia"},
    [6101] = {ot = "Utiliza la fusta de doma para domar a un acechador sable de la noche. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.", st = "La naturaleza está en continuo cambio, $n. En este sentido, es algo predecible.$B$BLas tareas que te voy a encomendar te ayudarán a ver y apreciar las grandes diferencias existentes entre unas criaturas y otras para que puedas elegir la que más te conviene como mascota.$B$BCoge esta fusta de doma y utilízala para domar a un acechador sable de la noche, que encontrarás en dirección sur. Practica tus habilidades como $gcazador:cazadora;. Entonces empezarás a comprender las similitudes y las diferencias que se dan en la naturaleza.", t = "Domesticar la bestia"},
    [6102] = {ot = "Utiliza la fusta de doma para domar a un estridador estrígido. Practica tus habilidades y después devuélvele la fusta de doma a Dazalar, que está en Dolanaar.", st = "Has domado a dos criaturas terrestres y ahora debes domar a una criatura de los cielos. Utiliza la fusta de doma para domar a un estridador estrígido, que encontrarás en dirección oeste. Practica tus habilidades con la poderosa lechuza que tienes a tu lado.$B$BCuando vuelvas, te daré las habilidades que necesitas para domar al animal que quieras; luchará junto a ti en todo y ganará experiencia al mismo tiempo que tú. También te enseñaré a llamarlo y a retirarlo cuando quieras.", t = "Domesticar la bestia"},
    [6103] = {ot = "Habla con Jocaste en el Enclave Cenarion de Darnassus.", st = "Ahora tienes el poder de domar una mascota, pero también debes adquirir las habilidades necesarias para amaestrarla.$B$BDirígete a Darnassus y habla con Jocaste, una de nuestras cazadoras más veneradas. Ella te proporcionará la habilidad para amaestrar a tu nueva mascota, así que date prisa.$B$BAunque pueda parecer demasiado estricta, siempre está dispuesta a instruir a nuevas promesas. Trátala con respeto y ella hará lo mismo contigo. Buena suerte, $n.", t = "Domesticar la bestia"},
    [6121] = {ot = "Viaja a Claro de la Luna, al poblado Amparo de la Noche, y habla con Dendrita Rafagaestelar.", st = "Ha llegado el momento de que aprendas algo sobre el veneno y el poder que los druidas tenemos sobre él, $n. Cenarius nos ha bendecido con la habilidad de purgar el veneno más agresivo con un mero conjuro. Este es un don que no debe tomarse a la ligera. Y para asegurarme de que aprendes esta lección, tratarás los efectos del envenenamiento como lo haría un seglar.$B$BViaja a Claro de la Luna y habla con Dendrita Rafagaestelar. Espera tu llegada para dar comienzo a tu lección.", t = "Nuevas lecciones"},
    [6122] = {ot = "Recoge agua de Salto de Fonroca a la entrada de la cueva.$b$bEntrégale la muestra llena de Salto de Fonroca a Alanndarian Arrullanoche; en Auberdine, en Costa Oscura.", st = "Casi toda el agua potable de la región proviene de Salto de Fonroca, en Costa Oscura. Sospecho que allí está el foco del envenenamiento que afecta a los ciervos. Recoge agua de la boca de la cueva con este recipiente. Ten cuidado; en una cueva al lado de la cascada viven unos nagas muy peligrosos.$b$bLlévaselo a Alanndarian Arrullanoche; está en Auberdine. Fue ella quien nos pidió ayuda y trabajarás con ella para solucionar este problema.", t = "La fuente del envenenamiento"},
    [6123] = {ot = "Lleva 5 raíces de tierra y 12 hongos lunares a Alanndarian Arrullanoche a Auberdine, para que pueda preparar un bálsamo curativo.", st = "El agua servirá como base para el bálsamo curativo que prepararé para los ciervos. Pero necesitaré raíz de tierra para potenciar sus propiedades curativas. Los herboristas saben cómo encontrarla, así que si no entiendes mucho de este tema, tendrás que encontrar a uno que nos ayude.$B$BPor último, para darle potencia, necesito hongos lunares. No es difícil encontrar flores de hongo lunar. Solo tienes que ir hacia el este y buscar en cualquier cueva. Pero ten cuidado, en las cuevas hay lechúcicos lunares y últimamente están muy irritables.", t = "Reunir los ingredientes del remedio"},
    [6124] = {ot = "Utiliza el bálsamo curativo para animales en los 10 ciervos enfermos que hay en Costa Oscura; el bálsamo debería curarlos. Se han avistado ciervos enfermos desde el sur del Río Fonroca hasta el norte de Auberdine y por toda la zona que lleva hasta el sur de Costa Oscura, donde empieza Vallefresno.", st = "Con los componentes que me has traído podré preparar diez dosis de bálsamo, $n. Mientras trabajo con la aldea para conseguir más bálsamo, me gustaría que nos ayudaras a ganar tiempo. Utiliza el bálsamo para curar a los ciervos enfermos que hay por toda Costa Oscura.$B$BDendrita Rafagaestelar, de Claro de la Luna, querrá hablar contigo cuando hayas acabado. Y por favor, transmite el agradecimiento de Auberdine al Círculo Cenarion... y permite que yo te agradezca a mi vez tu ayuda.", t = "Curar la dolencia"},
    [6125] = {ot = "Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion.", st = "Has aprendido lo que significa curar un envenenamiento sin ayuda espiritual. No dejes que tu poder sobre el veneno te haga olvidar lo que los demás sufren a causa de él.$b$bEs hora de que vuelvas a ver a Mathrengyl Garroso en Darnassus, $n. Seguro que ahora que has entendido la lección, tendrá algún hechizo importante que enseñarte.$b$bBuena suerte, joven druida. Volveremos a vernos.", t = "Poder contra el veneno"},
    [6181] = {ot = "Lleva la Nota de Lewis a Thor, el maestro de grifos.", st = "Aunque no tenemos mucha ayuda directa desde Ventormenta, tengo un contacto en la ciudad que nos ayuda con los suministros de armaduras. Su nombre es Osric Strang. Su tienda, Inmunidad Limitada, está en el Casco Antiguo de Ventormenta.$B$BNuestro suministro se está agotando y debemos contactar con Osric para pedirle más. ¿Puedes llevarle esta nota?$B$BEl camino más rápido hasta Ventormenta es con Thor, nuestro maestro de grifos. Está justo bajo la colina, llévale mi nota y coge un grifo hasta Ventormenta.", t = "Mensajero a toda prisa"},
    [6261] = {ot = "Lleva el cajón de Osric a Dungar Tragolargo, el maestro de grifos.", st = "$n, he reunido en este cajón todo lo que me pidió Lewis. ¿Puedes llevárselo?$B$BSi ya has hablado con Thor, en los Páramos de Poniente, podrás usar un grifo de vuelta. Dungar Tragolargo es nuestro maestro de grifos, lo encontrarás en el Distrito de Mercaderes.$B$BHabla con Dungar y lleva este cajón a Lewis tan rápido como puedas. ¡No queremos que nuestros combatientes de los Páramos de Poniente vayan mal equipados!", t = "Dungar Tragolargo"},
    [6281] = {ot = "Cómprale al maestro de grifos Thor un vuelo en grifo y lleva la Nota de Lewis a Osric Strang, en la tienda Inmunidad Limitada, en el Casco Antiguo de Ventormenta.", st = "A cambio de una pequeña tarifa puedes usar un grifo hasta Ventormenta, y llevarle a Osric la nota de Lewis. No encontrarás un modo más rápido para ir hasta allí.$B$BSi te parece aceptable, vuelve a hablar conmigo cuando estés $glisto:lista; para el viaje. Te cobraré algo pero, créeme, ¡merece la pena!", t = "Prosigue hasta Ventormenta"},
    [6282] = {ot = "Maggran Vinculador Terrestre, en el Refugio Roca del Sol, quiere que mates 7 arpías Furia Sangrienta, 7 emboscadoras Furia Sangrienta, 7 destripadoras Furia Sangrienta y 7 malaplumas Furia Sangrienta.", st = "Los tauren se enorgullecen de ser los protectores de estas tierras. Sin duda comprenderás que me preocupe la gran cantidad de arpías que viven aquí, en Espolón.$B$BLos Furia Sangrienta son la razón del aumento de las arpías en Kalimdor. Dan caza a toda forma de vida, impidiendo que los inocentes pasen de las fronteras.$B$B¡Necesito que acabes con las arpías, $n!", t = "La amenaza de las arpías"},
    [6283] = {ot = "Maggran, en el Refugio Roca del Sol, quiere que mates a la desgarradora Furia Sangrienta y le lleves sus restos como prueba de tu hazaña.", st = "Diezmar el número de arpías Furia Sangrienta no será suficiente. La única cura posible para su enfermedad, sería asesinar a su líder, desgarradora Furia Sangrienta.$B$BPara esas asquerosas criaturas, lo es todo menos su reina. Mátala y seguro que sus filas se reducen.$B$BVuelve a La Vega Carbonizada. La encontrarás allí, en las colinas del oeste. No será fácil acabar con ella, pero la recompensa merecerá la pena.", t = "El linaje Furia Sangrienta"},
    [6284] = {ot = "Mata a Besseleth y lleva el colmillo de Besseleth a Maggran en el Refugio Roca del Sol.", st = "Advertencia: Penetra en el Cañón Sishir al oeste de aquí por tu cuenta y riesgo.$B$BBesseleth y sus hijos del bosque de ocho patas, han reclamado este cañón como su guarida de telarañas.$B$BMaggran Vinculador terrestre en el Refugio Roca del Sol, ha puesto precio a la cabeza de Besseleth. Mátala y lleva una prueba de su muerte a Maggran. Recibirás una recompensa por poner fin a la amenaza de ocho patas.", t = "Aracnofobia"},
    [6285] = {ot = "Compra un vuelo en grifo hasta la Colina del Centinela al maestro de grifos Dungar Tragolargo y lleva el cajón de Osric a Lewis de la Colina del Centinela.", st = "El maestro de grifos de los Páramos de Poniente es Thor. Si ya has hablado con él puedes usar uno de los grifos para ir hasta allí.$B$BTe conviene saber algo: los grifos siempre están entrenados para volar a su capital pero solo te llevarán a otro maestro de grifos si ya has estado con él.$B$BYa has hablado con Thor, así que vuelve a hablar conmigo cuando estés $glisto:lista; para volar hasta los Páramos de Poniente. Cuando estés allí podrás entregar el Cajón de Osric al intendente Lewis.", t = "Regresa junto a Lewis"},
    [6301] = {ot = "Tammra Campo de Viento, en el Refugio Roca del Sol, quiere que le consigas 10 semillas de Gaia.", st = "La avaricia industrial y la guerra continua han destrozado las tierras de Espolón. Solo la bendición de la Madre Tierra podría curarlas.$B$B$n, necesito que busques una semilla especial, la semilla de Gaia. Solo es posible encontrarlas en Sierra Espolón, al norte del Refugio Roca del Sol en el Lago Mirkfallon, cerca de la orilla.$B$BCuando me traigas las semillas, las imbuiré de poder chamanístico para acelerar su crecimiento.", t = "El ciclo del renacimiento"},
    [6321] = {ot = "Lleva la orden de Podrig a Karos Razok.", st = "El ejecutor Hadrec me pidió que evaluara nuestro equipamiento en El Sepulcro. Con la Plaga y cosas mucho peores acechando en los bosques, no quiere que los Guardias de la Muerte estén escasos de equipos.$B$BEn general tenemos bastantes suministros, pero necesitamos más armas para reemplazar las que perdimos en el campo de batalla.$B$BAquí tienes el pedido de lo que se necesita para el vendedor de armas Gordon Wendham de Entrañas. Lleva el pedido al maestro de murciélagos Karos Razok y habla con él sobre el transporte a Entrañas.", t = "Suministros para el Sepulcro"},
    [6322] = {ot = "Lleva el cajón de Gordok a Michael Garrett.", st = "He guardado los suministros del Sepulcro en este cajón. Si ya has visitado el Sepulcro y has hablado con el maestro de murciélagos, entonces puedes volver en murciélago hasta su ubicación.$B$BHabla con el maestro de murciélagos de Entrañas, Michael Garrett. Puede proporcionarte un murciélago para ir al Sepulcro.", t = "Michael Garrett"},
    [6323] = {ot = "Compra un viaje en murciélago al maestro de murciélagos Karos Razok y lleva la orden de Podrig a Gordon Wendham en Entrañas.", st = "Uno de mis murciélagos puede llevarte a Entrañas, por una pequeña tarifa. Vuelve a verme cuando estés $glisto:lista; para organizar tu transporte.$B$BEncontrarás a Gordon Wendham en el Barrio del Comercio de Entrañas. Allí es donde aterrizará mi murciélago.", t = "Vuela a Entrañas"},
    [6324] = {ot = "Cómprale un viaje en murciélago hasta el Sepulcro al maestro de murciélagos Michael Garrett y lleva el cajón de Gordon al Guardia de la Muerte Podrig en el Sepulcro.", st = "El maestro de murciélagos en el Sepulcro es Karos Razok. Si ya has hablado con él, puedo ofrecerte un murciélago para que vueles hasta su ubicación.$B$BNuestros murciélagos siempre vuelan a Entrañas, pero para realizar viajes más largos, su jinete primero debe visitar la zona y hablar con el maestro de murciélagos.$B$BComo ya conociste a Karos en el Sepulcro, ahora puedes volar en murciélago hasta allí. Vuelve a hablar conmigo cuando estés $glisto:lista;.", t = "Regresa con Podrig"},
    [6341] = {ot = "Lleva la colección de Nessa a Vesprystus.", st = "A los pescadores de la Aldea Rut'theran les va muy bien, porque aquí los peces son grandes y abundantes. Me gustaría comparar las presas de aquí con las del continente.$B$BTengo una colección de huesos y escamas de peces que me gustaría llevarle a un colega mío en Costa Oscura. Se llama Laird, es un vendedor de peces en la aldea de Auberdine.$B$BLlévale mi colección a nuestro maestro de hipogrifos, Vesprystus, y habla con él para viajar a Auberdine.", t = "Las presas de Teldrassil"},
    [6342] = {ot = "Compra un vuelo en hipogrifo hasta Auberdine al maestro de hipogrifos Vesprystus y lleva la colección de Nessa a Laird.", st = "Desde Rut'theran, hay dos formas de viajar a Auberdine: en transbordador o en hipogrifo. Las dos son rápidas y confiables, pero si aún no has ido a Auberdine en hipogrifo, te sugiero que lo hagas.$B$BUn buen consejo general es hablar con el maestro de hipogrifos en todas las ciudades que tengan. Después de hablar con el maestro, puedes volar allí desde otras ciudades.$B$BAquí está la colección de Nessa. Ven a verme cuando estés $glisto:lista; para volar a Auberdine y entregar la colección de Nessa a Laird.", t = "Vuelo a Auberdine"},
    [6343] = {ot = "Lleva la respuesta de Laird a Nessa Cantosombrío.", st = "Debo enviar una respuesta a Nessa. Estará muy interesada en saber lo diferentes que son los peces de aquí comparados con los de la costa de Teldrassil. Solo es una hipótesis, pero creo que la diferencias se deben al Árbol del Mundo y sus efectos en la fauna local.$B$BPor favor, llévale esta respuesta a Nessa. Si quieres volver a Rut'theran en un hipogrifo, ve a ver al maestro de hipogrifos Caylais Plumalunar. Si quieres usar el transbordador, hay uno que sale regularmente del muelle en el noroeste.", t = "Regreso a Nessa"},
    [6344] = {ot = "Habla con Nessa Cantosombrío.", st = "Una amiga mía, Nessa Cantosombrío, es una mercader de peces de la Aldea Rut'theran. Necesita enviar un paquete a Costa Oscura, y está buscando ayuda.$B$BSi te interesa, usa el portal de Darnassus a la Aldea Rut'theran para hablar con Nessa. El portal está al oeste de los Jardines del Templo.", t = "Nessa Cantosombrío"},
    [6361] = {ot = "Llévale el fardo de pellejos al maestro de jinetes del viento Devrak en El Cruce.", st = "Tengo un fardo de pellejos de los animales de los Baldíos y debo enviarlos a Cima del Trueno. Un colega de allá, Ahanu, los usará para crear artículos de cuero.$B$B¿Podrías llevárselos por mí?$B$BLa forma más rápida de llegar a Cima del Trueno es montar un jinete del viento. Llévale el fardo de pellejos a Devrak, el maestro de jinetes del viento en El Cruce, y habla con él para conseguir transporte a Cima del Trueno.", t = "Un fardo de pellejos"},
    [6362] = {ot = "Cómprale un trayecto en jinete del viento hasta Cima del Trueno al maestro de jinetes del viento Devrak y llévale el fardo de pellejos a Ahanu en Cima del Trueno.", st = "Por una módica cantidad, te daré un jinete del viento a Cima del Trueno. ¡No verás un medio más rápido a la ciudad!$B$BSi te parece bien, vuelve para hablar conmigo cuando estés $glisto:lista; para salir.$B$BSi vas a llevar esos pellejos a Ahanu, me parece que se encuentra en La Armería de Hewa, en la base de la torre de los jinetes del viento de Cima del Trueno. ¡Y aterrizarás precisamente allí!", t = "Un viaje a Cima del Trueno"},
    [6363] = {ot = "Lleva los artículos de cuero de Ahanu a Tal en Cima del Trueno.", st = "He preparado unos artículos de cuero para que Jahan los venda en El Cruce. ¿Podrías llevárselos?$b$bSi ya has estado en El Cruce y has hablado con el maestro de jinetes del viento, entonces puedes volver a usar el mismo medio de transporte para volver allá.$b$bToma los artículos de cuero y ve a ver a Tal, el maestro de jinetes del viento de Cima del Trueno, y coméntale lo de organizar el transporte a El Cruce.", t = "Tal, maestro de jinetes del viento"},
    [6364] = {ot = "Cómprale un viaje en jinete del viento hasta El Cruce al maestro de jinetes del viento Tal y llévale los artículos de cuero de Ahanu a Jahan Ala Halcón.", st = "Para volar a una ciudad, tienes que haber estado allí antes y haber hablado con su maestro de jinetes del viento. Ya has estado en El Cruce y hablado con su maestro de jinetes del viento Devrak, así que por una módica cantidad puedes tomar un jinete del viento desde aquí para llegar.$B$BVuelve para hablar conmigo cuando estés $glisto:lista;. Cuando llegues a El Cruce, puedes entregarle los artículos de cuero a Jahan Ala Halcón.", t = "Regresa con Jahan"},
    [6365] = {ot = "Llévale la carne de Zargh a Devrak en El Cruce.", st = "Tengo unos cortes de carne especiales que desearía enviarle a una amiga. Su nombre es Gryshka, es la tabernera de Orgrimmar. ¿Podrías entregarle la carne de mi parte?$B$BLa forma más rápida de llegar a Orgrimmar es sobre un jinete del viento. Llévale la carne a Devrak, el maestro de jinetes del viento de El Cruce, y habla con él para conseguir transporte a Orgrimmar.", t = "Entrega de carne a Orgrimmar"},
    [6381] = {ot = "Planta 10 semillas de Gaia en los Túmulos y lleva las semillas de Gaia encantadas restantes a Tammra en el Refugio Roca del Sol.", st = "Como has visto, $c, aunque la tierra sufre, el ciclo de la vida es algo muy poderoso. Ahora debemos hacer algo para ayudar. Tienes que plantar las semillas en el centro de la destrucción, al oeste, en La Vega Carbonizada. Ten cuidado, la tierra sigue plagada de arpías y furiosos elementales de fuego.$B$B$n, lleva estas semillas de Gaia encantadas y plántalas en montones de tierra fértil. ¡El ciclo de la vida debe seguir adelante!", t = "Nueva vida"},
    [6382] = {ot = "Habla con Senani Corazón Atronador en Puesto del Hachazo, en Vallefresno.", st = "Tu fuerza es impresionante, $c. Tu determinación y dedicación a la caza me da la seguridad de que podrías pasar a algo más fuerte... a retos mayores.$B$BLos bosques de Vallefresno constituyen un vasto e indómito espacio natural sobre el que la Horda desea imponer su voluntad, tanto política como espiritual. Si quieres demostrar lo que vales en una tierra por descubrir, busca los consejos de Senani Corazón Atronador en el Puesto del Hachazo. La avanzada se encuentra al norte del camino procedente de Los Baldíos.", t = "La Caza de Vallefresno"},
    [6383] = {t = "La Caza de Vallefresno"},
    [6384] = {ot = "Cómprale un trayecto en jinete del viento hasta Orgrimmar al maestro de jinetes del viento Devrak y llévale la carne de Zargh a Gryshka en Orgrimmar.", st = "Por unas pocas monedas puedo conseguirte un jinete del viento que te lleve a Orgrimmar. Cuando llegues allí, puedes llevar la carne de Zargh a Gryshka. Su posada está en el Valle de la Fuerza, no muy lejos de la Torre Celestial, donde te dejará mi jinete del viento.$B$BVuelve a verme cuando estés $glisto:lista; para el viaje.", t = "Un viaje a Orgrimmar"},
    [6385] = {ot = "Llévale la carta de Gryshka a Doras en Orgrimmar.", st = "Le he escrito una carta de agradecimiento a Zargh. ¿Serías tan amable de entregársela? Si ya has estado en El Cruce y has hablado con su maestro de jinetes del viento, entonces puedes volver a usar ese medio de transporte.$B$BLlévale mi carta a Doras, el maestro de jinetes del viento de Orgrimmar, y coméntale lo del transporte a El Cruce.", t = "Doras, maestro de jinetes del viento"},
    [6386] = {ot = "Cómprale un trayecto en jinete del viento hasta El Cruce al maestro de jinetes del viento Doras y llévale la carta de Gryshka a Zargh en El Cruce.", st = "Mis jinetes del viento están entrenados para volar a muchos lugares diferentes, siempre que ya hayas estado en ese lugar y hayas hablado con su maestro de jinetes del viento.$b$bYa has estado en El Cruce y has hablado con el maestro de jinetes del viento Devrak, así que puedes volar directamente hasta allí desde aquí. Cuando llegues a El Cruce, podrás entregarle la carta de Gryshka a Zargh.$b$bHabla conmigo cuando estés $glisto:lista; para salir.", t = "Regreso a El Cruce"},
    [6387] = {ot = "Llévale la lista de Brocks a Thorgrum Borrelson en Thelsamar.", st = "Vienen a verme muchos enanos deseosos de aprender el arte de la minería. ¡Y el objeto más preciado para un minero es un pico!$B$BTengo una lista de estudiantes de minería que han ganado un pico honorario por sus buenas notas. Entrégasela a Golnir Dedorroca, en Forjaz. Él preparará los picos.$B$BLo más rápido es ir en grifo, así que llévale la lista al maestro de grifos, Thorgrum Borrelson, para que organice el transporte a Forjaz.", t = "Estudiantes de honor"},
    [6388] = {ot = "Lleva los picos honorarios a Gryth Thurden en Forjaz.", st = "Aquí están los picos honorarios para los estudiantes de Brock. Si ya has estado en Thelsamar, lo mejor es que vuelvas en grifo.$B$BLlévale los picos a nuestro maestro de grifos, Gryth Thurden, y habla con él sobre el regreso a Thelsamar.", t = "Gryth Thurden"},
    [6391] = {ot = "Contrata un vuelo en grifo a Forjaz con el maestro de grifos Thorgrum Borrelson y llévale la lista de Brock a Golnir Dedorroca, en Forjaz.", st = "Uno de mis grifos te llevará a Forjaz por unas monedas. Dale la lista de Brock a Golnir Dedorroca. Estará en el Gremio de minería de Montañahonda. Eso está en el distrito de La Gran Fundición en Forjaz; el grifo te dejará justo ahí.$B$BVen a verme cuando quieras partir.", t = "Vuela a Forjaz"},
    [6392] = {ot = "Contrata un vuelo en grifo a Thelsamar con el maestro de grifos Gryth Thurden para llevarle los picos honorarios a Brock Buscapiedras en Thelsamar.", st = "Puedes ir a Thelsamar en grifo por poco dinero, pero solo si ya has estado allí. Los grifos solo van a lugares en los que ya has estado, así que recuerda hablar con los maestros de grifos de todos los sitios a los que vayas para poder volver más adelante.$B$BComo ya has hablado con Thorgrum, el maestro de grifos de Thelsamar, podrás regresar. Cuando llegues a Thelsamar, llévale los picos a Brock Buscapiedras.$B$BVen a verme cuando estés $Glisto:lista; para partir.", t = "Regresa con Brock"},
    [6393] = {ot = "Lleva 10 incendritas a Tsunaman en el Refugio Roca del Sol.", st = "El Tribunal de las Mareas me ha enviado a declarar la guerra a los elementales de fuego que habitan aquí, en Sierra Espolón. Neptulon el Cazamareas, Señor de todos los elementales de agua, tiene un interés personal en extinguir a nuestros feroces parientes.$B$B$n, puedes ayudarme a conseguir el favor del Tribunal destruyendo a los elementales de fuego de La Vega Carbonizada. Al ser destruidos, los elementos de fuego dejan incendritas. Tráemelas y recibirás una recompensa.", t = "Guerra elemental"},
    [6394] = {ot = "Lleva el pico de Thazz'ril al supervisor Thazz'ril.", st = "$n, eres $gun:una:r; $r de confianza. ¿Puedo contar contigo para otra tarea?$B$BHace algún tiempo estaba inspeccionando la cueva del Norte en busca de minerales y olvidé allí mi pico favorito. ¡Pero cuando volví a recuperarlo descubrí que la cueva estaba plagada de despiadadas criaturas! ¿Irás a la cueva, el Aquelarre del Filo Ardiente, para recuperar mi pico?$B$BLo dejé en una caverna con cascadas. El pico tiene un hechizo que te permitirá verlo en la oscuridad, así que no tienes que preocuparte mucho por encontrarlo... ¡solo por lo que lo esté custodiando!", t = "Pico de Thazz'ril"},
    [6395] = {ot = "Lleva los restos de Samuel Fipps a la tumba de Marla y luego vuelve con la novicia Elreth.", st = "Mi amiga Marla Fipps vivía con su marido Samuel. Cuando llegó la plaga, Samuel sucumbió a ella y se unió a las filas de la Plaga.$B$BMarla escapó a la no-muerte, solo para morir a manos de su enajenado marido. Pero su amor era tan fuerte que su último deseo fue ser enterrada con su amado Samuel.$B$BAhora Samuel Fipps vaga por un campamento en ruinas que se encuentra en un camino al noreste de Camposanto. Acaba con él. Haz realidad el deseo de Marla. Entiérralo con ella, en la primera fila de nuestro cementerio.", t = "El último deseo de Marla"},
    [6401] = {ot = "Da las buenas noticias a Tammra Campo de Viento en el Refugio Roca del Sol.|n", st = "Vete a dar las buenas noticias a Tammra Campo de Viento, la tía de Kaya. Está en el Refugio Roca del Sol. ¡Kaya está viva! Pensábamos que la habíamos perdido tras el brutal ataque a nuestra aldea. Sigue el camino hacia el oeste para llegar al Refugio Roca del Sol.|n|n", t = "Kaya está viva"},
    [6421] = {ot = "Explora las profundidades de la cueva del Barranco del Alud y lleva 10 cristales de resonita al Refugio Roca del Sol para que Mor'rogal las estudie.", st = "Aquí en el Espolón pasa algo. ¿Sientes la tensión en el aire, $n?$B$BAl sureste de aquí existe una profunda caverna en el Barranco del Alud. Los kóbolds de allí están extrayendo un extraño mineral llamado resonita. Necesito que me traigas algunas muestras para poder entender lo que sucede allí. También necesito que investigues las profundidades de la cueva.$B$BVe allí, joven $c. Tenemos que saber lo que se oculta bajo esas montañas.", t = "Barranco del Alud"},
    [6441] = {ot = "Reúne 16 cuernos de sátiro para Pixie en el Puesto del Hachazo.", st = "¡Eh! He estado viajando por Vallefresno, camino de Trinquete, y decidí hacer un alto aquí en el Hachazo. Siempre estoy en busca de una oportunidad y, al parecer, los cuernos de sátiro están muy demandados en Trinquete en estos tiempos.$B$BDespués de preguntar por aquí, parece que los sátiros de la Senda de la Noche, Satyrnaar y Xavian tienen todos el tipo de cuernos que ando buscando. No puedo medirme a esos sátiros... ¡pero tú sí que pareces dar la talla!$B$BOye, ¿por qué no consigues los cuernos para mí y te compenso debidamente por tu tiempo?", t = "Los cuernos de sátiro"},
    [6442] = {ot = "Llévale 20 cabezas de Colafuria a Marukai en La Ensenada de Zoram.", st = "El mal nos acecha desde la costa, $r.$B$BEs el lugar de descanso de la ciudad maldita de Zoram, destruida hace mucho tiempo y desde entonces sumergida bajo los mares. Perdida y casi olvidada.$B$BAhora, los nagas han regresado y en cuanto a sus motivos... los ignoramos. Pero el porqué importa poco; debemos defender la tierra en la que hemos trabajado con tanto ahínco para reclamarla.$B$B¡Vuelve a mí con 20 de sus cabezas! ¡Manda a los nagas de vuelta a los abismos!", t = "Nagas en la Ensenada de Zoram"},
    [6461] = {ot = "Xen'zilla, en Malaka'Jin, necesita que mates a 10 trepadores Musgondo y a 7 escupevenenos Musgondo.", st = "Los trols de Malaka'Jin hemos prosperado gracias a la tierra. Sierra Espolón nos proporciona un gran terreno de caza para poder conseguir comida.$B$BÚltimamente hemos atraído a los visitantes inadecuados... Las arañas de estas montañas han estado asaltando nuestros campamentos por las noches, para robar nuestra caza.$B$BSi quisieras ayudarnos a matar a esas espantosas bestias, Malaka'Jin estaría en deuda contigo. En Espolón hay arañas por todas partes. Dirígete hacia el norte y verás lo que estoy diciendo.", t = "Chupasangres"},
    [6462] = {ot = "Llévale 8 talismanes trols a Mitsuwa en la Avanzada de Zoram'gar.", st = "Los de mi especie estaban viajando hacia aquí con muchos talismanes trols sagrados, ¡pero los fúrbolgs Piel de Cardo los atacaron y los mataron antes de que pudieran llegar a Zoram'gar! ¡Esos malvados fúrbolgs!$B$BExtraño a mis hermanos y hermanas que fueron masacrados, pero nos volveremos a encontrar en la otra vida. Sin embargo, sus talismanes trols tienen un gran valor en este mundo. ¡Es un ultraje que estén en manos de los fúrbolgs!$B$B$n, ¡debes recuperar los talismanes! Están en baúles en el Bastión Piel de Cardo, una cueva al final del Poblado Piel de Cardo, al norte de Astranaar.", t = "El talismán trol"},
    [6481] = {ot = "Abre el barril de resonita con el cristal de resonita encantado y, a continuación, mata a Goggeroc. Vuelve a ver a Mor'rogal para contarle lo ocurrido y entregarle el cristal de resonita encantado.", st = "Has descubierto una oscura amenaza para la tierra, $c. El barril de resonita que has encontrado en esa cueva, contiene a un terráneo dormido llamado Goggeroc.$B$BHe cambiado la mezcla de los cristales de resonita que encontraste con mis poderes chamanísticos. Coge el cristal de resonita encantado y abre el barril de resonita que contiene al terráneo.$B$BAl despertarse, Goggeroc estará debilitado... ¡Mátale, $n!", t = "El despertar del terráneo"},
    [6482] = {ot = "Escolta a Ruul y después habla con Yama Pezuña Nevada en el Puesto del Hachazo.", st = "¿Qué? ¿Quién eres?$B$B¿$n? No eres $gun:una; fúrbolg. ¡Están malditos! Pensaba, que era un oso y me capturaron ¡y ahora me matan de hambre! Las fuerzas me fallan...$B$BAyúdame a escapar y después habla con mi hermana Yama en el Puesto del Hachazo hacia el este.$B$B¡$n! ¡Debo escapar!", t = "Liberar a Ruul"},
    [6503] = {ot = "Mata a 9 avanzadas de Vallefresno y regresa con Kuray'bin en Puesto del Hachazo.", st = "Recibimos informes de que las avanzadas de Vallefresno abandonaron la Avanzada Ala de Plata hace poco, y ahora se infiltran entre nuestros territorios del bosque. ¡No podemos permitir que obtengan información de nuestras defensas!$B$BAdéntrate en los bosques al sur de nuestra posición y al este de la avanzada de la Alianza Ala de Plata. Busca a las avanzadas, mátalas y vuelve a verme.", t = "Avanzada de Vallefresno"},
    [6522] = {ot = "Lleva el pergamino pequeño a Varimathras en Entrañas.", st = "Estimada señora:$b$bComo muy bien sabe, le estamos ofreciendo la gran oportunidad de tomar Los Baldíos y tierras circundantes. A cambio, solo pedimos ayuda, y con ello nos referimos a la libertad de acción.$b$bRogamos que lo considere. Tenemos mucho poder y deseamos compartirlo con nuestros aliados. De momento me mantendré alejado de Zahúrda Rajacieno.$b$bSaludos.$BEmbajador Malcin", t = "Una alianza impía"},
    [6523] = {ot = "Escolta a Kaya Pezuña Plana hasta el Campamento Aparaje y ve a ver a Makaba Pezuña Plana cerca del límite sureste de Espolón.|n", st = "¡Gracias por rescatarme! Debemos irnos rápidamente antes de que descubran que soy libre. Por favor, escóltame hasta el Campamento Aparaje. Desde ahí, ya sé cómo seguir.$B$BMi padre, Makaba Pezuña Plana, estará muy preocupado hasta que llegue sana y salva.", t = "Protege a Kaya"},
    [6541] = {ot = "Preséntate ante Kadrak en la torre de vigilancia en Los Baldíos del Norte.", st = "¿Alguna vez has estado en Vallefresno, hacia el norte? La Horda ha montado recientemente una avanzada en La Ensenada de Zoram y siempre nos viene bien incorporar nuevos reclutas para defender los nuevos frentes.$B$BSi crees que te puede interesar, ve a ver a Kadrak en Los Baldíos del Norte, está en la torre de vigilancia. Se dirige a la campaña de Vallefresno y te dará más detalles.", t = "Preséntate ante Kadrak"},
    [6543] = {ot = "Abre el fardo de informes. Lleva los informes Grito de Guerra al explorador Grito de Guerra, al corredor Grito de Guerra y al escolta Grito de Guerra. Preséntate ante Kadrak en la torre de vigilancia norte en los Baldíos con la información que te hayan dado.", st = "Hace poco envié a unos exploradores a Vallefresno y necesito un mensajero para llevarles órdenes y traer los informes de lo que hayan observado.$B$BTu primera parada sería la Avanzada de Zoram'gar, en la costa oeste, en La Ensenada de Zoram, para encontrar al primer mensajero. También tendrás que detenerte en el Puesto del Hachazo, hacia el norte, y por la carretera que va hacia el este, cerca de Azshara. Allí encontrarás un explorador y un mensajero.$B$BDales a cada uno un informe y que ellos te den sus últimas pesquisas.", t = "Los informes Grito de Guerra"},
    [6544] = {ot = "Escolta a Torek en su ataque sobre la Avanzada Ala de Plata contra Duriel Fuegolunar e informa después a Ertog Colmillorrabioso en el Puesto del Hachazo.", st = "¡Eh! ¡$C! ¡Ven aquí!$B$BMis asaltantes y yo estamos a punto de atacar la Avanzada Ala de Plata hacia el oeste. Nuestro objetivo es su líder, Duriel Fuegolunar. Según los informes de los exploradores, la avanzada está fuertemente defendida por centinelas y guerreros. ¡La batalla será gloriosa!$B$B¿Quieres ser parte de esta gloria, $n, y ayudarnos? Si así lo deseas, cuando todo acabe, puedes informar de nuestro éxito a mi superior, Ertog Colmillorrabioso en el Hachazo.$B$B¿Qué me dices? ¿Podemos contar contigo?", t = "El asalto de Torek"},
    [6548] = {ot = "Mata a 8 rufianes Tótem Siniestro y a 6 mercenarios Tótem Siniestro. A continuación, ve a ver a Makaba Pezuña Plana cerca del límite sureste de Espolón.|n", st = "El clan Tótem Siniestro asaltó mi aldea y mató a casi todo el mundo. Yo maté a todos los que pude, pero conseguí escapar por los pelos.$B$B$n, solo deseo más muertes en sus filas. Los encontrarás justo al oeste de aquí.|n|n", t = "Venga mi aldea"},
    [6561] = {ot = "Llévale la cabeza del señor crepuscular Kelris a Bashana Tótem de Runa en Cima del Trueno.", st = "Las fuerzas me han abandonado. ¡Necesito tu ayuda!$B$BOtrora este lugar era un gran templo de Elune. Pero la desgracia lo ha llevado a la ruina cuando la corrupción de un dios antiguo empezó a calar desde el subsuelo y contaminó la sagrada Poza de la Luna.$B$BAku'Mai, sirviente del dios antiguo, surgió de las aguas.$B$BLos adeptos del Martillo Crepuscular se han unido a los nagas para ocupar esas tierras. Esos adeptos, cuyo jefe es Kelris, sacrifican a inocentes a Aku'Mai a cambio de poder.$B$BMata a Kelris y llévale su cabeza a Bashana en Cima del Trueno, $n, te lo ruego.", t = "La vileza de Brazanegra"},
    [6562] = {ot = "Habla con Je'neu Sancrea en Vallefresno.", st = "Je'neu Sancrea necesita ayuda. Está en la Avanzada de Zoram'gar de Vallefresno. El bosque de los elfos de la noche se encuentra al norte de la Sierra Espolón. Puedes atravesar Risco Cortaviento o ir hacia el norte desde Los Baldíos para llegar. La Ensenada de Zoram está al oeste del bosque. Ten cuidado, $n. Allí hay fuerzas a las que no les agradará tu presencia.", t = "Problemas en las profundidades"},
    [6563] = {ot = "Llévale 20 zafiros de Aku'Mai a Je'neu Sancrea en Vallefresno.", st = "Al principio de los túneles de las Cavernas de Brazanegra, se pueden encontrar grandes bloques de zafiros en las paredes de las cuevas. Recientemente se observó que los nagas estaban reuniendo los cristales. Hasta que se aclare el porqué, presiento que deberíamos impedírselo. Los cristales tienen un gran poder elemental y si este no se usa apropiadamente, podría producir un poderoso componente arcano.$B$B¿Me ayudarás, $n? Las Cavernas de Brazanegra bordean La Ensenada de Zoram al norte de nuestra avanzada.", t = "La esencia de Aku'Mai"},
    [6564] = {ot = "Llévale la nota mojada a Je'neu Sancrea en Vallefresno.", st = "Hay unas líneas con mala caligrafía garabateadas en la arrugada nota:$B$B\"Sí, díganles a todas las sacerdotisas que me traigan los cristales. Los espíritus elementales de agua son fuertes en su interior y ayudarán a nuestros acuamánticos en sus conjuros.$B$BSi controlamos el poder de los cristales, apaciguaremos a Aku'Mai. Algún día tendremos suficiente poder para devolvernos a Aku'Mai ¡y el mundo conocerá una vuelta a su era más grandiosa! ¡Una era de reinado de los dioses antiguos!\"", t = "Lealtad a los dioses antiguos"},
    [6565] = {ot = "Mata a Lorgus Jett en las Cavernas de Brazanegra y vuelve con Je'neu Sancrea en Vallefresno.", st = "No podemos permitir que este seguidor del Martillo Crepuscular lleve a cabo su plan. El Martillo Crepuscular no comprende los espíritus de la naturaleza. Creen en los dioses antiguos... criaturas de caos y destrucción que cayeron derrotadas hace mucho. No podemos dejar triunfar a este Lorgus. Tienes que detenerlo, $n. Yo no puedo... estoy muy débil.$B$BVe a las Cavernas de Brazanegra, búscalo y mátalo. Vuelve a verme aquí en Zoram'gar cuando termines.", t = "Lealtad a los dioses antiguos"},
    [6607] = {t = "Nat Pagle, pescador extremo"},
    [6629] = {ot = "Mata a Grundig Nube Negra y a 6 toscos Tótem Siniestro. A continuación, ve a ver a Makaba Pezuña Plana cerca del límite sureste de Espolón.|n", st = "$n, has hecho un buen trabajo matando a esos Tótem Siniestro. Si te atreves, Grundig Nube Negra y su banda personal de toscos son, con diferencia, los peores de todos. Él fue quien lideró el ataque contra mi aldea.$B$BLe encontrarás en el Poblado Tótem Siniestro, un poco más adelante del camino, hacia el oeste. Mátale y te lo agradeceré eternamente.|n", t = "Mata a Grundig Nube Negra"},
    [6641] = {ot = "Mantén a Muglash a salvo mientras viaja hacia el blandón. Apaga el blandón para ayudarlo y luego lucha contra los nagas para protegerlo.$B$BSi tienes éxito, regresa a Avanzada de Zoram'gar e informa al corredor Grito de Guerra sobre la muerte de Vorsha la Azotadora.", st = "Vorsha la Azotadora... la monstruosa hidra que recorre los mares...$B$BHa atacado nuestra avanzada, sin que nadie la provoque, arrasando allá por donde pasa.$B$BPero estoy listo, $n. Me he preparado para vencer a la hidra y poner fin a estos ataques sobre Zoram'gar.$B$BLos nagas honran la malvada naturaleza de este monstruo con un blandón que permanece encendido en una isla a escasa distancia de la costa. Creo que si lo apagamos, provocaremos la ira de Vorsha y aparecerá.$B$BNecesitaremos ayuda, así que asegúrate de traer aliados fuertes contigo.", t = "Vorsha la Azotadora"},
    [6661] = {ot = "Utiliza la flauta cazarratas para capturar 5 ratas del subterráneo. Guía a las ratas hasta Monty. No olvides devolver la flauta cuando termines.", st = "Alto ahí, pillastre. Eeeh... ¿Eeestás buscando curro? Nos tenemos un problemón de ratas aquí abajo y nos faltan manos en la cubierta de popa.$B$B¿Qué respondes? Solo tienes que tomar esta flauta atrapa-ratas y tocar la canción alrededor de esas alimañas. ¡Te seguirán al fin del mundo!$B$BCaptúranos cinco de esos bichos y tráenoslos acá. Nos los queremos vivos.$B$BEeeh...", t = "A por las ratas del tranvía subterráneo"},
    [6662] = {ot = "Lleva el envase de carne misteriosa a Niblis, que está en el Depósito del Tranvía Subterráneo de Ventormenta.", st = "Mi hermano Niblis dirige una operación de kebab de rata al otro lado de la estación de Ventormenta. Tú le llevas este envase de carne misteriosa a él, antes de que se estropeen. ¡Venga, en marcha, tú!$B$BHas viajado antes en tren, ¿no? Es fácil. Cuando llega, te subes a bordo y disfrutas del trayecto. Eso sí, brazos y piernas dentro durante el viaje, si no quieres lisiarte de por vida.", t = "Mi hermano Niblis"},
    [6921] = {ot = "Llévale el núcleo de las profundidades a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.", st = "El Martillo Crepuscular se ha trasladado a las Ruinas del Santuario Lunar de las Cavernas de Brazanegra. Su presencia solo puede servir para forzar a los elementos a actuar contra nosotros. Si no hacemos nada, esta región caerá en sus manos definitivamente.$b$b$n, dirígete a Brazanegra y encuentra la piedra de las profundidades en las ruinas; debería estar cerca, en el agua. En su interior hay un núcleo de las profundidades, un dispositivo que cuando se lee correctamente, revela la historia de toda actividad elemental. Si lo consigo, y con la ayuda de los miembros del Anillo de la Tierra, ¡quizás podamos detenerlos!", t = "Entre ruinas"},
    [6922] = {ot = "Llévale el extraño globo de agua a Je'neu Sancrea de la Avanzada de Zoram'gar, Vallefresno.", st = "El elemental de agua derrotado ha dejado tras de sí un extraño globo de agua. Supones que el objeto de alguna forma alimentó la energía de la bestia. En el interior del globo chapotea masa líquida repulsiva. El propio globo parece impermeable a todo tipo de fuerza física.$B$BSi alguien es capaz de interpretar este artilugio, es Je'neu Sancrea del Anillo de la Tierra. Se encuentra en la Avanzada de Zoram'gar de la Horda en Vallefresno.", t = "Barón Aquanis"},
    [6981] = {ot = "Viaja a Trinquete y busca a alguien que pueda decirte algo más sobre el fragmento resplandeciente.$B$BEntrega el fragmento como se te indique.", st = "El fragmento es verde y brillante y, aunque sólido, parece que hubiera humo arremolinándose bajo su superficie. No se puede evitar perder la mirada en las profundidades del cristal y, al mismo tiempo, uno sabe que hay algo muy desconcertante.$B$BQuizás deberías ir a ver si alguien de Trinquete puede decirte algo más sobre este extraño fragmento.", t = "El fragmento resplandeciente"},
    [7383] = {ot = "Llena la ampolla de amatista y devuélvesela a Corithras Furia Lunar en Dolanaar.", st = "Sin embargo, no todo iba bien en Teldrassil. Corzocelada lo había planeado todo meticulosamente ya que el Árbol del Mundo había brotado según lo previsto, pero ocurrió un pequeño desajuste, desajuste al que se pueden atribuir muchos de los conflictos de Teldrassil.$b$bPero no entraré en detalles por ahora. Debes ir a la última Poza de la Luna, al noroeste de El Claro del Oráculo. Debajo de las ramas del Árbol del Oráculo se encuentra la primera y más poderosa de nuestras pozas. Llena una ampolla con agua de esta poza y tráemela.", t = "La corona de la Tierra"},
    [65601] = {ot = "Habla con Magar en Orgrimmar.", st = "Los sayaad machos son conocidos como íncubos. Son criaturas de mente particular e inmensa maldad.\n\nPara atraer al demonio a nuestro mundo, se necesita un objeto que lo tiente... un objeto que represente el amor y la devoción.\n\nSi confías en que un hombre ciego te guíe, $n, escucha. Al este del Circo de las Sombras, por la calle principal de Orgrimmar, vive Magar. Ansía el regreso de su compañero, Krilge.\n\nVe a buscarlo. Te pedirá que busques algo preciado. Eso es lo que debes llevarle a Gan'rul.", t = "El amor duele"},
    [65602] = {t = "¿Qué es el amor?"},
    [65603] = {ot = "Usa la figurilla de madera para invocar y someter a un íncubo. Después, llévasela de regreso a Gakin el Presotenebra en El Cordero Degollado.", st = "Llegó la hora. Toma la figurilla y baja a las criptas. Hay un círculo de invocación preparado, debes colocar la figurilla en el centro.\n\nEso abrirá el portal para que el íncubo cruce a nuestro mundo.\n\nNo hay que subestimar a un sayaad. El demonio no dudará en atacar cuando se dé cuenta de lo que planeas. Necesitarás de todos tus recursos para derrotarlo.\n\nSi triunfas, vuelve a verme y someteré a la criatura a tu voluntad. Si fallas, no habrá salvación para tu alma.", t = "El vínculo"},
    [65604] = {ot = "Usa la bufanda desgastada para invocar y someter a un íncubo. Después devuelve la bufanda desgastada a Gan'rul Ojosangre en Orgrimmar.", st = "Sí... ya veo. Siento las emociones residuales impregnadas en estos hilos. El amor se ha tejido en su entramado. El íncubo no podrá resistirse.\n\nLleva esto al círculo de invocación de la carpa de Neeru, $n. Invoca a un íncubo malévolo y demuéstrale lo que puedes hacer. No creas que se someterá fácilmente. Ten tus hechizos listos y prepárate para una batalla. Subestimar a un demonio fue el último error que cometieron muchos brujos.\n\nCuando lo hayas derrotado, tráeme el tejido. Le diré a Magar lo que encontraste.", t = "El vínculo"},
    [65610] = {ot = "Explora el Lago Cielo Estrellado en Vallefresno e informa lo que encontraste a Gan'rul Ojosangre en Orgrimmar.", st = "Conocí a Krilge fabricando tela lunar en Vallefresno. Estaba ahí para proteger a los civiles del peligro, hasta que despareció...\n\nDejaron de buscarlo y lo consideraron desertor, pero yo no creo eso.\n\nTeníamos la costumbre de encontrarnos en el Lago Cielo Estrellado antes de que lo invadieran esas bestias de ciénaga agresivas.\n\nNo suelo pedir favores, pero si pudieras ir a Vallefresno y buscar algún rastro suyo, te lo agradecería.", t = "Ojalá estuvieras aquí"},
    [76156] = {ot = "Infíltrate en la mina de Ventura y Cía al sudeste de Cima del Trueno y recoge 5 cargas mineras de seforio de los carros con suministros explosivos, y regresa con Boarton Totemsombrío en Cima del Trueno.", st = "Siento que tienes un talento oculto para las artes del subterfugio, $c. Usa esta máscara para infiltrarte en la mina de Ventura y Cía cercana y roba sus suministros. Puede que no parezca un disfraz convincente, pero un pícaro hábil puede pasar inadvertido ante cualquier guardia solo con una sonrisa encantadora y una distracción astuta. Creo que tú también posees esa habilidad.", t = "Acechanzas con la Madre Tierra"},
    [76160] = {ot = "Recoge 8 piñas Viento Furioso al norte de Cima del Trueno, úsalas con el mortero y el majadero, y luego vuelve a ver a Boarton Totemsombrío a Cima del Trueno con el resultado.", st = "Puede que tu talento sea para los venenos, no los disfraces. Las arpías del norte anidan en un árbol que produce una resina de gran toxicidad. Recoge las piñas caídas cerca de los nidos y aplástalas para crear una pasta. Cuando se aplica a una cuchilla, este ungüento abrasa las heridas de tus oponentes y convierte su sangre en sal.", t = "Acechanzas con la Madre Tierra"},
    [76240] = {ot = "Compra o atrapa un pececito luminoso crudo y usa un conjunto de cuchillos para filetearlo frente a Boarton Totemsombrío en Cima del Trueno.", st = "Tengo una última idea que podría llevarnos al éxito. Aún siento que posees un talento oculto, pero tratemos de despertarlo con un enfoque menos directo.\n\nVe a buscar un pececito luminoso crudo y tráelo aquí. Usa estas dagas para limpiarlo y filetearlo. No lo pienses demasiado. Simplemente haz lo que te salga naturalmente.", t = "Acechanzas con la Madre Tierra"},
    [79008] = {t = "... y la nota que encontraste"},
    [79360] = {ot = "Derrota a Chargla Filonavaja en Horado Rajacieno y consigue información acerca de los planes de los jabaespines.", st = "Ahora que dominas los elementos, tienes una obligación con ellos y con toda Azeroth. Los llamamos para que nos asistan, pero no exigimos su poder. Es hora de que les regreses el favor. Y creo que sé cómo puedes hacerlo.\n\nLos jabaespines retuercen los elementos con fines egoístas y parecen estar expandiéndose por estas tierras. Ve a su horado y dale fin a sus planes. Hay que proteger estas tierras.", t = "Ayuda elemental"},
    [79364] = {ot = "Habla con Prate Vidente de las Nubes en Las Mil Agujas.", st = "La nota que encontraste dice que los Crines de Acero se han enterrado en las Mil Agujas para realizar algún ritual oculto. Tormentas iracundas y olas crecientes...\n\nLos jabaespines deben estar usando una brujería cruel que aprendieron de Hirzek, un chamán que dedicó su vida a retorcer los elementos. Si planean inundar el cañón, haría falta un poder elemental devastador.\n\nNo estamos preparados para lidiar con esto, pero $gun:una; chamán $gpoderoso:poderosa; como tú debe tener una idea. Regresa con tus aliados e intenta encontrar una respuesta.", t = "Vigilando los cielos"},
    [86574] = {ot = "Reúne $1oa suministros del Espolón de Dracoleón Alaorgullo y llévalos a la tabernera Faralia.", st = "<El desdichado cuerpo muestra las cicatrices de los innumerables ataques de los Dracoleones Alaorgullo. A su lado yace un paquete arrugado y abandonado, vacío, salvo por una nota en la mano del mensajero que revela lo perdido: un cargamento para la tabernera Faralia en Cima del Espolón.>\n\n<Es probable que los dracoleones se hayan llevado los paquetes de suministros para revestir sus nidos.>", t = "Búsqueda de suministros del Espolón"},
    [86576] = {ot = "Lleva $1oa piedrasoles relumbrantes a Mor'rogal.", st = "Las arpías Furia Sangrienta no solo esparcen su corrupción en la Vega Carbonizada, sino que también se llevan todo lo que brille. Se dice que recogen piedrasoles doradas para adornar sus nidos. No tengo interés en tales objetos, pero Mor'rogal las ha usado en el pasado.\n\nMientras luchas contra las arpías de La Vega, no pierdas de vista a las piedrasoles relumbrantes. Dirígete a las colinas que se alzan sobre nosotros y entrégale a Mor'rogal todo lo que encuentres.", t = "Abalorios Furia Sangrienta"},
    [86585] = {ot = "Levanta el estandarte de Forjaz, llama la atención del trogg partecabezas y acaba con él. Luego, preséntate ante el Capitán Rugelfuss.", st = "La montaraz caída lleva un estandarte de Forjaz. Quizás estaba explorando o lanzando una carga condenada a la derrota. En cualquier caso, han derribado y pisoteado el estandarte. Le han pegado tan fuerte a la montaraz en la cabeza que le quitaron el yelmo. Y murió a manos de un trogg, seguro con un garrote con pinchos.\n\nProbablemente, el trogg que la mató siga por la zona y, tal vez, recuerde el estandarte. Si levantas el estandarte de Forjaz otra vez, puede que llames su atención.", t = "Estandarte de los Caídos"},
    [86613] = {ot = "Devuélvele $1oa herramientas de excavación a Magmar Ceñimal.", st = "Las herramientas de excavación, que quedaron olvidadas cuando los enanos huyeron de los troggs, están casi en perfecto estado. Si se las devuelves a los excavadores, de seguro los ayudarás con su trabajo.", t = "Herramientas de excavación"},
    [86614] = {ot = "Devuelve la horquilla de plata con monogramas a quien le corresponda.", st = "<Entre las cosas de pesca en los restos hay anzuelos oxidados, carretes de sedal rotos y una horquilla de plata adornada pero un poco corroída, donde se lee el monograma \"K.A.\">", t = "Olas de plata"},
    [86667] = {ot = "Entrégale un tarro de nieve a Norric Lagolord.", st = "Mi mentor anterior, Norric, envió a un elemental menor con un pedido extraño. ¡Necesita un tarro de nieve para algunos de sus trabajos chamánicos! No tengo idea de lo que tendrá en mente, pero hace mucho tiempo aprendí a no cuestionar sus métodos en lo que respecta a la magia.\n\nAhora toda mi atención está dedicada a instalarme y aprender sobre los elementales locales, así que no puedo ir a ayudarlo. ¿Podrías tomar mi lugar? Ve al Paso de la Puerta Sur, allí hay nieve todo el año. Guarda un poco en este tarro de cerámica y llévaselo antes de que se derrita.", t = "Bajo nieve"},
    [86758] = {ot = "Encuentra y derrota al crocolisco Dagacolmillo y devuélvele el cuchillo a Marek.", st = "¿Alguna vez te conté cuando un crocolisco casi me arranca la mano? Logré clavarle mi cuchillo en su mandíbula y huir como alma que lleva el diablo. Pensé que ese cuchillo estaba por aquí, pero no lo encuentro por ningún lado.\n\nEn fin, ese crocolisco probablemente siga cazando a la vera del lago. Es posible que haya que despachar a esa bestia horrenda, aunque sea por la seguridad de los otros cazadores.\n\nPor costumbre, lo llamo Dagacolmillo. Si lo ves, ¡salúdalo de mi parte! Y por \"saludar\" me refiero a \"apuñalar\".", t = "Un cuchillo (y no por la espalda)"},
    [86784] = {ot = "Reúne $1oa ramas secas y llévaselas a Eleanor Shackleton.", st = "Mi socia Eleanor Shackleton se enorgullece de recorrer las tierras salvajes y de enfrentarse a las tormentas y los monstruos. En este momento, está acampando en las colinas del oeste, y jamás olvido su consejo: \"Cuando pienses que ya tienes suficiente leña, reúne cinco veces más\".\n\nSi tienes un momento libre, recoge leña en esta cesta y llévala a su campamento. Ella podrá darte valiosos consejos sobre la vida de los aventureros que viajan por tierras indómitas.", t = "Leños y huesos"},
    [87288] = {ot = "Lleva $1oa pelambres de sable de la noche suave a Aldria.", st = "¡Hola, $gviajero:viajera;! Espero que disfrutes de tu visita a nuestro pueblo. Me gusta Dolanaar porque es pequeño y rústico, y todos son amables.\n\nSoy un comerciante local y traigo todo tipo de herramientas y baratijas que podrían serte útiles en tus viajes. De hecho, si te interesa hacer un intercambio, necesito algunos pelambres de sable de la noche. Aunque estas majestuosas criaturas son hermosas, las de por aquí son bastante agresivas, así que defiéndete sin remordimiento.", t = "Pelambres de sable suave"},
    [87760] = {ot = "Encuentra a una dama de bestias Escama Tormentosa, mátala y regresa con su vara de dominio profundo.", st = "¡Me llegaron noticias de Darnassus, $n!\n\nA partir de las muestras animales nos enteramos de que los nagas dominaron a estas criaturas marinas para usarlas como monturas y bestias de carga contra su voluntad. A las que eran muy obstinadas, viejas o estaban lesionadas, las expulsaron para divertirse. ¡Monstruoso!\n\n¡Es nuestro deber sacro terminar con esto!\n\nLos nagas cuentan con fuerzas en las Ruinas de Mathystra y ya deben haberse hecho con trilladores de la costa. ¡Encuentra a su dama de bestias, mátala y regresa con sus herramientas de dominación!", t = "Buceador Sagrado"},
    [90902] = {ot = "Sana $1oa guardias de la muerte heridos con tu habilidad de Luz Sagrada.", st = "Me alegra darle la bienvenida a $gotro nuevo paladín resucitado:otra nueva paladín resucitada; que se une a nuestras filas. A medida que vuelvas a conectarte con la Luz, tal vez notes que ciertas habilidades que antes te resultaban naturales ahora te causen un gran dolor al usarlas. Aquellas donde debes canalizar la Luz para curarte a ti o al resto son un claro ejemplo. \n\nPor desgracia, la única forma de solucionarlo es ponerlas en práctica. Al igual que con cualquier músculo atrofiado, debes soportar el dolor y ejercitar la carne para que sea tan funcional como antes.", t = "Redescubrimiento de la Luz"},
    [91208] = {ot = "Encuentra a la paladín aterrorizada en Camposanto.", st = "No todos los paladines que se alzan otra vez se adaptan rápido a esta nueva realidad. Algunos luchan por aceptar en lo que se han convertido: algo en lo que, de cierta forma, vivieron su vida para erradicar.\n\nA menudo, lo único que estas personas necesitan es un acto de amabilidad o alguien que los escuche, pero, por desgracia, muchas otras no dudan en recurrir a la violencia. Encuentra al paladín que huyó a las colinas directamente al oeste de esta capilla. Demuéstrale tu amistad. Si puedes, ayúdale a que regrese a la senda de la Luz.", t = "Aceptar la realidad"},
    [91209] = {ot = "Sigue el camino que parte hacia el este de Camposanto y encuentra la ciudad de Rémol. Ve a ver a Shari Fontana para continuar con tu entrenamiento.", st = "Lordaeron quizá ya no sea la tierra que alguna vez conocimos, pero nuestro hogar todavía necesita protección contra toda clase de amenazas. Ha llegado el momento de que salgas y enfrentes al mundo. Tu próximo destino será la ciudad de Rémol en el centro de Claros de Tirisfal. Reúnete con Shari Stilwell allí. Ella será quien guíe tu entrenamiento. \n\nUn último consejo antes de partir: cuida cada paso que des como paladín en tu viaje por las tierras de los Renegados. Son muchos los que sirven a la Dama Oscura y desconfían de nosotros, así como de nuestra cercanía con la Luz.", t = "Continúa con tu entrenamiento"},
    [91282] = {ot = "Encuentra el Fuerte de Bandarion y habla con Breton Samuels.", st = "Me anima ver que mis hermanos y hermanas que acaban de resucitar prosperen tanto como tú. Sin embargo, solo podremos alcanzar nuestro máximo potencial mediante un sentido de comunidad y una fe en común. Por eso, estamos formando una nueva orden de paladines aquí en Tirisfal. \n\nSi te interesa, te recomiendo que visites el monasterio de Roca Boreafaz. Se llama Fuerte de Bandarion y está en los riscos justo al noroeste de Hacienda Solliden. Te aseguro que lo verás.", t = "Segundo hogar"},
    [91285] = {ot = "Mata $1oa atacantes Anca Vil y $2oa videntes Anca Vil, y luego informa a Breton Samuels cuando hayas completado la tarea.", st = "Por lo general, somos más hospitalarios con los recién llegados, pero ahora tenemos un problema con los múrlocs.\n\nUna tribu de múrlocs usaba este fuerte como criadero. Ya eran un fastidio desde que llegamos y los expulsamos, pero la situación se está saliendo de control. Pareces alguien bastante $gcurtido:curtida; en combate. ¿Podrías ayudarnos a ponerle un freno a esta plaga? Los encontrarás pululando por los riscos junto al camino del este y en los campamentos alrededor del lago del oeste.", t = "Múrlocs al acecho"},
    [91294] = {ot = "Habla con los residentes del Fuerte de Bandarion.", st = "Ahora que la amenaza inmediata de los ataques múrloc está bajo control, siéntete libre de recorrer el bastión. Todavía no parece gran cosa, pero es nuestro hogar.\n\nCuando hayas terminado de explorar, busca a Danitha Morr, nuestra líder. Ella te ayudará a acomodarte.\n\nMe alegro mucho de haberte conocido, $n. Que la Luz te guíe.", t = "Recorrido por las tierras"},
    [91316] = {ot = "Reúne 12 piezas de leña robusta en Vallesombra en Claros de Tirisfal.", st = "Estamos lejos de Entrañas. La logística es un desafío y no tenemos los materiales de construcción necesarios para restaurar esta fortaleza. Me gustaría que nos ayudaras con eso.\n\nVallesombra, la aldea en ruinas, queda en el Bosque Susurrante, al suroeste de aquí. Uno de los edificios tiene una despensa con todo tipo de cosas. Es muy probable que haya materiales allí. Recupera lo que puedas y regresa aquí.", t = "Haciendo arreglos"},
    [91317] = {ot = "Mata a 8 esclavos mancillados, 6 zelotes mancillados y consigue la cabeza del comandante Rudolph Gelhardt en Claros de Tirisfal.", st = "Ya debes haberte percatado de que no todos los paladines resucitados se han aclimatado bien a su nueva existencia. Algunos conservan los mismos prejuicios que tenían en vida y continúan ejerciendo la violencia contra los Renegados.\n\nNuestra gente aún no confía en nosotros porque recuerdan la persecución realizada por los vivos en nombre de la Luz, y estos ataques no ayudan. Algunos de estos mancillados se han instalado en Vallesombra, al suroeste. Encárgate de ellos y tráeme la cabeza de su líder.", t = "El Deslustrado"},
    [91723] = {ot = "Mata a 8 geománticos kóbold en la Cantera de Jaspe, y regresa con Hamish Bergwort en la Torre de Azora.", st = "¡Maldición! Cada vez que intento calibrar estos delicados instrumentos arcanos, vuelven a desajustarse por una oleada de energía.\nLas oleadas parecen provenir del norte, donde esos primitivos kóbolds practican su magia rudimentaria. ¿Podrías eliminar a algunos de ellos, para que pueda continuar con mi labor?", t = "Instrumentos delicados"},
    [91724] = {ot = "Mata a 6 zahoríes bribones de Defias en el Lago del Hito, y regresa con Hamish Bergwort en la Torre de Azora.", st = "¡Ya casi lo logro y… por el Abisal! Algo sigue perturbando mis instrumentos.\nEsto es sumamente frustrante, $n. He oído rumores de que los bandidos locales han estado practicando hechizos cerca del Lago del Hito. Quizá, si los detienes, estas interrupciones cesen al fin y pueda continuar con mi labor.", t = "Instrumentos delicados"},
    [91725] = {ot = "Recoge 5 suministros de encantamiento robados de los campamentos gnoll cerca de Lago del Hito, y llévaselos a Blixie Fitzwink en la Torre de Azora.", st = "El maestro Theocritus me envió para recoger algunos suministros de encantamiento del puesto de venta, ¡pero unos gnolls me emboscaron en el camino cuando estaba por volver!\n\nSolté el paquete y escapé, pero si regreso sin él, ¡tendré que pasar semanas limpiando los restos de los experimentos de polimorfia como castigo! ¿Podrías hacerme el favor de encontrar esos suministros?", t = "Suministros de encantamiento robados"},
    [91732] = {ot = "Recoge 4 herramientas de minería de la Cantera de Jaspe y regresa con Hagar Lowe en el Aserradero de la Vega del Este.", st = "El buen acero escasea desde la guerra, y nuestras herramientas han perdido su fuerza. Los mineros de Jaspe usaban picos finamente forjados, y sospecho que algunos todavía permanecen en lo profundo de la mina. ¿Podrías recuperarlos para mí? Veré si le puedo dar un nuevo propósito al acero.", t = "Buen acero"},
    [91733] = {ot = "Recoge el hacha calada, la sierra calada y la caja de herramientas calada que la corriente arrastró desde el Aserradero de la Vega del Este, y luego regresa con Ormin Pelford.", st = "Traía un cargamento desde el puesto de venta, pero mi carro volcó y los suministros cayeron al río. Antes de que pudiera alcanzarlos, ya habían sido arrastrados corriente abajo.\nEntre los múrlocs y los lobos que acechan en esas tierras, no tengo posibilidad de recuperarlos por mí mismo. Pareces fuerte… ¿podrías encontrarlos por mí?", t = "Río abajo"},
    [91740] = {ot = "Entrega la cabeza de Croaky a Merell Ross en Torre de la Peña.", st = "No cabe duda de que este múrloc ha estado sembrando el terror en los senderos de la región durante demasiado tiempo. Intuyes que los guardias de la vigilancia cercana estarán ansiosos de conocer su destino final.", t = "Cabeza de Croaky"},
    [91741] = {ot = "Regrésale el libro al hermano Paxton.", st = "<Uno de los kóbolds dejó caer este libro, y parece que trató de comerlo.\n\nEl hermano Paxton tiene una pequeña biblioteca dentro de la abadía. El libro debe haber salido de allí.>", t = "Libro mordisqueado"},
    [91743] = {ot = "Recupera $1oa libros perdidos de los kóbolds en el Valle de Villanorte y llévaselos al Hermano Paxton.", st = "¡Esos detestables kóbolds se están comiendo mis libros! Debes recuperarlos antes de que se devoren toda mi biblioteca.", t = "Roedores traviesos"},
    [91745] = {ot = "Habla con Kelsey Abisma en las afueras de la Mina del Eco en el Valle de Villanorte.", st = "Habla con la nueva aprendiz minera, Kelsey Abisma. Ella trabaja justo afuera de la mina y probablemente haya visto lo que los kóbolds están haciendo. Además, quizás pueda instruirte en algunos secretos de la minería mientras estás allí.", t = "Asesora de minería"},
    [91746] = {ot = "Entrégale la cabeza de Patolmo a Helene Desollapelambres cerca de Villadorada.", st = "El trofeo es un imponente recordatorio de tu victoria contra Patolmo. Quizá a algún cazador o desollador de la zona le interese escuchar la historia.", t = "Cabeza de Patolmo"},
    [91751] = {ot = "Desuella lobos en el Bosque de Elwynn para conseguir 7 pieles de lobo toscas, y entrégaselas a Helene Desollapelambres cerca de Villadorada.", st = "¿Buscas una oportunidad para perfeccionar tu destreza en el desuello? Mi esposo suele cazar lobos para ayudarme, pero ahora se encuentra ocupado en la abadía. Podría necesitar tu fuerza para recolectar pieles adicionales y cumplir con los pedidos que me aguardan.", t = "Pieles de lobo toscas"},
    [91752] = {ot = "Recupera un saco de libros con imágenes del Buscatesoros Narf. Lleva el saco al alguacil McBride dentro de la abadía de Villanorte.", st = "De vez en cuando, un kóbold aparece gritando: \"¡Imagen para Narf!\". No sé quién es Narf. Tal vez sea un jefe kóbold que gobierna desde las cavernas más profundas. A estas alturas, seguramente ya debe tener un saco entero repleto de libros.\n\nReclama esos libros y entrégalos a nuestra autoridad local, el alguacil McBride. Busca un aliado que te acompañe. Los kóbolds que habitan en la mina son mucho más feroces.", t = "El panorama completo"},
    [91753] = {ot = "En la Torre de Azora, Kitta Vientofuego quiere que recojas 3 residuos luminosos.\n\nSe pueden obtener residuos luminosos al desencantar las efigies de cera rudimentaria que arrojan los geománticos kóbold.", st = "El rigor académico, desde ya, es esencial para quienes crean encantamientos, pero unos cimientos prácticos pueden rendir frutos. Tomemos como ejemplo a los humildes kóbold. Carecen de educación formal, sin embargo, tienen una especie de aptitud innata para los conjuros y los encantamientos simples.\n\nConsigue algunas de sus efigies de cera y desarma los encantamientos vinculados a ellos. Puede que te resulte revelador.", t = "Una lección encantadora"},
    [91758] = {t = "¡Sigue a ese kóbold!"},
    [91772] = {t = "¡Shhh! Cazamos kóbolds"},
    [91775] = {ot = "Encuentra 6 libros perdidos y \"Diversión con los elementales\", y llévaselos al alguacil Dughan.", st = "Cuando investigues la Mina Abisal, trata de encontrar alguno de los libros extraviados del hermano Paxton. Está especialmente preocupado por un libro titulado \"Diversión con los elementales\". Cree que incluso un kóbold podría usarlo para invocar a un sirviente elemental. Pero ten cuidado: las profundidades de la mina son muy peligrosas. Te sugiero que vayas bien $gacompañado:acompañada;.\n\n¡Lleva esta bolsa de libros para guardarlos cuando los encuentres!", t = "Devolución de libros"},
    [91777] = {ot = "Recupera \"Geomancia para jóvenes hechiceros curiosos\" y \"Volumen arcano: Conceptos mágicos en pocas palabras\" y devuélveselos al hermano Paxton en la Abadía de Villanorte.", st = "Quedan dos libros por encontrar de la lista del hermano Paxton: \"Geomancia para jóvenes hechiceros curiosos\" y \"Volumen arcano: Conceptos mágicos en pocas palabras\".\n\nLos kóbolds deben haberlos llevado a la Cantera de Jaspe. Por favor, encuéntralos y devuélveselos al hermano Paxton.\n\nPor desgracia, me temo que será muy riesgoso. Si un kóbold \"aprendiz\" fue capaz de invocar a un elemental, quién sabe lo que un maestro podría hacer. Si yo estuviera en tu lugar, iría con amigos de confianza.", t = "Libros poco comunes"},
    [91858] = {ot = "Ve hacia el Sepulcro en el Bosque de Argénteos y habla con Trevan Rol sobre los viajeros perdidos del Anillo de la Tierra.", st = "Una serie de acontecimientos muy desafortunados en Argénteos nos ha dado una oportunidad única para demostrar nuestro valor frente a la horda.\n\nAlgunos miembros superiores del Anillo de la Tierra se perdieron en el Bosque de Argénteos de camino al Molino Tarren. Es todo lo que sabemos, pero los rumores apuntan a que esto se está convirtiendo en un incidente diplomático muy serio. Si encontramos a esas personas, conseguiremos la autoridad que tanto necesitamos.\n\nTenemos un hombre en el Sepulcro, Trevan Rol. Ve allí y habla con él.", t = "Incidente diplomático"},
    [91859] = {ot = "Habla con el Guardia de la Muerte Baldren sobre los viajeros misteriosos del Anillo de la Tierra que recientemente visitaron el Sepulcro.", st = "Yendo al grano, esos \"miembros superiores\" no eran simples diplomáticos. Uno era un Tauren, muy habitual para el Anillo de la Tierra. Pero el otro, y no vas a creerlo, era una elfa. Una elfa *noble*. Iban camuflados, pero he visto quel'dorei antes y apostaría lo que fuera a que eso fue lo que vi.\n\n¿Por qué una elfa acompañaba a un Tauren en territorio de la horda? Bueno, ni idea. Eso es todo lo que sé, así que te recomiendo hablar con el Guardia de la Muerte Baldren, cerca de la entrada a la ciudad.", t = "Un curioso par"},
    [91860] = {ot = "Explora el este de la Isla de Fenris y averigua el destino de los viajeros del Anillo de la Tierra.", st = "Anoche, mientras patrullaba, vi a un grupo de gnolls arrojando un gran cadáver a una hoguera en las orillas de la Isla de Fenris. No vi ningún elfo ni cadáveres más pequeños, pero esto no es un buen augurio.\n\nSi tienes el valor o la insensatez de lanzarte a la Isla de Fenris para averiguar más, adelante, pero si me preguntas a mí, es mucho esfuerzo para buscar a un elfo elitista que seguro ya lleva tiempo muerto.\n\nSé que a los paladines les encanta hacer juramentos y defender causas perdidas, pero esto no vale la pena. Créeme.", t = "Un macabro destino"},
    [91861] = {ot = "Investiga el castillo de Fenris, al norte, e intenta localizar al miembro desaparecido del grupo del Anillo de la Tierra.", st = "<El hecho de que solo hayas encontrado un solo cuerpo es una señal esperanzadora. Puede que la elfa noble que Trevan y Hadrec mencionaron siga viva en algún lugar en el interior de una fortaleza cercana?>", t = "Hacia el castillo de Fenris"},
    [91862] = {ot = "Recupera la llave de la Isla de Fenris de los gnolls Putrepellejo y úsala para liberar a Lumina Vientocantor.", st = "¿Quel'dorei? No soy una \"quel'dorei\", soy Lumina Vientocantor y soy una shen'dorei. Una de los cielonato Formavientos.\n\nVine a estas tierras invitada por el Anillo de la Tierra. Mi compañero Banon y yo estábamos pasando por Argénteos para llegar a las Tierras Altas de Arathi y estudiar las convergencias elementales que hay allí. Claro que no lo logramos.\n\nPero ahora no tenemos tiempo para eso. Mata a los gnolls cercanos. Recupera la llave de esta jaula y libérame. Te diré el resto cuando estemos lo suficientemente lejos de aquí.", t = "Lumina Vientocantor"},
    [91920] = {ot = "Consigue 3 ojos de múrloc y llévaselos al boticario Renferrel en el Sepulcro.", st = "Jamás me atrevería a dudar sobre la efectividad de la fórmula del boticario Renferrel, pero no creo que la poción haya cambiado algo.\n\nA lo largo del Lago Lordamere hay una horda de múrlocs y, dato importante: tienen ojos. Sospecho que el boticario no tiene muchas intenciones de probar cosas nuevas debido a su reciente obsesión con los corazones. Tráele algunos.\n\nPreferiría que Renferrel me asesine por cuestionar sus métodos antes que morir inevitablemente una segunda vez.", t = "Mirada salvaje"},
    [91921] = {ot = "Llévale la poción de Quinn a Quinn Yorick en los Dominios de Ivar, al norte del Sepulcro.", st = "Aquí está la nueva poción para ayudar a que Quinn se recupere, hecha con amor extraído de seis corazones enteros.\n\nAhora, si me disculpas, me marcharé antes de que me hagas hacer más papeleo.", t = "Regresa junto a Quinn (otra vez)"},
    [92109] = {ot = "Reúne 5 viales vacíos, 5 hojaplatas y 5 flores de paz para la joven aspirante a alquimista dentro de la granja de Arroyo de la Luna en Páramos de Poniente.", st = "Em... hola, $Gseñor:señora;. No debería hablar con extraños, pero... ¿qué son esas botellas brillantes que sobresalen de tu mochila? ¿Eres alquimista? ¡Genial!\n\nCuando sea mayor también quiero ser alquimista. Papi no me deja jugar con sus hierbas, dice que es muy peligroso.\n\nBueno, ahora quiero aprender. ¿Podrías conseguirme algunos suministros, por favor?", t = "Mi primer juego de alquimia"},
    [92110] = {ot = "Reúne 3 ojos de múrloc para la joven aspirante a alquimista dentro de la granja de Arroyo de la Luna en Páramos de Poniente.", st = "¡Vaya, mi primera poción! Cuando comenzaste, ¿sabías que si mezclabas esas dos hierbas la poción se volvería de color rojo brillante?\n\nEso fue divertido, pero mezclar unas cuantas flores no se parece al tipo de alquimia que hace mi papi. Él también usa otros ingredientes.\n\n¡No sé qué más utilizar, así que intentemos con lo primero que se nos ocurra! A ver... ¿ojos de múrloc? Suena asqueroso, pero apuesto a que algo sucederá.", t = "Mi primera poción real"},
    [92124] = {ot = "Habla con Daniel, el asistente del hermano Paxton, en la biblioteca.", st = "¡Debemos contar cuántos libros faltan!\n\nBusca a mi inútil asistente, Daniel. Él puede hacer un inventario rápido y decirnos qué tan grave es la situación.\n\nEstá obsesionado con los distintos oficios de comercio en Bosque de Elwynn. El muchacho prefiere enfocarse en eso en lugar de cumplir con su importante labor de asistirme.\n\nNo dejes que se entretenga con charlas sobre oficios. ¡Necesito que averigües que ocurrió con mis libros!", t = "Inventario de libros"},
    [92401] = {ot = "Investiga la desaparición de Edward Tejecorazones en las Ruinas de Lordaeron.", st = "Se trata de mi esposo, Edward...\n\nNo ha regresado de su viaje semanal al cementerio en las ruinas de Lordaeron. Perdimos a nuestro hijo cuando Arthas arrasó con la ciudad, y a mi querido Edward aún lo carcomen la culpa y el dolor por no haber encontrado su cuerpo. Intenté impedir que inspeccionara las ruinas infestadas, pero se niega a darse por vencido. Trato de no preocuparme, pero ya han pasado varios días.\n\nSé que hay cosas allí a las que no puedo enfrentarme, pero si estás $gdispuesto:dispuesta;, te pido que descubras qué le sucedió a mi marido.", t = "Una pregunta con miedo"},
    [92415] = {ot = "Llévale la carta manchada con sangre a la supervisora de huérfanos Ruiseñor en la Ciudad de Ventormenta.", st = "<Un montón de papiro rasgado y manchado que apenas sobrevivió al pisoteado suelo no-muerto del cementerio. Menciona a un niño de la familia Tejecorazones que desapareció. Quizás la supervisora de huérfanos en la Ciudad de Ventormenta sepa más al respecto.>", t = "Recuerda que te amo"},
    [92421] = {ot = "Recoge $1oa extremidades intactas dentro de las Ruinas de Lordaeron y regresa con Morbin Flageluz en Entrañas.", st = "Como paladín de los Renegados, es mi deber exigir que se cumpla la voluntad de nuestra Dama Oscura, mientras respondemos a las necesidades de la gente. Agradecemos la oportunidad de completar ambas tareas.\n\nLa Plaga aún deambula en grandes cantidades encima de Entrañas. Nuestras fuerzas se reducen al intentar reclamar nuestra tierra, y la carne descompuesta ya no se puede coser sin reemplazos.\n\nSi nuestro glorioso capitán Garek Bandarion estuviera aquí, estoy seguro de lo que pediría: terminar lo que empezó y sanar a los nuestros. ¡Por Lordaeron!", t = "Justicia de la Luz"},
    [92422] = {ot = "Mata a Rath'mael en las Ruinas de Lordaeron para el Guardia de la Muerte Kristof en Rémol.", st = "Llegaron informes del Mirador de Lordamere, en las profundidades de las Ruinas de Lordaeron. Una niebla profana ha invadido las calles y el cementerio, lo que le otorga a la Plaga cierto sigilo. \n\nSegún nos informaron nuestros exploradores, la está conjurando una nueva fuerza en sus filas, un nigromante conocido como Rath'mael. No podemos darnos el lujo de esperar esta vez, $n.\n\nSi tienes aliados, reúnelos para asistir a los Renegados. Libera a nuestra tierra de esta criatura.", t = "La furia de Rath'mael"},
    [92432] = {ot = "Preséntate ante la imagen de la archimaga Modera, cerca de la Ciudad de Dalaran.", st = "Traigo malas noticias de Dalaran. Algo ha perturbado nuestras líneas ley, lo que causa que nuestros ensamblajes en la ciudad presenten un comportamiento errático y destructivo.\n\nAún no sabemos qué es lo que causa este alboroto. El alto consejo nos ordenó mantener este asunto en secreto para no deshonrar a nuestra orden. Pero no podemos mantener esta farsa por siempre. ¡La ciudad está siendo arrasada mientras hablamos!\n\nLa archimaga Modera me envió para solicitar ayuda externa. Busca su imagen cerca de Dalaran junto al Lago Lordamere.", t = "Un pedido alarmante"},
    [92434] = {ot = "Busca una forma de entrar a Dalaran por el Lago Lordamere.", st = "Lo que sea que hizo que la barrera de Dalaran se desactivara, ha causado un caos en la ciudad. Ahora que ya te has deshecho de sus patrullas, no hay mejor momento que este para entrar y descubrir sus secretos.\n\nToma la llave que encontraste en el campo de reclusión y busca las alcantarillas que hay por la frontera norte de la ciudad. Con suerte, esos magos no habrán tenido ninguna razón para poner una barrera en una entrada tan... desagradable.", t = "Calles sangrientas"},
    [92456] = {ot = "Recoge una flor vil imbuida de la Ciudad de Dalaran y dásela a Shylamiir en la Ciudad de Ventormenta.", st = "Si vas a molestarme, al menos haz algo útil. Tengo un encargo pendiente.\n\nPara ser una ciudad de magos, en Dalaran tienen un interés sorprendente por la botánica. Los del Kirin Tor son bastante reservados, pero me encantaría conseguir una muestra de su vegetación imbuida de maná.\n\nEstá claro que te sientes $Gcómodo:cómoda; donde no te quieren. Quizás puedas encontrar la forma de entrar a la ciudad. Si lo logras, tráeme lo que sea que esté creciendo en el jardín central.", t = "Una buena muestra"},
    [92457] = {ot = "Elimina $1oa remanentes de búsqueda, $2oa remanentes saturados y $3oa ecos de maná dentro de la Ciudad de Dalaran para la archimaga Modera que espera fuera de Dalaran.", st = "La brecha ha afectado a muchos de nuestros sirvientes y encantamientos por toda la ciudad, incluidos muchos de los que se encargan de nuestras defensas. Esta energía arcana fragmentada ha atraído la atención de elementales rebeldes que buscan impregnarse en esta magia que fluye con libertad.\n\nEstamos ocupados manteniendo los resguardos y atendiendo otros asuntos graves, por lo que sería un gran favor para el Kirin Tor si pudieras eliminar esta multitud de elementales.", t = "Un arcano hambriento"},
    [92458] = {ot = "Recoge motas arcanas para la imagen de la archimaga Modera, cerca de la Ciudad de Dalaran.", st = "Lo que sea que perturbó las líneas ley, empezó en la cima de la Ciudadela Violeta. Un estruendo ensordecedor resonó por las salas de arriba y ahora nos inunda un poder arcano descontrolado. Estamos usando todas nuestras fuerzas para mantener las protecciones en su lugar.\n\nNo podemos aguantar mucho más. Necesitamos refuerzos.\n\nEl Kirin Tor está ocupado dentro, pero aun así necesitarás un método más discreto para entrar. Toma esta llave y ven a verme en la ciudadela en cuanto hayas entrado a la ciudad. Tenemos que terminar con esta perturbación.", t = "El corazón de la perturbación"},
    [92460] = {ot = "Habla con Rorian, el Buscadías en Arboleda Thendal.", st = "¡Mírate, con esos ojos brillantes y listos para la aventura! Hemos estado esperando tu llegada y ansiosos por contar con tu tan necesaria ayuda aquí, en el Poblado Thendal. Me imagino que tienes muchos nervios y una emoción inmensa por lo que vendrá. Después de todo, solo se llega a la mayoría de edad una vez en la vida.\n\n<Ailee sonríe amablemente.>\n\nVe a buscar a nuestro líder del poblado, Rorian el Buscadías, en la entrada del árbol abuelo, al oeste de aquí. Él te ayudará a comenzar tu viaje.", t = "La edad adulta"},
    [92461] = {ot = "Derrota a 8 vuldren jóvenes en Arboleda Thendal.", st = "Vivimos tiempos de gran incertidumbre para nuestro pueblo. Nos enfrentamos a desafíos sin precedentes que pueden requerir soluciones audaces, pero también debemos lidiar con lo cotidiano y mundano aquí, en Arboleda Thendal. Por ejemplo, piensa en el reciente aumento insostenible de la población de vuldren.\n\nLos vuldren son una parte vital de nuestro ecosistema. Sin embargo, es necesario corregir los desequilibrios para mantener la leve armonía que comparten todas las criaturas de Arboleda Thendal.\n\nDirígete al este y elimina a algunos de los vuldren que se encuentran allí.", t = "Armonía en equilibrio"},
    [92462] = {ot = "Mata a 8 cirrovuelos molestos en Arboleda Thendal.", st = "Hace poco, uno de nuestros forestales ha informado de una plaga de cirrovuelos aquí, en Arboleda de Thendal.\n\nLos cirrovuelos pueden ser peligrosos si el enjambre crece demasiado, así que dirígete al extremo este de la arboleda y extermina a todos los que puedas.", t = "Investigación de la plaga"},
    [92463] = {ot = "Destruye a la reina cirrovuelo en la Arboleda Thendal.", st = "Si el bosque está tan plagado de estos insectos como parece, no bastará con matar a las obreras.\n\nAdéntrate más en el bosque y encuentra a la reina. Estará cerca de la colmena, rodeada de soldados más grandes y agresivos; así que ten cuidado.\n\nElimina a la reina y regresa cuando hayas terminado. Así tendremos un problema menos de qué preocuparnos aquí.", t = "La reina cirrovuelo"},
    [92464] = {ot = "Habla con Yala Vigía del Viento en Arboleda Thendal.", st = "Desde que nuestros benefactores elementales nos abandonaron, parece que no hacemos más que pasar de un problema a otro. Ahora nos enfrentamos a las manifestaciones de vientos agitados cerca de las piedras erguidas al noreste.\n\nA diferencia de los espíritus de viento conscientes de sí mismos que una vez vivieron aquí, estos simples duendes reaccionan de manera similar a las fuerzas, emociones e intenciones de las criaturas que los rodean. \n\nMi aprendiz, Yala Vigía del Viento, fue a observarlos. Búscala y averigua qué descubrió.", t = "Agitación elemental"},
    [92465] = {ot = "Mata a $2oa vientos turbios y a $1oa conversos Al'Aketh en Arboleda Thendal.", st = "El culto Al'Aketh es una peste para esta isla. Sin duda, estos cultores son los responsables de agitar a los inocentes duendes de viento que residen aquí y de volverlos violentos.\n\nPor desgracia, tendremos que disipar estos vientos turbios antes de que le hagan daño a alguien. También debemos enviar un mensaje claro al culto de que no son bienvenidos en la arboleda.\n\n¿Me darías una mano, $c?", t = "Agitadores"},
    [92466] = {ot = "Lleva un sello de Akir a Formavientos Boro.", st = "Aunque gran parte de nuestra prosperidad se la debemos al elemento del viento, el camino que recorremos exige que obedezcamos el llamado de los cuatro elementos primarios y nos sometamos a una prueba para cada uno de ellos. Pero, antes de comenzar tu primera prueba más dura, debes demostrar tu determinación en esto.\n\nViaja hasta las piedras erguidas que se encuentran al este. Han encontrado allí a una fuerza de conversos Al'Aketh y debemos expulsarlos. Enfréntate a los cultores que se encuentran allí y tráeme uno de sus sellos como prueba.", t = "Llamado de la tierra"},
    [92467] = {ot = "Encuentra el Ascenso de Espíritus y bebe la Sapta de tierra.", st = "La sapta es una bebida creada para unir nuestros espíritus con los elementos. Cargada de magia, la poción permite a quien tiene fuerza de voluntad ver los elementos que nadie más puede ver. Tu espíritu se conectará con los elementos para los que fue creada la sapta, y son pocos los chamanes que conocen la receta.$B$BLa sapta siempre se bebe en un lugar sagrado, y en ningún otro sitio... recuérdalo.$B$BBusca el Ascenso de Espíritus al noroeste de aquí. Cuando llegues, bebe la sapta, y... verás lo que necesitas ver.", t = "Llamado de la tierra"},
    [92468] = {ot = "Lleva el cuarzo en bruto al Formavientos Boro en Arboleda Thendal.", st = "Toma este cuarzo en bruto y llévaselo al Formavientos Boro como prueba de nuestro encuentro. Te hará un tótem y este fragmento será su corazón. Puede parecer muy pequeño, pero descubrirás que el tamaño no importa, y que incluso las cosas más pequeñas pueden perdurar más que muchas otras.$B$BTen paciencia, $n. Sigue siendo fuerte. Y busca la sabiduría. Es todo lo que te piden los elementos. Al final te harás $guno:una; con ella... Respétala del mismo modo que ella te respeta a ti.", t = "Llamado de la tierra"},
    [92469] = {ot = "Llévale las noticias sobre los Al'Aketh a Rorian, el Buscadías en Arboleda Thendal.", st = "Ya has hecho suficiente aquí, $c. Yo me quedaré para acabar con los que queden.\n\nRegresa al pueblo y avísale a Rorian de la presencia del culto. No estará muy feliz.", t = "Vuelve con Rorian"},
    [92470] = {ot = "Mata a 8 carroñeros ursera y recoge la cabeza de la madre del cubil, Urs'anah, en Arboleda Thendal.", st = "Rorian dijo que te he estado observando. Ahora te propongo una prueba de determinación. Sin embargo, ten cuidado: estarás en grave peligro.\n\nVe a las cuevas del sur. Reduce la cantidad de urseras que hay allí y busca a su matriarca, a quien los forestales llaman \"Urs'anah\". Acaba con ella y tráeme una prueba de su muerte. Una vez que lo hayas hecho, habrás dado un paso importante en tu camino.", t = "Matriarca demoníaca"},
    [92471] = {ot = "Habla con Aetheen de los Vendavales en Arboleda Thendal.", st = "Quizá no lo sepas, pero todo lo que has hecho hasta ahora ha sido una especie de prueba. Una prueba de lo que te espera. Esta es una isla enorme, y Zephras necesita jóvenes aventureros valientes como tú si queremos sobrevivir a las pruebas que enfrenta nuestro pueblo.\n\nLa llamada Aetheen de los Vendavales es una de las líderes de nuestro pueblo aquí en Isla Zephras, y te ha estado observando. Ella tiene una tarea que debes completar. Habla con ella para obtener más información.", t = "Aetheen de los Vendavales"},
    [92472] = {ot = "Preséntate ante la agente Aonda en la Aldea Shen'dar.", st = "Una de las amenazas más generalizadas de Isla Zephras es el Culto de Al'Aketh. Se trata de zelotes religiosos que se dedican al culto del supuesto gobernante elemental de Muro Celeste, Al'Akir, el señor del viento. Son brutales, obstinados, y su poder y ambiciones se vuelven cada día más letales.\n\nTu camino te llevará pronto al sur de la Aldea Shen'dar. Preséntate ante la agente Aonda cuando llegues. El culto amenaza a Shen'dar y necesitan ayuda. Dile a Aonda que yo te envié.", t = "El próximo paso"},
    [92473] = {ot = "Consigue 6 garras de ursera escuálida de la ursera escuálida en Arboleda Thendal.", st = "La guarida ursera al suroeste se está convirtiendo en un problema rápidamente. Justo la semana pasada, los forestales tuvieron que matar a un adolescente ursera que se había acercado demasiado al pueblo e intentó atacar a un niño que jugaba cerca de la base del árbol ancestral en el centro del pueblo.\n\nEl niño tuvo mucha suerte de salir con vida. El hambre y la desesperación hacen que estas bestias sean demasiado peligrosas como para dejarlas sueltas. Ve al sur y acaba con los ursera más escuálidos. Tráeme sus garras como prueba cuando hayas acabado.", t = "Invasión agresiva"},
    [92474] = {ot = "Salta desde lo alto de la torre de vigilancia de Arboleda Thendal y usa tu habilidad Caminar en el aire para ralentizar la caída.", st = "¡Hola, $n! ¿Quieres jugar a algo?\n\nLo único que tienes que hacer es subirte a esa cornisa... ¡y saltar! Usa tu habilidad innata para caminar en el aire y así ralentizar tu caída, y descubre hasta dónde puedes flotar.\n\nLas reglas son inventadas y los puntos no importan, ¡pero obtendrás puntos extra si logras aterrizar justo en frente de Rorian el Buscadías y lo sorprendes! A él no le va a agradar, pero a mí me dará mucha gracia si logras hacerlo enfadar. ¡Ja!", t = "Caer con estilo"},
    [92479] = {ot = "Lee la carta garabateada y habla con Tordrin Filotallo en la abadía de Villanorte.", st = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $n. Parece ser una carta sellada con la marca de Tordrin Filotallo, nuestro instructor de cazadores de la zona. Deberías leerla antes de continuar con tus tareas en la abadía.", t = "Una carta garabateada"},
    [92481] = {ot = "Examina el cristal de regreso resplandeciente y luego habla con Dorii Susurro Alegre, en la Arboleda Thendal.", st = "Mientras te encargabas del problema con los vuldren, nuestra instructora de magos local, Dorii Susurro Alegre, dejó este cristal de regreso para ti. Contiene algún tipo de mensaje, así que échale un vistazo. Después, podrás encontrarla en la estructura que está justo detrás de mí.", t = "Estudiante de lo arcano"},
    [92482] = {ot = "Lee la nota garabateada y luego habla con Tai'ree Vistadista, en la Arboleda Thendal.", st = "Mientras te encargabas del problema con los vuldren, nuestra instructora de cazadores local, Tai'ree Vistadista, dejó está nota para ti. Léela y luego habla con ella. Está por allí, cerca del centro del poblado.", t = "El camino del cazador"},
    [92483] = {ot = "Lee la nota simple que dejó Akeri Hoja Umbría y ve a hablar con él en la torre de la vigilancia de la Arboleda Thendal.", st = "Mientras te encargabas del problema con los vuldren, nuestro instructor de pícaros local, Akeri Hoja Umbría, ha pedido hablar contigo. Dejó esta nota, así que léela antes de ir a buscarlo. Está en la torre de vigilancia, aquí en el poblado.\n\nEs un tipo misterioso, pero bueno, tú también. Creo que se van a llevar bien.", t = "En las sombras del hogar"},
    [92484] = {ot = "Examina el cristal de regreso resonante y luego habla con el Formavientos Boro, en Arboleda Thendal.", st = "Mientras te encargabas del problema con los vuldren, nuestro instructor de chamanes local, el Formavientos Boro, dejó este cristal de regreso para ti. Échale un vistazo y luego habla con él. Está por allí, cerca del centro del poblado.", t = "Conexión elemental"},
    [92485] = {ot = "Lee el papiro doblado y luego habla con Xyton Ventargento, en Arboleda Thendal.", st = "Mientras te encargabas del problema con los vuldren, nuestro instructor de druidas local, Xyton Ventargento, dejó esta nota para ti. Léela cuanto antes y búscalo en la base de este gran árbol que tengo detrás de mí.\n\nPresta atención a sus palabras y a sus consejos; puede enseñarte muchas cosas.", t = "Estudiante de la naturaleza"},
    [92489] = {ot = "Asesina al elemental de maná en la Ciudad de Dalaran para el sumo hechicero Andromath, en la Ciudad de Ventormenta.", st = "El Kirin Tor ha sido aliado de la Alianza por mucho tiempo. Tras la destrucción de su ciudad a manos del archidemonio Archimonde, los habitantes de lo que alguna vez fue una orgullosa ciudad de magos ahora viven aislados y desconfían de los forasteros.\n\nEn los últimos años se han puesto en marcha iniciativas de reconstrucción de la ciudad de Dalaran para devolverle su antigua gloria. Sin embargo, los informes indican que los habitantes están teniendo problemas para contener un brote de energías arcanas descontroladas.\n\nDebemos ayudarlos a contrarrestar el ataque para no perder a uno de nuestros aliados más poderosos.", t = "Poder sobrecogedor"},
    [92514] = {ot = "Habla con Illaya Ventámbar y Coriella Brisacalma en la Aldea Shen'dar.", st = "Tienes ese aire de Formavientos. Cuando estoy cerca de alguien con un toque espiritual, siento una suave descarga estática en la piel que me resulta inconfundible. Antes de ponerte a trabajar aquí, deberías hablar con la anciana Formavientos que vive aquí, Illaya Ventámbar. Está aquí afuera, cerca del centro de la ciudad.\n\nAh, y también habla con Coriella Brisacalma, que administra la posada local y puede proporcionarte alojamiento y suministros si necesitas.", t = "Bienvenida a la Aldea Shen'dar"},
    [92515] = {ot = "Consigue 10 pelambres de leozarpa de los leozarpas en las Tierras Altas de Shen'dar.", st = "Como si los bandidos y los cultores locos no fueran suficiente, las colinas también están plagadas de leozarpas en este momento. Comienzan a invadir las fronteras del pueblo y se vuelven cada vez más atrevidos. Es solo cuestión de tiempo para que se lleven a la mascota o al hijo de alguien. Sería un acto de misericordia reducir su número ahora, en lugar de esperar a que ocurra alguna tragedia.\n\nTráeme unas diez pelambres. Puedo convertirlas en todo tipo de productos que serán de gran ayuda para la aldea.", t = "El problema con los leozarpas"},
    [92516] = {ot = "Mata a 8 hipogrifos jóvenes, 6 protectores hipogrifos y una matriarca hipogrifo en las Tierras Altas de Shen'dar.", st = "Hace poco, una bandada de hipogrifos se estableció al sureste de la Aldea Shen'dar y han estado causando estragos entre los viajeros que pasan por ahí. Necesito que alguien vaya y reduzca su número por nosotros.", t = "Hipogrifos hostigadores"},
    [92517] = {ot = "Mata a 10 bandidos de las Tierras Altas y a su líder, Bennic \"Malvento\", en las Tierras Altas de Shen'dar.", st = "Hay una cueva no muy lejos, hacia el norte, escondida detrás de una cascada. Sé muy bien que hay un grupo de bandidos que opera desde esa cueva. Ya eran un problema para nosotros antes de que llegara el culto, pero ahora son una pesadilla. Por desgracia, no puedo enviar a nadie para eliminarlos.\n\nNecesito que vayas ahí y te encargues de ellos. Mata a todos los que puedas y, si es posible, acaba con su líder, al que llaman Bennic \"Malvento\". Esa cueva es peligrosa, así que ten cuidado.", t = "El elemento criminal"},
    [92528] = {ot = "Echa un vistazo por el Poblado Falaath para averiguar cuáles son las intenciones del culto en las Tierras Altas de Shen'dar.", st = "Los fieles de Al'Akir ganan fuerza con cada recluta entusiasta como tú. Como puedes ver, ¡nuestra fortaleza da forma a la propia tormenta!\n\nLo normal sería enviarte directamente al sacerdocielo Aanders para que te evalúe, pero está ocupado con una visita en la posada del norte de la ciudad. Por favor, evita ese lugar por ahora. $gUn:Una; recluta novel como tú ante la presencia de tal huésped sería inapropiado.\n\nPor el momento, limítate a no estorbar a nadie.", t = "Entre los fieles"},
    [92529] = {ot = "Ve a ver al misionero Jasaan, cerca de la entrada del Poblado Falaath.\n\nSi pierdes la Marca de Akir, habla con Sania Brisargenta en la Aldea Shen'dar para recuperarla.", st = "Me regocija el corazón que quieras servir a Al'Akir. Las tribulaciones que sufrimos como pueblo se deben a nuestro propio conformismo. Nos volvimos arrogantes y dimos por hecho la generosidad de los vientos. El estancamiento que sobrevino es el motivo por el que los espíritus del viento nos abandonaron.\n\nSolo a través de actos de compunción podremos volver a sentir la caricia de la brisa. Si deseas gozar de la compañía de otros shen'dorei con ideas afines, ve al Poblado Falaath y busca al misionero Jasaan. Te identificaré con una marca para que los fieles te reconozcan como recluta.", t = "Poblado Falaath"},
    [92532] = {ot = "Lee la nota arrugada que te dieron y luego busca a la maestra del acero Ren dentro de la torre de vigilancia del Poblado Thendal.", st = "Mientras no estabas, nuestra instructora de guerreros, la maestra del acero Ren, dijo que fueras a verla cuando regresaras. Además, te dejó esta nota.\n\nLéela y luego ve a verla en el interior de la torre de vigilancia del poblado.", t = "El camino del guerrero"},
    [92544] = {ot = "Mata a 6 brutos Al'Aketh, 4 neófitos Al'Aketh y a Malduko Rompenubes en Arboleda Thendal.", st = "Una banda de matones del culto Al'Aketh se ha instalado cerca de las ruinas del templo, al suroeste de aquí, liderada por un auténtico monstruo llamado Malduko Rompenubes. Sin duda, la suma sacerdotisa Lorthuna, del Santuario de Akir, envió a esta chusma para atacar a los viajeros y obligar a nuestro pueblo a unirse al culto.\n\nNecesito quedarme aquí en mi puesto para advertir del peligro a los viajeros que salen del bosque, pero te agradecería mucho que acabes con esos cultores y su líder por mí.", t = "Matones Al'Aketh"},
    [92550] = {ot = "Dirígete a las ruinas del Poblado Falaath, acaba con 6 clamatormentas Al'Aketh y 4 relámpagos vivientes, y córtale la cabeza al comandante Cyclas.", st = "Quizá nuestra mejor defensa aquí sea precisamente una ofensiva contundente. La ventaja que tenemos ahora es que sabemos que se avecina un ataque. Lo que menos esperan es que los ataquemos primero.\n\nSé que ya te pedí mucho, pero necesito que vuelvas al Poblado Falaath, mates a todos los cultores que puedas y, si logras acercarte lo suficiente, mates al comandante y me traigas su cabeza. Me quedaré aquí para organizar a los ciudadanos y a nuestros pocos pacificadores, y preparar una defensa... por si no regresas.", t = "Estragos en las Tierras Altas"},
    [92551] = {ot = "Recoge 10 paquetes de suministros de Shen'dar robados en el Poblado Falaath de las Tierras Altas de Shen'dar.", st = "¿Puede ser que irás al Poblado Falaath? Mientras estés ahí, cuida nuestros alijos de suministros robados.\n\nLos Al'Aketh llevan meses asaltando nuestras caravanas de suministros que transportan diversos productos, como alimentos y piedras de viento, hacia y desde las tierras bajas. Claro que le han echado la culpa a los bandidos, pero sabemos que todo apunta al mismo lugar. Si queda algo de estos recursos en Falaath, sería de gran ayuda que pudieras recuperarlos.", t = "Suministros robados"},
    [92553] = {ot = "Recoge $1oa huevos pequeños y $2oa trozos de carne de zancudo de las criaturas que se encuentran en las Tierras Altas de Shen'dar.", st = "¿Te interesa trabajar en algo? Me vendría bien un poco de ayuda de alguien tan fuerte y $gávido:ávida; de aventuras como tú. La situación se está volviendo cada vez más peligrosa por aquí, y nadie tiene tiempo para cazar o recolectar. Necesito a alguien que salga a buscar huevos frescos y carne de zancudo para seguir alimentando a este pueblo.\n\nEstaré encantado de enseñarte una de mis famosas recetas si me traes lo que necesito. ¿Qué dices?", t = "Reponer de alacenas"},
    [92579] = {ot = "Entrega el informe por escrito de Aonda a Valennia Puñotormenta en Valanaar.", st = "Por el momento, parece que el pilar y la aldea están a salvo, así que me gustaría que le entregaras este informe a Valennia Puñotormenta en Valanaar, en el límite sureste de la isla. Ella es la líder de los pacificadores de la isla y necesita saber lo que sucedió aquí.\n\nEl culto se está expandiendo rápidamente y los pacificadores han logrado evitar el conflicto directo hasta ahora, pero no creo que puedan hacerlo más. Valanaar tendrá que prepararse para la batalla.\n\nEn cualquier caso, gracias por todo. Nunca estarás $gsolo:sola; en Shen'dar, $n.", t = "A Valanaar"},
    [92595] = {ot = "Escucha lo que Illaya Ventámbar tiene para decir.", st = "<Illaya te sonríe con cariño.>\n\nMe alegra que hayas vuelto para hablar conmigo, $ghijo:hija; de los vientos. Supe desde el primer momento en que te presentaste ante mí que tenías una gran vista celeste. ¿Te sorprende? Incluso quienes no se han formado como chamanes pueden tener ese don. \n\nVen, hablemos del mandato de los Formavientos, la naturaleza de nuestras luchas en Zephras y la difícil situación de nuestro pueblo.", t = "Los Formavientos"},
    [92596] = {ot = "Siéntate y habla con Rathiril Lanzasol.", st = "El aura de energía arcana que te rodea es poderosa, aunque aún no te hayas iniciado en la magia. No me cabe duda de que te convertirás en $gun aventurero:una aventurera; muy hábil. Tu conexión con nuestra magia ancestral te resultará muy beneficiosa, incluso si nunca llegas a pronunciar un solo conjuro.\n\nVen, siéntate. Hablemos un poco sobre la orden a la que pertenezco, la esencia de la magia arcana de Zephras y el difícil presente que atraviesa nuestro pueblo.", t = "La Suma Orden"},
    [92597] = {ot = "Usa tu habilidad racial Leer línea ley en la línea ley de Arboleda Thendal.", st = "Aquí, en el plano elemental, obtenemos gran parte de nuestra fuerza arcana de las líneas ley que aún discurren por el suelo bajo nuestros pies. Últimamente, estas líneas ley han comenzado a aflorar a la superficie, lo que nos brinda un acceso más directo y poderoso a estas energías arcanas latentes.\n\nDirígete a las piedras erguidas que se encuentran al noreste. Allí hay una línea ley. Aprovecha tu derecho de nacimiento y absorbe su energía.", t = "Lectura de líneas ley"},
    [92598] = {ot = "Usa tu habilidad racial Vista celeste en la convergencia elemental de Arboleda Thendal.", st = "Como Formavientos, tienes la capacidad de utilizar la vista celeste sagrada que nos otorgaron los espíritus elementales. Viaja a las piedras erguidas ubicadas al noreste de la aldea. Encuentra allí la convergencia elemental y utiliza tu don.\n\nDescubrirás que puedes recurrir a la vista celeste en cualquier lugar, pero su poder es mucho mayor si lo haces en presencia de una convergencia elemental. En ocasiones, también podrás recibir otros fragmentos de sabiduría de los espíritus que se sienten atraídos por esos lugares de poder.", t = "El don de la vista celeste"},
    [92640] = {ot = "Habla con Valennia Puñotormenta en Valanaar y sigue sus instrucciones.", st = "Como no es viable enfrentarse al culto a campo abierto, nuestra mejor opción será aprovechar esta oportunidad para atacar el santuario mismo. Podemos acabar con la propia Lorthuna antes de que cumpla con su parte de todo este plan.\n\nTambién resulta que desde hace tiempo Valennia está preparando una estrategia para un posible ataque al santuario. El único problema es que necesitaremos ayuda. \n\nHabla con Valennia para que te dé los detalles.", t = "Tiempos desesperados"},
    [92642] = {ot = "Mata a 4 sanadores Al'Aketh y 8 camorristas Al'Aketh en los Bajíos Ventobaya.", st = "Valennia envió a una sola persona para ayudar a repeler un asalto a gran escala... Que los vientos soplen a nuestro favor.\n\nNo pareces muy fuerte, pero aceptaré toda la ayuda que venga. Tenemos que infligir el mayor daño posible para detener esto pronto. Mis soldados no podrán aguantar mucho más.\n\nBaja la colina e interrumpe su logística. Sus sanadores mantienen en pie a sus atacantes. Si los eliminamos, tal vez podamos juntar nuestras fuerzas y hacer que retrocedan. Mientras estás allí, mata a todos los cultores que puedas.", t = "Interrupción logística"},
    [92643] = {ot = "Encuentra al cultor traidor en la casa en las tierras altas, al noroeste de Valanaar.", st = "Hay un traidor entre los Al'Aketh. Asegura conocer las intenciones reales del culto en cuanto a la isla y quiere venir aquí, pero solo si le garantizamos protección.\n\nEl desertor se oculta en una residencia apartada justo al noroeste de Valanaar, en las tierras altas. Necesito que alguien vaya allí con discreción, encuentre al traidor y lo escolte hasta aquí. Puede que sea una trampa, pero si esta información es tan importante como asegura, vale la pena arriesgarse.", t = "El traidor"},
    [92644] = {ot = "Llévale el cristal resplandeciente a Talanaanis Cantosombrío en Valanaar.", st = "<Buscas debajo del cuerpo aún tibio del cultor traidor y encuentras un cristal azul pequeño y brillante. Parece que está dañado, pero puede ser importante. Tal vez al gran ancestro Cantosombrío le interese saber de esto.>", t = "Noticias desafortunadas"},
    [92645] = {ot = "Mata a la comandante Belguilos en los Bajíos Ventobaya.", st = "Será difícil repeler este ataque a menos que eliminemos a la comandante cultora. La llaman Belguilos, \"la Exterminadora\", y es el horror personificado. Solía ser una pacificadora antes de que el culto se saliera de control, e incluso en aquel entonces era... rara. Ahora que es cultora, no puedo ni imaginar las atrocidades que debe cometer.\n\nTal vez te estoy enviando a una muerte temprana, pero alguien tiene que encargarse de Belguilos si pretendemos sobrevivir. La encontrarás en la casa en la base de la colina. Buena suerte, $c.", t = "Exterminar a la Exterminadora"},
    [92646] = {ot = "Cruza el portal a los Pináculos Rohashi en lo alto y únete a Elaadrin Ventopar y Ayessa Cantoalba en su enfrentamiento con la suma sacerdotisa Lorthuna.", st = "Lorthuna huyó a los pináculos a través de una suerte de portal. Ayessa y Elaadrin fueron tras ella. Fue hace apenas unos instantes.\n\nMe temo que recibí demasiados golpes y tendré que quedarme aquí. Cruza el portal, busca a Ayessa y ayúdalos a detener a Lorthuna.\n\nA menos que la ayuda que Elaadrin y Ayessa dijeron que pedirían llegue pronto, estás $gsolo:sola; a partir de aquí. Buena suerte, $c.", t = "Enfrenta a Lorthuna"},
    [92679] = {ot = "Escucha lo que Alvarion Campo de Viento tiene para decir y busca a Aamelia Campo de Viento en el Huerto de Campo de Viento.", st = "Ho... Hola, $gforastero:forastera;. Das la impresión de ser $gun aventurero habilidoso:una aventurera habilidosa;. Me...\n\n<El cielonato se estremece, claramente por un terrible dolor que sufre.>\n\n... Me preguntaba si estabas buscando trabajo. Vine a Valanaar a reclutar luchadores que me ayuden a salvar mi granja. Si te interesa, ve a buscar a mi esposa Aamelia Campo de Viento, que se encuentra en nuestro huerto al oeste de Valanaar, en los bajíos.", t = "Diezmo de sangre"},
    [92682] = {ot = "Recoge 10 tormanzanas maduras y mata a 5 bandidos hambrientos en el Huerto de Campo de Viento.", st = "Ah, ¿así que tienes más valentía que sensatez? Bueno, no voy a discutir.\n\nFerauu y sus matones todavía no cumplieron con su cuota de la cosecha, así que te pondré a trabajar por tu comida hasta que lleguen.\n\nVe afuera y recoge el lote de tormanzanas del día. Ah, y los bandidos que acechan cerca de los tormanzanos... Se creen sigilosos, pero no lo son. Hazme el favor de matarlos. \n\nVeamos cómo te va peleando.", t = "Haz algo útil"},
    [92683] = {ot = "Recoge 5 montículos de polvo de alabatiente de las alabatientes que se encuentran en los Bajíos Ventobaya.", st = "Seguro has visto las alabatientes gigantes que andan por los campos abiertos cerca del huerto, ¿verdad? Son bonitas, pero también tienen beneficios, como el polvo de sus alas. Puede ser un chiquero, pero si logras juntar una gran cantidad, puede ser útil para varias actividades domésticas.\n\nToma este mataalabatientes y dales un buen golpe a esos insectos gigantes. Normalmente se asustan y huyen, pero a veces se ponen ofensivas. De todas formas, van a agitar sus alas y dejarán un montón de polvo.", t = "Polvo de alabatiente"},
    [92684] = {ot = "Recoge 7 solomillos de zancavientos de los bajíos de los zancavientos enfurruñados de los Bajíos Ventobaya.", st = "Como si la cosecha no fuera ya bastante pobre este año, los zancavientos se estuvieron metiendo en el huerto a robar mis tormanzanas. ¿Podrás hacerme el favor de matar algunos?\n\nIgualmente, te advierto, $gforastero:forastera;: estos zancavientos de los bajíos son más grandes y belicosos que los de las tierras altas. Ten cuidado, una patada bien dada es todo lo que necesitan para partirte la cabeza si no prestas atención.\n\nDe paso, tráeme un poco de su carne y nos prepararé una buena comida caliente.", t = "Zancavientos enfurruñados"},
    [92685] = {ot = "Recoge 7 máscaras de bandido manchadas con sangre de bandidos bandoleros en los Bajíos Ventobaya.", st = "Los bandidos tienen campamentos por todos lados, pero en las colinas del norte hay uno pequeño. Ve allí y ponte a partir cráneos. Si los agarramos de sorpresa y los eliminamos antes de que vengan por nosotros, tal vez inclinemos el tablero a nuestro favor.\n\nTráeme sus máscaras. Cuanta más sangre tengan, mejor.", t = "Las colinas tienen ojos"},
    [92693] = {ot = "Habla con Aamelia Campo de Viento cuando estés $glisto:lista; para enfrentar al líder de los bandidos.", st = "Haz hecho mucho para darnos una posibilidad de luchar. Incluso si hoy morimos, al menos sabremos que lo dimos todo.\n\nEsta es tu última oportunidad, $gforastero:forastera;. Si quieres volver a Valanaar y vivir para contarlo, no te culpo.\n\nPor otro lado, si de verdad tienes una inclinación por las causas perdidas, no tienes más que avisarme cuando estés $glisto:lista;. Saldremos con la frente bien alta, y que pase lo que tenga que pasar.", t = "Inquebrantables"},
    [92698] = {t = "¿Cuál es mi propósito?"},
    [92699] = {ot = "Busca a Elaadrin Ventopar en Valanaar.", st = "Ahora que estás en Valanaar, seguro querrás ponerte en contacto con los demás miembros de la Suma Orden que se encuentran aquí. El magíster supremo actual, Elaadrin Ventopar, y su pueblo tienen una base en la cabaña situada en el extremo sureste de Valanaar.\n\nDebes tener cuidado: la Suma Orden y los Formavientos no se llevan muy bien por estos lares. Sé prudente y evita a toda costa el contacto con los Formavientos. Ya tenemos suficientes problemas con el culto, y no toleraré la violencia entre facciones en las calles de Valanaar.", t = "El magíster supremo"},
    [92700] = {ot = "Busca a Ayessa Cantoalba en Valanaar.", st = "Ahora que estás en Valanaar, seguro querrás ponerte en contacto con los demás miembros de los Formavientos que se encuentran aquí. La Gran Vidente del Cielo actual y su pueblo tienen su base en la cabaña situada cerca del centro de Valanaar.\n\nTambién debes saber que los Formavientos y la Suma Orden no se llevan muy bien. Ten cuidado y mantente lejos de la Suma Orden. Ya tenemos suficientes problemas con el culto, y no toleraré violencia entre facciones en las calles de Valanaar.", t = "La Gran Vidente del Cielo"},
    [92701] = {ot = "Entrega el informe por escrito de Aonda a Valennia Puñotormenta en Valanaar.", st = "Por el momento, parece que el pilar y la aldea están a salvo, así que me gustaría que le entregaras este informe a Valennia Puñotormenta en Valanaar, en el límite sureste de la isla. Ella es la líder de los pacificadores de la isla y necesita saber lo que sucedió aquí.\n\nEl culto se está expandiendo rápidamente y los pacificadores han logrado evitar el conflicto directo hasta ahora, pero no creo que puedan hacerlo más. Valanaar tendrá que prepararse para la batalla.\n\nEn cualquier caso, gracias por todo. Nunca estarás $gsolo:sola; en Shen'dar, $n.", t = "A Valanaar"},
    [92703] = {ot = "Habla con Alvarion Campo de Viento en Valanaar.", st = "Creo que ya no está muy bien seguir llamándote $gextraño:extraña; después de todo este tiempo... Gracias, $n. \n\nSi no te molesta y te queda de paso cuando vuelvas, hazme el favor de contarle a Alvarion todo lo que pasó aquí. También dile que, cuando se recupere, tendrá que traer a un formavientos para que revise ese ensamblaje y compruebe que es seguro tenerlo cerca de nuestra... nuestra familia.\n\n<Aamelia se toca el vientre con delicadeza.>\n\nÉl no sabe de esto. Que por ahora siga siendo un secreto entre $gnosotros:nosotras; dos.", t = "Entrega de noticias"},
    [92706] = {ot = "Llévale la aleta dorsal de Bruuz a Gazlowe en Trinquete.", st = "¡Atención, pescadores!\n\nUn tiburón gigante merodea las aguas cerca del muelle, atacando marineros y pequeñas embarcaciones. Los trabajadores de embarcadero lo han apodado \"Bruuz\". Se otorgará una generosa recompensa a quien me traiga su aleta.\n\n— Gazlowe", t = "SE BUSCA: Bruuz"},
    [92708] = {ot = "Escucha lo que Ayessa Cantoalba tiene para decir.", st = "Los Formavientos han estado muy ocupados intentando hacer frente a la crisis actual en Isla Zephras. En nuestra búsqueda de los espíritus de viento perdidos, hemos hecho muchos descubrimientos sorprendentes, y estamos desarrollando un plan de acción que podría ayudarnos a obtener los medios para salvar a la isla.\n\nNecesitaremos a aventureros jóvenes y fuertes como tú para este trabajo. Si tienes un momento, permíteme darte más detalles.", t = "Una gran aventura"},
    [92709] = {ot = "Escucha lo que Elaadrin Ventopar en Valanaar tiene para decir.", st = "Tu linaje altonato brilla en tus ojos con tanta claridad como el cielo que nos cubre. Eres $Guno:una; de nosotros, y son los jóvenes como tú los que nos ayudarán a salvar nuestro hogar. Pero primero, déjame que te cuente un poco más sobre nuestra misión y nuestros planes aquí en Zephras... y más allá.", t = "Una gran aventura"},
    [92727] = {ot = "Descubre qué le ocurrió a Fillion Brisallama.", st = "La búsqueda de conocimiento es el mandato principal de la Suma Orden, pero ahora, en Zephras, este trabajo es más peligroso que nunca.\n\nUno de nuestros eruditos, Fillion Brisallama, emprendió un viaje a las Tierras Altas de Shen'dar para recopilar información sobre la magia natoviento que se concentra en algunas áreas de allí. Por desgracia, no ha regresado y tememos que le haya ocurrido algo en el camino.\n\nBúscalo si puedes. La última vez que se lo vio, iba por el camino al oeste de Valanaar hacia las Tierras Altas de Shen'dar.", t = "El erudito desaparecido"},
    [92741] = {ot = "Viaja al Bosque Ventarrosombra y recoge 8 garfas de chillín para Iaadaria Vientoglacial en Valanaar.", st = "El Bosque Ventarrosombra es extremadamente peligroso y el ingreso suele estar prohibido para los aventureros comunes y corrientes. En los últimos meses, la población de chillines ha aumentado de forma preocupante y han empezado a expandir su territorio fuera del bosque. Como podrás imaginar, esto supone un problema. Sin embargo, tengo interés en las propiedades alquímicas de las garfas de chillín, así que el sacrificio tan necesario de estas bestias puede ser beneficio para fines intelectuales.\n\nViaja al Bosque Ventarrosombra y caza a las bestias. Tráeme la mayor cantidad de garfas que puedas.", t = "Visitantes inoportunos"},
    [92742] = {ot = "Utiliza el kit de muestra de agua de pozo para recoger muestras de los pozos que hay en la Finca de Jansen y la Granja de Molsen.", st = "Debemos determinar el origen y la naturaleza del veneno que corrompe estas tierras. Comencemos con las aguas que hay debajo de las granjas de esta zona.\nVe a la Finca de Jansen y a la Granja de Molsen y recoge muestras de sus pozos de agua.", t = "Pruebas en los pozos"},
    [92744] = {ot = "Alba Lunaclara quiere que reúnas 7 branquias de múrloc de Playa Larga en las costas de Páramos de Poniente.", st = "La corrupción que afecta los cultivos de Páramos de Poniente ha llegado al océano. Si los peces locales terminan afectados, Ventormenta estaría condenada a morir de hambre.\nRecolecta branquias de los múrlocs a lo largo de la costa y tráemelas. Los múrlocs son bastante resistentes, pero su fisiología es muy sensible a los contaminantes. Cualquier toxina que haya en el agua será claramente visible en sus branquias.", t = "Branquias de múrloc"},
    [92745] = {ot = "Mata a 4 cavadores kóbold en la Mina de Jango y a 6 mineros Zarparrío en la Mina de la Costa del Oro.", st = "¡Las muestras que recogiste de los pozos contienen metales tóxicos! Si no erradicamos rápido la corrupción, no se podrá cultivar en este suelo durante décadas.\nLos Defias tomaron las minas de Páramos de Poniente y utilizan a criaturas como mano de obra para obtener sus recursos. Mata a los mineros en la Mina de Jango, al norte, y en la Mina de la Costa del Oro, al oeste, para interrumpir sus actividades.", t = "La cuestión de las minas"},
    [92747] = {ot = "Reúne 8 suministros industriales sospechosos en Arroyo de la Luna.", st = "Qué extraño... El veneno no parece venir de las minas que investigaste.\n\nTengo entendido que las Minas de la Muerte, debajo de Arroyo de la Luna, son las más grandes y profundas de los Páramos de Poniente, pero están abandonadas desde la Primera Guerra. ¿Acaso las Minas de la Muerte están activas otra vez?\n\nPor favor, dirígete a Arroyo de la Luna, $n, y busca pruebas de actividades industriales o mineras. ¡Esta es la última pista que tenemos!", t = "Espionaje en Arroyo de la Luna"},
    [92748] = {ot = "Viaja al Distrito de los Enanos en Ventormenta y encuentra un ingeniero que pueda ayudar.", st = "Los suministros que encontraste sugieren un operativo industrial masivo en algún lugar de las Minas de la Muerte. No hay dudas de que este es el origen de las toxinas que infestan los cultivos de los Páramos de Poniente. Debemos detenerlo ahora.\n\nSerá difícil destruir lo que sea que haya allá abajo. Ve al Distrito de los Enanos de Ventormenta y encuentra a un ingeniero que nos suministre explosivos.", t = "Consulta explosiva"},
    [92749] = {ot = "Consigue 10 fragmentos de dinamita burda a través de la fabricación, el comercio o la casa de subastas. Luego, regresa con Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta.", st = "¿Sabotaje industrial? ¡Ahora tienes mi atención!\nComenzaremos con algo de dinamita...", t = "Un plan explosivo"},
    [92750] = {ot = "Habla con alguien en la Inteligencia de Ventormenta acerca de adquirir un detonador a distancia.", st = "Supongo que buscas una explosión \"controlada\", ¿no? No es muy divertido, pero es una buena opción si quieres conservar todos tus miembros.\nMe temo que me falta un detonador a distancia. ¿Por qué no le preguntas a la gente de la Inteligencia de Ventormenta? Seguro pueden conseguirnos algo.", t = "Detonación a distancia"},
    [92751] = {ot = "Llévale el kit de detonación a distancia a Duendy Ruedadentada en el Distrito de los Enanos de Ventormenta.", st = "¿Necesitas destruir algo? ¿Tendrá algo que ver con tus actividades en Arroyo de la Luna? No debería sorprenderte que IV:7 esté al tanto de todo lo que ocurre en las tierras de Ventormenta.\nSi planeas causar una explosión en las cuevas debajo de Páramos de Poniente, querrás alejarte lo más que puedas antes de hacerlo. Toma este detonador a distancia, es un prototipo reciente creado por nuestros ingenieros.\nAh, y será mejor que no le comentes nada sobre mi colaboración a tu amiga elfa.", t = "Detonación a distancia"},
    [92752] = {ot = "Regresa con Alba Lunaclara en Páramos de Poniente.", st = "Muy bien, ¡la bomba está lista! Cuidado con este detonador.", t = "Consulta explosiva"},
    [92753] = {ot = "Busca La Forja oculta en las Minas de la Muerte y coloca los explosivos devastadores cerca de ahí. Luego, reúnete con Alba Lunaclara en la salida de las Minas de la Muerte.", st = "Es probable que la fuente del veneno sea algún tipo de forja metalúrgica grande. Busca la manera de entrar a las Minas de la Muerte, localiza la forja y luego coloca los explosivos.\nTe esperaré en las colinas detrás de Arroyo de la Luna. Cuando vuelvas, podremos detonar los explosivos. Una vez que la Forja haya desaparecido, la tierra comenzará a sanar.", t = "Destrucción en las Minas de la Muerte"},
    [92819] = {ot = "Utiliza el detonador.", st = "Casi terminamos. Utiliza el detonador y ponle fin a esto.", t = "Destrucción en las Minas de la Muerte"},
    [92834] = {ot = "Recoge 10 talismanes de piedra de viento Al'Aketh de los cultores Al'Aketh al norte de Valanaar, en los Campos Ventobaya o en el Santuario de Akir.", st = "Cuando el culto empezó su campaña de violencia, los pacificadores y los Formavientos respondieron con provocación. Me pareció que era una intensificación innecesaria del conflicto, por lo que propuse tener un diálogo pacífico. Ayer, envié a mi amigo Belathaan Deseoalegre al Santuario de Akir con la esperanza de establecer el diálogo.\n\nAcaba de llegar una caja con la lengua de Belathaan bañada en pigmento plateado. \n\nEstá claro que es imposible razonar con el culto. Mata a cualquier cultor que veas y tráeme sus talismanes de plegarias.", t = "La venganza será diez veces peor"},
    [92840] = {ot = "Lleva el Index Esoteria a las Piedras Erguidas del Mirador en las Tierras Altas de Shen'dar y úsalo para recopilar información en las formaciones de piedra de viento.", st = "Fillion partió hacia las Piedras Erguidas del Mirador con un dispositivo especial destinado a medir y estudiar la energía elemental presente en el lugar.\n\nLleva contigo este Index Esoteria, y úsalo para extraer datos de las enormes formaciones de piedra de viento que se alzan allí. Mantente alerta, pues es probable que los Formavientos custodien este sitio con fanática devoción.\n\nY si alguien intenta interponerse en tu camino... bueno, haz lo que sea necesario. Ya no tengo más paciencia para sus intromisiones.", t = "Vientos combativos"},
    [92849] = {ot = "Sigue buscando a Fillion Brisallama.", st = "<A juzgar por tus hallazgos, es muy probable que Fillion haya sufrido alguna desgracia aquí. Puede que aún esté cerca y que necesite ayuda. Vislumbras una cueva justo al norte de tu ubicación actual. Deberías continuar tu búsqueda allí.>", t = "El erudito desaparecido"},
    [92850] = {ot = "Mata a la matriarca chillín en la guarida de chillines y luego llévale su cabeza a Fillion Brisallama en Valanaar.", st = "Ya me siento mucho mejor. Soy hábil con las artes arcanas, y no estamos muy lejos de Valanaar. Puedo llegar por mi cuenta. Pero hay algo más importante que mi propia seguridad: estos chillines se han anidado muy cerca de Valanaar, por lo que suponen un peligro. Si eres tan amable, ¡vuelve a la cueva y córtale la cabeza a esa bestia!\n\nVen a verme cuando termines; estaré con Dondallion en Valanaar. Tengo que regresar con él cuanto antes. Debe estar hecho un manojo de nervios.", t = "El erudito desaparecido"},
    [92860] = {ot = "Preséntate ante Valennia Puñotormenta y dile que la Suma Orden está de su lado en la lucha contra los Al'Aketh.", st = "La Suma Orden ha hecho lo posible para evitar el conflicto directo con el culto, pero está claro que esa ya no es una opción viable. Han demostrado su postura hostil, y ahora hay rumores de que la actividad de los cultores se esparció por toda la isla. Es evidente que se están preparando para algo que afectará negativamente a los habitantes de Zephras.\n\nPreséntate ante Valennia Puñotormenta e infórmale que la Suma Orden ofrece toda la ayuda que Valanaar necesite para repeler a Al'Aketh.", t = "Al servicio de Zephras"},
    [92871] = {ot = "Preséntate ante Valennia Puñotormenta y dile que los Formavientos están de su lado en la lucha contra los Al'Aketh.", st = "Valennia Puñotormenta y sus pacificadores siempre han sido los protectores de Zephras, y hemos hecho todo a nuestro alcance para ayudar donde podamos. Hay rumores de que el culto está realizando movimientos de gran magnitud por la isla, y es evidente que están preparándose para algo.\n\nPreséntate ante Valennia y repítele que, si lo necesitan, los Formavientos están dispuestos a colaborar con la defensa de Valanaar contra los Al'Aketh.", t = "Al servicio de Zephras"},
    [92880] = {ot = "Llévale el informe de Yorna a Valennia Puñotormenta en Valanaar.", st = "Sospecho que nos llevará algo de tiempo acabar con los atacantes que quedan, pero ahora soplan vientos propicios. Vuelve a Valanaar y diles que la situación aquí es estable.\n\nNo alcanzan las palabras para agradecerte por la ayuda. No sé qué hubiera sido de nosotros sin ti. Pedí refuerzos y, en su lugar, me enviaron a $gun héroe:una heroína;. No podría haber pedido algo mejor.\n\nQue los Cuatro Vientos te bendigan, $c.", t = "Regreso a Valanaar"},
    [92881] = {ot = "Habla con Talaanis Cantosombrío en Valanaar.", st = "Los ataques a las torres de vigilancia occidental y oriental no son una coincidencia. Según lo que nos contaste sobre lo ocurrido en la torre occidental con ese sacerdocielo, lo más probable es que el culto esté intentando hacerles algo a los pilones de anclaje.\n\nHabla con el gran ancestro Cantosombrío. Él te dirá todo sobre una pista que parece prometedora.", t = "El pedido del gran ancestro"},
    [92909] = {ot = "Ozwin Piñón de Hierro, en la Finca de Saldean, quiere que consigas 14 isorresortes de gólem y 5 giroestabilizadores de cosechador.", st = "Ay, no... ¡Ahora sí que estoy en problemas!\n\nEscuché que los cosechadores estaban aterrorizando los campos de Páramos de Poniente, así que viajé desde Forjaz para recalibrarlos. ¡Pero están más agresivos de lo que había calculado y me acorralaron en este establo!\n\nSi tuviera algunos isorresortes y giroestabilizadores de los cosechadores, podría construir un dispositivo para cubrir mi escape. ¿Podrías reunir las partes por mí?", t = "Cosechar a los cosechadores"},
    [92910] = {ot = "Llévale el ensamblaje autocognitivo de precesión a Ozwin Piñón de Hierro en la Finca de Saldean.", st = "La parte que lograste rescatar del cosechador parece estar casi intacta. Podría interesarle a alguien que sepa de gólems de la cosecha.", t = "Cosechar a los cosechadores"},
    [92911] = {ot = "Ozwin Piñón de Hierro, en la Finca de Saldean, quiere que consigas 8 isorresortes de gólem, 4 moduladores de cobre y una mira rudimentaria.", st = "Ya veo... Esto me ayuda a entender cómo funcionan esos monstruos. Se me ocurre cómo podemos anular sus sistemas, al menos temporalmente.\n\nContinuaré jugando con el ensamblaje que me trajiste. Mientras tanto, ¿podrías mendigar algunas partes para el dispositivo?", t = "Cosechar a los cosechadores"},
    [92947] = {ot = "Mata a $1oa guardianes Al'Aketh, $2oa clamaespíritus Al'Aketh y $3oa maestros del acero Al'Aketh, y luego preséntate ante Hyusaa Ventirraudo en el Santuario de Akir.", st = "Estamos todos, bien. Envié a algunos de mis mejores luchadores al frente del santuario para que causen un poco de caos y sirvan como distracción mientras yo conduzco a los Formavientos y a la Suma Orden desde el flanco.\n\nSi todo sale bien, podremos atravesar rápidamente sus filas y eliminar a la suma sacerdotisa. Ve allí y empieza a partir cráneos. Reúnete con mi mano derecha, Hyusaa Ventirraudo, cerca de las escaleras del santuario después de hacer lo tuyo.\n\nQue los vientos te guíen, $c.", t = "Nuestro movimiento"},
    [93036] = {ot = "Habla con Sania Brisargenta en la Aldea Shen'dar.", st = "Desconozco si lo sabes, pero Sania Brisargenta, que está ahí, es una \"misionera\" de los Al'Aketh. Les gusta hacerse pasar por una orden religiosa normal y envían a emisarios pacíficos a todas partes para reclutar adeptos. Hasta ahora, hemos tolerado la presencia de Sania para evitar un conflicto directo con el culto, pero es evidente que la ilusión de paz no durará mucho más.\n\nEres $gnuevo:nueva; aquí y la mayoría no te conoce, así que me gustaría ver si puedes acercarte al culto por medio de Sania y averiguar cuáles son sus intenciones con la aldea.", t = "Infiltrarse en el culto"},
    [93065] = {ot = "Habla con Valennia Puñotormenta en los Bajíos Ventobaya.", st = "Los pacificadores se están movilizando y nosotros nos estamos equipando para marchar. Haz los preparativos que tengas que hacer, y veámonos en el camino del este que lleva al norte del pueblo. Haremos una última verificación con todos antes de seguir para asegurarnos de que esté todo en orden.", t = "Preparación para la batalla"},
    [93089] = {ot = "Habla con Elaadrin Ventopar cuando estés $glisto:lista; para abandonar Isla Zephras.", st = "Por favor, transmítele mi agradecimiento a Elaadrin por todo lo que la Suma Orden y sus nuevos amigos de este \"Kirin Tor\" han hecho por Isla Zephras. Estoy al tanto del plan de la Suma Orden para abandonar esta isla, y cuentan tanto con mi bendición como con mis buenos deseos para la expedición.\n\nSolo puedo esperar que cualquier solución arcana que encuentre la Suma Orden nos brinde la estabilidad de la que hemos carecido estos años. Si piensas ir con ellos... bueno, entonces no hay dudas de que su misión será un éxito.\n\nQue los vientos te acompañen, $n.", t = "Los próximos pasos"},
    [93090] = {ot = "Habla con Ayessa Cantoalba cuando estés $glisto:lista; para abandonar Isla Zephras.", st = "Por favor, transmítele mi agradecimiento a Ayessa por todo lo que los Formavientos y sus nuevos amigos de este \"Anillo de la Tierra\" han hecho por Isla Zephras. Estoy al tanto del plan de reunir a los chamanes Formavientos y abandonar esta isla, y tu orden cuenta tanto con mi bendición como con mis buenos deseos para esta expedición.\n\nSolo puedo esperar que cualquiera sea la solución que los Formavientos encuentren, nos brinde la estabilidad de la que hemos adolecido estos años. \n\nQue los vientos te acompañen, $n.", t = "Los próximos pasos"},
    [93159] = {ot = "Habla con el ermitaño extraño en el Bosque Ventarrosombra y averigua más sobre él.", st = "Eh, em... Ho... A ver... ¡Hola! Perdón... ehm, hacía mucho tiempo que no hablaba con otra persona. Ahora estoy un poco oxidado.\n\n<La extraña figura encapuchada se estremece con incomodidad frente a ti.>\n\nBueno, em... ¿Cómo estás?", t = "El ermitaño extraño"},
    [93160] = {ot = "Recoge $1oa bellotas Ventarrosombra en el Bosque Ventarrosombra.", st = "¡Te agradezco que hayas pasado a charlar conmigo! S... Si quieres ayudar, me vendría bien una mano para juntar bellotas del suelo del bosque. Recogí la mayoría de las que están aquí cerca, pero en el bosque hay una especie de pájaros raptores. ¡Está peligroso ahí afuera y no quiero convertirme en el almuerzo de un ave gigante!\n\nAsí que si quieres, ¿podrías recogerlas por mí? ¡Prepararé algo delicioso a cambio!", t = "La abundancia del bosque"},
    [93165] = {ot = "Recoge 10 orejas de cultor Al'Aketh de los cultores Al'Aketh en el Bosque Ventarrosombra, el Santuario de Akir o los Bajíos Ventobaya.", st = "Los Al'Aketh han provocado una gran tragedia sobre nuestro enclave, y la sangre debe pagarse con sangre.\n\nTengo una oferta para hacerte, $gforastero:forastera;. Si hay algún conflicto con estos endemoniados cultores, tráeme las orejas de los que mates. Te daré dinero a cambio de cada una que taigas y, cuando sea el momento, también te daré acceso a los secretos de los Garra Nocturna si demuestras ser $gun verdadero aliado:una verdadera aliada;.", t = "La piedad cae en oídos sordos"},
    [93172] = {ot = "Destruye 10 hoyas del viento en el Bosque Ventarrosombra.", st = "Parece que la mayoría de los elfos de esta isla creen que este bosque está encantado, y están en lo cierto.\n\nEn las viejas ruinas del noreste, se reúne una clase extraña de espíritus fantasmales. Algunas noches, casi que se los puede oír \"cantar\". Es distinto a cualquier canción que escuché, pero es definitivamente una canción, y es... muy triste.\n\nNo sé por qué, pero creo que en algún momento pasó algo terrible ahí, y estos espíritus están atrapados de algún modo. Si te sientes valiente, tal vez puedas ayudarlos a que sean libres.", t = "Libera la hoyas"},
    [93317] = {ot = "Recoge 6 trozos de carne de reptador de Son del Viento.", st = "¿Has oído hablar de los reptadores de Son del Viento? Verás, son unos cangrejos que solo habitan en el lago Son del Viento, aquí en Zephras. Solo es posible recolectarlos durante unas pocas semanas al año.\n\nÚltimamente, con el aumento de actividad cultora, no he podido ir al lago para recolectarlos, y el tiempo ya casi se agota. Te agradecería si pudieras ir allí y atrapar algunos. Por lo general, se encuentran a lo largo de la orilla del lago y en los ríos.\n\nPero ten cuidado. ¡Son más agresivos de lo que aparentan!", t = "Temporada de cangrejos"},
    [93318] = {ot = "Mata a Vulgara, la Insaciable, en las Tierras Altas de Shen'dar y llévale la cabeza a Danarii Velobramido.", st = "Por orden de la agente Aonda, de los pacificadores, ofrecen una recompensa por la captura de Vulgara, la Insaciable, el azote de las tierras altas. Se la vio por última vez en una colina al suroeste de la Aldea Shen'dar. Es una terrorífica vuldren alada y muy peligrosa, y hay que acercarse a ella con mucha precaución.\n\nEntrega la cabeza de la bestia a Danarii Velobramido para recibir tu recompensa.", t = "SE BUSCA: Vulgara, la Insaciable"},
    [93319] = {ot = "Consigue 10 piedras de viento saqueadas de los bandidos de las Tierras Altas de Shen'dar.", st = "Cada vez dependemos más de las piedras de viento para nuestra vida cotidiana en Zephras, por lo que intentamos mantener una reserva para casos de emergencia. Estos últimos días noté que faltan algunas de nuestros depósitos.\n\nEncontramos piedras de viento en los bandidos que atrapamos hace poco, y sospecho que ellos son los responsables de nuestra escasez.\n\nSi te encuentras cerca de la cueva de los bandidos al norte, ¿te importaría darles una paliza a unos cuantos y traerme algunas de nuestras piedras de viento robadas?", t = "Piedras de viento saqueadas"},
    [93320] = {ot = "Preséntate ante Yorana Junco Alabeado en la torre de vigilancia oriental, en los Bajíos Ventobaya.", st = "¡He recibido novedades de que el culto está atacando la torre de vigilancia junto al pilón, en las afueras de la ciudad! Envié a los pocos pacificadores que quedan aquí para intentar romper la retaguardia del enemigo y asistir a los defensores, pero cualquier ayuda adicional podría hacer la diferencia entre la vida o la muerte de los nuestros.\n\nPor favor, ve a la torre oriental de inmediato y asístelos como puedas.\n\nMi teniente, Yorana Junco Alabeado, lideró a la fuerza de auxilio. Si aún está con vida, te dirá cómo puedes ser útil.", t = "Defensa de la torre"},
    [93461] = {ot = "Habla con Rathiril Lanzasol y Coriella Brisacalma en la Aldea Shen'dar.", st = "Tienes ese aire de Suma Orden. Los descendientes de los altonato tienen un brillo especial en los ojos que los delata. Antes de ponerte a trabajar aquí, deberías hablar con Rathiril Lanzasol, veterano de la Suma Orden. Lo encontrarás muy cerca, en la cabaña principal, a la vuelta de aquí.\n\nAh, y también habla con Coriella Brisacalma, que administra la posada local y puede proporcionarte alojamiento y suministros si necesitas.", t = "Bienvenida a la Aldea Shen'dar"},
    [93552] = {ot = "Recoge 15 cúmulos de piedras de viento a partir de piedras de viento en bruto en Arboleda Thendal.", st = "Las piedras de viento son un recurso fundamental en Isla Zephras, ya que contienen la energía pura y concentrada de los propios vientos. Los elementales de viento que solían vivir aquí en Zephras con nosotros desaparecieron hace varios siglos, y desde entonces, la magia que sustenta esta isla se está desvaneciendo lentamente. Aunque no están exentas de limitaciones, las piedras de viento siguen siendo una fuente de energía confiable y son increíblemente valiosas para nosotros.\n\nEncontrarás piedras de viento en bruto esparcidas por el bosque, ¿puedes ayudarme a recolectarlas?", t = "Recolectar piedras de viento"},
    [93680] = {ot = "Consigue la llave de las cloacas de Dalaran y dásela a Magus Wordeen Vacuamirada en el Molino Tarren.", st = "La Alianza tenía un ejército de magos conocidos como el Kirin Tor. Aunque eran poderosos, la diabólica Legión Ardiente demostró tener aún más poder. De un solo golpe, el archidemonio Archimonde arrasó con su ciudad como si fuera un simple juego de niños. Aquellos que sobrevivieron se convirtieron en simples vagabundos desposeídos.\n\nAsí fue hasta que reconstruyeron Dalaran. ¡Y nada menos que bajo las propias narices de la Dama Oscura!\n\nMientras estén en sus campamentos, busca algo que nos permita entrar en la ciudad desapercibidos. Necesito saber más.", t = "Llave de la ciudad"},
    [93735] = {ot = "Busca a Riaani Nochebrisa en el lado oeste de Valanaar.", st = "Históricamente, los Formavientos se han ocupado de cuidar de los instrumentos y dispositivos mágicos que los espíritus del viento nos concedieron. Esto incluye los cientos de ensamblajes mágicos de la isla. Desde que los espíritus nos dejaron, solo quedan unos pocos en funcionamiento.\n\nUno de ellos se encuentra en Valanaar y ha sufrido daños. Hemos enviado a un artesano para que ayude, pero puede que necesite una mano. Viaja al extremo oeste de la ciudad y bríndale la ayuda que puedas.", t = "El ensamblaje averiado"},
    [93736] = {ot = "Recoge 10 esencias de hoya del viento de las hoyas del viento en el Bosque Ventarrosombra.", st = "La principal preocupación de los Formavientos es comprender mejor por qué los espíritus nos abandonaron, y qué es lo que podríamos hacer para recuperarlos. Hay una curiosidad en el norte del Bosque Ventarrosombra; una forma curiosa de duende de viento que algunos llaman \"hoyas\". Sabemos muy poco de ellas y por qué vinieron, pero lo que sí sabemos es que comenzaron a aparecer después de que los espíritus del viento nos dejaron.\n\nTienes que ir ahí y dispersarlas. Recoge los restos y tráemelos.", t = "Espíritus no deseados"},
    [93737] = {ot = "Habla con Rianni Nochebrisa y escúchalo con atención.", st = "Ah, hola. ¿Ayessa te envió a ayudarme? Muy bien. \n\nNo sé qué podría hacer $gun novato:una novata; como tú, pero si esperas a que saque la cabeza de las tuercas de este ensamblaje, tal vez se me ocurran una o dos cosas que podrían servirme.", t = "El ensamblaje averiado"},
    [93738] = {ot = "Vuelve con Ayessa Cantoalba en Valanaar.", st = "Deseoalegre, ¿eh? Así que la Suma Orden quería llevarse estos componentes por algún motivo. ¿Pero cuál?\n\nLa Suma Orden siempre ha estado llena de entrometidos que constantemente quieren experimentar con la magia de los espíritus de viento. No respetan nada, y les hemos prohibido estrictamente que hurguen en conocimientos que son propiedad de los Formavientos, pero últimamente han estado jugando con nuestra paciencia. \n\nCreo que deberías informar a Ayessa Cantoalba lo que has descubierto. Ella podrá darte instrucciones más precisas.", t = "El ensamblaje averiado"},
    [93740] = {ot = "Recoge 10 talismanes de piedra de viento Al'Aketh de los cadáveres de cultores Al'Aketh en los Bajíos Ventobaya.", st = "Han encontrado muertos a varios de nuestros novicios Formavientos en las Tierras Altas esta mañana. Aunque no tengamos certezas, es muy posible que los Al'Aketh sean los responsables. Los Formavientos cobramos sangre con sangre, siempre.\n\nVe al norte y mata a todo Al'Aketh que encuentres. Tráeme sus talismanes de plegarias de piedra de viento como prueba. No olvidamos, ni perdonamos.", t = "Sangre por sangre"},
    [93746] = {ot = "Enfrenta a Belthaan Deseoalegre en el camino al Santuario de Akir.", st = "La Suma Orden ha sido advertida de las consecuencias de entrometerse en los asuntos de los Formavientos. Creo que tenemos que usar a Belathaan como ejemplo y enviarlo de regreso a la Suma Orden con algunos moretones y un respeto adecuado por los límites que hemos establecido.\n\nVieron a Belathaan yéndose del pueblo, con rumbo norte hacia el Santuario de Akir. No sé con qué objetivo, pero puede que lo mejor sea enfrentarlo solo en el camino. Búscalo e infunde un poco de temor en su corazón.", t = "Una respuesta firme"},
    [93791] = {ot = "Habla con Belann Vientosauco en Valanaar.", st = "$n, es claro que tu habilidad con la magia está creciendo y, por lo tanto, creo que es hora de que participes en una de las tradiciones más antiguas de la Suma Orden para los jóvenes aspirantes a mago. Llegó el momento de crear tu propio enfoque de hechizo.\n\nBusca a Belann Vientosauco en Valanaar. Ha creado bastones y varitas para la Suma Orden durante más de cien años, así que estarás en buenas manos.", t = "Habla con Belann."},
    [93797] = {ot = "Lévale una rama infundida con el viento a Belann Vientosauco, en Valanaar.", st = "Es una tradición muy respetada que los jóvenes magos creen su propio enfoque de hechizo una vez que demuestran cierto dominio de la magia. Por lo general, el primer paso es recoger una rama caída de nuestros árboles más antiguos, ya que conservan vestigios de viento elemental.\n\nEl lugar ideal para encontrarlas es cerca del santuario del viento, al sur del Poblado Falaath. Trae una rama grande y te explicaré las tradiciones mientras creamos tu enfoque de hechizo.", t = "Ramas al viento"},
    [93835] = {ot = "Cruza el portal a los Pináculos Rohashi en lo alto y únete a Elaadrin Ventopar y Ayessa Cantoalba en su enfrentamiento con la suma sacerdotisa Lorthuna.", st = "Lorthuna huyó a los pináculos a través de una suerte de portal. Ayessa y Elaadrin fueron tras ella. Fue hace apenas unos instantes.\n\nMe temo que recibí demasiados golpes y tendré que quedarme aquí. Cruza el portal, busca a Elaadrin y ayúdalos a detener a Lorthuna.\n\nA menos que la ayuda que Elaadrin y Ayessa dijeron que pedirían llegue pronto, estás $gsolo:sola; a partir de aquí. Buena suerte, $c.", t = "Enfrenta a Lorthuna"},
    [93836] = {ot = "Habla con Talaanis Cantosombrío en Valanaar.", st = "Muln me ha contado mucho de los señores elementales, y me temo que tenemos buenos motivos para sentir miedo de Al'Akir. Ahora que los resguardos que habían mantenido a Zephras oculto para sus ojos, estamos completamente indefensos. Si decide atacarnos, no tenemos oportunidad de vencerlo aquí, en sus propios dominios.\n\nEl gran anciano Cantosombrío tiene que saber del peligro en el que nos encontramos, y más importante aún, cuáles son nuestras intenciones para nuestra misión en Azeroth. Encontraremos los medios para salvar tu hogar, lo juro.", t = "El destino de Zephras"},
    [93926] = {ot = "Busca al pacificador Vaaniel en la torre de vigilancia occidental.", st = "Sea cual sea el motivo que impulsa al culto a atacar la torre, no vale la pena perder a nuestro pueblo por ello.\n\nQuiero que vayas al suroeste y verifiques el estado de esa torre de vigilancia. Busca a los pacificadores que estén ahí y diles que regresen a la aldea. Mantener esa torre no justifica las vidas que nos costaría y prefiero concentrar a los defensores que tenemos aquí con tal de proteger a nuestros ciudadanos.\n\nEl pacificador Vaaniel está al mando. Avísale que regrese aquí lo más pronto posible. ¡Date prisa!", t = "La avanzada occidental"},
    [93927] = {ot = "Recoge la nota que encontraste cerca del cadáver del pacificador y léela para decidir los siguientes pasos.", st = "<Mientras examinas el cadáver del pacificador, una nota ensangrentada se le cae de las manos. Si la recoges y la lees, tal vez encuentres una pista sobre cómo continuar.>", t = "Un último pedido"},
    [93948] = {ot = "Entrega el sello de la familia Cantosombrío a Talaanis Cantosombrío en Valanaar.", st = "Ya que irás a Valanaar de todos modos, llévale el sello que recuperaste de la torre a Talaanis Cantosombrío en Valanaar. \n\nEstoy segura de querrá recuperarlo y, lo más importante, querrá saber qué le ocurrió a su sobrino. Talaanis es el gran ancestro de Isla Zephras y, además, es un buen hombre muy querido por el pueblo, a pesar de las dificultades que atravesamos hoy en día. Me duele imaginar cómo tomará la noticia. Dale mis condolencias por su pérdida.", t = "Entrega el sello"},
    [93949] = {ot = "Mata saltanubes en Valanaar hasta que hayas eliminado a $1oa saltanubes encantados.", st = "Tenemos una plaga de insectos.\n\nEs temporada de saltanubes en los bajíos, lo que significa que están por todas partes. Uno de los magos de la Suma Orden dijo que uno de los insectos que mataron tenía algún tipo de encantamiento. Cuando lo examinamos de cerca, resultó que era un hechizo de audición.\n\nSospechamos que el culto está usando a estos insectos como espías. Ve a exterminarlos por nosotros. Es imposible que te des cuenta de cuáles están encantados, así que tendrás que matar a todos.", t = "Insectos infiltrados"},
    [93951] = {ot = "Consigue 8 plumones de hipogrifo de las Tierras Altas de Shen'dar.", st = "Los hipogrifos que se instalaron al suroeste de la aldea son un poco molestos, pero también ofrecen una oportunidad única de conseguir sus plumas. A muchos cielonato les encanta adornarse el cabello con péndolas vibrantes. Justamente, los plumones de los hipogrifos son muy llamativos y, sobre todo, suaves como la seda.\n\nSi vas por allí, recoge todas las plumas caídas que puedas de sus nidos y alrededores. Pero ten cuidado: los hipogrifos salvajes son bastante hostiles con los intrusos.", t = "Una pizca de belleza"},
    [93958] = {ot = "Habla con Valennia Puñotormenta dentro del sagrario interior del Santuario de Akir.", st = "Las fuerzas de Valennia irrumpieron en el sagrario interior. Al principio, la batalla fue intensa, pero ahora es... inquietantemente silenciosa. Ve allí y haz todo lo posible por reunirte con Valennia y sus fuerzas... si es que aún viven.\n\nEstaré aquí respaldándote.", t = "El Sagrario Interior"},
    [94003] = {ot = "Recupera el Baluarte Rompecielos de Zaal Tormentión en el Santuario de Akir.", st = "Soy todo lo que queda de la línea de los Rompecielos en Isla Zephras. Los demás fueron asesinados por los Al'Aketh.\n\nLo único más grande que mi dolor es la vergüenza que siento. El escudo ancestral de mi familia, el Baluarte Rompecielos, ahora está en manos de un cultor llamado Zaal Tormentión. De acuerdo a las tradiciones familiares, quien sea digno de portar este escudo no sufrirá ningún daño.\n\nZaal no es digno, de eso no tengo duda. Búscalo en el Santuario de Akir y arrebátale mi escudo. Si lo haces, te enseñaré la Defensa Rompecielos.", t = "El Baluarte Rompecielos"},
    [94006] = {ot = "Habla con Urs'endris cerca de la cascada al noreste de Valanaar.", st = "Saludos, $n. Creo que has progresado lo suficiente en tus estudios druídicos para conocer a uno de los grandes espíritus que residen en Zephras. Urs'endris es un espíritu sabio y noble que les ha enseñado a los druidas a tomar la forma ursera durante generaciones. Lamentablemente, su dominio ha comenzado a marchitarse y a denigrarse en el firmamento, como muchas otras áreas de Zephras.\n\nVe al noreste y búscalo cerca de la cascada que está a la sombra del Santuario de Akir. Él debería poder brindarte nuevas lecciones.", t = "El gran espíritu ursera"},
    [94013] = {ot = "Utiliza la fusta de doma para domar a un vuldren alfa en los Bajíos Ventobaya. Practica tus habilidades y después devuélvele la fusta de domador a Quel'ana Ventarrápido en Valanaar.", st = "Has regresado triunfante de la doma de dos bestias, así que ha llegado el momento de tu última prueba. Los vientos de Zephras portan noticias de retos mayores en el horizonte.\n\nToma esta fusta de doma y viaja a los Bajíos Ventobaya. Allí, logra domar a un vuldren alfa y demuestra tu dominio.\n\nCompleta esta lección y estarás $glisto:lista; para profundizar en el camino de los cazadores.", t = "Domesticación de bestias"},
    [94050] = {ot = "Habla con Quel'dora Ventarrápido en Valanaar.", st = "Ahora tienes la capacidad de domesticar una mascota, pero también debes adquirir las habilidades necesarias para amaestrarla. Para esto, no hay nadie mejor que mi hermana, Quel'dora. Ella te dará la habilidad para amaestrar a tu nueva mascota. \n\nVe con los vientos, joven $c.", t = "Domesticar la bestia"},
    [94369] = {ot = "Habla con Talaanis Cantosombrío en Valanaar.", st = "Ansirem me ha contado mucho de los señores elementales, y me temo que tenemos buenos motivos para sentir miedo de Al'Akir, ahora que los resguardos que habían mantenido a Zephras oculto han caído. Si el Señor del Viento decide atacarnos, no tenemos oportunidad de defendernos aquí, en sus dominios.\n\nEl gran ancestro Cantosombrío tiene que saber del peligro en el que nos encontramos, y más importante aún, cuáles son nuestras intenciones en nuestra misión en Azeroth. Encontraremos los medios para salvar nuestro hogar, lo juro.", t = "El destino de Zephras"},
    [94373] = {ot = "Llévale 2 colgantes de oso Peloescarcha a Teo Mazatormenta a Yunquemar.", st = "Sí, ha llegado el momento, joven chamán. Te has vuelto fuerte y firme, como la piedra bajo nuestros pies. Tomar el sendero del chamán demuestra que posees la sabiduría de la montaña, incluso antes de probar tu valía. Tienes la resistencia de la roca para caminar el sendero de la tierra.\n\nPero para ganarte su favor, debes enfrentarlo con honor. Al sur de aquí, los trols Peloescarcha habitan en una cueva.\n\nTráeme dos de los collares que portan, forjados con las garras de los osos Garrahielo. Entonces hablaremos más de tu destino.", t = "Llamado de la tierra"},
    [94374] = {ot = "Encuentra la piedra de espíritu y bebe la Sapta de tierra.", st = "Sí, la sapta es una bebida fabricada con magia que vincula nuestros espíritus con los elementos. Solo algunos chamanes conocen la receta, y no es para los débiles de voluntad. Si la bebes, verás lo que otros no. Eso sí, solo debe beberse en un lugar sagrado.\n\nVe al norte, a la piedra de espíritu que hay al final de un sendero oculto que sube la montaña. Bébela allí... y observa lo que la tierra tiene para mostrarte.", t = "Llamado de la tierra"},
    [94375] = {ot = "Lleva el cuarzo en bruto a Teo Mazatormenta a Yunquemar.", st = "Coge este cuarzo en bruto y llévaselo a Teo Mazatormenta como prueba de nuestro encuentro. Te hará un tótem, y este guijarro será su corazón. Puede parecer muy pequeño, pero descubrirás que el tamaño no importa, y que incluso las cosas más pequeñas pueden superar a otras.\n\nTen paciencia, $n. Sigue siendo fuerte. Y busca la sabiduría. Es todo lo que te pide la tierra. Al final te harás $guno:una; con ella... Respétala del mismo modo que ella te respeta a ti.", t = "Llamado de la tierra"},
    [94411] = {ot = "Mata a 6 aprendices de la Suma Orden en las Tierras Altas de Shen'dar.", st = "¡Ten cuidado! Encontramos a miembros de la Suma Orden en las inmediaciones de las piedras erguidas al norte del pueblo. Siempre les advertimos que no se entrometan en nuestros lugares sagrados, pero son cada vez más audaces y juegan con nuestra paciencia. Es hora de que demuestres tu determinación. Ve a esas piedras y dispérsalos.\n\nNo estoy a favor del derramamiento de sangre, pero haz lo que sea necesario para ahuyentarlos. Vuelve a verme cuando hayas terminado.", t = "Magos metiches"},
    [94413] = {ot = "Derrota a 6 videntes novatos Formavientos en las Tierras Altas de Shen'dar.", st = "La reciente aparición de las líneas ley en la superficie de Zephras ha tenido un impacto mayúsculo en nuestra orden. Ahora tenemos un acceso más directo y tangible a las energías que impregnan este lugar. Gracias a ello, hemos mejorado considerablemente nuestra comprensión de este tipo de magia.\n\nSin embargo, los Formavientos ven estas manifestaciones como cicatrices en la tierra que hay que \"sanar\". Esto supone un agravio para nuestra orden y es algo que no podemos tolerar.\n\nVe a la línea ley del bosque al suroeste y expulsa a los Formavientos que encuentres.", t = "Un agravio mágico"},
    [94414] = {ot = "Habla con Halaan Ojo de Halcón y pídele que te preste su don para ver el pilón de anclaje a lo lejos.", st = "Saludos, joven $n. A veces vengo aquí a contemplar el antiguo pilón de anclaje. Son los regalos de los espíritus de los vientos los que unen y mantienen nuestra isla en equilibrio. Sin embargo, últimamente su magia se ha vuelto inestable e irregular.\n\nNo parecen sufrir ningún mal. Su esplendor no cambió.\n\nSi quieres, puedo darte mi don para que lo compruebes tú $gmismo:misma;.", t = "Las anclas de Zephras"},
    [94427] = {ot = "Habla con Tanis Alisero en Entrañas.", st = "Una característica clave de los paladines es la búsqueda de la divinidad. No se trata de la búsqueda de la bondad, pero de la búsqueda del bien en sí, por el bien mismo. Todos hemos llegado a este lugar como consecuencia de una tragedia, de una forma u otra, y sería fácil perder esa gracia que nos ha definido como paladines en la vida.\n\nVe a Entrañas y busca a Tanis Alisero en el Barrio del Comercio. Allí necesitan ayuda, y un poco de gracia puede serles de gran utilidad.", t = "Una lección de divinidad"},
    [94434] = {ot = "Llévale 10 paños de lino a Tanis Alisero en Entrañas.", st = "Espera, ¿quieres ayudar? ¿Por qué un paladín querría ayudar a un mendigo como yo?\n\nBueno, supongo que podrías ser de utilidad.\n\nSe trata de mi esposa. Ella, bueno... se está desmoronando. De verdad lo digo. Los boticarios podrían coserla por completo y dejarla como nueva, pero están ocupados con los asuntos de la Dama Oscura y ninguno de ellos está disponible. Si logras traerme un poco de tela, tal vez pueda hacer una envoltura para resguardarla y mantener sus partes unidas mientras esperamos el regreso de los boticarios.", t = "Una lección de divinidad"},
    [94435] = {ot = "Regresa con Danitha Morr en el Fuerte de Bandarion.", st = "No entiendo por qué te desviarías de tu viaje para ayudarme, pero te lo agradezco. Si alguien te envió, dile que también se lo agradezco. Siempre encontrarás un amigo en Tanis Alisero, $c.", t = "Una lección de divinidad"},
    [94436] = {ot = "Habla con el Guardia de la Muerte Billmuth en el Fuerte de Bandarion.\n\nSi llegaras a extraviar tu Símbolo de la vida, puedes regresar con Danitha Morr para pedirle uno nuevo.", st = "Es momento de demostrar tu habilidad para canalizar uno de los regalos más grandes de la luz.\n\nEste objeto que te acabo de entregar se llama el Símbolo de la vida. Cuídate, ya que utilizar un talismán de la luz como este puede causar cierta incomodidad. La luz puede ser una anatema para la fuerza que nos creó, pero no deja de ser nuestra guía y aliada. El dolor nos trae esto a memoria.\n\nVisita al Guardia de la Muerte Billmuth que se encuentra abajo. Acaba de llegar y nos ha pedido que colaboremos. Muéstrales a él y a los Renegados de qué es capaz un paladín.", t = "Una lección de divinidad"},
    [94438] = {ot = "Usa el Símbolo de la vida para resucitar al Guardia de la Muerte Falgan en Vega Venerácnidas. \n\nSi pierdes tu Símbolo de la vida, vuelve junto a Danitha Morr para que te dé otro.", st = "Nos han enviado a Falgan y a mí en una misión para investigar la actividad escarlata en Vega Venerácnidas. Logramos escabullirnos y acercarnos a uno de sus campamentos para escuchar sobre las nuevas órdenes sobre el ataque a Rémol. Antes de que pudiéramos decidir qué hacer, pisé una rama y el ruido los alertó de nuestra presencia.\n\nFalgan me gritó para que corriera, así que corrí. Cuando me di cuenta de que no estaba conmigo, ya estaba a medio camino de Rémol. Seguro que ese valiente idiota se quedó atrás para quitármelos de encima.\n\nPor favor, encuentra a mi amigo y ayúdalo si puedes.", t = "Una lección de divinidad"},
    [94440] = {ot = "Recupera los planes de ataque de la Cruzada Escarlata que llevan los cruzados Escarlata y entrégaselos al Guardia de la Muerte Billmuth en la Guardia de Tyr.", st = "Estos cruzados Escarlata suelen llevar sacos con sus órdenes de despliegue. Sabemos que el ataque es inminente, pero si logramos recuperar esas órdenes, podemos alertar al resto de la Guardia de la Muerte y preparar una emboscada. \n\nSin duda, eres un paladín imponente. Mata a estas bestias Escarlata, recupera una copia de estas órdenes y entrégaselas al Guardia de la Muerte Billmuth. Él se encargará del resto.", t = "Una lección de divinidad"},
    [94441] = {ot = "Habla con Danitha Morr en la fortaleza de la Guardia de Tyr.", st = "Agradece a Danitha Morr de mi parte y dile que el resto de la Guardia de la Muerte sabrá sobre la hazaña que los paladines de la Guardia de Tyr realizaron por nuestro pueblo. \n\nTienes un gran futuro como paladín, y me enorgullece contar con guerreros como tú entre las filas de los Renegados. Que la Dama Oscura te proteja, $n.", t = "Una lección de divinidad"},
    [94449] = {ot = "Habla con Bruegs Sangrellamas en Dun Morogh.", st = "Hace mucho tiempo que no superas una prueba, $n. Eres paciente, sí, pero es hora de que conozcas el caos... y la destrucción. El llamado del fuego es estruendoso y, si estás $gdispuesto:dispuesta; a pagar el precio, hablará contigo.\n\nBusca a Bruegs Sangrellamas en el extremo oriental de las montañas. Vive en una cueva sobre la Avanzada de la Puerta Sur. Él sabrá si estás $glisto:lista; de verdad.", t = "La llamada del fuego"},
    [94465] = {ot = "Lleva la antorcha de la Llama Latente a Braldir Mantogrís en Loch Modan.", st = "Sí, tienes la fuerza para llevar el tótem de fuego, $gmuchacho:muchacha;, pero la fuerza no hará que estés $glisto:lista;.\n\nMás allá del Valle de los Reyes, en los peñascos de Loch Modan, hay un camino oculto que conduce a una de nuestras cumbres sagradas. Allí, Braldir Mantogrís protege el Santuario de la Llama Latente. \n\nLlévale esta antorcha como muestra de tus intenciones. Enciéndela en el blandón del santuario y regresa aquí para ganarte el tótem.", t = "La llamada del fuego"},
    [94466] = {ot = "Consigue 1 montón de alquitrán y 1 faltriquera de componentes para Braldir Mantogrís en Loch Modan.", st = "Bah, pero no viniste hasta aquí para escuchar mis historias, ¿cierto, $n? Buscas la llama eterna y el tótem de fuego.\n\nPrimero, necesitarás una sapta para vincular tu espíritu con la llama.\n\nYo puedo fabricarla, pero necesitaré dos cosas: alquitrán de los geománticos Ratatúnel que hay en las cuevas de kóbolds al norte, y la faltriquera de componentes de un vidente Rompecantos que acecha en las colinas del sur. Es peligroso, pero la llama lo vale.", t = "La llamada del fuego"},
    [94467] = {ot = "Derrota a la manifestación de fuego menor y coloca las ascuas ardientes sobre el altar de la llama eterna.", st = "La sapta de fuego está lista, $n. Ahora, enfréntate a la llama. Utilízala en el santuario y asciende a la cima. Allí, verás al espíritu. No te atacará hasta que tú lo hagas, pero sabrá que lo observas.$B$BTienes que hacerlo rápido, $gmuchacho:muchacha;. Mientras más esperes, con más fuerza arderá. Cuando caiga, toma sus ascuas resplandecientes y colócalas en el blandón. Enciende la antorcha y gánate el favor del fuego.", t = "La llamada del fuego"},
    [94468] = {ot = "Lleva la antorcha de la llama eterna a Bruegs Sangrellamas en Dun Morogh.", st = "Con la antorcha firmemente sujeta, te alejas del blandón y diriges la vista sobre Loch Modan. Sientes una excitación creciente que tira de tu espíritu a la vez que el viento agita la llama y la hace bailar con violencia.$B$BEmprendes el camino de regreso a Dun Morogh en busca de Bruegs Sangrellamas.", t = "La llamada del fuego"},
    [94484] = {ot = "Busca a Elegael Zarzaspina y habla con él en la zona noreste del Bosque Ventarrosombra.", st = "Si no es mucha molestia, ¿tienes un minuto, $n?. ¿Te diriges al Bosque Ventarrosombra? Hay un cónclave de druidas allí, en una cueva al noreste. Estuve esperando noticias suyas, pero hace tiempo que no sé nada de ellos.\n\nCon Ban'aethall en ruinas y toda la agitación de los últimos tiempos, me preocupa que haya ocurrido algo grave. Si puedes ir, busca a Elegael Zarzaspina para devolverme la tranquilidad.", t = "Silencio inquietante"},
    [94485] = {ot = "Consigue $1oa moho de lágrima de dama.", st = "Si queremos salvar a mis compañeros de la Guarida Garra Nocturna, voy a necesitar algunos ingredientes para preparar una cataplasma. El primero y más importante es un moho delgado llamado Lágrima de dama. Suele crecer en la base de los árboles aquí, en Ventarrosombra.\n\nEste moho segrega una sustancia pegajosa que actúa como antiséptico y es perfecta para vendar heridas abiertas. He recogido lo poco que estaba a mi alcance, pero sé que hay más en este bosque.\n\nVe y date prisa. Vamos a necesitar mucho si los heridos que dejé atrás aún siguen con vida.", t = "Lágrimas de la dama"},
    [94486] = {ot = "Recoge $1oa plumas de chillines Ventarrosombra en el Bosque Ventarrosombra.", st = "El otro ingrediente que necesito para la cataplasma son las plumas de los chillines Ventarrosombra que deambulan por este bosque. Cuando son jóvenes, los chillines tienen plumas aislantes que serían ideales para colocar sobre el musgo. Estas plumas evitarán que la savia antiséptica se seque y proporcionarán al menos cierta protección contra los elementos.\n\nTen cuidado, los chillines suelen ser dóciles, pero últimamente se han vuelto increíblemente hostiles. Sus garras enormes pueden destrozarte con facilidad si no tienes cuidado.", t = "Plumas de unión"},
    [94487] = {ot = "Recoge $1oa reliquias ensangrentadas de los soldados de a pie Al'Aketh y trotatormentas Al'Aketh en el Bosque Ventarrosombra.", st = "Los cultores Al'Aketh nos atacaron de repente, aunque sus motivos siguen siendo un misterio para mí. Sabía que estos cultores tenían la cabeza en las nubes, pero nunca imaginé que alterarían el delicado equilibrio aquí en Zephras con tanta agresividad. Ve, mata a tantos como puedas y quítales sus reliquias si llevan alguna.\n\n<Elegael escupe.>\n\nEstos cultores de tormenta malditos no merecen ser llamados shen'dorei. Las bestias del bosque pueden quedarse con sus cuerpos. Sus cenizas no merecen los vientos.", t = "Indigno e infame"},
    [94488] = {ot = "Mata al comandante Haalien y llévale su cabeza a Elegael Zarzaspina en el Bosque Ventarrosombra.", st = "El motivo por el que los cultores siguen aquí aún me perturba, pero percibo un olor familiar entre el derramamiento de sangre.\n\nUno de los druidas de nuestro círculo, Haalien, desapareció hace meses. Parece que se ha unido a los cultores.\n\n¡Muéstrale lo que pasa cuando derrama la sangre de los suyos! Córtale la cabeza y tráemela.", t = "Los lazos que nos unen"},
    [94489] = {ot = "Entra en la Guarida Colminoche, cura a $1oa druidas y busca a Jorel Vientocantor en el Bosque Ventarrosombra.", st = "Ya terminé las cataplasmas. ¡Deprisa! Llévaselas a los druidas que están en la cueva, al norte, justo al otro lado del claro. Sé que mis hermanos están en un estado mucho más grave que el mío. Es probable que no puedan curarse las heridas por sí mismos debido a su grave condición. Somos tan pocos los druidas shen'dorei que cada vida cuenta.\n\nAntes de que te vayas, tengo una petición egoísta para hacerte. Mi compañero, Jorel Vientocantor, estaba en pésimas condiciones cuando me fui. Ve y sana sus heridas si aún está vivo.", t = "Las heridas de traición"},
    [94490] = {ot = "Llévale la misiva rasgada a Elegael Zarzaspina en el Bosque Ventarrosombra.", st = "<Hay una nota escondida detrás de uno de los brazales de Haalien que se rasgó un poco y se manchó de sangre durante la pelea. Parece que contiene información útil sobre las motivaciones de los cultores para el ataque a la guarida de los druidas. A Elegael le interesaría esta información.>", t = "Misiva rasgada"},
    [94491] = {ot = "Entrega la misiva a Lotheluum en Valannar y cuéntale lo que ha ocurrido.", st = "Parece que hay un informante escondido en algún lugar de Valanaar que le pasa información al culto. Es evidente que no estoy en condiciones de emprender el viaje, pero Lotheluum debe saber lo que ha ocurrido aquí.\n\nTambién debería conocer el destino de aquellos que ya no están con nosotros. Gracias a tu ayuda, creo que podemos encargarnos del resto de la situación desde aquí, aunque el daño ya está hecho.\n\nVete de una vez, $n. Espero que nuestros caminos se crucen de nuevo algún día. Hasta entonces, tengo cultores que matar.", t = "El destino de la guarida"},
    [94494] = {ot = "Encuentra a Norric Lagolord en Loch Modan.", st = "Mucho tiempo ha pasado desde que a prueba te pusieron, $n. Paciencia en tus estudios hasta ahora has mostrado, pero ha llegado la hora de que aprendas sobre la pureza del agua.\n\nBusca a Norric Lagolord en Loch Modan. Se encuentra en la orilla noroeste del lago, al sur de Presa de las Tres Cabezas. Lo encontrarás en su cabaña de madriguera. Que la Fortuna te sea favorable, $n.", t = "La llamada del agua"},
    [94495] = {ot = "Encuentra a Hervdana Saegrund en los Humedales.", st = "Si hay una verdad que debes aprender sobre el agua, es esta: el agua implica renacimiento. Talla la piedra, purifica la mugre y sana al exhausto, pero solo cuando es pura. Corrómpela y arruinará todo lo que toque.\n\nSi buscas el sapta de agua, encuentra a Hervdana Saegrund en los Humedales. Su familia mora en una cueva bajo las cascadas del sur.\n\nAnda, no dejes que el río te lleve la ventaja.", t = "La llamada del agua"},
    [94497] = {ot = "Llena el odre de agua marrón vacío en el pie de las cascadas que están debajo de la cueva de Hervdana y llévaselo a los Humedales.", st = "Ah, así que viniste a buscar el sapta, ¿no? Bueno, escucha bien, cariño. Para comprender y ganarte el sapta, tienes que buscar el agua en sus distintas formas. A medida que recojas las muestras, mantén los ojos abiertos. Observa las bestias que la protegen, la tierra que nutre y cómo transforma vidas.\n\nEmpecemos por lo fácil: llena este odre al pie de las cascadas, donde el agua dulce se mezcla con la salobre. Anda, y cuidado con el pantano.", t = "La llamada del agua"},
    [94499] = {ot = "Llena el odre de agua rojo vacío en las Cascadas Petravista, cerca de los reptanoches múrloc, y llévasela a Hervdana Saegrund en los Humedales.", st = "Sí, Crestagrana bebe directo del Lago Sempiterno, pero cuando las aguas bajan por las Cascadas Petravista, algo ya se les ha filtrado. Los múrlocs de allá abajo son brutos enormes y deformes. Nada que ver con los que encuentras aquí o en Loch Modan. Por suerte para la gente del pueblo, no se mueven del pie de las cascadas.\n\nTráeme una muestra. Algo me dice que es magia, veneno o algo peor lo que está corrompiendo las aguas cerca del viejo fuerte.", t = "La llamada del agua"},
    [94500] = {ot = "Llena el odre de agua azul vacío en las aguas de Astranaar, en Vallefresno, y llévasela a Hervdana Saegrund en los Humedales.", st = "Toma este odre de agua y adéntrate en la penumbra esmeralda de Vallefresno. Astranaar reposa entre aguas que la corrupción no ha tocado. Ruinas cubren el lecho del lago, vestigio de tiempos olvidados. Trae una muestra del lago. Agua pura, antigua y posiblemente encantada.\n\nEs el último líquido que me falta antes de mandarte de vuelta con Norric.\n\nToma el bote en Menethil con destino a Auberdine; para en Costasur en el camino.\n\nY ten cuidado... el bosque tiene ojos, y no parpadean.", t = "La llamada del agua"},
    [94568] = {ot = "Habla con Talaanis Cantosombrío y escucha la conversación.", st = "Evidentemente, el traidor temía los planes del culto, tanto que desertó y buscó nuestra ayuda. Es una desgracia que haya muerto y se haya llevado los secretos a la tumba.\n\nTenemos que analizar la situación y determinar nuestros próximos pasos.", t = "Los verdaderos planes del culto"},
    [94638] = {ot = "Busca y mata a Ur'endra en las Tierras Altas de Shen'dar.", st = "Acudiste a mí con la esperanza de aprender a asumir una forma fuerte. Tengo algo que pedirte, aunque me llene de pena el corazón.\n\nMi compañera, Ur'endra, ha caído en la locura y ha comenzado a atacar a los suyos. Sin los vientos, muchas criaturas han empezado a perder el rumbo, y debido al gran poder que tiene, Ur'endra representa una seria amenaza al delicado equilibrio. Deambula por las Tierras Altas de Shen'dar, en el noroeste.\n\nMuéstrame que tienes la fortaleza para poner fin a su sufrimiento y te concederé mi bendición.", t = "Fuerza y compasión"},
    [94774] = {ot = "Habla con la suma sacerdotisa Laurena en Ventormenta.", st = "Has llamado la atención de nuestros superiores, $n. Te piden que vayas a la Catedral de la Luz, en Ventormenta, lo antes posible. Por lo visto, creen que has demostrado tu valía y ya puedes recibir más instrucción. Cuando llegues, busca a la suma sacerdotisa Laurena. Ella podrá guiarte. Buena suerte y que la Luz te acompañe.", t = "Gracia divina"},
    [94792] = {ot = "Usa la fusta de doma para domar un jabalí Pielroca. Practica un poco y devuélvele la fusta a Josephine Carson.", st = "Muchos cazadores prefieren viajar con compañeros animales. Con una bestia a tu lado, descubrirás que puedes sobrevivir a las situaciones más peligrosas. Como dicen: todo es más fácil con un amigo. Sin embargo, conseguir a un compañero animal es algo que debe hacerse con cuidado. El equilibrio de la naturaleza es delicado y debemos respetarlo.\n\nToma esta fusta de doma y dirígete al bosque. Con ese instrumento, podrás domar un jabalí Pielroca y practicar tus habilidades como $gcazador:cazadora;.", t = "Domesticación de bestias"},
    [94793] = {ot = "Habla con Isaac Chan en Villadorada.", st = "Ahora tienes la capacidad de domar una mascota, pero también debes adquirir las habilidades necesarias para amaestrarla. Para esto, no hay nadie mejor que Isaac Chan, un leñador veterano. Él te proporcionará la habilidad para amaestrar a tu nueva mascota.\n\nVe con los vientos, joven $c.", t = "Domesticar la bestia"},
    [94818] = {t = "Plan de contingencia"},
    [94824] = {ot = "Habla con la suma sacerdotisa Mims en Forjaz.", st = "Ha llegado el momento de que vayas a Ventormenta, $n. La suma sacerdotisa Mims en la Sala de los Misterios te pide que hables con ella. Tiene que ser algo muy bueno o muy malo para que la suma sacerdotisa quiera que vayas, aunque supongo que, como lo has hecho tan bien, debe de ser algo bueno que quiera hablar contigo.$B$BPero no pierdas demasiado tiempo por aquí. Vete en cuanto puedas.", t = "Destello desconcertante"},
    [94863] = {ot = "Usa la fusta de doma para domar un lobo grisáceo del bosque. Practica un poco y devuélvele la fusta a Josephine Carson.", st = "Ahora que has aprendido a domar a un jabalí, podrás pasar a la siguiente lección. En el bosque habitan compañeros más fuertes, y con algo de esmero, podrás ganarte su confianza.\n\nToma esta fusta de doma y busca a un lobo grisáceo del bosque. No olvides respetar el equilibro de la naturaleza. Vuelve a demostrar tus habilidades como $gcazador:cazadora;.", t = "Domesticación de bestias"},
    [94864] = {ot = "Usa la fusta de doma para domar un oso del bosque joven. Practica un poco y devuélvele la fusta a Josephine Carson.", st = "Has demostrado tu valía al domar a un jabalí y a un lobo, y ahora deberás prepararte para tu último desafío. El equilibrio de Elwynn se basa en el respeto y la habilidad. Toma esta fusta de doma y busca un oso del bosque joven. Demuestra que puedes ganarte la confianza de los compañeros más fuertes de todos. \n\nUna vez que completes esta lección, tu armonía con las bestias se profundizará.", t = "Domesticación de bestias"},
    [94896] = {ot = "Reúne $1oa posesiones abandonadas de las Ruinas de Ban'aethal.", st = "Das la sensación de que eres $gun aventurero habilidoso:una aventurera habilidosa;. ¿Por casualidad te diriges al Bosque Ventarrosombra? Ban'aethal se encuentra en lo más profundo del bosque. De ahí venimos todos.\n\n<Ealaane señala a los demás refugiados.>\n\nHace poco tuvimos que evacuar Ban'aethal, ya que empezó a desmoronarse. Fue algo repentino y ocurrió en plena noche. Si vas en esa dirección, ¿podrías buscar cualquier pertenencia que hayamos dejado atrás? El bosque y la aldea son demasiado peligrosos para regresar ahora.", t = "Ayuda para los refugiados"},
    [94897] = {ot = "Busca a Resaan en las ruinas de Ban'aethal.", st = "Si vas a viajar a Ban'aethal, tengo una petición egoísta. Mi amado, Resaan... creo que ya no está más en este mundo. Quiso volver en busca de suministros a pesar de que le rogué que se quedara. Ya pasó más de una semana y temo lo peor.\n\nSi lo encuentras, tráelo con vida a casa. Si no sobrevivió, agradecería que me traigas una reliquia suya.", t = "El destino de un ser querido"},
    [94911] = {ot = "Habla con Turak Tótem de Runa en Cima del Trueno.", st = "Saludos, joven $r. Veo que tienes un futuro prometedor en las artes druídicas. Hay alguien en la ciudad de Cima del Trueno con quien deberías hablar. Se llama Turak Tótem de Runa y te enseñará a llegar a la fortaleza del Círculo Cenarion de Kalimdor, en Claro de la Luna. \n\nAhí te darán la bienvenida, y los druidas del círculo compartirán sus conocimientos contigo. \n\nComo diría tu pueblo, ve con la bendición del viento, joven. Te deseo buena fortuna en tus aventuras.", t = "Hijos de la naturaleza"},
    [94912] = {ot = "Habla con Sheldras Árbol Lunar en Ventormenta.", st = "Saludos, joven $c. \n\n¿Has oído hablar del Círculo Cenarion? Supongo que no. Son una orden antigua de naturalistas y practicantes de las artes druídicas, como tú. En la ciudad de Ventormenta, encontrarás a un elfo de la noche llamado Sheldras Árbol Lunar. Él te dirá cómo llegar a la fortaleza del Círculo Cenarion de Kalimdor, en un lugar llamado Claro de la Luna.\n\nVe. Tienes mucho que aprender para salvar tu hogar.", t = "Hijos de la naturaleza"},
    [94913] = {ot = "Utiliza el hechizo \"Teletransporte: Claro de la Luna\" para viajar a Claro de la Luna. Cuando llegues, ve al poblado Amparo de la Noche y habla con Dendrita Rafagaestelar.", st = "En las sagradas tierras de Claro de la Luna todos los druidas son bienvenidos. El guardián Remulos de Claro de la Luna sigue custodiando a los druidas que hibernan allí. Te enseñaré el hechizo que te permite teletransportarte allí. Utilízalo cuando busques el conocimiento o el consuelo del Claro de la Luna.$B$BComo primera lección aquí en Azeroth, ve a Claro de la Luna. Busca a Dendrita Rafagaestelar en Amparo de la Noche y háblale del camino que recorres. Buena suerte, joven druida.", t = "Claro de la Luna"},
    [94946] = {ot = "Aborda el cortacielos de Isla Zephras a Ciudad de Dalaran y habla con Denaaris Tempestrella cuando llegues.", st = "Quería ser el primero de nosotros en llegar a Azeroth, pero debido a los recientes acontecimientos con el culto, he tenido que cambiar mis planes. Por ello, seguiré en Valanaar por un tiempo. Pero no te preocupes, uno de nuestros magos te estará esperando y te recibirá cuando llegues a Dalaran. Ve a explorar Azeroth mientras ponemos en orden nuestros asuntos aquí. Te llamaremos cuando te necesitemos.\n\nCuando estés $glisto:lista;, ve al muelle que hay justo al salir de este recinto y aborda el cortacielos.", t = "La ciudad mágica de Dalaran"},
    [94947] = {ot = "Usa el portal cielonato a Ventormenta y preséntate ante Bolvar Fordragón en el Castillo de Ventormenta.", st = "El mundo aquí abajo es muy grande, y necesitamos que nuestra gente se separe para comenzar a explorarlo. Ahí es donde entras tú.\n\nEl Kirin Tor es miembro de una \"Alianza\" de naciones afines. El corazón de facto de esta alianza es la ciudad de Ventormenta, que está al sur. Elaadrin me ha pedido que encuentre a alguien para que viaje a Ventormenta y se reúna con el Señor regente de la ciudad, un humano llamado Bolvar Fordragón.\n\nCuando estés $glisto:lista;, usa el portal especial a Ventormenta que los magos del Kirin Tor han abierto para la Suma Orden.", t = "Bienvenido a Azeroth"},
    [94978] = {ot = "Usa la fusta de doma para domesticar un reptador de Son del viento cerca de los cuerpos de agua. \nPractica tus habilidades y devuélvele la fusta de doma a Quel'ana Ventarrápido en Valanaar.", st = "El primer paso de todo cazador es conocer el vínculo entre bestia y amo. Este será tu primer desafío. Con el tiempo, domesticarás a criaturas de todos los rincones del mundo pero, por ahora, comienza en los ríos y lagos de Zephras. \n\nToma esta fusta de doma y busca un reptador de Son del Viento.\n\nMuéstrale que puedes ganarte su confianza, y comienza tu camino hacia la verdadera maestría.", t = "Domesticación de bestias"},
    [94979] = {ot = "Utiliza la fusta de doma para domar a un zancavientos enfurruñado en los Bajíos Ventobaya.\nPractica tus habilidades y después devuélvele la fusta de doma a Quel'ana Ventarrápido en Valanaar.", st = "Has demostrado que puedes domesticar al reptador del río. Ahora, tienes que poner tus habilidades a prueba en terreno abierto. En las llanuras de Zephras, resuenan los gritos del zancavientos, un orgulloso cazador alado que viaja a la par del viento.\n\nToma esta fusta de doma y busca uno. Ve a los bajíos y gánate su confianza.\n\nDemuestra que estás $glisto:lista; para las pruebas que se avecinan.", t = "Domesticación de bestias"},
    [95034] = {ot = "Habla con Lumina Vientocantor en el Sepulcro.", st = "Creo que debes saber que en realidad no fueron los gnolls los que nos atacaron en el camino.\n\nFuimos atacados por una criatura gigantesca parecida a un lobo que conozco como \"huargen\". Derrotó a nuestros guardias y vino a por mí, pero Banon se interpuso en su camino. Conseguí lanzar un hechizo que sobresaltó a la criatura y huyó, pero Banon ya estaba gravemente herido. Insistió en que continuara sin él, pero me negué.\n\nVolvíamos a duras penas cuando los gnolls nos encontraron. Lo que siguió fue aterrador.", t = "La deuda"},
    [95065] = {ot = "Llévale el adorno lustroso de $2oa y los reptadores nocturnos de $1oa a Gilbert Gray, en el puerto de Ventormenta.", st = "Qué vista... Es lo mejor que puede pedir un anciano.\n\nLos peces están picando, pero solo me queda un cebo. De casualidad, no llevas suministros de pesca encima, ¿no? Claro que no, discúlpame. Me entusiasma tanto la sola idea de lanzar otro anzuelo que olvido que debo ser el único por ahí llevando suministros a cuestas.\n\n¿Serías tan amable de reabastecerme? Al oeste del Distrito de Mercaderes, junto a los canales, se encuentra Catherine Leland, que tiene un montón de artículos de pesca. Dile que vas en nombre del viejo Gray.", t = "Hora de la pesca"},
    [95161] = {ot = "Entrégale la carta manchada con sangre a Avette Bosquevil en el Bosque del Ocaso.", st = "Si buscas a Jeremy Tejecorazones, lo mejor que puedes hacer es hablar con su nueva madre adoptiva, Avette Bosquevil, en el Bosque del Ocaso. Es encantadora. Seguro necesita ayuda para trabajar, pero aun eso es mejor que quedarse en el orfanato.\n\nSi ves al pequeño Jeremy, hazme el favor de decirle que aquí todos pensamos en él.", t = "Recuerda que te amo"},
    [95189] = {ot = "Lleva el blasón de Lordaeron a Lady Dena Kennedy en la Ciudad de Ventormenta.", st = "<Un blasón curtido que representa la marca de Lordaeron. Dado que quedan pocas reliquias tras la caída del reino, se me ocurre alguien en Ventormenta que se interesará mucho.>", t = "Blasón de Lordaeron"},
    [95195] = {ot = "Recoge $1oa insignias ensangrentadas y llévaselas al general Marcus Jonathan en la Ciudad de Ventormenta.", st = "<La antigua insignia de la Alianza parece haber pertenecido a un soldado de Lordaeron. Es posible que estas ruinas estén llenas de medallas similares, cuyos dueños tienen familiares vivos que agradecerán mucho que se las regresen.>", t = "Insignia ensangrentada"},
    [95204] = {ot = "Lleva el blasón de Lordaeron a Oran Snakewrithe en Entrañas.", st = "<Un blasón curtido que representa la marca de Lordaeron. Ya que quedan pocas reliquias tras la caída del reino, se me ocurre alguien en Entrañas que se interesará mucho.>", t = "Blasón de Lordaeron"},
    [95212] = {ot = "Reúne 6 pelambres de leopardo prístinos y entrégalos en la Granja de Semperámbar.", st = "Nos estamos preparando para enviar un equipo de carneros para reforzar la expedición de Alterac, pero nos quedamos sin materiales para fabricar las monturas.\n\nReúne las pieles de los leopardos más grandes y feroces que hay al este y tráemelas. Nuestras tropas se congelan allá arriba. ¡Se merecen las mejores pieles para mantenerse calientes!", t = "Nunca escatimes en la calidad"},
    [95213] = {ot = "Llévale el barril de pólvora vacío al capataz de cantera Thesten en la Cantera de Gol'Bolar.", st = "El barril tiene una estampa:\n\nPÓLVORA EXPLOSIVA - PELIGRO - NO MANIPULAR - PELIGRO - SOLO CON AUTORIZACIÓN DEL CAPATAZ - PELIGRO\n\nTienes el leve presentimiento de que los troggs no deberían tener esto. Será mejor informar esto en la cantera antes de que sea tarde.", t = "Pólvora explosiva robada"},
    [95214] = {ot = "Recupera $1oa montones de pólvora explosiva robada de los troggs que hay al este de la Cantera de Gol'Bolar. Luego, entrégaselos al capataz de cantera Thesten.", st = "Este barril tenía suficiente pólvora para convertir el salón del trono del rey Magni en un patio de escuela. Debemos recuperarla de los troggs antes de que descubran cómo encenderla.", t = "Pólvora explosiva robada"},
    [95216] = {ot = "Recoge la cepa muy tóxica de Marchitacolmillos en las Ruinas de Lordaeron para Theodore Griffs en Entrañas.", st = "Te damos la bienvenida al lugar más importante de Entrañas: ¡El Apothecarium! Aquí experimentamos con los más virulentos especímenes exóticos de Azeroth.\n\nMe encuentras de buen humor, por lo que te pondré al día con mi última investigación. Parece que hay un artrópodo venenoso acechando las ruinas por encima de nuestra noble ciudad. Dicen que sus toxinas son capaces de carcomer incluso la carne no-muerta. ¡Qué emocionante!\n\nQuiero verificar estos reclamos. Si sufres su mordedura, me encantaría tomar una muestra.", t = "La nueva peste"},
    [95217] = {ot = "Reúne 12 barras de cobre y 4 pellejos de jabalí endurecidos y entrégaselos a Frast Dokner.", st = "¿Así que quieres aprender el oficio de la herrería? Quizás podamos ayudarnos.\n\nLa entrega de suministros está retrasada, y necesito los materiales para reparar algunas cosas en el campamento. Si encuentras lo que necesito, te enseñaré algunas de mis técnicas. ¿Suena justo?", t = "El herrero de la cantera"},
    [95250] = {ot = "Recoge la cabeza del Barón en las Ruinas de Lordaeron y regresa con el capitán Truman.", st = "¿Qué quieres, $r? ¿Acaso no ves que hay una guerra que debemos ganar?\n\nMi maestro ya se lanzó a la batalla y me ha ordenado conservar mi puesto. Sin embargo, ya pasó un buen rato.\n\nDudo que sobrevivas siquiera diez minutos en combate; pero si quieres tener ocupada tu mente escueta, busca al Gran mariscal. Es el héroe más alto y escultural que verás jamás. Te darás cuenta cuando lo veas.", t = "Criaturas abominables"},
    [95314] = {ot = "Reúne $1oa botellas de elixir susurrante en Vallesombra y regresa con Carolai Anise en Rémol.", st = "Antes de la invasión de la Plaga, la aislada aldea de Vallesombra era conocida por su elixir susurrante. El elixir, hecho con hierbas que solo se encuentran en la Cascada de Tyr, era muy buscado por los boticarios, los místicos y los fabricantes de veneno, incluso después de que lo prohibieran en la ciudad.\n\nTengo pedidos de bastantes clientes que quieren poner sus manos en el elixir. Viaja a las ruinas de Vallesombra, en las profundidades del Bosque Susurrante, al oeste. Estoy dispuesta a pagar una gran suma si logras conseguirme algunas botellas.", t = "Aquel elixir verde de Vallesombra"},
    [95328] = {ot = "Llévale el residuo de horror susurrante al padre Lankester en el Barrio de la Guerra en Entrañas.", st = "En contra de tu buen juicio recolectas los restos de la bestia, que aún se retuercen. Habrá alguien en Entrañas que podrá darles un uso.", t = "Residuo de horror susurrante"},
    [95349] = {ot = "Aborda el cortacielos de Isla Zephras a Mulgore y habla con Alana Zancatormentas cuando llegues.", st = "Debido a los recientes acontecimientos con el culto, he tenido que retrasar mi viaje a Azeroth. Me quedaré en Valanaar por un tiempo. A cambio, tú y un grupo de otros Formavientos serán nuestra vanguardia. Alana Caminatormentas te estará esperando y te recibirá cuando llegues a Mulgore. Ve a explorar Azeroth mientras acabamos nuestros asuntos aquí. Pronto iremos contigo.\n\nCuando estés $glisto:lista;, ve al muelle que hay justo al salir de este recinto y aborda el cortacielos. Banu-Alah, $n.", t = "El Anillo de la Tierra"},
    [95350] = {ot = "Viaja a Orgrimmar y habla con Thrall en el Valle de la Sabiduría.", st = "Este es un mundo grande, y nuestros nuevos aliados son fundamentales para nuestra supervivencia.\n\nEl Anillo de la Tierra es una agrupación que pertenece a la \"Horda\", un conjunto orgulloso de personas con opiniones similares. La ciudad cercana de Cima del Trueno es una parte de la Horda, y más al este se encuentra la ciudad de Orgrimmar.\n\nBusca al maestro de vuelo en el centro de Cima del Trueno para volar a Orgrimmar, donde podrás tener una audiencia con el jefe de guerra de la Horda, Thrall, en nombre de los Formavientos. Que los vientos te guíen, $n.", t = "Bienvenido a Azeroth"},
    [95494] = {ot = "Reúne 6 pieles de león de las matriarcas de la sabana y los patriarcas de la sabana en los Baldíos.", st = "Necesito a alguien que sepa empuñar bien una espada y tenga algo de tiempo de sobra para ayudarme a reunir pieles de león. Me duele en el orgullo pedirle esto a $Gun forastero:una forastera;, pero hace poco me lastimé la pierna. Hasta que me recupere, no estoy en condiciones de salir a cazar, pero tengo obligaciones que cumplir.\n\nLos grandes de esta zona suelen tener las mejores pieles, así que empieza por esos.", t = "El orgullo herido y la piel del león"},
    [95495] = {ot = "Llévale el fardo de pieles al ermitaño que está en el risco con vista a las Colinas Áridas, en los Baldíos.", st = "Estas pieles son para un peletero con el que comercio seguido. Es algo así como un ermitaño; vive solo en la cima del risco que tengo a mis espaldas. Ahora mismo, subir una ladera empinada no es algo que pueda hacer con facilidad, así que te debería una si pudieras hacer la entrega por mí.\n\nAh, y sobre la... apariencia del peletero. No te asustes. A pesar de cómo se ve, no es una amenaza. Te lo juro.", t = "El peletero ermitaño"},
    [95507] = {ot = "Reúne 8 presas atrapadas de las trampas activadas en los Baldíos.", st = "Ya que vas a estar por ahí, me harías un gran favor si pudieras revisar mis trampas. Las tengo desparramadas por todo el valle.\n\nTráeme los animales pequeños que haya atrapado. Eso sí, no pierdas de vista a la otra vida silvestre de la zona. Puede ser peligroso si no prestas atención.", t = "Las presas de Vrang"},
    [95508] = {ot = "Ayuda a Walton a sobrevivir al enfrentamiento con Terry Tragolargo y los marinos de Kul Tiras.", st = "Sí, fui miembro de la armada kultirana. Cuando Lady Almirante tomó Theramore y empezó su campaña en Durotar, tuve... \"objeciones\" con sus métodos. En particular con los que incluían ejecutar civiles.\n\nHay más, pero... espera... ¿qué es eso?\n\n¡Hay un grupo de hombres subiendo por el risco!", t = "Huéspedes no deseados"},
    [95621] = {ot = "Ve a la caravana destrozada y averigua por qué los kultiranos están aquí.", st = "Esta mañana vi a un grupo de humanos buscando algo en el valle de abajo. Logré usar la mira del rifle para ver mejor, y quedó claro que eran soldados portando la librea de Kul Tiras. \n\nSi estuvieras $Gdispuesto:dispuesta; a aceptar un trabajo de mi parte, ve al campamento que estos soldados montaron, cerca de la caravana destrozada al sur. Mata a los que encuentres e intenta averiguar por qué están aquí.", t = "Problemas en el valle"},
    [95646] = {ot = "Asesina a un Horror de las Tierras Altas dentro de los sitios de excavación y llévale su núcleo de raíz a Rethiel el Guardaverde en los Humedales.", st = "Estos humedales salobres albergan una gran reserva de aguas dulces del sur. Me duele, pero en lo más profundo de mis raíces siento cómo una corrupción se filtra en ese barranco de la montaña.\n\nLas criaturas como aquellas de nuestras tierras bajas reaccionan de forma más hostil ante la corrupción. Al no contar con la sal fortalecedora del mar desde el principio de la vida, estas criaturas no tienen las fuerzas suficientes para hacer frente a tal mal.\n\nDirígete a las Tierras Altas y tráeme el núcleo de raíz del Horror de las Tierras Altas.", t = "Horrores en las Tierras Altas"},
    [95647] = {ot = "Busca a Ardin Pastal en los sitios de excavación", st = "Mi esposo, Ardin, tiene un don excepcional para percibir la naturaleza. Escalaría cualquier cima con tal de conseguir las hierbas y flores que necesito para mi alquimia y así mantener bien abastecidos nuestros estantes y despensas.\n\nPero temo que se ha metido en problemas. Un equipo de excavación pasó en busca de provisiones. Hablaron, entre otras cosas, sobre hierbas altísimas como nunca antes habían visto. Ardin me dijo que tenía que ir a verlas con sus propios ojos. ¡Pero ya ha pasado mucho tiempo desde que se fue!\n\nSi me traes noticias de él, estaré muy agradecida.", t = "Perdidos en el zarzal"},
    [95663] = {ot = "Viaja a los Humedales y reúnete con la Agente Mortacechadora en las colinas que dan al campamento Faucedraco.", st = "Los Faucedraco son un clan formidable.\n\nSe los conoce por dominar magia de vinculación lo suficientemente potente como para doblegar a los dragones. Además, corre el rumor de que se están preparando para exhibir su poderío en los Humedales. Tal vez sea verdad o solo patrañas, pero los Mortacechadores no pueden guiarse por habladurías. Eso fue todo lo que los vientos titánicos pudieron decirme.\n\nUna Agente Mortacechadora necesita ayuda en las colinas con vistas al campamento de los Faucedraco. Encuéntrala para que te revele cómo proseguir.", t = "Rumores en fauces de draco"},
    [95664] = {ot = "Lleva la reliquia de titán al Alto de los Ancestros en Cima del Trueno y busca a alguien que pueda revelarte más sobre ella.", st = "Este fragmento compuesto es poco usual y dispersa la luz como si fuese un prisma vivo. A pesar de su naturaleza desconocida, no cabe duda de que posee un poder antiguo. Las mentes más sabias sobre artefactos de aquella era perdida deben encontrarse en Alto de los Ancestros, en Cima del Trueno.", t = "Sabiduría ancestral"},
    [95682] = {ot = "Mata a las fuerzas Faucedraco dentro del Sitio de Excavación y llévale cualquier hallazgo al agente Mortacechador que espera afuera.", st = "Faucedraco. <Deja escapar una risa seca y burlona.>\n\nLos restos de ese clan domador de dragones creen haber hallado algo que los llevará a recuperar su antiguo poder. ¿A los ojos de quién… de su falso jefe de guerra?\n\nAcaba con su desordenado clan en los Sitios de Excavación para que nuestros Mortacechadores puedan infiltrarse sin ser vistos.\n\nSi los Faucedraco portan algo de valor, tráelo a mí. Esta información debe permanecer entre $gnosotros:nosotras; y el mando real.", t = "Apertura de las Fauces"},
    [95697] = {ot = "Entra en los sitios de excavación en los Humedales y recupera carne de raptor de matorral", st = "Zamja me dice que necesitamos comida con un estilo más casero.\nSi comenzamos a vender carne de raptor, ella cree que atraeremos clientes que no suelen visitar la Fosa de lava de Borstan.\n\nAunque no es mala idea, quiero algo que esté por encima de los aromas de nuestras aldeas natales. Después de todo, ¡estamos en Orgrimmar! Borstan debería ofrecer manjares inspirados por los platos típicos favoritos.\n\nHace poco, un cazador regresó de los Humedales con una garra gigante de esos raptores de matorral que merodean en los sitios de excavación.\n\n¿Tienes tiempo para un trabajito?", t = "Gustos variados"},
    [95772] = {ot = "Busca al hermano de Dorin Filosón, Daewyn, en Excavación de Whelgar.", st = "Mi hermano intentó arrastrarme a los Humedales con un grupo de excavadores de Loch Modan. Dijo que se dirigían a unas colinas en las que ningún enano ha pisado jamás para hacer algún tipo de excavación.\n\nHubiera ido de no ser que estoy muy ocupado con esta pila de fajas que tengo que ajustar.\n\nDaewyn normalmente me escribe una carta después de partir, pero no me ha llegado nada. Esta vez, tengo una sensación extraña. \n\nSi vas por ese camino, ¿te importaría buscar a mi hermano?", t = "En busca de Filosón"},
    [95774] = {ot = "Mata jabaespines y consigue $1oa de los adornos de Olgra para el monumento de Mankrik.", st = "El sanador que me salvó a mí no pudo salvarla a ella, y murió en combate. Su nombre es Olgra, y jamás la olvidaré.\n\n¿No encontraste los adornos en su cuerpo? Llevaba muchas joyas de hueso pulido.\n\nMata a los asaltantes Crines de Acero que encuentres cerca del lugar donde cayó y recupera sus preciadas obras de arte.\n\nLas colocaré en el monumento que construiré para honrar su memoria.", t = "Su nombre es Olgra"},
    [95795] = {ot = "Regresa con Dorin Filosón", st = "<Cubres el cuerpo del enano con su capa.>\n\nViaja a Villa del Lago e infórmale personalmente a Dorin Filosón sobre el destino que sufrió su hermano en los sitios de excavación.", t = "Perdido en el pantano"},
    [95803] = {ot = "Llévale la cabeza de Rudolph Gelhardt a Sylvanas Brisaveloz en Entrañas.", st = "Ahora que hemos reclamado la cabeza del comandante deslustrado, necesito que la lleves a Entrañas. Sylvanas Brisaveloz desconfía mucho de nosotros y nos desprecia casi sin disimulo.\n\nLlévale la cabeza de Rudolph Gelhardt a la Dama Oscura. Muéstrale que solemos ser dueños de nuestra propia casa y que somos devotos de la prosperidad de los Renegados.", t = "Una muestra de buena fe"},
    [95805] = {ot = "Lleva el incienso humeante al santuario de An’she y Mu’sha, en las colinas del sureste, antes de que se reduzca a cenizas en diez minutos.", st = "El sol y la luna, An’she y Mu’sha, no forman parte de nuestro mundo como los elementos, pero su luz nos da vida, guía y esperanza.\n\nHonramos a los espíritus del mundo, y por ello también honramos a los gemelos.\n\nSi deseas mostrar tu respeto, toma este incienso humeante y llévalo a un santuario en las colinas al sureste, sobre la meseta, al sur de los jabaespines. Apresúrate, pues el incienso se extinguirá pronto.\n\n¡Y cuida que no se moje!", t = "Gracia de An'she y Mu'sha"},
    [95809] = {ot = "Vuelve con Caitlin Pastal en el Puerto de Menethil", st = "Necesito un momento para descansar antes de arreglármelas para salir.\n\n<Saca unos juncos de su mochila y los entrelaza rápidamente hasta darles forma de corazón.>\n\nToma esto y llévaselo a Caitlin. ¡Dile que pronto volveré a casa! Ahora que tenemos el camino despejado gracias a ti, recogeré mis provisiones y seguiré tus pasos.\n\nGracias.", t = "Corazón entrelazado"},
    [95810] = {ot = "Lleva la reliquia de titán al prospector Whelgar en el sitio de excavación de Los Humedales.", st = "Recoges una pieza rota del autómata de roca. Su textura no se parece a nada que hayas tocado antes: un material compuesto de naturaleza desconocida. Sin duda, esto es más un \"dispositivo\" que simples \"escombros\".\n\nEl propio prospector Whelgar, en su sitio de excavación, podría tener algo útil que compartir acerca de la reliquia.", t = "Portador de la reliquia perdida"},
    [95883] = {ot = "Consigue un alma torturada de los no-muertos cercanos en El Desafío de Beren en el Bosque de Argénteos.", st = "<Los preparativos para un ritual organizado a toda prisa se encuentran sin miramientos sobre el altar. De acuerdo al trozo de papel, ya se han reunido todos los elementos. Lo único que falta es la ofrenda de sangre y el alma torturada.\n\nLos no-muertos a tu alrededor parecen haber sufrido lo suficiente. Puede que tengan lo que buscas.>", t = "El alma torturada"},
    [95884] = {ot = "Encuentra la piedra de ofrenda en El Desafío de Beren en el Bosque de Argénteos.", st = "<El trozo de papel es casi ilegible. Aunque lo que se alcanza a leer son preparativos para una ofrenda.\n\nSe menciona una piedra de ofrenda y un ritual.\n\nTal vez puedas encontrar esta piedra de ofrenda en los alrededores.>", t = "La piedra de ofrenda"},
    [95885] = {ot = "Usa el alma torturada para otorgar una ofrenda de sangre en la piedra de ofrenda, en el Desafío de Beren.", st = "<Lo único que queda ahora es la ofrenda de sangre.\n\nEl trozo de papel mencionaba un \"sacrificio voluntario\".\n\nUn pavor inquietante se apodera de ti.>", t = "La ofrenda de sangre"},
    [95981] = {ot = "Mata a $1oa magos de Dalaran y $2oa vigías de Dalaran para el sacerdote de las Sombras Allister en El Sepulcro.", st = "Llevarnos sus pendientes fue tan solo el primer paso. Si es verdad que el Kirin Tor está enviando un flujo constante de reliquias desde Dalaran, debemos detenerlos en el punto de origen.\n\nRecorre los caminos en las inmediaciones de Molino Ámbar en busca de magos y vigías de Dalaran. Su presencia ha permitido el libre acceso por nuestras fronteras desde hace mucho tiempo. Si podemos reducir sus filas, eso debería bastar para que los colgantes dejen de llegar al Bosque de Argénteos en primer lugar.", t = "Caminos vigilados"},
    [95998] = {ot = "Siéntate cerca de la hoguera básica de Sam, escribe /sentarse en la ventana de chat y espera hasta que recibas el beneficio Descanso mejorado.", st = "Saludos, $c. Veo que tienes aspecto de $gaventurero:aventurera;. ¡Qué bien! El mundo necesita más almas inquietas como nosotros, en busca de fortuna y gloria.\n\nEl mundo es enorme, y necesitarás aprender a sobrevivir en la naturaleza para alcanzar tus metas. No conozco tus habilidades al aire libre, pero apuesto a que podría enseñarte un par de cosas, si estás $gdispuesto:dispuesta; a aprender.\n\nSiéntate cerca del fuego y ponte $gcómodo:cómoda;. Te lo explicaré todo.", t = "Bendita naturaleza"},
    [95999] = {ot = "Entrega el bastón roto del incinerador Gar'im al magistrado Solomon en Villa del Lago.", st = "¡Se busca! Incinerador Gar'im, líder de la incursión de los orcos en el Valle de Render. Se dice que colabora con la Roca Negra del Fuerte de Petravista.\n\nTen cuidado con el incinerador Gar'im. Él y sus taumaturgos umbríos son extremadamente peligrosos. Se otorgará una generosa recompensa a cualquier valiente que entregue prueba de la caída del incinerador Gar'im al magistrado Solomon.", t = "Se busca: incinerador Gar'im"},
    [96031] = {ot = "Habla con Gretta Bueneje en Forjaz para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Te convertiste en $Gpeletero:peletera;. Bien por ti, $c. Creo que conozco a alguien que puede enseñarte a fabricar una tienda de campamento para mantenerte $Gfresco:fresca; los días de calor y $Gseco:seca; los días de lluvia.\n\nCon una buena tienda sobre tu cabeza, te asegurarás de descansar todo lo necesario para mantenerte alerta durante tus viajes.", t = "Campamento básico: Peletería"},
    [96044] = {ot = "Habla con Tognus Fuegosílex en Kharanos para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que te hiciste $Gherrero:herrera;. Es una gran elección si quieres asegurarte de que tus hojas nunca pierdan el filo.\n\nCreo que conozco a alguien que puede echarte una mano y enseñarte a fabricar una rueda de afilar. Instala una en tu campamento y todos los guerreros y pícaros de la zona harán cola para afilar sus armas.", t = "Campamento básico: Herrería"},
    [96045] = {ot = "Habla con Vosur Brakthel en Forjaz para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Ahora que te dedicas a la alquimia, también puedo enseñarte a fabricar un pozo de maná para tu campamento, después de que hayas practicado un poco. Construye uno y todos los sanadores y taumaturgos vendrán corriendo por un sorbo refrescante.", t = "Campamento básico: Alquimia"},
    [96046] = {ot = "Habla con Yarr Martillal en Kharanos para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "La minería no será lo más glamuroso, pero es un trabajo honesto y una profesión excelente que puedes explorar.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una magnetita para tu campamento. Crea una y todo el que quiera blandir una espada correrá a reunirse junto a tu hoguera para empaparse de ese \"impulso\" y mejorar su destreza en combate.", t = "Campamento básico: Minería"},
    [96047] = {ot = "Habla con Thamner Pol en Kharanos para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que te metiste en primeros auxilios. Una vocación honorable... y muy práctica para $Gun:una; $c.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un equipo de primeros auxilios para tu campamento. Las heridas son parte de la vida de los aventureros, y brindar esa sanación tan necesaria en tu campamento podría incluso salvar vidas.", t = "Campamento básico: Primeros auxilios"},
    [96050] = {ot = "Habla con Paxton Ganter cerca del Lago Glacial en Dun Morogh para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Quizás no lo creas, pero tu habilidad como $Gpescador:pescadora; puede resultar muy útil en el campamento.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un cuenco de pescado para tu campamento. Puedes usar este accesorio para alegrarles un poco el día a ti y a tus compañeros de aventura. Un aventurero feliz es un aventurero fuerte, y seguro que tus habilidades de combate lo reflejarán.", t = "Campamento básico: Pesca"},
    [96055] = {ot = "Habla con Reyna Ramapiedra en Forjaz para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Por lo que veo, ya le agarraste la mano a la herboristería. Recoger flores no es solo para perder el tiempo, ¿sabes? Puede ser útil... y rentable.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una vela de incienso para tu campamento. El buen ánimo es fundamental para mantener a los sanadores y taumaturgos en la pelea, y una vela de incienso puede dar un impulso que los hechiceros sin duda valorarán.", t = "Campamento básico: Herboristería"},
    [96056] = {ot = "Habla con Balthus Cazarrocas en Forjaz para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Saber desollar con destreza las pieles y los pellejos de las bestias caídas es una de las habilidades más valiosas que un aventurero puede tener.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una silla de campamento. A veces es importante quitarse un peso de encima, y puedes usar algunos de los cueros que recogiste para hacer una silla cómoda donde sentarte. Un poco de relajación puede ayudarte a estar en óptimas condiciones y a atacar donde más duele la próxima vez que te metas en una pelea.", t = "Campamento básico: Desuello"},
    [96057] = {ot = "Habla con Uthrar Threx en Forjaz para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "La sastrería es un oficio sorprendentemente potente en el que vale la pena invertir tiempo, y seguro que te va a servir.\n\nConozco a alguien que puede enseñarte a fabricar un estandarte de facción para tu campamento, siempre y cuando tengas la destreza para ello. La inspiración y la moral son la clave para el éxito en cualquier batalla, y un estandarte inspirador te puede ayudar bastante para mantenerte con energía.", t = "Campamento básico: sastrería"},
    [96058] = {ot = "Habla con Bronk Comengranaje en Kharanos para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Los ingenieros como tú pueden armar toda clase de bártulos, bots y bombas, para divertirse y ganarse unas monedas.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un robot de componentes para tu campamento. Este útil autómata puede mantenerte bien $Gabastecido:abastecida; para que a ti y a tus aliados nunca les falten los materiales necesarios para potenciar los hechizos.", t = "Campamento básico: Ingeniería"},
    [96059] = {ot = "Habla con Thonys Piedrapilar en Forjaz para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Ahora que te has adentrado en el mundo del encantamiento, creo que podré enseñarte a fabricar un laúd encantado para tu campamento cuando hayas aprendido lo básico.\n\nEs muy importante distraerse en los ratos de descanso, y este toque de magia te ayudará a estar $Glisto:lista; para afrontar toda clase de desafíos cuando retomes el viejo y polvoriento sendero.", t = "Campamento básico: Encantamiento"},
    [96101] = {ot = "Siéntate cerca de la hoguera básica de Raan, escribe /sentarse en la ventana de chat y espera hasta que recibas el beneficio Descanso mejorado.", st = "Saludos, $c. Veo que tienes aspecto de $gaventurero:aventurera;. ¡Qué bien! El mundo necesita más almas inquietas como nosotros, en busca de fortuna y gloria.\n\nTendrás que aprender a sobrevivir en la naturaleza para tener éxito en este oficio. No conozco tus habilidades al aire libre, pero creo que puedo enseñarte un par de cosas, si estás $gdispuesto:dispuesta; a aprenderlas.\n\nSiéntate cerca del fuego y ponte $gcómodo:cómoda;. Te lo explicaré todo.", t = "Bendita naturaleza"},
    [96102] = {ot = "Habla con Snang en Orgrimmar para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "La sastrería es un oficio sorprendentemente potente en el que vale la pena invertir tiempo, y seguro que te va a servir.\n\nConozco a alguien que puede enseñarte a fabricar un estandarte de facción para tu campamento, siempre y cuando tengas la destreza para ello. La inspiración y la moral son la clave para el éxito en cualquier batalla, y un estandarte inspirador te puede ayudar bastante para mantenerte con energía.", t = "Campamento básico: Sastrería"},
    [96130] = {ot = "Derrota a Chakuyak y regresa con su pellejo.", st = "Entre los lobos de la pradera que cazan en las colinas cercanas hay una loba que es particularmente peligrosa. Hemos decidido llamarla Chakuyak. Se ha convertido en una amenaza para los viajeros que vienen del extranjero.\n\nAcecha desde los árboles del oeste del Lago Toro de Piedra y se mueve de copa en copa.\n\nAcaba con esta amenaza y tráeme su pellejo, y le hablaré de tus proezas al jefe. Ten cuidado, ¡es peligrosa! Puede que encuentres a otros cazadores que la estén buscando, tal vez puedan trabajar en conjunto.", t = "Chakuyak"},
    [96137] = {ot = "Derrota a $1oa devastadores negros jóvenes y $2oa devastadores negros. Luego, regresa con Sirra Von'Indi en Villa Oscura para obtener más información.", st = "Una daga pequeña que perteneció a la autoproclamada forestal, Ira, que mantenía los bosques a salvo al prevenir que las bestias del interior ataquen a los viajantes.\n\nQuizás el espíritu de Ira aún vaga por ahí porque tiene negocios inconclusos: eliminar a los huargos que continúan reclamando víctimas a lo largo del bosque.", t = "Daga de Ira"},
    [96139] = {ot = "Busca algo interesante en Cerro del Cuervo y regresa con Sirra Von'Indi en Villa Oscura.", st = "Es importante que, en tiempos oscuros como este, recordemos tanto a nuestros héroes como a nuestros enemigos. Villa Oscura no seguiría en pie si no fuera por la valentía de gente como Lady Althea o aquellos que dieron sus vidas en Cerro del Cuervo.\n\n¿Has leído algo sobre Cerro del Cuervo? No, claro que no; a su historia y a su gente la eliminaron. En mi biblioteca, por más impresionante que sea, hay poca información al respecto.\n\nSi encuentras algo, te agradecería que me lo traigas aquí. Esa gente merece que la recuerden.", t = "La familia Valor"},
    [96204] = {ot = "Acompaña a Lumina Vientocantor y ayúdala a escapar del castillo de Fenris.", st = "Ahora que soy libre, haré que esas repugnantes criaturas se arrepientan de haber puestos los ojos en un Formavientos.\n\nSalgamos de aquí, $c.", t = "La ira de los Formavientos"},
    [96390] = {ot = "Mata a $1oa espías Hierro Negro en Dun Morogh.", st = "Se han infiltrado espías Hierro Negro en Dun Morogh. No sé cuál es su objetivo, pero es un problema que tenemos que cortar de raíz antes de que sea demasiado tarde.\n\nVe hacia el Complejo Vetaferro al este y mata a los espías Hierro Negro que encuentres.", t = "Párteles el coco"},
    [96391] = {ot = "Entrega el mapa Hierro Negro al terravidente Farsen en Dun Morogh.", st = "<En el mapa que tienes en mano, ves una serie de complejos túneles y carreteras subterráneos que convergen en un punto bajo la ciudad de Forjaz.\n\nNo sabes a ciencia cierta qué dicen las runas, pues están escritas en un lenguaje rúnico horrendo y anguloso: el idioma de los enanos Hierro Negro. Sin embargo, supones para qué usarán estos túneles. Mientras lees el mapa, te envuelve una ráfaga de viento, que trae consigo un susurro enano apenas perceptible. El terravidente Farsen tiene que ver esto.>", t = "Mapa subterráneo"},
    [96392] = {ot = "Habla con el terravidente Farsen y pídele que te permita usar su vista lejana para observar a la amenaza Hierro Negro.", st = "Saludos, $gamigo:amiga;. Me llamo Videnterra Farsen y vengo de visita a Dun Morogh desde Pico Nidal. Durante mi viaje, no pude evitar notar que hay, eh... un pequeñito problema de enanos Hierro Negro.\n\nSi tienes un momento, puedo mostrarte a qué me refiero. Tengo la magia perfecta para encargarnos de este asunto.", t = "La vigilancia de Farsen"},
    [96393] = {ot = "Entra en el Salón de Señores Feudales debajo de Antigua Forjaz y recupera la cabeza de Durgen Martillo de Endecha.", st = "Reúne a algunos aliados y adéntrate en las cavernas debajo de Antigua Forjaz. Entra al Salón de Señores Feudales y ábrete camino hasta las bóvedas inferiores.\n\nMi conocimiento del lenguaje de los Hierro Negro es un poco limitado, pero distingo un nombre: un tal Durgen Martillo de Endecha. Es probable que sea el comandante. Córtale la cabeza y llévasela al rey Magni Barbabronce.\n\nAh, de paso, ¡dile que su viejo amigo Farsen le manda saludos!", t = "Incursión a Antigua Forjaz"},
    [96394] = {ot = "Mata $1oa aparecidos iracundos y $2oa almas atormentadas. Luego, ayuda al espíritu de Yunquemar a descansar en paz.", st = "Algo ha alterado las tumbas en el Salón de Señores Feudales, y se escuchan ruidos extraños que provienen de lo profundo de las bóvedas. Los espíritus de los muertos tienen el sueño ligero y, al parecer, lo que sea que ocurre allí los ha alarmado.\n\nDirígete allí y ve qué puedes hacer al respecto. Si alguno de los muertos está despierto... ¡ponlo a dormir otra vez!", t = "Los muertos sin descanso"},
    [96395] = {ot = "Ayuda al espíritu de Faldrim Yunquemar a descansar en paz y luego regresa con el asistente fantasmal en el Salón de Señores Feudales.", st = "El... Señor... Mi poderoso... Señor... necesita... descansar.\n\nPor favor... ayúdalo... ayúdalo... a descansar...\n\nConsumido... por... rencor... antiguo... Sin... descanso...", t = "Un rencor antiguo"},
    [96403] = {ot = "Reúne $1oa reliquias de los enanos del Salón de Señores Feudales.", st = "Oye, tú, $gaventurero:aventurera;... me vendría bien una mano.\n\nEstaba husmeando... emm, digo, \"patrullando\" las bóvedas, ¡cuando un grupo de asalto de enanos Hierro Negro surgió de las profundidades con sus máquinas topo! Desconozco para qué vinieron, pero allí abajo hay un botín invaluable... emm, digo, ¡\"reliquias culturales importantísimas\"! Te pido que recuperes todas las reliquias que veas y me las traigas.\n\nTe garantizo que catalogaré y regresaré todo lo que encuentres a su lugar de honor como corresponde.", t = "Reliquias importantes"},
    [96408] = {ot = "Investiga el campamento con vistas a la Cantera de Gol'Bolar.", st = "Anoche, uno de nuestros montaraces avistó una fogata en una colina hacia el este. Al parecer, se encuentra a una gran altura, con vistas a la Cantera de Gol'Bolar.\n\nDe seguro no sea nada, pero me gustaría que inspeccionaras el campamento. Si son aliados, no habrá problema. Si son enemigos... bueno, ya sabes qué hacer.", t = "Un visitante en Dun Morogh"},
    [96604] = {ot = "Siéntate cerca de la hoguera básica de Brakk, escribe /sentarse en la ventana de chat y espera hasta que recibas el beneficio Descanso mejorado.", st = "Saludos, $c. Veo que tienes aspecto de $gaventurero:aventurera;. ¡Qué bien! El mundo necesita más almas inquietas como nosotros, en busca de fortuna y gloria.\n\nTendrás que aprender a sobrevivir en la naturaleza para tener éxito en este oficio. No conozco tus habilidades al aire libre, pero creo que puedo enseñarte un par de cosas, si estás $gdispuesto:dispuesta; a aprenderlas.\n\nSiéntate cerca del fuego y ponte $gcómodo:cómoda;. Te lo explicaré todo.", t = "Bendita naturaleza"},
    [96605] = {ot = "Siéntate cerca de la hoguera básica de Kuga, escribe /sentarse en la ventana de chat y espera hasta que recibas el beneficio Descanso mejorado.", st = "Saludos, $c. Veo que tienes aspecto de $gaventurero:aventurera;. ¡Qué bien! El mundo necesita más almas inquietas como nosotros, en busca de fortuna y gloria.\n\nTendrás que aprender a sobrevivir en la naturaleza para tener éxito en este oficio. No conozco tus habilidades al aire libre, pero creo que puedo enseñarte un par de cosas, si estás $gdispuesto:dispuesta; a aprenderlas.\n\nSiéntate cerca del fuego y ponte $gcómodo:cómoda;. Te lo explicaré todo.", t = "Bendita naturaleza"},
    [96606] = {ot = "Siéntate cerca de la hoguera básica de Lyreena, escribe /sentarse en la ventana de chat y espera hasta que recibas el beneficio Descanso mejorado.", st = "Saludos, $c. Veo que tienes aspecto de $gaventurero:aventurera;. ¡Qué bien! El mundo necesita más almas inquietas como nosotros, en busca de fortuna y gloria.\n\nTendrás que aprender a sobrevivir en la naturaleza para tener éxito en este oficio. No conozco tus habilidades al aire libre, pero creo que puedo enseñarte un par de cosas, si estás $gdispuesto:dispuesta; a aprenderlas.\n\nSiéntate cerca del fuego y ponte $gcómodo:cómoda;. Te lo explicaré todo.", t = "Bendita naturaleza"},
    [96607] = {ot = "Siéntate cerca de la hoguera básica de Eleanor, escribe /sentarse en la ventana de chat y espera hasta que recibas el beneficio Descanso mejorado.", st = "Saludos, $c. Veo que tienes aspecto de $gaventurero:aventurera;. ¡Qué bien! El mundo necesita más almas inquietas como nosotros, en busca de fortuna y gloria.\n\nTendrás que aprender a sobrevivir en la naturaleza para tener éxito en este oficio. No conozco tus habilidades al aire libre, pero creo que puedo enseñarte un par de cosas, si estás $gdispuesto:dispuesta; a aprenderlas.\n\nSiéntate cerca del fuego y ponte $gcómodo:cómoda;. Te lo explicaré todo.", t = "Bendita naturaleza"},
    [96608] = {ot = "Siéntate cerca de la hoguera básica de Eric, escribe /sentarse en la ventana de chat y espera hasta que recibas el beneficio Descanso mejorado.", st = "Saludos, $c. Veo que tienes aspecto de $gaventurero:aventurera;. ¡Qué bien! El mundo necesita más almas inquietas como nosotros, en busca de fortuna y gloria.\n\nTendrás que aprender a sobrevivir en la naturaleza para tener éxito en este oficio. No conozco tus habilidades al aire libre, pero creo que puedo enseñarte un par de cosas, si estás $gdispuesto:dispuesta; a aprenderlas.\n\nSiéntate cerca del fuego y ponte $gcómodo:cómoda;. Te lo explicaré todo.", t = "Bendita naturaleza"},
    [96626] = {ot = "Habla con Tomas en Villadorada para aprender a cocinar.", st = "¿Así que quieres saber más sobre acampar, eh? ¡Qué bien, $c! El primer paso que debe dar cualquier aventurero es convertirse en cocinero y aprender a hacer una hoguera.\n\nCocinar no solo consiste en preparar algo sabroso, sino que también es la base del campamento.", t = "Campamento básico: Cocina"},
    [96627] = {ot = "Habla con Sam Sarsparilla en las cercanías de Villadorada.", st = "$n, has demostrado tu capacidad como $gprotector:protectora;. Es por esa razón que ahora te confío una misión extraordinaria.\n\nMe han llegado noticias de una aventurero en el camino hacia Villadorada. Ve y averigua qué está haciendo.", t = "El aventurero"},
    [96628] = {ot = "Entrega el conjunto de suministros a Eric Martillo Radiante cerca de Kharanos.", st = "Espera, $n. Tengo otro pedido antes de que te metas en ese túnel.\n\nMis montaraces me informaron de un aventurero que apareció a las afueras de Kharanos. ¿Podrías llevarle estos suministros?", t = "El aventurero"},
    [96629] = {ot = "Habla con Gremlock Pilsnor en Kharanos para aprender a cocinar.", st = "¿Así que quieres saber más sobre acampar, eh? ¡Qué bien, $c! El primer paso que debe dar cualquier aventurero es convertirse en cocinero y aprender a hacer una hoguera.\n\nCocinar no solo consiste en preparar algo sabroso, sino que también es la base del campamento.", t = "Campamento básico: Cocina"},
    [96630] = {ot = "Llévale el diario a Lyreena Hoja Umbría cerca de Dolanaar.", st = "<El diario parece bastante sencillo; detalla la vida y las aventuras de alguien que nunca escuchaste nombrar.\n\nHay muchas entradas que mencionan campamentos. Se ve bastante... divertido.>", t = "El aventurero"},
    [96634] = {ot = "Habla con Zarrin en Dolanaar para aprender a cocinar.", st = "Así que quieres saber más sobre acampar, ¿eh? ¡Qué bien, $c! El primer paso que debe dar cualquier aventurero es convertirse en cocinero y aprender a hacer una hoguera.\n\nCocinar no solo consiste en preparar algo sabroso, sino que también es la base del campamento.", t = "Campamento básico: Cocina"},
    [96638] = {ot = "Habla con Raan Bravovento cerca de la Aldea Shen'dar.", st = "Cada vez son más los aventureros como tú que buscan gloria y fortuna fuera de la seguridad de Arboleda Thendal. Uno de ellos montó un campamento a las afueras de la Aldea Shen'dar, junto al camino que sale de Arboleda Thendal hacia el suroeste.\n\nBúscalo y averigua qué puedes aprender de él que te pueda servir de ayuda en tus propios viajes.", t = "El aventurero"},
    [96646] = {ot = "Habla con Zerril Brisaleve en la Aldea Shen'dar para aprender a cocinar.", st = "Así que quieres saber más sobre acampar, ¿eh? ¡Qué bien, $c! El primer paso que debe dar cualquier aventurero es convertirse en cocinero y aprender a hacer una hoguera.\n\nCocinar no solo consiste en preparar algo sabroso, sino que también es la base del campamento.", t = "Campamento básico: Cocina"},
    [96652] = {ot = "Devuélvele el diario a Brakk cerca de Cerrotajo.", st = "<El diario parece bastante sencillo; detalla la vida y las aventuras de alguien que nunca escuchaste nombrar.\n\nHay muchas entradas que mencionan campamentos. Se ve bastante... divertido.>", t = "El aventurero"},
    [96655] = {ot = "Habla con el cocinero Torka en Cerrotajo para aprender a cocinar.", st = "¿Así que quieres saber más sobre acampar, eh? ¡Qué bien, $c! El primer paso que debe dar cualquier aventurero es convertirse en cocinero y aprender a hacer una hoguera.\n\nCocinar no solo consiste en preparar algo sabroso, sino que también es la base del campamento.", t = "Campamento básico: Cocina"},
    [96656] = {ot = "Habla con Eleanor Shackleton cerca de Rémol.", st = "$n, has demostrado tu lealtad en las batallas contra la Cruzada Escarlata. Es por esa razón que ahora te confío una misión extraordinaria.\n\nMe han llegado noticias de una aventurera en el camino hacia Rémol. Ve y averigua qué está haciendo.", t = "El aventurero"},
    [96658] = {ot = "Habla con William Pickman en Rémol para aprender a cocinar.", st = "¿Así que quieres saber más sobre acampar, eh? ¡Qué bien, $c! El primer paso que debe dar cualquier aventurero es convertirse en cocinero y aprender a hacer una hoguera.\n\nCocinar no solo consiste en preparar algo sabroso, sino que también es la base del campamento.", t = "Campamento básico: Cocina"},
    [96659] = {ot = "Entrega el conjunto de suministros a Kuga Cascosalvaje cerca del Poblado Pezuña de Sangre.", st = "Espera, $n. Tengo otro encargo para ti antes de que te vayas.\n\nHay una aventurera conocida como Kuga Cascosalvaje que ha montado un campamento justo en las afueras del Poblado Pezuña de Sangre. Me ha ayudado mucho en el pasado, y creo que ahora tengo la oportunidad de devolverle el favor. ¿Podrías entregarle estos suministros?", t = "El aventurero"},
    [96661] = {ot = "Habla con Pyall Trancosilencio en Poblado Pezuña de Sangre para aprender a cocinar.", st = "¿Así que quieres saber más sobre acampar, eh? ¡Qué bien, $c! El primer paso que debe dar cualquier aventurero es convertirse en cocinero y aprender a hacer una hoguera.\n\nCocinar no solo consiste en preparar algo sabroso, sino que también es la base del campamento.", t = "Campamento básico: Cocina"},
    [96779] = {ot = "Encuentra a Lord Tomas dentro del Castillo de Durnholde en las Laderas de Trabalomas y asesínalo. Cuando termines, regresa con Myrokos Silenforma.", st = "A veces, $r, un solo corte en el lugar indicado es suficiente para eliminar a tus enemigos. Lo mismo suele pasar con las organizaciones.\n\nNuestros agentes han identificado a un objetivo importante entre los rangos de la Hermandad: un hombre llamado Lord Tomas.\n\nTiene un rol importante en el funcionamiento del Castillo de Durnholde en las Laderas de Trabalomas. Si deseas ayudar a Ravenholdt, dirígete al Castillo y elimínalo. Mientras más rápido y silencioso, mejor.", t = "Sabotaje a la Hermandad"},
    [96821] = {ot = "Mata 6 trepadores sombrarrisco y 6 rondadores sombrarrisco en el sur de Durotar, y luego informa a Gar'thok en Cerrotajo.", st = "Cada vez vemo' meno' viajero' de Cerrotajo. Los escórpido' nunca fueron muy amable', pero ahora vengo escuchando que hay araña' haciendo sus nido' a lo largo del camino.\n\nSi tus viaje' te llevan al norte, mata algunas araña' a tu paso. Luego, cuéntale' a la gente de Cerrotajo que el camino es un poco más seguro.", t = "A pie"},
    [96822] = {ot = "Recoge el hacha de batalla de asaltante, arco de asaltante y escudo de asaltante de las afueras del Fuerte de Tiragarde y devuélveselos a Turroc en Cerrotajo.", st = "Perdimos a muchos guerreros valientes de la Horda cuando asaltamos el Fuerte de Tiragarde. Ahora que los humanos reforzaron las ruinas, no podemos recoger sus restos para honrar adecuadamente sus muertes.\n\nVe a las ruinas que rodean el fuerte y busca las armas que dejaron atrás nuestros hermanos caídos. Las exhibiremos en un sitio de honor.", t = "Por el honor"},
    [96825] = {ot = "El cocinero Torka, en Cerrotajo, quiere que recojas 8 frutos pera espinosa de las Tierras Crines de Acero, al oeste de la ciudad.", st = "Nuestros cazadores y pescadores traen bastante comida sabrosa para nuestras tropas, pero rara vez consiguen algo dulce.\n\nHe visto un cactus que produce una suculenta fruta espinosa, pero solo crece en las colinas del oeste, donde unos desgraciados jabaespines han hecho campamento. Ábrete paso entre ellos y trae algunos de esos frutos. Y ten cuidado: ¡las frutas pinchan tanto como los jabaespines!", t = "Esta fruta sabe cómo defenderse"},
    [96873] = {ot = "Pa'zula, en el Poblado Sen'jin, quiere que recojas 3 residuos luminosos. Se pueden obtener residuos luminosos al desencantar los colgantes embrujados que arrojan los trols de las Islas del Eco.", st = "Los trols al este de aquí han perdido su voluntad ante Zalazane, el médico brujo. Utiliza diversos hechizos siniestros para controlar la mente de sus prisioneros, pero una de sus artimañas favoritas es obligarlos a usar colgantes imbuidos con hechizos de vinculación maligna.\n\nExtrae esa magia de los colgantes para practicar tus habilidades de encantamiento, y tráeme sus restos. Pero recuerda: si quieres seguir disfrutando de tu libertad, ¡evita ponerte uno de esos colgantes!", t = "Un dolor de cuello"},
    [96874] = {ot = "Ug'thok, en Orgrimmar, quiere que consigas 5 espinas deterioradas de las bestias del Monte del Trueno y 5 piedras de pulir férreas.", st = "¿Has visto las bestias gigantescas del Monte del Trueno? No dejo de pensar que las espinas que tienen en la espalda serían perfectas para fabricar la cabeza de una poderosa hacha. Saru se rio a carcajadas cuando se lo mencioné... ¡¡pero él no entiende nada!!\n\n¡Como parte de tus lecciones de herrería, me podrás ayudar! Tráeme algunas de esas espinas y unas piedras de pulir para afilarlas.", t = "Un hacha espinosa"},
    [96875] = {ot = "Kamari, en Orgrimmar, quiere que consigas 5 pellejos de lagarto duros de las bestias de Monte del Trueno y 2 pellejos ligeros curtidos.", st = "Orgrimmar siempre está en expansión, $c. Y cuando los peones necesitan cueros para cubrir los muros y techos de nuestras construcciones nuevas, ¡acuden a mí!\n\nLos cueros de los lagartos de Monte del Trueno suelen ser muy gruesos para hacer armaduras, pero son un excelente material de construcción. Tráeme algunos de esos, y también unos cueros ligeros curtidos. ¡Veamos cuán hábil eres con el cuero!", t = "Las bestias de Monte del Trueno"},
    [96876] = {ot = "Devuélvele la mochila a Ukor en el sur de Durotar.", st = "La mochila tiene el nombre de \"Ukor\" bordado toscamente en una de las tiras.", t = "La mochila perdida de Ukor"},
    [96877] = {ot = "Lleva la pezuña de Halikor a Orgrimmar.", st = "La enorme pezuña es una prueba de tu triunfo sobre el poderoso lagarto.", t = "Pezuña de Halikor"},
    [96895] = {ot = "Encuentra al miembro del Alba Argenta cerca de la entrada de Entrañas.", st = "Quizá no lo sepas, pero dos emisarios del Alba Argenta acaban de pasar por aquí. No tengo problema con El Alba Argenta, pero no me gusta que merodeen por Tirisfal sin supervisión. Ambos eran Renegados... pero eso no me hace sentir más tranquilo.\n\n Uno de ellos acaba de pasar por aquí y se dirigía al sureste. En esa dirección, hay un grupo de cultistas de la Plaga que merodea en las afueras de la ciudad. Si esos dos se enteraron de su presencia, sin duda eso habrá captado su interés.", t = "El emisario Argenta"},
    [96896] = {ot = "Escucha la conversación entre Danitha Morr y Leonid Barthalomew el Venerado.", st = "Con Danitha peleamos en la defensa de Entrañas contra el ataque proveniente de Naxxramas. Aquel día, perdimos a muchos buenos amigos, incluido el héroe que le da nombre a este fuerte: Garek Bandarion.\n\nPuede que haya sido el primer paladín Renegado en redescubrir cómo utilizar la Luz como paladín. Me alegra ver que su legado y su potencial perduran aquí con Danitha y su séquito.\n\nOjalá el resto de los Renegados pensaran igual...", t = "Una causa justa"},
    [96897] = {ot = "Mata a $1oa neófitos oscuros y $2oa déspotas oscuros en Claros de Tirisfal.", st = "La Plaga es una peste en nuestras tierras, y sus sirvientes vivos son lo peor de todo. La gente de Tirisfal ya tiene suficiente con los muertos descerebrados y la Cruzada Escarlata. Si deseas hacer el bien, ayúdame a encargarme de esta escoria.", t = "El Culto de los Malditos"},
    [96898] = {ot = "Recoge $1oa trozos de cristal necrótico en Claros de Tirisfal.", st = "No fue hace mucho que la ciudadela de Naxxramas atacó esta ciudad con la intención de borrar a los Renegados del mapa. Aquel día, los Renegados y el Alba Argenta perdieron mucho para proteger el futuro de los Renegados.\n\nDurante la batalla, el gran cristal de enfoque necrótico que colgaba debajo de Naxxramas se rompió y sus fragmentos se dispersaron por esta zona. Sospecho que los cultistas vinieron por eso. Ayúdame a recuperar los fragmentos antes que la Plaga lo haga.", t = "Los restos de la guerra"},
    [96899] = {ot = "Habla con Leonid Barthalomew en el Fuerte de Bandarion en Claros de Tirisfal.", st = "Hoy has sido de gran ayuda para el Alba Argenta, y te doy las gracias. No sé si conoces el Fuerte de Bandarion, pero mi comandante y yo nos dirigíamos allí para conocer a los paladines que lo hicieron su hogar. Eso era antes de que supiéramos del Culto de los Malditos.\n\nSi quieres saber más sobre el Alba Argenta y nuestra misión, habla con mi comandante en el Fuerte de Bandarion, al noroeste de aquí. Me quedaré aquí para limpiar el resto de este desastre.", t = "Fuerte de Bandarion"},
    [96984] = {ot = "Recoge motas arcanas en la Ciudad de Dalaran y dáselas a Magus Wordeen Vacuamirada, en Molino Tarren.", st = "Puede que no quieras lo mejor para nosotros, pero no voy a rechazar un poco de ayuda. Si Dalaran cae, se llevará todo con ella, incluida Entrañas.\n\n¿Así que tu benefactor quiere entrar? Bien. impregnaré tu llave con magia para que puedas atravesar mis resguardos y entrar a la ciudad. Una vez que estés dentro, ven a verme en la Ciudadela Violeta donde comenzó todo esto. Con todo lo que está ocurriendo, el Kirin Tor estará muy ocupado para detenerte.\n\nBusca lo que quieras, pero pase lo que pase, nuestra principal prioridad es evitar una catástrofe.", t = "El corazón de la perturbación"},
    [96986] = {ot = "Asesina a Atrexis, el Caballero de la tumba en la Ciudad de Dalaran para Melisara, en el Molino Tarren.", st = "Dentro de los Bajos Fondos de la ciudad de los magos, al norte, hay un traidor de nuestra especie. Un nigromante con un talento perturbador. Está reuniendo un ejército de no-muertos justo bajo las narices del Kirin Tor.\n\nNo me importa el destino de la ciudad de los magos, $n, pero este caballero de la tumba está pisoteando todo lo que defendemos los Renegados. Acábalo. Demuéstrale que nadie puede burlar a la Dama Oscura.", t = "El Caballero de la tumba"},
    [96987] = {ot = "Recoge la Fundación de Dalaran de la Ciudad de Dalaran y dáselo a Rexxie Cuprigarra cerca de la entrada de la cloaca.", st = "Vaya, si es $Gun emprendedor:una emprendedora; que piensa como yo. ¿Colarte en Dalaran en tiempos difíciles? Pff.\n\n¡Eres de los míos, $r!\n\nMientras nuestros amigos magos están aquí ocupados, tal vez podríamos encontrar algún tesoro \"perdido\". Tienen bibliotecas enteras dedicadas a magias arcanas y sofisticadas. Si pudieras traerme uno de sus tomos secretos, podría venderlo a un buen precio. Compartiré las ganancias contigo.\n\nEy, ey, no me mires así. No estás aquí precisamente de excursión. ¿Te sumas o qué?", t = "Educación oportunista"},
    [96988] = {ot = "Recoge $1oa núcleos de avizor rajados en la Ciudad de Dalaran y dáselos al Doctor Martin Felben en Entrañas.", st = "Con la ciudad de Dalaran bajo el asedio de sus propios ensamblajes, esta es la oportunidad perfecta para, digamos, tomar prestadas algunas muestras.\n\nImagina un ejército de abominaciones impulsadas por magia arcana. A la Dama Oscura no le quedará otra opción más que reconocer mi habilidad para la alquimia. Quizá hasta me nombre presidente de la Sociedad Real de Boticarios.\n\nVe a la ciudad y encuentra el núcleo de los ensamblajes. Es poco probable que te los den por voluntad propia, así que haz lo que tengas que hacer.", t = "Origen del poder"},
    [97003] = {ot = "Llévale la cabeza de Chol'aruk a Gur'ak en los Baldíos.", st = "Tú, $c. Necesito tu ayuda. Corren rumores de una bestia que tiene su guarida en lo profundo de una cueva en la Colina Espinosa, al noreste de aquí. Los Crines de Acero la llaman Chol'aruk o \"el Insaciable\". Se dice que es cinco veces más grande que un jabaespín normal, con una sed de sangre que nada puede saciar.\n\nLa mayoría no cree esas historias. Pero yo sí, porque ya enfrenté a algo así.\n\nBusca su guarida y mata a Chol'aruk. Tráeme su cabeza. Pero te lo advierto: prepárate bien y no vayas sin compañía.\n\nSangre y trueno, $c.", t = "Chol'aruk, el Insaciable"},
    [97220] = {ot = "Lleva el cargamento de entrada a la puerta del almacén que se encuentra en la tienda de Queso de Trias del Distrito de Mercaderes.", st = "Cada día de esta semana hemos estado escasos de personal portuario.\n\n¿Te interesaría ayudarnos a aligerar el cronograma de entregas?\n\nLleva este paquete a la puerta del almacén de la Torre de Entrada. La encontrarás dentro de la tienda de Queso de Trias, en el segundo piso. A la encargada, Elaine, las entregas le resultarán familiares. En la Torre de Entrada, los cargamentos suelen entregarse de forma más discreta para facilitar las sorpresas ceremoniales de los oficiales de la guardia.", t = "Favor de Philmor"},
    [97222] = {ot = "Lleva el cargamento de entrada por las escaleras de la tienda de Trias y déjalo delante de la puerta.", st = "Sí, solo es subir unas escaleras, pero si es un favor tan pequeño, ¡no debería ser ningún problema para ti hacer la entrega tú $gmismo:misma;! \n\nEl queso de Trias no forma parte de la Torre de Entrada ni de su inventario de existencias, pero nuestros edificios comparten un piso.\n\nDeja la caja afuera de la puerta de su almacén; el guardia enviará a alguien para que la recoja como de costumbre. Verán que llegó el paquete y lo llevarán adentro al regresar a su puesto.", t = "Víveres de entrada"},
    [97223] = {ot = "Llévale huevos de la Matriarca Garrasangre a Xar'Ti en el Poblado Sen'jin.", st = "Todo' eh'tos raptore' que ve' aquí lo' he entrenado yo mismo. Vienen de todo' lo' rincone' de Kalimdor, pero lo' mejore' vienen de lo' raptore' Garrasangre de la' ih'la' frente a nueh'tra costa.\n\nUno de eso' raptore', la Matriarca Garrasangre, e' particularmente salvaje y ha matado a mucho' de nueh'tro' aldeano'. Se ha vuelto muy peligrosa como para dejarla suelta en nueh'tra' frontera'. Si logra' vencerla, vuelve y trae su' huevo', así podemo' criar a su prole como aliado' y no como enemigo'.", t = "Matriarca Garrasangre"},
    [97225] = {ot = "Recoge $1oa ídolos loa olvidados en las Islas del Eco. Llévaselos al Maestro Gadrin en el Poblado Sen'jin.", st = "Cuando huimo' de la' ih'la' donde ahora viven Zalazane y lo' de su clase, dejamo' atrá' mucho' ídolo' preciado' que no' ayudan a comulgar con lo' eh'píritu' que adoramo': nueh'tro' loa. Son muy importante' para nuestra tribu.\n\nLo' seguidore' de Zalazane no mueh'tran ninguna reverencia hacia nueh'tro loa y han eh'parcido eh'to' ídolo' a lo largo y lo ancho de la ih'la má' grande.\n\nEh'te comportamiento no pasará desapercibido a meno' que recolectemo' eh'to' ídolo', y ofender a un loa e' un problema serio.\n\nVe, encuentra todo' lo' ídolo' loa que pueda' y tráelo' de vuelta.", t = "Ídolos loa olvidados"},
    [97234] = {ot = "Lleva el material de lectura envuelto a la biblioteca de Ventormenta.", st = "¿Viniste para debatir sobre los significados más profundos de nuestras leyendas célebres?\n\n¿No? Bueno, cuando hayas terminado de revisar el lugar, ¿puedes llevar esto a la biblioteca? Estamos cambiando algunas de nuestras obras menos populares por otras más modernas. Tengo una lista de tomos que seguramente el bibliotecario podrá conseguir como parte del acuerdo que tenemos.\n\nLas bebidas del club corren por nuestra cuenta si nos echas una mano.", t = "Zona de lectura"},
    [97236] = {ot = "Entrega el colmillo de Githyiss a algún interesado en el estudio de los arácnidos en Aldrassil.", st = "Un ejemplar fresco de una bestia de semejante tamaño es un hallazgo inusual. Tal vez este colmillo le interese a alguien en Aldrassil que esté versado en el estudio de los arácnidos.", t = "Colmillo de Githyiss"},
    [97237] = {ot = "Encuentra todos los materiales de lectura que se encuentran dispersos en la biblioteca. Luego, regresa con Roy Lewells en el Parque de Ventormenta.", st = "He revisado nuestro inventario y todas las selecciones que el señor Lewells ha incluido en la lista se encuentran disponibles.\n\nSin embargo, tendrás que encargarte de sacarlos de los estantes. Parte de nuestra labor bibliotecaria es la vigilancia, y por ello, retomaré los registros de supervisión.\n\nLlevarte el material en nombre de Roy no te hará responsable de su devolución, ya que esta nota demuestra que trabajas para el club de lectura como transportista. La responsabilidad será del local.\n\nBuen día, $n.", t = "Directo del estante"},
    [97242] = {ot = "Recoge algunos esquejes de eneas y césped lanza que crecen alrededor de las corrientes de agua en el Valle del Honor, y regresa a Kor'geld en Alquimia y Pociones de Yelmak.", st = "Yelmak no quiere que su aprendiz rompa nada más… bueno, nada más de lo que ya ha roto.\n\nMe dijo que el aprendiz de mezclador es demasiado orgulloso para pedir ayuda cuando la necesita. Yelmak quiere que pruebe una receta casera especial.\n\nRecoge una mezcla de eneas y césped lanza de las orillas del Valle del Honor. No puedo ausentarme porque si abandono el taller, Whuut se dará cuenta de que lo estamos complaciendo.", t = "La mezcla de Yelmak"},
    [97243] = {ot = "Lleva la antorcha de la Llama Latente a Olariaan Fuegoveloz en el Santuario de las Llamas, en los Bajíos Ventobaya.", st = "Aunque estemos en el reino del Muro Celeste, esto sigue siendo el plano elemental. Los espíritus de los cuatro elementos nos hablan, si nos dignamos a escuchar. Uno de nosotros, los Formavientos, tiene una afinidad especial con el elemento del fuego. Un shen'dorei llamado Olariaan Fuegoveloz.\n\nLlévale esto al Santuario de las Llamas, en los Bajíos Ventobaya. La hallarás escondido junto a la orilla de la isla, al oeste de Valanaar.", t = "El llamado del fuego"},
    [97244] = {ot = "Mata al sacerdocielo Faladiel en los Bajíos Ventobaya y recoge su corazón.", st = "Hay un sacerdocielo Al'Aketh llamado Faladiel. Alguna vez fue un invocador de la llama y un Formavientos inquebrantable. Como tantos otros Al'Aketh, hipotecó su lealtad por poder, y ahora tiene las manos manchadas con la sangre de sus antiguos hermanos y hermanas.\n\nEncontrarás al sacerdocielo Faladiel en la granja al noreste, pasando Valanaar, justo al sur del Santuario de Akir. Mata al traidor. Tráeme su corazón. Es una tarea atroz, pero es necesaria para el ritual que debemos llevar a cabo.", t = "El llamado del fuego"},
    [97245] = {ot = "Encuentra el hogar de Kuramaa en las Tierras Altas de Shen'dar y derrota al espíritu en combate. Llévale la máscara de Kuramaa a Olariaan Fuegoveloz en los Bajíos Ventobaya, cuando hayas salido $Gvictorioso:victoriosa;.", st = "Los residentes de las Tierras Altas de Shen'dar hablan de un antiguo elemental del bosque llamado Kuramaa. Dicen que vive dentro de un tocón retorcido en la cima de una colina, cerca de las tierras altas del pilón de anclaje.\n\nVe a las tierras altas y busca ese tocón. Golpea la corteza con el puño y Kuramaa aparecerá. Véncelo en combate y tráeme su máscara de madera.\n\nPero ten cuidado: esta entidad será sumamente resistente a buena parte de tu magia. Solo el toque de llamas podrá derribar al espíritu.", t = "El llamado del fuego"},
    [97246] = {ot = "Visita la fosa de lava de Borstan y dile que Thatog quiere que entregues el almuerzo de Migi personalmente.", st = "Mi hijo, Migi, se pasa el día jugando con sus amigos. Le digo que busque su almuerzo en la posada de Borstan, aunque sé que rara vez obedece, porque vuelve con un hambre feroz. ¡Estos muchachos piensan que sus juegos son más sagrados que sus propios cuerpos!\n\nHaz una parada en la fosa de lava de Borstan y dile que debes entregar el almuerzo de Migi. Con toda seguridad hallarás al muchacho tras el Fuerte Grommash, rodeado de sus amigos.\n\nMis deberes me retienen aquí durante el día, y no puedo vigilar cada comida de mi hijo.", t = "Comida apetecible"},
    [97249] = {ot = "Llévale el almuerzo a Migi detrás del Fuerte Grommash.", st = "Ahora que sé que sus padres se preocupan por lo poco que come, se me ha ocurrido una idea.\n\nSus padres me pidieron que no repita el mismo almuerzo, para que Migi conozca más sabores. Sin embargo, cuando el ahumador rebosa y servimos sándwiches de vientre de jabalí glaseado, el muchacho siempre viene a almorzar. Ahora hemos empezado a espolvorear los restos crujientes por encima, un toque que podemos ofrecer a diario.\n\nLlévale esto. Tal vez empiece a llegar temprano y a traer a sus amigos.", t = "Comida favorita"},
    [97250] = {ot = "Mata a los soldados de la Alianza que están usurpando Los Baldíos en la frontera de Marjal Revolcafango. Luego, regresa con Bruto Logmar en el Campamento Taurajo.", st = "$gViajero:Viajera;, ¿tienes planes de ir a Marjal Revolcafango? He oído por ahí que algunos soldados humanos han mostrado su postura en la frontera y están derribando los monumentos que nuestros abrecaminos tauren dejaron atrás.\n\nSe rumorea que se incendió una de las tabernas más populares del pueblo y, como es de esperar de la Alianza, ¡enseguida culparon a la Horda! Es imposible saber si hay algo de verdad en sus declaraciones, pero su incursión a NUESTRA tierra no prevalecerá.\n\n¡Primero, maten y, luego, investiguen!", t = "Falsa acusación, justa redención"},
    [97253] = {ot = "Recoge $1oa puñados de piezas complicadas en la zona superior del campamento pirata ubicado al sur de Trinquete. Luego, regresa con Desdio el Desdichado en Trinquete.", st = "Oye, ¿tienes un minuto?\n\nParece que ninguno de los que envié a lidiar con el problema de los piratas ha vuelto con vida. Luego de cinco o seis intentos pensé: \"¿Y si envío una máquina?\" Resulta que se pueden usar cimitarras como destornilladores para salir del paso y, antes de que pudiera redirigirla a casa, ¡ya estaba destruida y las piezas estaban desparramadas por su campamento!\n\nNecesito esas piezas de vuelta. Y, como esta será una simple misión de recuperación, apuesto que tus probabilidades de sobrevivir son MUCHO mayores que las de los demás. ¿Qué te parece?", t = "Partes y piezas"},
    [97257] = {ot = "Espera a que Olariaan comience el ritual en el blandón de ofrenda y sigue sus instrucciones.\n\nDebes llevar la llama eterna a Valanaar antes de que se acabe el tiempo.", st = "Ahora llevaremos a cabo el ritual. \n\nColocaré los materiales en el altar e invocaré a los espíritus de la llama. Si aceptan la ofrenda, aparecerán y encenderán la llama eterna. En ese momento, alza tu antorcha y atrapa la llama.\n\nLleva la antorcha encendida a Valanaar y deposítala en el brasero de las llamas eternas. Debes darte prisa: las llamas de las Tierras de Fuego se extinguen con rapidez aquí en el Muro Celeste.", t = "El llamado del fuego"},
    [97275] = {ot = "Entrega la poción de Yelmak a Whuut.", st = "Whuut es un prodigio indiscutible. Sin embargo, carece todavía de la experiencia, la sabiduría y las horas de práctica con la vara para aprender a respetar los rituales de la alquimia.\n\nEstá agotando los más raros y exóticos componentes que tenemos, sin detenerse a practicar ni perfeccionar sus habilidades básicas.\n\nEntrégale esta poción, creada con un método tónico veloz. Comprenderá sus errores cuando aprenda que los remedios locales y la delicadeza en el trato son la verdadera maestría.", t = "La prisa de Whuut"},
    [97277] = {ot = "Encuentra a Grund y el campamento de Gozwin en las colinas del noroeste. Recupera el registro de mecánico de Gozwin y mata al merodeador leopardo de las nieves.", st = "¡Oye! Estaba de espaldas, preparando el jabalí asado, cuando escuché a mi compañero Gozwin pidiendo auxilio a los gritos.\n\nCuando me di vuelta, lo único que vi fueron colmillos brutales y una mancha borrosa. ¡Semejantes garras! Un leopardo de las nieves se estaba llevando a rastras a su presa gnómica. Agarré mi escopeta y le disparé al aire, por encima de la bestia. Lo soltó y salió disparada.\n\nPor suerte, al viejo Goz no le hizo más que unos buenos arañazos.\n\nRegresa al campamento en las colinas del noroeste y recupera el registro de mecánico de Gozwin. ¡Y si ves a ese leopardo de las nieves, mátalo!", t = "Grund y Gozwin"},
    [97279] = {ot = "Reúne $1oa armas de entrenamiento abandonadas y devuélveselas a Kzan Trallafusta en El Cubil.", st = "Con esta ola de nuevos reclutas como tú, ha sido difícil aprovisionarnos de suficientes armas. Kzan, nuestro forjador de armas, se está quedando sin armas de entrenamiento, y me gustaría ver qué habilidades tienes para darme una idea de a qué me enfrento. Por suerte para ti, podemos matar dos pájaros de un tiro.\n\nMientras andas por ahí puliendo tus habilidades, recupera seis armas de entrenamiento abandonadas que nuestros reclutas fallidos dejaron en el suelo. Cuando lo hagas, llévaselas a nuestro forjador de armas, Kzan, que está detrás de mí en El Cubil.", t = "Armas extraviadas"},
    [97281] = {ot = "Llévale el orbe opaco tormentoso a Rezlak cerca del Barranco Árido.", st = "<Delante de ti hay un orbe extraño con una superficie opaca. Al levantarlo, sientes una pequeña corriente eléctrica que parece vibrar desde adentro. Luego de echarle un vistazo más cercano, observas que una niebla oscura gira en el interior y, por momentos, aparece una chispa eléctrica.\n\nEs evidente que la arpía lo usaba con un objetivo. ¿Tal vez Rezlak esté interesado en este objeto?>", t = "Una tormenta inminente"},
    [97282] = {ot = "Llévale $1oa órganos de truenagarto cargados a Rezlak cerca del Barranco Árido.", st = "\"Rezlack, cuando una oportunidad toca tu puerta, procura estar listo para aprovecharla\". Esa es una de las perlas que Gazlowe me enseñó y es exactamente cómo trato de vivir.\n\nEste orbe no parece estar dañado, puede que solo le falte energía. ¡Pero tengo una idea para recargarlo al máximo!\n\nHay un montón de truenagartos en una garganta al oeste de aquí. Tienen órganos con una fuerte carga eléctrica que pueden encajar perfectamente en este orbe.\n\n¡Ve, cosecha algunos y tráelos!", t = "Potencial tormentoso"},
    [97287] = {ot = "Habla con la archimaga Celindra en la Ciudad de Dalaran.", st = "Has hecho un buen trabajo al infiltrarte en la ciudad de magos, pero creo que es hora de que seamos más... negociadores.\n\nPor más que me duela admitirlo, no existe otro lugar en Azeroth con semejante cantidad de conocimiento sobre lo arcano. Mi brillante trabajo es insignificante si lo comparas con la sabiduría antigua que el Kirin Tor acumuló durante este tiempo. Creo que ya es hora de que nos den acceso a esta orden exclusiva, ¿no es cierto?\n\nToma la mota que conseguiste, no tengo dudas de que darán lo que sea para recuperarla. Lo que sea.", t = "Negociaciones arteras"},
    [97288] = {ot = "Entrega la cabeza abominable al maestro boticario Faranell en Entrañas.", st = "<Cuando la criatura cae, su cabeza también lo hace. Parece que se la hubieran cosido varias veces, y que la unión se debilita con cada nuevo intento.\n\nAlguien de Entrañas debe saber más sobre esta abominación única.>", t = "Tormento eterno"},
    [97289] = {ot = "Lleva la cabeza del Barón al cuerpo de Othmar en Entrañas.", st = "Fabricamos cabezas de abominaciones todo el tiempo, pero esta es especial. Perteneció a un gran mariscal de la Alianza, uno particularmente desagradable. Creo que su nombre era Othmar. La Dama Oscura tuvo el placer de despacharlo ella misma.\n\nAh... los secretos que contaría si pudiera hablar. ¡Y claro que puede! Si la cosemos a un huésped adecuado.\n\nAdelante, colócala al lado del cuerpo disponible en la habitación contigua, pero todavía no la cosas.", t = "Tormento eterno"},
    [97290] = {ot = "Informa tus hallazgos al maestro boticario Faranell en Entrañas.", st = "Tú... abominación...\n\n¿Por qué... debería ayudarte...?\n\nDesaparece...", t = "Tormento eterno"},
    [97291] = {ot = "Visita a Tawny Grisette en el Barrio del Comercio para conseguir un capacete tóxico, a las instructoras de herboristería para reunir hierba ampolla y a los vendedores de venenos del Barrio de los Pícaros para obtener esencia de agonía. Lleva todo al maestro boticario Faranell de Entrañas.", st = "Con la cabeza unida, ahora solo necesitamos ligarla a la voluntad de la Dama Oscura. Eso no debería ser un problema. La bestia apenas tiene cerebro, luego de todas las palizas que recibió.\n\nSolo hay que motivarla.\n\nConsígueme un capacete tóxico de la señorita Grisette en el Barrio del Comercio. Ah, y un poco de hierba ampolla de nuestras instructoras de herboristería, las Alliestar. Están en deuda conmigo, así que llévate un poco sin culpa. Y por último, un poco de esencia de agonía. Cualquier vendedor de venenos debería tener.\n\n¡Es hora de hacer una poción!", t = "Tormento eterno"},
    [97292] = {ot = "Inyecta el suero siseante en el sistema que está encima del cuerpo de Othmar para el maestro boticario Faranell.", st = "He creado un amoroso suero que nuestro nuevo invitado seguro encontrará bastante... estimulante.\n\nLlévatelo e introdúcelo en los engranajes que gotean arriba suyo. Veamos si así podemos demostrarle que le conviene servirnos con lealtad.\n\nProcura que no se te caiga, no puedo perder más asistentes.", t = "Tormento eterno"},
    [97326] = {ot = "Llévale $1oa rocas lisas a Thra detrás del Fuerte Grommash.", st = "¡Oye! Tienes tiempo de ayudarnos. Puedo verlo en la forma en que sonreíste mientras nos mirabas jugar.\n\nEste lugar detrás del Fuerte Grommash es perfecto porque está despejado y podemos colocar nuestras figuras. Lo malo es que no tenemos suficientes rocas para usarlas como sillas o mesas.\n\nEres grande y fuerte… ¿crees que podrías traer algunas rocas medianas que sean lo bastante lisas para sentarnos si necesitamos descansar?", t = "De rocas a descansos"},
    [97485] = {ot = "Cómprale un fardo de hierbas a Nida, la herborista; un fardo de ramitas de cedro a Nata, la proveedora de encantamiento; un hilo de tendón a Mahu, el proveedor de peletería; y sílex y yesca ceremoniales a Naal, el proveedor de cocina.\n\nCombina estos objetos y esparce el incienso por el Alto de los Cazadores.", st = "Las bendiciones de An'she sean contigo, colega.\n\nLos tauren tenemos la tradición de esparcir incienso al viento, y esperaba que pudieras honrarla.\n\nPara preparar el incienso, tendrás que comprar hierbas a Nida, cedro a Nata, hilo de tendón a Mahu en el nivel medio, y sílex y yesca ceremoniales a Naal en el nivel alto. Cuando reúnas todos los objetos, combínalos y espárcelos desde el risco orientado al sur del Alto de los Cazadores.\n\nEncontrarás un felpudo e incienso en el sitio ceremonial.", t = "Tradiciones de la Cima"},
    [97538] = {ot = "Tah Pezuña Invernal en Cima del Trueno quiere $1oa vainas de hierba oscura del Lago Mirkfallon.", st = "Saludos, $gamigo:amiga;. ¿Podría pedirte un favor? Se me acaba de terminar el pigmento rojo para mis pinturas y busco a alguien de pezuñas jóvenes para que emprenda el largo viaje a Sierra Espolón por mí.\n\nEn medio del paso entre montañas, yace el Lago Mirkfallon, un enorme cuerpo de agua circular en donde crece una planta única de ese sitio. Las vainas de esta planta, llamada hierba oscura, se vuelven de un rojo brillante al secarse. Tráeme las vainas de esta planta y te recompensaré por tus esfuerzos.", t = "Pigmentos para pinturas"},
    [97558] = {ot = "Lleva $1oa membranas de alas de murciumbrío, $2oa pellejos de can oscuro y $3oa pieles de múrloc Anca Vil a Shelene Rhobart.", st = "Un misterio sobre los no-muertos del que nadie habla es lo que ocurre cuando sufrimos heridas. ¿Cómo sana la piel de un no-muerto?\n\nBueno, no sana.\n\nLa nuestra es una vida maldita, $n. Estamos condenados a arrebatar a los vivos lo necesario para sostener nuestra propia existencia.\n\nCuando sufrimos una herida, debemos reemplazar nuestra la piel con el pellejo de animales. Los distintos espesores se adaptan mejor a diferentes partes del cuerpo, y por eso, la variedad es esencial.\n\nTráeme las membranas de las alas de un murciumbrío, el pellejo de un can oscuro y la piel de un múrloc Anca Vil.", t = "Pellejos para los Renegados"},
    [97891] = {ot = "Llévale la poción inestable al doctor Martin Felben en El Apothecarium antes de que se agote el tiempo.", st = "¡Tú! ¡Rápido, necesito que le lleves esta poción al doctor Martin Felben, al otro lado de este canal de baba en El Apothecarium!\n\nTiene una vida útil muy limitada, y yo no puedo ir por mi cuenta, pues mis rodillas se descalabran si intento correr.\n\nOtro de los espectaculares efectos de ser un no-muerto, al parecer.\n\n¡Dejemos de perder el tiempo! Ten, ¡toma esto y vete!\n\n<Alessandro te hace gestos para que te vayas.>", t = "Presto portador de la poción"},
    [97899] = {ot = "Habla con Whuut en Orgrimmar para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que elegiste preparar brebajes y pociones como alquimista. Seguro que te resultará útil en tus viajes.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un pozo de maná para tu campamento. Construye uno y todos los sanadores y taumaturgos vendrán corriendo por un sorbo refrescante.", t = "Campamento básico: Alquimia"},
    [97900] = {ot = "Habla con Dwukk en Cerrotajo para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que te hiciste $Gherrero:herrera;. Es una gran elección si quieres asegurarte de que tus hojas nunca pierdan el filo.\n\nCreo que conozco a alguien que puede echarte una mano y enseñarte a fabricar una rueda de afilar. Instala una en tu campamento y todos los guerreros y pícaros de la zona harán cola para afilar sus armas.", t = "Campamento básico: Herrería"},
    [97901] = {ot = "Habla con Jhag en Orgrimmar para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Los encantadores mejoran todo y siempre son bien recibidos en cualquier campamento en las tierras salvajes.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un laúd encantado para tu campamento. Es muy importante distraerse en los ratos de descanso, y este toque de magia te ayudará a estar $Glisto:lista; para afrontar toda clase de desafíos cuando retomes el viejo y polvoriento sendero.", t = "Campamento básico: Encantamiento"},
    [97902] = {ot = "Habla con Mukdrak en Cerrotajo para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Los ingenieros como tú pueden armar toda clase de bártulos, bots y bombas, para divertirse y ganarse unas monedas.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un robot de componentes para tu campamento. Este útil autómata puede mantenerte bien $Gabastecido:abastecida; para que a ti y a tus aliados nunca les falten los materiales necesarios para potenciar los hechizos.", t = "Campamento básico: Ingeniería"},
    [97903] = {ot = "Habla con Rawrk en Cerrotajo para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que te metiste en primeros auxilios. Una vocación honorable... y muy práctica para $Gun:una; $c.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un equipo de primeros auxilios para tu campamento. Las heridas son parte de la vida de los aventureros, y brindar esa sanación tan necesaria en tu campamento podría incluso salvar vidas.", t = "Campamento básico: Primeros auxilios"},
    [97904] = {ot = "Habla con Lau'Tiki cerca del Poblado Sen'jin para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Quizás no lo creas, pero tu habilidad como $Gpescador:pescadora; puede resultar muy útil en el campamento.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un cuenco de pescado para tu campamento. Puedes usar este accesorio para alegrarles un poco el día a ti y a tus compañeros de aventura. Un aventurero feliz es un aventurero fuerte, y seguro que tus habilidades de combate lo reflejarán.", t = "Campamento básico: Pesca"},
    [97905] = {ot = "Habla con Jandi en Orgrimmar para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Por lo que veo, ya le agarraste la mano a la herboristería. Recoger flores no es solo para perder el tiempo, ¿sabes? Puede ser útil... y rentable.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una vela de incienso para tu campamento. El buen ánimo es fundamental para mantener a los sanadores y taumaturgos en la pelea, y una vela de incienso puede dar un impulso que los hechiceros sin duda valorarán.", t = "Campamento básico: Herboristería"},
    [97906] = {ot = "Habla con Karolek en Orgrimmar para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Te convertiste en $Gpeletero:peletera;. Bien por ti, $c. Creo que conozco a alguien que puede enseñarte a fabricar una tienda de campamento para mantenerte $Gfresco:fresca; los días de calor y $Gseco:seca; los días de lluvia.\n\nCon una buena tienda sobre tu cabeza, te asegurarás de descansar todo lo necesario para mantenerte alerta durante tus viajes.", t = "Campamento básico: Peletería"},
    [97907] = {ot = "Habla con Krunn en Cerrotajo para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "La minería no será lo más glamuroso, pero es un trabajo honesto y una profesión excelente que puedes explorar.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una magnetita para tu campamento. Crea una y todo el que quiera blandir una espada correrá a reunirse junto a tu hoguera para empaparse de ese \"impulso\" y mejorar su destreza en combate.", t = "Campamento básico: Minería"},
    [97908] = {ot = "Habla con Thuwd en Orgrimmar para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Saber desollar con destreza las pieles y los pellejos de las bestias caídas es una de las habilidades más valiosas que un aventurero puede tener.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una silla de campamento. A veces es importante quitarse un peso de encima, y puedes usar algunos de los cueros que recogiste para hacer una silla cómoda donde sentarte. Un poco de relajación puede ayudarte a estar en óptimas condiciones y a atacar donde más duele la próxima vez que te metas en una pelea.", t = "Campamento básico: Desuello"},
    [97914] = {ot = "Llévale la carta de Thundris a Baros Alexston en Ventormenta.\n\nThundris mencionó un barco en Auberdine que te puede llevar hasta allí.", st = "Auberdine es un lugar humilde, $c. No mencionan su nombre en los bosques de Darnassus. La mayoría solo se refiere a lo que El Cataclismo nos arrebató: las prósperas ciudades de Ameth'Aran, Bashal'Aran y... Lathar'Lazal.\n\nSin embargo, Auberdine permanece a su sombra.\n\nMe gustaría que se reconociera nuestro trabajo aquí. Un nuevo barco nos conecta con el reino de Ventormenta al traer vida y provisiones a nuestras costas. Te ruego que te unas a su próximo viaje y le entregues esta carta a un humano llamado Baros Alexston.\n\nDifundamos nuestro hogar.", t = "Expandiendo tus horizontes"},
    [97915] = {ot = "Habla con el alquimista Mallory en el Bosque de Elwynn cerca de Ventormenta para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que elegiste preparar brebajes y pociones como alquimista. Seguro que te resultará útil en tus viajes.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un pozo de maná para tu campamento. Construye uno y todos los sanadores y taumaturgos vendrán corriendo por un sorbo refrescante.", t = "Campamento básico: Alquimia"},
    [97916] = {ot = "Habla con el herrero Argus en Villadorada para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que te hiciste $Gherrero:herrera;. Es una gran elección si quieres asegurarte de que tus hojas nunca pierdan el filo.\n\nCreo que conozco a alguien que puede echarte una mano y enseñarte a fabricar una rueda de afilar. Instala una en tu campamento y todos los guerreros y pícaros de la zona harán cola para afilar sus armas.", t = "Campamento básico: Herrería"},
    [97917] = {ot = "Habla con Betty Quin en Ventormenta para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Los encantadores mejoran todo y siempre son bien recibidos en cualquier campamento en las tierras salvajes.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un laúd encantado para tu campamento. Es muy importante distraerse en los ratos de descanso, y este toque de magia te ayudará a estar $Glisto:lista; para afrontar toda clase de desafíos cuando retomes el viejo y polvoriento sendero.", t = "Campamento básico: Encantamiento"},
    [97918] = {ot = "Habla con Duendy Ruedadentada en Ventormenta para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Los ingenieros como tú pueden armar toda clase de bártulos, bots y bombas, para divertirse y ganarse unas monedas.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un robot de componentes para tu campamento. Este útil autómata puede mantenerte bien $Gabastecido:abastecida; para que a ti y a tus aliados nunca les falten los materiales necesarios para potenciar los hechizos.", t = "Campamento básico: Ingeniería"},
    [97919] = {ot = "Habla con Michelle Belle en Villadorada para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que te metiste en primeros auxilios. Una vocación honorable... y muy práctica para $Gun:una; $c.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un equipo de primeros auxilios para tu campamento. Las heridas son parte de la vida de los aventureros, y brindar esa sanación tan necesaria en tu campamento podría incluso salvar vidas.", t = "Campamento básico: Primeros auxilios"},
    [97920] = {ot = "Habla con Lee Moreno cerca de Villadorada para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Quizás no lo creas, pero tu habilidad como $Gpescador:pescadora; puede resultar muy útil en el campamento.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un cuenco de pescado para tu campamento. Puedes usar este accesorio para alegrarles un poco el día a ti y a tus compañeros de aventura. Un aventurero feliz es un aventurero fuerte, y seguro que tus habilidades de combate lo reflejarán.", t = "Campamento básico: Pesca"},
    [97921] = {ot = "Habla con la herborista Pomarrosa en el Bosque de Elwynn para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Por lo que veo, ya le agarraste la mano a la herboristería. Recoger flores no es solo para perder el tiempo, ¿sabes? Puede ser útil... y rentable.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una vela de incienso para tu campamento. El buen ánimo es fundamental para mantener a los sanadores y taumaturgos en la pelea, y una vela de incienso puede dar un impulso que los hechiceros sin duda valorarán.", t = "Campamento básico: Herboristería"},
    [97922] = {ot = "Habla con Adele Fielder en Villadorada para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Te convertiste en $Gpeletero:peletera;. Bien por ti, $c. Creo que conozco a alguien que puede enseñarte a fabricar una tienda de campamento para mantenerte $Gfresco:fresca; los días de calor y $Gseco:seca; los días de lluvia.\n\nCon una buena tienda sobre tu cabeza, te asegurarás de descansar todo lo necesario para mantenerte alerta durante tus viajes.", t = "Campamento básico: Peletería"},
    [97923] = {ot = "Habla con Gelman Petramano en Ventormenta para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "La minería no será lo más glamuroso, pero es un trabajo honesto y una profesión excelente que puedes explorar.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una magnetita para tu campamento. Crea una y todo el que quiera blandir una espada correrá a reunirse junto a tu hoguera para empaparse de ese \"impulso\" y mejorar su destreza en combate.", t = "Campamento básico: Minería"},
    [97924] = {ot = "Habla con Helene Desollapelambres en Villadorada para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Saber desollar con destreza las pieles y los pellejos de las bestias caídas es una de las habilidades más valiosas que un aventurero puede tener.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una silla de campamento. A veces es importante quitarse un peso de encima, y puedes usar algunos de los cueros que recogiste para hacer una silla cómoda donde sentarte. Un poco de relajación puede ayudarte a estar en óptimas condiciones y a atacar donde más duele la próxima vez que te metas en una pelea.", t = "Campamento básico: Desuello"},
    [97925] = {ot = "Habla con Eldrin en el Aserradero de la Vega del Este del Bosque de Elwynn para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "La sastrería es un oficio sorprendentemente potente en el que vale la pena invertir tiempo, y seguro que te va a servir.\n\nConozco a alguien que puede enseñarte a fabricar un estandarte de facción para tu campamento, siempre y cuando tengas la destreza para ello. La inspiración y la moral son la clave para el éxito en cualquier batalla, y un estandarte inspirador te puede ayudar bastante para mantenerte con energía.", t = "Campamento básico: Sastrería"},
