    [97949] = {ot = "Habla con Radnaal Tejecrín en el camino a de Dolanaar a Darnassus para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Saber desollar con destreza las pieles y los pellejos de las bestias caídas es una de las habilidades más valiosas que un aventurero puede tener.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una silla de campamento. A veces es importante quitarse un peso de encima, y puedes usar algunos de los cueros que recogiste para hacer una silla cómoda donde sentarte. Un poco de relajación puede ayudarte a estar en óptimas condiciones y a atacar donde más duele la próxima vez que te metas en una pelea.", t = "Campamento básico: desuello"},
    [97950] = {ot = "Habla con Trianna en Darnassus para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "La sastrería es un oficio sorprendentemente potente en el que vale la pena invertir tiempo, y seguro que te va a servir.\n\nConozco a alguien que puede enseñarte a fabricar un estandarte de facción para tu campamento, siempre y cuando tengas la destreza para ello. La inspiración y la moral son la clave para el éxito en cualquier batalla, y un estandarte inspirador te puede ayudar bastante para mantenerte con energía.", t = "Campamento básico: sastrería"},
    [97951] = {ot = "Habla con Carolai Anise en Rémol para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que elegiste preparar brebajes y pociones como alquimista. Seguro que te resultará útil en tus viajes.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un pozo de maná para tu campamento. Construye uno y todos los sanadores y taumaturgos vendrán corriendo por un sorbo refrescante.", t = "Campamento básico: Alquimia"},
    [97952] = {ot = "Habla con Basil Frye en Entrañas para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que te hiciste $Gherrero:herrera;. Es una gran elección si quieres asegurarte de que tus hojas nunca pierdan el filo.\n\nCreo que conozco a alguien que puede echarte una mano y enseñarte a fabricar una rueda de afilar. Instala una en tu campamento y todos los guerreros y pícaros de la zona harán cola para afilar sus armas.", t = "Campamento básico: Herrería"},
    [97953] = {ot = "Habla con Vance Bajopenumbra en Rémol para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Los encantadores mejoran todo y siempre son bien recibidos en cualquier campamento en las tierras salvajes.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un laúd encantado para tu campamento. Es muy importante distraerse en los ratos de descanso, y este toque de magia te ayudará a estar $Glisto:lista; para afrontar toda clase de desafíos cuando retomes el viejo y polvoriento sendero.", t = "Campamento básico: Encantamiento"},
    [97954] = {ot = "Habla con Graham Van Talen en Entrañas para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Los ingenieros como tú pueden armar toda clase de bártulos, bots y bombas, para divertirse y ganarse unas monedas.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un robot de componentes para tu campamento. Este útil autómata puede mantenerte bien $Gabastecido:abastecida; para que a ti y a tus aliados nunca les falten los materiales necesarios para potenciar los hechizos.", t = "Campamento básico: Ingeniería"},
    [97955] = {ot = "Habla con la enfermera Neela en Rémol para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Así que te metiste en primeros auxilios. Una vocación honorable... y muy práctica para $Gun:una; $c.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un equipo de primeros auxilios para tu campamento. Las heridas son parte de la vida de los aventureros, y brindar esa sanación tan necesaria en tu campamento podría incluso salvar vidas.", t = "Campamento básico: Primeros auxilios"},
    [97956] = {ot = "Habla con la Clyde Kellen en Rémol para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Quizás no lo creas, pero tu habilidad como $Gpescador:pescadora; puede resultar muy útil en el campamento.\n\nCreo que conozco a alguien que puede enseñarte a fabricar un cuenco de pescado para tu campamento. Puedes usar este accesorio para alegrarles un poco el día a ti y a tus compañeros de aventura. Un aventurero feliz es un aventurero fuerte, y seguro que tus habilidades de combate lo reflejarán.", t = "Campamento básico: Pesca"},
    [97957] = {ot = "Habla con Faruza en Rémol para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Por lo que veo, ya le agarraste la mano a la herboristería. Recoger flores no es solo para perder el tiempo, ¿sabes? Puede ser útil... y rentable.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una vela de incienso para tu campamento. El buen ánimo es fundamental para mantener a los sanadores y taumaturgos en la pelea, y una vela de incienso puede dar un impulso que los hechiceros sin duda valorarán.", t = "Campamento básico: herboristería"},
    [97958] = {ot = "Habla con Shelene Rhobart en el camino a Entrañas desde Rémol para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Te convertiste en $Gpeletero:peletera;. Bien por ti, $c. Creo que conozco a alguien que puede enseñarte a fabricar una tienda de campamento para mantenerte $Gfresco:fresca; los días de calor y $Gseco:seca; los días de lluvia.\n\nCon una buena tienda sobre tu cabeza, te asegurarás de descansar todo lo necesario para mantenerte alerta durante tus viajes.", t = "Campamento básico: peletería"},
    [97959] = {ot = "Habla con Brom Killian en Entrañas para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "La minería no será lo más glamuroso, pero es un trabajo honesto y una profesión excelente que puedes explorar.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una magnetita para tu campamento. Crea una y todo el que quiera blandir una espada correrá a reunirse junto a tu hoguera para empaparse de ese \"impulso\" y mejorar su destreza en combate.", t = "Campamento básico: minería"},
    [97960] = {ot = "Habla con Rand Rhobart en el camino a Entrañas desde Rémol para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad.", st = "Saber desollar con destreza las pieles y los pellejos de las bestias caídas es una de las habilidades más valiosas que un aventurero puede tener.\n\nCreo que conozco a alguien que puede enseñarte a fabricar una silla de campamento. A veces es importante quitarse un peso de encima, y puedes usar algunos de los cueros que recogiste para hacer una silla cómoda donde sentarte. Un poco de relajación puede ayudarte a estar en óptimas condiciones y a atacar donde más duele la próxima vez que te metas en una pelea.", t = "Campamento básico: desuello"},
